veh = mkVehicle()
it = newItem(GPS_T, { uses = 0.5, useDelta = 0.006 })
ch:getInventory():AddItem(it)
noSideEffect("沒有螺絲刀", NO_TOOL, ch, veh, "nav", true, it)

