    "快速重試先續期 GPS")
checkEq(sentClient[2] and sentClient[2].args.active, true, "快速重試的 Auto heartbeat 維持 active=true")

-- OnPlayerUpdate 的兩道早退：不是本機玩家、以及這個 slot 沒有 session
driveReset(dveh)
it = newPlayer({ num = 0, remote = true })
fire("OnPlayerUpdate", it)
checkEq(drive.calls.getForwardVector, 0, "遠端玩家擋在最前面（就算他的 slot 有 session）")
checkEq(drive.pool.alloc, 0, "遠端玩家不取向量池")

players[1] = newPlayer({ num = 1, username = "autodrive1" })
fire("OnPlayerUpdate", players[1])
checkEq(drive.calls.getForwardVector, 0, "別的 slot 在自駕不會誤動這個 slot 的車")
checkEq(drive.pool.alloc, 0, "沒有自己的 session：不取向量池")
players[1] = nil

-- =====================================================================
-- 情境十八：限速剖面分幀建構
-- =====================================================================
scenario("限速剖面分幀建構：每幀 128 點、建構期不控速也不施力")

-- 300 points now use geometry/coast/brake/merge/accel = 1497 bounded operations;
-- 128 per frame means the first 11 frames build and the 12th starts control.
resetStats()
MDAD.Drive.stop(0, nil)
checkEq(#sentClient, 1, "clearSession 對 stop／抵達／失效共用 best-effort off")
checkEq(sentClient[1] and sentClient[1].command, MDAD.CMD_USAGE,
    "停止使用同一 Usage command")
checkEq(sentClient[1] and sentClient[1].args.active, false, "停止 heartbeat 宣告 active=false")
drive.nav.route = newRoute(300, 0, 0, 4, 0)
dveh._x, dveh._y, dveh._speed, dveh._steering = 0, 0, 20, 0
setHeading(dveh, 0.3)
dveh._regulator = true   -- 玩家上車前自己設的定速：建構期必須是關著的
driveReset(dveh)
checkTrue(MDAD.Drive.start(dp), "長路線也能啟動（建表攤到後續幀）")
checkEq(drive.calls.regulatorOff, 1, "長路線一樣在啟動當下就把舊定速關掉")
checkEq(dveh._regulator, false, "建表還沒開始，舊定速就已經失效")

driveReset(dveh)
for _ = 1, 11 do driveTick(dp, dveh) end
checkEq(dveh._imp.total, 0, "剖面還沒建好：不施力")
checkEq(drive.calls.setRegulator, 0, "剖面還沒建好：不動 regulator")
checkEq(dveh._regulator, false, "整段建構期舊定速都不生效（start 關掉、建構幀不再碰）")
checkEq(drive.calls.setRegulatorSpeed, 0, "剖面還沒建好：不設定速")
checkEq(drive.calls.forceBrake, 0, "剖面還沒建好：不煞車")
checkEq(drive.calls.getForwardVector, 0, "剖面還沒建好：連前向向量都不讀")
checkEq(drive.pool.alloc, 0, "建構幀不取向量池（stepBuild 沒完成就 return）")
checkEq(drive.nav.targetCalls, 0, "250ms 節流內不重查導航目標")
checkTrue(MDAD.Drive.isActive(0), "建構期間 session 還活著")

driveTick(dp, dveh)
checkEq(dveh._imp.total, 1, "第 12 幀剖面建好，開始控車")
checkEq(drive.calls.setRegulatorSpeed, 1, "第 12 幀開始控速")
checkEq(drive.calls.regulatorOn, 1, "沒超速：regulator 開著供油")
checkEq(drive.calls.getForwardVector, 1, "控制幀只讀一次前向向量")
checkEq(drive.pool.alloc, 2, "控制幀取兩顆池向量（forward／relPos 共用一顆＋impulse 一顆）")
checkEq(drive.pool.release, 2, "取幾顆就還幾顆")
checkEq(drive.pool.live, 0, "幀末池水位歸零")
checkEq(drive.bad.impulse + drive.bad.pair + drive.bad.live, 0, "8 幀都沒有違反每幀不變式")

-- =====================================================================
-- 情境十九：跟線 60 幀的每幀不變式
-- =====================================================================
scenario("跟線 60 幀：每幀最多一次 addImpulse、向量池成對歸零、定速不超過沙盒上限")

-- 沿用情境十八建好的 session。20 km/h ＝ 5.556 m/s，dt ＝ 1.6/48 秒，
-- 所以每幀前進 0.1852 公尺——讓進度真的推進（投影窗口、前視點都會跟著動）。
driveReset(dveh)
for _ = 1, 60 do
    dveh._x = dveh._x + 0.1852
    driveTick(dp, dveh)
end
checkEq(drive.frames, 60, "跑了 60 幀")
checkEq(dveh._imp.max, 1, "單幀施力次數的最高水位是 1（addImpulse 是單槽）")
checkEq(drive.bad.impulse, 0,
    "沒有任何一幀施力超過一次（首次違規幀 " .. tostring(drive.bad.atImpulse) .. "）")
checkEq(drive.bad.pair, 0,
    "每幀 alloc 與 release 成對（首次違規幀 " .. tostring(drive.bad.atPair) .. "）")
checkEq(drive.bad.live, 0,
    "每幀結束時池水位歸零（首次違規幀 " .. tostring(drive.bad.atLive) .. "）")
checkEq(drive.pool.live, 0, "60 幀跑完沒有任何向量沒還")
checkEq(drive.pool.alloc, 120, "60 個控制幀各取兩顆向量")
checkEq(drive.pool.alloc, drive.pool.release, "取還總數相同")
checkEq(drive.pool.bad, 0, "沒有 release 過不在手上的向量")
checkEq(dveh._imp.useAfterRelease, 0, "施力用的向量都還在手上（沒有 use-after-release）")
checkEq(dveh._imp.total, 60, "60 幀各施力一次")
checkEq(drive.calls.getForwardVector, 60, "每幀只讀一次前向向量")
checkEq(drive.calls.setRegulatorSpeed, 60, "60 幀各設一次定速")
checkEq(drive.calls.badRegSpeed, 0, "定速不曾是負數或非數字")
checkEq(drive.calls.fractionalRegSpeed, 0,
    "寫進原版 regulator 的速度是整數（儀表不露出長小數）")
checkTrue(drive.calls.maxRegSpeed <= 40,
    "定速不超過沙盒 AutoDriveMaxSpeed=40（實得 " .. tostring(drive.calls.maxRegSpeed) .. "）")
checkEq(drive.calls.forceBrake, 0, "正常跟線不搶煞車")
checkEq(drive.nav.targetCalls, 0, "60 幀都在 250ms 節流窗內：完全沒重查導航目標")

-- Phase F: arbitrary actual-target gap never force-brakes. Normal 20/45/90°
-- curves coast through the envelope; only an actual hard curvature breach brakes.
do
    local savedSpeed = dveh._speed
    local function productionCurveRoute(degrees)
        local pts, radius = {}, 20
        for i = 0, 10 do
            pts[#pts + 1] = i * 4
            pts[#pts + 1] = 0
        end
        local steps = math.ceil(degrees / 5)
        for i = 1, steps do
            local a = -math.pi * 0.5 + math.rad(degrees) * i / steps
            pts[#pts + 1] = 40 + radius * math.cos(a)
            pts[#pts + 1] = 20 + radius * math.sin(a)
        end
        local endA = math.rad(degrees)
        local ex, ey = pts[#pts - 1], pts[#pts]
        for i = 1, 25 do
            pts[#pts + 1] = ex + math.cos(endA) * i * 4
            pts[#pts + 1] = ey + math.sin(endA) * i * 4
        end
        return { pts = pts }
    end

    for _, degrees in ipairs({ 20, 45, 90 }) do
        MDAD.Drive.stop(0, nil)
        drive.nav.route = productionCurveRoute(degrees)
        dveh._x, dveh._y, dveh._speed, dveh._stopped = 39, 0, 10, false
        setHeading(dveh, 0)
        checkTrue(MDAD.Drive.start(dp),
            degrees .. "° production curve profile starts")
        for _ = 1, 16 do driveTick(dp, dveh) end
        driveReset(dveh)
        driveTick(dp, dveh)
        checkEq(drive.calls.forceBrake, 0,
            degrees .. "° production curve coasts without forceBrake")
        checkEq(dveh._imp.total, 1,
            degrees .. "° production curve retains steering authority")
    end

    MDAD.Drive.stop(0, nil)
    drive.nav.route = newRoute(300, 0, 0, 4, 0)
    dveh._x, dveh._y, dveh._speed = 0, 0, 20
    setHeading(dveh, 0)
    checkTrue(MDAD.Drive.start(dp), "restore straight production profile")
    for _ = 1, 20 do driveTick(dp, dveh) end
    driveReset(dveh)

    local realControl = MDADFollower.control
    MDADFollower.control = function(_, state)
        state.curveValid = true
        state.curveHardActive = false
        state.curveKappa, state.curveCapKmh = 0, 29.6
        return 1, 29.6, 100, false, 0, 0, 0
    end
    dveh._speed = 100
    driveReset(dveh)
    driveTick(dp, dveh)
    checkEq(drive.calls.forceBrake, 0,
        "straight actual-target gap alone never force-brakes")
    checkEq(drive.calls.setRegulatorSpeed, 1,
        "straight overspeed keeps regulator/coast command")

    MDADFollower.control = function(_, state)
        state.curveValid = true
        state.curveHardActive = false
        state.curveKappa, state.curveCapKmh = 0.2, 5
        return 1, 5, 100, false, 0, 0, 0
    end
    dveh._speed = 20
    driveReset(dveh)
    driveTick(dp, dveh)
    checkEq(drive.calls.forceBrake, 0,
        "future horizon curvature only coasts; straight current segment never hard-brakes")
    checkEq(dveh._imp.total, 1,
        "future curve cap preserves current straight steering authority")

    MDADFollower.control = function(_, state)
        state.curveValid = true
        state.curveHardActive = true
        state.curveKappa, state.curveCapKmh = 0.2, 5
        return 1, 5, 100, false, 0, 0, 0
    end
    dveh._speed = 20
    driveReset(dveh)
    driveTick(dp, dveh)
    -- 1002a：彎道 ×1.5 災難超速 10 km/h 以上改不鎖輪（Drive.hardBrake）：中線減速外力與轉向同一個 impulse，
    -- 不叫引擎一秒鎖輪（正式服 0.16.0 curve 鎖輪片段：一鎖就 sk 0.02–0.05、整台停住才轉）。
    -- 違規證明：hardBrake 拿掉 why＝curve 分支＝這三條紅。
    checkEq(drive.calls.forceBrake, 0,
        "current SEG_ARC gross breach at 20 km/h brakes without locking the wheels")
    checkEq(dveh._imp.total, 1,
        "non-lock curve brake: one impulse carries the center-line decel and the steering")
    do
        local sbk = MDAD.Drive.debugSession(0)
        checkTrue(sbk.lastHardBrakeReason == "curve"
                and math.abs((sbk.visAssistDecel or 0) - MDAD.Drive.debugTune().TOW_BRAKE_DECEL) < 1e-9,
            "hbr names the curve breach and the non-lock decel is TOW_BRAKE_DECEL (hbr="
            .. tostring(sbk.lastHardBrakeReason) .. " vad=" .. tostring(sbk.visAssistDecel) .. ")")
    end
    -- 低於 TOW_NOLOCK_KMH 照舊一秒鎖輪停住（8 km/h 對彎帽 5）
    dveh._speed = 8
    driveReset(dveh)
    driveTick(dp, dveh)
    checkEq(drive.calls.forceBrake, 1,
        "current SEG_ARC breach below 10 km/h still locks (forceBrake)")
    checkEq(dveh._imp.total, 0,
        "locked-wheel curve brake never emits a competing steering impulse")

    MDADFollower.control = function(_, state)
        state.curveValid = true
        state.curveHardActive = false
        state.curveKappa, state.curveCapKmh = 0, 0
        return 0, 0, 100, false, 0, 0, 0
    end
    dveh._speed = 0
    driveReset(dveh)
    driveTick(dp, dveh)
    checkTrue(MDAD.Drive.isActive(0), "legal target=0 remains an active non-fault command")
    checkEq(drive.calls.forceBrake, 0, "legal target=0 does not masquerade as invalid")

    -- 0907b：弧段（curveHardActive）位置環 ×CROSS_TRACK_ARC_GAIN——同一個橫向偏差、同速，
    -- 弧段上的偏航力矩＝直路的 2 倍（session-058 R≈12 彎切內 1.7m 撞路燈；Follower 弧段
    -- 改追切線後位置只剩 cross-track 管）。fake control：steer 0、err 0、latSigned 3 → 只有
    -- cross-track 在出力；curveCapKmh 40 > 20 km/h 不觸發任何煞車。違規證明：拿掉 elseif 即紅。
    local function fakeLat(hard)
        MDADFollower.control = function(_, state)
            state.curveValid = true
            state.curveHardActive = hard
            state.curveKappa, state.curveCapKmh = hard and 0.05 or 0, 40
            return 0, 40, 100, false, 0, 9, 3
        end
        dveh._speed = 20
        driveReset(dveh)
        driveTick(dp, dveh)
        checkEq(drive.calls.forceBrake, 0, "cross-track 契約幀不煞車（hard=" .. tostring(hard) .. "）")
        checkEq(dveh._imp.total, 1, "cross-track 契約幀施力一次（hard=" .. tostring(hard) .. "）")
        return dveh._imp.torqueY
    end
    local tqLine = fakeLat(false)
    local tqArc = fakeLat(true)
    checkTrue(tqLine ~= 0 and tqArc * tqLine > 0, "直路／弧段 cross-track 力矩同向且非零")
    checkNear(tqArc / tqLine, MDADDynamics.CROSS_TRACK_ARC_GAIN, 0.05,
        "弧段 cross-track 力矩＝直路 ×CROSS_TRACK_ARC_GAIN（實得 "
        .. string.format("%.3f", tqArc / tqLine) .. "）")
    -- 2026-09-27：爬行承諾（dodging＋dodgeCrawl）位置環 ×CROSS_TRACK_DODGE_GAIN，但 Follower 的
    -- fallback 出彎窗（kinkExitS 在）退回一般增益——pre-a 時 lineLat 仍在來向臂，×3 會與 Follower
    -- 的出彎轉向抵消（正式服 SemiBox 片段）。違規證明：拿掉 kinkExitS 條件即紅。
    do
        local stk = MDAD.Drive.debugSession(0)
        local function crawlTq(kink)
            stk.dodging, stk.dodgeCrawl = true, true
            stk.fstate.kinkExitS = kink
            local tq = fakeLat(false)
            stk.dodging, stk.dodgeCrawl, stk.fstate.kinkExitS = false, false, nil
            return tq
        end
        local tqCrawl = crawlTq(nil)
        local tqKink = crawlTq(50)
        checkTrue(math.abs(tqCrawl) > math.abs(tqLine) * 1.5,
            "爬行承諾位置環加倍（" .. string.format("%.3f", tqCrawl / tqLine) .. "）")
        checkNear(tqKink / tqLine, 1, 0.05,
            "fallback 出彎窗（kinkExitS）退回一般增益（實得 " .. string.format("%.3f", tqKink / tqLine) .. "）")
        -- 1002p：回線精確線（returnActive、非 hold）位置環同弧段 ×CROSS_TRACK_ARC_GAIN（正式服 0.17.0 三段回線過衝 1.1m
        -- 兩秒收不回）。違規證明：拿掉 returnActive 條件＝紅。
        local keepA, keepH, keepT = stk.returnActive, stk.returnHold, stk.returnTarget
        stk.returnActive, stk.returnHold, stk.returnTarget = true, false, 0
        local tqRet = fakeLat(false)
        stk.returnActive, stk.returnHold, stk.returnTarget = keepA, keepH, keepT
        checkNear(tqRet / tqLine, MDADDynamics.CROSS_TRACK_ARC_GAIN, 0.05,
            "回線精確線 cross-track 力矩＝直路 ×CROSS_TRACK_ARC_GAIN（實得 " .. string.format("%.3f", tqRet / tqLine) .. "）")
    end

    MDADFollower.control = function(_, state)
        state.curveValid = true
        state.curveHardActive = false
        state.curveKappa, state.curveCapKmh = 0, 40
        return 1, 0 / 0, 100, false, 0, 0, 0
    end
    dveh._speed = 20
    driveReset(dveh)
    driveTick(dp, dveh)
    checkEq(drive.calls.forceBrake, 1,
        "non-finite cruise aggregation best-effort brakes in the same frame")
    checkEq(dveh._imp.total, 0, "invalid command emits no steering impulse")
    checkFalse(MDAD.Drive.isActive(0), "invalid command visibly terminates the session")
    checkEq(haloKey(), DKEY.UNSUPPORTED, "invalid command reports unsupported dynamics")
    MDADFollower.control = realControl
    dveh._speed = savedSpeed
end

-- 沙盒上下界、非法／缺席回預設：HUD必須顯示此session真正採用的上限。
-- 此時Sensor尚未載入，行駛命令另受未驗證帽限制，不能拿命令低速假證沙盒夾限。
-- 切MAX，避免玩家原有的70檔蓋住120案例；不改玩家已選檔位的預設政策。
dp._modData.MDADGear = 4
for _, ok in ipairs({ { 1, 5 }, { 999, 120 }, { "fast", 120 }, { nil, 120 } }) do
    MDAD.Drive.stop(0, nil)
    setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = true, AutoDriveMaxSpeed = ok[1], RightLaneBias = 0 })
    dveh._x, dveh._y, dveh._speed = 0, 0, 0
    setHeading(dveh, 0.0) -- 完全對準：高速誤差護欄（>70 按誤差折返）不介入
    drive.nav.route = newRoute(300, 0, 0, 4, 0)
    checkTrue(MDAD.Drive.start(dp), "AutoDriveMaxSpeed=" .. tostring(ok[1]) .. " 可以啟動")
    local _, _, shownCap = MDAD.Drive.hudState(0)
    checkEq(shownCap, ok[2], "HUD反映沙盒上限與缺席預設，不被未驗證行駛帽遮蔽")
    driveReset(dveh)
    for _ = 1, 72 do driveTick(dp, dveh) end
    local expectedCap = ok[2]
    if expectedCap > 15 then expectedCap = 15 end
    checkTrue(drive.calls.maxRegSpeed > 0 and drive.calls.maxRegSpeed <= expectedCap,
        "sensor missing keeps real command within gate cap " .. expectedCap
        .. "（實得 " .. tostring(drive.calls.maxRegSpeed) .. "）")
    checkEq(drive.calls.badRegSpeed, 0, "夾限後的定速仍是非負數字")
end
setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = true, AutoDriveMaxSpeed = 40, RightLaneBias = 0 })
dp._modData.MDADGear = nil -- 還原預設檔位（後續情境量 40 上限，運動 70 不干擾）

-- 檔位 cap 必須在 sensor 塊之外（codex M5.5 對抗審 BLOCKING）：此區
-- MDADSensor 尚未 require（在情境二十八才載入），session.sensor＝false＝
-- 感知缺席退 M3 純跟線——檔位照樣要生效。
dp._modData.MDADGear = 1 -- 輕鬆 30 < 沙盒 40
MDAD.Drive.stop(0, nil)
dveh._x, dveh._y, dveh._speed = 0, 0, 0
setHeading(dveh, 0.05)
drive.nav.route = newRoute(300, 0, 0, 4, 0)
checkTrue(MDAD.Drive.start(dp), "感知缺席＋輕鬆檔情境啟動")
driveReset(dveh)
for _ = 1, 72 do driveTick(dp, dveh) end
checkTrue(drive.calls.maxRegSpeed > 0 and drive.calls.maxRegSpeed <= 15,
    "感知缺席時實際 command 受 sensor gate <=15（實得 "
    .. tostring(drive.calls.maxRegSpeed) .. "）")
-- hudState 契約（M5.5b HUD 的資料面；多值純量、不洩漏 session）。
-- do block：釋放 local slot（harness 主 chunk 貼 PUC 200 活躍上限）
do
    local hudKey, hudGear, hudCap, hudZ, hudC = MDAD.Drive.hudState(0)
    checkEq(hudKey, "follow", "hudState 狀態鍵：跟線中")
    checkEq(hudGear, 1, "hudState 檔位＝輕鬆")
    checkEq(hudCap, 30, "hudState 有效上限＝min(檔位 30, 沙盒 40)")
    checkEq(hudZ, true, "hudState 殭屍減速：政策預設由玩家決定＋偏好預設開")
    checkEq(hudC, true, "hudState 屍體減速：同上")
    checkEq(MDAD.Drive.hudState(9), nil, "無 session 的槽回 nil")
    checkEq(MDAD.Drive.effectiveCap(0, dveh), 30,
        "effectiveCap：無論 session 是否存在都與 hudState 同一上限")
    checkEq(MDAD.Drive.hudStartReason(0), nil,
        "hudStartReason：引擎／模組／導航目標齊全可啟動")
    local savedState, savedRoute = drive.nav.state, drive.nav.route
    drive.nav.state = "building"
    checkEq(MDAD.Drive.hudStartReason(0), DKEY.ROUTE,
        "hudStartReason：路網仍在 building 不得誤顯示可啟動")
    drive.nav.state, drive.nav.route = "noroad", nil
    checkEq(MDAD.Drive.hudStartReason(0), DKEY.ROUTE,
        "hudStartReason：noroad 沒有可用路線時回 RouteNotReady")
    drive.nav.state, drive.nav.route = savedState, savedRoute
    local savedTX = drive.nav.tx
    drive.nav.tx = nil
    checkEq(MDAD.Drive.hudStartReason(0), DKEY.ROUTE,
        "hudStartReason：未設導航目標回短狀態可用的原因鍵")
    drive.nav.tx = savedTX
    -- 偏好切換即時反映（setSlowPref 直接刷新 active session 快取）
    MDAD.Drive.setSlowPref(0, "zombie", false)
    local _, _, _, hudZ2 = MDAD.Drive.hudState(0)
    checkEq(hudZ2, false, "關掉殭屍減速偏好：hudState 即時反映")
    checkEq(dp._modData.MDADZombieSlow, false, "偏好寫進 player modData")
    MDAD.Drive.setSlowPref(0, "zombie", true)
end
dp._modData.MDADGear = nil
MDAD.Drive.stop(0, nil)

-- No fixed 70km/h stack remains. Misalignment uses the profile's continuous
-- heading envelope (and adaptive sessions additionally use the named align gate).
dp._modData.MDADGear = 4
setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = true, AutoDriveMaxSpeed = 100, RightLaneBias = 0 })
MDAD.Drive.stop(0, nil)
dveh._x, dveh._y, dveh._speed = 0, 0, 0
setHeading(dveh, 0.0873)
drive.nav.route = newRoute(300, 0, 0, 4, 0)
checkTrue(MDAD.Drive.start(dp), "高速無固定帽情境啟動")
driveReset(dveh)
for _ = 1, 72 do driveTick(dp, dveh) end
checkTrue(drive.calls.maxRegSpeed > 0 and drive.calls.maxRegSpeed <= 15,
    "即使對正，sensor missing gate 仍實際限制 <=15（實得 "
    .. tostring(drive.calls.maxRegSpeed) .. "）")
setHeading(dveh, 0.21)
driveReset(dveh)
driveTick(dp, dveh)
checkTrue(drive.calls.maxRegSpeed <= 15,
    "misalignment cannot bypass sensor gate（實得 "
    .. tostring(drive.calls.maxRegSpeed) .. "）")
dp._modData.MDADGear = nil
MDAD.Drive.stop(0, nil)
setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = true, AutoDriveMaxSpeed = 40, RightLaneBias = 0 })

-- =====================================================================
-- 情境二十：轉向的符號關係與力的量級（力矩由 relPos × impulse 就地算，不抄 production 係數）
-- =====================================================================
scenario("轉向符號與量級：誤差反號則力矩反號、幀奇偶只翻中心力、衝量落在推得動又不甩尾的區間")

-- 車頭比路線朝向大 0.3 rad（車頭偏左）→ 前視點落在右手邊 → 誤差為負。
-- 繞 +y 的正向旋轉會讓 (x,z) 向量順時針轉，也就是 heading 變小；因此
-- 「要往右修（誤差為負）」對應的是**正**的偏航力矩。
MDAD.Drive.stop(0, nil)
dveh._x, dveh._y, dveh._speed, dveh._steering = 0, 0, 20, 0
setHeading(dveh, 0.3)
drive.nav.route = newRoute(40, 0, 0, 4, 0)
checkTrue(MDAD.Drive.start(dp), "短路線啟動（coast/brake 分幀）")
driveReset(dveh)
driveTick(dp, dveh)
driveTick(dp, dveh)
checkEq(dveh._imp.total, 1, "短路線第二幀建完剖面並施力")
drive.snapTorque = dveh._imp.torqueY
drive.snapForce = dveh._imp.x
drive.snapRelX = dveh._imp.rx
checkTrue(drive.snapTorque > 0,
    "車頭偏左（誤差為負）：偏航力矩為正（實得 " .. tostring(drive.snapTorque) .. "）")
checkEq(dveh._imp.y, 0, "impulse 沒有垂直分量（帶垂直分量會變成翻滾／俯仰力矩）")
checkEq(dveh._imp.ry, 0, "relPos 沒有垂直分量")
checkTrue(dveh._imp.rx * dveh._fwdX + dveh._imp.rz * dveh._fwdY > 0,
    "施力點落在車頭（relPos 沿前向為正；2026-09-02 前臂轉向裁定）")
-- 前臂化的決定性契約（2026-09-02）：側推方向與轉頭方向同向——右轉（此案
-- torqueY > 0）時車頭被推向右（側推沿 p̂＝車左法向為負）。後臂會反號
-- （推尾向左讓頭向右轉）；這條斷言把兩種臂向區分開來，力矩同號斷言分不出。
do
    local lat = dveh._imp.x * (-dveh._fwdY) + dveh._imp.z * dveh._fwdX
    checkTrue((lat < 0) == (drive.snapTorque > 0),
        "前臂：側推方向＝轉頭方向（右轉時車頭被推向右；後臂會反號；實得 lat="
        .. tostring(lat) .. "）")
end

driveTick(dp, dveh)
checkEq(dveh._imp.total, 2, "第二幀也只施力一次")
checkTrue(dveh._imp.x * drive.snapForce > 0,
    "側向橫推的中心力兩幀同向（力矩來源是持續的側推，不是幀間交替）")
checkTrue(dveh._imp.torqueY * drive.snapTorque > 0, "力矩與幀奇偶無關，持續同向")
checkNear(dveh._imp.x * dveh._fwdX + dveh._imp.z * dveh._fwdY, 0, 1e-6,
    "中心力是純側向（與前向點積 0）：縱向推力為零，不干擾 regulator 控速")
checkTrue(dveh._imp.rx ~= drive.snapRelX,
    "幀奇偶擺動施力點（車頭左右角交替，防同點數值共振）")

-- 鏡像：車頭偏右（誤差為正）→ 力矩必須反號
MDAD.Drive.stop(0, nil)
dveh._x, dveh._y = 0, 0
setHeading(dveh, -0.3)
drive.nav.route = newRoute(40, 0, 0, 4, 0)
checkTrue(MDAD.Drive.start(dp), "鏡像情境重新啟動（新 session 沒有舊誤差歷史）")
driveReset(dveh)
driveTick(dp, dveh)
driveTick(dp, dveh)
checkEq(dveh._imp.total, 1, "鏡像情境第一幀施力一次")
checkTrue(dveh._imp.torqueY < 0,
    "車頭偏右（誤差為正）：偏航力矩為負（實得 " .. tostring(dveh._imp.torqueY) .. "）")
checkTrue(dveh._imp.torqueY * drive.snapTorque < 0, "朝向誤差反號 → 力矩反號")

-- 對準路線：轉向落在死區，不施力也不取 impulse 向量（免無謂抖動）
MDAD.Drive.stop(0, nil)
dveh._x, dveh._y = 0, 0
setHeading(dveh, 0)
drive.nav.route = newRoute(40, 0, 0, 4, 0)
checkTrue(MDAD.Drive.start(dp), "對準路線也能啟動")
driveReset(dveh)
driveTick(dp, dveh)
driveTick(dp, dveh)
checkEq(dveh._imp.total, 0, "朝向已對準：轉向落在死區，不施力")
checkEq(drive.calls.setRegulatorSpeed, 1, "死區不施力但照樣控速")
checkEq(drive.pool.alloc, 1, "沒施力時只取一顆向量（forward）")
checkEq(drive.pool.release, 1, "沒施力也要把 forward 還回池子")
checkEq(drive.pool.live, 0, "死區這條路徑同樣不能漏 release")

-- 重車直線起步：前推與轉向共用同一個 addImpulse；無轉向時施力點在車身中心，
-- 因此前推沒有額外 yaw，也不會突破每幀單槽不變式。
MDAD.Drive.stop(0, nil)
dveh._x, dveh._y, dveh._speed, dveh._mass = 0, 0, 0, 1600
setHeading(dveh, 0)
drive.nav.route = newRoute(40, 0, 0, 4, 0)
checkTrue(MDAD.Drive.start(dp), "重車前推輔助情境啟動")
driveReset(dveh)
for _ = 1, 120 do driveTick(dp, dveh) end
checkTrue(dveh._imp.total > 0, "重車直線起步會取得前推輔助")
checkEq(dveh._imp.max, 1, "前推與轉向合成後每幀仍最多一次 addImpulse")
checkTrue(dveh._imp.x * dveh._fwdX + dveh._imp.z * dveh._fwdY > 0,
    "前推分量沿車頭方向")
checkNear(dveh._imp.torqueY, 0, 1e-9, "純前推施力點在中心，沒有額外 yaw")
checkNear(dveh._imp.rx, 0, 1e-12, "純前推 relPos.x 為零")
checkNear(dveh._imp.rz, 0, 1e-12, "純前推 relPos.z 為零")
checkEq(drive.bad.impulse, 0, "前推全程沒有第二次 impulse")
checkEq(drive.pool.live, 0, "前推向量池幀末歸零")
MDAD.Drive.stop(0, nil)

-- 1005 高速力臂延伸（TUNE.ARM_EXT_*）：≥FULL 時施力點沿車頭放到 arm×K、側推÷K——力矩不變、側推只剩 1/K，側推方向仍＝
-- 轉頭方向（前臂裁定）；FROM 以下、貼縫爬行 K＝1。fake control 給固定 steer 0.6、目標 120（不觸發煞車）。
-- 違規證明：力不除以 K＝(力矩) 紅；K 不爬升（≥FROM 直接 K）＝(爬升) 紅；拿掉 dodgeCrawl 條件＝(爬行) 紅。
function drive.scenarioArmExt()
    scenario("高速力臂延伸：力臂×K、側推÷K，力矩逐位不變；低速／貼縫爬行 K＝1")
    local T = MDAD.Drive.debugTune()
    local realControl = MDADFollower.control
    local function shot(kmh, setup)
        MDAD.Drive.stop(0, nil)
        dveh._x, dveh._y, dveh._speed, dveh._steering = 0, 0, kmh, 0
        setHeading(dveh, 0)
        drive.nav.route = newRoute(40, 0, 0, 4, 0)
        checkTrue(MDAD.Drive.start(dp), "(arm) " .. kmh .. " km/h 啟動")
        driveReset(dveh)
        driveTick(dp, dveh)
        MDADFollower.control = function(_, state)
            state.curveValid, state.curveHardActive, state.curveKappa, state.curveCapKmh = true, false, 0, 120
            return 0.6, 120, 100, false, 0.2, 0, 0
        end
        local s = MDAD.Drive.debugSession(0)
        if setup then setup(s) end
        driveReset(dveh)
        driveTick(dp, dveh)
        MDADFollower.control = realControl
        local im = dveh._imp
        local r = { total = im.total, tq = im.torqueY, ext = s.armExt, arm = s.rearArm,
            lat = im.x * (-dveh._fwdY) + im.z * dveh._fwdX, fwdR = im.rx * dveh._fwdX + im.rz * dveh._fwdY }
        if setup then setup(s, true) end
        MDAD.Drive.stop(0, nil)
        return r
    end
    local keepK = T.ARM_EXT_K
    T.ARM_EXT_K = 1
    local base = shot(70)
    T.ARM_EXT_K = keepK
    local ext = shot(70)
    checkTrue(base.total == 1 and ext.total == 1, "(arm) 兩次都施力一次")
    checkNear(base.ext, 1, 0, "(arm) 對照組 K＝1")
    checkNear(ext.ext, T.ARM_EXT_K, 1e-12, "(arm) ≥FULL：K＝ARM_EXT_K（實得 " .. tostring(ext.ext) .. "）")
    checkTrue(base.tq ~= 0 and math.abs(ext.tq - base.tq) <= 1e-9 * math.abs(base.tq), string.format(
        "(力矩) 延伸前後偏航力矩不變（%.6f vs %.6f）", ext.tq, base.tq))
    checkNear(ext.lat / base.lat, 1 / T.ARM_EXT_K, 1e-9, "(arm) 側推只剩 1/K")
    checkNear(ext.fwdR, base.fwdR * T.ARM_EXT_K, 1e-6, "(arm) 施力點沿車頭放到 arm×K")
    checkTrue((ext.lat < 0) == (ext.tq > 0), "(arm) 延伸後側推方向仍＝轉頭方向（前臂裁定）")
    local mid = shot((T.ARM_EXT_FROM_KMH + T.ARM_EXT_FULL_KMH) / 2)
    checkNear(mid.ext, 1 + (T.ARM_EXT_K - 1) / 2, 1e-9, "(爬升) FROM 與 FULL 中點：K 走一半（實得 "
        .. tostring(mid.ext) .. "）")
    local low = shot(T.ARM_EXT_FROM_KMH - 5)
    checkTrue(low.ext == 1 and math.abs(low.fwdR - low.arm) < 1e-6, "(arm) FROM 以下 K＝1、施力點＝原前臂（實得 "
        .. tostring(low.ext) .. "）")
    local crawl = shot(70, function(s, undo)
        if undo then s.dodging, s.dodgeCrawl = false, false else s.dodging, s.dodgeCrawl = true, true end
    end)
    checkNear(crawl.ext, 1, 0, "(爬行) 貼縫爬行 K＝1（要的就是側移）")
    -- 拖車（掛車折角動態沒有離線模型）：K＝1。直接問 Drive.armExtK（整合幀掛假 tow 表會走進拖車路徑）
    checkNear(MDAD.Drive.armExtK({ tow = { halfW = 1.2 } }, 70), 1, 0, "(拖車) 拖掛 K＝1")
    checkNear(MDAD.Drive.armExtK({}, 70), T.ARM_EXT_K, 1e-12, "(拖車) 對照：同速單車 K＝ARM_EXT_K")
    checkNear(MDAD.Drive.armExtK({ zombieLane = 1.2 }, 70), 1, 0, "(軟縫) 殭屍軟縫側移中 K＝1（要的就是側移）")
    dveh._speed = 20
end
drive.scenarioArmExt()

-- 1005 同車型轉向增益種子（MDADFollower.storeGains／seedGains 經 Driver）：clearSession 記、startSession 種；快取鍵＝
-- 車輛 script 名（拖掛另分鍵）。違規證明：clearSession 不呼叫 storeGains＝(seed) 紅；startSession 不呼叫 seedGains＝(seed) 紅。
function drive.scenarioGainSeeds()
    scenario("同車型轉向增益種子：session 結束記下、下一趟啟動就帶上；快取鍵依車型與拖掛")
    drive.keepGains = true
    local function startNoTick()
        MDAD.Drive.stop(0, nil)
        dveh._x, dveh._y, dveh._speed, dveh._steering = 0, 0, 20, 0
        setHeading(dveh, 0.3)
        drive.nav.route = newRoute(40, 0, 0, 4, 0)
        checkTrue(MDAD.Drive.start(dp), "(seed) 啟動")
        return MDAD.Drive.debugSession(0)
    end
    local s1 = startNoTick()
    checkEq(s1.gainKey, dveh:getScriptName(), "(seed) 快取鍵＝車輛 script 名")
    checkFalse(s1.gainSeeded, "(seed) 第一趟快取是空的")
    local f = s1.fstate
    f.yawGain, f.ygLearnT, f.yawGainFb, f.fbLearnT, f.yawGainHi, f.hiLearnT = 0.3, 1, 0.2, 1, 0.45, 1
    MDAD.Drive.stop(0, nil)
    local s2 = startNoTick()
    checkTrue(s2.gainSeeded == true and s2.fstate.yawGain == 0.3 and s2.fstate.yawGainFb == 0.2
        and s2.fstate.yawGainHi == 0.45, string.format("(seed) 第二趟啟動就帶上一趟學到的增益（yg %s ygf %s ygh %s）",
            tostring(s2.fstate.yawGain), tostring(s2.fstate.yawGainFb), tostring(s2.fstate.yawGainHi)))
    -- 第二趟學到飽和值（0.08）與沒學滿的 yawGainFb：都不蓋掉快取
    s2.fstate.yawGain, s2.fstate.ygLearnT, s2.fstate.yawGainFb, s2.fstate.fbLearnT = 0.08, 1, 0.6, 0.1
    MDAD.Drive.stop(0, nil)
    local s3 = startNoTick()
    checkTrue(s3.fstate.yawGain == 0.3 and s3.fstate.yawGainFb == 0.2,
        "(seed) 飽和／沒學滿的趟次不蓋掉快取（yg " .. tostring(s3.fstate.yawGain) .. "）")
    MDAD.Drive.stop(0, nil)
    drive.keepGains = false
    local vp = { scriptName = "Base.Pickup" }
    checkEq(MDAD.Drive.gainKey(vp, nil), "Base.Pickup", "(key) 單車＝script 名")
    checkEq(MDAD.Drive.gainKey(vp, { trailer = { getScriptName = function() return "Base.Trailer" end } }),
        "Base.Pickup>Base.Trailer", "(key) 拖掛另分鍵（牽引車>掛車）")
    checkEq(MDAD.Drive.gainKey(vp, { trailer = { getScriptName = function() error("boom") end } }),
        "Base.Pickup>?", "(key) 掛車名讀不到：另一格 ?，不混進單車")
    checkNil(MDAD.Drive.gainKey({}, nil), "(key) 沒有 script 名＝不記")
end
drive.scenarioGainSeeds()

-- (acc) 1001i 加速輔助：目標比實速高就沿車身中線補 ACCEL_ASSIST_MPS2（輕車也有；前推輔助只給重車低速）。
-- 違規證明：ACCEL_ASSIST_MPS2＝0 即整合案（感知情境①後）紅；拿掉伺服器速限夾＝速限案紅；拿掉折角門檻＝拖車案紅；
-- 拿掉全速閘門條件＝閘門案紅；拿掉偏差門檻＝偏差案紅（1001j E2E h1003：離期望線 0.9m 開始補、越線撞路邊）。
do
    local tune = MDAD.Drive.debugTune()
    local acc = { runtimeMass = 1200, fullGate = true, lastLatDev = 0.1 }
    local full = MDAD.Drive.accelAssistForce(acc, 40, 60, 0.8)
    checkNear(acc.accelAssist, tune.ACCEL_ASSIST_MPS2, 1e-9, "(acc) 差 20 km/h：補滿")
    checkNear(full, tune.ACCEL_ASSIST_MPS2 * 1200 / (0.01 * 48 / 0.8), 1e-6,
        "(acc) 力＝加速度×質量（每幀 Δv＝F/m×0.01，與減速輔助同一條換算）")
    checkEq(MDAD.Drive.accelAssistForce(acc, 59.5, 60, 0.8), 0, "(acc) 貼近目標不補（不過衝）")
    MDAD.Drive.accelAssistForce(acc, 56.5, 60, 0.8)
    checkNear(acc.accelAssist, tune.ACCEL_ASSIST_MPS2 * 0.5, 1e-9, "(acc) 差 3.5 km/h：淡入一半")
    -- 伺服器速限 70（getFakeSpeedModifier＝120/70）：引擎到速限就斷油，輔助補到速限前 2 km/h 為止
    local fakeWas = BaseVehicle.getFakeSpeedModifier
    BaseVehicle.getFakeSpeedModifier = function() return 120 / 70 end
    checkEq(MDAD.Drive.accelAssistForce(acc, 67.5, 100, 0.8), 0, "(acc) 伺服器速限 70：67.5 km/h 不補")
    checkTrue(MDAD.Drive.accelAssistForce(acc, 50, 100, 0.8) > 0, "(acc) 伺服器速限 70：50 km/h 照補")
    BaseVehicle.getFakeSpeedModifier = fakeWas
    -- 拖車：折角超過門檻不補（掛車另由呼叫端分攤）
    acc.tow, acc.towPhi = {}, 0.3
    checkEq(MDAD.Drive.accelAssistForce(acc, 40, 60, 0.8), 0, "(acc) 拖車折角 17°：不補")
    acc.towPhi = 0.05
    checkTrue(MDAD.Drive.accelAssistForce(acc, 40, 60, 0.8) > 0, "(acc) 拖車折角 3°：照補")
    acc.tow, acc.towPhi = nil, nil
    -- 全速閘門關著（證明線掃到東西、繞行、回線）或起步近物保護中：不補（E2E acc-1001i h2005）
    acc.fullGate = false
    checkEq(MDAD.Drive.accelAssistForce(acc, 40, 60, 0.8), 0, "(acc) 全速閘門關著：不補")
    acc.fullGate, acc.startGuard = true, true
    checkEq(MDAD.Drive.accelAssistForce(acc, 40, 60, 0.8), 0, "(acc) 起步近物保護中：不補")
    acc.startGuard = nil
    acc.lastLatDev = 0.9
    checkEq(MDAD.Drive.accelAssistForce(acc, 40, 60, 0.8), 0, "(acc) 離期望線 0.9m：不補")
    acc.lastLatDev = -0.6
    checkEq(MDAD.Drive.accelAssistForce(acc, 40, 60, 0.8), 0, "(acc) 離期望線 −0.6m：不補")
    acc.lastLatDev = 0.45
    checkTrue(MDAD.Drive.accelAssistForce(acc, 40, 60, 0.8) > 0, "(acc) 離期望線 0.45m：照補")
    -- (acc-head) 1002a 正式服 0.17.0 Silence/clip-04：出 19° 折點車頭偏 9°、ld −0.43（偏差門檻內）時開始補，
    --   1.5 秒 24→44 km/h 越線 0.56m 擦路邊。違規證明：拿掉航向門檻＝第一條紅。
    acc.lastRouteErr = 0.16
    checkEq(MDAD.Drive.accelAssistForce(acc, 40, 60, 0.8), 0, "(acc-head) 車頭偏離路線 9°：不補")
    acc.lastRouteErr = 0.1
    checkTrue(MDAD.Drive.accelAssistForce(acc, 40, 60, 0.8) > 0, "(acc-head) 偏 5.7°：照補")
    acc.lastRouteErr = nil
    -- (acc-lead) 1002t 正式服 0.17.0 clip-17：出 18.9° 折點時偏差 0.07／0.32（門檻內）、車頭 6.6°／4.9°（門檻內），
    --   但正以 1.1–1.4 m/s 橫越期望線，照補 40→51 km/h 外甩撞路邊。偏差＋橫向速度×0.5 秒超過門檻就不補。
    --   違規證明：拿掉預測閘＝第一條紅。
    acc.lastLatDev, acc.crossDLat = 0.07, 1.44
    checkEq(MDAD.Drive.accelAssistForce(acc, 40, 60, 0.8), 0, "(acc-lead) 偏 0.07m 但以 1.44 m/s 橫越：不補")
    acc.lastLatDev, acc.crossDLat = 0.32, -0.6
    checkTrue(MDAD.Drive.accelAssistForce(acc, 40, 60, 0.8) > 0, "(acc-lead) 偏 0.32m、正往線收：照補")
    acc.lastLatDev, acc.crossDLat = 0.45, nil
    -- (acc-kink) 1002t 正式服 0.17.0 clip-09：起步 4.3m 接 90° fallback 折點，各閘都過、補滿到放行點 14 km/h
    --   滿舵打滑繞圈。前視鉗在還沒放行的無弧折點上（fstate.kinkHeld）就不補。違規證明：拿掉這道閘＝第一條紅。
    acc.fstate = { kinkHeld = 4.3 }
    checkEq(MDAD.Drive.accelAssistForce(acc, 10, 20, 0.8), 0, "(acc-kink) 前視鉗在 4.3m 外的 fallback 折點：不補")
    acc.fstate.kinkHeld = nil
    checkTrue(MDAD.Drive.accelAssistForce(acc, 10, 20, 0.8) > 0, "(acc-kink) 放行之後：照補")
    acc.fstate = nil
    -- (acc-why) 1002a 朝已知障礙接近的帽不補（Aho/clip-21：待承諾繞行時補到 45 km/h，再從 39.5 一秒鎖輪）。
    --   違規證明：拿掉理由白名單＝前一組紅；白名單漏 curve-coast＝後一組紅。
    for _, r in ipairs({ "dodge-defer", "zombie", "zombie-lane", "moving", "dodge", "align", "corpse" }) do
        acc.lastCapReason = r
        checkEq(MDAD.Drive.accelAssistForce(acc, 40, 60, 0.8), 0, "(acc-why) 限速理由 " .. r .. "：不補")
    end
    for _, r in ipairs({ "curve-coast", "visibility", "gear" }) do
        acc.lastCapReason = r
        checkTrue(MDAD.Drive.accelAssistForce(acc, 40, 60, 0.8) > 0, "(acc-why) 限速理由 " .. r .. "：照補")
    end
    acc.lastCapReason = nil
end
dveh._mass = 1200

-- 力的量級：符號全對但推力小兩個數量級＝實機「按了自駕，車直直開過路口」；
-- 2026-08-28 二輪實測連「純力矩×0.8m 臂」的 43k-122k 都只換到每秒 5-9° 偏航。
-- 幾何（前臂側向衝量；耦力調頭走後臂力偶）與量級改照質量與車速標定（實機調校）。
-- 把車頭轉到幾乎反向（2.8 rad＝160° > 原地調頭門檻
-- 135°），follower 必定給飽和轉向。**速度固定 3 km/h**：帶速調頭在
-- ROTATE_ARC_MAX 以下走大弧、以上才煞停（帶動量旋轉＝漂移甩出 22m，st 88,113
-- 遙測）放行的區間內量。
-- 不抄 production 的係數，只圈出可用區間：下界＝夠力調頭，上界＝不會把車彈飛。
MDAD.Drive.stop(0, nil)
dveh._x, dveh._y, dveh._steering = 0, 0, 0
dveh._speed, dveh._mass = 3, 1200
setHeading(dveh, 2.8)
drive.nav.route = newRoute(40, 0, 0, 4, 0)
checkTrue(MDAD.Drive.start(dp), "轉向飽和情境啟動")
driveReset(dveh)
driveTick(dp, dveh)
driveTick(dp, dveh)
checkEq(dveh._imp.total, 1, "轉向飽和幀照樣只施力一次")
drive.f3 = impulseMag(dveh)
checkTrue(drive.f3 >= 8000, "1200kg／3km/h／調頭飽和：衝量至少 8000（實得 "
    .. tostring(drive.f3) .. "；誤差 >90° 走耦力模式，力量乘 ROTATE_FORCE_SCALE"
    .. "——全額調頭＝實機快速循轉，縮到四成才是緩慢平穩的迴轉）")
checkTrue(drive.f3 <= 125000, "同一組條件下衝量不超過 125000（實得 "
    .. tostring(drive.f3) .. "；激進化 STEER 1.8×ROTATE 0.65 後的等比上限）")

-- 耦力調頭：誤差 > 90° 時衝量與施力主臂同乘幀奇偶——力矩恆定同向、側向中心力
-- 幀間抵消＝原地旋轉不橫滑（橫推調頭實機會把車推橫滑 24 km/h 滑出路外撞東西）
drive.rotSnapX, drive.rotSnapTq = dveh._imp.x, dveh._imp.torqueY
driveReset(dveh)
driveTick(dp, dveh)
checkTrue(dveh._imp.x * drive.rotSnapX < 0,
    "調頭模式：連續兩幀側向中心力反號（幀間抵消，不推車橫滑）")
checkTrue(dveh._imp.torqueY * drive.rotSnapTq > 0,
    "調頭模式：力矩與幀奇偶無關，持續同向（q² 相消）")

-- 大誤差速度閘：同樣的 160° 誤差、30 km/h → 主動煞停、本幀不施力
dveh._speed = 30
driveReset(dveh)
driveTick(dp, dveh)
-- 1001e：25 km/h 以上的調頭前煞停改不鎖輪（正式服 susu 82 km/h 換目標要調頭，連續鎖輪 4.5 秒只減到 27 km/h）：
-- 只有沿車頭反向的中線減速力、方向盤不轉。違規證明：hardBrake 拿掉 rotate 分支＝forceBrake 0 那條紅。
checkTrue(drive.pureBrake(dveh),
    "誤差 160°、車速 30 km/h：速度閘煞停不施側推（yield 中調頭再放手不得瞬間甩車）")
checkTrue(drive.calls.forceBrake == 0 and (MDAD.Drive.debugSession(0).visAssistDecel or 0) > 0,
    "帶動量的調頭需求：主動煞停（30 km/h 不鎖輪減速，forceBrake " .. drive.calls.forceBrake .. "）")
dveh._speed = 4
driveReset(dveh)
driveTick(dp, dveh)
checkEq(dveh._imp.total, 1, "同誤差、車速降到 4（≤5 近停）：放行，開始施力調頭")

-- 速度增益：0 km/h 仍有轉向權威、護欄內隨速度單調上升；封頂（60 cap）用小誤差
-- （30°，護欄不介入）在 70 vs 200 km/h 驗——兩者 steer 相同，衝量只差 gain(v)
dveh._speed = 0
driveReset(dveh)
driveTick(dp, dveh)
drive.f0 = impulseMag(dveh)
checkTrue(drive.f0 > 0 and drive.f0 == drive.f0 and drive.f0 < math.huge,
    "0 km/h 仍有有限且非零的轉向權威（原地掉頭要推得動，實得 " .. tostring(drive.f0) .. "）")
checkTrue(drive.f3 > drive.f0, "轉向衝量隨速度單調上升（0 km/h＝" .. tostring(drive.f0)
    .. "、3 km/h＝" .. tostring(drive.f3) .. "）")

MDAD.Drive.stop(0, nil)
dveh._x, dveh._y, dveh._speed = 0, 0, 100
setHeading(dveh, 0.52)  -- 30°：護欄之下、死區之上
drive.nav.route = newRoute(40, 0, 0, 4, 0)
checkTrue(MDAD.Drive.start(dp), "封頂情境啟動")
driveReset(dveh)
driveTick(dp, dveh)
drive.f70 = impulseMag(dveh)
MDAD.Drive.stop(0, nil) -- 兩案各自乾淨 PID：連續 tick 的 D 項（err-ePrev）
dveh._speed = 200        -- 在 STEER 1.8 放大後會讓兩案假差 ~0.6×
checkTrue(MDAD.Drive.start(dp), "封頂情境 200 案重啟")
driveReset(dveh)
driveTick(dp, dveh)
drive.f200 = impulseMag(dveh)
checkTrue(drive.f70 > 0, "小誤差高速照常施力（實得 " .. tostring(drive.f70) .. "）")
local capDiff = drive.f200 - drive.f70
if capDiff < 0 then capDiff = -capDiff end
-- 100 vs 200：lookahead 都封頂 18m、速度增益都封 60——兩案衝量嚴格同量級。
-- （舊對照 70 vs 200 混入 lookahead 14.4/18 的投影差，激進化常數放大後假紅）
checkTrue(capDiff <= drive.f70 * 0.02,
    "速度增益封頂：量級不再隨速度成長（100＝" .. tostring(drive.f70)
    .. "、200＝" .. tostring(drive.f200) .. "；±2% 內為控制歷史量測差）")

-- 拖掛車低速側推（2026-09-26 Workshop「草地起步劇烈晃動、掛車脫開」，E2E trailer-grass-mp）：
-- 側推的 MASS_BASE 項與車速無關，靜止也把車頭整台橫推、掛車不動＝折角 0.4 秒甩到 61°。
-- 拖車時側推隨車速線性放大到 TOW_STEER_FULL_KMH（15）才全額。
-- 一般車同理（2026-09-27 正式服 14 段起步 target 0 橫滑 13–30 km/h）：STEER_FULL_KMH（4）以下
-- 按車速縮、靜止為零。違規證明：一般車拿掉縮放＝free0 紅。
do
    local trailer = {
        getForwardVector = function(_, out) return out:set(dveh._fwdX, 0, dveh._fwdY) end,
        getUpVectorDot = function() return 1 end,
    }
    -- fwdKmh：車身前進速度（給了就讓 getLinearVelocity 回「前進 fwdKmh＋橫向補足」，|v| 仍是 speed）
    local function steerMag(speed, towed, fwdKmh)
        MDAD.Drive.stop(0, nil)
        dveh._x, dveh._y, dveh._speed = 0, 0, speed
        setHeading(dveh, 0.52)
        drive.nav.route = newRoute(40, 0, 0, 4, 0)
        checkTrue(MDAD.Drive.start(dp), "拖車側推情境啟動（" .. speed .. " km/h）")
        if towed then MDAD.Drive.debugSession(0).tow = { trailer = trailer } end
        driveReset(dveh)
        driveTick(dp, dveh) -- 第一幀可能還在 build（建剖面、不施力）
        local realVel = dveh.getLinearVelocity
        if fwdKmh ~= nil then
            local f, l = fwdKmh / 3.6, math.sqrt(math.max(0, speed * speed - fwdKmh * fwdKmh)) / 3.6
            dveh.getLinearVelocity = function(self, out)
                return out:set(self._fwdX * f - self._fwdY * l, 0, self._fwdY * f + self._fwdX * l)
            end
        end
        driveReset(dveh)
        driveTick(dp, dveh)
        dveh.getLinearVelocity = realVel
        checkTrue(MDAD.Drive.isActive(0), "拖車側推情境仍在自駕（" .. speed .. " km/h）")
        return dveh._imp.total > 0 and impulseMag(dveh) or 0
    end
    local free0, tow0 = steerMag(0, false), steerMag(0, true)
    checkEq(free0, 0, "沒拖車：靜止也不側推（實得 " .. tostring(free0) .. "）")
    checkEq(tow0, 0, "拖車：靜止不側推（實得 " .. tostring(tow0) .. "）")
    local free2, tow2 = steerMag(2, false), steerMag(2, true)
    checkTrue(free2 > 0, "沒拖車 2 km/h：已開始有側推（實得 " .. tostring(free2) .. "）")
    checkNear(tow2, free2 * 4 / 15, free2 * 1e-6,
        "2 km/h：一般車按 2/4、拖車按 2/15 縮（" .. tostring(tow2) .. " / " .. tostring(free2) .. "）")
    local free75, tow75 = steerMag(7.5, false), steerMag(7.5, true)
    checkNear(tow75, free75 * 0.5, free75 * 1e-6,
        "拖車 7.5 km/h：側推為全額的一半（" .. tostring(tow75) .. " / " .. tostring(free75) .. "）")
    local free20, tow20 = steerMag(20, false), steerMag(20, true)
    checkNear(tow20, free20, free20 * 1e-6, "拖車 20 km/h：側推全額")
    -- (slip-push) 1004b 正式服 0.18.2 起步大弧調頭 8 段：側推推出的橫滑讓 |v| 越過 STEER_FULL_KMH，縮放被自己解鎖成
    --   全額、越推越滑。縮放改看車身前進速度：|v| 6、前進只有 0.5 km/h＝按 0.5/4 縮；前進已過 4＝全額照舊。
    --   違規證明：applySteering 不讀前進速度（退回 |v|）＝(slip-push) 第一條紅。
    local free6, slip6 = steerMag(6, false), steerMag(6, false, 0.5)
    checkNear(slip6, free6 * 0.5 / 4, free6 * 1e-6,
        "(slip-push) |v| 6 km/h 但前進只有 0.5：側推按前進速度縮成 0.5/4（" .. tostring(slip6) .. " / " .. tostring(free6) .. "）")
    local free8, slip8 = steerMag(8, false), steerMag(8, false, 5)
    checkNear(slip8, free8, free8 * 1e-6, "(slip-push) 前進 5 km/h（已過 4）帶側滑：側推全額照舊")
    MDAD.Drive.stop(0, nil)
end

-- =====================================================================
-- 情境二十一：玩家讓位與恢復
-- =====================================================================
scenario("玩家讓位：預設介入即關閉；選了自動恢復才待命，放手連續 N 秒才恢復跟線，換路線不繞過等待")

-- 2026-09-06 使用者裁定：手動介入後預設「不自動恢復」（回饋「不知道放開會變回自動駕駛、
-- 突然回頭被嚇到」）。HUD 缺 manualResumeMs getter＝預設＝介入即結束 session。
MDAD.Drive.stop(0, nil)
dveh._x, dveh._y, dveh._speed, dveh._steering = 0, 0, 20, 0
setHeading(dveh, 0.3)
drive.nav.route = newRoute(40, 0, 0, 4, 0)
checkTrue(MDAD.Drive.start(dp), "讓位情境啟動")
driveReset(dveh)
driveTick(dp, dveh)
driveTick(dp, dveh)
checkEq(dveh._imp.total, 1, "正常跟線會施力（讓位斷言才有對照）")
checkEq(MDAD.HUD, nil, "此處 HUD 尚未掛載＝getter 缺席＝預設策略")
dveh._steering = 0.02
driveReset(dveh)
clearList(halos)
driveTick(dp, dveh)
checkFalse(MDAD.Drive.isActive(0), "預設不自動恢復：一碰方向盤就結束 session")
checkEq(dveh._imp.total, 0, "介入當幀不施力")
checkEq(drive.calls.regulatorOff, 1, "介入即關閉時把 regulator 關掉")
checkEq(drive.calls.forceBrake, 0, "介入即關閉不搶煞車")
checkEq(#halos, 1, "介入即關閉提示一次")
checkEq(haloKey(), noteReason("UI_MinidoracatAutoDrive_ManualStop"), "介入即關閉提示 ManualStop")
checkEq(halos[1] and halos[1].kind, "good", "介入即關閉是綠字（玩家自己接手不是錯誤）")
checkEq(drive.lastVoice(), "manual", "介入即關閉開口 manual（不是 stop）")

-- 選項明確回 0 也一樣（缺席與「不自動恢復」同義）
drive.resumeMs = 0
MDAD.HUD = { manualResumeMs = function() return drive.resumeMs end }
dveh._steering = 0
drive.nav.route = newRoute(40, 0, 0, 4, 0)
checkTrue(MDAD.Drive.start(dp), "選項回 0：重新啟動")
driveTick(dp, dveh)
driveTick(dp, dveh)
dveh._steering = 0.02
driveReset(dveh)
driveTick(dp, dveh)
checkFalse(MDAD.Drive.isActive(0), "選項回 0：介入即關閉")

-- 選「放手 2 秒後恢復」：待命，下面是原本的讓位／恢復契約
drive.resumeMs = 2000
dveh._steering = 0
drive.nav.route = newRoute(40, 0, 0, 4, 0)
checkTrue(MDAD.Drive.start(dp), "選 2 秒：重新啟動")
driveReset(dveh)
driveTick(dp, dveh)
driveTick(dp, dveh)
checkEq(dveh._imp.total, 1, "選 2 秒：正常跟線會施力")
clearList(drive.voiceLog)

-- getCurrentSteering 的門檻是 0.01：手把的類比轉向會有微小殘值，不能一碰就讓位
dveh._steering = 0.005
driveReset(dveh)
driveTick(dp, dveh)
checkEq(dveh._imp.total, 1, "轉向 0.005 在門檻以下：不算玩家輸入")

dveh._steering = 0.02
driveReset(dveh)
driveTick(dp, dveh)
checkEq(dveh._imp.total, 0, "玩家在轉方向盤：當幀完全不施力")
checkEq(drive.calls.regulatorOff, 1, "讓位時關掉 regulator")
checkEq(drive.calls.regulatorOn, 0, "讓位時不再供油")
checkEq(drive.calls.setRegulatorSpeed, 0, "讓位時不設定速")
checkEq(drive.calls.forceBrake, 0, "讓位不搶煞車（玩家要自己接手）")
checkEq(drive.pool.alloc, 0, "讓位幀不取向量池")
checkEq(#halos, 1, "讓位提示一次")
checkEq(haloKey(), DKEY.MANUAL, "讓位提示 ManualOverride")
checkEq(halos[1] and halos[1].kind, "good", "讓位是綠字（不是錯誤）")
checkTrue(MDAD.Drive.isActive(0), "讓位不結束 session（待命中）")
checkEq(drive.voiceCount("yield"), 1, "讓位開口 yield（教學句）")
checkEq(select(6, MDAD.Drive.hudState(0)), nil, "按著方向盤：HUD 不倒數（第 6 值 nil）")

driveReset(dveh)
driveTick(dp, dveh)
driveTick(dp, dveh)
checkEq(#halos, 0, "持續讓位不重複提示")
checkEq(dveh._imp.total, 0, "持續讓位持續不施力")
checkEq(drive.calls.regulatorOff, 0, "已經在 yield 就不重複關 regulator")

-- 放手：恢復是「連續 2 秒無輸入」的時間制（舊制 10 幀＝手一離開就接管，玩家
-- 調頭到一半就被暴力搶回）。放手瞬間先記時戳、觀察期不施力，滿 2 秒才恢復
-- 並提示，且恢復幀會清 PID 歷史（保留投影游標）。
dveh._steering = 0
driveReset(dveh)
for _ = 1, 9 do driveTick(dp, dveh) end
checkEq(dveh._imp.total, 0, "放手後時間未滿：觀察期不施力（幀數再多也一樣）")
checkEq(drive.calls.setRegulatorSpeed, 0, "觀察期不控速")
checkEq(drive.pool.alloc, 0, "觀察期不取向量池")
checkEq(select(6, MDAD.Drive.hudState(0)), 2, "放手當下 HUD 倒數 2 秒")
nowMs = nowMs + 1999
driveTick(dp, dveh)
checkEq(dveh._imp.total, 0, "1999ms：還差 1ms，不恢復")
checkEq(select(6, MDAD.Drive.hudState(0)), 1, "剩 1ms：倒數顯示 1（向上取整、最少 1）")
nowMs = nowMs + 1
driveReset(dveh)
driveTick(dp, dveh)
checkEq(dveh._imp.total, 1, "滿 2 秒無輸入：恢復跟線並施力")
checkEq(drive.calls.setRegulatorSpeed, 1, "恢復後重新控速")
checkEq(haloKey(), DKEY.RESUME, "恢復時頭上提示 Resume")
checkEq(halos[1] and halos[1].kind, "good", "恢復是綠字")
checkEq(select(6, MDAD.Drive.hudState(0)), nil, "恢復後 HUD 不再倒數")
checkEq(drive.voiceCount("resume"), 0, "讓位不到 5 秒就恢復：不念 resume（微調不吵）")

-- 油門／煞車沒有等價的類比觀測（isGasPedalPressed 在 regulator 供油時恆真），
-- 所以改看鍵位；五個綁定名都必須讓位
for _, ok in ipairs({ "Left", "Right", "Forward", "Backward", "Brake" }) do
    drive.keys[ok] = true
    driveReset(dveh)
    driveTick(dp, dveh)
    checkEq(dveh._imp.total, 0, ok .. " 鍵按下：當幀不施力")
    checkTrue(MDAD.Drive.isActive(0), ok .. " 鍵按下不結束 session")
    drive.keys[ok] = false
    driveTick(dp, dveh)          -- 記乾淨時戳
    nowMs = nowMs + 2100
    driveTick(dp, dveh)          -- 滿 2 秒恢復
end
driveReset(dveh)
driveTick(dp, dveh)
checkEq(dveh._imp.total, 1, "五個鍵都放開並等滿恢復緩衝後回到跟線")

-- 讓位語音每 session 一次；恢復語音只在讓位持續 ≥ TUNE.YIELD_VOICE_MS（5 秒）才念——
-- 勾了自動恢復的老玩家輕推方向盤微調，每 2 秒念一句「我接手了」會吵。
checkEq(drive.voiceCount("yield"), 1, "七次讓位只念一次 yield")
checkEq(drive.voiceCount("resume"), 0, "短暫讓位恢復都不念 resume")
dveh._steering = 0.02
driveReset(dveh)
driveTick(dp, dveh)
nowMs = nowMs + 4000
driveTick(dp, dveh)              -- 按著 4 秒
dveh._steering = 0
driveTick(dp, dveh)              -- 記乾淨時戳
nowMs = nowMs + 2000
driveReset(dveh)
driveTick(dp, dveh)
checkEq(dveh._imp.total, 1, "按 4 秒＋放手 2 秒：恢復跟線")
checkEq(drive.voiceCount("resume"), 1, "讓位累計 6 秒 ≥5 秒：恢復念 resume")
checkEq(drive.voiceCount("yield"), 1, "第二次以後的讓位不再念 yield")

-- 讓位中主 MOD 換路線（玩家掉頭最常觸發偏航重算）：cutover 不得覆寫 yield——舊制
-- 覆寫成 build、下一幀 build→follow＝0 秒接管、無 Resume 提示（2026-09-06 回饋
-- 「放開會變回自動駕駛、突然回頭」的一條路徑）。恢復幀對未 build 的新剖面先走 build。
dveh._steering = 0.02
driveReset(dveh)
driveTick(dp, dveh)                        -- 讓位
dveh._steering = 0
driveTick(dp, dveh)                        -- 記乾淨時戳（觀察期）
drive.nav.route = newRoute(40, 0, 0, 4, 0) -- 新 identity＝主 MOD 重算
nowMs = nowMs + 300                        -- 越過 ROUTE_REFRESH_MS
driveReset(dveh)
clearList(halos)
driveTick(dp, dveh)                        -- cutover 幀
driveTick(dp, dveh)
checkEq((MDAD.Drive.hudState(0)), "yield", "觀察期換路線：仍是 yield（cutover 不覆寫）")
checkEq(dveh._imp.total, 0, "觀察期換路線：不施力、不接管")
checkEq(#halos, 0, "觀察期換路線：沒有提示（尚未恢復）")
nowMs = nowMs + 1700                       -- 放手累計 2 秒
driveReset(dveh)
driveTick(dp, dveh)                        -- 恢復幀
checkEq(haloKey(), DKEY.RESUME, "換路線後滿 2 秒才恢復並提示 Resume")
checkEq(dveh._imp.total, 0, "恢復幀：新剖面先 build，不施力")
checkEq((MDAD.Drive.hudState(0)), "build", "恢復幀 mode build（新剖面尚未 ready）")
-- 40 點剖面在 BUILD_BUDGET=128 下要幾幀（fillet 建弧的 ops 不只點數）；build 完才跟線
drive.resumeBuildFrames = 0
while (MDAD.Drive.hudState(0)) == "build" and drive.resumeBuildFrames < 8 do
    drive.resumeBuildFrames = drive.resumeBuildFrames + 1
    driveTick(dp, dveh)
end
checkEq((MDAD.Drive.hudState(0)), "follow",
    "build 完成：回到 follow（" .. drive.resumeBuildFrames .. " 幀）")
driveReset(dveh)
driveTick(dp, dveh)
checkEq(dveh._imp.total, 1, "恢復後跟線施力")

-- =====================================================================
-- 情境二十二：超速主動煞車與抵達停車
-- =====================================================================
scenario("超速主動煞車；抵達目的地煞停，停妥後交還控制權，途中玩家接手立刻放手")

-- regulator 只會「不再供油」，下坡或超速時它不會煞車，所以超出目標太多要自己煞
driveReset(dveh)
driveTick(dp, dveh)
checkEq(drive.calls.regulatorOn, 1, "沒超速時 regulator 開著供油")
checkEq(drive.calls.forceBrake, 0, "沒超速不煞車")

setHeading(dveh, 0)
dveh._speed = 100
driveReset(dveh)
driveTick(dp, dveh)
checkEq(drive.calls.forceBrake, 0,
    "straight overspeed without a hard stopping/curvature breach does not forceBrake")
checkEq(drive.calls.regulatorOn, 1, "straight overspeed coasts under regulator command")
checkEq(drive.calls.setRegulatorSpeed, 1, "straight overspeed still writes the lower command")
checkTrue(dveh._imp.total <= 1, "straight overspeed still obeys one-impulse maximum")
checkEq(drive.pool.live, 0, "coast path同樣不漏 release")
dveh._speed = 20

-- MAX 對應積極，其餘檔位舒適；行駛中切换只重建速度表，不更換路線或重設投影。
do
    MDAD.Drive.stop(0, nil)
    local oldGear = MDAD.Drive.getGear(0)
    dveh._x, dveh._y, dveh._speed = 0, 0, 20
    setHeading(dveh, 0)
    drive.nav.route = { pts = { 0, 0, 30, 0, 60, 0, 60, 60, 120, 60 }, len = 180 }
    MDAD.Drive.setGear(0, 4)
    checkTrue(MDAD.Drive.start(dp), "(style) MAX 啟動")
    for _ = 1, 8 do driveTick(dp, dveh) end
    local st = MDAD.Drive.debugSession(0)
    local profile, routeGen, points = st.profile, st.routeGen, st.profile.pts
    -- 這台假車的側向先驗 3.2、制動先驗 2.6 都低於兩檔的天花板（1001i 起兩檔彎前收油也都加中線減速輔助），
    -- 速度表分不出兩檔；兩檔參數的差別由 test_follower 的風格情境鎖。這裡鎖 Driver 的契約：MAX 對應積極、
    -- 其餘對應舒適，切檔就地換風格、不換路線 identity。
    local briskStart = profile.v[2]
    for _, gear in ipairs({ 3, 2, 1 }) do
        MDAD.Drive.setGear(0, gear)
        for _ = 1, 8 do driveTick(dp, dveh) end
        checkEq(profile.styleName, "comfort", "(style) 非 MAX 檔用舒適風格")
        checkTrue(st.profile == profile and st.profile.pts == points and st.routeGen == routeGen,
            "(style) 切檔保留路線與幾何 identity")
    end
    MDAD.Drive.setGear(0, 4)
    for _ = 1, 8 do driveTick(dp, dveh) end
    checkEq(profile.styleName, "brisk", "(style) 切回 MAX 用積極風格")
    checkNear(profile.v[2], briskStart, 1e-9,
        "(style) 切回 MAX 速度表與起步時相同")
    checkTrue(MDAD.Drive.isActive(0), "(style) 切檔不停止本趟自駕")
    -- 速度明細：MAX 檔沒有檔位上限（由車輛極速決定），一般檔位回該檔上限
    checkNil(select(3, MDAD.Drive.speedInfo(0, dveh)), "(speed-info) MAX 檔不回檔位上限")
    MDAD.Drive.setGear(0, 3)
    for _ = 1, 2 do driveTick(dp, dveh) end
    checkEq(select(3, MDAD.Drive.speedInfo(0, dveh)), 70, "(speed-info) 70 檔回檔位上限 70")
    MDAD.Drive.stop(0, nil)
    MDAD.Drive.setGear(0, oldGear)
end

-- 抵達：用短路線（8 點×4 公尺＝28 公尺）。follower 的投影搜尋窗只有前後 12 段，
-- 把車瞬移到長路線的終點不會被判定為抵達——那是刻意的防瞬移設計，不是 bug。
MDAD.Drive.stop(0, nil)
dveh._x, dveh._y, dveh._speed, dveh._steering = 0, 0, 20, 0
setHeading(dveh, 0.3)
drive.nav.route = newRoute(8, 0, 0, 4, 0)
checkTrue(MDAD.Drive.start(dp), "短路線啟動")
driveReset(dveh)
driveTick(dp, dveh)
checkEq(dveh._imp.total, 1, "還沒到：照常施力")
-- 假抵達守衛：車移到終點前 2 公尺、但橫向偏離 20 公尺（被撞開／擦身而過）。
-- 沿路徑剩餘距離同樣是 2m，只看 remaining 的話這裡就會宣告到站並煞停，
-- 而車其實還在 20 公尺外的路邊。此佈置對前視點的朝向誤差 ≈101°、車速 20。
-- 2026-09-01 階段 2 主體 6（調頭雙契約統一）：調頭姿態的唯一權威改成 Follower
-- 的 fstate.rotating（135° 進／100° 出遲滯），Driver 自己那條 90° 門檻已刪。
-- 101° 落在舊 90-135° 匯流區——舊制 Driver 判「要調頭」主動煞停，Follower 卻
-- 判「還在跟線」照樣給轉向，兩層各說各話。新契約：101° 就是「姿態很差但仍可
-- 追線」，減速交給 alignmentCap 連續縮放，不再主動煞停；絕不宣告抵達。
dveh._x, dveh._y = 26, 20
driveReset(dveh)
driveTick(dp, dveh)
checkEq(drive.calls.forceBrake, 0,
    "匯流區 101°（<ROTATE_ENTER 135°）不再主動煞停：交 alignmentCap 減速")
checkEq(dveh._imp.total, 1, "匯流區 101° 照常施轉向（Follower 仍在跟線）")
checkTrue(MDAD.Drive.isActive(0), "橫向偏離終點：session 繼續（不是 arrive）")
-- 這個早期 M3 fixture 尚未載入 Sensor／Corridor；RETURN 不得成為啟動依賴，
-- 因此保持既有 pure follower 主動煞停後跟線，而不是誤進 RETURN HOLD。
checkEq(drive.calls.setRegulatorSpeed, 1, "alignment brake may follow an already-issued coast command")
checkEq(drive.calls.regulatorOn, 1, "alignment handling remains best-effort after regulator update")
-- 對照組：真正的反向（err ≈156° > ROTATE_ENTER）＝調頭姿態。
-- 2026-09-06「調頭方式」（使用者裁定預設溫和）：新一次調頭先煞到該檔 entry（溫和 5）以下
-- 才放行；放行後只剩常駐上限 arc（溫和 13）——大弧爬行 12 不重啟入場煞停（s060 振盪防線）。
-- 選項在調頭開始讀一次，途中改檔同一次調頭不變；快速檔 entry＝arc＝25＝09-01 激進化行為。
setHeading(dveh, 1.66)
driveReset(dveh)
driveTick(dp, dveh)
-- 1004b：調頭前煞停 10 km/h 以上不鎖輪（RETURN_NOLOCK_KMH 25→10，使用者核准）：斷油＋中線減速力、本幀不轉向；
-- 10 以下照舊鎖輪停住。違規證明：RETURN_NOLOCK_KMH 改回 25＝下面三條「不鎖輪」紅。
checkTrue(drive.calls.forceBrake == 0 and (MDAD.Drive.debugSession(0).visAssistDecel or 0) > 0,
    "溫和（預設）：反向 156°＋速度 20 > entry 5：入場先煞停（不鎖輪，forceBrake " .. drive.calls.forceBrake .. "）")
checkTrue(drive.pureBrake(dveh), "溫和入場煞停幀不施轉向（只有中線減速力）")
dveh._speed = 8
driveReset(dveh)
driveTick(dp, dveh)
checkTrue(drive.calls.forceBrake > 0, "入場煞停降到 8（< 10）：鎖輪停住")
checkTrue(MDAD.Drive.isActive(0), "入場煞停不放棄 session")
dveh._speed = 4
driveReset(dveh)
driveTick(dp, dveh)
checkEq(drive.calls.forceBrake, 0, "降到 4 ≤ entry 5：放行、不煞")
checkTrue(dveh._imp.total >= 1, "放行幀施轉向力")
dveh._speed = 12   -- 探測擋住走大弧的爬行速（此 fixture 無 Sensor：spin 5 以上即大弧）
driveReset(dveh)
driveTick(dp, dveh)
checkEq(drive.calls.forceBrake, 0, "放行後大弧 12 > entry 5 但 ≤ arc 13：不重啟入場煞停（s060）")
checkTrue(dveh._imp.total >= 1, "大弧幀施轉向力")
dveh._speed = 14
driveReset(dveh)
driveTick(dp, dveh)
checkTrue(drive.calls.forceBrake == 0 and (MDAD.Drive.debugSession(0).visAssistDecel or 0) > 0,
    "14 > arc 13：常駐上限仍煞停（不鎖輪）")
MDAD.HUD.uturnMode = function() return "fast" end
dveh._speed = 20
driveReset(dveh)
driveTick(dp, dveh)
checkTrue(drive.calls.forceBrake == 0 and (MDAD.Drive.debugSession(0).visAssistDecel or 0) > 0,
    "同一次調頭途中改快速：仍用溫和參數（20 > arc 13 煞停、不鎖輪）")
-- 結束這次調頭：收尾看的是對前視點的誤差 < 100°——側偏 20m 時 heading 0.3 對前視點仍
-- ≈101°（見上方假抵達守衛註解）；把車頭指向前視點（約 -73°）即收尾，不能回 y=0（會抵達）
setHeading(dveh, -1.3)
driveReset(dveh)
driveTick(dp, dveh)
setHeading(dveh, 1.66)  -- 下一次調頭：快速檔生效
driveReset(dveh)
driveTick(dp, dveh)
checkEq(drive.calls.forceBrake, 0,
    "快速：反向 156°＋速度 20 ≤ ARC 25：帶速甩調頭、不煞停（09-01 激進化裁定保留）")
checkTrue(dveh._imp.total >= 1, "帶速調頭幀施轉向力")
checkTrue(MDAD.Drive.isActive(0), "帶速調頭不放棄 session")
dveh._speed = 30
driveReset(dveh)
driveTick(dp, dveh)
checkTrue(drive.calls.forceBrake > 0 or (MDAD.Drive.debugSession(0).visAssistDecel or 0) > 0,
    "快速：反向 156°＋速度 30 > ARC 25：仍主動煞停（甩出防線在；25 km/h 以上不鎖輪）")
checkTrue(drive.pureBrake(dveh), "超帶煞停幀不施轉向（只有中線減速力）")
checkTrue(MDAD.Drive.isActive(0), "煞停不放棄 session")
MDAD.HUD.uturnMode = nil
dveh._speed = 20
setHeading(dveh, 0.3)
driveReset(dveh)
driveTick(dp, dveh)
dveh._y = 0
dveh._x = 26           -- 沿路徑剩 2 公尺、離終點直線距離也是 2 公尺 <= ARRIVE_M(5)
driveReset(dveh)
driveTick(dp, dveh)
checkEq(dveh._imp.total, 0, "抵達當幀不再施力（停車時不能還在推車）")
checkEq(drive.calls.forceBrake, 1, "pure follower brake 與 arrive 共用當前冪等煞車狀態")
checkEq(drive.calls.regulatorOff, 1, "pure follower brake 與 arrive 都維持 regulator 關閉")
checkEq(dveh._regulator, false, "抵達後 regulator 是關的")
checkEq(drive.pool.alloc, 1, "抵達幀只取 forward 一顆向量")
checkEq(drive.pool.live, 0, "抵達幀也要把向量還回池子")
checkTrue(MDAD.Drive.isActive(0), "還沒停妥：session 繼續（要把車停好）")

-- 煞停途中就算引擎熄火也不能半路放手
dveh._engine = false
driveReset(dveh)
driveTick(dp, dveh)
checkTrue(MDAD.Drive.isActive(0), "煞停途中熄火仍不放手（arrive 排在其他閘門之前）")
checkEq(drive.calls.forceBrake, 1, "繼續送煞車")
checkEq(dveh._imp.total, 0, "煞停途中不施力")
checkEq(drive.calls.getForwardVector, 0, "煞停途中不做跟線運算")
checkEq(drive.pool.alloc, 0, "煞停途中不取向量池")
checkEq(#halos, 0, "還沒停妥不提示")
dveh._engine = true

nowMs = nowMs + 2200 -- 與上一趟零秒明確不同，漏掉 arrive 計時才真的會被抓到
drive.clockAtArrival = select(7, MDAD.Drive.hudState(0))
dveh._stopped = true
driveReset(dveh)
driveTick(dp, dveh)
checkFalse(MDAD.Drive.isActive(0), "停妥後結束 session")
checkEq(select(7, MDAD.Drive.hudState(0)), drive.clockAtArrival,
    "抵達自動結束也保留末趟時間（不只手動 stop）")
checkEq(drive.calls.forceBrake, 0, "停妥後不再送煞車")
checkEq(drive.calls.regulatorOff, 1, "停妥時關掉 regulator")
checkEq(#halos, 1, "抵達提示一次")
checkEq(haloKey(), DKEY.ARRIVED, "抵達提示 Arrived")
checkEq(halos[1] and halos[1].kind, "good", "抵達是綠字")
checkEq(drive.lastVoice(), "arrive", "停妥開口 arrive")
dveh._stopped = false

-- 煞停途中玩家自己踩煞車：立刻交還，不跟他搶（已送出的 forceBrake 1 秒後自行失效）
MDAD.Drive.stop(0, nil)
dveh._x, dveh._y = 0, 0
drive.nav.route = newRoute(8, 0, 0, 4, 0)
checkTrue(MDAD.Drive.start(dp), "重新啟動以再測一次抵達")
driveTick(dp, dveh)
dveh._x = 26
driveTick(dp, dveh)
checkTrue(MDAD.Drive.isActive(0), "已進入煞停")
drive.keys.Brake = true
driveReset(dveh)
driveTick(dp, dveh)
checkFalse(MDAD.Drive.isActive(0), "煞停途中玩家踩煞車：立刻交還控制權")
checkEq(drive.calls.forceBrake, 0, "交還後不再送煞車")
checkEq(drive.calls.regulatorOff, 1, "交還時把 regulator 關掉（不留定速給下一個上車的人）")
checkEq(#halos, 1, "玩家自己接手：一則綠字提示（不是紅字）")
checkEq(haloKey(), noteReason("UI_MinidoracatAutoDrive_ManualStop"), "煞停途中接手提示 ManualStop")
checkEq(halos[1] and halos[1].kind, "good", "煞停途中接手是綠字")
checkEq(drive.lastVoice(), "manual", "煞停途中接手開口 manual")
drive.keys.Brake = false

-- =====================================================================
-- 情境二十三：失效停止
-- =====================================================================
scenario("失效停止：下車／換車／非駕駛／死亡靜默結束；引擎、電瓶、模組、GPS、nav API、路線各自紅字")

checkTrue(armDrive(), "失效情境的基準 session 建立成功")
dp._vehicle = nil
driveTick(dp, dveh)
checkFalse(MDAD.Drive.isActive(0), "玩家下車：靜默結束")
checkEq(#halos, 0, "下車不是錯誤，不彈紅字")
checkEq(drive.calls.regulatorOff, 1, "下車也要把 regulator 關掉")

checkTrue(armDrive(), "換車情境重新啟動")
veh = newVehicle({ battery = newItem("Base.CarBattery", { uses = 0.8 }), engineRunning = true })
veh._driver = dp
dp._vehicle = veh
driveTick(dp, dveh)
checkFalse(MDAD.Drive.isActive(0), "換到另一輛車：靜默結束")
checkEq(#halos, 0, "換車不彈紅字")
checkEq(dveh._regulator, false, "關掉的是**原本**那台車的 regulator")

checkTrue(armDrive(), "非駕駛情境重新啟動")
dveh._driver = nil
driveTick(dp, dveh)
checkFalse(MDAD.Drive.isActive(0), "被擠到副駕：靜默結束")
checkEq(#halos, 0, "換座位不彈紅字")

checkTrue(armDrive(), "死亡情境重新啟動")
dp._dead = true
driveTick(dp, dveh)
checkFalse(MDAD.Drive.isActive(0), "玩家死亡：靜默結束")
checkEq(#halos, 0, "死亡不彈紅字")
checkEq(drive.calls.getForwardVector, 0, "死亡當幀不再算控制")
checkEq(drive.pool.alloc, 0, "死亡當幀不取向量池")

checkTrue(armDrive(), "熄火情境重新啟動")
dveh._engine = false
driveTick(dp, dveh)
checkFalse(MDAD.Drive.isActive(0), "引擎熄火：結束自駕")
checkEq(haloKey(), DKEY.ENGINE, "熄火提示 EngineOff")
checkEq(halos[1] and halos[1].kind, "bad", "失效停止是紅字")

checkTrue(armDrive(), "電瓶情境重新啟動")
dveh._part._item._uses = 0
driveTick(dp, dveh)
checkFalse(MDAD.Drive.isActive(0), "行進中電瓶沒電：結束自駕")
checkEq(haloKey(), DKEY.ENGINE, "電瓶死掉沿用 EngineOff")

checkTrue(armDrive(), "模組情境重新啟動")
dveh._devices.MDADAutopilot._item = nil
driveTick(dp, dveh)
checkFalse(MDAD.Drive.isActive(0), "自駕模組被拆掉：結束自駕")
checkEq(haloKey(), DKEY.NEED_MODULE, "缺模組提示 NeedModule")
dveh._devices.MDADAutopilot._item = newItem(AUTO_T)

-- 導航道具閘門在行進中失效。driveGate 每幀用 context="draw"，隨身搜尋有 1 秒快取，
-- 所以要跨過 TTL 才會重掃背包——這正是「每幀不掃背包」的效能設計。
setSandbox({ NeedItemForNav = true, NeedItemForAutoDrive = true, AutoDriveMaxSpeed = 40 })
dp:getInventory():AddItem(newItem(GPS_T, { uses = 0.5, useDelta = 0.006 }))
nowMs = nowMs + 2000
checkTrue(armDrive(), "帶著有電 GPS 可以啟動（NeedItemForNav=true）")
it = MDAD.findChargedPortableGPS(dp)
checkTrue(it ~= nil, "GPS 真的在背包裡")
dp:getInventory():DoRemoveItem(it)
driveReset(dveh)
driveTick(dp, dveh)
checkTrue(MDAD.Drive.isActive(0), "GPS 剛掉：draw 快取還沒過期，自駕不受影響")
checkEq(stats.scanTypeEval, 0, "快取有效期內完全不掃背包")
nowMs = nowMs + 1001
driveReset(dveh)
driveTick(dp, dveh)
checkEq(stats.scanTypeEval, 1, "跨過 1 秒快取才重掃一次背包")
checkFalse(MDAD.Drive.isActive(0), "行進中 GPS 掉了：結束自駕")
checkEq(haloKey(), NEED_GPS, "缺 GPS 提示 NeedGPS")
setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = true, AutoDriveMaxSpeed = 40, RightLaneBias = 0 })

checkTrue(armDrive(), "nav API 情境重新啟動")
MinidoracatMiniMapAPI = nil
driveTick(dp, dveh)
checkFalse(MDAD.Drive.isActive(0), "行進中主 MOD 被拔掉：結束自駕")
checkEq(haloKey(), NAV_API_MISSING, "缺 API 提示 NavApiMissing")
installNavApi(2)

-- 路線遺失的三條路徑（都要跨過 250ms 節流才會重查）
checkTrue(armDrive(), "目標消失情境重新啟動")
drive.nav.tx = nil
nowMs = nowMs + 250
driveTick(dp, dveh)
checkFalse(MDAD.Drive.isActive(0), "導航目標被清掉：結束自駕")
checkEq(haloKey(), DKEY.LOST, "目標消失提示 LostRoute")

-- 抵達競態：主 MOD 在距目標 NAV_ARRIVE_DIST（5 格）內**每幀**自動清除導航目標
-- （小地圖「走到旗子就收旗」），必然搶在 follower reached（沿線開完＋停妥）之前
-- ——目標消失但車已在剛才目標的抵達圈（12 格）內＝「到達」：轉入 arrive 煞停
-- 流程收綠字，不是紅字 LostRoute（2026-08-28 實機：每次開到目的地都閃紅字）
checkTrue(armDrive(), "抵達清除競態情境重新啟動")
dveh._x = 296                      -- 距 armDrive 目標 (300,0) 4 格＝主 MOD 清除圈內
drive.nav.tx = nil                 -- 主 MOD navCheckArrival 收走目標
nowMs = nowMs + 250
driveReset(dveh)
driveTick(dp, dveh)
checkTrue(MDAD.Drive.isActive(0), "抵達圈內目標消失：不結束（轉入到站煞停）")
checkEq(#halos, 0, "接管當幀不彈紅字")
checkTrue(drive.calls.forceBrake > 0, "接管當幀開始煞停")
dveh._speed = 0
dveh._stopped = true
driveReset(dveh)
driveTick(dp, dveh)
checkFalse(MDAD.Drive.isActive(0), "停妥後結束 session")
checkEq(haloKey(), DKEY.ARRIVED, "提示已抵達（不是路線遺失）")

checkTrue(armDrive(), "路線重算中情境重新啟動")
drive.nav.state = "pending"
nowMs = nowMs + 250
driveTick(dp, dveh)
checkFalse(MDAD.Drive.isActive(0), "路線重算中拿不到路線：結束自駕")
checkEq(haloKey(), DKEY.LOST, "路線拿不到提示 LostRoute")

checkTrue(armDrive(), "壞路線情境重新啟動")
drive.nav.route = { pts = { 5, 5 } }
nowMs = nowMs + 250
driveTick(dp, dveh)
checkFalse(MDAD.Drive.isActive(0), "新路線 follower 收不了：結束自駕")
checkEq(haloKey(), DKEY.LOST, "壞路線提示 LostRoute")
checkTrue(armDrive(), "zero forward vector 情境重新啟動")
dveh._fwdX, dveh._fwdY = 0, 0
driveReset(dveh)
driveTick(dp, dveh)
checkFalse(MDAD.Drive.isActive(0),
    "finite zero-length forward vector visibly fail-stops")
checkTrue(drive.calls.regulatorOff >= 1,
    "zero forward vector disables regulator before visible stop")
checkEq(drive.calls.forceBrake, 0,
    "zero forward vector cannot issue a steering-dependent brake path")
checkEq(dveh._imp.total, 0, "zero forward vector never emits steering impulse")
checkEq(drive.pool.live, 0, "zero forward vector returns the pooled vector before stop")
checkEq(haloKey(), DKEY.UNSUPPORTED, "zero forward vector reports unsupported dynamics")
setHeading(dveh, 0)
do
checkTrue(armDrive(), "missing curve state 情境重新啟動")
local strictCurveControl = MDADFollower.control
MDADFollower.control = function(_, state)
    state.curveValid = false
    state.curveHardActive = false
    state.curveKappa, state.curveCapKmh = 0, 0
    return 0, 20, 100, false, 0, 0, 0
end
driveReset(dveh)
driveTick(dp, dveh)
MDADFollower.control = strictCurveControl
checkFalse(MDAD.Drive.isActive(0),
    "missing curve validity is a terminal dynamics fault")
checkTrue(drive.calls.regulatorOff >= 1 and drive.calls.forceBrake >= 1,
    "invalid curve state disables regulator and best-effort brakes")
checkEq(dveh._imp.total, 0, "invalid curve state never emits steering impulse")
checkEq(haloKey(), DKEY.UNSUPPORTED, "invalid curve state reports unsupported dynamics")
end

-- =====================================================================
-- 情境二十四：route identity 換了才重建剖面
-- =====================================================================
scenario("路線換 identity 才重建剖面：重建期不控速、follower 狀態就地重設")

-- 監看 follower 的四個入口：只是順路記一筆，真正的實作照樣執行
drive.spy.beginReal = MDADFollower.begin
drive.spy.resetReal = MDADFollower.resetState
drive.spy.controlReal = MDADFollower.control
MDADFollower.begin = function(route, maxSpeed)
    drive.spy.begin = drive.spy.begin + 1
    return drive.spy.beginReal(route, maxSpeed)
end
MDADFollower.resetState = function(state)
    drive.spy.reset = drive.spy.reset + 1
    drive.spy.resetState = state
    return drive.spy.resetReal(state)
end
MDADFollower.control = function(profile, state, x, y, heading, speed, dt)
    drive.spy.control = drive.spy.control + 1
    drive.spy.idxIn = state.idx
    drive.spy.state = state
    return drive.spy.controlReal(profile, state, x, y, heading, speed, dt)
end

MDAD.Drive.stop(0, nil)
dveh._x, dveh._y, dveh._speed, dveh._steering = 0, 0, 20, 0
dveh._engine, dveh._driver = true, dp
dveh._part._item._uses = 0.8
dp._vehicle = dveh
setHeading(dveh, 0.3)
drive.nav.tx, drive.nav.ty, drive.nav.state = 300, 0, "ok"
drive.nav.route = newRoute(40, 0, 0, 4, 0)
driveReset(dveh)
checkTrue(MDAD.Drive.start(dp), "route identity 情境啟動")
checkEq(drive.spy.begin, 1, "啟動時建一次剖面")
checkEq(drive.spy.control, 0, "啟動本身不呼叫 control")
driveTick(dp, dveh)
driveTick(dp, dveh)
checkEq(drive.spy.control, 1, "第二幀剖面建完並呼叫一次 control")
drive.spy.firstState = drive.spy.state
checkEq(type(drive.spy.firstState), "table", "control 拿到的 follower state 是 table")

for _ = 1, 5 do
    dveh._x = dveh._x + 4
    driveTick(dp, dveh)
end
checkEq(drive.spy.state, drive.spy.firstState, "每幀重用同一顆 state（不是每幀新配一顆）")
checkTrue(drive.spy.idxIn > 1,
    "進度真的推進了（進 control 時的 idx＝" .. tostring(drive.spy.idxIn) .. "）")

-- 同一顆 route：節流到期也不重建
nowMs = nowMs + 250
driveReset(dveh)
driveTick(dp, dveh)
checkEq(drive.nav.targetCalls, 1, "節流到期會重查一次導航目標")
checkEq(drive.nav.routeCalls, 1, "有目標才去要路線")
checkEq(drive.spy.begin, 0, "route 是同一顆：不重建剖面")
checkEq(drive.spy.reset, 0, "route 沒換：不重設 follower 狀態")
checkEq(dveh._imp.total, 1, "沒重建就照常跟線")

-- 換一顆新 route table＝主 MOD 重算過（改目標、偏航重算）：整份重建
drive.nav.route = newRoute(300, 0, 0, 4, 0)
nowMs = nowMs + 250
driveReset(dveh)
driveTick(dp, dveh)
checkEq(drive.spy.begin, 1, "route 換 identity：重建剖面")
checkEq(drive.spy.reset, 1, "重建時重設 follower 狀態（否則吃到舊路線的誤差歷史）")
checkEq(drive.spy.resetState, drive.spy.firstState, "就地重設同一顆 state，不換 table")
checkEq(drive.spy.control, 0, "重建當幀不呼叫 control")
checkEq(dveh._imp.total, 0, "重建當幀不施力")
checkEq(drive.calls.setRegulatorSpeed, 0, "重建當幀不控速")
checkEq(drive.calls.regulatorOff, 1, "重建期間鬆油門讓車滑行")
checkEq(drive.calls.forceBrake, 0, "重建期間不煞車（剖面通常一兩幀就好）")
checkEq(drive.pool.alloc, 0, "重建幀不取向量池")

-- New 300-point profile needs 12 total bounded build calls; cutover already did one.
driveReset(dveh)
for _ = 1, 10 do driveTick(dp, dveh) end
checkEq(dveh._imp.total, 0, "新剖面建構期同樣不施力")
driveTick(dp, dveh)
checkEq(dveh._imp.total, 1, "建完新剖面就恢復跟線")
checkEq(drive.spy.idxIn, 1, "重設後從路線起點重新投影（idx 歸 1）")

MDADFollower.begin = drive.spy.beginReal
MDADFollower.resetState = drive.spy.resetReal
MDADFollower.control = drive.spy.controlReal

-- =====================================================================
-- 情境二十五：車輛 radial 選單
-- =====================================================================
scenario("車輛 radial：片補在原版之後、只給駕駛、選單看得見才加、標題隨狀態、回呼真的切換")

MDAD.Drive.stop(0, nil)
drive.menus[0] = newRadialMenu()
dp._vehicle, dveh._driver = dveh, dp
dveh._x, dveh._y, dveh._steering = 0, 0, 0
setHeading(dveh, 0.3)
drive.nav.route = newRoute(40, 0, 0, 4, 0)

driveReset(dveh)
ISVehicleMenu.showRadialMenu(dp)
checkEq(drive.orig.n, 1, "原版 showRadialMenu 有被呼叫（wrapper 沒把它吃掉）")
checkEq(drive.orig.player, dp, "原樣把玩家傳給原版")
checkEq(#drive.menus[0].slices, 3, "原版的片還在，自駕片＋檔位片補在後面")
checkEq(drive.menus[0].slices[1].text, "VANILLA",
    "第一片是原版自己加的（我們的片必須在原版 clear() 之後才加）")
opt = drive.menus[0].slices[2]
checkEq(noteReason(opt.text), DKEY.START, "沒在自駕時標題是啟動")
checkEq(opt.command, MDAD.Drive.toggle, "回呼交出的就是 production 的 Drive.toggle")
checkEq(opt.arg1, dp, "回呼帶操作者")
checkEq(opt.texture, "tex:AutopilotModule", "自駕片帶到自訂圖示")
checkEq(drive.texCalls[1], "media/textures/Item_AutopilotModule.png", "先試完整 media 路徑")
checkEq(drive.texCalls[2], "Item_AutopilotModule", "完整路徑拿不到就退回無路徑寫法")
checkEq(#drive.texCalls, 2, "只查兩次貼圖")
-- 檔位片：文字帶 GearSlice 鍵（fake getText 丟參數回鍵名）、點了循環到下一檔。
-- do block：釋放 local slot（主 chunk 貼 PUC 200 活躍上限）
do
    local gearOpt = drive.menus[0].slices[3]
    checkEq(noteReason(gearOpt.text), "UI_MinidoracatAutoDrive_GearSlice", "第三片是檔位片")
    checkEq(MDAD.Drive.getGear(0), 3, "未設定過檔位：預設運動（升級不無聲降速）")
    gearOpt.command(gearOpt.arg1)
    checkEq(MDAD.Drive.getGear(0), 4, "點檔位片：循環到下一檔（運動→瘋狂）")
    checkEq(haloKey(), "UI_MinidoracatAutoDrive_GearInsane", "切檔頭上綠字回饋新檔位")
    checkEq(dp._modData.MDADGear, 4, "檔位寫進 player modData（跨 session 持久）")
    gearOpt.command(gearOpt.arg1)
