-- =====================================================================
-- 情境二十八：走廊感知與繞行（真 MDAD_Sensor + MDAD_Corridor，假世界）
-- =====================================================================
-- 到這裡才載入感知兩檔：前面所有自駕情境都跑在 session.sensor=false 的 M3 退路上
-- ——那也是 production 契約（檔案樹缺 Sensor 不得炸、跟線照常）。實機引擎會把
-- client 目錄全部載入，感知路徑由本情境覆蓋。
require "MDAD_Corridor"
require "MDAD_Sensor"
scenario("走廊感知：淨空直行、中線障礙繞行、堵死煞停可自動恢復、殭屍跟車未載入減速、停車政策不繞")

checkEq(type(MDADCorridor), "table", "production shared/MDAD_Corridor.lua 真的載入了")
checkEq(type(MDADSensor), "table", "production client/MDAD_Sensor.lua 真的載入了")

-- 感知的假世界。Sensor 的 PZ 入口全走參數（cell、vehicle）與延後綁定
-- （IsoFlagType/IsoObjectType/instanceof 首輪掃描才讀），這裡塞替身即可。
IsoFlagType = { water = "water", solidfloor = "solidfloor", doorN = "doorN", doorW = "doorW",
    DoorWallN = "DoorWallN", DoorWallW = "DoorWallW", open = "open",
    solidtrans = "solidtrans", solid = "solid", collideN = "collideN", collideW = "collideW" }
    -- solidtrans：(C2) 用；solid／collideN／collideW：0929j 引擎形狀（putSolid 的 props 一律回 false，不受影響）
IsoObjectType = { isMoveAbleObject = 28 }
-- _isa：繼承鏈（IsoAnimal extends IsoPlayer，IsoAnimal.java:123）——真引擎 instanceof(animal, "IsoPlayer") 為真
function instanceof(obj, cls)
    if type(obj) ~= "table" then return false end
    if rawget(obj, "_class") == cls then return true end
    local isa = rawget(obj, "_isa")
    return isa ~= nil and isa[cls] == true
end
drive.world = {}
drive.cellVehicles = {}  -- 全域車輛清單（調頭探測 probeAround 走 Set:iterator() 迭代）
drive.vehGeo = {}        -- 格級車輛佔位（production 走 square:getVehicleContainer() 幾何查詢）
drive.cell = {
    getGridSquare = function(_, x, y, _z) return drive.world[x * 100000 + y] end,
    -- 42.20.4 的 getVehicles() 回 Set<BaseVehicle>：**沒有 get(int)**，只能 iterator。
    -- fake 也只給 iterator/size，production 若倒退回 :get(i-1)（ISVehicleBloodUI 的
    -- 過期寫法，實機 nil call）這裡會當場炸。
    getVehicles = function()
        local i, n = 0, #drive.cellVehicles
        return {
            size = function() return n end,
            iterator = function()
                return {
                    hasNext = function() return i < n end,
                    next = function()
                        i = i + 1
                        return drive.cellVehicles[i]
                    end,
                }
            end,
        }
    end,
}
function getCell() return drive.cell end

function drive.mkSquare(x, y)
    local objs, mv, smv = {}, {}, {}
    local sq = { _objs = objs, _mv = mv, _smv = smv, _floor = false }
    -- production 的水面判定看地板 sprite（getFloor():hasProperty(water)）；
    -- 假格預設無地板物件（回 nil）＝非水。要造水面就把 _floor 換成帶
    -- hasProperty 的假物件。
    sq.getFloor = function() return sq._floor or nil end
    -- 0905s：production 的水面判定改逐物件看 sprite 旗標（waterUnderfoot），地板也是
    -- getObjects 的一員（IsoGridSquare.getFloor 就是從 objects 找）：假格把 _floor 排在
    -- index 0 一起吐出；_floor 以 drive.floorObj 建（帶 getSprite/getProperties）。
    sq._objList = {
        size = function() return #objs + (sq._floor and 1 or 0) end,
        get = function(_, i)
            if sq._floor then
                if i == 0 then return sq._floor end
                return objs[i]
            end
            return objs[i + 1]
        end,
    }
    sq._mvList = { size = function() return #mv end, get = function(_, i) return mv[i + 1] end }
    -- 屍體容器（IsoDeadBody 住 staticMovingObjects，見 Sensor 的出處註解）
    sq._smvList = { size = function() return #smv end, get = function(_, i) return smv[i + 1] end }
    sq.getObjects = function() return sq._objList end
    -- 格級聚合屬性（production 只在門類 sprite 才讀：closedDoor）；drive.putGate 寫 sq._flags
    sq._flags = {}
    sq.getProperties = function() return { has = function(_, key) return sq._flags[key] == true end } end
    -- 格級幾何查詢（IsoGridSquare.getVehicleContainer 的假版）：production 的
    -- 車輛感知唯一入口。單格佔位＝點車（等同舊 movingObjects 錨語意）。
    sq.getVehicleContainer = function() return drive.vehGeo[x * 100000 + y] end
    sq.getMovingObjects = function() return sq._mvList end
    sq.getStaticMovingObjects = function() return sq._smvList end
    drive.world[x * 100000 + y] = sq
    return sq
end

-- 佈滿空格的路面（含路肩）：走廊帶 ±4 公尺內任何 nil 格都算「未載入」，
-- 所以淨空情境也要把格子填好填滿
function drive.fillWorld(x0, x1, y0, y1)
    drive.world = {}
    drive.vehGeo = {}
    for x = x0, x1 do
        for y = y0, y1 do drive.mkSquare(x, y) end
    end
end

-- 假地板物件：solidfloor 旗標＋（選）water 旗標；不帶碰撞。production 讀 getSprite()
-- :getProperties():has(flag) 與 getSpriteName()。
function drive.floorObj(name, water)
    local props = { has = function(_, key)
        if key == "solidfloor" then return true end
        if key == "water" then return water == true end
        if key == "solidtrans" then return water == true end -- 實機水面 sprite 帶 solidtrans
        return false
    end }
    local sprite = {
        shouldHaveCollision = function() return water == true end, -- solidtrans → 引擎回 true
        getProperties = function() return props end,
    }
    return {
        getSpriteName = function() return name end,
        getSprite = function() return sprite end,
        getProperties = function() return props end,
        getType = function() return nil end,
        hasProperty = function(_, key) return props:has(key) end,
    }
end

-- 鋪路面：把矩形範圍的假格地板換成 blends_street 家族 sprite（路面對中統計
-- 認前綴；非水）。production 讀 floorObj:getSpriteName()。
function drive.putRoad(x0, x1, y0, y1)
    for x = x0, x1 do
        for y = y0, y1 do
            local sq = drive.world[x * 100000 + y] or drive.mkSquare(x, y)
            sq._floor = drive.floorObj("blends_street_01_16", false)
        end
    end
end

-- 格級車輛：塞進 vehGeo（getVehicleContainer 幾何佔位）。stopped＝isStopped 回傳
-- （true＝硬障礙要繞；false＝跟車減速）。回傳假車物件供情境調 isStopped 波動
-- 或改 _x/_y 模擬移動（production 的跨輪位置比對讀 getX/getY＋getId）。
drive.vehIdSeq = 0
function drive.putVehicle(x, y, stopped)
    drive.vehIdSeq = drive.vehIdSeq + 1
    local id = drive.vehIdSeq
    local v = {
        _class = "BaseVehicle",
        _stopped = stopped,
        _x = x + 0.5,
        _y = y + 0.5,
    }
    v.getX = function() return v._x end
    v.getY = function() return v._y end
    v.getId = function() return id end
    v.isStopped = function() return v._stopped end
    drive.vehGeo[x * 100000 + y] = v
    return v
end

function drive.clearVehicle(x, y)
    drive.vehGeo[x * 100000 + y] = nil
end

-- 移動假車到新格（保 id：production 的跨輪位置比對以 vehicleId 為鍵，
-- 「同一台車動了」必須同 id 才測得到）
function drive.moveVehicle(v, x, y)
    for k, vv in pairs(drive.vehGeo) do
        if vv == v then drive.vehGeo[k] = nil end
    end
    v._x, v._y = x + 0.5, y + 0.5
    drive.vehGeo[x * 100000 + y] = v
end

-- 有真幾何的假車（2026-09-02 車陣精確輪廓）：中心 (cx,cy)、朝向 heading（rad）、
-- 尺寸 W×L；提供 getScript():getExtents()/getCenterOfMassOffset() 與
-- getWorldPos(lx, ly, lz, out)（VehiclePoly.java:52-88 同式：x 軸＝車寬、z 軸＝車長），
-- 並把 OBB 蓋到的每一格都登記進 vehGeo（＝isIntersectingSquare 的格級語意）。
-- 回車物件與佔位格清單（clear 用）。
function drive.putVehicleGeom(cx, cy, heading, W, L, stopped)
    drive.vehIdSeq = drive.vehIdSeq + 1
    local id = drive.vehIdSeq
    local halfW, halfL = W * 0.5, L * 0.5
    local fx, fy = math.cos(heading), math.sin(heading)
    local nx, ny = -fy, fx
    local ext = { x = function() return W end, z = function() return L end, y = function() return 1.5 end }
    local com = { x = function() return 0 end, z = function() return 0 end, y = function() return 0 end }
    local script = { getExtents = function() return ext end, getCenterOfMassOffset = function() return com end }
    local v = { _class = "BaseVehicle", _stopped = stopped ~= false, _x = cx, _y = cy }
    v.getX = function() return v._x end
    v.getY = function() return v._y end
    v.getId = function() return id end
    v.isStopped = function() return v._stopped end
    v.getScript = function() return script end
    -- local (lx, ly, lz)：lx 沿車寬（法向）、lz 沿車長（前向）
    v.getWorldPos = function(_, lx, _ly, lz, out)
        return out:set(v._x + fx * lz + nx * lx, v._y + fy * lz + ny * lx, 0)
    end
    local cells = {}
    local reach = halfL + halfW + 1
    for gx = math.floor(cx - reach), math.floor(cx + reach) do
        for gy = math.floor(cy - reach), math.floor(cy + reach) do
            -- 格子四角＋格心任一落在 OBB 內＝相交（粗判，測試用）
            local hit = false
            for _, pt in ipairs({ { gx, gy }, { gx + 1, gy }, { gx, gy + 1 }, { gx + 1, gy + 1 }, { gx + 0.5, gy + 0.5 } }) do
                local dx, dy = pt[1] - cx, pt[2] - cy
                local u, w = dx * fx + dy * fy, dx * nx + dy * ny
                if u >= -halfL and u <= halfL and w >= -halfW and w <= halfW then hit = true break end
            end
            if hit then
                drive.vehGeo[gx * 100000 + gy] = v
                cells[#cells + 1] = gx * 100000 + gy
            end
        end
    end
    return v, cells
end

function drive.clearVehicleGeom(cells)
    for i = 1, #cells do drive.vehGeo[cells[i]] = nil end
end

-- 硬障礙：有碰撞、非地板（Sensor 分類器：shouldHaveCollision 且非 solidfloor＝HARD）
function drive.putSolid(x, y, name)
    local props = { has = function() return false end }
    local sprite = {
        shouldHaveCollision = function() return true end,
        getProperties = function() return props end,
    }
    local sq = drive.world[x * 100000 + y] or drive.mkSquare(x, y)
    sq._objs[#sq._objs + 1] = {
        getSpriteName = function() return name end,
        getSprite = function() return sprite end,
        getProperties = function() return props end,
        getType = function() return nil end,
    }
end

-- 城市路邊物件：分開模擬 collision／HitByCar／StopCar。引擎是 StopCar 才把
-- tile type 設成 isMoveAbleObject；tile 的 IsMoveAble 屬性本身不會。
function drive.putSpriteObject(x, y, name, collision, hitByCar, stopCar)
    local props = {
        has = function(_, key)
            if key == "HitByCar" then return hitByCar == true end
            if key == "StopCar" then return stopCar == true end
            return false
        end,
    }
    local sprite = {
        shouldHaveCollision = function() return collision == true end,
        getProperties = function() return props end,
    }
    local sq = drive.world[x * 100000 + y] or drive.mkSquare(x, y)
    sq._objs[#sq._objs + 1] = {
        getSpriteName = function() return name end,
        getSprite = function() return sprite end,
        getProperties = function() return props end,
        getType = function()
            if stopCar then return IsoObjectType.isMoveAbleObject end
            return nil
        end,
    }
end

-- 樹：sprite **無**碰撞 flag（實機樹對 shouldHaveCollision 隱形，靠
-- instanceof IsoTree 判 HARD——2026-08-28 撞樹鬼打牆的修正）
function drive.putTree(x, y, name)
    local props = { has = function() return false end }
    local sprite = {
        shouldHaveCollision = function() return false end,
        getProperties = function() return props end,
    }
    local sq = drive.world[x * 100000 + y] or drive.mkSquare(x, y)
    sq._objs[#sq._objs + 1] = {
        _class = "IsoTree",
        getSpriteName = function() return name end,
        getSprite = function() return sprite end,
        getProperties = function() return props end,
        getType = function() return nil end,
    }
end

-- 細桿（0929j）：無碰撞旗標的籬笆 sprite＝Sensor 的格心 0 半徑細桿（引擎不給形狀，保守留著）。0929j 起樹幹照
-- 引擎放在格 +0.6/+0.6、半徑 0.15；需要「格心點狀障礙」幾何的精密夾縫情境（混材縫、守護降檔）改用它，
-- 幾何與這些情境當初設計時的樹幹模型一致。
function drive.putPost(x, y, name)
    drive.putSolid(x, y, "fencing_" .. (name or "harness_post"))
end

-- 門／柵門（0928m）：門 sprite 帶 doorN／doorW；格級屬性另有 DoorWallN／W，開著多一個 open（引擎 calcPhysics
-- 只在沒有 open 時給車輛碰撞牆）。sprite 名隨開關不同（IsoDoor closedSprite／openSprite）。
function drive.putGate(x, y, north, open)
    local door = north and "doorN" or "doorW"
    local props = { has = function(_, key) return key == door end }
    local sprite = {
        shouldHaveCollision = function() return false end,
        getProperties = function() return props end,
    }
    local sq = drive.world[x * 100000 + y] or drive.mkSquare(x, y)
    sq._flags[door] = true
    sq._flags[north and "DoorWallN" or "DoorWallW"] = true
    sq._flags.open = open == true or nil
    sq._objs[#sq._objs + 1] = {
        _class = "IsoDoor",
        getSpriteName = function() return open and "harness_gate_open" or "harness_gate_closed" end,
        getSprite = function() return sprite end,
        getProperties = function() return props end,
        getType = function() return nil end,
    }
end

function drive.putMoving(x, y, mv)
    local sq = drive.world[x * 100000 + y] or drive.mkSquare(x, y)
    -- production 對殭屍讀 getX/getY（殭屍軟縫的 (s,l)）：缺者以格心補（同引擎的 IsoMovingObject 座標）
    if mv.getX == nil then
        local wx, wy = x + 0.5, y + 0.5
        mv.getX = function() return wx end
        mv.getY = function() return wy end
    end
    sq._mv[#sq._mv + 1] = mv
end

-- 地面屍體：進 staticMovingObjects、instanceof IsoDeadBody
function drive.putCorpse(x, y, angle)
    local sq = drive.world[x * 100000 + y] or drive.mkSquare(x, y)
    local body = { _class = "IsoDeadBody", _x = x + 0.5, _y = y + 0.5, _angle = angle or 0 }
    body.getX = function() return body._x end
    body.getY = function() return body._y end
    body.getAngle = function() return body._angle end
    sq._smv[#sq._smv + 1] = body
    return body
end

function drive.clearCell(x, y)
    local sq = drive.world[x * 100000 + y]
    if not sq then return end
    for i = #sq._objs, 1, -1 do sq._objs[i] = nil end
    for i = #sq._mv, 1, -1 do sq._mv[i] = nil end
    for i = #sq._smv, 1, -1 do sq._smv[i] = nil end
end

-- 跑完一整輪掃描＋規劃；nowMs 先跨過 250ms 節流窗。
-- 一輪的幀數＝掃描帶步數 ÷（SCAN_BUDGET/LAT_N＝4 個弧步／幀）。0909b 感知距離可調後，
-- 帶長從「28 幀跑得完的 ~50m」變成最長 120m（≈30 幀），舊的「一輪＝28 幀」假定會讓
-- 明確要求長視距的情境拿到半輪快照。改成先跑滿原本的 28 幀（既有情境的時間推進量與
-- 進度語意不變），再等 sensor.scanning 落下＝本輪真的收尾。nowMs 在輪內不前進、
-- nextMs＝輪首+250ms，所以同一次呼叫裡不可能開下一輪，等到的必定是同一輪的完成。
function drive.scanRound(freezeProgress)
    nowMs = nowMs + 300
    -- Most sensor-policy fixtures report a non-zero wheel speed. Keep their mock world
    -- physically consistent with the progress supervisor without changing final geometry:
    -- after the round is complete (nextMs is in the future), move >1m for one tick and
    -- return for one tick. Intentional stuck/contact cases pass true to suppress this.
    for _ = 1, 28 do driveTick(dp, dveh) end
    for _ = 1, 128 do
        local sc = MDAD.Drive.debugSession(0)
        sc = sc ~= nil and sc.sensor or nil
        if sc == nil or sc.scanning ~= true then break end
        driveTick(dp, dveh)
    end
    local av = dveh._speed
    if av < 0 then av = -av end
    if not freezeProgress and av >= 1 and MDAD.Drive.isActive(0) then
        local ox, oy = dveh._x, dveh._y
        dveh._x = ox + dveh._fwdX * 1.1
        dveh._y = oy + dveh._fwdY * 1.1
        driveTick(dp, dveh)
        dveh._x, dveh._y = ox, oy
        driveTick(dp, dveh)
    end
end

-- 寬帶判到這次脫困嘗試的最寬一級（1004c：第一級仍堵就升級重掃，倒車／改道的閘等最寬那級判完）。給「寬帶判堵後看
-- 倒車／改道時序」的情境用；升級本身由 (wide2) 逐輪檢查。武裝解除（已承諾／判淨空）或判完即停，最多三輪。
function drive.wideRounds(freezeProgress)
    for _ = 1, 3 do
        drive.scanRound(freezeProgress)
        local st = MDAD.Drive.debugSession(0)
        if st == nil or not st.wideArmed or st.wideJudged == st.episodeAttempts then return end
    end
end

-- 感知距離可調（0909b）：有效視距＝SCAN_NEAR＋(額度/LAT_N)×PERCEPTION_ROUND_MS/幀時，額度自 0929o 起
-- 隨幀時放大（MDADDynamics.scanBudget，最多 3 倍）：預設 drive.mult 1.6（30 FPS＝幀時 33ms）已有 60 FPS 的
-- 92m，要重現「幀率造成的短視距」得用 50ms 以上。個別情境在自己的區塊裡改幀時再還原。
-- frameEwmaMs 從 33ms 收斂到 10ms 要上百個樣本（每樣本只走 frame/(1000+frame)），所以連
-- EWMA 一起直接寫成目標幀時；區塊內新開的 session 其 EWMA 是 0、首個樣本就等於幀時，
-- 不需要暖機。回傳原本的幀時（ms）供區塊結束時還原。
function drive.frameMs(ms)
    local was = drive.mult * 1000 / 48 -- Driver 的 SECONDS_PER_MULT＝1/48
    drive.mult = ms * 48 / 1000
    local st = MDAD.Drive.debugSession(0)
    if st ~= nil and st.sensor ~= nil then st.sensor.frameEwmaMs = ms end
    return was
end

-- ① 淨空：跑完一輪，沒有任何檔位介入，定速吃滿剖面（沙盒 40）
setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false, AutoDriveMaxSpeed = 40, RightLaneBias = 0 })
drive.fillWorld(-2, 70, -7, 7)
checkTrue(armDrive(), "感知情境啟動")
-- 車頭幾乎對準路線（< 航向誤差減速的 10° 門檻）：本情境量的是「感知檔位」，
-- 不能讓 M3 的誤差收油混進來（armDrive 預設 0.3 rad 會把 40 壓到 35）
setHeading(dveh, 0.05)
dveh._speed = 20
driveReset(dveh)
drive.scanRound()
checkTrue(drive.calls.maxRegSpeed >= 0 and drive.calls.maxRegSpeed <= 40,
    "走廊淨空 command 不超 profile envelope")
checkEq(drive.calls.forceBrake, 0, "走廊淨空：不煞車")
checkEq(#halos, 0, "走廊淨空：無提示")

-- ①a 真正無 physics body 的 HitByCar 小物：小郵箱／輪式垃圾桶已在 shipped
-- 分類順序正確放行，不應產生 hard 或 soft 限速。
drive.putSpriteObject(20, 0, "street_decoration_01_18", false, true, false)
drive.putSpriteObject(22, 1, "trashcontainers_01_0", false, true, false)
drive.scanRound()
driveReset(dveh)
driveTick(dp, dveh)
checkTrue(drive.calls.maxRegSpeed >= 0 and drive.calls.maxRegSpeed <= 40,
    "無 physics body 城市小物不抬高 command")
checkEq(#halos, 0, "無 physics body 的城市小物不顯示繞行提示")
drive.clearCell(20, 0)
drive.clearCell(22, 1)

-- ①b prefix 不能 blanket-ignore：實體 public mailbox 即使有 HitByCar，也先被
-- solidtrans/StopCar 收編。
checkTrue(armDrive(), "實體郵筒對照重臂")
setHeading(dveh, 0.05)
driveReset(dveh)
drive.putSpriteObject(20, 0, "street_decoration_01_8", true, true, true)
drive.scanRound()
checkEq(haloKey(), DKEY.DODGE, "solidtrans＋StopCar public mailbox 仍觸發繞行")
drive.clearCell(20, 0)

checkTrue(armDrive(), "水泥路障對照重臂")
setHeading(dveh, 0.05)
driveReset(dveh)
drive.putSpriteObject(20, 0, "street_decoration_01_28", false, false, true)
drive.scanRound()
checkEq(haloKey(), DKEY.DODGE, "StopCar 水泥路障即使無 collision flag 仍觸發繞行")
