checkTrue(armDrive(), "大型 dumpster 對照重臂")
setHeading(dveh, 0.05)
driveReset(dveh)
drive.putSpriteObject(24, 0, "trashcontainers_01_8", true, false, false)
drive.scanRound()
checkEq(haloKey(), DKEY.DODGE, "沒有 HitByCar 的 solid 大型 dumpster 仍觸發繞行")
drive.clearCell(24, 0)

-- 使用者實景：路邊停放的黑車橫跨三格；另在 a 前放合法近樹，並在距車群
-- 7m 的 c..d 收回段放 l=-1.5 細樹（不擋 baseL、不會被 GROUP_GAP 併群）。
-- 兩者若誤納 minMargin 都會降速；碰撞仍要驗，但不得污染 entry＋hold cap。
local blackParked = drive.putVehicle(20, 0, true)
drive.vehGeo[20 * 100000 - 1] = blackParked
drive.vehGeo[20 * 100000 + 1] = blackParked
drive.putTree(4, 1, "vegetation_trees_01_5")
drive.putTree(27, -2, "vegetation_trees_01_7")
checkTrue(armDrive(), "黑色停車 comfort speed 重臂")
setHeading(dveh, 0.05)
driveReset(dveh)
drive.scanRound()
-- 2026-09-01 去保守（needHalf 1.4→1.2）：近樹縫在新需求下可行——能繞就繞
checkEq(haloKey(), DKEY.DODGE,
    "停車旁近樹：新需求半寬下有縫即繞行（舊契約保守 blocked 已廢）")
driveReset(dveh)
driveTick(dp, dveh)
checkTrue(drive.calls.maxRegSpeed >= 0 and drive.calls.maxRegSpeed <= 25,
    "stopped vehicle dynamic class immediately remains <=25")
drive.vehGeo[20 * 100000 - 1] = nil
drive.clearVehicle(20, 0)
drive.vehGeo[20 * 100000 + 1] = nil
drive.clearCell(4, 1)
drive.clearCell(27, -2)

-- squeeze 檔：主障礙的 normal comfort lane 會在 entry 段撞上左右兩棵細樹；
-- 三條 normal retry 也分別撞左右樹。縮到 need=1.2 後 first-safe 側偏較小，
-- entry 與兩樹距離超過 1.1m，world sweep 才能通過。速度由 clearanceCap 連續縮放。
-- 0904y 貼縫承諾速度閘：以下貼縫 fixture 的車速降到爬行檔（30 km/h 在 8m 內煞不到 cap 5
-- ＝本輪 defer 先減速，那是 (sp3) 的契約，不是這裡要驗的縫語意）
dveh._speed = 4
drive.putSolid(20, 0, "harness_squeeze_main")
drive.putTree(15, -3, "vegetation_trees_01_5")
drive.putTree(15, 2, "vegetation_trees_01_6")
checkTrue(armDrive(), "窄縫 squeeze cap 重臂")
setHeading(dveh, 0.05)
driveReset(dveh)
drive.scanRound()
-- 2026-09-01 物理終審＋使用者裁定「視覺上有空間就該過」：兩樹縫低於舒適
-- 保留但物理半寬掃掠可過 → 擠過去（Dodge），速度由 clearanceCap 連續縮放；
-- 舊契約（0.4m 保留不足即拒絕）已由「物理可過即過、真撞 contact 兜底」取代。
checkEq(haloKey(), DKEY.DODGE,
    "narrow tree gap passes the physical probe and squeezes through")
driveReset(dveh)
driveTick(dp, dveh)
checkTrue(drive.calls.maxRegSpeed > 0 and drive.calls.maxRegSpeed <= DODGE_CAP_TEST,
    "physical squeeze keeps a positive clearance-scaled cap")
checkTrue(MDAD.Drive.isActive(0), "unsafe squeeze keeps the session alive for rescan")
drive.clearCell(20, 0)
drive.clearCell(15, -3)
drive.clearCell(15, 2)

-- 初判無縫降檔複審（2026-09-01 s045 定罪）：左排細桿（格心 r=0，drive.putPost）＋右排實牆
--（規劃 r=0.7、掃掠整格方塊）圍出 3.0m 格心縫——cruise 檔 need 1.2 的可行帶是空集（距牆需
-- 1.9、距桿需 1.2，帶交集不存在），plan 直接判 blocked，候選鏈根本不進；
-- physical 0.9 的帶 [0.1,0.6] 存在且 sweep 兩側都有餘裕可過。修前這裡永遠
-- blocked 停死；修後降檔複審以貼縫檔接住擠過。
-- 0929j：左排原本是樹，樹幹照引擎放到格 +0.6、半徑 0.15 後，這條縫在引擎裡本來就會擦到樹幹（舊模型把樹幹
-- 放在格心、0 半徑，少算南側 0.2m），改用細桿保留這組夾縫情境的幾何。
for wy = -6, -1 do drive.putPost(20, wy, "vegetation_trees_01_5") end
for wy = 2, 6 do drive.putSolid(20, wy, "harness_demote_r" .. wy) end
checkTrue(armDrive(), "降檔複審案重臂")
setHeading(dveh, 0.05)
driveReset(dveh)
drive.scanRound()
checkEq(haloKey(), DKEY.DODGE,
    "cruise plan 初判 blocked 的 3.0m 混材縫由降檔複審（physical）接住")
driveReset(dveh)
driveTick(dp, dveh)
checkTrue(drive.calls.maxRegSpeed > 0 and drive.calls.maxRegSpeed <= DODGE_CAP_TEST,
    "降檔複審 commit 後供油（速度由 clearanceCap 連續縮放，非離散爬行帽）")
-- 2026-09-04 s057 定罪（commit cap 0.5-1.7 km/h 爬到死鎖）：貼縫承諾至少以可執行下限走。
-- 看 session 的 binding cap（同幀 maxRegSpeed 可能保留前一輪較高寫值，不能拿來鎖地板）。
checkTrue(MDAD.Drive.debugSession(0).dodgeSpeedCap >= 5 - 1e-6,
    "貼縫承諾 cap 不低於可執行下限 5 km/h（實得 " .. tostring(MDAD.Drive.debugSession(0).dodgeSpeedCap) .. "）")
-- 淨距 0.05 <0.15：不得抬到第二檔 10
checkTrue(MDAD.Drive.debugSession(0).dodgeSpeedCap < 10 - 1e-6,
    "淨距 0.05 的貼縫不抬到第二檔（實得 " .. tostring(MDAD.Drive.debugSession(0).dodgeSpeedCap) .. "）")
-- (tier) 守護輪同檔：把承諾淨距改成 0.2（同 s019 實測 0.16-0.25）並讓世界成長觸發重驗，
--        cap 至少抬到第二檔 10；淨距 0.05 維持 5。
do
    local st = MDAD.Drive.debugSession(0)
    st.dodgeMargin = 0.2
    st.dodgeGuardHardN = 0 -- 讓 worldGrew 成立 → 守護重掃（掃掠結果照舊，淨距由 sweep 回填）
    driveReset(dveh)
    drive.scanRound()
    -- 守護重掃回填的是實測淨距（0.05）→ 仍第一檔；直接用 trust 輪驗第二檔：
    -- 同 s019 實機：承諾長 0.6m（sinHeading=1）→ clearanceCap(0.2)=1.6 → 舊制地板 5
    st.dodgeGuardFailed, st.dodgeMargin, st.dodgeGuardHardN = false, 0.2, st.sensor.hardN
    st.dodgeCommittedLength = 0.6
    driveReset(dveh)
    drive.scanRound()
    checkTrue(st.dodging == true, "(tier) 承諾仍在")
    checkTrue(st.dodgeClearanceCap < 5, "(tier) fixture：raw clearanceCap <5（實得 " .. tostring(st.dodgeClearanceCap) .. "）")
    checkTrue(st.dodgeSpeedCap >= 10 - 1e-6,
        "(tier) 守護 trust 輪淨距 0.2 → cap 抬到第二檔 10（實得 " .. tostring(st.dodgeSpeedCap) .. "）")
end
-- (pass) 過了 commit 時的最緊點，trust 輪重掃一次、餘裕改用剩餘線的（2026-09-04 s023
--        st184,096-115：margin 0.13 → 5 km/h 地板爬完整條 26m 直線，最緊點只在前 6m）。
--        縫在 x=20；車移到 x=20+halfL+2（車尾過縫 >1m），最緊點記在 s=20。
do
    local st = MDAD.Drive.debugSession(0)
    checkTrue(st.dodging == true, "(pass) 前置：承諾仍在")
    -- 線 c=22（過 c 且前方淨空即釋放），車只能停在 x=21；把縫拆掉模擬「最緊點已在車後」
    -- （最緊點記在 s=16：車尾 18.8 > 16+1）。重掃看的是剩餘線＝淨空。
    for wy = -6, -1 do drive.clearCell(20, wy) end
    for wy = 2, 6 do drive.clearCell(20, wy) end
    dveh._x = 21
    driveReset(dveh)
    drive.scanRound()
    st.dodgeMargin, st.dodgeMarginS, st.dodgeGuardFailed = 0.05, 16, false
    st.dodgeGuardHardN = st.sensor.hardN -- 持平＝trust 輪
    driveReset(dveh)
    drive.scanRound()
    checkTrue(st.dodging == true, "(pass) 承諾仍在（實得 dodging=" .. tostring(st.dodging) .. "）")
    checkTrue(st.dodgeMargin > 0.15,
        "(pass) 過最緊點後 trust 輪重掃：餘裕改用剩餘線（實得 " .. tostring(st.dodgeMargin) .. "）")
    checkTrue(st.dodgeSpeedCap >= 10 - 1e-6,
        "(pass) 餘裕放寬後 cap 至少第二檔 10（實得 " .. tostring(st.dodgeSpeedCap) .. "）")
    -- 最緊點還沒過（記在車前 5m）：不重掃、餘裕照舊（世界同樣淨空，差別只在位置閘）
    st.dodgeMargin, st.dodgeMarginS = 0.05, dveh._x + 5
    st.dodgeClrRetryS0 = st.fstate.ovS0 -- 0928d 補表額度已用：本段只驗位置閘
    driveReset(dveh)
    drive.scanRound()
    checkTrue(st.dodgeMargin < 0.1,
        "(pass) 最緊點在前方：不重掃（實得 " .. tostring(st.dodgeMargin) .. "）")
    -- 還原縫（(pad) 家族用同一道牆）
    for wy = -6, -1 do drive.putPost(20, wy, "vegetation_trees_01_5") end
    for wy = 2, 6 do drive.putSolid(20, wy, "harness_demote_r" .. wy) end
    dveh._x = 0
    driveReset(dveh)
    drive.scanRound()
end
checkTrue(MDAD.Drive.isActive(0), "降檔複審後 session 存活")
-- (pad) 貼縫承諾執行中 contact 圈同源（2026-09-04 s063/s064「只差一點點」）：物理檔承諾中
--       車身離牆 0.07m（<預設 0.15 圈）不得 contact 煞停；真重疊照停。牆 r=0.7 在 (20, 2..6)，
--       車在 x=18（前緣 20.2 才把牆納進前方快照）。
do
    local st = MDAD.Drive.debugSession(0)
    checkTrue(st.dodging and st.dodgeNeed < st.sweepBase - 1e-6, "(pad) 前置：物理檔承諾中")
    dveh._x, dveh._y, dveh._speed = 18, 0.8, 0
    driveReset(dveh)
    drive.scanRound(true)
    driveTick(dp, dveh)
    -- pad −0.1 下 actual 比預設多 0.25（0.15+0.1）：車身真淨距 0.07 → 實得 0.17
    checkTrue(st.actualClearance > 0.1 and st.actualClearance < 0.25,
        "(pad) fixture：車身真淨距 ≈0.07（pad −0.1 讀數 " .. tostring(st.actualClearance) .. "）")
    checkTrue(st.currentBlocked ~= true and st.footprintBlocked ~= true,
        "(pad) 貼縫承諾中離牆 <0.15 不 contact（footprintBlocked=" .. tostring(st.footprintBlocked) .. "）")
    -- 0904r：pad 與物理掃掠同源（−0.1）——牆格心 r0.7 離車身 0.02（pad 0 會 contact）仍不停
    dveh._y = 0.98 -- 車身壓進格心圓 ~0.08（<0.1 名義重疊）：pad 0 會 contact、pad −0.1 不會
    driveReset(dveh)
    drive.scanRound(true)
    driveTick(dp, dveh)
    checkTrue(st.footprintBlocked ~= true,
        "(pad) 物理承諾中名義重疊 <0.1 不 contact（actual=" .. tostring(st.actualClearance) .. "）")
    dveh._y = 1.2 -- 真重疊（pad −0.1 對 r 0.7 格心點：需重疊 >0.1）
    driveReset(dveh)
    drive.scanRound(true)
    driveTick(dp, dveh)
    checkTrue(st.footprintBlocked == true and st.actualClearance <= 0,
        "(pad) 真重疊仍 contact（actual=" .. tostring(st.actualClearance) .. "）")
    -- (pad2) 貼縫 contact 後倒車加長（2026-09-04 s004@0904n：退 3m 再撞同一點三次）：
    --        第一次倒車要退 3+3=6m 才 settle；退 3m 時仍在 unstick。
    dveh._speed = 0
    driveReset(dveh)
    driveTick(dp, dveh)
    nowMs = nowMs + 2501
    driveReset(dveh)
    driveTick(dp, dveh)
    checkEq(MDAD.Drive.hudState(0), "unstick", "(pad2) contact 2.5s 後倒車（實得 " .. tostring(MDAD.Drive.hudState(0)) .. "）")
    checkEq(st.unstickExtraM, 3, "(pad2) 貼縫 contact 第一次倒車額外 3m（實得 " .. tostring(st.unstickExtraM) .. "）")
    local ux, uy = st.unstickX, st.unstickY
    dveh._x, dveh._speed = ux - 3.5, -5
    nowMs = nowMs + 100
    driveReset(dveh)
    driveTick(dp, dveh)
    checkEq(st.mode, "unstick", "(pad2) 退 3.5m 仍在倒車（未 settle；實得 " .. tostring(st.mode) .. "）")
    dveh._x = ux - 6.2
    nowMs = nowMs + 100
    driveReset(dveh)
    driveTick(dp, dveh)
    checkEq(st.mode, "settle", "(pad2) 退 6.2m 才 settle（實得 " .. tostring(st.mode) .. "）")
    dveh._x, dveh._y, dveh._speed = 0, 0, 20
    MDAD.Drive.stop(0, nil)
    checkTrue(armDrive(), "(pad2) 重臂")
end
-- (pad-prea) 2026-09-27 正式服 SemiBox：承諾線 pre-a 段掃掠只以 SWEEP_PHYS_PAD（0.05）驗，執行
--   contact 卻用預設 0.15，完美跟線也會被判接觸。車在 a 之前 contact 圈與掃掠同源：同一個側邊
--   硬物的淨距讀數，pre-a 比 a 之後多 0.1（0.15−0.05）。違規證明：拿掉 pre-a pad＝差 0 紅。
do
    local keepWorld = drive.world
    drive.world = {}
    drive.fillWorld(-10, 170, -20, 20)
    drive.putRoad(-10, 170, -20, 20)
    assert(armDrive())
    setHeading(dveh, 0)
    dveh._speed = 20
    drive.putSolid(30, 0, "prea_commit_obstacle")
    drive.scanRound(true)
    local st = MDAD.Drive.debugSession(0)
    checkTrue(st.dodging and not st.dodgeCrawl and st.lastSNow < st.fstate.offA,
        "(pad-prea) 前置：巡航承諾、車仍在 a 之前（rs " .. tostring(st.lastSNow)
        .. " a " .. tostring(st.fstate.offA) .. "）")
    drive.putSolid(3, -3, "prea_side_object")
    drive.scanRound(true)
    local preA = st.actualClearance
    local keepA = st.fstate.offA
    st.fstate.offA = st.lastSNow - 1
    drive.scanRound(true)
    local postA = st.actualClearance
    st.fstate.offA = keepA
    checkNear(preA - postA, 0.1, 1e-6,
        "(pad-prea) pre-a 的 contact 圈＝掃掠的 0.05（淨距讀數 pre " .. string.format("%.3f", preA)
        .. "、post " .. string.format("%.3f", postA) .. "）")
    MDAD.Drive.stop(0, nil)
    drive.world = keepWorld
    assert(armDrive())
end
-- (ban) 擦過就算過（2026-09-04 s025 st185,813：路口電線桿 contact 一瞬即過、沒倒車，recovery
--       ban（車前 9m 虛擬障礙）留著 → 下一次 replan 全候選 steep → 空路上 blocked → 後方是桿
--       倒不了 → StopStuck）：contact 後車身整個越過命中點且 episodeAttempts=0 → ban 清掉。
do
    local st = MDAD.Drive.debugSession(0)
    -- 車在 1.2、常駐 0，左側 −0.3 的桿在斜切帶內：斜切保持（1004e）會讓規劃器改以 1.2 判擋、從縫物理檔擠過去，
    -- 就沒有本案要的 contact。本案只測 contact 後的 ban 清除：門檻暫時拉到斜切保持不會啟動（另見 scenario1004e）。
    local T = MDAD.Drive.debugTune()
    local keepLat = T.START_GUARD_LAT_M
    T.START_GUARD_LAT_M = 99
    dveh._x, dveh._y, dveh._speed = 18, 1.2, 5
    driveReset(dveh)
    drive.scanRound(true)
    driveTick(dp, dveh)
    checkTrue(st.footprintBlocked == true, "(ban) 前置：contact（實得 " .. tostring(st.footprintBlocked) .. "）")
    checkTrue(st.pushBanL ~= nil and st.banFromRecovery == true,
        "(ban) contact 當輪設下 recovery ban（pushBanL=" .. tostring(st.pushBanL) .. "）")
    checkTrue(st.episodeAttempts == 0, "(ban) 前置：尚未倒車")
    local hitS = st.episodeHitS
    -- 車身越過命中點 halfL+1 以上、離牆 0.8（不再 contact）
    dveh._x, dveh._y = hitS + st.vehicleProfile.halfL + 2, 0.8
    driveReset(dveh)
    drive.scanRound(true)
    driveTick(dp, dveh)
    checkTrue(st.pushBanL == nil and st.banFromRecovery == false,
        "(ban) 沒倒車就越過命中點：ban 清掉（pushBanL=" .. tostring(st.pushBanL) .. "）")
    -- 對照：命中點還在車身內（差 0.5m）不清（投影只准前進：換位重開 session）
    dveh._x, dveh._y, dveh._speed = 0, 0, 20
    MDAD.Drive.stop(0, nil)
    checkTrue(armDrive(), "(ban) 對照重臂")
    st = MDAD.Drive.debugSession(0)
    dveh._x, dveh._y, dveh._speed = 18, 1.2, 5
    driveReset(dveh)
    drive.scanRound(true)
    driveTick(dp, dveh)
    checkTrue(st.pushBanL ~= nil, "(ban) 對照：再 contact 重設 ban")
    dveh._x, dveh._y = hitS + st.vehicleProfile.halfL - 0.5, 0.8
    driveReset(dveh)
    drive.scanRound(true)
    driveTick(dp, dveh)
    checkTrue(st.pushBanL ~= nil, "(ban) 命中點還沒整個越過：ban 保留（pushBanL=" .. tostring(st.pushBanL) .. "）")
    dveh._x, dveh._y, dveh._speed = 0, 0, 20
    MDAD.Drive.stop(0, nil)
    checkTrue(armDrive(), "(ban) 重臂")
    T.START_GUARD_LAT_M = keepLat
end
function drive.scenarioDesignEnvelope()
    local world, frame = drive.world, drive.frameMs(8)
    drive.world = {}
    drive.fillWorld(-10, 170, -20, 20)
    drive.putRoad(-10, 170, -20, 20)
    assert(armDrive())
    setHeading(dveh, 0)
    drive.scanRound(true)
    local st = MDAD.Drive.debugSession(0)
    local ok, _, _, _, a1, b1 = MDAD.Drive.debugSweepFallbacks(0, 25, 45, 60, 90, 2.5, "design")
    assert(ok)
    st.profileEnvelope = 12 -- 同一路線仍可巡航，只是當下姿態／出彎收正要求低速
    local ok2, _, _, _, a2, b2 = MDAD.Drive.debugSweepFallbacks(0, 25, 45, 60, 90, 2.5, "design")
    assert(ok2)
    checkNear(b2 - a2, b1 - a1, 1e-9,
        "(design-envelope) 當下控制帽降12不改短未來繞行的進入段")
    st.fstate.profileSpeedKmh = 12 -- 真正路線物理包絡降低，才改用低速幾何
    local ok3, _, _, _, a3, b3 = MDAD.Drive.debugSweepFallbacks(0, 25, 45, 60, 90, 2.5, "design")
    assert(ok3)
    checkTrue(b3 - a3 < b1 - a1,
        "(design-envelope) 路線本身的物理限速仍約束幾何設計")
    st.fstate.profileSpeedKmh = 0
    local ok4, _, _, _, a4, b4 = MDAD.Drive.debugSweepFallbacks(0, 25, 45, 60, 90, 2.5, "design")
    assert(ok4)
    checkNear(b4 - a4, b3 - a3, 1e-9,
        "(design-envelope) 真物理零速只套爬行設計地板，不誤認成未知而恢復巡航")
    MDAD.Drive.stop(0, nil)
    drive.world = world
    drive.frameMs(frame)
    assert(armDrive())
end
drive.scenarioDesignEnvelope()

function drive.scenarioDeferOwner()
    local world, mode = drive.world, MDAD.HUD.uturnMode
    drive.world = {}
    drive.fillWorld(-10, 170, -20, 20)
    drive.putRoad(-10, 170, -20, 20)
    MDAD.HUD.uturnMode = function() return "fast" end
    assert(armDrive())
    setHeading(dveh, math.pi)
    dveh._speed = 10
    for x = 3, 105, 6 do drive.putSolid(x, 1, "defer_behind_turn") end
    for _ = 1, 3 do drive.scanRound(true) end
    driveReset(dveh)
    driveTick(dp, dveh)
    local st = MDAD.Drive.debugSession(0)
    assert(st.fstate.rotating and not st.currentBlocked)
    checkTrue(drive.calls.forceBrake == 0 and dveh._imp.total > 0,
        "(defer-owner) 車尾方向的長群只延後路線繞行，不得取消淨空調頭的轉向")
    MDAD.Drive.stop(0, nil)
    MDAD.HUD.uturnMode = mode
    drive.world = world
    assert(armDrive())
end
drive.scenarioDeferOwner()

-- (brake-assist) 0925r 硬煞外力輔助：只在已知障礙前、照一般硬煞停不住（v²/2d > NEED）且 40 km/h 以上時，
--   對質心加車頭反向中心力（零力矩），60 km/h 起滿載 0.4×mass×10×(mult/0.8)。可視距離／彎道／恢復等
--   一般煞車理由沒有障礙距離＝不加。違規證明：NEED 改 0＝(brake-assist) 「停得住不加」紅；門檻 999＝施力紅；
--   NEED 退回 6＝「55 km/h、障礙 25m」紅（0929g：弱煞車的車鎖輪只有 4.0–4.3 m/s²）。
function drive.scenarioBrakeAssist()
    assert(armDrive())
    setHeading(dveh, 0)
    local st = MDAD.Drive.debugSession(0)
    local function hit(speed, dist)
        driveReset(dveh)
        dveh._imp.frame, dveh._imp.x, dveh._imp.z, dveh._imp.torqueY = 0, 0, 0, 0
        dveh._speed = speed
        st.brakeImpulseThis = false
        MDAD.Drive.brakeAssist(st, dveh, dist)
        return dveh._imp
    end
    local imp = hit(80, 20) -- 22.2 m/s、20m：需 12.3 m/s²
    local fx, fz = dveh._fwdX, dveh._fwdY
    local mass = st.runtimeMass or 1200
    local mult = math.max(0.1, getGameTime():getMultiplier())
    local want = MDAD.Drive.debugTune().BRAKE_ASSIST_RATIO * mass * 10 * (mult / 0.8)
    checkTrue(imp.frame == 1 and imp.x * fx + imp.z * fz < 0 and math.abs(imp.torqueY) < 1e-9
            and math.abs(math.sqrt(imp.x * imp.x + imp.z * imp.z) - want) < want * 1e-6,
        "(brake-assist) 80 km/h、障礙 20m：車頭反向、零力矩、滿載量級（" .. tostring(imp.x) .. "）")
    imp = hit(80, 60) -- 需 4.1 m/s²：一般硬煞停得住
    checkEq(imp.frame, 0, "(brake-assist) 一般硬煞停得住（80 km/h、60m）：不加外力")
    imp = hit(55, 25) -- 15.3 m/s、25m：需 4.7 m/s²——弱煞車的車鎖輪只有 4.0–4.3（0929g p092）
    checkEq(imp.frame, 1, "(brake-assist) 55 km/h、障礙 25m（需 4.7）：超過鎖輪可靠能力 4.5，加外力")
    imp = hit(30, 2)
    checkEq(imp.frame, 0, "(brake-assist) 40 km/h 以下不施外力")
    imp = hit(80, nil)
    checkEq(imp.frame, 0, "(brake-assist) 沒有障礙距離（可視／彎道等一般煞車）：不加外力")
    -- 0928m 使用者裁定「煞不住就用輔助力」：可視硬煞（連緊急煞車都停不到前緣才觸發）照同一條件加外力，
    --   距離＝硬煞帳前緣扣 halfL＋2。違規證明：visibility 分支拿掉＝這兩行紅。
    st.visHardAhead = nil
    checkEq(MDAD.Drive.emergencyBrakeDist(st, "visibility", false), nil, "(brake-assist) 還沒有可視帳：不加")
    st.visHardAhead = 30
    local halfLv = st.vehicleProfile.halfL
    checkNear(MDAD.Drive.emergencyBrakeDist(st, "visibility", false), 30 - halfLv - 2, 1e-9,
        "(brake-assist) 可視硬煞：距離＝前緣扣 halfL＋2")
    imp = hit(90, MDAD.Drive.emergencyBrakeDist(st, "visibility", false)) -- 25 m/s、約 26m：需 12 m/s²
    checkEq(imp.frame, 1, "(brake-assist) 可視前緣前真的煞不住：加外力")
    st.visHardAhead = nil
    checkEq(MDAD.Drive.emergencyBrakeDist(st, "curve", false), nil, "(brake-assist) 彎道煞車不算緊急")
    -- (curve-assist) 0928m brisk 彎前晚收油：剖面（profileSpeedKmh）已假設中線減速輔助，實速超過就照
    --   超速量×CURVE_ASSIST_GAIN 補、上限 CURVE_ASSIST_MAX；舒適檔（coastAssist 0）不補。
    --   違規證明：拿掉 visAssistForce 的剖面分支＝第一行紅。
    local oldCap, oldPv, oldAssist, oldReady = st.visibilityCap, st.fstate.profileSpeedKmh,
        st.profile.coastAssist, st.sensor and st.sensor.ready
    st.visibilityCap, st.fstate.profileSpeedKmh, st.profile.coastAssist = 90, 40, 2.5
    if st.sensor then st.sensor.ready = true end
    local tune = MDAD.Drive.debugTune()
    MDAD.Drive.visAssistForce(st, 42.5, 1)
    checkNear(st.visAssistDecel, (42.5 - 40 - tune.VIS_ASSIST_TOL_KMH) * tune.CURVE_ASSIST_GAIN, 1e-9,
        "(curve-assist) 超剖面 2.5 km/h：照超速量×增益補（" .. tostring(st.visAssistDecel) .. "）")
    MDAD.Drive.visAssistForce(st, 60, 1)
    checkNear(st.visAssistDecel, tune.CURVE_ASSIST_MAX, 1e-9, "(curve-assist) 上限 CURVE_ASSIST_MAX")
    st.profile.coastAssist = 0
    MDAD.Drive.visAssistForce(st, 60, 1)
    checkEq(st.visAssistDecel, 0, "(curve-assist) 剖面沒假設輔助（舒適檔）：不補")
    -- (curve-assist-low) 2026-10-01 正式服 0.14.0–0.16.0：MAX 急彎（彎帽 12）一秒鎖輪升到每百公里 1.2–1.8——
    --   剖面在 25 km/h 以下的收油包絡仍算進輔助，visAssistForce 卻在 25 以下整個不補，最後 3–4m 只剩斷油、
    --   抵達 18.5–20 km/h 越過 1.5×彎帽。建表算進輔助的段（coastAssistAt>0）25 以下照補；終點停車段（0）
    --   與繞行／堵車等其他帳維持舊下限。違規證明：拿掉剖面分支的下限放寬＝第一行紅。
    local oldAt, oldIdx = st.profile.coastAssistAt, st.fstate.idx
    st.profile.coastAssist, st.fstate.profileSpeedKmh = 2.5, 12
    st.profile.coastAssistAt, st.fstate.idx = { 2.5, 0 }, 1
    MDAD.Drive.visAssistForce(st, 14, 1)
    checkNear(st.visAssistDecel, math.min(tune.CURVE_ASSIST_MAX,
            2.5 + (14 - 12 - tune.VIS_ASSIST_TOL_KMH) * tune.CURVE_ASSIST_GAIN), 1e-9,
        "(curve-assist-low) 彎前 14 km/h 超剖面 12：25 以下照補（" .. tostring(st.visAssistDecel) .. "）")
    -- (curve-ff) 1002c：剖面在收時一超過剖面就先補建表假設的輔助（前饋），比例項只追殘差
    --   （純比例要先落後 TOL＋2.5/增益＝2.25 km/h；E2E SemiTruckLite 進 R≈7 彎一路落後 2–4 km/h）。
    --   1002d：「在收」＝剖面比上一次呼叫低 ASSIST_FALL_KMH 以上；巡航（剖面＝上限）與弧內（平坦）不前饋，
    --   否則 regulator 每越過剖面一點點就脈衝減速。
    --   違規證明：拿掉前饋＝第一條紅；拿掉「在收」條件＝第二、四條紅。
    st.assistPvLast = 13
    MDAD.Drive.visAssistForce(st, 12.5, 1)
    checkNear(st.visAssistDecel, 2.5, 1e-9,
        "(curve-ff) 剖面在收、超剖面 0.5（容忍內）：前饋補建表假設的 2.5（" .. tostring(st.visAssistDecel) .. "）")
    st.assistPvLast = 12
    MDAD.Drive.visAssistForce(st, 12.5, 1)
    checkEq(st.visAssistDecel, 0, "(curve-ff) 剖面平坦（弧內）：超一點點不前饋（" .. tostring(st.visAssistDecel) .. "）")
    st.assistPvLast = 13
    MDAD.Drive.visAssistForce(st, 11.9, 1)
    checkEq(st.visAssistDecel, 0, "(curve-ff) 低於剖面：不補")
    local pmaxK = st.profile.maxSpeedMs * 3.6
    local oldVisCap = st.visibilityCap
    st.fstate.profileSpeedKmh, st.visibilityCap, st.assistPvLast = pmaxK, pmaxK + 50, pmaxK
    MDAD.Drive.visAssistForce(st, pmaxK + 0.5, 1)
    checkEq(st.visAssistDecel, 0, "(curve-ff) 巡航（剖面＝上限）：超一點點不前饋（" .. tostring(st.visAssistDecel) .. "）")
    st.visibilityCap, st.fstate.profileSpeedKmh = oldVisCap, 12
    st.fstate.idx = 2
    MDAD.Drive.visAssistForce(st, 14, 1)
    checkEq(st.visAssistDecel, 0, "(curve-assist-low) 沒算輔助的段：25 以下照舊不補")
    -- (stop-assist) 1002l：終點段建表假設 Follower.STOP_ASSIST（6），上限跟著留 CURVE_ASSIST_HEADROOM＝8；
    --   彎前段（3.5）仍是 5.5。違規證明：拿掉上限放寬＝第一條紅（只剩 5.5）。
    local oldStampSA = st.laneCurveStamp
    st.laneCurveStamp = -1
    st.profile.coastAssistAt, st.fstate.idx = { MDADFollower.STOP_ASSIST }, 1
    st.fstate.profileSpeedKmh, st.assistPvLast = 30, 31
    MDAD.Drive.visAssistForce(st, 40, 1)
    checkNear(st.visAssistDecel, MDADFollower.STOP_ASSIST + tune.CURVE_ASSIST_HEADROOM, 1e-9,
        "(stop-assist) 終點段超剖面 10 km/h：前饋＋比例項，上限 STOP_ASSIST＋餘地（" .. tostring(st.visAssistDecel) .. "）")
    st.assistPvLast = 31
    MDAD.Drive.visAssistForce(st, 30.5, 1)
    checkNear(st.visAssistDecel, MDADFollower.STOP_ASSIST, 1e-9,
        "(stop-assist) 終點段在收、超剖面 0.5：前饋補終點假設的那一份（" .. tostring(st.visAssistDecel) .. "）")
    st.laneCurveStamp, st.fstate.profileSpeedKmh = oldStampSA, 12
    st.profile.coastAssistAt, st.fstate.idx = oldAt, oldIdx
    -- (traffic-assist) 1002q：會車／跟車帽只夾 regulator＝斷油滑行；超過帽照超速量補中線外力（上限 DODGE_ASSIST_MAX）
    --   （正式服 0.17.0 pigpig/clip-02：前車 35m 才出現、帽 43→25、vad 0，只滑到 61）。違規證明：拿掉 traffic 帳＝紅。
    do
        local keep = { st.trafficCapKmh, st.laneCurveStamp, st.fstate.profileSpeedKmh, st.dodgeDeferCap,
            st.zombieLaneCap, st.blockedApproachCap, st.dodging }
        st.trafficCapKmh, st.laneCurveStamp, st.fstate.profileSpeedKmh = 30, -1, 90
        st.dodgeDeferCap, st.zombieLaneCap, st.blockedApproachCap, st.dodging = -1, -1, nil, false
        MDAD.Drive.visAssistForce(st, 36, 1)
        checkTrue(st.visAssistWhy == "traffic"
                and math.abs(st.visAssistDecel - (36 - 30 - tune.VIS_ASSIST_TOL_KMH) * tune.VIS_ASSIST_GAIN) < 1e-9,
            "(traffic-assist) 超過會車帽 6 km/h：照超速量補中線減速（why=" .. tostring(st.visAssistWhy)
            .. " vad=" .. tostring(st.visAssistDecel) .. "）")
        MDAD.Drive.visAssistForce(st, 60, 1)
        checkNear(st.visAssistDecel, tune.DODGE_ASSIST_MAX, 1e-9, "(traffic-assist) 上限 DODGE_ASSIST_MAX")
        st.trafficCapKmh, st.laneCurveStamp, st.fstate.profileSpeedKmh, st.dodgeDeferCap,
            st.zombieLaneCap, st.blockedApproachCap, st.dodging =
            keep[1], keep[2], keep[3], keep[4], keep[5], keep[6], keep[7]
    end
    -- (curve-lane) 1002a：目標由車道包絡（證明線的 lane curve envelope）裁決、比剖面低時，輔助追車道包絡
    --   （正式服 0.17.0 kkbug/clip-03：lce 26 vs 剖面 38、vad 0，38 km/h 衝進 26 km/h 的 90° 折點側滑撞上）。
    --   包絡過期（stamp 不符）或等於車輛極速（直路 κ＝0）不追。
    --   違規證明：拿掉 lane 分支＝第一條紅；拿掉 stamp 條件＝第二條紅；拿掉極速條件＝第三條紅。
    local oldLce, oldStamp = st.laneCurveEnvelope, st.laneCurveStamp
    st.fstate.profileSpeedKmh = 40
    st.laneCurveEnvelope, st.laneCurveStamp, st.assistLceLast = 30, st.sensor.stamp, nil
    MDAD.Drive.visAssistForce(st, 35, 1)
    checkTrue(math.abs(st.visAssistDecel - math.min((35 - 30 - tune.VIS_ASSIST_TOL_KMH) * tune.CURVE_ASSIST_GAIN,
            tune.DODGE_ASSIST_MAX)) < 1e-9 and st.visAssistWhy == "lane",
        "(curve-lane) 車道包絡 30 低於剖面 40：35 km/h 追車道包絡（vad=" .. tostring(st.visAssistDecel)
        .. " vaw=" .. tostring(st.visAssistWhy) .. "）")
    -- (curve-lane-ff) 1002d：車道包絡在收時一超過就補「計畫減速度（laneEnvDecel）－斷油」；平坦不前饋。
    --   違規證明：拿掉車道帳前饋＝第一條紅；拿掉「在收」條件＝第二條紅。
    local oldEnvDecel, oldCoastL = st.laneEnvDecel, st.safeCoast
    st.laneEnvDecel, st.safeCoast, st.assistLceLast = 6.5, 3.0, 31
    MDAD.Drive.visAssistForce(st, 30.5, 1)
    checkTrue(math.abs(st.visAssistDecel - 3.5) < 1e-9 and st.visAssistWhy == "lane",
        "(curve-lane-ff) 車道包絡在收、超 0.5：補計畫 6.5－斷油 3.0（vad=" .. tostring(st.visAssistDecel) .. "）")
    st.assistLceLast = 30
    MDAD.Drive.visAssistForce(st, 30.5, 1)
    checkEq(st.visAssistDecel, 0, "(curve-lane-ff) 車道包絡平坦：超一點點不前饋")
    st.laneEnvDecel, st.safeCoast = oldEnvDecel, oldCoastL
    st.laneCurveStamp = st.sensor.stamp - 1
    MDAD.Drive.visAssistForce(st, 35, 1)
    checkEq(st.visAssistDecel, 0, "(curve-lane) 包絡過期（不是這一輪的證明線）：不追")
    local vmaxL = st.vehicleProfile.maxSpeed
    st.laneCurveStamp, st.laneCurveEnvelope = st.sensor.stamp, vmaxL
    st.visibilityCap, st.fstate.profileSpeedKmh = vmaxL + 50, vmaxL + 50
    MDAD.Drive.visAssistForce(st, vmaxL + 3, 1)
    checkEq(st.visAssistDecel, 0, "(curve-lane) 直路包絡＝車輛極速：不是彎道帳、不追")
    st.laneCurveEnvelope, st.laneCurveStamp = oldLce, oldStamp
    -- (zl-assist) 1002a：殭屍軟縫的縱向配合帽也用同一條中線外力追（正式服 40 段帽低於實速 8 以上、39 段 vad 0；
    --   0.17.0 Aho/clip-19：77 km/h 對帽 12 只滑到 70 就撞進殭屍群）。繞行中不追（帽本來就不套）。
    --   違規證明：拿掉 zombie-lane 分支＝第一條紅；拿掉 not dodging＝第二條紅。
    st.visibilityCap, st.fstate.profileSpeedKmh = 120, 120
    st.zombieLaneCap = 12
    MDAD.Drive.visAssistForce(st, 77, 1)
    checkTrue(math.abs(st.visAssistDecel - tune.DODGE_ASSIST_MAX) < 1e-9 and st.visAssistWhy == "zombie-lane",
        "(zl-assist) 77 km/h 對軟縫帽 12：滿額不鎖輪減速（vad=" .. tostring(st.visAssistDecel)
        .. " vaw=" .. tostring(st.visAssistWhy) .. "）")
    local oldDodging, oldDac = st.dodging, st.dodgeApproachCap
    st.dodging, st.dodgeApproachCap = true, -1 -- 繞行帽不參與比較，只看軟縫帽是否被繞行擋下
    MDAD.Drive.visAssistForce(st, 77, 1)
    checkTrue(st.visAssistWhy ~= "zombie-lane", "(zl-assist) 繞行中：軟縫帽不參與（vaw=" .. tostring(st.visAssistWhy) .. "）")
    st.dodgeApproachCap = oldDac
    st.dodging, st.zombieLaneCap = oldDodging, -1
    st.visibilityCap, st.fstate.profileSpeedKmh, st.profile.coastAssist = oldCap, oldPv, oldAssist
    if st.sensor then st.sensor.ready = oldReady end
    MDAD.Drive.stop(0, nil)
    assert(armDrive())
end
drive.scenarioBrakeAssist()

function drive.scenarioCommitSpeed()
    local world = drive.world
    drive.world = {}
    drive.fillWorld(-10, 170, -20, 20)
    drive.putRoad(-10, 170, -20, 20)
    -- 煞得停、但到縫前減不到 cap：延後並先減速（30m 外、55 km/h）。0929o 起 30 FPS 的掃描額度放大到
    -- 60 FPS 的 92m，縫出口不再被視距截短、線不再是低速線；session 以 20 FPS 以下（100ms：可負擔 47m）
    -- 起算（首輪就是這個幀時，沒有上一輪的可負擔視距要慢慢回縮），重現「出口被截短、線只有 25 km/h」。
    local was = drive.frameMs(100)
    assert(armDrive())
    setHeading(dveh, 0)
    dveh._speed = 55
    drive.putSolid(30, 0, "cruise_commit_speed")
    drive.scanRound(true)
    drive.frameMs(100)
    local st = MDAD.Drive.debugSession(0)
    assert(not st.dodgeCrawl)
    checkTrue(not st.dodging and st.dodgeDeferCap >= 0 and st.dodgeDeferCap < 70,
        "(commit-speed) 巡航分類的低速線也要先減速，不能以55km/h承諾25km/h縫")
    dveh._speed = 20
    drive.scanRound(true)
    drive.frameMs(was)
    checkTrue(st.dodging and st.dodgeDeferCap < 0,
        "(commit-speed) 減到可執行速度後，原候選正常承諾")
    MDAD.Drive.stop(0, nil)
    -- 0925p：連緊急煞車都停不住（20m 外、70 km/h）＝延後只會撞上，掃掠驗過的線當輪承諾
    drive.clearCell(30, 0)
    assert(armDrive())
    setHeading(dveh, 0)
    dveh._speed = 70
    drive.putSolid(20, 0, "cruise_commit_late")
    drive.scanRound(true)
    st = MDAD.Drive.debugSession(0)
    checkTrue(st.dodging and st.dodgeDeferCap < 0,
        "(commit-late) 緊急煞停也停不住：不延後、當輪承諾驗過的繞行線")
    MDAD.Drive.stop(0, nil)
    drive.world = world
    assert(armDrive())
end
drive.scenarioCommitSpeed()

function drive.scenarioBanActualLane()
    local world = drive.world
    drive.world = {}
    drive.fillWorld(-10, 170, -20, 20)
    drive.putRoad(-10, 170, -20, 20)
    assert(armDrive())
    dveh._y, dveh._speed = 1.5, 10
    setHeading(dveh, 0)
    for y = 0, 6 do drive.putSolid(30, y, "ban_future_wall") end
    drive.scanRound(true)
    local st = MDAD.Drive.debugSession(0)
    assert(st.dodging and st.fstate.offA > 0.75 and st.fstate.offL < 0)
    dveh._x = 0.75
    drive.putSolid(3, 2, "ban_actual_contact")
    -- 等新增的近點真的進入**完成**的快照（承諾中不會因為世界一變就重規劃）。
    for _ = 1, 3 do drive.scanRound(true) end
    assert(st.footprintBlocked and st.pushBanL ~= nil)
    -- 真 ban 交給下游規劃器：兩側硬物間只剩負側窄口，未走過的 offL 不得把它封掉。
    local mode, _, _, _, _, lane = MDADCorridor.plan(
        { st.pushBanS, st.pushBanS, st.pushBanS }, { -3, 1.2, st.pushBanL }, 3,
        1.2, 3, 0, { 0.7, 0.7, 0.6 }, 1.5)
    checkTrue(mode == "dodge" and lane < 0,
        "(ban-actual) pre-a撞到正側硬物後，負側未走過的出口仍可被規劃器選用")
    MDAD.Drive.stop(0, nil)
    drive.world = world
    assert(armDrive())
end
drive.scenarioBanActualLane()

-- (gd) 守護的物理複驗通過＝降為物理承諾（2026-09-07 session-008 t=53-61：巡航承諾 margin 1.41，
--      回線段串流載入一根物件 comfort −0.21 → guard 失敗 → guard-probe 物理過 → 舊制沿用 commit 餘裕
--      → 40 km/h 到 d 釋放 → 1.8m 外 blocked → forceBrake → contact）。fixture：單一 solid (20,0)
--      → 巡航承諾 offL −2.25、回線段 x=40 線在 y≈−0.5；樹（r 0）放 (40,−2)＝世界 (40.5,−1.5)：
--      離線 ≈1.0 → comfort 1.1 打槍 −0.1、physical 0.8 過 +0.2。三路：worldGrew 輪／trust 輪的
--      guard-pass／物理也不過（樹放 (40,−1)＝離線 0.0）→ 判死 blocked。
--      違規證明：guard-probe 通過沿用 s.dodgeMargin（拿掉 guardDemote）即紅。
local function scenarioGuardDemote()
    local frameWas = drive.frameMs(8) -- 本案驗回線段守護，先完整掃到線尾。
    for wy = -6, -1 do drive.clearCell(20, wy) end
    for wy = 2, 6 do drive.clearCell(20, wy) end
    drive.putSolid(20, 0, "gd_main")
    local function arm(tag)
        checkTrue(armDrive(), tag .. " 重臂")
        setHeading(dveh, 0.05)
        dveh._speed = 20
        driveReset(dveh)
        drive.scanRound()
        local st = MDAD.Drive.debugSession(0)
        checkTrue(st.dodging == true and st.dodgeCrawl ~= true and st.dodgeNeed > st.vehicleProfile.halfW,
            tag .. " 前置：巡航承諾（dg=" .. tostring(st.dodging) .. " crawl=" .. tostring(st.dodgeCrawl)
            .. " need=" .. tostring(st.dodgeNeed) .. "）")
        return st
    end
    -- ① worldGrew 輪：comfort 失敗 → 物理過 → 降物理承諾
    local st = arm("(gd)")
    local margin0 = st.dodgeMargin
    drive.putPost(40, -2, "gd_exit_tree")
    st.dodgeGuardHardN = -5 -- 讓 worldGrew（hardN > 基準+2）成立
    driveReset(dveh)
    drive.scanRound()
    checkTrue(st.dodging == true and not st.blocked,
        "(gd) 物理複驗通過：承諾續走、不 blocked（dg=" .. tostring(st.dodging) .. " bl=" .. tostring(st.blocked) .. "）")
    checkTrue(st.dodgeCrawl == true, "(gd) 降為物理承諾：dodgeCrawl")
    checkNear(st.dodgeNeed, MDADVehicleProfile.sweepBase(st.vehicleProfile.halfW, "physical"), 1e-9,
        "(gd) dodgeNeed 換成物理檔（contact pad 同源）")
    checkTrue(st.dodgeMargin < 0.5 and st.dodgeMargin < margin0 - 0.5,
        "(gd) 餘裕換成物理淨距（實得 " .. tostring(st.dodgeMargin) .. "，commit 時 " .. tostring(margin0) .. "）")
    checkTrue(st.dodgeMarginS ~= nil and st.dodgeMarginS > 36 and st.dodgeMarginS < 44,
        "(gd) 最緊點＝那根樹的弧長（實得 " .. tostring(st.dodgeMarginS) .. "）")
    checkTrue(st.dodgeSpeedCap > 0 and st.dodgeSpeedCap <= 12,
        "(gd) 守護 cap 走 crawl 地板（實得 " .. tostring(st.dodgeSpeedCap) .. "）")
    -- ①b（Codex lane 反例）：降級後下一個 worldGrew 輪，物理檔守護成功回填的是 [a,c] 窗的
    --     最小淨距（看不到 p4 的樹）→ 舊制餘裕放回 1.1、cap 回 28。記下的回線段最緊點在車過之前
    --     必須保留。放三根遠方硬點觸發 worldGrew（不擋線）。
    drive.putSolid(46, 5, "gd_far_a")
    drive.putSolid(47, 5, "gd_far_b")
    drive.putSolid(48, 5, "gd_far_c")
    driveReset(dveh)
    drive.scanRound()
    checkTrue(st.dodging == true and not st.blocked and st.dodgeCrawl == true,
        "(gd1b) worldGrew 輪物理守護通過：承諾續走仍是物理承諾")
    checkTrue(st.dodgeMargin < 0.5 and st.dodgeMarginS ~= nil and st.dodgeMarginS > 36 and st.dodgeMarginS < 44,
        "(gd1b) 回線段最緊點在後續守護輪保留（餘裕 " .. tostring(st.dodgeMargin) .. " s=" .. tostring(st.dodgeMarginS) .. "）")
    checkTrue(st.dodgeSpeedCap > 0 and st.dodgeSpeedCap <= 12,
        "(gd1b) cap 維持 crawl 地板（實得 " .. tostring(st.dodgeSpeedCap) .. "）")
    drive.clearCell(46, 5); drive.clearCell(47, 5); drive.clearCell(48, 5)
    -- ② trust 輪的 guard-pass：點雲持平、最緊點未知 → 帶餘裕重掃失敗 → 物理過 → 同樣降檔
    drive.clearCell(40, -2)
    st = arm("(gd2)")
    drive.putPost(40, -2, "gd_exit_tree")
    st.dodgeGuardHardN = st.sensor.hardN + 1 -- 持平（+1 不過 worldGrew 門檻）
    st.dodgeMarginS = nil -- 最緊點未知 → trust 輪重掃
    driveReset(dveh)
    drive.scanRound()
    checkTrue(st.dodging == true and not st.blocked and st.dodgeCrawl == true,
        "(gd2) guard-pass 掃不過帶餘裕 → 物理複驗過 → 降物理承諾（dg=" .. tostring(st.dodging)
        .. " bl=" .. tostring(st.blocked) .. " crawl=" .. tostring(st.dodgeCrawl) .. "）")
    -- ③ 物理也不過：樹貼線 → 判死、煞停錨＝命中點
    drive.clearCell(40, -2)
    st = arm("(gd3)")
    drive.putPost(40, -1, "gd_exit_tree_on_line")
    st.dodgeGuardHardN = st.sensor.hardN + 1
    st.dodgeMarginS = nil
    driveReset(dveh)
    drive.scanRound()
    checkTrue(st.blocked == true and st.dodgeGuardFailed == true and st.guardHitS ~= nil,
        "(gd3) 物理複驗也不過：判死（bl=" .. tostring(st.blocked) .. " failed=" .. tostring(st.dodgeGuardFailed)
        .. " hitS=" .. tostring(st.guardHitS) .. "）")
    drive.clearCell(40, -1)
    drive.clearCell(20, 0)
    for wy = -6, -1 do drive.putPost(20, wy, "vegetation_trees_01_5") end
    for wy = 2, 6 do drive.putSolid(20, wy, "harness_demote_r" .. wy) end
    dveh._x, dveh._y, dveh._speed = 0, 0, 20
    MDAD.Drive.stop(0, nil)
    drive.frameMs(frameWas)
    checkTrue(armDrive(), "(gd) 還原重臂")
end
scenarioGuardDemote()
-- (ex) 恢復額度用盡後的 CRAWL 計入停等預算（s058/s059：attempt-limit 每 2.5s 一次、0 km/h
--      100 秒不交還）。predicate：直接把 episodeAttempts 設到上限、車不動，15s 後必須交還。
do
    -- 真實狀態（s058 樣本）：episode 活著（eid=2）、ua=3、dg=true、intent CRAWL、車不動
    local st = MDAD.Drive.debugSession(0)
    -- 審查補刀：後方 hard 時 attempts 永遠 0 也要交還 → 只設 episodeActive，不設次數
    st.episodeActive, st.episodeAttempts, st.episodeId = true, 0, 2
    dveh._speed = 0
    for _ = 1, 8 do
        nowMs = nowMs + 2500
        driveReset(dveh)
        driveTick(dp, dveh)
        if not MDAD.Drive.isActive(0) then break end
    end
    checkTrue(not MDAD.Drive.isActive(0), "(ex) 額度用盡＋CRAWL 不動 20s：交還（不再永遠停等）")
    checkEq(haloKey(), DKEY.STUCK, "(ex) 交還理由 StopStuck（實得 " .. tostring(haloKey()) .. "）")
    -- 0904i：整個 harness 第一次「診斷關著」的 StopStuck 落在這裡
    checkEq(haloKey(drive.infoHaloIndex()), "UI_MinidoracatAutoDrive_TelemetryHint",
        "(ex) 診斷關著：StopStuck 附白字診斷提示（鍵四語有翻譯）")
end
-- (al) 貼縫承諾姿態閘門（2026-09-04 s@166216：倒車後車頭偏 27° 當幀 commit −3.50，前角撞
--      黑車三次）：同一混材縫、車頭偏 30° → 本輪延後（defer align）、不 commit；擺正回 3°
--      → 承諾。
do
    for wy = -6, -1 do drive.putPost(20, wy, "vegetation_trees_01_5") end
    for wy = 2, 6 do drive.putSolid(20, wy, "harness_demote_r" .. wy) end
    checkTrue(armDrive(), "(al) 重臂")
    setHeading(dveh, 0.52)
    driveReset(dveh)
    drive.scanRound()
    local st = MDAD.Drive.debugSession(0)
    checkTrue(st.dodging ~= true, "(al) 車頭偏 30°：貼縫不 commit（dodging=" .. tostring(st.dodging) .. "）")
    checkTrue(st.blocked ~= true, "(al) 延後不是 blocked")
    -- (al-cap) 0928b E2E rc1 0008：延後期間照縫口降速（接近帽＝Drive.alignDeferCap），出口速不低於
    --   MIN_EXEC（停下就擺不正）。違規證明：延後不設接近帽＝紅。
    checkTrue(MDADDynamics.finite(st.dodgeDeferCap) and st.dodgeDeferCap >= MDADDynamics.MIN_EXEC_KMH,
        "(al-cap) 對正延後有縫口接近帽且不低於 MIN_EXEC（cap=" .. tostring(st.dodgeDeferCap) .. "）")
    checkNear(MDAD.Drive.alignDeferCap({ safeBrake = 4, lastSNow = 18, vehicleProfile = { halfL = 2 } }, 20, 5),
        MDADDynamics.MIN_EXEC_KMH, 1e-9, "(al-cap) 已到縫口：承諾帽 5 也只壓到 MIN_EXEC（停下就擺不正）")
    setHeading(dveh, 0.05)
    driveReset(dveh)
    drive.scanRound()
    checkTrue(st.dodging == true, "(al) 擺正後承諾（dodging=" .. tostring(st.dodging) .. "）")
    for wy = -6, -1 do drive.clearCell(20, wy) end
    for wy = 2, 6 do drive.clearCell(20, wy) end
    MDAD.Drive.stop(0, nil)
end
-- (sp3) 貼縫承諾速度閘（2026-09-04 s021/s030：21 km/h 當幀 commit cap 5、margin 0.06-0.11，
--       煞到 5 已吃掉整段進入段 → 橫向落後 0.3-0.4 > margin → contact → 倒車；靜止重 commit
--       同線就過）：同 (al) 縫、40 km/h → 本輪不承諾、套接近帽減速；4 km/h → 承諾。
do
    for wy = -6, -1 do drive.putPost(20, wy, "vegetation_trees_01_5") end
    for wy = 2, 6 do drive.putSolid(20, wy, "harness_demote_r" .. wy) end
    checkTrue(armDrive(), "(sp3) 重臂")
    setHeading(dveh, 0.05)
    dveh._speed = 40
    driveReset(dveh)
    drive.scanRound()
    local st = MDAD.Drive.debugSession(0)
    checkTrue(st.dodging ~= true, "(sp3) 40 km/h 到縫前煞不到 cap：本輪不承諾（dodging=" .. tostring(st.dodging) .. "）")
    checkTrue(st.blocked ~= true, "(sp3) 延後不是 blocked")
    checkTrue(type(st.dodgeDeferCap) == "number" and st.dodgeDeferCap >= 0 and st.dodgeDeferCap < 40,
        "(sp3) 本輪套接近帽（dodgeDeferCap=" .. tostring(st.dodgeDeferCap) .. "）")
    driveReset(dveh)
    driveTick(dp, dveh)
    -- 0928h：接近帽由不鎖輪的減速輔助去追（中線反向外力），連緊急煞車都停不到群起點才一秒鎖輪
    --   （rc6 0068：38 km/h 越過 cap+3 就鎖輪煞到 0，下一輪就承諾了 15 km/h 的繞行）。
    --   違規證明：Drive.deferHardKmh 原樣回接近帽＝鎖輪、下一條紅；輔助不看待承諾帽＝下一條紅。
    checkTrue(drive.calls.forceBrake == 0 and st.lastHardBrakeReason == nil
            and st.visAssistDecel > 0 and dveh._imp.x < 0
            and drive.calls.maxRegSpeed <= st.dodgeDeferCap + 1,
        "(sp3) 已超過待承諾煞停包絡：不鎖輪的減速輔助實際減速，定速也寫到接近帽以下（fb="
        .. tostring(drive.calls.forceBrake) .. " hbr=" .. tostring(st.lastHardBrakeReason)
        .. " vad=" .. tostring(st.visAssistDecel) .. " imp=" .. tostring(dveh._imp.x) .. "）")
    dveh._speed = 90
    driveReset(dveh)
    driveTick(dp, dveh)
    -- 1002a：待承諾接近的硬煞 25 km/h 以上改不鎖輪（同 blocked 接近；正式服 0.17.0 Aho/clip-21 39.5 km/h
    -- 一秒鎖到 0）。違規證明：hardBrake 拿掉 dodge-defer＝紅。
    checkTrue(drive.calls.forceBrake == 0 and st.lastHardBrakeReason == "dodge-defer"
            and math.abs((st.visAssistDecel or 0) - MDAD.Drive.debugTune().TOW_BRAKE_DECEL) < 1e-9
            and dveh._imp.x < 0,
        "(sp3-hard) 90 km/h 連緊急煞車都停不到群起點：不鎖輪的中線外力硬煞（hbr="
        .. tostring(st.lastHardBrakeReason) .. " fb=" .. tostring(drive.calls.forceBrake)
        .. " vad=" .. tostring(st.visAssistDecel) .. "）")
    dveh._speed = 4
    driveReset(dveh)
    drive.scanRound()
    checkTrue(st.dodging == true, "(sp3) 減到 4 km/h 後承諾（dodging=" .. tostring(st.dodging) .. "）")
    checkTrue(st.dodgeDeferCap < 0, "(sp3) 承諾後接近帽清除")
    -- (sp3b) 已貼到縫口（車頭到 b < DODGE_SPEED_DEFER_MIN_M）就不延後：40 km/h 也承諾
    --        （2026-09-04 s@172615：連延兩輪後 b−rs<1 → 全滅 blocked 停等倒車）
    MDAD.Drive.stop(0, nil)
    checkTrue(armDrive(), "(sp3b) 重臂")
    setHeading(dveh, 0.05)
    dveh._x, dveh._speed = 15.5, 40
    driveReset(dveh)
    drive.scanRound()
    st = MDAD.Drive.debugSession(0)
    checkTrue(st.dodging == true, "(sp3b) 縫口 40 km/h：不延後、直接承諾（dodging=" .. tostring(st.dodging) .. "）")
    dveh._x = 0
    dveh._speed = 20
    for wy = -6, -1 do drive.clearCell(20, wy) end
    for wy = 2, 6 do drive.clearCell(20, wy) end
    MDAD.Drive.stop(0, nil)
end
-- (ex2) 同一狀態但車真的在爬（6 km/h，位置每幀前進）：不計預算、20s 內不交還
--       （2026-09-04 s@164561「只嘗試一次就中途停」）。
do
    for wy = -6, -1 do drive.putPost(20, wy, "vegetation_trees_01_5") end
    for wy = 2, 6 do drive.putSolid(20, wy, "harness_demote_r" .. wy) end
    checkTrue(armDrive(), "(ex2) 重臂")
    setHeading(dveh, 0.05)
    driveReset(dveh)
    drive.scanRound()
    checkEq(haloKey(), DKEY.DODGE, "(ex2) 貼縫承諾")
    local st = MDAD.Drive.debugSession(0)
    st.episodeActive, st.episodeAttempts, st.episodeId = true, 0, 3
    st.waitAccumMs = 12000 -- blocked＋倒車已吃掉 12s；6 km/h 爬 10m 真進度要 6s
    dveh._speed = 6
    for i = 1, 8 do
        nowMs = nowMs + 1000
        dveh._x = dveh._x + 1.6 -- 6 km/h
        driveReset(dveh)
        driveTick(dp, dveh)
        if not MDAD.Drive.isActive(0) then break end
    end
    checkTrue(MDAD.Drive.isActive(0), "(ex2) 真的在爬：20s 內不交還")
    for wy = -6, -1 do drive.clearCell(20, wy) end
    for wy = 2, 6 do drive.clearCell(20, wy) end
    MDAD.Drive.stop(0, nil)
end
for wy = -6, -1 do drive.clearCell(20, wy) end
for wy = 2, 6 do drive.clearCell(20, wy) end
-- (ex-go) 1001g：額度用盡後的 GO 也計停等預算（E2E rc44 0007：VanAmbulance 繞行承諾中卡在路肩，intent GO、
--   min-exec 8 km/h、車 0 km/h；attempt-limit 每 3.5 秒一次 softFail 回 follow，5 分鐘不交還）。
--   違規證明：計時條件拿掉 GO＝這條紅（session 一直活著）。
do
    checkTrue(armDrive(), "(ex-go) 重臂（淨空路）")
    setHeading(dveh, 0)
    driveReset(dveh)
    drive.scanRound()
    local st = MDAD.Drive.debugSession(0)
    st.episodeActive, st.episodeAttempts, st.episodeId = true, 3, 4
    dveh._speed = 0
    local seen = {}
    for _ = 1, 10 do
        nowMs = nowMs + 2500
        driveReset(dveh)
        driveTick(dp, dveh)
        local cur = MDAD.Drive.debugSession(0)
        if not cur then break end
        seen[#seen + 1] = tostring(cur.intentShadow)
    end
    checkTrue(not MDAD.Drive.isActive(0), "(ex-go) 額度用盡＋GO 不動 25s：交還（intent " .. table.concat(seen, ",") .. "）")
    checkEq(haloKey(), DKEY.STUCK, "(ex-go) 交還理由 StopStuck（實得 " .. tostring(haloKey()) .. "）")
end
-- (ex-go-rear) 1004g：後方一寸不退時的 GO 也計停等預算（E2E k1004g nightrain：路上 24 台車，改道後車被前後夾住、
--   GO 8 km/h 不動；rear-blocked softFail 不扣倒車額度＝次數永遠 0，舊條件只認「額度用盡」→ 3 分鐘不交還）。
--   違規證明：計時條件拿掉後方探測＝這條紅（session 一直活著）。
function drive.scenarioExGoRear()
    local oldAuto = MDAD.HUD.autoDetour
    MDAD.HUD.autoDetour = function() return false end
    checkTrue(armDrive(), "(ex-go-rear) 重臂（淨空路）")
    dveh._x, dveh._y, dveh._speed = 11, 0, 0
    setHeading(dveh, 0)
    for _, y in ipairs({ -1, 0, 1 }) do drive.putSolid(7, y, "harness_rearwall_" .. y) end -- 車尾後 0.8m＝一寸不退
    driveReset(dveh)
    drive.scanRound()
    local st = MDAD.Drive.debugSession(0)
    st.episodeActive, st.episodeAttempts, st.episodeId = true, 0, 6
    local maxAtt, rears, intents = 0, {}, {}
    for _ = 1, 12 do
        nowMs = nowMs + 2500
        driveReset(dveh)
        driveTick(dp, dveh)
        local cur = MDAD.Drive.debugSession(0)
        if not cur then break end
        if cur.episodeAttempts > maxAtt then maxAtt = cur.episodeAttempts end
        rears[#rears + 1] = tostring(cur.rearStatus)
        intents[#intents + 1] = tostring(cur.intentShadow)
    end
    checkTrue(not MDAD.Drive.isActive(0) and maxAtt == 0,
        "(ex-go-rear) 後方擋死＋GO 不動 30s：倒車額度沒扣也交還（倒車次數 " .. maxAtt .. "、rear "
            .. table.concat(rears, ",") .. "、intent " .. table.concat(intents, ",") .. "）")
    checkEq(haloKey(), DKEY.STUCK, "(ex-go-rear) 交還理由 StopStuck（實得 " .. tostring(haloKey()) .. "）")
    for _, y in ipairs({ -1, 0, 1 }) do drive.clearCell(7, y) end
    dveh._x, dveh._y = 0, 0
    MDAD.HUD.autoDetour = oldAuto
    MDAD.Drive.stop(0, nil)
end
drive.scenarioExGoRear()

-- 對抗式 phase collision：把已烘好的第一個 baseline 點壓到一棵「弧座標不擋線」
-- 的樹上。若碰撞判定被錯包進 a..c 的 inCap，這條會誤 commit。
do
    local realBuild = MDADFollower.buildOffsetLine
    local realSetOffset = MDADFollower.setOffset
    local commits = 0
    MDADFollower.buildOffsetLine = function(profile, s0, a, b, c, d, off, bias, outX, outY)
        local n, lineS0 = realBuild(profile, s0, a, b, c, d, off, bias, outX, outY)
        if n >= 1 then outX[1], outY[1] = 4.5, 1.5 end
        return n, lineS0
    end
    MDADFollower.setOffset = function(...)
        commits = commits + 1
        return realSetOffset(...)
    end
    drive.putSolid(20, 0, "harness_phase_baseline_main")
    drive.putTree(4, 1, "vegetation_trees_01_8")
    checkTrue(armDrive(), "baseline sweep collision 重臂")
    setHeading(dveh, 0.05)
    driveReset(dveh)
    drive.scanRound()
    MDADFollower.buildOffsetLine = realBuild
    MDADFollower.setOffset = realSetOffset
    checkEq(commits, 0, "baseline 實碰撞：不得 commit 繞行剖面")
    checkEq(haloKey(), DKEY.BLOCKED, "baseline 實碰撞：分類 blocked")
    drive.clearCell(20, 0)
    drive.clearCell(4, 1)
end

-- 同一守衛的 exit 負向案例：每條候選烘線的末點都壓到 c 後細樹上。
-- margin 不計 exit，不代表碰撞可以不驗；normal 與 squeeze 都必須拒絕。
do
    local realBuild = MDADFollower.buildOffsetLine
    local realSetOffset = MDADFollower.setOffset
    local commits = 0
    MDADFollower.buildOffsetLine = function(profile, s0, a, b, c, d, off, bias, outX, outY)
        local n, lineS0 = realBuild(profile, s0, a, b, c, d, off, bias, outX, outY)
        if n >= 1 then outX[n], outY[n] = 25.5, -1.5 end
        return n, lineS0
    end
    MDADFollower.setOffset = function(...)
        commits = commits + 1
        return realSetOffset(...)
    end
    drive.putSolid(20, 0, "harness_phase_exit_main")
    drive.putTree(25, -2, "vegetation_trees_01_9")
    checkTrue(armDrive(), "exit sweep collision 重臂")
    setHeading(dveh, 0.05)
    driveReset(dveh)
    drive.scanRound()
    MDADFollower.buildOffsetLine = realBuild
    MDADFollower.setOffset = realSetOffset
    checkEq(commits, 0, "exit 實碰撞：不得 commit 繞行剖面")
    checkEq(haloKey(), DKEY.BLOCKED, "exit 實碰撞：分類 blocked")
    drive.clearCell(20, 0)
    drive.clearCell(25, -2)
end
checkTrue(armDrive(), "一般硬障礙情境重臂")
setHeading(dveh, 0.05)
driveReset(dveh)

-- ② 單格中線障礙 → 繞行：first-safe 是左側 -1.75；same-side refinement
--    最多再外推 0.75m 到 -2.50，取得足夠餘裕後以 24 km/h 通過。
-- 從此案起 harness 主體以 getDebug()=true 跑（刻意，非洩漏）：debug 分支的
-- string.format／串接是使用者實機每輪都走的 production 路徑（固定 debug 啟動），
-- nil 串接會炸整個 tick——離線必須在 debug 開啟下覆蓋；後面 (b)/(d1b) 兩案的
-- log 斷言也依賴它。「關閉＝零成本」契約已由情境二十六獨立驗證。
drive.debug = true
drive.putSolid(20, 0, "harness_barrel")
drive.scanRound()
-- 提示斷言先於 driveReset（reset 會清 halos 帳本）
checkEq(#halos, 1, "繞行開始提示一次（玩家要知道慢下來的原因）")
checkEq(haloKey(), DKEY.DODGE, "繞行提示 Dodge")
checkEq(halos[1] and halos[1].kind, "good", "繞行是綠字（自動處理中，不是要玩家介入）")
drive.scanRound()
checkEq(#halos, 1, "持續繞行期間不重複轟提示（sig 每輪微變、replan 反覆進來也只提示一次）")
driveReset(dveh)
driveTick(dp, dveh)
checkTrue(drive.calls.maxRegSpeed >= 0 and drive.calls.maxRegSpeed < 40,
    "static dodge command obeys dynamic cap")
checkEq(drive.calls.forceBrake, 0, "safe static dodge coasts without forceBrake")
checkTrue(MDAD.Drive.isActive(0), "繞行不結束 session")

-- ③ 五格橫排堵死 → blocked：±5 走廊的可行帶是 ±3.6，兩三格還繞得過（借路肩），
--    y=-2..2 五格（l 記錄 -1.5..2.5）把 lane 全吃光才是真堵死。
--    blocked 先「漸進接近」：障礙群在 15 公尺外時不急煞，以 12 km/h 滑行逼近
--    （近距離掃描的縫隙判定更準）；15 公尺內才煞停等待。
drive.putSolid(20, -6, "harness_wreck_l3") -- 物理終審（probe need≈halfW）時代：
drive.putSolid(20, -5, "harness_wreck_l2") -- 堵死牆必須真堵滿 ±6.5 走廊，任何
drive.putSolid(20, -4, "harness_wreck_l1") -- ≥1.9m 的洞都會被 probe 合法擠過
drive.putSolid(20, -3, "harness_wreck_l0")
drive.putSolid(20, -2, "harness_wreck_a")
drive.putSolid(20, -1, "harness_wreck_b")
drive.putSolid(20, 0, "harness_wreck_m")
drive.putSolid(20, 1, "harness_wreck_c")
drive.putSolid(20, 2, "harness_wreck_d")
drive.putSolid(20, 3, "harness_wreck_r0")
drive.putSolid(20, 4, "harness_wreck_r1")
drive.putSolid(20, 5, "harness_wreck_r2")
drive.putSolid(20, 6, "harness_wreck_r3")
drive.blockedVoicesBefore = drive.voiceCount("blocked")
drive.scanRound()
checkEq(haloKey(), DKEY.BLOCKED, "堵死提示 Blocked")
checkEq(halos[1] and halos[1].kind, "bad", "堵死是紅字（要玩家注意）")
checkEq(drive.voiceCount("blocked") - drive.blockedVoicesBefore, 1, "堵死開口 blocked")
-- 車在 s≈0、障礙群 20：距離 >15 → 接近段（滑行不煞停）
driveReset(dveh)
driveTick(dp, dveh)
checkEq(drive.calls.forceBrake, 0, "障礙還在 15 公尺外：接近段不煞停")
do
    -- 1004e：接近停止線只套包絡（在停止線收到 BLOCK_APPROACH_KMH），不再平壓 20 爬到停止線
    local stB = MDAD.Drive.debugSession(0)
    local env = stB and stB.blockedApproachCap
    local flat = MDAD.Drive.debugTune().BLOCK_APPROACH_KMH
    checkTrue(type(env) == "number" and env > flat,
        "blocked 接近：停止線前 10m 的包絡高於停止線速度（實得 " .. tostring(env) .. "）")
    checkTrue(type(env) == "number" and drive.calls.maxRegSpeed > flat and drive.calls.maxRegSpeed <= env + 1,
        "blocked approach command follows the stop-line envelope, not a flat " .. tostring(flat) .. "（實得 "
        .. tostring(drive.calls.maxRegSpeed) .. " ≤ " .. tostring(env) .. "）")
end
-- 車逼近到 11（距障礙群 <10＝BLOCK_STOP_DIST）→ 煞停等待
dveh._x = 11
driveTick(dp, dveh) -- 投影窗跟上新位置
driveReset(dveh)
driveTick(dp, dveh)
checkTrue(drive.calls.forceBrake > 0, "逼近 15 公尺內：主動煞停")
checkEq(drive.calls.regulatorOn, 0, "煞停時不再供油")
checkTrue(MDAD.Drive.isActive(0), "堵死不結束 session（障礙消失要能自動恢復）")
local halosBefore = #halos
drive.scanRound()
checkEq(#halos, halosBefore, "堵死持續期間不重複轟紅字（只提示一次）")
checkEq(drive.voiceCount("blocked") - drive.blockedVoicesBefore, 1, "堵死語音只開口一次（與紅字同 dedupe）")

-- ④ 清障 → blocked 解除（守護驗證通過、恢復供油）。immutable 承諾**不因
--    clear 提前釋放**——剖面（d≈28.5）走完才回全速（多繞幾公尺比換邊安全；
--    實機車在動、承諾必然走完，「駛過 d 後釋放」由 ⑩c 與紅測試覆蓋）。
drive.clearCell(20, -6)
drive.clearCell(20, -5)
drive.clearCell(20, -4)
drive.clearCell(20, -3)
drive.clearCell(20, -2)
drive.clearCell(20, -1)
drive.clearCell(20, 0)
drive.clearCell(20, 1)
drive.clearCell(20, 2)
drive.clearCell(20, 3)
drive.clearCell(20, 4)
drive.clearCell(20, 5)
drive.clearCell(20, 6)
dveh._x = 8
drive.scanRound()
drive.scanRound() -- 守護驗證連續通過：blocked 解除（單輪抖動自癒的反向）
driveReset(dveh)
driveTick(dp, dveh)
checkEq(dveh._regulator, true, "障礙消失：自動恢復供油")
checkTrue(drive.calls.maxRegSpeed > 0 and drive.calls.maxRegSpeed < 40,
    "immutable commitment retains its computed dynamic cap")
-- 駛過剖面末端（d≈28.5）：**每幀**釋放承諾、繞行帽解除——不依賴 replan
-- （replan 是障礙簽章事件驅動；通過後路面乾淨 sig 不變，釋放若只在 replan
-- 會永遠沒人跑，爬行帽在開闊直路掛死——2026-08-29 圖 4 實測 bug）
dveh._x = 60
driveTick(dp, dveh) -- 投影跟上（40m 路線段長 10m、前向搜索 12 段）
drive.fillWorld(-2, 140, -12, 12)
drive.scanRound()
driveReset(dveh)
driveTick(dp, dveh)
checkTrue(drive.calls.maxRegSpeed >= 0 and drive.calls.maxRegSpeed <= 40,
    "released commitment remains within profile/gate envelope")
-- ⑤ 系列要乾淨旗標＋車回 s≈0：重臂（armDrive 換同構 40m 路線）
checkTrue(armDrive(), "④→⑤ 重臂")
setHeading(dveh, 0.05)
dveh._speed = 20
driveReset(dveh)

-- ⑤／⑤a／⑤b 只量速度檔：殭屍軟縫關掉（假車不會橫向跟線，lane 目標飄走會讓航向誤差減速混進來；
-- 軟縫本身在 ⑤z 測）
MDAD.HUD.zombieDodge = function() return false end

-- ⑤ 殭屍密度減速：1 隻 → 35；4 隻 → 25；8 隻 → 15；沙盒關閉 → 不減速
-- 0907b：檔位速對最近一隻做 approach envelope——殭屍放在 lead（halfL＋ZOMBIE_APPROACH_LEAD_M
-- ≈10m）之內＝檔位速本身；遠處另鎖 envelope 身分（見下）。
drive.putMoving(8, 0, { _class = "IsoZombie" })
drive.scanRound()
driveReset(dveh)
driveTick(dp, dveh)
checkTrue(drive.calls.maxRegSpeed >= 0 and drive.calls.maxRegSpeed <= 35,
    "1 zombie command never exceeds 35")
drive.putMoving(8, -1, { _class = "IsoZombie" })
drive.putMoving(9, 0, { _class = "IsoZombie" })
drive.putMoving(9, 1, { _class = "IsoZombie" })
drive.scanRound()
driveReset(dveh)
driveTick(dp, dveh)
checkTrue(drive.calls.maxRegSpeed >= 0 and drive.calls.maxRegSpeed <= 25,
    "4 zombie command never exceeds 25")
drive.putMoving(10, -1, { _class = "IsoZombie" })
drive.putMoving(10, 0, { _class = "IsoZombie" })
drive.putMoving(10, 1, { _class = "IsoZombie" })
drive.putMoving(11, 0, { _class = "IsoZombie" })
drive.scanRound()
driveReset(dveh)
driveTick(dp, dveh)
checkTrue(drive.calls.maxRegSpeed >= 0 and drive.calls.maxRegSpeed <= 15,
    "8 zombie command never exceeds 15")
do
    local st5 = MDAD.Drive.debugSession(0)
    checkEq(st5.lastSensorCap, 15, "8 隻在 lead 內：sensor cap＝檔位速 15 本身")
    -- 同一群搬到 30m 外：cap＝approachCapKmh(最近殭屍 − rs − halfL − LEAD, 15, 0.5, safeCoast)
    -- ＞15（遠時不壓；減速度用斷油滑行 safeCoast——殭屍檔只夾 regulator、不進 forceBrake，
    -- 用煞車減速度反推會到殭屍前還剩 28 km/h）；違規證明：LEAD 改 999（＝整帶平帽）即紅
    for _, c in ipairs({ { 8, 0 }, { 8, -1 }, { 9, 0 }, { 9, 1 }, { 10, -1 }, { 10, 0 }, { 10, 1 }, { 11, 0 } }) do
        drive.clearCell(c[1], c[2])
        drive.putMoving(c[1] + 22, c[2], { _class = "IsoZombie" })
    end
    drive.scanRound()
    driveReset(dveh)
    driveTick(dp, dveh)
    local zs = st5.sensor.zombieNearS
    checkTrue(type(zs) == "number" and zs > 25 and zs < 32,
        "Sensor 記到最近殭屍弧長 ≈30（實得 " .. tostring(zs) .. "）")
    local decel5 = st5.safeCoast
    if type(decel5) ~= "number" then decel5 = 0 end
    checkTrue(type(st5.safeBrake) == "number" and decel5 < st5.safeBrake * 0.7,
        "envelope 減速度＝safeCoast，嚴格低於煞車基準 safeBrake×0.7（實得 " .. tostring(decel5) .. "）")
    local want5 = MDADDynamics.approachCapKmh(
        zs - st5.lastSNow - st5.vehicleProfile.halfL - MDAD.Drive.debugTune().ZOMBIE_APPROACH_LEAD_M,
        15, 0.5, decel5)
    checkTrue(want5 > 15 + 1, "30m 外的殭屍群：envelope 高於檔位速（實得 " .. tostring(want5) .. "）")
    checkTrue(type(st5.lastSensorCap) == "number" and math.abs(st5.lastSensorCap - want5) < 1e-6,
        "sensor cap＝對最近殭屍的 approach envelope（期望 " .. tostring(want5)
        .. "、實得 " .. tostring(st5.lastSensorCap) .. "）")
    -- 搬回 lead 內供 ⑤a（政策×偏好）沿用 4 隻 → 25 的契約
    for _, c in ipairs({ { 8, 0 }, { 8, -1 }, { 9, 0 }, { 9, 1 }, { 10, -1 }, { 10, 0 }, { 10, 1 }, { 11, 0 } }) do
        drive.clearCell(c[1] + 22, c[2])
    end
    drive.putMoving(8, 0, { _class = "IsoZombie" })
    drive.putMoving(8, -1, { _class = "IsoZombie" })
    drive.putMoving(9, 0, { _class = "IsoZombie" })
    drive.putMoving(9, 1, { _class = "IsoZombie" })
end
setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false,
    AutoDriveMaxSpeed = 40, ZombieAreaSlowdown = false, RightLaneBias = 0 })
drive.scanRound()
driveReset(dveh)
driveTick(dp, dveh)
checkTrue(drive.calls.maxRegSpeed >= 0 and drive.calls.maxRegSpeed <= 40,
    "zombie policy off does not bypass other gate caps")
-- ⑤a 三態政策×玩家偏好（上一段的 boolean false＝舊值遷移：強制全速）。
--     政策/偏好改動後要跨 250ms 刷新窗（scanRound 推 nowMs）才進 session 快取。
setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false,
    AutoDriveMaxSpeed = 40, ZombieAreaSlowdown = 1, RightLaneBias = 0 })
MDAD.Drive.setSlowPref(0, "zombie", false)
drive.scanRound()
driveReset(dveh)
driveTick(dp, dveh)
checkTrue(drive.calls.maxRegSpeed > 0 and drive.calls.maxRegSpeed <= 25,
    "政策強制減速：玩家偏好關掉仍受 25 上限；coast envelope 可更低（實得 "
    .. tostring(drive.calls.maxRegSpeed) .. "）")
setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false,
    AutoDriveMaxSpeed = 40, ZombieAreaSlowdown = 2, RightLaneBias = 0 })
drive.scanRound()
driveReset(dveh)
driveTick(dp, dveh)
checkTrue(drive.calls.maxRegSpeed >= 0 and drive.calls.maxRegSpeed <= 40,
    "player preference off does not bypass other gate caps")
MDAD.Drive.setSlowPref(0, "zombie", true)
drive.scanRound()
driveReset(dveh)
driveTick(dp, dveh)
checkEq(drive.calls.maxRegSpeed, 25, "偏好開回來：減速恢復")
setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false,
    AutoDriveMaxSpeed = 40, ZombieAreaSlowdown = 3, RightLaneBias = 0 })
drive.scanRound()
driveReset(dveh)
driveTick(dp, dveh)
checkTrue(drive.calls.maxRegSpeed >= 0 and drive.calls.maxRegSpeed <= 40,
    "forced zombie full-speed still obeys other gates")
setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false, AutoDriveMaxSpeed = 40, RightLaneBias = 0 })
drive.clearCell(8, 0); drive.clearCell(8, -1)
drive.clearCell(9, 0); drive.clearCell(9, 1)

-- ⑤b 地面屍體減速：獨立訊號（不進 hard/soft、不觸發繞行／煞停），預設政策
--     由玩家決定＋偏好開＝壓 CORPSE_CAP 20；政策強制全速＝直接輾過
drive.putCorpse(8, 0) -- 接近預留距離內才應到達屍體檔位速。
drive.scanRound()
driveReset(dveh)
driveTick(dp, dveh)
checkTrue(drive.calls.maxRegSpeed >= 0 and drive.calls.maxRegSpeed <= 30,
    "corpse command never exceeds 30")
checkEq(drive.calls.forceBrake, 0, "屍體不是障礙：不煞停")
checkEq(#halos, 0, "屍體不觸發繞行／堵住提示")
setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false,
    AutoDriveMaxSpeed = 40, CorpseSlowdown = 3, RightLaneBias = 0 })
drive.scanRound()
driveReset(dveh)
driveTick(dp, dveh)
checkTrue(drive.calls.maxRegSpeed >= 0 and drive.calls.maxRegSpeed <= 40,
    "corpse policy off still obeys other gates")
setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false, AutoDriveMaxSpeed = 40, RightLaneBias = 0 })
drive.clearCell(8, 0)
drive.scanRound()

-- ⑤z 殭屍軟縫（0906c）：零星殭屍＝在路面內緩緩換 lane 穿縫；
--     速率 ≤ 1.0 m/s；目標 lane 對硬障礙不淨空＝不動；選項關＝不動；殭屍散去回常駐 lane。
--     可行帶＝常駐 ±3 ∩ 路面餘裕（本 fixture 無 laneRoom／無路面帶＝±3）。
--     違規證明：拿掉 plan 淨空檢查＝(z3) 紅；拿掉速率上限＝(z1) 首輪 ≤0.3 紅；帶退回 ±1.5＝(z1b) 紅。
do
    MDAD.HUD.zombieDodge = nil -- 選項預設開（⑤ 系列關掉的還原）
    -- 假車不會自己橫移：每輪把 y 擺到目前 laneBias（真車會跟線），否則 PREFER 後的 2.05
    -- 偏移對「留在 y=0 的車」是 2m 橫偏＝RETURN 接手、軟縫被讓位釋放（0907 第一版假紅）
    local function zRound()
        drive.scanRound()
        local s0 = MDAD.Drive.debugSession(0)
        if s0 and s0.fstate and type(s0.fstate.laneBias) == "number" then dveh._y = s0.fstate.laneBias end
    end
    local P = MDADCorridor.ZOMBIE_PREFER -- 0.5：自由段夠寬時離殭屍區間邊多留的距離
    drive.scanRound()
    local st = MDAD.Drive.debugSession(0)
    checkTrue(st ~= nil and st.zombieLane == nil, "(z0) 無殭屍：軟縫未啟動")
    -- (z1) 殭屍在 l=−0.5（格 y=−1）→ 區間 [−2.05, 1.05]；可行帶 ±3 → 右縫 [1.05, 3]，
    --      段夠寬再多留 PREFER → +1.55（離常駐最近的一側）
    drive.putMoving(18, -1, { _class = "IsoZombie" })
    zRound()
    st = MDAD.Drive.debugSession(0)
    checkTrue(st.sensor.zomN == 1, "(z1) Sensor 記到 1 隻殭屍 (s,l)（實得 " .. tostring(st.sensor.zomN) .. "）")
    checkTrue(st.sensor.zomL[1] < 0 and st.sensor.zomL[1] > -1, "(z1) 殭屍橫向 −0.5 左右（實得 " .. tostring(st.sensor.zomL[1]) .. "）")
    local lane1 = st.fstate.laneBias
    checkTrue(st.zombieLane ~= nil and lane1 > 0.2 and lane1 <= MDAD.Drive.softLaneRate(20) * 0.3 + 1e-6,
        "(z1) 首輪往右偏、且不超過速率上限（車速×0.25）×0.3 s（實得 " .. tostring(lane1) .. "）")
    -- (z5) 縱向配合：殭屍 18m 前、側移 1.55m；速率隨車速（0925d 0.15×v、下限 1 m/s）＋LEAD 0.3 s
    --      → 帽遠高於車速 20（值依速率常數而變，只驗「有帽、不綁」）
    checkTrue(type(st.zombieLaneCap) == "number" and st.zombieLaneCap > 20,
        "(z5) 縱向配合帽有值且高於車速 20（殭屍 18m、側移 1.55m；實得 " .. tostring(st.zombieLaneCap) .. "）")
    local prev = lane1
    local rateOk = true
    for _ = 1, 8 do
        zRound()
        st = MDAD.Drive.debugSession(0)
        local lb = st.fstate.laneBias
        if lb - prev > MDAD.Drive.softLaneRate(20) * 0.3 + 1e-6 then rateOk = false end
        prev = lb
    end
    checkTrue(rateOk, "(z1) 之後每輪（300ms）變化 ≤ 速率上限×0.3 s")
    checkTrue(math.abs(prev - (1.05 + P)) < 0.05, "(z1) 收斂到縫邊 1.05＋PREFER（實得 " .. tostring(prev) .. "）")
    checkTrue(st.zombieLaneCap < 0, "(z5) 側移到位：縱向配合帽解除（實得 " .. tostring(st.zombieLaneCap) .. "）")
    -- (z1b) 實機 2026-09-06「完全沒閃」：殭屍**正壓在車道上**（l=0＝常駐 lane）。
    --       舊帶 ±1.5 < R 1.55 → 任何帶內 lane 都在殭屍區間 [−1.55, 1.55] 裡＝nil＝不動；
    --       帶 ±3 → 兩側縫 [−3,−1.55]／[1.55,3] 等距，同 cost 取右 +1.55＋PREFER
    drive.clearCell(18, -1)
    for _ = 1, 8 do zRound() end
    drive.putMoving(18, 0, { _class = "IsoZombie",
        getX = function() return 18.5 end, getY = function() return 0.0 end }) -- l=0 正壓車道
    -- (z5c) 驗「帽低於其他帽就綁住定速」的接線：0925p 速率 0.25×v 後 18m 已來得及，
    -- 這一輪暫用舊速率常數讓帽落在 env 40 之下
    local tn = MDAD.Drive.debugTune()
    local rp, rm = tn.ZOMBIE_LANE_RATE_PER_MPS, tn.ZOMBIE_LANE_RATE_MAX
    tn.ZOMBIE_LANE_RATE_PER_MPS, tn.ZOMBIE_LANE_RATE_MAX = 0.15, 3.5
    zRound()
    st = MDAD.Drive.debugSession(0)
    -- (z5c) 側移 2.05m、殭屍 18m：帽低於其他帽（env 40）→ 本幀綁住定速
    driveReset(dveh)
    driveTick(dp, dveh)
    tn.ZOMBIE_LANE_RATE_PER_MPS, tn.ZOMBIE_LANE_RATE_MAX = rp, rm
    checkTrue(type(st.zombieLaneCap) == "number" and st.zombieLaneCap >= 12 and st.zombieLaneCap < 40
            and drive.calls.maxRegSpeed <= st.zombieLaneCap + 0.5 and st.lastCapReason == "zombie-lane",
        "(z5c) 縱向配合帽綁住定速（帽 " .. tostring(st.zombieLaneCap) .. " reg " .. tostring(drive.calls.maxRegSpeed)
        .. " cap=" .. tostring(st.lastCapReason) .. "）")
    for _ = 1, 11 do zRound() end -- τ 0.6s 指數收斂：12 輪（3.6s）到 98%
    st = MDAD.Drive.debugSession(0)
    checkTrue(st.zombieLane ~= nil and math.abs(st.fstate.laneBias - (1.55 + P)) < 0.08,
        "(z1b) 殭屍正壓車道：偏到縫邊 +1.55＋PREFER（實得 " .. tostring(st.fstate.laneBias) .. "）")
    drive.clearCell(18, 0)
    for _ = 1, 8 do zRound() end
    drive.putMoving(18, -1, { _class = "IsoZombie" })
    for _ = 1, 8 do zRound() end
    st = MDAD.Drive.debugSession(0)
    checkTrue(math.abs(st.fstate.laneBias - (1.05 + P)) < 0.05, "(z1) 回到右縫 1.05＋PREFER 供 (z2)（實得 " .. tostring(st.fstate.laneBias) .. "）")
    -- (z5b) 縫太窄留不下 PREFER 退回貼 R（帶 ±3、殭屍 l=1.2 → 右段 [2.75, 3] 寬 0.25）：右側 2.75
    --       vs 左側 [−3, −0.35]→−0.85（cost 0.72 < 7.6）→ 取左 −0.85（縫窄不犧牲最小閃避）
    do
        local lo2, hi2 = {}, {}
        checkNear(MDADCorridor.softZombieLane({ 10 }, { 1.2 }, 1, 0, 30, 0.9, 0, 0, -3, 3, 1, lo2, hi2), -0.85, 1e-9,
            "(z5b) 段寬 < PREFER 退回貼 R：左段 −0.35−0.5＝−0.85")
        checkNear(MDADCorridor.softZombieLane({ 10 }, { 1.2 }, 1, 0, 30, 0.9, 2.9, 2.9, -3, 3, 1, lo2, hi2), 2.9, 1e-9,
            "(z5b) 常駐 2.9 在右段 [2.75,3] 內：段留不下 PREFER 退回整段，u0 在段內就取 u0（不被推到 3.25）")
    end
    checkEq(haloKey(), nil, "(z1) 殭屍不是障礙：不繞行、不 blocked")
    checkTrue(not st.dodging, "(z1) 沒有 dodge 承諾")
    -- (z2) 殭屍離開 → 回常駐 lane、釋放
    drive.clearCell(18, -1)
    for _ = 1, 12 do zRound() end
    st = MDAD.Drive.debugSession(0)
    checkTrue(math.abs(st.fstate.laneBias) < 0.06 and st.zombieLane == nil,
        "(z2) 殭屍散去：lane 回常駐 0 並釋放（實得 " .. tostring(st.fstate.laneBias) .. "）")
    -- (z3) 右側縫被硬物封住、左側仍可通行：應改選左縫，而不是只否決右側後不動。
    drive.putMoving(18, -1, { _class = "IsoZombie" })
    drive.putSolid(24, 2, "harness_zlane_block")
    drive.putSolid(24, -3, "harness_zlane_other_side")
    zRound()
    st = MDAD.Drive.debugSession(0)
    -- 0925p：無縫時取最不壞 lane（"least"），但只能在兩道硬物之間的連通帶內（不越過硬物）
    checkTrue(st.zombieWhy ~= "gap"
            and math.abs(st.fstate.laneBias) + st.needHalf + MDADCorridor.OBS_HALF <= 2.5 + 1e-6,
        "(z3-wall) 兩側硬物封住殭屍縫：只在硬物之間的帶內偏（實得 " .. tostring(st.fstate.laneBias)
        .. " why " .. tostring(st.zombieWhy) .. "）")
    drive.clearCell(24, -3)
    zRound()
    st = MDAD.Drive.debugSession(0)
    checkTrue(not st.dodging and haloKey() == nil, "(z3) 硬物只擋目標 lane、不擋常駐線：無 dodge")
    for _ = 1, 12 do zRound() end
    checkTrue(st.zombieLane ~= nil and st.fstate.laneBias < -2.4,
        "(z3) 右側有硬物：持續偏到左側淨空縫（實得 " .. tostring(st.fstate.laneBias) .. "）")
    drive.clearCell(24, 2)
    drive.clearCell(18, -1)
    for _ = 1, 16 do zRound() end
    drive.putMoving(18, -1, { _class = "IsoZombie" })
    -- (z3b) 硬物在殭屍視窗外（(44,2)：s 44.5 > 視窗 rs+40，仍在 48m 掃描帶內）：不得否決偏移
    --       （0906e；實機 hardN 70-90 時「整條掃描帶找一根桿子」的 plan 檢查讓目標 lane 永遠被否決）。
    --       之後 replan 以偏移後的 lane 為基準會對這根遠桿子規劃 dodge（同一個 predicate）＝正常接手，
    --       所以只鎖「殭屍先處理：兩輪內 lane 已離開常駐線」，不鎖最終值。
    --       1005 起擋線判定用形狀位置（方塊 l 2.5、面在 2.0）：兩輪後 lane 0.83＋規劃半寬 1.2＝2.03 越過方塊面＝擋線，
    --       replan 當輪就承諾繞行（舊制取樣點 l 2.92 判不擋、沒有承諾）。假車不會開過承諾線，收尾改重開 session
    --       再驗回常駐線（承諾不可變，清掉世界不會讓它自己消失）。
    drive.putSolid(44, 2, "harness_zlane_far")
    zRound()
    zRound()
    st = MDAD.Drive.debugSession(0)
    checkTrue(st.fstate.laneBias > 0.5,
        "(z3b) 視窗外硬物不否決：兩輪內已偏 >0.5（實得 " .. tostring(st.fstate.laneBias) .. "）")
    checkTrue(st.dodging == true,
        "(z3b) 遠桿方塊面在偏移後 lane 的規劃半寬內：replan 承諾繞行接手（實得 " .. tostring(st.dodging) .. "）")
    drive.clearCell(44, 2)
    drive.clearCell(18, -1)
    checkTrue(armDrive(), "(z3b) 重開 session（假車開不過承諾線）")
    for _ = 1, 16 do zRound() end
    st = MDAD.Drive.debugSession(0)
    checkTrue(st.zombieLane == nil and math.abs(st.fstate.laneBias) < 0.06 and not st.dodging,
        "(z3b) 收尾：桿子與殭屍都清掉後 lane 回常駐、無 dodge（實得 " .. tostring(st.fstate.laneBias) .. "）")
    drive.putMoving(18, -1, { _class = "IsoZombie" })
    -- (z4) 選項關：不偏移
    MDAD.HUD.zombieDodge = function() return false end
    zRound()
    st = MDAD.Drive.debugSession(0)
    checkTrue(st.zombieLane == nil and math.abs(st.fstate.laneBias) < 1e-6, "(z4) 閃避殭屍關閉：不偏移")
    MDAD.HUD.zombieDodge = nil
    zRound()
    st = MDAD.Drive.debugSession(0)
    checkTrue(st.zombieLane ~= nil and st.fstate.laneBias > 0.2, "(z4) 選項開回來：下一輪即偏移")
    drive.clearCell(18, -1)
    for _ = 1, 12 do zRound() end
    st = MDAD.Drive.debugSession(0)
    checkTrue(st.zombieLane == nil, "(z) 收尾：軟縫釋放")
    checkTrue(armDrive(), "(z-near) 前向盲區保持情境啟動")
    drive.putMoving(18, -1, { _class = "IsoZombie" })
    for _ = 1, 14 do zRound() end
    st = MDAD.Drive.debugSession(0)
    dveh._x, dveh._y = 16, st.fstate.laneBias - 0.15
    drive.scanRound()
    checkTrue(st.sensor.zomN > 0 and st.zombieLaneCap < 0,
        "(z-safe) 已偏開且只剩0.15m追線誤差：通過常駐線殭屍時不額外壓到12")
    dveh._y = st.fstate.laneBias
    dveh._x = 17
    zRound()
    checkTrue(st.sensor.zomN == 0 and st.zombieLane ~= nil and st.fstate.laneBias > 1.4,
        "(z-near) 殭屍進入Sensor前向盲區：車尾尚未通過，不得回線")
    drive.putMoving(26, 2, { _class = "IsoZombie",
        getY = function() return 2.5 end })
    for _ = 1, 3 do zRound() end
    checkTrue(st.sensor.zomN == 1 and dveh._y + 0.5 >= st.vehicleProfile.halfW
            + MDADCorridor.ZOMBIE_R + MDADCorridor.ZOMBIE_MARGIN,
        "(z-cross) 遠處新殭屍出現：不可為選新縫切回尚在車身旁的舊殭屍")
    dveh._x = 23
    for _ = 1, 3 do zRound() end
    checkTrue(dveh._y < 1.0,
        "(z-cross) 車尾通過舊殭屍後：開始轉入新殭屍的左側縫")
    drive.clearCell(26, 2)
    for _ = 1, 14 do zRound() end
    checkTrue(st.zombieLane == nil and math.abs(st.fstate.laneBias) < 0.06,
        "(z-near) 車尾通過後恢復常駐線")
    drive.clearCell(18, -1)
    -- (zc) 屍體與殭屍共用同一條軟避讓縫（0909b 使用者「屍體盡量像殭屍軟避讓」）：
    --      Sensor 把屍體長軸兩端併進 zomS/zomL，所以選縫、速率上限、硬物否決全部共用。
    --      但屍體不是殭屍——zombieN 不得被污染，殭屍推撞（免質量門檻）也不得被屍體觸發。
    checkTrue(armDrive(), "(zc) 屍體軟縫情境啟動")
    setHeading(dveh, 0)
    drive.putCorpse(18, -1)
    zRound()
    st = MDAD.Drive.debugSession(0)
    checkTrue(st.sensor.corpseN > 0 and st.sensor.zomN == 2 and st.sensor.zombieN == 0,
        "(zc) 屍體以長軸兩端進混合軟避讓點雲、不污染殭屍數（corpseN="
        .. tostring(st.sensor.corpseN) .. " zomN=" .. tostring(st.sensor.zomN)
        .. " zombieN=" .. tostring(st.sensor.zombieN) .. "）")
    for _ = 1, 10 do zRound() end
    st = MDAD.Drive.debugSession(0)
    checkTrue(st.zombieLane ~= nil and st.fstate.laneBias > 0.2,
        "(zc) 屍體照殭屍那條軟縫偏開（實得 " .. tostring(st.fstate.laneBias) .. "）")
    -- 屍體不產生殭屍推撞：1200kg < ASSIST_MASS_MIN，低速對高目標等再久也不得推
    -- （加速輔助 1001i 另有 (acc) 案；這裡只看殭屍推撞，先關掉）
    drive.accWas = MDAD.Drive.debugTune().ACCEL_ASSIST_MPS2
    MDAD.Drive.debugTune().ACCEL_ASSIST_MPS2 = 0
    dveh._speed = 2
    for _ = 1, 4 do zRound() end -- 每輪推進 300ms，遠超 ZOMBIE_PUSH_DELAY_MS
    checkEq(st.lastAssistForce, 0,
        "(zc) 屍體不算殭屍：低於質量門檻的車不得靠屍體拿到脫困推力")
    drive.clearCell(18, -1)
    drive.putMoving(18, -1, { _class = "IsoZombie" })
    for _ = 1, 4 do zRound() end
    checkTrue(st.sensor.zombieN > 0 and st.lastAssistForce > 0,
        "(zc) 反例：換成真殭屍擋車 ≥800ms 才免質量門檻推（zombieN="
        .. tostring(st.sensor.zombieN) .. " force=" .. tostring(st.lastAssistForce) .. "）")
    MDAD.Drive.debugTune().ACCEL_ASSIST_MPS2 = drive.accWas
    drive.clearCell(18, -1)
    -- (zc-wall) 兩側硬物封住＝屍體的軟縫同樣讓位給硬物（與 (z3-wall) 同一道守門）
    checkTrue(armDrive(), "(zc-wall) 屍體軟縫硬物否決情境啟動")
    setHeading(dveh, 0)
    drive.putCorpse(18, -1)
    drive.putSolid(24, 2, "harness_corpse_lane_block")
    drive.putSolid(24, -3, "harness_corpse_lane_other")
    zRound()
    st = MDAD.Drive.debugSession(0)
    -- 0925p：無縫時可取最不壞 lane（least），但只能在兩道硬物之間的連通帶內
    checkTrue(st.sensor.corpseN > 0 and st.zombieWhy ~= "gap"
            and math.abs(st.fstate.laneBias) + st.needHalf + MDADCorridor.OBS_HALF <= 2.5 + 1e-6,
        "(zc-wall) 兩側硬物封住屍體縫：只在硬物之間的帶內偏（lane="
        .. tostring(st.fstate.laneBias) .. " why " .. tostring(st.zombieWhy) .. "）")
    drive.clearCell(24, 2)
    drive.clearCell(24, -3)
    drive.clearCell(18, -1)
    -- (z-jit) 1002t 正式服 0.17.0 clip-02：軟縫可行帶離硬物擋線帶緣讓出 SOFT_HARD_JITTER_M（hardL 取樣柱在格內跳動，
    --   貼帶緣選的 lane 下一輪就落進牆的擋線帶 → 從車旁判堵鎖輪）。違規證明：拿掉讓出量＝紅。
    function drive.zJitAway() -- 主 chunk local 已近 200：包成函式，區塊內 local 另計
        checkTrue(armDrive(), "(z-jit) 情境啟動")
        setHeading(dveh, 0)
        MDAD.HUD.zombieDodge = nil
        local tn = MDAD.Drive.debugTune()
        drive.putSolid(24, -4, "harness_zjit_wall")
        drive.putMoving(18, 0, { _class = "IsoZombie",
            getX = function() return 18.5 end, getY = function() return 0.5 end })
        for _ = 1, 14 do zRound() end
        st = MDAD.Drive.debugSession(0)
        local edge = nil
        for i = 1, st.sensor.hardN do
            if st.sensor.hardL[i] < -2 then
                local r = st.sensor.hardR and st.sensor.hardR[i] or MDADCorridor.OBS_HALF
                local e = st.sensor.hardL[i] + st.needHalf + r
                if edge == nil or e > edge then edge = e end
            end
        end
        checkTrue(edge ~= nil and st.zombieLane ~= nil and st.fstate.laneBias < 0
                and st.fstate.laneBias >= edge + tn.SOFT_HARD_JITTER_M - 0.05,
            "(z-jit) 往牆側閃：lane 離牆的擋線帶緣至少讓出取樣跳動量（lane " .. tostring(st.fstate.laneBias)
            .. "、帶緣 " .. tostring(edge) .. "）")
        -- (z-away) lane 已在牆的擋線帶內（取樣跳動的結果）、車身還在帶外：往遠離牆的方向退不判 hard。
        --   違規證明：拿掉 away 例外＝lane 釘在帶內紅。
        drive.clearCell(24, -4)
        drive.putSolid(24, -3, "harness_zjit_near")
        st.zombieLane, st.fstate.laneBias = -1.3, -1.3
        dveh._y = -0.2
        drive.scanRound()
        st = MDAD.Drive.debugSession(0)
        checkTrue(st.zombieWhy ~= "hard" and st.fstate.laneBias > -1.3 + 0.05,
            "(z-away) 帶內的 lane 往外退：不判 hard（why " .. tostring(st.zombieWhy) .. "、lane "
            .. tostring(st.fstate.laneBias) .. "）")
        drive.clearCell(24, -3)
        drive.clearCell(18, 0)
        for _ = 1, 16 do zRound() end
    end
    drive.zJitAway()
    armDrive() -- 後續樹木情境沿用一個仍活著、位於路線起點的 session。
end

-- ⑤zp 殭屍逐群規劃（0925d；減速政策關＝維持車速閃避）。
--   (zp-side) 貼近到完整閃開來不及：不得為了較便宜的另一側橫越殭屍，只在車身這一側盡量偏。
--   (zp-lean) 下一群緊接在後、換邊量超過可及範圍：這一群改貼向下一群縫的一側（右緣 R），
--             不是整段併成一條往左的大側移（E2E stagger 換邊撞兩隻的解）。
--   違規證明：拿掉可及帶＝(zp-side) 紅；①②順序對調（先併群）＝(zp-lean) 紅。
function drive.scenarioZombiePlan()
    scenario("殭屍逐群規劃：可及帶與貼向下一群縫")
    local oldZ, oldC = MDAD.Drive.getSlowPref(0, "zombie"), MDAD.Drive.getSlowPref(0, "corpse")
    setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false, AutoDriveMaxSpeed = 40,
        RightLaneBias = 0, ZombieAreaSlowdown = MDAD.POLICY_PLAYER, CorpseSlowdown = MDAD.POLICY_PLAYER })
    MDAD.Drive.setSlowPref(0, "zombie", false)
    MDAD.Drive.setSlowPref(0, "corpse", false)
    local function put(x, l)
        drive.putMoving(math.floor(x), math.floor(l), { _class = "IsoZombie",
            getX = function() return x end, getY = function() return l end })
    end
    local function arm(y)
        assert(armDrive())
        setHeading(dveh, 0)
        dveh._speed, dveh._y = 20, y
        drive.scanRound(true)
        drive.scanRound(true)
        return MDAD.Drive.debugSession(0)
    end
    local s = arm(0.5)
    local R = s.vehicleProfile.halfW + MDADCorridor.ZOMBIE_R + MDADCorridor.ZOMBIE_MARGIN
    put(8.5, 0.2) -- 車身（0.5）在牠右側；常駐 0 的成本偏好左縫，但左右都來不及完整閃開
    drive.scanRound(true)
    checkTrue(s.zombieWhy == "gap" and type(s.zombieAvoidLane) == "number"
            and s.zombieAvoidLane >= 0.2 + R - 1e-6,
        "(zp-side) 來不及完整閃開：留在車身右側盡量偏，不橫越殭屍換到左縫（實得 "
        .. tostring(s.zombieAvoidLane) .. "、why " .. tostring(s.zombieWhy) .. "）")
    drive.clearCell(8, 0)
    s = arm(0)
    put(20.5, 0) -- 第一群正壓車道：左右縫等價，同 cost 取右（R＋PREFER）
    put(31.5, 2 * R - 0.2) -- 下一群只留下 R−0.2 以左：換邊 0.7m 在 5.6m 內做不完
    drive.scanRound(true)
    checkTrue(s.zombieWhy == "gap" and type(s.zombieAvoidLane) == "number"
            and math.abs(s.zombieAvoidLane - R) < 0.05,
        "(zp-lean) 下一群緊接：這一群貼右緣 R（再偏 0.2m 過下一群），不併成往左的大側移（實得 "
        .. tostring(s.zombieAvoidLane) .. "、R " .. tostring(R) .. "）")
    drive.clearCell(20, 0)
    drive.clearCell(31, math.floor(2 * R - 0.2))
    -- (zp-return) 軟縫側移領先車身 >2m（車身完全沒跟上）：這是「還在跟」不是偏離路線，
    --   RETURN 不得接手（接手＝放掉閃避、壓到回線速度；E2E crowd 0925h）。違規證明：RETURN
    --   進入改用原始 latDev 即紅。
    s = arm(0)
    put(40.5, 0)
    local maxAway, returned = 0, false
    for _ = 1, 10 do
        driveReset(dveh)
        dveh._x = dveh._x + 1.6667 -- 20 km/h×300ms 真前進；橫向不動
        drive.scanRound(true)
        if s.returnActive then returned = true end
        local away = math.abs(s.fstate.laneBias - dveh._y)
        if away > maxAway then maxAway = away end
    end
    checkTrue(maxAway > 2.0 and not returned and s.zombieLane ~= nil,
        "(zp-return) 閃避 lane 領先車身 " .. string.format("%.2f", maxAway)
        .. "m 仍由軟縫持有、RETURN 不接手（returnActive " .. tostring(returned) .. "）")
    drive.clearCell(40, 0)
    -- (zp-prefer) 0925p 高速多留餘裕：低速 PREFER、110 km/h 起多 EXTRA，中間單調
    checkNear(MDAD.Drive.softPrefer(20), MDADCorridor.ZOMBIE_PREFER, 1e-9, "(zp-prefer) 低速＝PREFER")
    checkTrue(MDAD.Drive.softPrefer(75) > MDAD.Drive.softPrefer(40)
            and MDAD.Drive.softPrefer(110) > MDAD.Drive.softPrefer(75)
            and math.abs(MDAD.Drive.softPrefer(130) - MDAD.Drive.softPrefer(110)) < 1e-9,
        "(zp-prefer) 40→110 km/h 單調加大、之後封頂")
    -- (zp-least) 殭屍蓋滿硬物之間的帶＝無縫：不得停在原 lane 正撞，取帶內離最近殭屍最遠的
    --   lane（why least，不算已處理＝減速開啟時數量減速檔照套）。違規證明：拿掉 softBest 分支即紅。
    -- 兩側硬物把帶收窄到約 ±1.7，殭屍 −1／0.5 的佔位（±R）蓋滿整條帶
    drive.putSolid(15, 3, "zp_least_r"); drive.putSolid(15, -4, "zp_least_l")
    s = arm(0)
    put(15.5, -1); put(15.5, 0.5) -- 最遠點在右帶緣（離 0.5 約 1.1），不是中點
    drive.scanRound(true)
    checkTrue(s.zombieWhy == "least" and math.abs(s.fstate.laneBias) > 0.1,
        "(zp-least) 無縫時往最不壞的 lane 偏（why " .. tostring(s.zombieWhy) .. "、lane "
        .. tostring(s.fstate.laneBias) .. "）")
    drive.clearCell(15, -1); drive.clearCell(15, 0); drive.clearCell(15, 3); drive.clearCell(15, -4)
    -- (zp-least-near) 1004a 正式服 0.18.2 kanazawa clip-08：無縫、整條帶都搆得到時，least 從車身這一側翻到最近
    --   那隻的另一側（0.6 秒後就到）。近威脅的 least 同樣只在車身這一側取。違規證明：least 不限側＝紅。
    drive.putSolid(15, 3, "zp_leastn_r"); drive.putSolid(15, -4, "zp_leastn_l")
    s = arm(0)
    put(12.5, 0.3); put(13.5, -0.9) -- 最近那隻在車身（0）右邊 0.3；帶 ±1.1 的最遠點在右帶緣（越過牠），車身這側只有兩隻之間
    drive.scanRound(true)
    checkTrue(s.zombieWhy == "least" and s.fstate.laneBias < -0.05,
        "(zp-least-near) 近威脅無縫：留在車身這一側取最不壞的 lane，不越過最近那隻（why "
        .. tostring(s.zombieWhy) .. "、lane " .. tostring(s.fstate.laneBias) .. "）")
    drive.clearCell(12, 0); drive.clearCell(13, -1); drive.clearCell(15, 3); drive.clearCell(15, -4)
    -- (zp-cross) 減速開啟（整條帶可選）時的近威脅：常駐 0 的成本偏好左縫，但殭屍 1.5 秒內就到、
    --   車身在牠右側＝先在右側選（E2E p2-on 85 km/h 距 20m 翻邊穿過兩隻）。違規證明：拿掉近威脅
    --   限側即紅。
    MDAD.Drive.setSlowPref(0, "zombie", true)
    s = arm(0.9)
    put(7.5, 0.4)
    drive.scanRound(true)
    checkTrue(s.zombieWhy == "gap" and type(s.zombieAvoidLane) == "number"
            and s.zombieAvoidLane >= 0.4 + R - 1e-6,
        "(zp-cross) 減速開啟也不橫越近處殭屍：選車身右側（實得 " .. tostring(s.zombieAvoidLane)
        .. "、why " .. tostring(s.zombieWhy) .. "）")
    drive.clearCell(7, 0)
    -- (zp-blind) 盲區記憶：殭屍進到車前 2m 內（Sensor 不再收），即使不是保持中的那隻，也不得
    --   當作淨空把 lane 拉回常駐線（E2E p3-off：釋放後拉回 3.0 撞上 l 3.1）。違規證明：不帶盲區點即紅。
    s = arm(0)
    put(4.5, 0.01)
    drive.scanRound(true)
    checkTrue(s.zombieLane ~= nil and s.zomBlindN >= 1,
        "(zp-blind) 將進盲區的殭屍記進盲區記憶（blindN " .. tostring(s.zomBlindN) .. "）")
    driveReset(dveh)
    dveh._x = dveh._x + 3.2 -- 殭屍落到車前 2m 內
    s.zombieAvoidUntilS = nil -- 排除「保持中那隻」的既有路徑
    drive.scanRound(true)
    checkTrue(s.zombieWhy ~= "clear" and s.zombieLane ~= nil,
        "(zp-blind) 盲區內的殭屍仍算威脅：不當淨空釋放（why " .. tostring(s.zombieWhy) .. "）")
    drive.clearCell(4, 0)
    -- (zp-pass) 換邊途中剛好經過常駐 lane 不是「已回線」：殭屍在常駐線左側（目標在右），lane 從左邊
    --   −0.47 往右走、這一步落在常駐 0 附近時不得釋放（0925 零散殭屍 E2E：途經常駐被釋放、laneBias
    --   跳回常駐正對殭屍）。違規證明：settle 條件拿掉 want 檢查即紅。
    s = arm(0)
    put(20.5, -0.6)
    drive.scanRound(true)
    s.zombieLane, s.zombieLaneMs = -0.47, s.zombieLaneMs - 50 -- 左側出發、這一步約前進 0.49（落在常駐 0 附近）
    MDADFollower.setLaneBias(s.fstate, -0.47)
    drive.scanRound(true)
    checkTrue(s.zombieLane ~= nil and s.fstate.laneBias > 0,
        "(zp-pass) 途經常駐 lane 不釋放、繼續往右（lane " .. tostring(s.fstate.laneBias) .. "）")
    drive.clearCell(20, -1)
    MDAD.Drive.setSlowPref(0, "zombie", false)
    MDAD.Drive.setSlowPref(0, "zombie", oldZ)
    MDAD.Drive.setSlowPref(0, "corpse", oldC)
    setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false, AutoDriveMaxSpeed = 40, RightLaneBias = 0 })
    assert(armDrive())
end
drive.scenarioZombiePlan()

-- (zr) 1002c 回線途中閃殭屍：RETURN 持有車道時軟縫讓位、連縱向帽都不算，回線斜穿殭屍（E2E zombie turn 首輪：
--   路邊停車逼出長繞行，進彎前 RETURN 從 −0.1 回 3.5 的線穿過 l 1.9–2.8 的三隻，撞兩隻）。回線帶上有殭屍：
--   不進 RETURN／RETURN 中讓位，軟縫從車身位置接手；常駐線與車身之間的殭屍也算軟縫的威脅（不掃回常駐線穿過牠）。
--   違規證明：returnYieldZombies 恆 false＝(zr-enter) 紅；拿掉 updateReturnSnapshot 的讓位＝(zr-release) 紅；
--   威脅帶改回只看常駐線／車身／目前 lane 三端＝(zr-hold) 紅；拿掉選項閘＝(zr-off) 紅。
function drive.scenarioZombieReturn()
    scenario("回線途中閃殭屍：RETURN 讓位給軟縫")
    local oldDodge = MDAD.HUD.zombieDodge
    MDAD.HUD.zombieDodge = function() return true end
    setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false, AutoDriveMaxSpeed = 40,
        RightLaneBias = 0, ZombieAreaSlowdown = false, CorpseSlowdown = false })
    local function arm(y)
        assert(armDrive())
        setHeading(dveh, 0)
        dveh._speed, dveh._y = 20, y
        drive.scanRound(true)
        drive.scanRound(true)
        return MDAD.Drive.debugSession(0)
    end
    local s = arm(0)
    local R = s.vehicleProfile.halfW + MDADCorridor.ZOMBIE_R + MDADCorridor.ZOMBIE_MARGIN
    local zl, y0 = R + 0.15, 2 * R + 0.3 -- 殭屍離常駐線 0 與車身 y0 都比 R 遠，卻正好在回程路上
    local zx = 8.5 -- 20 km/h 約 1 秒到（近威脅：不橫越牠換邊）
    local function put(x)
        drive.putMoving(math.floor(x), math.floor(zl), { _class = "IsoZombie",
            getX = function() return x end, getY = function() return zl end })
    end
    put(zx)
    drive.scanRound(true)
    drive.scanRound(true)
    checkTrue(s.zombieLane == nil and math.abs(s.fstate.laneBias) < 0.05 and (s.sensor.zomN or 0) == 1,
        "(zr) 前置：殭屍離常駐線 R 以外，車在常駐線不閃（lane " .. tostring(s.fstate.laneBias) .. "）")
    -- (zr-enter) 車被推到 y0：RETURN 進場前看到回線帶上的殭屍＝不進，停在車身交軟縫
    dveh._y = y0
    driveTick(dp, dveh)
    checkTrue(not s.returnActive and math.abs(s.fstate.laneBias - y0) < 0.05 and s.zombieLaneParked ~= nil,
        "(zr-enter) 回線帶上有殭屍：不進 RETURN、停在車身（returnActive " .. tostring(s.returnActive)
        .. "、lane " .. tostring(s.fstate.laneBias) .. "）")
    -- (zr-hold) 軟縫從車身接手：殭屍在常駐線與車身之間也是威脅，lane 留在車身那側、不掃回常駐線
    local minLane, everReturn = 99, false
    for _ = 1, 4 do
        driveReset(dveh)
        dveh._x = dveh._x + 0.8
        drive.scanRound(true)
        if s.returnActive then everReturn = true end
        if s.fstate.laneBias < minLane then minLane = s.fstate.laneBias end
    end
    checkTrue(not everReturn and minLane >= zl + R - 0.05,
        "(zr-hold) 車尾過殭屍前 lane 留在車身那側（最低 " .. string.format("%.2f", minLane) .. " ≥ "
        .. string.format("%.2f", zl + R) .. "、RETURN " .. tostring(everReturn) .. "）")
    drive.clearCell(math.floor(zx), math.floor(zl))
    -- (zr-release) RETURN 進行中殭屍出現在回線帶：結束 RETURN、停在車身交軟縫（不是 stall 那樣交回目標線）
    s = arm(y0)
    for _ = 1, 4 do driveTick(dp, dveh) end
    drive.scanRound(true)
    checkTrue(s.returnActive == true, "(zr-release) 前置：線外 " .. string.format("%.1f", y0) .. "m 進 RETURN")
    local rx = dveh._x + zx
    put(rx)
    drive.scanRound(true)
    drive.scanRound(true)
    checkTrue(not s.returnActive and math.abs(s.fstate.laneBias - y0) < 0.6,
        "(zr-release) 回線帶出現殭屍：RETURN 讓位、lane 留在車身（returnActive " .. tostring(s.returnActive)
        .. "、lane " .. tostring(s.fstate.laneBias) .. "）")
    drive.clearCell(math.floor(rx), math.floor(zl))
    -- (zr-off) 閃避選項關：軟縫不作用（讓位＝直接切回常駐線），照舊 RETURN
    MDAD.HUD.zombieDodge = function() return false end
    s = arm(0)
    put(zx)
    drive.scanRound(true)
    dveh._y = y0
    for _ = 1, 4 do driveTick(dp, dveh) end
    checkTrue(s.returnActive == true, "(zr-off) 閃避選項關：照舊 RETURN（returnActive " .. tostring(s.returnActive) .. "）")
    drive.clearCell(math.floor(zx), math.floor(zl))
    MDAD.HUD.zombieDodge = oldDodge
    setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false, AutoDriveMaxSpeed = 40, RightLaneBias = 0 })
    assert(armDrive())
end
drive.scenarioZombieReturn()

-- (zfar) 1004a 玩家回報「繞道後一直走路邊草地，要到第一次轉彎或殭屍／屍體出現才回到路上」；正式服 0.18.2
--   GGGMAMEER clip-22：殭屍走了、軟縫回常駐線的側移檢查看整個軟縫視窗（車速×4.5s，80 km/h＝100m），遠處
--   常駐線旁一根硬物就判 hard，lane 停在偏移處 2 秒、再停 10 秒；車速降下來（彎道、殭屍／屍體減速）視窗縮到
--   40m 才放行。現制只驗側移真的會掃過的那段（Drive.softShiftEndS，至少 SOFT_LOOKAHEAD_M）。
--   (zfar-far)  80 km/h、lane 停在常駐線外 y0，側移路上 60m 外有樹（不擋常駐線、不擋 y0）：回到常駐線。
--   (zfar-near) 同一棵樹在 15m（側移範圍內）：照舊 hard、留在 y0（1002t「側移不得穿過側邊硬物」）。
--   違規證明：拿掉 sShift 上限＝(zfar-far) 紅；拿掉側移硬物檢查＝(zfar-near) 紅。
function drive.scenarioZombieFarHard()
    scenario("軟縫回常駐線：只驗側移掃過的那段，遠處硬物不把 lane 留在偏移處")
    local oldDodge = MDAD.HUD.zombieDodge
    MDAD.HUD.zombieDodge = function() return true end
    setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false, AutoDriveMaxSpeed = 120,
        RightLaneBias = 0, ZombieAreaSlowdown = false, CorpseSlowdown = false })
    local wasMs = drive.frameMs(10)
    local function run(treeAhead)
        drive.fillWorld(-10, 200, -8, 8)
        assert(armDrive())
        setHeading(dveh, 0)
        dveh._speed, dveh._y = 80, 0
        drive.scanRound(true)
        drive.scanRound(true)
        local s = MDAD.Drive.debugSession(0)
        local tr = 0.15 -- 樹幹半徑（0929j：格 +0.6、r 0.15）
        -- 樹在常駐線右側、離常駐線 0 比擋線帶遠（不觸發繞行）；(s,l) 記取樣柱，先掃兩輪量實際 l 再擺 y0
        drive.putTree(math.floor(dveh._x + treeAhead), math.floor(s.needHalf + tr) + 1, "harness_zfar_tree")
        drive.scanRound(true)
        drive.scanRound(true)
        local tl = nil
        for i = 1, s.sensor.hardN do
            if s.sensor.hardS[i] > s.lastSNow + treeAhead - 3 then tl = s.sensor.hardL[i] end
        end
        local y0 = (tl or 3) + s.needHalf + tr + 0.4 -- 樹在 0 與 y0 之間、兩邊都不擋
        -- 前置：軟縫停在常駐線外 y0（RETURN 讓位停放／殭屍閃避後的狀態；怎麼來的不是本案主題）
        s.zombieLane, s.zombieLaneParked, s.fstate.laneBias = y0, nil, y0
        dveh._y = y0
        local why, lane = nil, y0
        for _ = 1, 10 do
            drive.scanRound(true)
            if s.zombieWhy == "hard" then why = "hard" end
            lane = s.fstate.laneBias
            dveh._y = lane
        end
        return s, y0, lane, why, tl
    end
    local s, y0, lane, why, tl = run(60)
    checkTrue(type(tl) == "number" and math.abs(tl) >= s.needHalf + 0.15 and math.abs(y0 - tl) >= s.needHalf + 0.15
            and tl > 0 and tl < y0,
        "(zfar) 前置：樹在側移路上、不擋常駐線也不擋 y0（l " .. tostring(tl) .. "、y0 " .. tostring(y0) .. "）")
    checkTrue(math.abs(lane) < 0.06 and s.zombieLane == nil and why == nil and not s.dodging,
        "(zfar-far) 80 km/h、60m 外的樹不在側移段：lane 回常駐線（lane " .. tostring(lane) .. "、why "
        .. tostring(why) .. "、dodging " .. tostring(s.dodging) .. "）")
    s, y0, lane, why = run(15)
    checkTrue(why == "hard" and math.abs(lane - y0) < 0.05,
        "(zfar-near) 15m 的樹在側移段內：照舊 hard、lane 留在 y0（lane " .. tostring(lane) .. "、why "
        .. tostring(why) .. "）")
    MDAD.Drive.stop(0, nil)
    MDAD.HUD.zombieDodge = oldDodge
    drive.frameMs(wasMs)
    drive.fillWorld(-2, 70, -7, 7)
    setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false, AutoDriveMaxSpeed = 40, RightLaneBias = 0 })
    assert(armDrive())
end
drive.scenarioZombieFarHard()

-- (soft) 1005 動物與車外的其他玩家：併入殭屍軟縫選縫（大型動物與玩家多 SOFT_COMFORT_M），閃不開就以接近包絡
--   停在前方等；動物等 ANIMAL_WAIT_MS 後以 ≤ANIMAL_CRAWL_KMH 爬過、玩家等到停等預算以專屬理由交還；殭屍軟縫在
--   keep 版帶寬沒縫時改在物理 laneRoom 內貼路緣找（fstate.laneKeep＝0，釋放還原）。fixture 擺正壓車道。
--   (soft-a) 大型動物有空間：閃開（佔位含舒適餘裕）、不停不減速
--   (soft-b) 沒空間：接近包絡收速、停在前方等（WAIT）；到期前不動、到期後 CRAWL ≤4 km/h（不被 min-exec 抬）
--   (soft-c) 小動物：AnimalDodge＝大型時不閃不停、＝所有時閃；AnimalSlowdown＝關閉時沒空間也不停
--   (soft-d) 其他玩家擋路沒空間：停等、不倒車，停等預算 WAIT_TIMEOUT_MS 到期以 PlayerBlockStop 交還
--   (soft-e) 殭屍正壓車道、keep 版帶無縫、只剩貼路緣有縫：選 keep 0 的 lane、laneKeep＝0 與 control 一致、釋放還原；
--            keep 版有縫時不動 keep
function drive.scenarioSoftAnimals()
    scenario("動物與玩家：軟縫閃避、閃不開停等、動物爬過、玩家交還、殭屍貼路緣")
    local T = MDAD.Drive.debugTune()
    local oldZ, oldA = MDAD.HUD.zombieDodge, MDAD.HUD.animalDodge
    local aLvl = 2
    MDAD.HUD.zombieDodge = function() return true end
    MDAD.HUD.animalDodge = function() return aLvl end
    local function sandbox(slow)
        setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false, AutoDriveMaxSpeed = 40,
            RightLaneBias = 0, ZombieAreaSlowdown = false, CorpseSlowdown = false, AnimalSlowdown = slow })
    end
    local function arm()
        drive.fillWorld(-10, 160, -9, 9)
        assert(armDrive())
        setHeading(dveh, 0)
        dveh._speed, dveh._y = 20, 0
        drive.scanRound(true)
        drive.scanRound(true)
        return MDAD.Drive.debugSession(0)
    end
    local function putAnimal(x, l, kg)
        drive.putMoving(math.floor(x), math.floor(l), { _class = "IsoAnimal", _isa = { IsoPlayer = true },
            getX = function() return x end, getY = function() return l end,
            isDead = function() return false end, getVehicle = function() return nil end,
            isHeld = function() return false end,
            getData = function() return { getWeight = function() return kg end } end })
    end
    local function putPlayer(x, l)
        drive.putMoving(math.floor(x), math.floor(l), { _class = "IsoPlayer",
            getX = function() return x end, getY = function() return l end,
            isDead = function() return false end, getVehicle = function() return nil end })
    end
    local function walls(x) drive.putSolid(x, 3, "soft_wall_r"); drive.putSolid(x, -4, "soft_wall_l") end
    -- 停在目標前：車頭到目標不足 SOFT_STOP_GAP_M，車停住
    local function parkBefore(s, x)
        dveh._x, dveh._speed = x - s.vehicleProfile.halfL - T.SOFT_STOP_GAP_M + 0.2, 0
        driveReset(dveh)
        drive.scanRound(true)
        driveReset(dveh)
        driveTick(dp, dveh)
    end

    -- (soft-a)
    sandbox(2); aLvl = 2
    local s = arm()
    local R = s.vehicleProfile.halfW + MDADCorridor.ZOMBIE_R + MDADCorridor.ZOMBIE_MARGIN
    local base = s.desiredTarget
    putAnimal(30.5, 0.2, 300)
    drive.scanRound(true)
    checkTrue(s.zombieWhy == "gap" and s.zombieLane ~= nil and type(s.zombieWant) == "number"
            and math.abs(s.zombieWant - 0.2) >= R + T.SOFT_COMFORT_M - 1e-6,
        "(soft-a) 大型動物有空間：閃開且佔位含舒適餘裕（want " .. tostring(s.zombieWant) .. "、R " .. tostring(R) .. "）")
    local held, slowed = false, false
    for _ = 1, 4 do
        driveReset(dveh)
        dveh._x, dveh._y = dveh._x + 1.6667, s.fstate.laneBias
        drive.scanRound(true)
        if s.softHoldKind ~= nil or s.followHold or s.softStopKind ~= nil then held = true end
        if s.desiredTarget < base - 1e-6 then slowed = true end
    end
    checkTrue(not held and not slowed,
        "(soft-a) 閃得開：不停等、不減速（held " .. tostring(held) .. "、slowed " .. tostring(slowed) .. "）")

    -- (soft-b)
    s = arm()
    walls(20)
    putAnimal(20.5, 0.1, 300)
    drive.scanRound(true)
    checkTrue(s.softStopKind == "animal" and s.zombieWhy ~= "gap" and s.lastSensorReason == "animal-stop"
            and s.softStopCapKmh >= 0 and s.softStopCapKmh < base,
        "(soft-b) 沒空間：停等目標＝動物、接近包絡在收（why " .. tostring(s.zombieWhy) .. "、cap "
        .. tostring(s.softStopCapKmh) .. "、reason " .. tostring(s.lastSensorReason) .. "）")
    parkBefore(s, 20.5)
    checkTrue(s.softHoldKind == "animal" and s.followHold == true and s.intentShadow == "WAIT"
            and s.lastSensorReason == "animal-stop" and s.softStopCapKmh == 0,
        "(soft-b) 停在動物前等（intent " .. tostring(s.intentShadow) .. "、reason " .. tostring(s.lastSensorReason) .. "）")
    drive.stallFrames(T.ANIMAL_WAIT_MS - 1500)
    driveReset(dveh)
    driveTick(dp, dveh)
    checkTrue(not s.softCrawl and s.followHold == true and s.softHoldMs > 1000 and s.softHoldMs < T.ANIMAL_WAIT_MS,
        "(soft-b) 等待未到期：仍停（holdMs " .. tostring(s.softHoldMs) .. "）")
    drive.stallFrames(2500)
    driveReset(dveh)
    driveTick(dp, dveh)
    checkTrue(s.softCrawl == true and s.intentShadow == "CRAWL" and s.lastCapReason == "animal-crawl"
            and s.softStopCapKmh > 0 and s.softStopCapKmh <= 4 and not s.followHold and MDAD.Drive.isActive(0),
        "(soft-b) 等待到期：≤4 km/h 爬過（intent " .. tostring(s.intentShadow) .. "、reason "
        .. tostring(s.lastCapReason) .. "、cap " .. tostring(s.softStopCapKmh) .. "）")
    drive.clearCell(20, 0)
    drive.scanRound(true)
    checkTrue(s.softHoldKind == nil and not s.softCrawl and s.softHoldMs == 0,
        "(soft-b) 動物離開：停等狀態清掉（kind " .. tostring(s.softHoldKind) .. "）")

    -- (soft-c)
    s = arm()
    putAnimal(30.5, 0.2, 3)
    drive.scanRound(true)
    checkTrue(s.zombieLane == nil and s.zombieWhy == "clear" and s.softStopKind == nil,
        "(soft-c) AnimalDodge＝大型：小動物不閃不停（why " .. tostring(s.zombieWhy) .. "）")
    aLvl = 3
    drive.scanRound(true)
    checkTrue(s.zombieWhy == "gap" and s.zombieLane ~= nil,
        "(soft-c) AnimalDodge＝所有：小動物也閃（why " .. tostring(s.zombieWhy) .. "）")
    aLvl = 2
    sandbox(1)
    s = arm()
    walls(20)
    putAnimal(20.5, 0.1, 300)
    parkBefore(s, 20.5)
    checkTrue(s.softStopKind == nil and s.softHoldKind == nil and not s.followHold
            and s.lastSensorReason ~= "animal-stop",
        "(soft-c) AnimalSlowdown＝關閉：沒空間也不停（reason " .. tostring(s.lastSensorReason) .. "）")

    -- (soft-d)
    sandbox(2); aLvl = 1 -- 動物閃避關閉不影響玩家
    MDAD.HUD.zombieDodge = function() return false end -- 殭屍閃避關閉也不影響玩家
    s = arm()
    putPlayer(30.5, 0.2)
    drive.scanRound(true)
    checkTrue(s.zombieWhy == "gap" and type(s.zombieWant) == "number"
            and math.abs(s.zombieWant - 0.2) >= R + T.SOFT_COMFORT_M - 1e-6 and s.softStopKind == nil,
        "(soft-d) 玩家有空間：永遠參與閃避（AnimalDodge／ZombieDodge 關也一樣）、含舒適餘裕、不停（want "
        .. tostring(s.zombieWant) .. "）")
    MDAD.HUD.zombieDodge = function() return true end
    s = arm()
    walls(20)
    putPlayer(20.5, 0.1)
    parkBefore(s, 20.5)
    checkTrue(s.softHoldKind == "player" and s.followHold == true and s.lastSensorReason == "player-stop",
        "(soft-d) 玩家擋路沒空間：停等（kind " .. tostring(s.softHoldKind) .. "、reason " .. tostring(s.lastSensorReason) .. "）")
    clearList(halos)
    local waited, unstuck, stopAt = 0, false, nil
    while waited <= T.WAIT_TIMEOUT_MS + 3000 and MDAD.Drive.isActive(0) do
        nowMs = nowMs + 250
        driveTick(dp, dveh)
        waited = waited + 250
        if s.mode == "unstick" or s.recoverWhy ~= nil or s.softCrawl then unstuck = true end
    end
    if not MDAD.Drive.isActive(0) then stopAt = waited end
    local playerKey = false
    for _, h in ipairs(halos) do
        if noteReason(h.text) == "UI_MinidoracatAutoDrive_PlayerBlockStop" then playerKey = true end
    end
    checkTrue(stopAt ~= nil and stopAt >= T.WAIT_TIMEOUT_MS - 1500 and playerKey and not unstuck,
        "(soft-d) 停等預算到期以 PlayerBlockStop 交還、期間不倒車不爬（停在 " .. tostring(stopAt) .. "ms）")

    -- (soft-e)
    sandbox(2); aLvl = 2
    local function roomed(room)
        local st = arm()
        local p = st.profile
        p.laneRoomR, p.laneRoomL = {}, {}
        for i = 1, p.n do p.laneRoomR[i], p.laneRoomL[i] = room, room end
        return st
    end
    local room = 2.6
    s = roomed(room)
    local a = 2.05 - R -- 兩隻 ±a 的佔位聯集＝[−2.05, 2.05]：蓋滿 keep 版帶 ±(room−0.6)，貼路緣各剩一段
    drive.putMoving(30, math.floor(a), { _class = "IsoZombie", getX = function() return 30.5 end, getY = function() return a end })
    drive.putMoving(31, math.floor(-a), { _class = "IsoZombie", getX = function() return 30.6 end, getY = function() return -a end })
    drive.scanRound(true)
    local want = s.zombieWant
    checkTrue(s.zombieWhy == "gap" and s.zombieKeep0 == true and type(want) == "number"
            and math.abs(want) > room - MDADFollower.LANE_BIAS_KEEP + 1e-6 and math.abs(want) <= room + 1e-6,
        "(soft-e) keep 版無縫：在物理 laneRoom 內貼路緣找到縫（why " .. tostring(s.zombieWhy) .. "、want "
        .. tostring(want) .. "）")
    local idx = s.fstate.idx
    checkTrue(s.fstate.laneKeep == 0 and MDAD.Drive.laneKeepOf(s) == 0
            and math.abs(MDADFollower.laneBiasAt(s.profile, want, idx, s.lastSNow, s.fstate.laneKeep) - want) < 1e-6,
        "(soft-e) control／期望線同用 keep 0：want 不被夾回 keep 版帶（laneKeep " .. tostring(s.fstate.laneKeep) .. "）")
    drive.clearCell(30, math.floor(a)); drive.clearCell(31, math.floor(-a))
    for _ = 1, 20 do
        if s.zombieLane == nil then break end
        driveReset(dveh)
        dveh._y = s.fstate.laneBias
        drive.scanRound(true)
    end
    checkTrue(s.zombieLane == nil and s.zombieKeep0 == false and s.fstate.laneKeep == nil,
        "(soft-e) 釋放後還原 keep（laneKeep " .. tostring(s.fstate.laneKeep) .. "）")
    s = roomed(room)
    drive.putMoving(30, 0, { _class = "IsoZombie", getX = function() return 30.5 end, getY = function() return 0.05 end })
    drive.scanRound(true)
    checkTrue(s.zombieWhy == "gap" and s.zombieKeep0 == false and s.fstate.laneKeep == nil,
        "(soft-e) keep 版有縫：不改 keep（keep0 " .. tostring(s.zombieKeep0) .. "）")

    MDAD.Drive.stop(0, nil)
    MDAD.HUD.zombieDodge, MDAD.HUD.animalDodge = oldZ, oldA
    drive.fillWorld(-2, 70, -7, 7)
    setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false, AutoDriveMaxSpeed = 40, RightLaneBias = 0 })
    assert(armDrive())
end
drive.scenarioSoftAnimals()

-- (soft2) 1005 整合審查補刀：停等判讀要看仲裁後「到目標時車身在哪」、閃殭屍選項只篩種類、盲區保持對玩家也有效、
--   殭屍點陣溢出不吃掉行人。
--   (soft-f) 軟縫往左閃行人、會車把 laneBias 拉到右邊行人站的線上：判停看會車目標＝player-stop（反例：軟縫仍主導＝不停）
--   (soft-g) 行人太近、側移來不及（目標 lane 清得開但到不了）：player-stop，不靠 12 km/h 下限擦過去
--   (soft-h) 閃殭屍關閉時 RETURN 仍讓位給回線帶上的玩家／選到的大型動物
--   (soft-i) 閃殭屍關閉、單一行人從前窗進到盲區、車尾未過：軟縫不釋放
--   (soft-j) 64 點殭屍點陣溢出後再遇行人：軟縫棄權但停等仍看得到行人；停等目標也收不下時溢出段之後照停等
function drive.scenarioSoftArbiter()
    scenario("動物與玩家（整合補刀）：仲裁後判停、側移來不及停、選項只篩種類、盲區保持、點陣溢出")
    local T = MDAD.Drive.debugTune()
    local oldZ, oldA = MDAD.HUD.zombieDodge, MDAD.HUD.animalDodge
    local zOn = true
    MDAD.HUD.zombieDodge = function() return zOn end
    MDAD.HUD.animalDodge = function() return 2 end
    setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false, AutoDriveMaxSpeed = 40,
        RightLaneBias = 0, ZombieAreaSlowdown = false, CorpseSlowdown = false, AnimalSlowdown = 2 })
    local function arm()
        drive.fillWorld(-10, 160, -9, 9)
        assert(armDrive())
        setHeading(dveh, 0)
        dveh._speed, dveh._y = 20, 0
        drive.scanRound(true)
        drive.scanRound(true)
        return MDAD.Drive.debugSession(0)
    end
    local function putPlayer(x, l)
        drive.putMoving(math.floor(x), math.floor(l), { _class = "IsoPlayer",
            getX = function() return x end, getY = function() return l end,
            isDead = function() return false end, getVehicle = function() return nil end })
    end
    local function putCow(x, l)
        drive.putMoving(math.floor(x), math.floor(l), { _class = "IsoAnimal", _isa = { IsoPlayer = true },
            getX = function() return x end, getY = function() return l end,
            isDead = function() return false end, getVehicle = function() return nil end,
            isHeld = function() return false end,
            getData = function() return { getWeight = function() return 500 end } end })
    end

    -- (soft-f)
    local s = arm()
    local R = s.vehicleProfile.halfW + MDADCorridor.ZOMBIE_R + MDADCorridor.ZOMBIE_MARGIN
    putPlayer(30.5, 1.5)
    drive.scanRound(true)
    checkTrue(s.zombieLane ~= nil and type(s.zombieWant) == "number" and s.zombieWant < 0 and s.softStopKind == nil,
        "(soft-f) 前置：軟縫往左閃行人、選定的線清得開＝不停（want " .. tostring(s.zombieWant) .. "）")
    s.trafficLane, s.trfOnWant = 1.5, 1.5 -- 會車要求往右：trafficLaneOf 的 max 覆寫軟縫結果
    MDADFollower.setLaneBias(s.fstate, 1.5)
    MDAD.Drive.softStopScan(s, 20)
    checkTrue(s.softStopKind == "player" and type(s.softStopLane) == "number" and math.abs(s.softStopLane - 1.5) < 0.05,
        "(soft-f) 會車把線拉到行人站的右側：用仲裁後的線判停＝player-stop（at " .. tostring(s.softStopLane) .. "）")
    s.trafficLane, s.trfOnWant = nil, nil
    MDADFollower.setLaneBias(s.fstate, s.zombieLane)
    MDAD.Drive.softStopScan(s, 20)
    checkTrue(s.softStopKind == nil, "(soft-f) 反例：軟縫仍主導最後的線＝照它的 want 判、不停")
    -- (soft-f2) 會車側移還在途中（laneBias 0.6）、目標 2.9 正是行人站的位置：判停看會車的終點，不看途中的 laneBias
    s = arm()
    putPlayer(30.5, 2.9)
    drive.scanRound(true)
    checkTrue(s.zombieLane == nil and s.softStopKind == nil, "(soft-f2) 前置：行人在常駐線外、不閃不停")
    s.trafficLane, s.trfOnWant = 0.6, 2.9
    MDADFollower.setLaneBias(s.fstate, 0.6)
    MDAD.Drive.softStopScan(s, 20)
    checkTrue(s.softStopKind == "player" and type(s.softStopLane) == "number" and s.softStopLane > 2.5,
        "(soft-f2) 會車主導、還在側移：用會車終點判停＝player-stop（at " .. tostring(s.softStopLane) .. "）")
    s.trafficLane, s.trfOnWant = nil, nil

    -- (soft-g)
    s = arm()
    putPlayer(9.5, 0.2)
    drive.scanRound(true)
    checkTrue(s.softStopKind == "player" and s.lastSensorReason == "player-stop",
        "(soft-g) 行人在近處、側移來不及：停等（want " .. tostring(s.zombieWant) .. "、why " .. tostring(s.zombieWhy)
        .. "、at " .. tostring(s.softStopLane) .. "）")

    -- (soft-h)
    zOn = false
    for _, kind in ipairs({ "player", "animal" }) do
        s = arm()
        local zl = R + T.SOFT_COMFORT_M + 0.15
        local y0 = zl + R + 0.3
        if kind == "player" then putPlayer(8.5, zl) else putCow(8.5, zl) end
        drive.scanRound(true)
        dveh._y = y0
        driveTick(dp, dveh)
        checkTrue(not s.returnActive and math.abs(s.fstate.laneBias - y0) < 0.05 and s.zombieLaneParked ~= nil,
            "(soft-h) 閃殭屍關閉：回線帶上的" .. kind .. "仍讓 RETURN 讓位（returnActive " .. tostring(s.returnActive)
            .. "、lane " .. tostring(s.fstate.laneBias) .. "）")
    end

    -- (soft-i)
    s = arm()
    putPlayer(4.5, 0.01)
    drive.scanRound(true)
    checkTrue(s.zombieLane ~= nil and (s.zomBlindN or 0) >= 1,
        "(soft-i) 前置：閃殭屍關閉仍閃行人、記進盲區（blindN " .. tostring(s.zomBlindN) .. "）")
    driveReset(dveh)
    dveh._x = dveh._x + 3.2 -- 行人落到車前 SCAN_NEAR 內（快照不再有牠）
    s.zombieAvoidUntilS = nil
    drive.scanRound(true)
    checkTrue(s.zombieLane ~= nil and s.zombieWhy ~= nil and s.zombieWhy ~= "clear",
        "(soft-i) 行人在盲區、車尾未過：軟縫不釋放（why " .. tostring(s.zombieWhy) .. "）")
    -- 車尾過了行人：盲區記憶不再算（下一輪才壓縮記憶，先直接問判定）
    driveReset(dveh)
    dveh._x = dveh._x + 5
    driveTick(dp, dveh)
    checkTrue(MDAD.Drive.softOthersJoin(s, s.sensor, 2) == false,
        "(soft-i) 車尾過了行人：盲區記憶不再讓軟縫作用")
    zOn = true

    -- (soft-j)
    s = arm()
    for k = 1, 70 do drive.putMoving(10, -4, { _class = "IsoZombie", getX = function() return 10.5 + k * 0.001 end,
        getY = function() return -3.6 end }) end
    putPlayer(30.5, 0.1)
    drive.scanRound(true)
    checkTrue(s.sensor.zomOverflow == true and s.sensor.stopN == 1 and s.softStopKind == "player",
        "(soft-j) 殭屍點陣溢出、軟縫棄權：停等仍看得到行人（overflow " .. tostring(s.sensor.zomOverflow) .. "、stopN "
        .. tostring(s.sensor.stopN) .. "、kind " .. tostring(s.softStopKind) .. "）")
    local sen = s.sensor
    sen.stopN, sen.stopOverflow, sen.stopOverS, sen.stopOverKind = 0, true, s.lastSNow + 20, "player"
    MDAD.Drive.softStopScan(s, 20)
    checkTrue(s.softStopKind == "player" and math.abs((s.softStopS or 0) - (s.lastSNow + 20)) < 1e-6,
        "(soft-j) 停等目標也收不下：收不下的那段起點之後證明不了淨空＝停等")
    sen.stopOverKind = "small" -- AnimalSlowdown＝大型：收不下的只有小動物不停
    MDAD.Drive.softStopScan(s, 20)
    checkTrue(s.softStopKind == nil, "(soft-j) 收不下的只有沒選到的小動物：不停")

    MDAD.Drive.stop(0, nil)
    MDAD.HUD.zombieDodge, MDAD.HUD.animalDodge = oldZ, oldA
    drive.fillWorld(-2, 70, -7, 7)
    setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false, AutoDriveMaxSpeed = 40, RightLaneBias = 0 })
    assert(armDrive())
end
drive.scenarioSoftArbiter()

-- (soft-k) 1005 E2E animal-sp cow（an-cow-1005b）：路緣硬物取樣柱在格內跳動，可行帶右緣每輪在「右縫剛好放得下」與
--   「差 0.3m」之間換，舊制選縫每輪左右翻（want 5.04↔0.12），lane 停在牛前、43 km/h 擦過。重現：包一層
--   Drive.softBand，右緣隔輪在 occ＋0.06／occ−0.29 之間換（occ＝牛的佔位右緣＝0.6＋R，跳動量在 SOFT_HARD_JITTER_M 內）。
--   期望：同一頭牛整段都在同一側閃（Drive.softKeepSide）。反例：跳動超過 JITTER（右縫真的消失）照常換到左側。
--   違規證明：拿掉 softKeepSide 呼叫＝(soft-k) 紅；拿掉帶緣容許量＝(soft-k) 紅。
function drive.scenarioSoftSide()
    scenario("軟縫換邊遲滯：帶緣取樣跳動不讓同一個威脅左右翻")
    local Dr = MDAD.Drive
    local T = Dr.debugTune()
    local oldA, oldBand = MDAD.HUD.animalDodge, Dr.softBand
    MDAD.HUD.animalDodge = function() return 2 end
    setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false, AutoDriveMaxSpeed = 40,
        RightLaneBias = 0, ZombieAreaSlowdown = false, CorpseSlowdown = false, AnimalSlowdown = 2 })
    local cap = nil
    Dr.softBand = function(...)
        local lo, hi, known = oldBand(...)
        if cap ~= nil and hi > cap then hi = cap end
        return lo, hi, known
    end
    local function run(shrinkBy)
        drive.fillWorld(-10, 160, -9, 9)
        assert(armDrive())
        setHeading(dveh, 0)
        dveh._speed, dveh._y = 20, 0
        cap = nil
        drive.scanRound(true)
        drive.scanRound(true)
        local s = Dr.debugSession(0)
        local R = s.vehicleProfile.halfW + MDADCorridor.ZOMBIE_R + MDADCorridor.ZOMBIE_MARGIN
        local occ = T.SOFT_COMFORT_M + R
        drive.putMoving(40, 0, { _class = "IsoAnimal", _isa = { IsoPlayer = true },
            getX = function() return 40.5 end, getY = function() return 0 end,
            isDead = function() return false end, getVehicle = function() return nil end,
            isHeld = function() return false end,
            getData = function() return { getWeight = function() return 500 end } end })
        local sides, flips, prev = "", 0, nil
        for k = 1, 8 do
            cap = (k % 2 == 0) and occ - shrinkBy or occ + 0.06
            driveReset(dveh)
            dveh._x, dveh._y = dveh._x + 1.6667, s.fstate.laneBias
            drive.scanRound(true)
            local w = s.zombieWant
            local side = (type(w) == "number" and w > 0.05) and 1 or ((type(w) == "number" and w < -0.05) and -1 or 0)
            sides = sides .. (side > 0 and "R" or (side < 0 and "L" or "0"))
            if prev ~= nil and side ~= prev then flips = flips + 1 end
            prev = side
        end
        cap = nil
        return sides, flips
    end
    local sides, flips = run(0.29)
    checkTrue(flips == 0 and sides:sub(1, 1) == "R",
        "(soft-k) 右緣在 JITTER 內跳動：同一頭牛整段都從右側閃，不左右翻（" .. sides .. "）")
    -- 原本那一側被第二個目標擋住（玩家走進右縫）：不得硬留，換到左側
    local s = Dr.debugSession(0)
    local R = s.vehicleProfile.halfW + MDADCorridor.ZOMBIE_R + MDADCorridor.ZOMBIE_MARGIN
    local rl = T.SOFT_COMFORT_M + R + 1.0
    drive.putMoving(41, math.floor(rl), { _class = "IsoPlayer", getX = function() return 41.5 end,
        getY = function() return rl end, isDead = function() return false end, getVehicle = function() return nil end })
    cap = 99
    driveReset(dveh)
    dveh._y = s.fstate.laneBias
    drive.scanRound(true)
    cap = nil
    checkTrue(type(s.zombieWant) == "number" and s.zombieWant < 0,
        "(soft-k) 原本那一側被擋住：換到另一側（want " .. tostring(s.zombieWant) .. "）")
    sides, flips = run(T.SOFT_HARD_JITTER_M + 0.3)
    checkTrue(flips >= 1 and sides:find("L") ~= nil,
        "(soft-k) 反例：右縫真的消失（超過 JITTER）照常換到左側（" .. sides .. "）")
    Dr.softBand = oldBand
    MDAD.Drive.stop(0, nil)
    MDAD.HUD.animalDodge = oldA
    drive.fillWorld(-2, 70, -7, 7)
    setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false, AutoDriveMaxSpeed = 40, RightLaneBias = 0 })
    assert(armDrive())
end
drive.scenarioSoftSide()

-- ⑤lf 低幀率降速提示（0925；0929o 門檻改為掃描額度放大到上限的 50ms）：可視上限壓速、平均幀時 ≥50ms，
--   且視距是被幀率截短，持續 2s 才讓 HUD 狀態變「卡頓降速」（lowfps）、恢復 3s 才消失；同趟累計 10s 跳一次
--   通知。session 從 150ms（可負擔 32m）起算。反例：幀率低但速度沒被可視上限壓（沙盒上限 20）不顯示。
--   違規證明：ON 遲滯歸零＝首輪即顯示紅；拿掉「只通知一次」＝通知次數 >1 紅。
function drive.scenarioLowFpsNotice()
    scenario("低幀率降速：HUD 狀態遲滯顯示、每趟只通知一次、沒被壓速不顯示")
    local function count(key)
        local n = 0
        for _, h in ipairs(halos) do if noteReason(h.text) == key then n = n + 1 end end
        return n
    end
    local function run(maxKmh)
        setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false,
            AutoDriveMaxSpeed = maxKmh, RightLaneBias = 0 })
        drive.fillWorld(-10, 170, -9, 9)
        assert(armDrive())
        setHeading(dveh, 0)
        MDAD.Drive.setGear(0, 4)
        dveh._speed = maxKmh
        return MDAD.Drive.debugSession(0)
    end
    local was = drive.frameMs(150)
    local s = run(120)
    drive.frameMs(150)
    drive.scanRound()
    drive.frameMs(150)
    local firstKey = MDAD.Drive.hudState(0)
    for _ = 1, 8 do drive.scanRound(); drive.frameMs(150) end
    local onKey = MDAD.Drive.hudState(0)
    checkTrue(firstKey ~= "lowfps" and onKey == "lowfps",
        "(lf) 可視上限被幀率壓住：遲滯後 HUD 顯示 lowfps（首輪 " .. tostring(firstKey) .. "、之後 " .. tostring(onKey) .. "）")
    for _ = 1, 40 do drive.scanRound(); drive.frameMs(150) end
    checkEq(count("UI_MinidoracatAutoDrive_LowFpsNotice"), 1, "(lf) 同一趟累計超過 10 秒只通知一次")
    drive.frameMs(10)
    for _ = 1, 16 do drive.scanRound(); drive.frameMs(10) end
    checkTrue(MDAD.Drive.hudState(0) ~= "lowfps", "(lf) 幀率恢復後狀態消失")
    -- 門檻 predicate 級：同樣視距被幀率截短、可視上限在壓速，25 FPS（40ms：額度已放大到看得到 60 FPS 的
    -- 距離，不是幀率造成的）不算、17 FPS（60ms：額度已到上限）算
    for _, c in ipairs({ { 40, false }, { 60, true } }) do
        local fake = { mode = "follow", playerNum = 0, lastSNow = 0, sensor = {
            affordableAheadM = 62, requestedAheadM = 240, effectiveAheadM = 62, frameEwmaMs = c[1] } }
        for t = 0, 3000, 100 do MDAD.Drive.updateLowFps(fake, 1000 + t, true) end
        checkEq(fake.lowFps == true, c[2], "(lf) 幀時 " .. c[1] .. "ms 可視上限壓速 3 秒：低幀率＝" .. tostring(c[2]))
    end
    s = run(20)
    for _ = 1, 12 do drive.scanRound(); drive.frameMs(150) end
    checkTrue(MDAD.Drive.hudState(0) ~= "lowfps" and not s.lowFps,
        "(lf) 幀率低但沒被可視上限壓速（上限 20）：不顯示")
    drive.frameMs(was)
    setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false, AutoDriveMaxSpeed = 40, RightLaneBias = 0 })
    MDAD.Drive.setGear(0, 3)
    assert(armDrive())
end
drive.scenarioLowFpsNotice()

function drive.scenarioAvoidSlowPrefs()
    local world, geo, sandbox, avoid = drive.world, drive.vehGeo, SandboxVars, MDAD.HUD.zombieDodge
    local oldZ, oldC = MDAD.Drive.getSlowPref(0, "zombie"), MDAD.Drive.getSlowPref(0, "corpse")
    scenario("軟避讓遵守各自減速開關：關閉不借側移時間帽、混合目標不互相授權")
    setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false,
        AutoDriveMaxSpeed = 40, RightLaneBias = 0,
        ZombieAreaSlowdown = MDAD.POLICY_PLAYER, CorpseSlowdown = MDAD.POLICY_PLAYER })
    MDAD.HUD.zombieDodge = function() return true end
    local function arm(z, c)
        drive.fillWorld(-10, 160, -9, 9)
        MDAD.Drive.setSlowPref(0, "zombie", z)
        MDAD.Drive.setSlowPref(0, "corpse", c)
        assert(armDrive())
        setHeading(dveh, 0)
        dveh._speed = 20
        drive.scanRound(true)
        drive.scanRound(true)
        local s = MDAD.Drive.debugSession(0)
        return s, s.desiredTarget
    end
    local function putAt(kind, x, l)
        if kind == "corpse" then
            local body = drive.putCorpse(x, math.floor(l))
            body._y = l -- 屍體長軸兩端（angle 0）同一個橫向偏移，只換邊
        else
            drive.putMoving(x, math.floor(l), { _class = "IsoZombie",
                getX = function() return x + 0.5 end, getY = function() return l end })
        end
    end
    local function tick(s)
        drive.scanRound(true)
        dveh._y = s.fstate.laneBias
        driveReset(dveh)
        driveTick(dp, dveh)
    end
    for _, kind in ipairs({ "zombie", "corpse" }) do
        local s, base = arm(kind == "corpse", kind == "zombie")
        putAt(kind, 8, 0)
        tick(s)
        checkTrue(s.zombieLane ~= nil and math.abs(s.fstate.laneBias) > 0.1,
            "(avoid-pref) " .. kind .. " 關閉減速仍嘗試橫向避讓")
        checkTrue(s.zombieLaneCap < 0 and s.desiredTarget >= base - 1e-6
                and s.lastSensorReason ~= "zombie-lane" and drive.calls.forceBrake == 0,
            "(avoid-pref) 另一類開關不能替關閉的 " .. kind .. " 授權減速")
        s, base = arm(kind == "zombie", kind == "corpse")
        putAt(kind, 8, 0)
        tick(s)
        checkTrue(s.zombieLaneCap > 0 and s.desiredTarget < base,
            "(avoid-pref) " .. kind .. " 開啟減速時仍可配合閃避放慢")
        local stamp = s.sensor.stamp
        MDAD.Drive.setSlowPref(0, kind, false)
        driveReset(dveh)
        driveTick(dp, dveh)
        checkTrue(s.sensor.stamp == stamp and s.zombieLaneCap < 0
                and s.desiredTarget >= base - 1e-6 and drive.calls.forceBrake == 0,
            "(avoid-pref) 關閉 " .. kind .. " 當幀撤回舊限速，不等新掃描")
    end
    local s, base = arm(false, false)
    putAt("zombie", 8, 0)
    putAt("corpse", 18, 0)
    for _ = 1, 4 do
        tick(s)
        checkTrue(s.zombieLaneCap < 0 and s.desiredTarget >= base - 1e-6
                and drive.calls.forceBrake == 0,
            "(avoid-pref) 兩類都關：混合避讓不產生任何配合減速")
    end
    for _, enabled in ipairs({ "zombie", "corpse" }) do
        s = arm(enabled == "zombie", enabled == "corpse")
        putAt(enabled, 28, 0)
        putAt(enabled == "zombie" and "corpse" or "zombie", 8, 0)
        tick(s)
        checkTrue(s.zombieLaneCap > 30,
            "(avoid-pref) 近處未授權目標不取代遠處 " .. enabled .. " 的配合距離")
    end
    s, base = arm(false, true)
    putAt("corpse", 8, 0)
    tick(s)
    checkTrue(s.zombieLaneCap > 0, "(avoid-pref) 重用前槽位確實曾屬可減速屍體")
    drive.clearCell(8, 0)
    putAt("zombie", 8, 0)
    for _ = 1, 2 do
        tick(s) -- 兩輪後再用到原本存屍體的工作緩衝，false標記不能省略。
        checkTrue(s.zombieLaneCap < 0 and s.desiredTarget >= base - 1e-6,
            "(avoid-pref) 雙緩衝重用不把殭屍誤認成允許減速的屍體")
    end
    -- (avoid-lag) 真正「側移跟不上」的反例：車每輪沿線前進 1.6667m（20km/h×300ms＝
    --     進度監督看得見的真前進），車身橫向動不了／只慢慢跟——y 不再被寫成 laneBias，
    --     所以軟需求跑掉多少就真的變成追線誤差。0909c 離線重現：兩類減速都關、避讓開，
    --     laneBias .3→.6→.9→1.2→1.5 而車身留在 0，共用的對線帽把 des 36→22→17→13
    --     一路壓下去（zombieLaneCap 全程 −1，reason=align，配合帽沒授權也照樣慢）。
    --     契約：沒有減速權限時能閃就閃、跟不上就少閃，絕不因此降速或煞車。
    --     四組合計覆蓋左右兩側、車身完全不動／慢慢跟，以及兩類都關／另一類開。
    local function roll(dy)
        driveReset(dveh) -- 觀測窗含整輪掃描幀：掃描中途的 forceBrake 也要算進來
        dveh._x = dveh._x + 1.6667
        dveh._y = dveh._y + dy
        drive.scanRound(true) -- 位移自己給（真前進），不要 harness 的 1.1m 來回跳
    end
    -- off 點不必壓住當前車道，也能封住 on 目標旁的候選；距離與側移預算都不能借權限。
    for _, row in ipairs({ { "zombie", { 0 }, 1.7 }, { "corpse", { 0 }, 1.7 },
            { "zombie", { -1, 1 }, 2.8 } }) do
        local enabled, lanes, edge = row[1], row[2], row[3]
        local disabled = enabled == "zombie" and "corpse" or "zombie"
        s = arm(enabled == "zombie", enabled == "corpse")
        for _, l in ipairs(lanes) do putAt(enabled, 28, l) end
        drive.scanRound(true)
        local allowedCap, allowedTarget = s.zombieLaneCap, s.desiredTarget
        s = arm(enabled == "zombie", enabled == "corpse")
        for _, l in ipairs(lanes) do putAt(enabled, 28, l) end
        putAt(disabled, 8, edge)
        putAt(disabled, 8, -edge)
        drive.scanRound(true)
        checkTrue(allowedCap > 0 and math.abs(s.zombieLaneCap - allowedCap) < 1e-6
                and s.desiredTarget >= allowedTarget - 1e-6,
            "(avoid-mixed) " .. disabled .. " 關閉時，不得擴大 " .. enabled .. " 的減速側移預算")
        MDAD.Drive.setSlowPref(0, disabled, true)
        checkTrue(s.zombieLaneCap > 0 and s.zombieLaneCap < allowedCap,
            "(avoid-mixed) 兩類都開時，近端目標確實需要較低的配合速度")
        local stamp = s.sensor.stamp
        MDAD.Drive.setSlowPref(0, disabled, false)
        driveReset(dveh)
        driveTick(dp, dveh)
        checkTrue(s.sensor.stamp == stamp and math.abs(s.zombieLaneCap - allowedCap) < 1e-6
                and s.desiredTarget >= allowedTarget - 1e-6,
            "(avoid-mixed) 關閉 " .. disabled .. " 當幀重算共享幾何，不保留它的舊減速")
    end
    for _, c in ipairs({ { "zombie", 0, 0, false }, { "zombie", 1.2, 0, true },
            { "corpse", 0, 0.08, false }, { "corpse", 1.2, -0.08, true } }) do
        local kind, at, dy, other = c[1], c[2], c[3], c[4]
        local tag = "(avoid-lag) " .. kind .. (other and " 關、另一類開" or " 關、兩類都關")
        s, base = arm(kind ~= "zombie" and other, kind ~= "corpse" and other)
        putAt(kind, 20, at)
        for i = 1, 5 do
            roll(dy)
            checkTrue(s.desiredTarget >= base - 1e-6 and drive.calls.forceBrake == 0
                    and s.zombieLaneCap < 0 and s.lastSensorReason ~= "zombie-lane",
                tag .. "：側移跟不上的第 " .. i .. " 輪也不得降速／煞車（實得 "
                .. tostring(s.desiredTarget) .. "、基準 " .. tostring(base) .. "）")
        end
        local away = s.fstate.laneBias - dveh._y -- 相對車身的側移意圖（不是相對常駐線）
        -- 0925：不再限「只領先車身 0.25m」——那會把閃避掐成車身自己的橫移速度（E2E crowd 關減速
        -- 兩秒只偏 0.16m 就撞）；對線帽改看常駐線到軟縫的區間，落後不再換成減速。車身完全不動的
        -- 兩案要領先 >0.5m；慢慢跟的兩案車身已追上一部分，只驗方向。
        local minAway = dy == 0 and 0.5 or 0.05
        checkTrue(s.zombieLane ~= nil and math.abs(away) > minAway and (at > 0) == (away < 0),
            tag .. "：側移意圖不被車身落後掐住（相對車身 " .. tostring(away) .. "）")
    end
    -- (avoid-lag) 中途關閉：授權期間已經跑出去的軟需求要當幀撤回，舊追線誤差不得
    --     繼續換速度。不跑下一輪掃描（stamp 不變）＝撤回真的來自政策本身。
    s, base = arm(true, false)
    putAt("zombie", 20, 0)
    for _ = 1, 5 do roll(0) end
    checkTrue(s.zombieLaneCap > 0 and s.desiredTarget < base
            and math.abs(s.lastLatDev) > 0.6,
        "(avoid-lag) 開啟時授權大幅側移：車身跟不上就照配合帽放慢（latDev "
        .. tostring(s.lastLatDev) .. "、des " .. tostring(s.desiredTarget) .. "）")
    local lagStamp = s.sensor.stamp
    MDAD.Drive.setSlowPref(0, "zombie", false)
    driveReset(dveh)
    driveTick(dp, dveh)
    checkTrue(s.sensor.stamp == lagStamp and s.zombieLaneCap < 0
            and s.desiredTarget >= base - 1e-6 and drive.calls.forceBrake == 0,
        "(avoid-lag) 關閉當幀連舊 latDev 的等待減速一起撤回（實得 "
        .. tostring(s.desiredTarget) .. "、基準 " .. tostring(base) .. "）")
    -- (avoid-lag) 配合帽的授權看它自己的來源：切換無關類型（開或關）不得順手把另一類
    --     已經成立的合法減速解除一輪。這裡帽屬屍體（世界裡只有屍體），動的是殭屍偏好。
    s, base = arm(true, true)
    putAt("corpse", 14, 0) -- 0925p 速率 0.25×v：20m 外已側移得完、帽不綁
    for _ = 1, 3 do roll(0) end
    checkTrue(s.zombieLaneCap > 0 and s.desiredTarget < base,
        "(avoid-lag) 屍體減速開著：屍體那條合法配合減速成立（des "
        .. tostring(s.desiredTarget) .. "）")
    local capped = s.desiredTarget
    lagStamp = s.sensor.stamp
    for _, on in ipairs({ false, true, false }) do
        MDAD.Drive.setSlowPref(0, "zombie", on)
        driveReset(dveh)
        driveTick(dp, dveh)
        checkTrue(s.sensor.stamp == lagStamp and s.zombieLaneCap > 0
                and s.desiredTarget <= capped + 1e-6,
            "(avoid-lag) 把無關的殭屍偏好切成 " .. tostring(on)
            .. " 不得解除屍體那條合法減速（實得 " .. tostring(s.desiredTarget)
            .. "、原本 " .. tostring(capped) .. "）")
    end
    -- (avoid-adapt) 撤回舊軟需求＝換了一條線，證明不能沿用舊線的。開啟期間軟縫把線帶到
    --     常駐線右側 1m 以上（車身仍在線上），此時把樹放在常駐線那一側：偏開的舊線掃掠
    --     仍淨空、不繞行也不停等；關閉當幀重錨回車身＝新線穿樹，速度必須跟著掉，不得
    --     沿用舊線的證明全速穿過去。這一案要真 adaptive：v2 session 的 gate 恆以 arc 走
    --     0.9 比例檔，近場未知地板看不出來。斜路沿線前進同時更新 x/y，不能以 y=0 代替。
    --     組合沿用 0909c 探針（RaceCar58 幾何、鋪面寬 10）。
    local oldVeh = dveh
    local function adaptiveToggle(tree, tag)
        local h = math.rad(7)
        installNavApi(4)
        dveh = newVehicle({ battery = newItem("Base.CarBattery", { uses = 0.8 }),
            engineRunning = true, mass = 1000, speed = 20, maxSpeed = 120,
            bodyW = 1.31, bodyL = 3.24, comX = 0, comZ = 0.4, profileFull = true,
            enginePower = 4000, brakingForce = 80, wheelFriction = 1.5, tireFriction = 1.5 })
        drive.fillWorld(-10, 170, -30, 40)
        drive.putRoad(-10, 170, -30, 40)
        local route = newRoute(40, 0, 0, 4 * math.cos(h), 4 * math.sin(h))
        route.segSurface, route.segWidth = {}, {}
        for i = 1, 39 do route.segSurface[i], route.segWidth[i] = "paved", 10 end
        route.len, route.cost, route.avoidPenalty, route.approachSurface = 156, 156, 0, "unknown"
        MDAD.Drive.stop(0, nil)
        dveh._x, dveh._y, dveh._speed, dveh._steering, dveh._stopped = 0, 0, 20, 0, false
        dveh._engine, dveh._driver = true, dp
        dveh._part._item._uses = 0.8
        dp._vehicle, dp._dead, dp._local = dveh, false, true
        setHeading(dveh, h)
        drive.nav.tx, drive.nav.ty = 300 * math.cos(h), 300 * math.sin(h)
        drive.nav.state, drive.nav.route = "ok", route
        MDAD.Drive.setSlowPref(0, "zombie", false)
        MDAD.Drive.setSlowPref(0, "corpse", false)
        assert(MDAD.Drive.start(dp))
        for _ = 1, 2 do driveTick(dp, dveh) end
        for _ = 1, 3 do drive.scanRound(true) end
        local a = MDAD.Drive.debugSession(0)
        local full = a.desiredTarget
        drive.putMoving(12, 1, { _class = "IsoZombie",
            getX = function() return 12.5 * math.cos(h) end,
            getY = function() return 12.5 * math.sin(h) end })
        for i = 1, 4 do
            dveh._x, dveh._y = 1.5 * i * math.cos(h), 1.5 * i * math.sin(h)
            driveReset(dveh)
            drive.scanRound(true)
            checkTrue(a.desiredTarget >= full - 1e-6 and drive.calls.forceBrake == 0,
                tag .. "關閉時沿線前進第 " .. i .. " 輪不為軟避讓減速（實得 "
                .. tostring(a.desiredTarget) .. "、基準 " .. tostring(full) .. "）")
        end
        MDAD.Drive.setSlowPref(0, "zombie", true)
        for _ = 1, 3 do drive.scanRound(true) end
        checkTrue(a.zombieLaneCap > 0 and a.desiredTarget < full
                and math.abs(a.lastLatDev) > 0.6,
            tag .. "開啟時授權大幅側移：車身跟不上就照配合帽放慢（latDev "
            .. tostring(a.lastLatDev) .. "、des " .. tostring(a.desiredTarget) .. "）")
        if tree then
            drive.putTree(24, 2, "vegetation_trees_01_5") -- 常駐線那一側（l≈−0.5）
            drive.scanRound(true)
            checkTrue(a.verifySweep and not a.dodging and not a.blocked,
                tag .. "偏開的舊線掃掠仍淨空：樹不在這條線上，不繞行也不停等")
        end
        local stamp0, lane0 = a.sensor.stamp, a.fstate.laneBias
        MDAD.Drive.setSlowPref(0, "zombie", false)
        driveReset(dveh)
        driveTick(dp, dveh)
        checkTrue(a.sensor.stamp == stamp0, tag .. "關閉當幀沒有新掃描完成")
        return a, full, lane0
    end
    local adapt, adaptFull = adaptiveToggle(false, "(avoid-adapt) 無樹：")
    checkTrue(adapt.desiredTarget >= adaptFull - 1e-6 and adapt.verifyLineReason == "ok"
            and drive.calls.forceBrake == 0,
        "(avoid-adapt) 無樹：關閉當幀回滿基準速度，而且新線自己驗得過（實得 "
        .. tostring(adapt.desiredTarget) .. "、基準 " .. tostring(adaptFull)
        .. "、proof " .. tostring(adapt.verifyLineReason) .. "）")
    -- 0925 起關閉減速不再把軟縫撤回車身（對線帽已不看常駐線到軟縫之間的落後）：偏開的舊線
    -- 繼續有效，不得被拉回常駐線那一側的樹，也不為此減速。
    local lane0
    adapt, adaptFull, lane0 = adaptiveToggle(true, "(avoid-adapt) 有樹：")
    checkTrue(math.abs(adapt.fstate.laneBias - lane0) < 1e-6 and adapt.verifySweep
            and not adapt.dodging and not adapt.blocked and adapt.desiredTarget >= adaptFull - 1e-6,
        "(avoid-adapt) 有樹：關閉減速保留已偏開的線（不拉回樹那側）且不減速（lane "
        .. tostring(adapt.fstate.laneBias) .. "／" .. tostring(lane0) .. "、des "
        .. tostring(adapt.desiredTarget) .. "、基準 " .. tostring(adaptFull) .. "）")
    dveh = oldVeh
    oldVeh._driver, dp._vehicle = dp, oldVeh
    installNavApi(2) -- 還原本情境進來時的版本（非 adaptive）：後續樹木情境沿用它
    MDAD.Drive.stop(0, nil)
    drive.world, drive.vehGeo, SandboxVars, MDAD.HUD.zombieDodge = world, geo, sandbox, avoid
    MDAD.Drive.setSlowPref(0, "zombie", oldZ)
    MDAD.Drive.setSlowPref(0, "corpse", oldC)
    assert(armDrive())
end
drive.scenarioAvoidSlowPrefs()

-- ⑤c 樹＝硬障礙：樹 sprite 無碰撞 flag（shouldHaveCollision 隱形），靠
--     instanceof IsoTree 判 HARD——修 2026-08-28 實機撞樹鬼打牆（全油撞樹→
--     脫困→原路再撞 ×3）。與屍體相反：樹要繞、屍體只減速。
driveReset(dveh)
drive.putTree(20, 0, "vegetation_trees_01_5")
drive.scanRound()
checkEq(haloKey(), DKEY.DODGE, "路中一棵樹：硬障礙 → 繞行")
driveReset(dveh)
driveTick(dp, dveh)
checkTrue(drive.calls.maxRegSpeed > 0 and drive.calls.maxRegSpeed < 40,
    "tree dodge uses computed dynamic cap")
drive.clearCell(20, 0)
drive.scanRound()
drive.scanRound() -- 守護驗證連續通過（樹已清）：不轉 blocked
driveReset(dveh)
driveTick(dp, dveh)
checkEq(dveh._regulator, true, "樹清除：恢復行駛")
checkTrue(drive.calls.maxRegSpeed > 0 and drive.calls.maxRegSpeed < 40,
    "tree-clear guard preserves the immutable computed cap")
-- 路緣樹段要乾淨旗標：重臂
checkTrue(armDrive(), "⑤c→路緣樹 重臂")
setHeading(dveh, 0.05)
dveh._speed = 20
driveReset(dveh)
-- 路緣樹（l≈-2.5，細桿門檻 1.4 → 不擋線）：不觸發繞行、不減速——實機
-- 2026-08-28：肥半徑把整排路緣樹判成擋路，車長期貼對側路緣不回中
drive.putTree(20, -3, "vegetation_trees_01_7")
drive.scanRound()
driveReset(dveh)
driveTick(dp, dveh)
checkEq(#halos, 0, "路緣樹：不觸發繞行提示")
checkTrue(drive.calls.maxRegSpeed >= 0 and drive.calls.maxRegSpeed <= 40,
    "roadside tree does not raise command")
drive.clearCell(20, -3)
drive.scanRound()

-- ⑥ 行進中的別台車 → 跟車減速（不是障礙）；靜止的別台車 → 硬障礙走繞行。
--    車輛感知唯一入口＝square:getVehicleContainer()（格級幾何查詢）——
--    不碰 movingObjects、不碰 cell:getVehicles() 集合（兩者實機都會漏）。
drive.putVehicle(20, 0, false)
drive.scanRound()
driveReset(dveh)
driveTick(dp, dveh)
checkTrue(drive.calls.maxRegSpeed >= 0 and drive.calls.maxRegSpeed <= 20,
    "moving vehicle command never exceeds 20")
checkEq(drive.calls.forceBrake, 0, "跟車只降速不煞停")
drive.clearVehicle(20, 0)
drive.putVehicle(32, 0, true)
drive.scanRound()
dveh._x = 14 -- 進入剖面 15m 界內（接近段分級：遠處照常速、近了才壓）
driveTick(dp, dveh)
driveReset(dveh)
driveTick(dp, dveh)
checkTrue(drive.calls.maxRegSpeed <= DODGE_CAP_TEST, "靜止的車＝硬障礙：進繞行減速（實得 "
    .. tostring(drive.calls.maxRegSpeed) .. "）")
drive.clearVehicle(32, 0)
dveh._x = 0
driveTick(dp, dveh)
driveTick(dp, dveh)

-- ⑥b isStopped 波動＋跨輪靜止判定（2026-08-29 路口皮卡定讞）：MP 假動車
--    isStopped 恆 false，但**位置不會說謊**——同 id 連兩輪（~250ms）位移
--    <0.3m＝實質靜止、強制硬障礙。判停/假動兩態都走繞行，「跟車等一台
--    永不動的車」的誤判態被消滅（舊行為：皮卡不進 hard、plan 從不規劃
--    繞它的縫、車按在原地等它讓路到 20 秒紅字）
local vWobble = drive.putVehicle(30, 0, true)
drive.scanRound()
dveh._x = 12 -- 進 15m 界（剖面 a≈24）
driveTick(dp, dveh)
driveReset(dveh)
driveTick(dp, dveh)
checkTrue(drive.calls.maxRegSpeed > 0 and drive.calls.maxRegSpeed <= DODGE_CAP_TEST,
    "波動車判「靜止」的輪：硬障礙繞行減速（實得 "
    .. tostring(drive.calls.maxRegSpeed) .. "）")
vWobble._stopped = false -- 半更新誤判成行進中：位置不動 → 照樣硬障礙
drive.scanRound()
driveReset(dveh)
driveTick(dp, dveh)
checkTrue(drive.calls.maxRegSpeed > 0 and drive.calls.maxRegSpeed <= DODGE_CAP_TEST,
    "波動車假動（isStopped=false 但位置不動）：跨輪靜止判定收編、照樣繞行（實得 "
    .. tostring(drive.calls.maxRegSpeed) .. "）")
drive.clearVehicle(30, 0)
-- 真動車不被誤判：同 id 輪間位移 1m > 0.3m → 行進中 → 跟車減速（非繞行）。
-- 先重臂：波動段的 dodge 剖面殘留會以 margin 縮放 cap（<15）壓過跟車 15。
-- 手動控輪（scanRound 一口氣掃兩輪、輪間動不了車）：250ms 節流＋12 tick 一輪
checkTrue(armDrive(), "(6b) 真動段重臂")
setHeading(dveh, 0.05)
dveh._speed = 20
local vMove = drive.putVehicle(30, 0, false)
nowMs = nowMs + 300
for _ = 1, 12 do driveTick(dp, dveh) end -- 第一輪：無上輪記錄 → moving
drive.moveVehicle(vMove, 31, 0)
nowMs = nowMs + 300
for _ = 1, 12 do driveTick(dp, dveh) end -- 第二輪：位移 1m → 仍 moving
drive.moveVehicle(vMove, 32, 0)
nowMs = nowMs + 300
for _ = 1, 12 do driveTick(dp, dveh) end -- 第三輪：持續移動（快照穩定 moving）
driveReset(dveh)
driveTick(dp, dveh)
checkTrue(drive.calls.maxRegSpeed >= 0 and drive.calls.maxRegSpeed <= math.ceil(
    MDADDynamics.approachCapKmh(32 - MDAD.Drive.debugSession(0).lastSNow - 20,
        20, 0.5, MDAD.Drive.debugSession(0).safeCoast)),
    "持續移動的前車仍受可實現的接近帽限制")
drive.clearVehicle(32, 0) -- vMove 最後停 (32,0)：清錯格＝幽靈 fixture 每輪判 still
drive.scanRound()
checkTrue(armDrive(), "(6b) 段尾重臂") -- 真動段殘留剖面：⑦ 的 15 斷言不吃 margin cap
setHeading(dveh, 0.05)
dveh._speed = 20
-- 近距跟車（<10m）：目標 0 煞停——MP 半更新的靜止車被 isStopped 誤判成
-- 行進中、不進硬障礙（2026-08-28 實機追尾黑車），不能只 cap 15 跟到撞。
-- 車推到 x=8（route 40m 段長 10m：0→8 同段內，投影一幀跟上）、前車格
-- (16,0)＝中心 16.5：gap = 16.5-8 = 8.5 < 10 且在帶內
dveh._x = 8
driveTick(dp, dveh)
drive.putVehicle(16, 0, false)
drive.scanRound()
driveReset(dveh)
driveTick(dp, dveh)
-- 新語意（跨輪靜止判定）：貼近的「假行進」車兩輪即判 still → 直接當障礙。
-- 世界掃掠通過才允許在寬縫以 24 繞行，否則煞停；兩者都不會全速跟撞。
-- 1001a：跟車停等（followHold）在 10 km/h 以上改不鎖輪煞停（斷油＋中線外力、照常轉向），也算煞停。
checkTrue(drive.calls.forceBrake > 0
        or (MDAD.Drive.debugSession(0).followHold and (MDAD.Drive.debugSession(0).visAssistDecel or 0) > 0
            and drive.calls.maxRegSpeed == 0)
        or (drive.calls.maxRegSpeed > 0 and drive.calls.maxRegSpeed <= 24),
    "前車貼到 10m 內：煞停（鎖輪或不鎖輪）或掃掠通過後以繞行上限 24 通過（實得 forceBrake="
    .. tostring(drive.calls.forceBrake) .. " vad=" .. tostring(MDAD.Drive.debugSession(0).visAssistDecel)
    .. " maxReg=" .. tostring(drive.calls.maxRegSpeed) .. "）")
drive.clearVehicle(16, 0)
drive.scanRound()
checkTrue(armDrive(), "(6b) 近距段尾重臂") -- 殘留剖面不進 ⑦
setHeading(dveh, 0.05)
dveh._speed = 20

-- ⑦ 未載入 chunk：動態煞停距——距外不減速（chunk 會載入）、距內按「能
--    停住的速度」漸進壓（2026-08-29 使用者裁定：帶尾恆未載入不該永遠 15）
drive.world[35 * 100000 + 0] = nil
drive.scanRound()
driveReset(dveh)
driveTick(dp, dveh)
checkTrue(drive.calls.maxRegSpeed >= 0 and drive.calls.maxRegSpeed < 40,
    "exact visibility root never exceeds unloaded horizon cap")
dveh._x = 28 -- gap ~7m < 煞停距：進入動態減速區
driveTick(dp, dveh)
driveReset(dveh)
driveTick(dp, dveh)
checkTrue(drive.calls.forceBrake > 0 or drive.calls.maxRegSpeed == 0,
    "visibility envelope breach immediately clamps/brakes（reg="
    .. tostring(drive.calls.maxRegSpeed) .. "）")
drive.mkSquare(35, 0)
dveh._x = 8 -- 還原 ⑧ 依賴的位置
driveTick(dp, dveh)
driveTick(dp, dveh)

-- ⑧ 停車政策（ObstaclePolicy=2）：就算有縫隙也不繞，一律漸進停車
setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false,
    AutoDriveMaxSpeed = 40, ObstaclePolicy = 2, RightLaneBias = 0 })
dveh._x = 12 -- 靠近障礙（重臂歸零過）：世界距 barrel ~8.5m < 10 直接煞停
driveTick(dp, dveh)
drive.putSolid(20, 0, "harness_barrel2")
drive.scanRound()
checkEq(haloKey(), DKEY.BLOCKED, "停車政策：有縫隙也提示 Blocked（不繞）")
-- 車已在 x=12（上一段），距障礙群 ~8.5 公尺 <10（世界距離判準）→ 直接煞停
driveReset(dveh)
driveTick(dp, dveh)
checkTrue(drive.calls.forceBrake > 0, "停車政策：煞停等待")
checkTrue(MDAD.Drive.isActive(0), "停車政策：session 活著（玩家接手或清障恢復）")
setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false, AutoDriveMaxSpeed = 40, RightLaneBias = 0 })
drive.clearCell(20, 0)
MDAD.Drive.stop(0, nil)

-- ⑨ 彎道繞行（不禁止，算進去）：障礙群落在轉角段（累計轉角 > 25°）時，縫隙判定
--    用放大的需求半寬（+0.6）重算——內輪差與 pure pursuit 切內彎吃掉的餘裕先扣
--    再判。判得過＝真有寬縫照繞、速度受彎道 16 km/h 天花板限制；判不過＝
--    blocked 煞停，不硬擠。手組 L 型路線：直行到 (76,0) 後右轉往南（+Y），
--    障礙放轉角後（障礙群 b..c 涵蓋 45° 折點）。
do
    local pts = {}
    for i = 0, 19 do pts[#pts + 1] = i * 4; pts[#pts + 1] = 0 end       -- (0,0)..(76,0)
    for i = 1, 19 do pts[#pts + 1] = 80; pts[#pts + 1] = i * 4 end      -- (80,4)..(80,76)
    drive.nav.route = { pts = pts }
end
drive.fillWorld(-9, 90, -7, 90)
-- 車放在直段 s=50（障礙 s≈84 要在 36 公尺掃描帶內）
dveh._x, dveh._y, dveh._speed, dveh._steering = 50, 0, 20, 0
setHeading(dveh, 0.05)
dp._vehicle, dveh._driver = dveh, dp
checkTrue(MDAD.Drive.start(dp), "彎道情境啟動")
driveReset(dveh) -- 清掉 Start 綠字
-- ⑨a 彎道縫（2026-09-01 契約更新）：舊制 swept clearance < 0.4 reserve →
--    clearanceCap 0 → 一律 blocked。新制（使用者裁定「物理可過就過」＋近目標
--    exit 壓縮定罪）：彎道爬行檔 reserve 歸零、curveCap 有爬行下限——世界
--    掃掠過就擠過（Dodge，速度連續縮放），真撞 contact fail-closed 兜底。
drive.putSolid(80, 4, "harness_curve_obs")
drive.scanRound()
checkEq(haloKey(), DKEY.DODGE,
    "彎道縫世界掃掠可過：擠過（reserve 否決已廢）")
driveReset(dveh)
driveTick(dp, dveh)
checkTrue(drive.calls.forceBrake > 0
        or (drive.calls.maxRegSpeed >= 0 and drive.calls.maxRegSpeed <= 20),
    "彎道爬行檔速度不超過 blocked approach 帶")
checkTrue(MDAD.Drive.isActive(0), "彎道繞行不結束 session")

-- ⑨a 承諾走完前不換剖面（immutable）：⑨b 要觀察「窄縫降級」的**新提案**，
-- 先結束 ⑨a 的 session 清承諾（否則 ⑨b 只會走守護驗證、⑨c 的紅字被
-- ⑨b 的守護失敗提前吃掉）
MDAD.Drive.stop(0, nil)
checkTrue(MDAD.Drive.start(dp), "⑨b 重臂")
driveReset(dveh) -- 清掉 Start 綠字
-- ⑨b 彎中並排三格（加嚴後無寬縫、**普通縫仍在** ±3.25）：窄縫降級爬行——
--    不再直接 blocked（2026-08-28 實機：彎道兩台並排車被加嚴判死 → 卡死
--    鬼打牆；真擦撞由世界空間複驗把關），entry 仍受 16 km/h 上限。
drive.putSolid(79, 4, "harness_curve_obs_b")
drive.putSolid(81, 4, "harness_curve_obs_c")
drive.scanRound()
-- 2026-09-04 同線物理複驗（s037/s038 同位置重啟一次 blocked 一次過定罪）：巡航 pad
-- 打槍的那條線先以物理 pad 複掃，過＝爬行承諾（使用者 09-01「物理可過就過」）。
-- 舊契約「blocked，不以中心線 clear 硬擠」＝巡航 pad 打槍後只試降檔重規劃的**另一條**
-- lane；現在同線物理過就走，速度仍由 clearance 連續縮放＋爬行檔。
checkEq(haloKey(), DKEY.DODGE,
    "彎中窄縫：巡航 pad 打槍、同線物理 pad 過 → 爬行承諾（不再 blocked）")
-- 換縫找更寬（1004f TUNE.DODGE_THIN_M；E2E f1004e dixie9050w 改道線：物理淨距 0.07 的爬行縫掃過就承諾、進縫落後擦車角，
-- 另一側 0.39 的縫沒試）：同線物理複驗過的 +3.25 物理淨距只有 0.2，記下、ban 掉往下找，另一側 −4.25 以巡航 pad 掃過
-- （物理淨距 0.6）＝換它。違規證明：thinNote 恆回 false（掃過就定案）＝紅。
do
    local ss, T = MDAD.Drive.debugSession(0), MDAD.Drive.debugTune()
    local phys = (ss.dodgeMargin or -1) + (ss.dodgeNeed or 0) - ss.vehicleProfile.halfW
    checkTrue(ss.dodging == true and phys >= T.DODGE_THIN_M
            and ss.thinRec ~= nil and ss.thinRec.on == true and ss.thinRec.phys < T.DODGE_THIN_M,
        string.format("彎中窄縫：兩條縫都掃得過時換物理淨距較寬的（承諾 %.2f、記下的窄縫 %s）", phys,
            tostring(ss.thinRec and ss.thinRec.phys)))
    -- 換成的寬縫以巡航 pad 掃過：不沿用先採納的窄縫（物理複驗＝爬行）的爬行旗標，速度不被爬行地板綁住
    checkTrue(ss.dodgeNeed >= ss.sweepBase - 1e-6 and ss.dodgeCrawl ~= true,
        "彎中窄縫：換成的寬縫是巡航檔、不帶窄縫的爬行旗標（dodgeCrawl=" .. tostring(ss.dodgeCrawl) .. "）")
end
driveReset(dveh)
driveTick(dp, dveh)
checkTrue(drive.calls.forceBrake > 0
        or (drive.calls.maxRegSpeed > 0 and drive.calls.maxRegSpeed <= 20),
    "彎中窄縫爬行承諾速度不超過 blocked approach 帶")
checkTrue(MDAD.Drive.isActive(0), "彎中窄縫：session 活著")
-- ⑨c 彎中真堵死（普通 needHalf 也無縫：七顆並排蓋過可行帶 ±5.6）
--    → blocked 煞停等待，這才是「不硬擠」的底線
drive.putSolid(77, 4, "harness_curve_obs_d")
drive.putSolid(83, 4, "harness_curve_obs_e")
drive.putSolid(75, 4, "harness_curve_obs_f") -- 走廊 ±7 後可行帶 ±5.6：堵死要排到 l≈±5
drive.putSolid(85, 4, "harness_curve_obs_g")
drive.scanRound()
-- 判堵那一輪的紅字照常（承諾那條也被新來的車蓋住）；之後同樣堵著的輪不得再轟（0828 契約：提示只在狀態轉換時）
driveReset(dveh)
drive.scanRound()
checkEq(haloKey(), nil, "已在 blocked 中不重複轟提示")
checkTrue(MDAD.Drive.isActive(0), "彎中堵死：session 活著（等待或玩家接手）")
drive.clearCell(75, 4)
drive.clearCell(77, 4)
drive.clearCell(79, 4)
drive.clearCell(80, 4)
drive.clearCell(81, 4)
drive.clearCell(83, 4)
drive.clearCell(85, 4)
drive.scanRound()
drive.scanRound() -- blocked 解除遲滯：連續兩輪 clear
driveReset(dveh)
driveTick(dp, dveh)
checkEq(dveh._regulator, true, "彎中障礙清除：自動恢復行駛")
MDAD.Drive.stop(0, nil)

-- ⑨b2 只剩窄縫（1004f 換縫找更寬的反面）：同一組彎中三車、另一側也堵住＝掃得過的只有物理淨距 0.2 的 +3.25——
-- 窄縫照過（09-01「物理可過就過」），不因為窄就判堵或改道。違規證明：找完不採納記下的窄縫（thinAdopt 恆回 false）＝紅。
function drive.scenarioThinOnly()
    dveh._x, dveh._y, dveh._speed, dveh._steering = 50, 0, 20, 0
    setHeading(dveh, 0.05)
    dp._vehicle, dveh._driver = dveh, dp
    checkTrue(MDAD.Drive.start(dp), "⑨b2 啟動")
    driveReset(dveh)
    local cells = { 79, 80, 81, 83, 84, 85 }
    for _, x in ipairs(cells) do drive.putSolid(x, 4, "harness_thin_" .. x) end
    drive.scanRound()
    local ss, T = MDAD.Drive.debugSession(0), MDAD.Drive.debugTune()
    local phys = (ss.dodgeMargin or -1) + (ss.dodgeNeed or 0) - ss.vehicleProfile.halfW
    checkTrue(ss.dodging == true and ss.blocked ~= true and phys >= 0 and phys < T.DODGE_THIN_M
            and (ss.fstate.offL or 0) > 0,
        string.format("⑨b2 只剩窄縫：照樣承諾那條窄縫（offL %s、物理淨距 %.2f）", tostring(ss.fstate.offL), phys))
    for _, x in ipairs(cells) do drive.clearCell(x, 4) end
    MDAD.Drive.stop(0, nil)
end
drive.scenarioThinOnly()

-- ⑨b3 replan 牆鐘遙測（1005 perf）：stepFollow 在 replan 前後各讀一次 getTimestampMs，最多每 TUNE.REPLAN_CLOCK_MS 量一次；
--   sweepLine 自己累加掃掠數。繞行承諾事件帶 wms（replan 開始到發事件的 ms，不是絕對時戳）／sweeps／hn；樣本 replanMs／
--   replanSweeps／replanHn 每次量測只寫一筆。(rpclk) 時鐘改成每讀一次走 1ms，wms 才量得到 >0。
--   (rpclk) 有量：承諾事件 wms ∈ [1, 1000)、sweeps ≥ 1、hn ≥ 1；樣本收到 replan 三欄。
--   (rpclk-throttle) 窗內（離上次量測 < REPLAN_CLOCK_MS）replan 照跑（掃掠數被歸零重數）但不量：量測時戳不動、樣本不出現 replan 欄。
--   (rpclk-reopen) 窗外再量一次，同一時戳的後續 replan 不再量＝樣本恰好一筆。
--   違規證明：拿掉節流＝(throttle) 紅；wms 改成絕對時戳＝(rpclk) 紅；sweepLine 不累加＝(rpclk) 紅；樣本不消費＝(throttle) 紅。
function drive.scenarioReplanClock()
    local oldEvent, oldSample, oldShould, oldClock = MDADDiagnostics.event, MDADDiagnostics.sample,
        MDADDiagnostics.shouldSample, getTimestampMs
    local events, physN, lastPhys = {}, 0, nil
    local nav = drive.nav
    local navRoute, navTx, navTy, navState = nav.route, nav.tx, nav.ty, nav.state -- armDrive 換直路；後面 ⑨d 沿用彎道路線
    MDADDiagnostics.event = function(_, name, a) events[#events + 1] = { name = name, a = a } end
    MDADDiagnostics.shouldSample = function() return true end
    MDADDiagnostics.sample = function(...)
        local p = select(32, ...)
        if type(p) == "table" and p.replanMs ~= nil then physN, lastPhys = physN + 1, p end
        return true
    end
    checkTrue(armDrive(), "(rpclk) 啟動")
    setHeading(dveh, 0.05)
    driveReset(dveh)
    local s = MDAD.Drive.debugSession(0)
    s.diag = true
    getTimestampMs = function() nowMs = nowMs + 1; return nowMs end
    drive.putSolid(20, 0, "harness_rpclk_barrel")
    drive.scanRound()
    local commit
    for i = #events, 1, -1 do
        local e = events[i]
        if e.name == "dodge" and e.a and e.a.phase == "commit" then commit = e.a; break end
    end
    checkTrue(commit ~= nil and type(commit.wms) == "number" and commit.wms >= 1 and commit.wms < 1000
            and type(commit.sweeps) == "number" and commit.sweeps >= 1 and type(commit.hn) == "number" and commit.hn >= 1,
        "(rpclk) 繞行承諾事件帶 replan 牆鐘（相對 replan 開始）、掃掠數與點數（wms=" .. tostring(commit and commit.wms)
        .. " sweeps=" .. tostring(commit and commit.sweeps) .. " hn=" .. tostring(commit and commit.hn) .. "）")
    checkTrue(physN >= 1 and lastPhys.replanMs >= 1 and lastPhys.replanSweeps >= 1 and lastPhys.replanHn >= 1,
        "(rpclk) 樣本收到 replan 牆鐘三欄（筆數 " .. physN .. "）")
    getTimestampMs = oldClock
    -- scanRound 先把 nowMs 推 300 再跑幀：量測時戳設在那一刻前 100ms＝窗內
    s.replanClockAt = nowMs + 300 - 100
    local clockAt0, physN0, evN0 = s.replanClockAt, physN, #events
    s.sweepCount = -5
    drive.scanRound()
    local evWms = false
    for i = evN0 + 1, #events do
        if events[i].a and events[i].a.wms ~= nil then evWms = true end
    end
    checkTrue(s.dodging == true and s.sweepCount ~= -5 and s.replanClockAt == clockAt0 and physN == physN0 and not evWms,
        "(rpclk-throttle) 窗內 replan 照跑但不讀時鐘、樣本不重寫（sweepCount=" .. tostring(s.sweepCount)
        .. " 樣本 +" .. (physN - physN0) .. "）")
    s.replanClockAt = nil
    drive.scanRound()
    checkTrue(s.replanClockAt == nowMs and physN == physN0 + 1 and lastPhys.replanMs == 0,
        "(rpclk-reopen) 窗外量一次、同一時戳不再量：樣本恰好一筆（+" .. (physN - physN0) .. "）")
    MDADDiagnostics.event, MDADDiagnostics.sample, MDADDiagnostics.shouldSample = oldEvent, oldSample, oldShould
    drive.clearCell(20, 0)
    MDAD.Drive.stop(0, nil)
    nav.route, nav.tx, nav.ty, nav.state = navRoute, navTx, navTy, navState
end
drive.scenarioReplanClock()

-- ⑨d 折點旁障礙（2026-09-01 契約更新）：comfort/squeeze 檔的長車前角 OBB
--    掃掠照樣否決斜切候選；但物理終審檔（probe need≈halfW、接受剮蹭）窄體
--    掃掠可過 → 擠過（Dodge，速度連續縮放）。舊「一律 blocked」實為 curveCap 假 0
--    誤兜住——curveCap 的職責是限速不是否決通行；真撞 contact fail-closed。
do
    dveh._x, dveh._y, dveh._speed, dveh._steering = 50, 0, 20, 0
    setHeading(dveh, 0.05)
    dp._vehicle, dveh._driver = dveh, dp
    checkTrue(MDAD.Drive.start(dp), "⑨d 啟動")
    driveReset(dveh)
    drive.putSolid(79, 3, "harness_corner_a") -- 貼著 L 折點（76,0→80,4 過渡段）
    drive.putSolid(80, 4, "harness_corner_b") -- 折點頂點
    drive.scanRound()
    checkEq(haloKey(), DKEY.DODGE,
        "⑨d 物理終審檔窄體掃掠可過：爬行擠過（curveCap 假 0 誤兜已廢）")
    driveReset(dveh)
    driveTick(dp, dveh)
    checkTrue(drive.calls.maxRegSpeed > 0 and drive.calls.maxRegSpeed <= DODGE_CAP_TEST,
        "⑨d 擠過供油（速度由 clearanceCap 連續縮放）")
    dveh._speed = 0
    driveReset(dveh)
    driveTick(dp, dveh)
    nowMs = nowMs + 4200
    driveTick(dp, dveh)
    checkTrue(MDAD.Drive.isActive(0), "⑨d 安全繞行保持 session")
    drive.clearCell(79, 3)
    drive.clearCell(80, 4)
    MDAD.Drive.stop(0, nil)
end

-- ⑨e 折點起步（2026-09-01 s048 實機定罪的回歸保護）：實機 59-pts snap route
--    的折點 verifyEnvelope 格為 0（κ 極限假象），GO 下 curve-coast 壓 0＝
--    起步死鎖（cap 要速度才放寬、速度要 cap>0）；修法＝GO＋tgt 0＋curve-coast
--    ＋非到站 → 抬 MIN_EXEC。harness 的 L 折點經 fillet 後 envelope > 0，
--    此案踩不到假 0 路徑（僅防折點起步倒退）；行為證明依 s048 實測 telemetry
--    （修後同場景 capReason 應出現 min-exec 且車起步）。
do
    dveh._x, dveh._y, dveh._speed, dveh._steering = 78, 1, 0, 0
    setHeading(dveh, 0.6) -- 折點過渡姿態（介於 +x 與 +y 之間）
    dp._vehicle, dveh._driver = dveh, dp
    checkTrue(MDAD.Drive.start(dp), "⑨e 折點起步")
    driveReset(dveh)
    drive.scanRound()
    driveTick(dp, dveh)
    driveTick(dp, dveh)
    checkTrue(drive.calls.maxRegSpeed ~= nil
            and drive.calls.maxRegSpeed >= MDADDynamics.MIN_EXEC_KMH,
        "折點速 0 起步：regulator 目標不得停在 (0, MIN_EXEC) 假 0（實得 "
        .. tostring(drive.calls.maxRegSpeed) .. "）")
    checkTrue(MDAD.Drive.isActive(0), "⑨e session 存活")
    MDAD.Drive.stop(0, nil)
end

-- ⑩ 首次繞行以 laneBias 為中心（driver→corridor 接線）：同一顆 (20,0) 障礙，
--    開靠右 1m 後 first-safe 右縫 +2.75 比左縫更近，先選右側，再同側外推至
--    comfort +3.50。offL 用 setOffset spy 觀察（halo／速度看不出側別）。
setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false,
    AutoDriveMaxSpeed = 40, RightLaneBias = 1 })
do
    local realSetOffset = MDADFollower.setOffset
    local spyOffL = nil
    MDADFollower.setOffset = function(st, a, b, c, d, off, ...)
        spyOffL = off
        return realSetOffset(st, a, b, c, d, off, ...)
    end
    checkTrue(armDrive(), "靠右繞行情境啟動")
    drive.putSolid(20, 0, "harness_bias_obs")
    drive.scanRound()
    MDADFollower.setOffset = realSetOffset
    checkEq(haloKey(), DKEY.DODGE, "靠右行駛遇中線障礙：照樣繞行")
    checkEq(spyOffL, 3.25, "首次繞行以 laneBias 為中心：選右側後同側外推至 comfort +3.25（needHalf 1.2）")
    drive.clearCell(20, 0)
    MDAD.Drive.stop(0, nil)
end

-- ⑩b 擋線判定以行駛線為中心（plan 第八參 baseL 接線）：路緣樹 (20,1)
--    對中心線不擋，對 bias=+1 的行駛線會擋。first-safe 是中心線 0，
--    comfort refinement 維持左側再推到 -0.75。這同時保留 offL=0 可用的
--    planner 契約；不得把它當 inactive 哨兵。
do
    local realSetOffset = MDADFollower.setOffset
    local spyOffL, spyRet = nil, nil
    MDADFollower.setOffset = function(st2, a, b, c, d, off, ...)
        spyOffL = off
        spyRet = realSetOffset(st2, a, b, c, d, off, ...)
        return spyRet
    end
    checkTrue(armDrive(), "路緣樹情境啟動")
    drive.putTree(20, 1, "vegetation_trees_01_9")
    drive.scanRound()
    MDADFollower.setOffset = realSetOffset
    checkEq(haloKey(), DKEY.DODGE, "路緣樹擋行駛線（不擋中線）：觸發繞行而非直行蹭樹")
    -- 0929j：樹幹照引擎放在格 +0.6、半徑 0.15（舊模型格心 0 半徑），行駛線那側多出的 0.15 讓 comfort 再外推一格
    checkEq(spyOffL, -0.75, "先借中心線，再同側外推 0.75m 取得 comfort 餘裕（needHalf 1.2）")
    checkEq(spyRet, true, "comfort offL 被 setOffset 接受")
    drive.clearCell(20, 1)
    MDAD.Drive.stop(0, nil)
end

-- ⑩c 側別記憶只限當前剖面（黏側修正）：群1 兩顆箱物堵死中線與左側 → 只能借
--    右外側；車駛過剖面末端後，群2 路緣樹只擋行駛線（中線可行）→ 新繞行段
--    必須回到以行駛線為基準選左側，再取 comfort -0.75。修正前 prefer 沿用
--    lastOffL 會黏在路肩——實機 2026-08-28 曾沿草地走完整段路。
do
    local realSetOffset = MDADFollower.setOffset
    local offs = {}
    local tuples = {}
    MDADFollower.setOffset = function(st2, a, b, c, d, off, ...)
        offs[#offs + 1] = off
        tuples[#tuples + 1] = string.format("a=%.1f d=%.1f off=%.2f", a, d, off)
        return realSetOffset(st2, a, b, c, d, off, ...)
    end
    checkTrue(armDrive(), "黏側情境啟動")
    -- 2026-09-04 起承諾線覆蓋到未載入區就延後 commit：群2（樹 65）的回線 d≈90
    -- 剛好頂到 5851 那片世界的東緣 90——把世界往東延到 130，讓這個案測的仍是黏側
    drive.fillWorld(-9, 130, -7, 90)
    drive.putSolid(20, -1, "harness_stick1")
    drive.putSolid(20, 0, "harness_stick2")
    drive.scanRound()
    checkEq(haloKey(), DKEY.DODGE, "群1 堵中線與左側：繞行")
    checkTrue(offs[#offs] ~= nil and offs[#offs] > 2,
        "群1 只剩右外側縫（實得 " .. tostring(offs[#offs]) .. "）")
    -- 2026-09-04 起過渡幾何按巡航意圖設計；0906c 起 dl 取車的實際橫向（車在 0、bias 1 → 側移
    -- 3.25 而非 2.25），剖面 d 延到 ≈52：車要推到剖面末端之外（55）、下一個障礙（65）仍在前方帶內。
    -- 1004e：車回到常駐線（bias 1）上——harness 不模擬橫移，留在 0 的話樹在「車位→常駐線」的斜切帶內，
    -- 斜切保持會讓車沿 0 直走過樹（不需要繞行），本案測的是剖面走完後在常駐線上的新繞行選側。
    dveh._x, dveh._y = 55, 1 -- beyond dynamic d≈51.9 while the next obstacle at x=65 stays ahead
    for _ = 1, 8 do driveTick(dp, dveh) end
    drive.clearCell(20, -1); drive.clearCell(20, 0)
    drive.putTree(65, 1, "vegetation_trees_02_1")
    drive.scanRound() -- 首輪收舊帶：clear 遲滯 +1
    drive.scanRound() -- 新帶掃到樹 → 新繞行段
    MDADFollower.setOffset = realSetOffset
    checkEq(offs[#offs], -0.75,
        "剖面走完後的新繞行回行駛線基準側，再取同側 comfort -0.75（全序列 "
        .. table.concat(tuples, " | ", 1, #tuples) .. "；halo=" .. tostring(haloKey())
        .. " n=" .. tostring(#offs) .. "）")
    drive.clearCell(65, 1)
    MDAD.Drive.stop(0, nil)
end
setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false, AutoDriveMaxSpeed = 40, RightLaneBias = 0 })

-- ⑩d 候選線起點＝車的實際橫向（0906c；s025 定罪：車在 1.66、bias 夾成 0.13，線從 0.13 起步，
--    cross-track 先把車往左拉 1.5m 再右切）。車停在 +1.5、常駐 bias 0、中線障礙 → 承諾線在 s0
--    的橫向必須是 1.5（不是 0），dodgeCommitDl＝|offL−1.5|。違規證明：startLaneOf 退回 baseL 即紅。
setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false, AutoDriveMaxSpeed = 40, RightLaneBias = 0 })
do
    checkTrue(armDrive(), "(⑩d) 車離常駐線 1.5m 情境啟動")
    setHeading(dveh, 0)
    dveh._y = 1.5
    driveReset(dveh)
    driveTick(dp, dveh) -- 投影更新 lastLatSigned
    drive.putSolid(20, 0, "harness_startlane_obs")
    drive.scanRound()
    local st = MDAD.Drive.debugSession(0)
    checkEq(haloKey(), DKEY.DODGE, "(⑩d) 中線障礙：繞行")
    checkTrue(st ~= nil and st.dodging == true and st.fstate.ovN and st.fstate.ovN >= 2,
        "(⑩d) 承諾線存在")
    if st and st.fstate.ovN and st.fstate.ovN >= 2 then
        local y0 = st.fstate.ovY[1]
        checkTrue(math.abs(y0 - 1.5) < 0.05,
            "(⑩d) 承諾線起點橫向＝車的實際橫向 1.5（實得 " .. tostring(y0) .. "）")
        local off = st.fstate.offL
        local want = math.abs(off - 1.5)
        checkTrue(math.abs(st.dodgeCommitDl - want) < 1e-6,
            "(⑩d) dodgeCommitDl＝|offL−車橫向|（offL=" .. tostring(off) .. " dl=" .. tostring(st.dodgeCommitDl) .. "）")
        -- 回線段仍回常駐 lane：線尾橫向 ≈ bias 0
        local yEnd = st.fstate.ovY[st.fstate.ovN]
        checkTrue(math.abs(yEnd) < 0.05,
            "(⑩d) 線尾回常駐 lane 0（實得 " .. tostring(yEnd) .. "）")
    end
    drive.clearCell(20, 0)
    dveh._y = 0
    MDAD.Drive.stop(0, nil)
end

-- ⑩e 繞行速度政策分檔（0906g）：貼縫的**安全分類**（爬行／緊縮）是幾何與物理
--    的既定事實，DODGE_TUNE 只准調「確定可過之後開多快」。舊測試只比對表值
--    與「brisk 整體帽高於 comfort」——那條在分類外洩時照樣綠（分類放寬本身就
--    會抬速度），隔離不了收益來源。改用純鉤 debugDodgeCaps 對同一份 profile／
--    姿態／候選跑真公式，0924h 起全部檔位同一張表（DODGE_TUNE）。
do -- 主 chunk local 槽已滿：state fake 全部建在函式內
local function scenarioDodgeStyle()
    local T = MDAD.Drive.debugTune()
    local TU = T.DODGE_TUNE -- 0924h 起全部檔位同一張繞行速度表
    local DY = MDADDynamics
    local LAT = 3.5   -- minLat：兩檔共用，風格不准動物理
    local VP = { wheelbase = 2.5, delta0Safe = 0.7, deltaVSafe = 0.25,
        maxSpeed = 120, halfL = 2, centerOfMassX = -0.5, centerOfMassZ = 0.25 }
    local function space(dl, avail, jerk)
        return DY.shiftSpaceSpeedCapKmh(dl, avail, LAT, VP.wheelbase,
            VP.delta0Safe, VP.deltaVSafe, VP.maxSpeed, jerk)
    end
    -- 獨立 state：只帶速度收口讀得到的欄位。gear／profile／vis 一律拉高，
    -- 讓每案被測的那一項真的綁定（真 session 的分類受掃掠與點雲牽動，
    -- 隔離不了風格）。
    -- exitDl＝commit 凍結的出口段最大側移（回線段走的橫向距離；省略＝與 entry
    -- 同側移，等同舊行為）。出口段那條腿的預算要用它算，不是拿 entry 的側移。
    local function mkState(entryLen, exitLen, dl, exitDl)
        exitDl = exitDl or dl
        local shortest = entryLen < exitLen and entryLen or exitLen
        local eCap = space(dl, entryLen, DY.LATERAL_JERK_MAX)
        local xCap = space(exitDl, exitLen, DY.LATERAL_JERK_MAX)
        return {
            gearCap = 40, profileEnvelope = 40,
            vehicleProfile = VP,
            dodgeClass = DY.DODGE_STATIC,
            dodgeCrawl = false, dodgeTight = false,
            dodgeCommitDl = dl, dodgeCommittedLength = shortest,
            dodgeShapeDl = dl, dodgeSpaceLat = LAT, dodgeExitDl = exitDl,
            dodgeEntryLength = entryLen, dodgeExitLength = exitLen,
            dodgeSpaceBaseCap = eCap < xCap and eCap or xCap,
        }
    end
    -- 跑一輪收口。style=nil＝沿用 state 現有的表與現有分類（連續輪）；
    -- 給了 style 就重置分類，用來做「同姿態只換風格」的隔離對照。
    local function caps(s, style, margin, commit, entryPassed)
        if style then
            s.dodgeCrawl, s.dodgeTight = false, false
        end
        s.dodgeMargin = margin
        local reason = MDAD.Drive.debugDodgeCaps(
            s, margin, 0, LAT, 60, commit, entryPassed or false)
        return s.dodgeSpeedCap, s.dodgeCrawl, reason
    end
    local function sh(dl, len) return 1.2 * dl / len end

    -- (A) 貼縫分類不看風格：0.14m 淨距對舒適 reserve 0.15 是「只能爬行過」的
    --     幾何事實。修正前 brisk 的 reserve 0.10 讓 0.14 還剩 0.04 餘額 →
    --     clearanceCap 5.66 > 0 → 完全不進爬行分類，一台「brisk」的車會以巡航
    --     分類（不吃 DODGE_CRAWL_ALIGN_RAD 對線閘、不吃減速延後）穿 0.14m 的縫。
    --     違規證明：分類條件改回讀 DODGE_TUNE.reserve → brisk 得 5.66 且 crawl=false。
    local sA = mkState(30, 30, 2)
    local capAc, crawlAc = caps(sA, "comfort", 0.14, true)
    local capAb, crawlAb = caps(sA, "brisk", 0.14, true)
    checkTrue(crawlAc, "(⑩e-A) 0.14m 淨距：comfort 判爬行")
    checkTrue(crawlAb, "(⑩e-A) 0.14m 淨距：brisk 同樣判爬行（風格不改安全分類）")
    checkNear(capAc, DY.clearanceCapKmh(0.14, 0, 0.3, LAT, sh(2, 30)), 1e-9,
        "(⑩e-A) 爬行承諾速＝clearanceCap(淨距, reserve 豁免 0, 0.3, minLat, 1.2·dl/L)")
    checkEq(capAb, capAc,
        "(⑩e-A) 同一縫兩檔逐位元同速 17.689：reserve 只在非爬行時才有差別")

    -- (B) 地板抬過的承諾：分類一律用固定基準 reserve 0.15 → 0.25m 淨距的
    --     clearanceCap 只有 8.777、低於第二檔地板 10 → 兩檔都抬到 10 並記爬行。
    --     兩條外洩路徑在這裡定罪：
    --     ① 分類讀風格 reserve → brisk 得 12.514 高於地板 → 不記爬行，車以
    --        巡航分類（不吃對線閘、不吃減速延後）跑 12.5 穿 0.25m 的縫；
    --     ② 抬地板後同輪就豁免 reserve 重算 → 19.2，比該給的地板放大 92%。
    --     dl 必須是 2：dl 3 讓兩種 reserve（5.85／8.34）都掉到地板下面，
    --     兩檔結果同為 10，① 的外洩就被掩蓋成綠。
    local sB = mkState(20, 20, 2)
    local capBc, crawlBc = caps(sB, "comfort", 0.25, true)
    local capBb, crawlBb = caps(sB, "brisk", 0.25, true)
    checkTrue(crawlBc, "(⑩e-B) 0.25m 淨距：comfort 記爬行")
    checkTrue(crawlBb, "(⑩e-B) 0.25m 淨距：brisk 同樣記爬行（12.514 不是通行資格）")
    checkNear(capBc, T.DODGE_CRAWL_MID_KMH, 1e-9,
        "(⑩e-B) comfort 承諾＝第二檔地板 DODGE_CRAWL_MID_KMH")
    checkEq(capBb, capBc, "(⑩e-B) brisk 逐位元同地板：風格不改抬升結果")
    -- 姿態鑑別力自檢：brisk 自算的 12.514 必須真的越過地板，否則本案退化成
    -- 恆真（同 dl 3 的失效模式），未來 retune 也會在這裡先紅。
    checkTrue(DY.clearanceCapKmh(0.25, TU.reserve, 0.3, LAT, sh(2, 20))
        > T.DODGE_CRAWL_MID_KMH + 1,
        "(⑩e-B) 姿態有鑑別力：brisk 自算值越過地板，兩檔差異可被觀察到")
    -- 守護輪照原邏輯浮動（單向鎖已退役、cap 隨剩餘線餘裕即時上調），
    -- 但已判爬行的承諾不得因為帽升上去就掉回巡航分類。
    local capBg, crawlBg = caps(sB, nil, 0.55, false)
    checkTrue(capBg > capBb + 1,
        "(⑩e-B) 守護輪餘裕變好：帽依原邏輯上調（實得 " .. tostring(capBg) .. "）")
    checkTrue(crawlBg, "(⑩e-B) 已爬行的承諾在守護輪不得降級回巡航")
    sB.episodeActive = true
    local recoveringCap = caps(sB, nil, 0.55, false)
    checkTrue(recoveringCap <= T.DODGE_CRAWL_MID_KMH,
        "(recover-crawl) 脫困後貼縫未過入口：guard 不得立即抬高爬行速度")
    local passedCap = caps(sB, nil, 0.55, false, true)
    checkTrue(passedCap > recoveringCap,
        "(recover-crawl) 真正通過入口並對正後，照既有保持段規則放行")

    -- (C) 反向護欄：修正不准把 brisk 的速度收益一起砍掉。0.30m 淨距兩檔都在
    --     地板 10 之上、由 clearanceCap 真正綁定 → reserve 差異必須傳到速度。
    --     違規證明：clearance 改吃固定 TUNE.DODGE_CLEARANCE_RESERVE → 兩檔同值。
    local sC = mkState(20, 20, 2)
    local capCc, crawlCc = caps(sC, "comfort", 0.30, true)
    local capCb, crawlCb = caps(sC, "brisk", 0.30, true)
    checkFalse(crawlCc, "(⑩e-C) 0.30m 淨距高於地板：comfort 是巡航承諾")
    checkFalse(crawlCb, "(⑩e-C) 0.30m 淨距高於地板：brisk 是巡航承諾")
    checkNear(capCc, DY.clearanceCapKmh(0.30, TU.reserve, 0.3, LAT, sh(2, 20)),
        1e-9, "(⑩e-C) comfort 巡航速＝clearanceCap 帶 comfort reserve 0.15")
    checkNear(capCb, DY.clearanceCapKmh(0.30, TU.reserve, 0.3, LAT, sh(2, 20)),
        1e-9, "(⑩e-C) brisk 巡航速＝clearanceCap 帶 brisk reserve 0.10")

    -- (D) jerk 放寬只給**最終**的 brisk 巡航：橫向 jerk 3 是「乘客不舒服但沒事」
    --     的預算，貼縫爬行／彎道緊縮的承諾本來就壓在幾何極限上，再放寬 jerk＝
    --     拿安全邊際換舒適預算。大餘裕 1.5m＋高其餘帽讓 spaceCap 真的綁定。
    --     違規證明：jerkCap 不看最終分類→ 後兩條變 36。
    local sD = mkState(20, 20, 2)
    local capDc = caps(sD, "comfort", 1.5, true)
    local capDb = caps(sD, "brisk", 1.5, true)
    checkEq(capDc, capDb, "(⑩e-D) 全部檔位同一張表：巡航空間帽同值（jerk 3）")
    checkNear(capDb, space(2, 20, TU.jerkCap), 1e-9,
        "(⑩e-D) brisk 巡航才准用 jerk 3 重算空間帽 36")
    sD.dodgeCrawl, sD.dodgeTight = true, false
    checkNear(caps(sD, nil, 1.5, true), space(2, 20, DY.LATERAL_JERK_MAX), 1e-9,
        "(⑩e-D) brisk＋爬行分類：空間帽退回 jerk 2 基準")
    sD.dodgeCrawl, sD.dodgeTight = false, true
    checkNear(caps(sD, nil, 1.5, true), space(2, 20, DY.LATERAL_JERK_MAX), 1e-9,
        "(⑩e-D) brisk＋彎道緊縮：空間帽退回 jerk 2 基準")

    -- (E) 守護輪的分類回授：commit 當下是巡航的承諾，守護輪量到縫縮進爬行
    --     區間就必須降爬行。修正前守護輪只算速度不動分類 → 車以巡航分類
    --     繼續走一條已經只能爬行的縫（爬行對線閘與減速延後全部落空）。
    --     0.25m：固定基準 8.777 < 地板 10 → 降爬行並鎖在 10。
    --     違規證明：守護輪分類讀 brisk reserve → 12.514 高於地板 → 留在巡航。
    local sE = mkState(20, 20, 2)
    local capEc, crawlEc = caps(sE, "brisk", 1.5, true)
    checkFalse(crawlEc, "(⑩e-E) 1.5m 大餘裕：brisk 巡航承諾")
    checkNear(capEc, space(2, 20, TU.jerkCap), 1e-9,
        "(⑩e-E) 巡航承諾由 brisk 空間帽綁定（36）")
    local capEg, crawlEg = caps(sE, nil, 0.25, false)
    checkTrue(crawlEg, "(⑩e-E) 守護輪 0.25m：固定基準低於地板 → 巡航承諾降爬行")
    checkNear(capEg, T.DODGE_CRAWL_MID_KMH, 1e-9,
        "(⑩e-E) 降爬行後速度＝地板，不是 brisk 自算的 12.514")
    checkTrue(capEg < capEc - 20, "(⑩e-E) 縫從 1.5m 縮到 0.25m：速度必須跟著掉")
    -- 反例：守護輪不得一律降級。0.40m 的固定基準 19.2 仍高於地板 → 維持巡航，
    --       否則「修好誤放」會變成「每個守護輪都誤降」，繞行全程被壓在 10。
    local sE2 = mkState(20, 20, 2)
    caps(sE2, "brisk", 1.5, true)
    local capEk, crawlEk = caps(sE2, nil, 0.40, false)
    checkFalse(crawlEk, "(⑩e-E) 守護輪 0.40m 固定基準仍高於地板：不得誤降爬行")
    checkTrue(capEk > T.DODGE_CRAWL_MID_KMH + 1,
        "(⑩e-E) 維持巡航的守護輪速度高於爬行地板")

    -- (F) 非法純量仍 fail-closed：分類重排不得把 dynamics-invalid 吃掉
    local sF = mkState(20, 20, 2)
    local capFm = caps(sF, "brisk", 0 / 0, true)
    checkEq(capFm, 0, "(⑩e-F) NaN 淨距：帽歸零、不承諾")
    sF.dodgeCrawl, sF.dodgeTight = false, false
    sF.dodgeMargin = 0.30
    local reasonFv = MDAD.Drive.debugDodgeCaps(sF, 0.30, 0, LAT, 0 / 0, true, false)
    checkEq(sF.dodgeSpeedCap, 0, "(⑩e-F) NaN 可視帽：帽歸零")
    checkEq(reasonFv, "dynamics-invalid", "(⑩e-F) fail-closed 具名，不吞成一般零帽")

    -- (G) entryPassed 只移除「已經走完的進入段」那條限制：12m 進入段對 2m 側移
    --     的空間帽 18.87 在車尾越過 offB 後已是歷史，20m 出口段的 31.45 才是
    --     還沒走的路。修正前 spaceCap 永久取兩段最小＝已走完的段一路壓速。
    local sG = mkState(12, 20, 2)
    local capGbefore = caps(sG, "comfort", 2.5, false, false)
    local capGafter = caps(sG, "comfort", 2.5, false, true)
    checkNear(capGbefore, space(2, 12, TU.jerkCap), 1e-9,
        "(⑩e-G) 未越過進入段：空間帽＝兩段最小（進入段）")
    checkNear(capGafter, space(2, 20, TU.jerkCap), 1e-9,
        "(⑩e-G) 越過進入段後：空間帽換成出口段")
    checkTrue(capGafter > capGbefore + 5, "(⑩e-G) 移除過期限制確實提速")
    -- 出口段才是短的那一段：越過進入段也不准放大出口段自己的帽
    local sG2 = mkState(20, 12, 2)
    local capG2before = caps(sG2, "comfort", 2.5, false, false)
    local capG2after = caps(sG2, "comfort", 2.5, false, true)
    checkEq(capG2after, capG2before,
        "(⑩e-G) 出口段短：越過進入段後仍受出口段原帽（不是無條件放寬）")
    checkNear(capG2after, space(2, 12, TU.jerkCap), 1e-9, "(⑩e-G) 該帽就是出口段 12m 的帽")

    -- (H) 越過進入段後 heading 項也要換成出口段實長，不能圖方便把 sinHeading
    --     壓到 0.05 下限——那會把 clearanceCap 從 22.19 吹到 53.25，等於用
    --     「幾乎不側移」的假設放行還沒走的出口段側移。
    local sH = mkState(12, 20, 2)
    local capHbefore = caps(sH, "comfort", 0.45, false, false)
    local capHafter = caps(sH, "comfort", 0.45, false, true)
    checkNear(capHbefore, DY.clearanceCapKmh(0.45, TU.reserve, 0.3, LAT, sh(2, 12)),
        1e-9, "(⑩e-H) 未越過：sinHeading 用兩段最小長 12m")
    checkNear(capHafter, DY.clearanceCapKmh(0.45, TU.reserve, 0.3, LAT, sh(2, 20)),
        1e-9, "(⑩e-H) 越過後：sinHeading 用出口段實長 20m（不是 0.05 下限）")
    checkTrue(capHafter < DY.clearanceCapKmh(0.45, TU.reserve, 0.3, LAT, 0.05) - 10,
        "(⑩e-H) sinHeading 沒有被壓到 0.05 下限（那會虛報 53.25）")

    -- (I) 出口段的側移不等於進入段的側移（0906h）：車已在常駐線外 1m、繞到 3、
    --     回線回 0 → 進入段只走 2m 橫向、出口段要走 3m。exitDl 是 commit 當下
    --     凍結的出口最大側移；越過進入段後兩個替代限制都必須換成它算：
    --     sinHeading 的分子取 max(commitDl, exitDl)、空間帽的側移取
    --     max(shapeDl, exitDl)。錯用進入段的 2m ＝ 用「側移比較小」的假設放行
    --     一段還沒走、而且側移更大的回線段。
    --     違規證明：分子留 commitDl → clearance 從 18.51 虛報成 27.76（+50%）。
    local sI = mkState(12, 20, 2, 3)
    local capIbefore = caps(sI, "brisk", 0.5, false, false)
    local capIafter = caps(sI, "brisk", 0.5, false, true)
    checkNear(capIbefore, DY.clearanceCapKmh(0.5, TU.reserve, 0.3, LAT, sh(2, 12)),
        1e-9, "(⑩e-I) 未越過：sinHeading 用承諾長 12m 與進入段側移 2m")
    checkNear(capIafter, DY.clearanceCapKmh(0.5, TU.reserve, 0.3, LAT, sh(3, 20)),
        1e-9, "(⑩e-I) 越過後：sinHeading 用出口段側移 3m／實長 20m（18.51）")
    checkTrue(capIafter < DY.clearanceCapKmh(0.5, TU.reserve, 0.3, LAT, sh(2, 20)) - 5,
        "(⑩e-I) 不得錯用進入段側移 2m（那會虛報成 27.76）")
    -- 空間帽側同一條契約：大餘裕讓 clearance 不綁定，出口段側移 3m 的預算才是上限
    local sI2 = mkState(12, 20, 2, 3)
    local capI2 = caps(sI2, "brisk", 3, false, true)
    checkNear(capI2, space(3, 20, TU.jerkCap), 1e-9,
        "(⑩e-I) 越過後空間帽用出口段側移 3m 的預算")
    checkTrue(capI2 < space(2, 20, TU.jerkCap) - 1,
        "(⑩e-I) 錯用進入段側移 2m 會高估出口段空間預算")
    -- exitDl 省略＝與 entry 同側移：舊 profile 不因新欄位改變任何既有帽
    local sI3 = mkState(12, 20, 2)
    checkEq(caps(sI3, "brisk", 3, false, true), space(2, 20, TU.jerkCap),
        "(⑩e-I) exitDl 等於 entry 側移時逐位元回到舊行為")

    local sJ = mkState(8, 8, 2)
    caps(sJ, "brisk", 0.30, false, true)
    checkTrue(sJ.dodgeSpeedCap >= 10 and sJ.dodgeHoldCap > sJ.dodgeSpeedCap + 5,
        "(⑩e-J) 入口已過：低帽升格不再短路保持段，窄點仍保留10地板")
end
scenarioDodgeStyle()
end

-- ⑩f entryPassed 資格 predicate（0906g；同 debugStayLook 的純鉤測法）：移除過期
--    限制的前提是「那段真的走完了、而且車確實貼在承諾線上」。任一證據缺失都
--    必須 false——這條鉤放行一次，速度收口就會拿還沒走完的進入段當歷史。
do -- 主 chunk local 槽已滿：state fake 全部建在函式內
local function scenarioEntryPassed()
    local NOW = 100000
    -- 承諾線沿 +x 直行（切線恆為 heading 0，避開折點的切線歸屬歧義）：
    -- offB=10 進入段末、offC=30 出口段起、offD=38；ov 弧長 0..40。
    -- 車尾門檻＝offB+halfL+|COMX|+|COMZ|+1＝10+2+0.5+0.25+1＝13.75。
    -- 點距必須取 production 的 MDADFollower.OV_STEP：predicate 以
    -- floor((lastSNow−ovS0)/OV_STEP)+1 取段，fixture 自己挑密度（舊版 ovN=5、
    -- 點距 10m）算出的 i=23 會直接越過 ovN，每一條正例都被索引閘擋成 false，
    -- 而反例變成「因越界而 false」的假綠——比全紅更難察覺。
    local function mkPhase()
        local step = MDADFollower.OV_STEP
        local fs = {
            offA = 2, offB = 10, offC = 30, offD = 38,
            ovS0 = 0, ovEndS = 40, ovX = {}, ovY = {},
        }
        fs.ovN = math.floor(fs.ovEndS / step) + 1
        for i = 1, fs.ovN do fs.ovX[i], fs.ovY[i] = (i - 1) * step, 0 end
        return {
            dodging = true, dodgeStay = false,
            profile = { styleName = "brisk", length = 100 },
            vehicleProfile = { halfW = 1, halfL = 2, centerOfMassX = -0.5, centerOfMassZ = 0.25,
                wheelbase = 2.5, delta0Safe = 0.7, deltaVSafe = 0.25, maxSpeed = 120 },
            fstate = fs,
            bodyReach = 3.75,
            lastSNow = 22, lastLatDev = 0.05, lastVehicleHeading = 0,
            dodgeMargin = 0.4,
            dodgeEntryLength = 12, dodgeExitLength = 20,
            dodgeSpaceLat = 3.5, dodgeShapeDl = 2, dodgeExitDl = 2,
            sensor = { ready = true, stamp = NOW - 100,
                unloaded = false, hardOverflow = false, scanEndS = 80 },
        }
    end
    local function phaseIs(mutate, want, label)
        local s = mkPhase()
        if mutate then mutate(s) end
        checkEq(MDAD.Drive.debugDodgeEntryPassed(s, NOW), want, "(⑩f) " .. label)
    end
    local DEG = math.pi / 180

    phaseIs(nil, true, "基準：車尾已越進入段、貼線、快照新鮮 → 具資格")
    -- 政策閘：只有真正在跑的繞行保持段（0924h 起不分檔位：一般檔同樣解除過期的進入段限速）
    phaseIs(function(s) s.profile.styleName = "comfort" end, true,
        "一般檔同樣具資格（使用者裁定：所有檔位繞行不保守低速）")
    phaseIs(function(s) s.dodgeStay = true end, false,
        "停留段不得提升（laneBias 已換成 offL，進入段概念不成立）")
    phaseIs(function(s) s.dodging = false end, false,
        "沒在繞行就沒有承諾線可談")
    -- 幾何閘：車尾（含質心偏移與 1m 餘量）真的越過 offB，且還在保持段內
    phaseIs(function(s) s.lastSNow = 13.75 end, false,
        "車尾剛好貼在門檻上＝還沒越過（比較是嚴格大於）")
    phaseIs(function(s) s.lastSNow = 13.8 end, true,
        "越過門檻即算越過（門檻不是保守亂設的一大截）")
    phaseIs(function(s) s.lastSNow = 13.5 end, false,
        "質心偏移必須計入門檻（漏算 |COMX|+|COMZ| 就會在 13.5 誤放）")
    phaseIs(function(s) s.lastSNow = 30 end, false,
        "已到出口段起點＝末端，出口段的限制還沒走完")
    phaseIs(function(s) s.lastSNow = 29.9 end, true,
        "保持段最後一公尺仍具資格")
    -- 對線閘：偏差對「承諾線」而言，不是對世界軸
    phaseIs(function(s) s.lastLatDev = 0.2 end, false,
        "橫向偏差 0.2 超過 0.15 絕對上限＝未對線")
    phaseIs(function(s) s.dodgeMargin, s.lastLatDev = 0.2, 0.12 end, false,
        "容差隨餘裕縮成 min(0.15, m/2)=0.10（寫死 0.15 會在薄縫誤放）")
    phaseIs(function(s) s.lastVehicleHeading = 6 * DEG end, false,
        "車頭與承諾線切線差 6° 超過 5°＝未對線")
    phaseIs(function(s) s.lastVehicleHeading = 4 * DEG end, true,
        "5° 內的常態姿態不罰")
    phaseIs(function(s)
        -- 每段仍是 OV_STEP 長（dx=dy=OV_STEP/√2），弧長與 ovEndS 保持自洽
        local d = MDADFollower.OV_STEP / math.sqrt(2)
        for i = 1, s.fstate.ovN do
            s.fstate.ovX[i], s.fstate.ovY[i] = (i - 1) * d, (i - 1) * d
        end
        s.lastVehicleHeading = 45 * DEG
    end, true, "承諾線轉 45°、車頭同轉：對線是對線不是對世界 X 軸")
    phaseIs(function(s)
        local d = MDADFollower.OV_STEP / math.sqrt(2)
        for i = 1, s.fstate.ovN do
            s.fstate.ovX[i], s.fstate.ovY[i] = (i - 1) * d, (i - 1) * d
        end
    end, false, "承諾線轉 45° 但車頭仍 0°：45° 夾角必須判未對線")
    -- 快照閘：缺證據一律 false（不知道 ≠ 淨空）
    phaseIs(function(s) s.sensor.ready = false end, false, "快照未就緒")
    phaseIs(function(s) s.sensor.stamp = 0 end, false, "首輪尚未掃描（stamp 0）")
    phaseIs(function(s) s.sensor.stamp = NOW - 800 end, false,
        "快照超過 750ms 新鮮度＝過期")
    -- 0906i：未載入前緣落在承諾線內（≤ offD）才是證據缺失；MP 110m 高速帶 2/3 時間帶尾
    -- 有未載入 chunk（session-055 unl=true 483/732），一律拒絕＝資格永遠不成立。
    phaseIs(function(s) s.sensor.unloaded = true end, false,
        "走廊內有未載入 chunk 且沒有前緣座標＝不知道在哪，不准提升")
    phaseIs(function(s) s.sensor.unloaded, s.sensor.unloadedS = true, 38 end, false,
        "未載入前緣剛好在 offD 上＝承諾線末端沒證據，不准提升")
    phaseIs(function(s) s.sensor.unloaded, s.sensor.unloadedS = true, 50 end, true,
        "未載入前緣在整條線與車身前伸之外，照常提升")
    phaseIs(function(s) s.sensor.unloaded, s.sensor.unloadedS = true, 0 / 0 end, false,
        "未載入前緣座標非數＝證據缺失")
    phaseIs(function(s) s.sensor.scanEndS = 39 end, false,
        "沒有未載入格也不能替未掃尾段提供提速證明")
    phaseIs(function(s) s.sensor.scanEndS = 43.6 end, false,
        "掃到線尾但未涵蓋車身前伸仍不提升")
    phaseIs(function(s) s.sensor.hardOverflow = true end, false,
        "硬點雲溢位＝快照不完整")
    -- 欄位不存在也是證據缺失：Sensor 若哪天忘了 publish hardOverflow，falsy 檢查
    -- 會讓這道閘永遠通過（實機再也不會因點雲溢位擋下提升）。要求明確的 false。
    phaseIs(function(s) s.sensor.hardOverflow = nil end, false,
        "hardOverflow 未發布＝證據缺失，不是「沒有溢位」")
    phaseIs(function(s) s.sensor.stamp = NOW + 100 end, false,
        "快照時間在未來（時鐘倒退）＝新鮮度算不得，fail-closed")
    phaseIs(function(s) s.sensor = nil end, false, "沒有快照")
    -- 線長閘：承諾線末端必須真的蓋到剖面（或路線終點）
    phaseIs(function(s) s.fstate.ovEndS = 37 end, false,
        "承諾線末端 37 不到 min(offD 38, 路線長)")
    -- 路線比剖面短：門檻必須是 min(offD, length)。ovEndS 33 蓋得住路線長 30、
    -- 蓋不住 offD 38——只看 offD 的實作會在這裡把路線終點前的合法承諾判死。
    phaseIs(function(s) s.profile.length, s.fstate.ovEndS = 30, 33 end, true,
        "路線比剖面短時門檻用路線長（min(offD 38, length 30)=30）")
    phaseIs(function(s) s.profile.length, s.fstate.ovEndS = 30, 29 end, false,
        "連路線長都蓋不到＝線不完整")
    -- 替代限制的輸入閘：算不出新限制就不准移除舊限制
    phaseIs(function(s) s.dodgeExitLength = nil end, false, "缺出口段長度")
    phaseIs(function(s) s.dodgeExitLength = 0 end, false, "出口段長度非正")
    phaseIs(function(s) s.dodgeEntryLength = nil end, false, "缺進入段長度")
    -- exitDl 是 commit 凍結的出口最大側移：沒有它就算不出出口段的替代限制，
    -- 不准拿進入段的側移頂替（那會用比較小的側移假設放行更大的回線側移）。
    phaseIs(function(s) s.dodgeExitDl = nil end, false, "缺出口段最大側移")
    phaseIs(function(s) s.dodgeSpaceLat = 0 end, false, "橫向加速度非正")
    phaseIs(function(s) s.dodgeShapeDl = -1 end, false, "側移量負值")
    phaseIs(function(s) s.dodgeShapeDl = 0 end, true, "零側移合法（shapeDl>=0）")
    phaseIs(function(s) s.vehicleProfile.centerOfMassX = 0 / 0 end, false,
        "質心偏移非有限＝門檻算不出來，fail-closed")
    phaseIs(function(s) s.fstate = nil end, false, "沒有剖面")
    phaseIs(function(s) s.vehicleProfile = nil end, false, "沒有車輛剖面")
    -- 承諾線 identity（0906c ⑩d 釘的契約）：predicate 只能讀，不准動 ov 陣列
    do
        local s = mkPhase()
        local fx, fy = {}, {}
        for i = 1, s.fstate.ovN do fx[i], fy[i] = s.fstate.ovX[i], s.fstate.ovY[i] end
        local n0, s00, e0 = s.fstate.ovN, s.fstate.ovS0, s.fstate.ovEndS
        MDAD.Drive.debugDodgeEntryPassed(s, NOW)
        MDAD.Drive.debugDodgeEntryPassed(s, NOW - 5000) -- 過期輪同樣不准動線
        local intact = s.fstate.ovN == n0 and s.fstate.ovS0 == s00
            and s.fstate.ovEndS == e0
        for i = 1, n0 do
            if s.fstate.ovX[i] ~= fx[i] or s.fstate.ovY[i] ~= fy[i] then intact = false end
        end
        checkTrue(intact, "(⑩f) predicate 不修改承諾線（ovN／ovS0／ovEndS／ovX／ovY 逐位元不動）")
    end
end
scenarioEntryPassed()
end

-- ⑩g entryPassed 端到端（0906g）：⑩e／⑩f 各自綠只證明「兩個純鉤自己算對」，
--    不證明 production 真的把 predicate 接上速度收口。這一案跑真 session、真掃描、
--    真承諾線：commit 在起點（車還在進入段內），再把車開進保持段中段重掃，
--    s.dodgeEntryPassed 必須自己翻 true，而且承諾線一個位元都不許動、空間帽不得
--    越過同一條線出口段的預算、曲率量測起點也要跟著搬。
--    違規證明：① 守護輪不傳 entryPassed／predicate 沒被呼叫 → 永遠 false、帽停在
--    兩段最小；② predicate 誤放 → comfort 對照也會翻 true；③ 提升時順手重建承諾線
--    → ovX／ovY 的 table identity 或 offA-D 的值會動；④ 曲率仍從整線起算 → κ 不變。
do -- 主 chunk local 槽已滿：所有 local 建在函式內
-- 中線硬列：ROW0 要近（讓進入段被 entryAvail 夾短、比出口段短才觀察得到提升），
-- ROW1 要遠（保持段長到能把車尾擺過 offB 又不到 offC）。下面兩條「fixture 可用性」
-- 會把量到的 offB／offC／entry／exit 印出來——紅了調這兩個數字，不要去手改
-- dodgeEntryPassed 或 fstate 欄位（那就退化成 ⑩f 的純鉤測法了）。
local ROW0, ROW1 = 14, 40
local function scenarioEntryPassedLive(styleName, tag, wantPassed)
    local oldGear, oldFrame = MDAD.Drive.getGear(0), drive.frameMs(8)
    MDAD.Drive.setGear(0, styleName == "comfort" and 3 or 4)
    -- 世界要蓋滿整條掃描走廊（route 40×4＝156m）：承諾線內的破洞會讓 sensor.unloaded
    -- 前緣落在 offD 之前，predicate 依約 false，本案要量的東西就被擋掉。
    drive.fillWorld(-4, 160, -8, 8)
    checkTrue(armDrive(), "(⑩g" .. tag .. ") 情境啟動")
    setHeading(dveh, 0)
    dveh._x, dveh._y, dveh._speed = 0, 0, 20
    driveReset(dveh)
    driveTick(dp, dveh) -- 投影更新 lastLatSigned
    for x = ROW0, ROW1 do drive.putSolid(x, 0, "harness_entrypass_row") end
    drive.scanRound() -- 首輪真掃描：commit 承諾線
    local st = MDAD.Drive.debugSession(0)
    local fs = st and st.fstate
    local armed = st ~= nil and st.dodging == true and fs ~= nil
        and type(fs.ovX) == "table" and type(fs.ovY) == "table" and (fs.ovN or 0) >= 3
    checkTrue(armed, "(⑩g" .. tag .. ") 首輪真掃描承諾出繞行線")
    if not armed then
        MDAD.Drive.setGear(0, oldGear)
        MDAD.Drive.stop(0, nil)
        drive.frameMs(oldFrame)
        return
    end
    checkFalse(st.dodgeEntryPassed,
        "(⑩g" .. tag .. ") commit 當輪車還在進入段內：不得提升")
    -- 承諾線 identity＋點值＋剖面 offsets 的快照
    local ovX, ovY, ovN = fs.ovX, fs.ovY, fs.ovN
    local xs, ys = {}, {}
    for i = 1, ovN do xs[i], ys[i] = ovX[i], ovY[i] end
    local ovS0, ovEndS = fs.ovS0, fs.ovEndS
    local offA, offB, offC, offD, offL = fs.offA, fs.offB, fs.offC, fs.offD, fs.offL
    local entryLen, exitLen = st.dodgeEntryLength, st.dodgeExitLength
    local dl, lat, vp = st.dodgeShapeDl, st.dodgeSpaceLat, st.vehicleProfile
    local spaceBefore, kappaBefore = st.dodgeSpaceCap, st.dodgeKappa
    -- exitDl 由 production 在 commit 當下凍結；fake 猜不到真值，預算一律用
    -- max(shapeDl, exitDl) 算，且先把「這個欄位真的有被凍結」當契約釘住。
    local exitDl = st.dodgeExitDl
    checkTrue(type(exitDl) == "number" and exitDl >= 0,
        "(⑩g" .. tag .. ") commit 凍結出口最大側移 dodgeExitDl（實得 "
        .. tostring(exitDl) .. "）")
    local budgetDl = dl
    if type(exitDl) == "number" and exitDl > budgetDl then budgetDl = exitDl end
    -- 車尾門檻＝halfL＋|COMX|＋|COMZ|＋1（predicate 的定義），再多 1.5m 才算真的
    -- 越過；同時必須落在 offC 之前，否則是末端而不是保持段中段。
    local rear = vp.halfL + math.abs(vp.centerOfMassX) + math.abs(vp.centerOfMassZ) + 1
    local targetS = offB + rear + 1.5
    checkTrue(targetS < offC - 0.5,
        "(⑩g" .. tag .. ") fixture 可用性：保持段容得下車尾越過點（offB="
        .. tostring(offB) .. " offC=" .. tostring(offC)
        .. " 目標 s=" .. tostring(targetS) .. "）")
    checkTrue(entryLen < exitLen - 1,
        "(⑩g" .. tag .. ") fixture 可用性：進入段需比出口段短，提升才觀察得到（entry="
        .. tostring(entryLen) .. " exit=" .. tostring(exitLen) .. "）")
    -- 把車開進保持段中段：橫向貼在承諾線的偏移上、車頭沿線（直路＝heading 0）
    dveh._x, dveh._y = targetS, offL
    setHeading(dveh, 0)
    driveTick(dp, dveh) -- 先讓投影更新 lastSNow／lastLatDev／lastVehicleHeading
    drive.scanRound()
    -- 觀測的必須是同一個 session（中途重啟會給一張新表，看起來也「對」）
    checkTrue(MDAD.Drive.debugSession(0) == st,
        "(⑩g" .. tag .. ") 保持段重掃沒有重啟 session")
    checkTrue(st.dodging == true, "(⑩g" .. tag .. ") 保持段重掃仍持有繞行承諾")
    -- 位置是真的開出來的（不是手改欄位）：車尾已越過 offB、還沒到 offC
    checkTrue(st.lastSNow > offB + rear and st.lastSNow < offC,
        "(⑩g" .. tag .. ") lastSNow 落在車尾越過點與 offC 之間（實得 "
        .. tostring(st.lastSNow) .. "）")
    checkTrue(math.abs(st.lastLatDev) <= math.min(0.15, st.dodgeMargin * 0.5),
        "(⑩g" .. tag .. ") 車確實對在承諾線上，兩檔差別只剩風格（latDev "
        .. tostring(st.lastLatDev) .. " 餘裕 " .. tostring(st.dodgeMargin) .. "）")
    checkEq(st.dodgeEntryPassed, wantPassed,
        "(⑩g" .. tag .. ") 保持段中段重掃：production 自己判定 entryPassed")
    -- 提升只准動速度：承諾線 table identity、點值、剖面 offsets 全部不動
    local intact = fs.ovX == ovX and fs.ovY == ovY and fs.ovN == ovN
        and fs.ovS0 == ovS0 and fs.ovEndS == ovEndS
        and fs.offA == offA and fs.offB == offB and fs.offC == offC
        and fs.offD == offD and fs.offL == offL
    for i = 1, ovN do
        if ovX[i] ~= xs[i] or ovY[i] ~= ys[i] then intact = false end
    end
    checkTrue(intact,
        "(⑩g" .. tag .. ") 承諾線 table identity／點值／offA-D 逐位元不變")
    -- 曲率只量兩段過渡（[offA,offB]／[offC,offD]）且從車尾起算：車尾越過 offB 後
    -- 進入段折角不再限速，保持段的路線彎本來就由 profile 曲率表管——與風格無關
    -- （0906i：整線 max 會讓彎道旁一根桿子的 tight 繞行把整條 20-50m 線壓在 15）。
    -- 這一條把 polylineKappaMax 的窗口契約接到真承諾線上，接線漏了會在這裡紅。
    local STEP = MDADFollower.OV_STEP
    local rearS = st.lastSNow - vp.halfL
    local function windowKappa(from, to)
        local lo = math.max(from, rearS, ovS0)
        if lo >= to then return 0 end
        return MDADDynamics.polylineKappaMax(ovX, ovY, ovN,
            math.floor((lo - ovS0) / STEP) + 1, math.floor((to - ovS0) / STEP) + 2)
    end
    checkTrue(rearS > offB, "(⑩g" .. tag .. ") 車尾已越過 offB：進入段窗口為空")
    checkNear(st.dodgeKappa, math.max(windowKappa(offA, offB), windowKappa(offC, offD)), 1e-9,
        "(⑩g" .. tag .. ") 守護 κ＝兩段過渡從車尾起量的最大值（實得 "
        .. tostring(st.dodgeKappa) .. "）")
    checkTrue(st.dodgeKappa < kappaBefore - 1e-6,
        "(⑩g" .. tag .. ") 駛過進入段後 κ 只剩出口段（commit κ=" .. tostring(kappaBefore)
        .. " → " .. tostring(st.dodgeKappa) .. "），風格無關")
    -- 速度：提升不得越過同一條線出口段的空間預算（風格 jerkCap＝最寬的上界，
    -- 分類若壓回 jerk 2 只會更低，所以這是與分類無關的真上界）。出口段的側移
    -- 用 max(shapeDl, exitDl)：回線側移比進入段大時，拿 entry 的側移算會高估。
    local exitBudget = MDADDynamics.shiftSpaceSpeedCapKmh(budgetDl, exitLen, lat,
        vp.wheelbase, vp.delta0Safe, vp.deltaVSafe, vp.maxSpeed, MDAD.Drive.debugTune().DODGE_TUNE.jerkCap)
    checkTrue(st.dodgeSpaceCap <= exitBudget + 1e-6,
        "(⑩g" .. tag .. ") 空間帽不越過同線出口段預算（帽 "
        .. tostring(st.dodgeSpaceCap) .. " ≤ " .. tostring(exitBudget) .. "）")
    if wantPassed then
        checkTrue(st.dodgeSpaceCap > spaceBefore + 0.5,
            "(⑩g" .. tag .. ") 提升確實放掉已走完的進入段限制（"
            .. tostring(spaceBefore) .. " → " .. tostring(st.dodgeSpaceCap) .. "）")
    else
        -- 未提升＝兩段各用自己的側移算，取最小那段
        local eBudget = MDADDynamics.shiftSpaceSpeedCapKmh(dl, entryLen, lat,
            vp.wheelbase, vp.delta0Safe, vp.deltaVSafe, vp.maxSpeed, MDAD.Drive.debugTune().DODGE_TUNE.jerkCap)
        local shortBudget = eBudget < exitBudget and eBudget or exitBudget
        checkTrue(st.dodgeSpaceCap <= shortBudget + 1e-6,
            "(⑩g" .. tag .. ") 不提升：空間帽仍受兩段較嚴的那段限制（帽 "
            .. tostring(st.dodgeSpaceCap) .. " ≤ " .. tostring(shortBudget) .. "）")
    end
    if wantPassed then
        -- 0907c 保持段帽（session-062 t=17-25「這裡還慢是正常的嗎」：餘裕 0.55、出口過渡被路口壓到
        -- 3.3m → sh 0.37 → clearance 10.6 綁死 32m 平行保持段）：entry 已過時另算 dodgeHoldCap
        -- ＝clearance 用 DODGE_HOLD_SH（平行行駛）、不吃出口的 space／curve；stepFollow 在保持段套
        -- min(holdCap, 對 offC 的 approach envelope 收到 dodgeSpeedCap)。
        do
            local T = MDAD.Drive.debugTune()
            local savedExitLen, savedExitDl, savedCommitDl = st.dodgeExitLength, st.dodgeExitDl, st.dodgeCommitDl
            st.dodgeExitLength, st.dodgeExitDl, st.dodgeCommitDl = 3.3, 1.0, 0.25
            local reason = MDAD.Drive.debugDodgeCaps(st, 0.55, st.dodgeKappa, st.safeLat, 72, false, true)
            checkEq(reason, nil, "(⑩g-hold) 短出口＋餘裕 0.55 的守護帽合成合法")
            checkTrue(st.dodgeSpeedCap < 14,
                "(⑩g-hold) 整線帽被出口 sh 綁在 ~10.6（實得 " .. tostring(st.dodgeSpeedCap) .. "）")
            local reserve = MDAD.Drive.debugTune().DODGE_TUNE.reserve
            local wantHold = MDADDynamics.dodgeSpeedCapKmh(st.gearCap, st.profileEnvelope, st.gearCap,
                MDADDynamics.clearanceCapKmh(0.55, reserve, 0.3, st.safeLat, T.DODGE_HOLD_SH), 72, st.dodgeClass)
            checkNear(st.dodgeHoldCap, wantHold, 1e-9,
                "(⑩g-hold) 保持段帽＝clearance(sh=DODGE_HOLD_SH) 與 gear／剖面／可視的 min（實得 "
                .. tostring(st.dodgeHoldCap) .. "）")
            checkTrue(st.dodgeHoldCap > st.dodgeSpeedCap + 8,
                "(⑩g-hold) 保持段帽明顯高於整線帽（" .. tostring(st.dodgeSpeedCap) .. " → "
                .. tostring(st.dodgeHoldCap) .. "）")
            -- 同一幀套用：保持段 applied＝min(holdCap, approach(offC−rs−halfL → dcap))
            st.dodgeEnvN = 0 -- 撤掉逐點證明，驗既有保持段包絡的回退路徑。
            driveReset(dveh)
            driveTick(dp, dveh)
            -- 對 offC 的 envelope 用 safeCoast（繞行帽只夾 regulator，斷油滑行才是做得到的減速）
            local toExit = MDADDynamics.approachCapKmh(offC - st.lastSNow - vp.halfL, st.dodgeSpeedCap, 0.5, st.safeCoast)
            checkTrue(st.safeCoast < st.safeBrake * T.APPROACH_BRAKE_FRAC, "(⑩g-hold) envelope 減速度＝safeCoast < safeBrake×0.7")
            local wantApplied = st.dodgeHoldCap < toExit and st.dodgeHoldCap or toExit
            checkNear(st.dodgeApproachCap, wantApplied, 1e-6,
                "(⑩g-hold) 保持段 applied＝min(holdCap, 對 offC 的 envelope)（實得 "
                .. tostring(st.dodgeApproachCap) .. "）")
            checkTrue(st.dodgeApproachCap > st.dodgeSpeedCap + 5,
                "(⑩g-hold) 保持段實際帽高於整線帽（違規證明：DODGE_HOLD_SH=1 即紅）")
            -- 未過 entry：holdCap＝cap（不放寬）
            MDAD.Drive.debugDodgeCaps(st, 0.55, st.dodgeKappa, st.safeLat, 72, false, false)
            checkNear(st.dodgeHoldCap, st.dodgeSpeedCap, 1e-9, "(⑩g-hold) entry 未過：holdCap＝cap")
            st.dodgeExitLength, st.dodgeExitDl, st.dodgeCommitDl = savedExitLen, savedExitDl, savedCommitDl
            MDAD.Drive.debugDodgeCaps(st, st.dodgeMargin, st.dodgeKappa, st.safeLat, 72, false, true)
        end
        -- 前方常駐線還有障礙，避免 exitClear 提前釋放；它在此刻的側偏線外。
        -- 車進入回線段後，已走完的 entry 不得因不再處於保持段而復活。
        local holdSpace = st.dodgeSpaceCap
        local farX = math.floor(offC + 8)
        drive.putSolid(farX, 0, "harness_entrypass_exit")
        dveh._x, dveh._y = offC + 0.25, offL
        setHeading(dveh, 0)
        driveTick(dp, dveh)
        drive.scanRound()
        checkTrue(st.dodging and fs.ovX == ovX and fs.ovY == ovY,
            "(⑩g) 進入回線段仍持有同一承諾線，未走提前釋放")
        checkTrue(st.lastSNow >= offC and st.dodgeEntryPassed,
            "(⑩g) 跨 offC 後記住 entry 已通過，不重新套回整線限制")
        checkNear(st.dodgeSpaceCap, holdSpace, 1e-9,
            "(⑩g) 回線段空間帽不因 entry 復活突然降低")
        drive.clearCell(farX, 0)
    end
    MDAD.Drive.setGear(0, oldGear)
    MDAD.Drive.stop(0, nil)
    drive.frameMs(oldFrame)
end
