-- ⑬ 世界軌跡與 debug 標記：一般玩家 active session 在 OnPostRender 以
-- renderIsoLine 畫單一半透明藍／黃線；DebugOverlay 只加紅／綠／橙 marker。
-- 關 debug 不影響線，route cutover 與 stop 都要立即清線。
drive.markerN = 0
drive.markerAlphaN = 0
drive.markerAlpha = nil
drive.worldLines = {}
drive.trajectoryVisible = true
drive.trajectoryWidth = 2
drive.renderPlayerNum = 0
MDAD.HUD = {
    trajectoryVisible = function() return drive.trajectoryVisible end,
    trajectoryWidth = function() return drive.trajectoryWidth end,
    manualResumeMs = function() return drive.resumeMs end,
    uturnMode = function() return drive.uturnMode end,
}
drive.renderPlayer = { getPlayerNum = function() return drive.renderPlayerNum or 0 end }
function getPlayer() return drive.renderPlayer end
function renderIsoLine(x, y, z, x2, y2, z2, thickness, r, g, b, a)
    local n = #drive.worldLines + 1
    drive.worldLines[n] = {
        x = x, y = y, z = z, x2 = x2, y2 = y2, z2 = z2,
        thickness = thickness, r = r, g = g, b = b, a = a,
    }
end
drive.overlayRenderBefore = #(eventHandlers.OnPostRender or {})
function getWorldMarkers()
    return {
        addGridSquareMarker = function(_, sq, r, g, b, doAlpha, size)
            drive.markerN = drive.markerN + 1
            local alive = true
            return {
                setAlpha = function(_, a)
                    drive.markerAlphaN = drive.markerAlphaN + 1
                    drive.markerAlpha = a
                end,
                remove = function()
                    if alive then
                        alive = false
                        drive.markerN = drive.markerN - 1
                    end
                end,
            }
        end,
    }
end
require "MDAD_Overlay"
checkEq(type(MDADOverlay), "table", "production client/MDAD_Overlay.lua 真的載入了")
-- (passive) 停止／手動接手後仍在導航：沿導航路線畫前方 52m（HUD 250ms 呼叫 updatePassive）。
--   路線 (0,0)→(30,0)→(30,40)，車在 (10,3)：線從投影點 (10,0) 起、過折點、止於 (30,32)。
--   不在駕駛座／關閉軌跡／沒目標＝不畫。違規證明：拿掉投影（從 pts[1] 起）或長度截斷即紅。
function drive.scenarioPassiveTrail()
    local savedApi = MinidoracatMiniMapAPI
    local target = true
    MinidoracatMiniMapAPI = {
        getNavTarget = function() if target then return 30, 40 end end,
        requestRoute = function() return { pts = { 0, 0, 30, 0, 30, 40 } }, "ok" end,
    }
    local driver = true
    local car = { getX = function() return 10 end, getY = function() return 3 end,
        getZ = function() return 0 end, isDriver = function() return driver end }
    local function lines()
        clearList(drive.worldLines)
        drive.renderPlayerNum = 0
        fire("OnPostRender")
        return drive.worldLines
    end
    MDADOverlay.updatePassive(0, {}, car)
    local ls = lines()
    local len, joined = 0, true
    for i = 1, #ls do
        len = len + math.sqrt((ls[i].x2 - ls[i].x) ^ 2 + (ls[i].y2 - ls[i].y) ^ 2)
        if i > 1 and (ls[i].x ~= ls[i - 1].x2 or ls[i].y ~= ls[i - 1].y2) then joined = false end
    end
    checkTrue(#ls == 2 and ls[1].x == 10 and ls[1].y == 0 and ls[1].x2 == 30 and ls[1].y2 == 0
            and math.abs(ls[2].y2 - 32) < 1e-9 and joined and math.abs(len - 52) < 1e-9,
        "(passive) 導航線從車的投影點起、沿路過折點、長 52m（段數 " .. #ls .. "、長 " .. len .. "）")
    driver = false
    MDADOverlay.updatePassive(0, {}, car)
    checkEq(#lines(), 0, "(passive) 不在駕駛座不畫")
    driver, drive.trajectoryVisible = true, false
    MDADOverlay.updatePassive(0, {}, car)
    checkEq(#lines(), 0, "(passive) 關閉軌跡顯示不畫")
    drive.trajectoryVisible, target = true, false
    MDADOverlay.updatePassive(0, {}, car)
    checkEq(#lines(), 0, "(passive) 沒有導航目標不畫")
    MinidoracatMiniMapAPI = savedApi
end
drive.scenarioPassiveTrail()
checkEq(#(eventHandlers.OnPostRender or {}), drive.overlayRenderBefore + 1,
    "Overlay 只註冊一個 OnPostRender 世界線 renderer")
checkTrue(type(MDADFollower.OV_STEP) == "number" and MDADFollower.OV_STEP > 0,
    "Follower 導出有效的 M6 折線步距供 Overlay 共用")
checkFalse(MDADOverlay.setTrajectoryWidth(0 / 0), "Overlay 拒絕 NaN 軌跡粗細")
checkTrue(MDADOverlay.setTrajectoryWidth(2), "Overlay 接受合法標準軌跡粗細")
local function testTrajectoryOverlay()
    setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false,
        AutoDriveMaxSpeed = 40, RightLaneBias = 0, DebugOverlay = false })
    checkTrue(armDrive(), "一般玩家軌跡情境啟動")
    drive.putRoad(0, 70, -2, 2)
    drive.putSolid(20, 0, "harness_ovl_obs")
    local overlayState = nil
    local realOverlayUpdate = MDADOverlay.update
    MDADOverlay.update = function(pn, s, ...)
        if pn == 0 then overlayState = s end
        return realOverlayUpdate(pn, s, ...)
    end
    drive.scanRound()
    MDADOverlay.update = realOverlayUpdate
    checkEq(type(overlayState), "table", "Driver 把 active session 交給 Overlay 更新")
    checkEq(drive.markerN, 0, "DebugOverlay 關閉：一般軌跡不建立 marker 圈")
    local savedProfile, savedFstate, savedSNow =
        overlayState.profile, overlayState.fstate, overlayState.lastSNow
    local fracProfile = MDADFollower.begin(
        { pts = { 0, 0, 30, 0, 30, 60 } }, 40, 2)
    while not MDADFollower.stepBuild(fracProfile, 4096) do end
    local fracX, fracY = {}, {}
    local fracN, fracS0, fracWhy, fracEnd = MDADFollower.buildOffsetLine(
        fracProfile, 5, 10, 16, 24, 30.4, -1.75, 0.3, fracX, fracY)
    local fracState = MDADFollower.newState()
    MDADFollower.setLaneBias(fracState, 0.3)
    checkEq(fracWhy, "ok", "fractional d=30.4 overlay line builds")
    checkNear(fracEnd, 31.4, 1e-12, "fractional overlay line keeps true ovEndS")
    checkTrue(MDADFollower.setOffset(fracState, 10, 16, 24, 30.4, -1.75,
        fracX, fracY, fracN, fracS0, fracEnd), "fractional overlay line commits")
    local queryS = 31.2
    local lastStart = fracS0 + (fracN - 2) * MDADFollower.OV_STEP
    local ft = (queryS - lastStart) / (fracEnd - lastStart)
    local expectX = fracX[fracN - 1] + (fracX[fracN] - fracX[fracN - 1]) * ft
    local expectY = fracY[fracN - 1] + (fracY[fracN] - fracY[fracN - 1]) * ft
    overlayState.profile, overlayState.fstate, overlayState.lastSNow =
        fracProfile, fracState, queryS
    MDADOverlay.update(0, overlayState, dveh, drive.cell, false)
    clearList(drive.worldLines)
    drive.renderPlayerNum = 0
    fire("OnPostRender")
    checkNear(drive.worldLines[1].x, expectX, 1e-6,
        "Overlay last interval x uses ovEndS-lastStart denominator")
    checkNear(drive.worldLines[1].y, expectY, 1e-6,
        "Overlay last interval y matches Follower exact fractional coordinate")
    overlayState.profile, overlayState.fstate, overlayState.lastSNow =
        savedProfile, savedFstate, savedSNow
    MDADOverlay.update(0, overlayState, dveh, drive.cell, false)

    clearList(drive.worldLines)
    drive.renderPlayerNum = 0
    fire("OnPostRender")
    checkTrue(#drive.worldLines > 10,
        "一般玩家 active session：OnPostRender 送出連續線段（實得 "
        .. tostring(#drive.worldLines) .. "）")
    local standardLineN = #drive.worldLines
    local standardFirst = drive.worldLines[1]
    local sawBlue, sawYellow, lineStyleOk = false, false, true
    for i = 1, #drive.worldLines do
        local ln = drive.worldLines[i]
        if not (ln.a > 0 and ln.a < 1 and ln.thickness == 3
                and (ln.x ~= ln.x2 or ln.y ~= ln.y2) and ln.z == ln.z2) then
            lineStyleOk = false
        end
        if ln.r < 0.3 and ln.g > 0.7 and ln.b > 0.8 then sawBlue = true end
        if ln.r > 0.8 and ln.g > 0.7 and ln.b < 0.3 then sawYellow = true end
    end
    checkTrue(lineStyleOk, "標準軌跡是單一 thickness=3 半透明直線")
    checkTrue(sawBlue, "正常 follower 段使用藍線")
    checkTrue(sawYellow or not overlayState.dodging,
        "yellow is emitted exactly when the dynamic candidate is committed")

    drive.trajectoryWidth = 1
    drive.scanRound(true)
    clearList(drive.worldLines)
    fire("OnPostRender")
    local thinLineN = #drive.worldLines
    local thinFirst = drive.worldLines[1]
    checkEq(thinLineN, standardLineN, "細／標準每段都只提交一條線")
    checkTrue(thinFirst and thinFirst.thickness == 1, "細線使用 thickness=1")
    checkNear(thinFirst.x, standardFirst.x, 1e-6, "改粗細不改軌跡 x")
    checkTrue(type(thinFirst.y) == "number", "細線軌跡 y 保持有限")

    drive.trajectoryWidth = 3
    drive.scanRound(true)
    clearList(drive.worldLines)
    fire("OnPostRender")
    checkEq(#drive.worldLines, thinLineN, "粗線仍是每段單次 client draw")
    checkTrue(drive.worldLines[1].thickness == 7, "粗線使用 thickness=7")
    checkNear(drive.worldLines[1].x, thinFirst.x, 1e-6, "粗線仍沿同一條中心軌跡 x")
    checkTrue(type(drive.worldLines[1].y) == "number", "粗線中心軌跡 y 保持有限")
    drive.trajectoryWidth = 0 / 0
    drive.scanRound(true)
    clearList(drive.worldLines)
    fire("OnPostRender")
    checkTrue(drive.worldLines[1].thickness == 3, "NaN 軌跡粗細退回標準 thickness=3")

    drive.trajectoryVisible = false
    drive.scanRound()
    clearList(drive.worldLines)
    fire("OnPostRender")
    checkEq(#drive.worldLines, 0, "關閉顯示軌跡：active session 也不提交線段")
    drive.trajectoryVisible = true
    drive.trajectoryWidth = 2
    drive.scanRound()

    setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false,
        AutoDriveMaxSpeed = 40, RightLaneBias = 0, DebugOverlay = true })
    drive.scanRound()
    checkTrue(drive.markerN > 10,
        "DebugOverlay 開啟：紅／綠診斷 markers 額外出現（實得 "
        .. tostring(drive.markerN) .. "）")
    checkTrue(drive.markerAlphaN > 0 and drive.markerAlpha == 1,
        "Debug marker 建立後立刻 setAlpha(1)，FBO 路徑不隱形")
    local slot0Markers = drive.markerN
    MDADOverlay.update(1, overlayState, dveh, drive.cell, true)
    checkTrue(drive.markerN > slot0Markers,
        "split slot1 debug markers 與 slot0 並存（實得 "
        .. tostring(slot0Markers) .. "→" .. tostring(drive.markerN) .. "）")
    MDADOverlay.clear(0)
    checkTrue(drive.markerN > 0, "清 slot0 不會抹掉 slot1 debug markers")
    clearList(drive.worldLines)
    drive.renderPlayerNum = 1
    fire("OnPostRender")
    checkTrue(#drive.worldLines > 0, "清 slot0 後 slot1 viewport 軌跡仍存在")
    MDADOverlay.clear(1)
    checkEq(drive.markerN, 0, "清 slot1 後 split debug markers 才歸零")
    MDADOverlay.update(0, overlayState, dveh, drive.cell, true)
    clearList(drive.worldLines)
    drive.renderPlayerNum = 0
    fire("OnPostRender")
    checkTrue(#drive.worldLines > 0, "DebugOverlay 開啟時一般藍／黃線仍照畫")

    setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false,
        AutoDriveMaxSpeed = 40, RightLaneBias = 0, DebugOverlay = false })
    drive.scanRound()
    checkEq(drive.markerN, 0, "DebugOverlay 關閉：debug markers 全清")
    clearList(drive.worldLines)
    fire("OnPostRender")
    checkTrue(#drive.worldLines > 0, "關閉 debug 不會關掉一般玩家軌跡線")

    drive.nav.route = newRoute(300, 0, 0, 4, 0)
    nowMs = nowMs + 300
    driveReset(dveh)
    driveTick(dp, dveh)
    clearList(drive.worldLines)
    fire("OnPostRender")
    checkEq(#drive.worldLines, 0, "route cutover 建構期：舊軌跡立即清除")
    drive.scanRound()
    clearList(drive.worldLines)
    fire("OnPostRender")
    checkTrue(#drive.worldLines > 0, "新 route 首輪完成：軌跡線重新出現")

    MDAD.Drive.stop(0, nil)
    clearList(drive.worldLines)
    fire("OnPostRender")
    checkEq(#drive.worldLines, 0, "停止自駕：下一 viewport render 不再提交軌跡線")
    checkEq(drive.markerN, 0, "停止自駕：debug markers 亦全清")
    drive.clearCell(20, 0)
    drive.fillWorld(-2, 70, -7, 7)
end
testTrajectoryOverlay()
setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false, AutoDriveMaxSpeed = 40, RightLaneBias = 0 })

-- ⑪ 調頭安全探測：原地耦力旋轉前先探車周 3m——淨空＝耦力（衝量幀間反向、
--    中心力抵消不橫滑）；有牆＝退回橫推大弧（衝量幀間同向；爬行前進轉，
--    空間不夠自然由卡死→脫困鏈接手）。車頭朝西（誤差 180°）：側向＝世界 z 軸。
checkTrue(armDrive(), "調頭探測情境啟動")
dveh._x, dveh._y, dveh._speed = 10, 0, 0
setHeading(dveh, math.pi)
driveTick(dp, dveh)                -- 投影跟上＋第一次車周探測（淨空）
driveReset(dveh)
driveTick(dp, dveh)
do
    local i1 = dveh._imp.z
    driveTick(dp, dveh)
    checkTrue(i1 ~= 0 and dveh._imp.z ~= 0 and i1 * dveh._imp.z < 0,
        "車周淨空：耦力調頭＝衝量幀間反向（實得 " .. tostring(i1) .. " / "
        .. tostring(dveh._imp.z) .. "）")
    -- 溫和檔（預設）探測淨空＝原地轉：目標壓到 crawl 4（< spin 5，不會加速到 Follower 的 12
    -- 又切回大弧）；快速檔 crawl 12＝Follower 值。首輪 sensor 未 warm 目標本來就 0，
    -- 先跑一輪掃描讓 Follower 的 12 成為基準，斷言才有鑑別力（拿掉夾限＝12）。
    drive.scanRound()
    driveTick(dp, dveh)
    checkEq(dveh._regSpeed, 4, "溫和檔車周淨空原地轉：定速目標＝crawl 4（不是 Follower 的 12）")
    drive.putSolid(12, 0, "harness_rot_wall") -- 格心 (12.5,0.5) 距車 2.5m：半徑 3 內
    nowMs = nowMs + 600                       -- 跨過 500ms 探測節流
    driveTick(dp, dveh)                       -- 重探：不淨空
    driveReset(dveh)
    driveTick(dp, dveh)
    local j1 = dveh._imp.z
    driveTick(dp, dveh)
    checkTrue(j1 ~= 0 and dveh._imp.z ~= 0 and j1 * dveh._imp.z > 0,
        "車周 3m 有牆：退回橫推大弧＝衝量幀間同向（實得 " .. tostring(j1) .. " / "
        .. tostring(dveh._imp.z) .. "）")
end
-- 車周有「cell 清單的靜止車」（MP 靜止車在逐格 movingObjects 不可靠——
-- 2026-08-28 實機：探測回 clear、原地旋轉直接撞上旁邊的救護車）：
-- 全域列舉必須抓到 → 退大弧（衝量幀間同向）
do
    drive.clearCell(12, 0)
    drive.cellVehicles[1] = { getX = function() return 13 end,
        getY = function() return 1 end, isStopped = function() return true end }
    nowMs = nowMs + 600
    driveTick(dp, dveh)                       -- 重探：cell 車輛清單命中
    driveReset(dveh)
    driveTick(dp, dveh)
    local k1 = dveh._imp.z
    driveTick(dp, dveh)
    checkTrue(k1 ~= 0 and dveh._imp.z ~= 0 and k1 * dveh._imp.z > 0,
        "車周 3m 有 cell 清單的車（movingObjects 掃不到）：退大弧（實得 "
        .. tostring(k1) .. " / " .. tostring(dveh._imp.z) .. "）")
    drive.cellVehicles[1] = nil
end
-- 樹（COST_HARD_THIN 細桿）也擋調頭：探測曾只認 COST_HARD，樹旁判「淨空」
-- 原地旋轉直接掃到樹（2026-08-28 實機）。樹格心 (13.5,1.5) 距車 3.8m——
-- 舊半徑 3 掃不到、新半徑 4 必須掃到 → 退大弧
do
    drive.putTree(13, 1, "harness_rot_tree")
    nowMs = nowMs + 600
    driveTick(dp, dveh)                       -- 重探：樹命中
    driveReset(dveh)
    driveTick(dp, dveh)
    local t1 = dveh._imp.z
    driveTick(dp, dveh)
    checkTrue(t1 ~= 0 and dveh._imp.z ~= 0 and t1 * dveh._imp.z > 0,
        "車周 4m 有樹（細桿硬障礙）：退大弧（實得 "
        .. tostring(t1) .. " / " .. tostring(dveh._imp.z) .. "）")
    drive.clearCell(13, 1)
end
drive.clearCell(12, 0)
MDAD.Drive.stop(0, nil)

-- =====================================================================
-- 情境二十八b：immutable DODGE 承諾語意＋停等豁免（2026-08-28 對抗審紅測試）
-- =====================================================================
scenario("immutable 承諾：單次 setOffset／大側偏不誤判 offroad／停等不倒車")

-- (a) 同一承諾期只呼叫一次 setOffset：承諾後世界變化（不擋剖面線）只走
--     守護驗證，不重新提案——「每輪重規劃可覆寫執行中的承諾」正是實測
--     offL 逐輪翻面震盪的結構性根因
do
    local realSetOffset = MDADFollower.setOffset
    local spyN = 0
    MDADFollower.setOffset = function(st2, a2, b2, c2, d2, off, ...)
        spyN = spyN + 1
        return realSetOffset(st2, a2, b2, c2, d2, off, ...)
    end
    checkTrue(armDrive(), "(a) 啟動")
    drive.putSolid(20, 0, "harness_imm_a")
    drive.scanRound()
    checkEq(spyN, 1, "(a) 首次提案：setOffset 恰一次")
    -- 帶內新增一顆不擋剖面線的障礙：sig 變、replan 進來，但承諾不可變
    drive.putSolid(24, 3, "harness_imm_b")
    drive.scanRound()
    drive.scanRound()
    MDADFollower.setOffset = realSetOffset
    checkEq(spyN, 1, "(a) 承諾期間 sig 變化不重新提案（setOffset 仍恰一次）")
    checkTrue(MDAD.Drive.isActive(0), "(a) 承諾期間 session 活著")
    drive.clearCell(20, 0)
    drive.clearCell(24, 3)
    MDAD.Drive.stop(0, nil)
end

-- (b) 合法大側偏剖面跟隨不觸發 offroad：甩出量＝|latSigned−期望線|——
--     舊判法量「到中心線距離」>4，|offL|>4 的合法繞行會自己觸發 offroad
--     →清剖面→回線→再繞行的鋸齒循環，這種縫永遠執行不完
do
    local realSetOffset = MDADFollower.setOffset
    local spyOffL = nil
    MDADFollower.setOffset = function(st2, a2, b2, c2, d2, off, ...)
        spyOffL = off
        return realSetOffset(st2, a2, b2, c2, d2, off, ...)
    end
    checkTrue(armDrive(), "(b) 啟動")
    for y = -3, 4 do drive.putSolid(20, y, "harness_wide_" .. y) end
    drive.scanRound()
    MDADFollower.setOffset = realSetOffset
    checkEq(haloKey(), DKEY.DODGE, "(b) 寬障礙：外側縫繞行")
    checkTrue(type(spyOffL) == "number" and (spyOffL > 4 or spyOffL < -4),
        "(b) 縫在大側偏（|offL|>4；實得 " .. tostring(spyOffL) .. "）")
    -- 車擺在剖面保持段的期望位置：dev≈0 → 不觸發 offroad，也不額外壓到 15
    dveh._x = 20
    dveh._y = spyOffL
    driveTick(dp, dveh) -- 投影跟上（40m 路線段長 10m、前向搜索 12 段）
    driveReset(dveh)
    driveTick(dp, dveh)
    local hasOffroad = false
    for _, l in ipairs(drive.logs) do
        if l:find("offroad", 1, true) then hasOffroad = true end
    end
    checkFalse(hasOffroad, "(b) 沿剖面大側偏：不誤判 offroad（無掃回 log）")
    checkTrue(drive.calls.maxRegSpeed >= 0 and drive.calls.maxRegSpeed <= 28,
        "(b) committed large offset remains within dynamic cap")
    -- 對照組：同一 s、真甩出（偏離期望線再 6m、更外側的草地）→ offroad 掃回
    dveh._y = spyOffL < 0 and spyOffL - 6 or spyOffL + 6
    driveTick(dp, dveh) -- 觸發幀：offroad 設立並清 dodging（當幀 dodge cap 已先套）
    driveReset(dveh)
    driveTick(dp, dveh)
    -- 2026-09-02 契約翻轉（s046 彎中每次進 RETURN 都煞到 1 km/h）：pending＝
    -- unsafe crawl（≤RETURN_UNSAFE_CAP、不主動煞停），回線走不走由下一輪快照決定；
    -- 舊制「無 fresh lane proof 即 HOLD／target 0／forceBrake」退役。
    checkEq(MDAD.Drive.controlState(0), "RETURN",
        "(b) 真甩出進 RETURN pending（unsafe crawl 的 derived RETURN，非 HOLD）")
    checkTrue(drive.calls.maxRegSpeed > 0
            and drive.calls.maxRegSpeed <= TUNE_RETURN_UNSAFE_CAP_TEST + 1e-9,
        "(b) pending 期間 crawl ≤ RETURN_UNSAFE_CAP（實得 " .. tostring(drive.calls.maxRegSpeed) .. "）")
    checkEq(drive.calls.forceBrake, 0, "(b) pending 不主動煞停（無 forceBrake）")
    for y = -3, 4 do drive.clearCell(20, y) end
    MDAD.Drive.stop(0, nil)
end

-- (b2) 承諾中的 dodge 不被 RETURN 殺掉（2026-09-04 s051 st404.7：offL 2.00 陡剖面的追蹤
--      誤差 2-3m 超過 available 2 → RETURN enter 釋放承諾 → 同輪 replan 全滅 → blocked →
--      5 秒後 StopStuck）。繞行中 RETURN 門檻＝RETURN_DODGE_DEV(4)：偏 3m 仍是 dodge 持有；
--      (b) 的 +6m 真甩出照舊交 RETURN。
do
    checkTrue(armDrive(), "(b2) 啟動")
    for y = -3, 4 do drive.putSolid(20, y, "harness_wide2_" .. y) end
    drive.scanRound()
    checkEq(haloKey(), DKEY.DODGE, "(b2) 寬障礙：外側縫繞行")
    local st = MDAD.Drive.debugSession(0)
    local offL = st.fstate.offL
    dveh._x = 20
    dveh._y = offL + (offL < 0 and 3 or -3) -- 偏離期望線 3m（> available 2、< RETURN_DODGE_DEV 4）
    driveTick(dp, dveh)
    driveReset(dveh)
    driveTick(dp, dveh)
    checkTrue(st.dodging == true, "(b2) 偏 3m：dodge 承諾仍持有（實得 dodging=" .. tostring(st.dodging) .. "）")
    checkTrue(st.returnActive ~= true, "(b2) 偏 3m：RETURN 不進入（實得 " .. tostring(st.returnActive) .. "）")
    checkTrue(MDAD.Drive.controlState(0) ~= "RETURN", "(b2) controlState 非 RETURN（實得 " .. tostring(MDAD.Drive.controlState(0)) .. "）")
    for y = -3, 4 do drive.clearCell(20, y) end
    MDAD.Drive.stop(0, nil)
end

-- (c) 停等豁免：blocked 煞停是合法等待。2026-09-01 新契約：5 秒仍無縫會嘗試
--     倒退重掃（BLOCK_RETRY），但此 fixture 後方也是牆（車隊裡倒車危險的
--     具象化）＝rear hard 不退、繼續合法停等；獨立超時 15s 才紅字停用。
--     0908a 階梯縮帶起後牆要貼在車尾 0.8m（x=7；1.5m 最短帶也命中）才是「一寸不退」；
--     車尾後 4m 的牆（舊 x=4）現在會退 1.5m——見 (c4b)。
do
    local oldClient, oldServer = clientFlag, serverFlag
    clientFlag, serverFlag = false, false
    drive.pauseCalls, drive.pauseVehicle = 0, dveh
    checkTrue(armDrive(), "(c) 啟動")
    for _, y in ipairs({ -5, -4, -2, -1, 0, 1, 2, 4, 5 }) do
        drive.putSolid(20, y, "harness_wall_" .. y)
    end
    for _, y in ipairs({ -1, 0, 1 }) do
        drive.putSolid(7, y, "harness_rearwall_" .. y)
    end
    -- 先進入 blocked 的 10m 煞停線（BLOCK_STOP_DIST 2026-09-01 15→10）；
    -- 更遠仍屬 target=20 接近段，不適合驗 target=0 的合法停等豁免。
    dveh._x = 11
    driveTick(dp, dveh)
    drive.scanRound()
    checkEq(haloKey(), DKEY.BLOCKED, "(c) 堵死紅字")
    dveh._speed = 0 -- 車停妥（blocked 等待）
    driveReset(dveh)
    driveTick(dp, dveh)  -- 停等預算起算
    nowMs = nowMs + 6000 -- 6 秒 > STUCK_MS 5 秒：舊行為此刻已倒車脫困
    driveTick(dp, dveh)
    checkTrue(MDAD.Drive.isActive(0), "(c) 停等 6 秒：session 活著（不 unstick 不放棄）")
    checkTrue(haloKey() ~= DKEY.UNSTICK and haloKey() ~= DKEY.STUCK,
        "(c) 停等 6 秒：無倒車／放棄提示（實得 " .. tostring(haloKey()) .. "）")
    checkFalse(isGamePaused(), "(pause) 暫時堵路仍允許脫困，不提早暫停")
    nowMs = nowMs + 15000 -- 累計 21 秒 > WAIT_TIMEOUT 15 秒
    -- 0904i 診斷提示：診斷開著時 StopStuck 不附提示（本場開、(c3) 關、(d) 驗不重複）
    MDAD.HUD.telemetryEnabled = function() return true end
    driveTick(dp, dveh)
    checkTrue(not MDAD.Drive.isActive(0), "(c) 停等逾 20 秒：超時停用（交還玩家）")
    checkEq(haloKey(), DKEY.STUCK, "(c) 超時紅字 StopStuck")
    checkEq(drive.infoHaloIndex(), nil, "(c) 診斷已開：StopStuck 不附診斷提示")
    MDAD.HUD.telemetryEnabled = nil
    checkEq(drive.lastVoice(), "handback", "(c) 超時交還開口 handback，不是 stop")
    checkTrue(isGamePaused(), "(pause) 單人脫困失敗預設暫停")
    checkEq(drive.pauseCalls, 1, "(pause) 最終交還只暫停一次")
    checkFalse(drive.pauseHadSession, "(pause) 暫停前已清除自駕 session")
    checkFalse(drive.pauseHadRegulator, "(pause) 暫停前已關閉定速")
    drive.paused = false -- 玩家解除暫停，不應復活已結束的自駕
    nowMs = nowMs + 3000
    driveTick(dp, dveh)
    checkFalse(MDAD.Drive.isActive(0), "(pause) 解除暫停後仍須手動重啟自駕")
    checkFalse(dveh._regulator, "(pause) 解除暫停後不自動供油")
    clientFlag, serverFlag = oldClient, oldServer
    drive.pauseVehicle = nil
    for _, y in ipairs({ -5, -4, -2, -1, 0, 1, 2, 4, 5 }) do drive.clearCell(20, y) end
    for _, y in ipairs({ -1, 0, 1 }) do drive.clearCell(7, y) end
end

-- (c4) 倒車中途後方探到障礙（2026-09-04 s051/s052「第二次也太早停了」）：已退過
--      UNSTICK_MIN_M＝當一次成功脫困進 settle（重掃），不交還、不算失敗。
do
    checkTrue(armDrive(), "(c4) 啟動")
    for _, y in ipairs({ -5, -4, -2, -1, 0, 1, 2, 4, 5 }) do
        drive.putSolid(20, y, "harness_c4_wall_" .. y)
    end
    dveh._x = 11
    driveTick(dp, dveh)
    drive.scanRound()
    checkEq(haloKey(), DKEY.BLOCKED, "(c4) 堵死")
    dveh._speed = 0
    driveReset(dveh)
    driveTick(dp, dveh)
    drive.wideRounds(true) -- 停在停點：寬帶判堵到最寬一級（倒車要等這次嘗試的寬帶重判）
    nowMs = nowMs + 6000
    driveTick(dp, dveh)
    checkEq(MDAD.Drive.hudState(0), "unstick", "(c4) 5s 後 rear 淨空倒車（實得 " .. tostring(MDAD.Drive.hudState(0)) .. "）")
    dveh._x = 9.5 -- 已退 1.5m
    dveh._speed = -5
    drive.putSolid(5, 0, "harness_c4_rear")
    nowMs = nowMs + 100
    driveReset(dveh)
    driveTick(dp, dveh)
    checkTrue(MDAD.Drive.isActive(0), "(c4) 退 1.5m 後 rear hard：不交還")
    checkEq(dveh._imp.total, 0, "(c4) rear hard 命中幀零 reverse impulse")
    checkTrue(drive.calls.forceBrake > 0, "(c4) 進 settle 煞停")
    checkTrue(haloKey() ~= DKEY.STUCK, "(c4) 不出 StopStuck 紅字")
    -- settle 停妥 → success → 重掃（session 活著）
    dveh._speed = 0
    nowMs = nowMs + 500
    driveReset(dveh)
    driveTick(dp, dveh)
    checkTrue(MDAD.Drive.isActive(0), "(c4) settle 停妥後 session 活著、重掃")
    for _, y in ipairs({ -5, -4, -2, -1, 0, 1, 2, 4, 5 }) do drive.clearCell(20, y) end
    drive.clearCell(5, 0)
    MDAD.Drive.stop(0, nil)
end

-- (c5) 改道（2026-09-02 車陣策略）：blocked 時 Drive.requestDetour 向主 MOD 要
--      替代線並驗收——仍穿避讓圈（avoidPenalty>0）／起點太遠（snapDist>20）／
--      長度超標一律拒（紅字 NoDetour＋語音 nodetour、session 活著）；合格＝綠字
--      Detour＋語音 detour，下一幀 cutover 換線、blocked 解除。自動改道（ESC 選項）
--      預設關；開了才在停等累計 10s 後自動要一次，同 episode 不重試。
-- 主 chunk 的 local 槽已貼近 200 上限：情境包成函式，內部 local 不佔主 chunk。
local function scenarioDetour()
    checkTrue(armDrive(), "(c5) 啟動")
    for _, y in ipairs({ -5, -4, -2, -1, 0, 1, 2, 4, 5 }) do
        drive.putSolid(20, y, "harness_wall_" .. y)
    end
    dveh._x = 11
    driveTick(dp, dveh)
    drive.scanRound()
    checkEq(haloKey(), DKEY.BLOCKED, "(c5) 堵死紅字")
    dveh._speed = 0
    driveReset(dveh)
    driveTick(dp, dveh)
    local nav = drive.nav
    nav.detourCalls = 0
    local function detourRoute(len, penalty, snap)
        -- 繞開牆（x=20）的替代線：先往 +y 繞出去、終點與原路線同一個（1002k：requestDetourRoute 驗終點）
        local r = { pts = { 11, 0, 11, 12, 156, 12, 156, 0 } }
        r.len, r.cost, r.avoidPenalty, r.snapDist = len, len, penalty, snap
        return r
    end
    local halosBefore = #halos
    nav.detour = detourRoute(60, 5, 1)
    local ok, why = MDAD.Drive.requestDetour(0)
    checkTrue(ok == false and why == "through", "(c5) 仍穿避讓圈的路線拒收（實得 " .. tostring(why) .. "）")
    checkEq(nav.detourCalls, 1, "(c5) 真的問了主 MOD 一次")
    checkEq(nav.lastDetour and nav.lastDetour.r, 40, "(c5) 避讓半徑 40")
    checkEq(haloKey(#halos), noteReason("UI_MinidoracatAutoDrive_NoDetour"), "(c5) 拒收紅字 NoDetour")
    checkEq(drive.lastVoice(), "nodetour", "(c5) 拒收語音 nodetour")
    nav.detour = detourRoute(60, 0, 30)
    ok, why = MDAD.Drive.requestDetour(0)
    checkTrue(ok == false and why == "far", "(c5) 起點 30m 外的路線拒收")
    -- 空線（1002h E2E rc50 0017：主 MOD 回 ok 但 len 0）收下＝下一幀建不出剖面、LostRoute 交還
    nav.detour = detourRoute(0, 0, 1)
    ok, why = MDAD.Drive.requestDetour(0)
    checkTrue(ok == false and why == "empty", "(c5) len 0 的替代線拒收 empty（實得 " .. tostring(why) .. "）")
    -- 終點不是原路線的終點（1002k E2E rc53 0008：主 MOD 回 4.3m 短線、終點在車旁，收下後下一幀就判到站交還）
    nav.detour = { pts = { 11, 0, 11, 2, 13, 4 }, len = 4.3, cost = 4.3, avoidPenalty = 0, snapDist = 1 }
    ok, why = MDAD.Drive.requestDetour(0)
    checkTrue(ok == false and why == "end", "(c5) 終點不在目標的替代線拒收 end（實得 " .. tostring(why) .. "）")
    nav.detour = detourRoute(5000, 0, 1)
    ok, why = MDAD.Drive.requestDetour(0)
    checkTrue(ok == false and why == "long", "(c5) 5km 替代線拒收（剩餘 ~150m）")
    checkTrue(MDAD.Drive.isActive(0), "(c5) 五次拒收 session 仍活著")
    -- 被拒收的替代線仍躺在主 MOD 快取（requestDetour 成功即覆寫）：下一次 250ms 取路
    -- 原樣拿回同一個 table，不得以 "deviation" 名義 cutover 跟著走（2026-09-02 s064：
    -- 拒收 far 的線同幀被收下→lat=63.5 開進樹林）。主 MOD 冷卻重算＝新 identity 才收。
    local poisoned = nav.detour -- 剛被拒的 5km 線
    local routeWas = nav.route
    local rgBefore
    do
        local cap = nil
        local realOv = MDADOverlay.update
        MDADOverlay.update = function(pn, st, ...) if pn == 0 then cap = st end return realOv(pn, st, ...) end
        nav.route = poisoned
        nowMs = nowMs + 300
        driveTick(dp, dveh)
        drive.scanRound() -- overlay 只在掃描輪完成時綁 session
        MDADOverlay.update = realOv
        checkTrue(cap ~= nil and cap.route ~= poisoned, "(c5) 剛拒收的替代線從快取拿回來也不 cutover")
        rgBefore = cap and cap.routeGen
        -- 主 MOD 冷卻後重算：新 identity（幾何同原線）→ 照常收
        local rebuilt = newRoute(10, 11, 0, -2, 0)
        rebuilt.len, rebuilt.cost, rebuilt.avoidPenalty, rebuilt.snapDist = 60, 60, 0, 1
        nav.route = rebuilt
        nowMs = nowMs + 300
        MDADOverlay.update = function(pn, st, ...) if pn == 0 then cap = st end return realOv(pn, st, ...) end
        driveTick(dp, dveh)
        drive.scanRound()
        MDADOverlay.update = realOv
        checkTrue(cap ~= nil and cap.route == rebuilt, "(c5) 主 MOD 重算的新 identity 照常 cutover")
        -- 還原：切回原線（新 identity→cutover），牆仍在 → 再度 blocked，後續斷言照舊
        nav.route = routeWas
        nowMs = nowMs + 300
        driveTick(dp, dveh)
        dveh._speed = 0
        driveReset(dveh)
        drive.scanRound()
        checkEq(haloKey(), DKEY.BLOCKED, "(c5) 切回原線後仍 blocked（後續改道斷言的前提）")
    end
    nav.detour = detourRoute(120, 0, 1)
    ok, why = MDAD.Drive.requestDetour(0)
    checkTrue(ok == true, "(c5) 合格替代線接受（實得 " .. tostring(why) .. "）")
    checkEq(halos[#halos] and halos[#halos].kind, "good", "(c5) 改道是綠字")
    checkEq(haloKey(#halos), noteReason("UI_MinidoracatAutoDrive_Detour"), "(c5) 綠字 Detour")
    checkEq(drive.lastVoice(), "detour", "(c5) 語音 detour")
    -- 主 MOD 接受後覆寫快取：requestRoute 回替代線 → 下一幀 cutover
    nav.route = nav.detour
    driveReset(dveh)
    local captured = nil
    local realOverlayUpdate = MDADOverlay.update
    MDADOverlay.update = function(pn, st, ...)
        if pn == 0 then captured = st end
        return realOverlayUpdate(pn, st, ...)
    end
    driveTick(dp, dveh)
    drive.scanRound()
    MDADOverlay.update = realOverlayUpdate
    checkTrue(captured ~= nil and captured.route == nav.detour,
        "(c5) 替代線下一幀 cutover（session.route 換成替代線）")
    checkEq(captured and captured.pendingDetour, false, "(c5) cutover 後 pendingDetour 清空")
    -- 圓心＝堵點沿「車→堵點」方向再推 R=40（2026-09-02 s064：以堵點為圓心時車在圈內，
    -- 本路出發的替代線第一段必穿圈＝全部 "through"，永遠 nodetour）：車在 x=11、
    -- 堵點 x=20.5 → 圓心 x≈60.5（近緣貼堵點，車在圈外）。
    checkTrue(captured and captured.avoidX > 60 and captured.avoidX < 61,
        "(c5) sticky 避讓圈圓心＝堵點再往前推 R（x≈60.5，實得 " .. tostring(captured and captured.avoidX) .. "）")
    checkTrue(nav.lastDetour and nav.lastDetour.ax > 60 and nav.lastDetour.ax < 61
        and (nav.lastDetour.ax - 11) > nav.lastDetour.r,
        "(c5) 主 MOD 收到的圓心離車 > R＝車在圈外")
    checkTrue(MDAD.Drive.hudState(0) ~= "blocked", "(c5) cutover 後不再 blocked（實得 " .. tostring(MDAD.Drive.hudState(0)) .. "）")
    ok, why = MDAD.Drive.requestDetour(0)
    checkTrue(ok == false and why == "not-blocked", "(c5) 沒堵時按改道＝not-blocked，不問主 MOD")
    for _, y in ipairs({ -5, -4, -2, -1, 0, 1, 2, 4, 5 }) do drive.clearCell(20, y) end
    MDAD.Drive.stop(0, nil)

    -- 自動改道：預設關（HUD 缺席／選項關）→ 停等 12s 不問主 MOD；開了才問一次
    nav.detour = nil
    checkTrue(armDrive(), "(c5b) 啟動")
    for _, y in ipairs({ -5, -4, -2, -1, 0, 1, 2, 4, 5 }) do
        drive.putSolid(20, y, "harness_wall_" .. y)
    end
    for _, y in ipairs({ -1, 0, 1 }) do drive.putSolid(7, y, "harness_rearwall_" .. y) end
    dveh._x = 11
    driveTick(dp, dveh)
    drive.scanRound()
    dveh._speed = 0
    driveReset(dveh)
    driveTick(dp, dveh)
    nav.detourCalls = 0
    if type(MDAD.HUD) ~= "table" then MDAD.HUD = {} end
    local oldAuto = MDAD.HUD.autoDetour
    MDAD.HUD.autoDetour = function() return false end
    -- 與 (c5c) 同節奏：6s（blocked-retry 先試、soft fail）→ 6s（累計 12s）→ 2s
    for _ = 1, 3 do
        nowMs = nowMs + 6000
        driveTick(dp, dveh)
    end
    checkEq(nav.detourCalls, 0, "(c5b) 自動改道關：停等 18s 不問主 MOD")
    checkTrue(not MDAD.Drive.isActive(0), "(c5b) 停等 18s 超時交還")
    checkEq(drive.infoHaloIndex(), nil, "(c5b) 同一啟動不重複診斷提示（首次在 (ex)）")
    MDAD.Drive.stop(0, nil)
    checkTrue(armDrive(), "(c5c) 啟動")
    dveh._x = 11
    driveTick(dp, dveh)
    drive.scanRound()
    dveh._speed = 0
    driveReset(dveh)
    driveTick(dp, dveh)
    drive.wideRounds(true) -- 寬帶判堵到最寬一級
    nav.detourCalls = 0
    -- (c5c-ev) 1004b：每次改道請求記一筆 detour 事件（phase auto／manual／stuck／skip、why＝結果）；舊制自動改道被拒
    --   只在 Debug console。違規證明：requestDetour 不記事件＝紅。
    local detourEv, realEvent = {}, MDADDiagnostics.event
    -- 本情境沒開本機紀錄：diagEvent 要 s.diag，而每幀 sample 回非 true 會把它關掉——取樣先回 true
    local realSample = MDADDiagnostics.sample
    MDADDiagnostics.sample = function() return true end
    MDAD.Drive.debugSession(0).diag = true
    MDADDiagnostics.event = function(pn, name, a, ...)
        if name == "detour" and type(a) == "table" then detourEv[#detourEv + 1] = a end
        return realEvent(pn, name, a, ...)
    end
    MDAD.HUD.autoDetour = function() return true end
    nowMs = nowMs + 6000
    driveTick(dp, dveh)
    checkEq(nav.detourCalls, 0, "(c5c) 自動改道開：6s 還沒到門檻（先讓 blocked-retry 試）")
    nowMs = nowMs + 6000
    driveTick(dp, dveh)
    checkEq(nav.detourCalls, 1, "(c5c) 累計 12s 自動問主 MOD 一次")
    checkEq(drive.lastVoice(), "nodetour", "(c5c) 主 MOD 無路：語音 nodetour")
    nowMs = nowMs + 2000
    driveTick(dp, dveh)
    checkEq(nav.detourCalls, 1, "(c5c) 同一停等 episode 不重問")
    local ev1 = detourEv[1]
    checkTrue(#detourEv == 1 and ev1.phase == "auto" and ev1.why ~= "ok" and type(ev1.ms) == "number" and ev1.ms >= 10000,
        "(c5c-ev) 自動改道被拒記一筆 detour（phase " .. tostring(ev1 and ev1.phase) .. "、why " .. tostring(ev1 and ev1.why)
        .. "、等了 " .. tostring(ev1 and ev1.ms) .. " ms）")
    MDAD.HUD.autoDetour = function() return false end
    MDAD.Drive.stuckDetour(MDAD.Drive.debugSession(0), 0)
    local ev2 = detourEv[2]
    checkTrue(ev2 ~= nil and ev2.phase == "skip" and ev2.why == "off",
        "(c5c-ev) 交還前改道因選項關沒問也記一筆（phase " .. tostring(ev2 and ev2.phase) .. "、why " .. tostring(ev2 and ev2.why) .. "）")
    MDADDiagnostics.event, MDADDiagnostics.sample = realEvent, realSample
    MDAD.Drive.debugSession(0).diag = false
    MDAD.HUD.autoDetour = oldAuto
    for _, y in ipairs({ -5, -4, -2, -1, 0, 1, 2, 4, 5 }) do drive.clearCell(20, y) end
    for _, y in ipairs({ -1, 0, 1 }) do drive.clearCell(7, y) end
    MDAD.Drive.stop(0, nil)

    -- (c5d) 實機序列（2026-09-02 定罪「勾了自動改道也沒效」）：後方淨空 → 5s
    -- blocked-retry 真的倒車 → 開回原地又堵 → 非 WAIT 幀已清 blockRetryDone →
    -- 舊碼同幀先判 blocked-retry 又設 recoverWhy → 改道永遠等不到 recoverWhy==nil。
    -- 新契約：累計 ≥10s 時改道**先於**第二次倒車。
    checkTrue(armDrive(), "(c5d) 啟動")
    for _, y in ipairs({ -5, -4, -2, -1, 0, 1, 2, 4, 5 }) do
        drive.putSolid(20, y, "harness_wall_" .. y)
    end
    dveh._x = 11
    driveTick(dp, dveh)
    drive.scanRound()
    dveh._speed = 0
    driveReset(dveh)
    driveTick(dp, dveh)
    drive.wideRounds(true) -- 寬帶判堵到最寬一級
    nav.detourCalls = 0
    MDAD.HUD.autoDetour = function() return true end
    nowMs = nowMs + 5500
    driveReset(dveh)
    driveTick(dp, dveh)
    checkEq(haloKey(), DKEY.UNSTICK, "(c5d) 5s 後 blocked-retry 真的倒車（後方淨空）")
    checkEq(nav.detourCalls, 0, "(c5d) 倒車那幀不改道（accum < 10s）")
    -- 倒 4m → settle → 開回原地（GO 幀清 blockRetryDone）→ 再堵
    dveh._x, dveh._speed = 7.9, -13
    nowMs = nowMs + 16
    driveReset(dveh)
    driveTick(dp, dveh) -- success → settle
    dveh._speed = 0
    nowMs = nowMs + 16
    driveTick(dp, dveh) -- settle complete
    dveh._speed = 8
    for _ = 1, 3 do
        nowMs = nowMs + 300
        driveTick(dp, dveh)
    end
    dveh._x, dveh._speed = 11, 0
    -- 改道那一刻的 session 狀態：必須是「倒車過一次、還沒開始第二次」
    local cap5d = nil
    local realOv5d = MDADOverlay.update
    MDADOverlay.update = function(pn, st, ...)
        if pn == 0 then cap5d = st end
        return realOv5d(pn, st, ...)
    end
    local realReqDetour = MinidoracatMiniMapAPI.requestDetour
    local atDetour = nil
    MinidoracatMiniMapAPI.requestDetour = function(...)
        atDetour = { attempts = cap5d and cap5d.episodeAttempts, mode = cap5d and cap5d.mode,
            wait = cap5d and cap5d.waitAccumMs }
        return realReqDetour(...)
    end
    drive.wideRounds() -- 倒車後的新嘗試：寬帶從第一級重判到最寬一級
    MinidoracatMiniMapAPI.requestDetour = realReqDetour
    MDADOverlay.update = realOv5d
    checkEq(nav.detourCalls, 1, "(c5d) 開回原地再堵：改道先於第二次倒車（實得 " .. tostring(nav.detourCalls) .. "）")
    checkTrue(atDetour ~= nil and atDetour.attempts == 1 and atDetour.mode == "follow",
        "(c5d) 改道當下：倒車過一次、尚未開始第二次（attempts=" .. tostring(atDetour and atDetour.attempts)
        .. " mode=" .. tostring(atDetour and atDetour.mode) .. "）")
    checkTrue(atDetour ~= nil and atDetour.wait >= 5000 and atDetour.wait < 10000,
        "(c5d) 觸發靠「倒車過＋再堵」而非 10s 累計（wait=" .. tostring(atDetour and atDetour.wait) .. "）")
    checkEq(drive.lastVoice(), "nodetour", "(c5d) 主 MOD 無路：語音 nodetour")
    checkTrue(MDAD.Drive.isActive(0), "(c5d) 改道失敗 session 仍活著（交回停等／倒車階梯）")
    MDAD.HUD.autoDetour = oldAuto
    for _, y in ipairs({ -5, -4, -2, -1, 0, 1, 2, 4, 5 }) do drive.clearCell(20, y) end
    MDAD.Drive.stop(0, nil)

    -- 路線起點太遠守門（s052/s053：吸到 67m 外平行路、車穿樹林卡死）。
    -- snapDist 門檻只信 nav API v5 起：v4 沿用快取時是「玩家→pts[1]」，沿線前進後失真
    -- （實機 2026-09-02：沿線開 100 格停車再啟動被拒「起點太遠」）。v4+ 的 route 要帶
    -- 逐段 segSurface/segWidth，否則 Follower 判 badroute。
    MDAD.Drive.stop(0, nil)
    dveh._x, dveh._y, dveh._speed = 0, 0, 20
    setHeading(dveh, 0)
    nav.tx, nav.ty, nav.state = 300, 0, "ok"
    nav.route = newRoute(40, 0, 0, 4, 0)
    nav.route.segSurface, nav.route.segWidth = {}, {}
    for i = 1, 39 do nav.route.segSurface[i], nav.route.segWidth[i] = "paved", 10 end
    MinidoracatMiniMapAPI.navApiVersion = 5
    nav.route.snapDist = 30
    clearList(halos)
    checkFalse(MDAD.Drive.start(dp), "(snap) v5 起點 30m 外：拒啟動")
    checkEq(haloKey(), noteReason("UI_MinidoracatAutoDrive_RouteTooFar"), "(snap) 紅字 RouteTooFar")
    nav.route.snapDist = 12
    checkTrue(MDAD.Drive.start(dp), "(snap) v5 起點 12m：可啟動")
    MDAD.Drive.stop(0, nil)
    MinidoracatMiniMapAPI.navApiVersion = 4
    nav.route.snapDist = 100
    clearList(halos)
    checkTrue(MDAD.Drive.start(dp), "(snap) v4 的 snapDist=100 不擋（舊語意＝到首點距離，不可信）")
    MDAD.Drive.stop(0, nil)
    -- (snap2) 偏航重算的 cutover 也要驗（2026-09-02 s064 定罪：舊制只在啟動與換
    -- 目標驗；車卡住後主 MOD 對**同一目標**重算，起點被吸到 65m 外的平行道路，
    -- addon 照跟＝直接開進樹林，telemetry lat=63.5）。同目標的新路線 snapDist
    -- 超門檻 → 立刻 RouteTooFar 交還，不得沿用。
    MinidoracatMiniMapAPI.navApiVersion = 5
    nav.route = newRoute(40, 0, 0, 4, 0)
    nav.route.segSurface, nav.route.segWidth = {}, {}
    for i = 1, 39 do nav.route.segSurface[i], nav.route.segWidth[i] = "paved", 10 end
    nav.route.snapDist = 2
    dveh._x, dveh._y, dveh._speed = 0, 0, 20
    setHeading(dveh, 0)
    clearList(halos)
    checkTrue(MDAD.Drive.start(dp), "(snap2) 起點在車旁：正常啟動")
    driveTick(dp, dveh)
    checkTrue(MDAD.Drive.isActive(0), "(snap2) 同一條路線照常行駛")
    -- 改反向目標後的煞停過衝可能越過新起點20m；這仍是已驗收的同一顆快取路線。
    nav.route.snapDist = 21
    dveh._x, dveh._speed = -21, 9
    setHeading(dveh, math.pi)
    nowMs = nowMs + 300
    driveTick(dp, dveh)
    checkTrue(MDAD.Drive.isActive(0),
        "(snap-cache) 合法快取路線的掉頭過衝不重新觸發起點距離拒收")
    MDAD.Drive.stop(0, nil)
    nav.route.snapDist = 2
    dveh._x, dveh._y, dveh._speed = 0, 0, 20
    setHeading(dveh, 0)
    assert(MDAD.Drive.start(dp))
    -- 主 MOD 同目標重算：新 route identity、起點 65m 外
    local farRoute = newRoute(40, 0, 0, 4, 0)
    farRoute.segSurface, farRoute.segWidth = {}, {}
    for i = 1, 39 do farRoute.segSurface[i], farRoute.segWidth[i] = "paved", 10 end
    farRoute.snapDist = 65
    nav.route = farRoute
    clearList(halos)
    nowMs = nowMs + 300 -- 越過 ROUTE_REFRESH_MS（250）才會重新 fetchRoute
    driveTick(dp, dveh)
    checkFalse(MDAD.Drive.isActive(0), "(snap2) 偏航重算起點 65m 外：交還而不是跟著開進樹林")
    checkEq(haloKey(), noteReason("UI_MinidoracatAutoDrive_RouteTooFar"), "(snap2) 紅字 RouteTooFar")
    MDAD.Drive.stop(0, nil)
    nav.route = newRoute(40, 0, 0, 4, 0)
    nav.route.segSurface, nav.route.segWidth = {}, {}
    for i = 1, 39 do nav.route.segSurface[i], nav.route.segWidth[i] = "paved", 10 end
    MinidoracatMiniMapAPI.navApiVersion = 4
    nav.route.snapDist = nil
    MinidoracatMiniMapAPI.navApiVersion = 2 -- 還原本區段其餘情境沿用的版本
end
scenarioDetour()

-- (c5h) 同一趟多次改道帶舊避讓圈（1004f；E2E e1004e dixie9050w：第二次交還前改道只避新堵點，主 MOD 原路繞回第一處
--   路障，detour 用完交還）：第二次 requestDetour 第 7 參附上第一次的圈（nav API v9），回來的線穿舊圈＝拒收 "again"
--   （v8 主 MOD 忽略第 7 參時靠這一關），不穿＝收下、第一次的圈進歷史；換目標清歷史。
--   違規證明：不附舊圈／不驗穿舊圈／收下時不推歷史＝各自紅。
function drive.scenarioDetourHist()
    local nav = drive.nav
    checkTrue(armDrive(), "(c5h) 啟動")
    for _, y in ipairs({ -5, -4, -2, -1, 0, 1, 2, 4, 5 }) do drive.putSolid(20, y, "harness_wall_" .. y) end
    dveh._x = 11
    driveTick(dp, dveh)
    drive.scanRound()
    dveh._speed = 0
    driveReset(dveh)
    driveTick(dp, dveh)
    local function via(pts) -- 終點接回原路線終點 (156,0)（requestDetourRoute 驗終點）
        return { pts = pts, len = 300, cost = 300, avoidPenalty = 0, snapDist = 1 }
    end
    nav.detour = via({ 11, 0, 11, -200, 156, -200, 156, 0 })
    local ok1 = MDAD.Drive.requestDetour(0)
    local ss = MDAD.Drive.debugSession(0)
    local ax1, ay1 = ss.avoidX, ss.avoidY
    checkTrue(ok1 == true and nav.lastDetour and nav.lastDetour.more == nil and ax1 ~= nil,
        "(c5h) 第一次改道沒有舊圈可附、收下")
    -- 開到繞行線上 (100,−200)、前方又堵：交還前改道（不要求 blocked；堵點錨在車前 10m）
    dveh._x, dveh._y = 100, -200
    setHeading(dveh, 0)
    ss.blockHitX, ss.blockHitY = 110, -200
    nav.detour = via({ 100, -200, 100, 0, 156, 0 }) -- 原路穿回第一處路障
    local ok2, why2 = MDAD.Drive.requestDetour(0, true)
    local more = nav.lastDetour and nav.lastDetour.more
    checkTrue(ok2 == false and why2 == "again" and type(more) == "table" and #more == 3
            and math.abs(more[1] - ax1) < 1e-6 and math.abs(more[2] - ay1) < 1e-6 and more[3] == 40,
        "(c5h) 第二次改道附上第一次的避讓圈，回來的線穿回舊圈＝拒收 again（實得 " .. tostring(why2) .. "）")
    nav.detour = via({ 100, -200, 200, -200, 200, 0, 156, 0 })
    local ok3 = MDAD.Drive.requestDetour(0, true)
    checkTrue(ok3 == true and type(ss.avoidHist) == "table" and #ss.avoidHist == 3
            and ss.avoidHist[1] == ax1 and ss.avoidHist[2] == ay1 and ss.avoidX ~= ax1,
        "(c5h) 不穿舊圈的線收下，第一次的圈進歷史、目前的圈換成第二處")
    -- 換目標＝新的一趟：先前判死的堵點不再算
    nav.tx = 310
    nowMs = nowMs + 300
    driveTick(dp, dveh)
    checkTrue(ss.avoidHist == nil and ss.avoidX == nil, "(c5h) 換目標清掉避讓圈與歷史")
    for _, y in ipairs({ -5, -4, -2, -1, 0, 1, 2, 4, 5 }) do drive.clearCell(20, y) end
    nav.detour = nil
    MDAD.Drive.stop(0, nil)
end
drive.scenarioDetourHist()

-- (c7) 車輛精確輪廓（2026-09-02 Dixie 車陣實爆）：兩台 1.8m 寬的車並排、真縫 2.8m
--      （車寬 1.8＋兩側各 0.3 餘裕＝2.4 可過）。格級佔位把每台膨脹成 3 格＋0.7 圓，
--      縫剩 0.2m＝永遠 blocked；改用 OBB 周長點（r=0.3）後 plan 必須提得出縫。
--      同時鎖：點雲來源是輪廓點（r=0.3、每台 ~21 顆）而不是格心（r=0.7）；任一
--      getter 失敗（沒有 getScript 的舊假車）退回格級佔位（fail-safe）。
local function scenarioOutline()
    checkTrue(armDrive(), "(c7) 啟動")
    -- 路線沿 +x、車在 l=0；兩台車朝向 +x，中心 y=-2.4 與 +2.4（內側邊 ±1.5 → 縫 3.0；
    -- 再各往內 0.1 → 真縫 2.8）
    local vA, cA = drive.putVehicleGeom(20, -2.3, 0, 1.8, 4.4, true)
    local vB, cB = drive.putVehicleGeom(20, 2.3, 0, 1.8, 4.4, true)
    -- 兩側圍籬（l=±4.5、±5.5）：不讓 plan 從車外側繞過去，縫只剩兩車之間
    for x = 12, 28 do
        for _, y in ipairs({ -6, -5, 4, 5 }) do drive.putSolid(x, y, "harness_c7_fence_" .. x .. "_" .. y) end
    end
    local captured = nil
    local realOverlayUpdate = MDADOverlay.update
    MDADOverlay.update = function(pn, st, ...)
        if pn == 0 then captured = st end
        return realOverlayUpdate(pn, st, ...)
    end
    driveReset(dveh)
    drive.scanRound()
    MDADOverlay.update = realOverlayUpdate
    checkTrue(MDAD.Drive.hudState(0) ~= "blocked", "(c7) 2.8m 真縫：不 blocked（實得 " .. tostring(MDAD.Drive.hudState(0)) .. "）")
    local sen = captured and captured.sensor
    local outlineN, squareN = 0, 0
    if sen then
        for i = 1, sen.hardN do
            if sen.hardR[i] == 0.15 then outlineN = outlineN + 1
            elseif sen.hardR[i] == 0.7 and sen.hardL[i] > -4 and sen.hardL[i] < 4 then squareN = squareN + 1 end
        end
    end
    checkTrue(outlineN >= 60 and outlineN <= 100, "(c7) 點雲＝兩台車的輪廓點（r=0.15，實得 " .. outlineN .. "）")
    checkEq(squareN, 0, "(c7) 有幾何的車不再推格心 0.7 圓（車道帶內零格心點；圍籬在帶外）")
    -- 池向量成對歸還（每台車 alloc/release 各一）
    checkEq(drive.pool.live, 0, "(c7) 輪廓取角的池向量全部歸還")
    drive.clearVehicleGeom(cA)
    drive.clearVehicleGeom(cB)
    MDAD.Drive.stop(0, nil)

    -- 反面對照：同樣兩台車但用沒有幾何 getter 的舊假車（每格一顆 0.7 圓）→ blocked
    checkTrue(armDrive(), "(c7b) 啟動")
    local cellsOld = {}
    for _, v in ipairs({ vA, vB }) do
        local cx, cy = v._x, v._y
        for gx = math.floor(cx - 2.2), math.floor(cx + 2.2) do
            for gy = math.floor(cy - 0.9), math.floor(cy + 0.9) do
                local old = { _class = "BaseVehicle", _stopped = true, _x = gx + 0.5, _y = gy + 0.5 }
                drive.vehIdSeq = drive.vehIdSeq + 1
                local id = drive.vehIdSeq
                old.getX = function() return old._x end
                old.getY = function() return old._y end
                old.getId = function() return id end
                old.isStopped = function() return true end
                drive.vehGeo[gx * 100000 + gy] = old
                cellsOld[#cellsOld + 1] = gx * 100000 + gy
            end
        end
    end
    driveReset(dveh)
    drive.scanRound()
    checkEq(haloKey(), DKEY.BLOCKED, "(c7b) 格級佔位（無幾何 getter）：同一縫 blocked（膨脹證明）")
    drive.clearVehicleGeom(cellsOld)
    for x = 12, 28 do
        for _, y in ipairs({ -6, -5, 4, 5 }) do drive.clearCell(x, y) end
    end
    MDAD.Drive.stop(0, nil)

    -- (c7c) 長車不截斷：巴士 2.5×8（周長 21m／0.3＝70 > 上限 63）→ 步距放大而不是砍尾。
    -- 截斷＝車側破洞＝假縫；契約：該車輪廓點 ≤ 64、四條邊都有點（bbox 撐滿車身）、
    -- 相鄰點最大間距 ≤ 周長／63＋量化餘裕。
    checkTrue(armDrive(), "(c7c) 啟動")
    local _, cBus = drive.putVehicleGeom(20, 0, 0, 2.5, 8.0, true)
    local capBus = nil
    local realOvBus = MDADOverlay.update
    MDADOverlay.update = function(pn, st, ...)
        if pn == 0 then capBus = st end
        return realOvBus(pn, st, ...)
    end
    driveReset(dveh)
    drive.scanRound()
    MDADOverlay.update = realOvBus
    local senB = capBus and capBus.sensor
    local busN, minX, maxX, minY, maxY = 0, math.huge, -math.huge, math.huge, -math.huge
    local pts = {}
    if senB then
        for i = 1, senB.hardN do
            if senB.hardR[i] == 0.15 then
                busN = busN + 1
                local px, py = senB.hardX[i], senB.hardY[i]
                pts[#pts + 1] = { px, py }
                if px < minX then minX = px end
                if px > maxX then maxX = px end
                if py < minY then minY = py end
                if py > maxY then maxY = py end
            end
        end
    end
    checkTrue(busN >= 40 and busN <= 64, "(c7c) 巴士輪廓點 ≤ 64（實得 " .. busN .. "）")
    checkTrue(maxX - minX > 7.9 and maxY - minY > 2.4,
        "(c7c) 四邊都有點：bbox 撐滿 8×2.5（實得 " .. string.format("%.2f×%.2f", maxX - minX, maxY - minY) .. "）")
    -- 相鄰點最大間距**含收尾段**（最後一顆周長點 → 第一顆）：截斷會把洞留在周長末端，
    -- 只看中段抓不到。中心保底點＝離 (20,0) 最近的那顆，排除後其餘依推入序成環。
    local perimPts, centerIdx, centerD = {}, nil, math.huge
    for i, pt in ipairs(pts) do
        local d = (pt[1] - 20) ^ 2 + pt[2] ^ 2
        if d < centerD then centerD, centerIdx = d, i end
    end
    checkTrue(centerIdx ~= nil and centerD < 0.01, "(c7c) 中心保底點存在（實得 d²=" .. tostring(centerD) .. "）")
    for i, pt in ipairs(pts) do if i ~= centerIdx then perimPts[#perimPts + 1] = pt end end
    local worstGap = 0
    for i = 1, #perimPts do
        local a, b = perimPts[i], perimPts[i % #perimPts + 1]
        local dx, dy = b[1] - a[1], b[2] - a[2]
        local g = math.sqrt(dx * dx + dy * dy)
        if g > worstGap then worstGap = g end
    end
    checkTrue(worstGap > 0 and worstGap <= 21 / 63 + 0.05,
        "(c7c) 相鄰輪廓點間距（含收尾段）≤ 周長／63（實得 " .. string.format("%.3f", worstGap) .. "）")
    drive.clearVehicleGeom(cBus)
    MDAD.Drive.stop(0, nil)

    -- (c7d) 貼縫檔不鑽死路（2026-09-02 s064／s001 兩輪定罪：車陣第一台以 margin 0.09 的
    -- 貼縫承諾、4 km/h 爬 20m，出口落在第二排前、整段 DP nopath——擠過去也立刻再
    -- blocked，代價 40s＋接觸＋三次倒車）。fixture：兩台車真縫 2.6m、偏離行駛線（邊緣
    -- l −0.1／2.5）：cruise（1.35）與 squeeze（1.30）都找不到 lane，physical（1.05）在
    -- l≈1.0-1.25 有縫＝貼縫 Dodge 候選；出口之後 14m 一道整寬牆。契約：拒收貼縫→blocked。
    -- (c7e) 同一縫、牆拿掉＝出口後淨空→照 2026-09-01 裁定「物理可過即過」承諾貼縫 Dodge。
    checkTrue(armDrive(), "(c7d) 啟動")
    local _, cD1 = drive.putVehicleGeom(20, -1.0, 0, 1.8, 4.4, true)
    local _, cD2 = drive.putVehicleGeom(20, 3.4, 0, 1.8, 4.4, true)
    for x = 12, 28 do
        for _, y in ipairs({ -6, -5, 6, 7 }) do drive.putSolid(x, y, "harness_c7d_fence_" .. x .. "_" .. y) end
    end
    for y = -6, 5 do drive.putSolid(44, y, "harness_c7d_wall_" .. y) end
    driveReset(dveh)
    drive.scanRound()
    checkEq(haloKey(), DKEY.BLOCKED, "(c7d) 2.6m 貼縫＋出口後整寬牆：拒收貼縫、blocked（實得 " .. tostring(haloKey()) .. "）")
    checkTrue(MDAD.Drive.hudState(0) == "blocked", "(c7d) HUD 狀態 blocked（實得 " .. tostring(MDAD.Drive.hudState(0)) .. "）")
    for y = -6, 5 do drive.clearCell(44, y) end
    MDAD.Drive.stop(0, nil)
    checkTrue(armDrive(), "(c7e) 啟動")
    driveReset(dveh)
    drive.scanRound()
    checkEq(haloKey(), DKEY.DODGE, "(c7e) 同一縫、出口後淨空：貼縫照過（實得 " .. tostring(haloKey()) .. "）")
    MDAD.Drive.stop(0, nil)
    -- (c7f) 出口後仍有擋線點（單台側停車）＝多重障礙：使用者裁定「複雜的障礙人工處理」
    -- （2026-09-02，車陣蛇行 DP 與死路 oracle 一併退役）——貼縫不鑽，blocked 交給
    -- 改道／交還；cruise 檔的單次繞行不受此規則影響。
    checkTrue(armDrive(), "(c7f) 啟動")
    local _, cD3 = drive.putVehicleGeom(46, -1.6, 0, 1.8, 4.4, true) -- 邊緣 l=-0.7：擋線
    driveReset(dveh)
    drive.scanRound()
    checkEq(haloKey(), DKEY.BLOCKED, "(c7f) 出口後仍有擋線點：貼縫不鑽、blocked（實得 " .. tostring(haloKey()) .. "）")
    drive.clearVehicleGeom(cD3)
    drive.clearVehicleGeom(cD1)
    drive.clearVehicleGeom(cD2)
    for x = 12, 28 do
        for _, y in ipairs({ -6, -5, 6, 7 }) do drive.clearCell(x, y) end
    end
    MDAD.Drive.stop(0, nil)
end
scenarioOutline()

-- (c9) 鏈式停留（2026-09-04 s046/s047 Quiet St 東向定罪：B 車北側 lane 可過、回線段撞
--      12m 外的 A 車；A 只能貼北緣過——兩段不同 lane 的同側連續繞行）。fixture：B 停在
--      +1.6（擋 lane 0）、A 停在 −0.2（x 40-44，擋 lane 0 也擋 −1.5；回線段撞它）。契約：
--      ① 首輪 commit 是停留承諾（tier *-stay、線只到 c＋車身、常駐 lane 立刻＝offL、
--         laneChained）；② 保持段走完（≥c）釋放，下一輪從停留 lane 對 A 做普通繞行
--         （出口回停留 lane）；③ A 過了、停留 lane 淨空但常駐線仍被擋時**不解鏈**（c9b）；
--         ④ 兩線都淨空才解鏈、常駐 lane 交回 0；⑤ 回線段撞的是整寬牆＝拒絕停留、blocked（c9c）。
--      假車不會自己橫移：每步把 dveh._y 擺到承諾剖面該在的位置（否則 contact／RETURN 介入）。
do -- 主 chunk local 槽已滿：情境函式放進 do 區塊
local function scenarioChain()
    local function capture()
        local cap = nil
        local realOv = MDADOverlay.update
        MDADOverlay.update = function(pn, st, ...) if pn == 0 then cap = st end return realOv(pn, st, ...) end
        return function() MDADOverlay.update = realOv; return cap end
    end
    local function stepTo(x, y)
        dveh._x, dveh._y = x, y
        driveReset(dveh)
        driveTick(dp, dveh)
        drive.scanRound()
    end
    drive.fillWorld(-10, 120, -8, 8)
    checkTrue(armDrive(), "(c9) 啟動")
    local _, cB = drive.putVehicleGeom(20, 1.6, 0, 1.8, 4.4, true)
    local _, cA = drive.putVehicleGeom(42, -0.2, 0, 1.8, 4.4, true)
    local release = capture()
    driveReset(dveh)
    drive.scanRound()
    local st = release()
    checkEq(haloKey(), DKEY.DODGE, "(c9) 回線段撞 A：停留承諾＝Dodge（實得 " .. tostring(haloKey()) .. "）")
    checkEq(st.dodgeTier, "plan-stay", "(c9) tier 標 stay（實得 " .. tostring(st.dodgeTier) .. "）")
    checkTrue(st.dodgeStay == true and st.laneChained == true, "(c9) dodgeStay＋laneChained 同時立起")
    -- 0905g：commit 當下 laneBias 不切（車還在原 lane，切了期望線跳 4m → RETURN 殺承諾）；
    --        記 stayLanePending、過 b 才切
    checkEq(st.stayLanePending, st.fstate.offL, "(c9) commit 記下待切的停留 lane")
    checkTrue(st.fstate.laneBias ~= st.fstate.offL, "(c9) commit 當下 laneBias 不動（實得 " .. tostring(st.fstate.laneBias) .. "）")
    checkTrue(st.fstate.offL < -1 and st.fstate.offL > -2, "(c9) 停留 lane 在 B 車南側（實得 " .. tostring(st.fstate.offL) .. "）")
    checkTrue(st.fstate.offD > st.fstate.offC and st.fstate.offD < st.fstate.offC + 4,
        "(c9) 停留線只到 c＋車身（offD−offC＝" .. string.format("%.2f", st.fstate.offD - st.fstate.offC) .. "）")
    checkEq(st.sensor.scanBias, st.fstate.offL, "(c9) 掃描帶跟著停留 lane")
    -- (c9z) 貼縫第二檔（2026-09-04「只用 5 km 太慢」）：停留承諾淨距 ≥0.15 → cap 至少 10
    checkTrue(st.dodgeCrawl == true and st.dodgeMargin >= 0.15,
        "(c9z) 停留是貼縫承諾且淨距 ≥0.15（m=" .. tostring(st.dodgeMargin) .. "）")
    checkTrue(st.dodgeSpeedCap >= 10 - 1e-6, "(c9z) 淨距 ≥0.15 的貼縫 cap ≥10（實得 " .. tostring(st.dodgeSpeedCap) .. "）")
    local stayLane, stayC = st.fstate.offL, st.fstate.offC
    local commitCap = st.dodgeSpeedCap
    stepTo(10, stayLane * 0.7)
    checkTrue(st.fstate.laneBias ~= stayLane, "(c9) 進入段中 laneBias 仍未切")
    -- 0905q：期望線＝ov 線本身（停留線的換道從 commit 點就開始，不是 a..b）——cross-track
    -- 跟線走，不再把車往 laneBias 拉（2026-09-04 s023 進縫前被拉離線 0.9m）
    checkTrue(type(st.diagExpL) == "number" and st.diagExpL < st.fstate.laneBias - 0.2 and st.diagExpL > stayLane,
        "(c9) 進入段中期望線已隨停留線離開 laneBias（expL=" .. tostring(st.diagExpL)
        .. " bias=" .. tostring(st.fstate.laneBias) .. " stay=" .. tostring(stayLane) .. "）")
    stepTo(st.fstate.offB + 0.5, stayLane)
    checkEq(st.fstate.laneBias, stayLane, "(c9) 過 b：常駐 lane 換成 offL")
    -- (c9g) 守護輪不得把停留 cap 放飛（2026-09-04 s034：laneBias 已換成 offL → 守護 dl=0 →
    --       clearanceCap 15→36）：點雲成長 +3（worldGrew）觸發守護重算，cap 仍 ≤ commit 值。
    --       在 b 之前驗（0904z 起停留過 b＋1m 且前方有縫會提早釋放）
    for gy = 6, 8 do drive.putSolid(80, gy, "harness_c9g_grow_" .. gy) end
    release = capture()
    stepTo(12, stayLane)
    st = release()
    checkTrue(st.planMode == "guard", "(c9g) 點雲成長觸發守護輪（實得 " .. tostring(st.planMode) .. "）")
    checkTrue(st.dodgeSpeedCap <= commitCap + 0.5,
        "(c9g) 守護輪 cap 不放飛（commit " .. tostring(commitCap) .. " → " .. tostring(st.dodgeSpeedCap) .. "）")
    local shG = 1.2 * st.dodgeCommitDl / st.dodgeCommittedLength
    local boundG = MDADDynamics.clearanceCapKmh(st.dodgeMargin, 0, 0.3, st.safeLat, shG)
    checkTrue(st.dodgeClearanceCap <= boundG + 0.5,
        "(c9g) 守護輪 clearanceCap 用 commit 側移量（dl=" .. tostring(st.dodgeCommitDl) .. " bound " .. tostring(boundG) .. " 實得 " .. tostring(st.dodgeClearanceCap) .. "）")
    for gy = 6, 8 do drive.clearCell(80, gy) end
    -- (c9s0) 0905i：走廊回報的「下一群」起點還在停留段內（corridor 用舒適需求把停留線正貼著過的
    --        東西當成要繞的群）＝不提早釋放（st178,085 釋放→全滅→倒車→漂到路緣）。
    --        predicate 級：把 corridor.plan 暫時換成「回 dodge、群起點 a2＝c−1」（離線幾何塞不出
    --        「物理過得去、舒適判擋」的縫：l 量化 0.5 格）
    do
        local realPlan = MDADCorridor.plan
        MDADCorridor.plan = function(...)
            local m, a2, b2, c2, d2, o2 = realPlan(...)
            if m == "dodge" then return m, stayC - 1, b2, c2, d2, o2 end
            return m, a2, b2, c2, d2, o2
        end
        release = capture()
        stepTo(20, stayLane)
        st = release()
        MDADCorridor.plan = realPlan
        checkTrue(st.dodgeStay == true, "(c9s0) 群起點在停留段內：不提早釋放（stay=" .. tostring(st.dodgeStay) .. "）")
    end
    -- (c9s) 提早釋放：過 b＋1m、已貼在停留 lane 上、走廊從停留 lane 看前方 A 有縫 → 釋放停留、
    --       從現在規劃 A（進入段不早於停留段終點 c）
    release = capture()
    stepTo(20, stayLane)
    st = release()
    checkTrue(st.dodgeStay ~= true and st.laneChained == true, "(c9s) 過 b 且貼線：停留提早釋放、鏈仍在（stay=" .. tostring(st.dodgeStay) .. "）")
    checkTrue(st.dodging == true and type(st.fstate.offA) == "number" and st.fstate.offA >= stayC - 1e-6,
        "(c9s) 下一段已承諾且進入段起點 ≥ 停留段終點 c（offA=" .. tostring(st.fstate.offA) .. " c=" .. tostring(stayC) .. "）")
    checkEq(MDAD.Drive.hudState(0), "dodging", "(c9) 保持段：dodging 不 blocked（實得 " .. tostring(MDAD.Drive.hudState(0)) .. "）")
    -- (c9h) 提早釋放後、c 之前候選全滅：不解鏈、不停等（stay-hold），沿停留 lane 爬到 c
    --       （2026-09-04 s@172558：釋放→全滅→解鏈→常駐線被 A 擋→停等→倒車第二次）
    do
        MDADFollower.clearOffset(st.fstate)
        st.dodging = false
        st.stayHoldEndS = stayC
        for y = -7, 7 do drive.putSolid(40, y, "harness_c9h_wall_" .. y) end
        release = capture()
        stepTo(21, stayLane)
        st = release()
        checkEq(st.planMode, "stay-hold", "(c9h) c 之前全滅、群在 c 後＝stay-hold（實得 " .. tostring(st.planMode) .. "）")
        checkTrue(st.laneChained == true, "(c9h) 不解鏈")
        checkTrue(st.blocked ~= true, "(c9h) 不進 blocked 停等")
        checkTrue(type(st.dodgeDeferCap) == "number" and st.dodgeDeferCap > 5,
            "(c9h) 對群起點套煞停 envelope、群還遠不是 0（cap=" .. tostring(st.dodgeDeferCap) .. "）")
        for y = -7, 7 do drive.clearCell(40, y) end
        -- (c9h2) 群起點在 c 之前（停留 lane 本身被擋）：不 stay-hold，走一般 blocked（0905c：
        --        st174,068 群在車前、envelope 算 0、車停在 c 前 26 秒不 blocked 不倒車）
        st.stayHoldEndS = stayC + 30
        for y = -7, 7 do drive.putSolid(28, y, "harness_c9h2_wall_" .. y) end
        release = capture()
        stepTo(22, stayLane)
        st = release()
        checkTrue(st.planMode ~= "stay-hold", "(c9h2) 群在 c 之前：不 stay-hold（實得 " .. tostring(st.planMode) .. "）")
        checkTrue(st.blocked == true, "(c9h2) 走一般 blocked（實得 " .. tostring(st.blocked) .. "）")
        -- (c9h3) blocked 停等後倒車：停留段終點地板必須清掉（0905d：st174,596 退三次 entry 恆 5.6）
        st.stayHoldEndS = stayC + 30
        local keepSpeed = dveh._speed
        dveh._x, dveh._y, dveh._speed = 25, stayLane, 0
        driveReset(dveh)
        driveTick(dp, dveh)
        drive.scanRound()
        driveReset(dveh)
        driveTick(dp, dveh)
        st.blockSteepM = 5 -- (c9h4) 全滅含大側移 steep、差 5m 跑道：倒車要多退 5m
        -- (c9h6) 1004c：跑道不夠不升級寬帶（更外側只會更陡）——這一輪的判定照「最寬一級已判」開倒車的閘。
        --   注入的 steep 在第一級判定後才寫：撤回那次升級、以 steep 重跑一次判定。
        --   違規證明：拿掉 wideJudge 的 steep 條件＝升級、倒車等第二級＝紅。
        st.wideJudged, st.wideLevel, st.wideLevelAt = nil, nil, nil
        MDAD.Drive.wideJudge(st, 0)
        checkTrue(st.wideJudged == st.episodeAttempts and MDAD.Drive.wideLevelOf(st) == 1,
            "(c9h6) steep 差額：不升級寬帶、直接開倒車的閘（judged=" .. tostring(st.wideJudged)
            .. " lvl=" .. tostring(MDAD.Drive.wideLevelOf(st)) .. "）")
        nowMs = nowMs + 800 -- (c9h5) 0905i：steep 差額＝靜態幾何，停穩 0.5s 即倒車、不等 5s
        driveReset(dveh)
        driveTick(dp, dveh)
        checkEq(st.mode, "unstick", "(c9h3/h5) steep 差額 blocked：0.8s 就進倒車、不等 5s（mode=" .. tostring(st.mode) .. "）")
        checkTrue(st.stayHoldEndS == nil, "(c9h3) 倒車起點清掉 stayHoldEndS（實得 " .. tostring(st.stayHoldEndS) .. "）")
        checkTrue(st.unstickExtraM >= 5 - 1e-6, "(c9h4) steep 差額交給倒車：多退 ≥5m（實得 " .. tostring(st.unstickExtraM) .. "）")
        dveh._speed = keepSpeed
        for y = -7, 7 do drive.clearCell(28, y) end
        MDAD.Drive.stop(0, nil)
        checkTrue(armDrive(), "(c9h3) 重臂")
        -- 後續 (c9) 斷言需要重建停留狀態：重跑一次首段
        drive.clearVehicleGeom(cA)
        _, cA = drive.putVehicleGeom(42, -0.2, 0, 1.8, 4.4, true)
        release = capture()
        driveReset(dveh)
        drive.scanRound()
        st = release()
        stayLane, stayC = st.fstate.offL, st.fstate.offC
        stepTo(10, stayLane * 0.7)
        stepTo(12, stayLane)
    end
    release = capture()
    stepTo(stayC + 2, stayLane)
    st = release()
    checkTrue(st.dodgeStay == false and st.laneChained == true, "(c9) 過 c 釋放停留、鏈仍在")
    checkEq(st.fstate.laneBias, stayLane, "(c9) 釋放後常駐 lane 仍是停留 lane")
    checkEq(MDAD.Drive.hudState(0), "dodging", "(c9) 從停留 lane 對 A 做第二段普通繞行（實得 " .. tostring(MDAD.Drive.hudState(0)) .. "）")
    checkTrue(type(st.fstate.offL) == "number" and st.fstate.offL < stayLane - 1,
        "(c9) 第二段側偏在停留 lane 更外側（實得 " .. tostring(st.fstate.offL) .. "）")
    checkTrue(st.dodgeTier ~= nil and not string.find(tostring(st.dodgeTier), "stay", 1, true),
        "(c9) 第二段是普通繞行、出口回停留 lane（tier " .. tostring(st.dodgeTier) .. "）")
    local a2, b2, c2, d2, off2 = st.fstate.offA, st.fstate.offB, st.fstate.offC, st.fstate.offD, st.fstate.offL
    local function laneAt(x)
        if x <= a2 then return stayLane end
        if x >= d2 then return stayLane end
        local t
        if x < b2 then t = (x - a2) / (b2 - a2) elseif x > c2 then t = (d2 - x) / (d2 - c2) else t = 1 end
        t = t * t * (3 - 2 * t)
        return stayLane + (off2 - stayLane) * t
    end
    for _, x in ipairs({ 30, 36, 40, 44 }) do stepTo(x, laneAt(x)) end
    release = capture()
    stepTo(48, laneAt(48))
    st = release()
    -- 0927：整車越過 c（bodyReach 3.1）才提前釋放回線段，48 還不行、52 才放
    checkTrue(st.dodging == true, "(c9) 車頭剛過 c：仍持有已掃過的回線段")
    release = capture()
    stepTo(52, laneAt(52))
    st = release()
    local dbgMin, dbgK0 = 9, nil
    if st.fstate.ovS0 and (st.dodgeClrN or 0) > 0 then
        dbgK0 = math.floor((st.lastSNow - st.vehicleProfile.halfL - st.fstate.ovS0) / MDADFollower.OV_STEP) + 1
        for k = math.max(dbgK0, st.dodgeClrK0 or 1), st.dodgeClrN do
            if (st.dodgeClr[k] or 9) < dbgMin then dbgMin = st.dodgeClr[k] end
        end
    end
    checkTrue(st.laneChained == false, "(c9) A 過了、兩線都淨空：解鏈（dodging=" .. tostring(st.dodging)
        .. " clrN=" .. tostring(st.dodgeClrN) .. " ovN=" .. tostring(st.fstate.ovN)
        .. " s0ok=" .. tostring(st.dodgeClrS0 == st.fstate.ovS0) .. " s1ok=" .. tostring(st.dodgeClrS1 == st.fstate.ovEndS)
        .. " k0=" .. tostring(dbgK0) .. " min=" .. tostring(dbgMin) .. " lat=" .. tostring(st.lastLatSigned) .. "）")
    for _, x in ipairs({ 56, 64 }) do stepTo(x, laneAt(x)) end
    stepTo(72, stayLane)
    release = capture()
    stepTo(80, stayLane * 0.5)
    stepTo(90, 0)
    st = release()
    checkEq(st.fstate.laneBias, 0, "(c9) 解鏈後常駐 lane 交回 0（實得 " .. tostring(st.fstate.laneBias) .. "）")
    checkEq(MDAD.Drive.hudState(0), "follow", "(c9) 收尾 follow（實得 " .. tostring(MDAD.Drive.hudState(0)) .. "）")
    drive.clearVehicleGeom(cA)
    drive.clearVehicleGeom(cB)
    MDAD.Drive.stop(0, nil)

    -- (c9b) A 只擋常駐線（+1.3：邊 0.4..2.2）、不擋停留 lane：停留釋放後停留 lane 淨空，
    --       但常駐線前方還被 A 擋＝**不解鏈**、繼續沿停留 lane 過 A；A 過了才解鏈。
    checkTrue(armDrive(), "(c9b) 啟動")
    _, cB = drive.putVehicleGeom(20, 1.6, 0, 1.8, 4.4, true)
    -- +1.3（邊 0.4）：擋常駐線 0（1.25 內）、不擋停留 lane −1.5；車頭偏 0.3 rad 的前角
    -- 掃到 y≈0.0，留 0.4 給 contact 圈（0.3）
    _, cA = drive.putVehicleGeom(42, 1.3, 0, 1.8, 4.4, true)
    release = capture()
    driveReset(dveh)
    drive.scanRound()
    st = release()
    checkEq(st.dodgeTier, "plan-stay", "(c9b) 回線段撞 A：停留承諾（實得 " .. tostring(st.dodgeTier) .. "）")
    stayLane, stayC = st.fstate.offL, st.fstate.offC
    stepTo(10, stayLane * 0.7)
    stepTo(20, stayLane)
    release = capture()
    stepTo(stayC + 2, stayLane)
    stepTo(30, stayLane)
    stepTo(36, stayLane)
    st = release()
    checkTrue(st.laneChained == true, "(c9b) 停留 lane 淨空、常駐線仍被 A 擋：不解鏈")
    checkEq(st.fstate.laneBias, stayLane, "(c9b) 常駐 lane 仍是停留 lane（實得 " .. tostring(st.fstate.laneBias) .. "）")
    checkEq(MDAD.Drive.hudState(0), "follow", "(c9b) 沿停留 lane 直行不繞不停（實得 " .. tostring(MDAD.Drive.hudState(0)) .. "）")
    stepTo(40, stayLane)
    stepTo(44, stayLane)
    release = capture()
    stepTo(48, stayLane)
    st = release()
    checkTrue(st.laneChained == false, "(c9b) A 過了才解鏈")
    drive.clearVehicleGeom(cA)
    drive.clearVehicleGeom(cB)
    MDAD.Drive.stop(0, nil)

    -- (c9d) 對側 stay 拒絕（2026-09-04 s051：stay −2.25 → +0.25 → −2.25 → +2.00 左右擺盪，
    --       最後把 4.25m 側移塞進 2.8m 進入段）：已鏈在 −1.5，下一台 C 擋住 −1.5 與中線、
    --       縫只在 +側且回線段又撞 D → 想 stay 在 +側＝拒絕（why=side）；沒有 stay 就是
    --       普通候選鏈（回線段撞 D 全滅）→ blocked，不橫拉過整條路。
    drive.c9dFrame = drive.frameMs(8) -- 反例包含62m第三台車；不能借未掃尾段當淨空。
    checkTrue(armDrive(), "(c9d) 啟動")
    _, cB = drive.putVehicleGeom(20, 1.6, 0, 1.8, 4.4, true)
    local _, cC = drive.putVehicleGeom(42, -1.4, 0, 1.8, 4.4, true)
    local _, cD = drive.putVehicleGeom(62, 1.8, 0, 1.8, 4.4, true)
    for x = 34, 70 do
        for _, y in ipairs({ -6, -5, 5, 6 }) do drive.putSolid(x, y, "harness_c9d_fence_" .. x .. "_" .. y) end
    end
    release = capture()
    driveReset(dveh)
    drive.scanRound()
    st = release()
    checkEq(st.dodgeTier, "plan-stay", "(c9d) 第一段停留 −側（實得 " .. tostring(st.dodgeTier) .. "）")
    stayLane, stayC = st.fstate.offL, st.fstate.offC
    stepTo(10, stayLane * 0.7)
    stepTo(20, stayLane)
    release = capture()
    stepTo(stayC + 2, stayLane)
    stepTo(30, stayLane)
    st = release()
    -- 0904x：+側縫落在常駐線 ±TUNE.STAY_HOME_M 內＝「回家」→ 以停留承諾（無回線段、鏈換到
    --       +側），不再建「回到 −側鏈 lane」的全繞行（s027 t=19→23：回線段被 guard 判死→
    --       再從 −3.25 commit −3 stay → 車在 +1.5 → RETURN hold 2.5s）。
    checkTrue(st.laneChained == true, "(c9d) 鏈仍在")
    checkTrue(st.dodgeStay == true, "(c9d) 回家縫以停留承諾（實得 dodgeStay=" .. tostring(st.dodgeStay) .. "）")
    local homeRes = st.residentBias or st.sandBias
    checkTrue(type(st.stayLanePending) == "number" and st.stayLanePending > 0
        and math.abs(st.stayLanePending - homeRes) <= MDAD.Drive.debugTune().STAY_HOME_M + 1e-6,
        "(c9d) 鏈將換到 +側、離常駐線 ≤ STAY_HOME_M（pending=" .. tostring(st.stayLanePending) .. " resident=" .. tostring(homeRes) .. "）")
    -- 非回家的對側候選仍受 side 規則：把 STAY_HOME_M 縮到 0.3 重跑同一場景 → 不得 stay
    do
        local keep = MDAD.Drive.debugTune().STAY_HOME_M
        MDAD.Drive.debugTune().STAY_HOME_M = 0.3
        MDAD.Drive.stop(0, nil)
        checkTrue(armDrive(), "(c9d-side) 啟動")
        release = capture()
        driveReset(dveh)
        drive.scanRound()
        st = release()
        stayLane, stayC = st.fstate.offL, st.fstate.offC
        stepTo(10, stayLane * 0.7)
        stepTo(20, stayLane)
        release = capture()
        stepTo(stayC + 2, stayLane)
        stepTo(30, stayLane)
        st = release()
        checkTrue(st.laneChained == true, "(c9d-side) 鏈仍在（−側）")
        checkTrue(st.dodgeStay ~= true, "(c9d-side) 非回家的對側縫不得 stay（實得 dodgeStay=" .. tostring(st.dodgeStay) .. "）")
        MDAD.Drive.debugTune().STAY_HOME_M = keep
    end
    drive.clearVehicleGeom(cD)
    drive.clearVehicleGeom(cC)
    drive.clearVehicleGeom(cB)
    for x = 34, 70 do
        for _, y in ipairs({ -6, -5, 5, 6 }) do drive.clearCell(x, y) end
    end
    drive.frameMs(drive.c9dFrame)
    MDAD.Drive.stop(0, nil)

    -- (c9e) 鏈上候選全滅時立刻解鏈重枚舉（2026-09-04 s@165140：停留 −3.25 後 −5.25／−4.25／
    --       −5.50 全滅 → blocked 5s → 倒車 → 解鏈才找到 +2.00）。predicate 級：鏈在 −1.5、
    --       前方整寬牆＝全滅 → 該輪解鏈、不進 blocked 停等；牆拆掉後下一輪從常駐線承諾。
    checkTrue(armDrive(), "(c9e) 啟動")
    _, cB = drive.putVehicleGeom(20, 1.6, 0, 1.8, 4.4, true)
    _, cA = drive.putVehicleGeom(42, -0.2, 0, 1.8, 4.4, true) -- 同 (c9)：回線段撞 A → 停留
    release = capture()
    driveReset(dveh)
    drive.scanRound()
    st = release()
    checkEq(st.dodgeTier, "plan-stay", "(c9e) 第一段停留 −側（實得 " .. tostring(st.dodgeTier) .. "）")
    stayLane, stayC = st.fstate.offL, st.fstate.offC
    stepTo(10, stayLane * 0.7)
    drive.clearVehicleGeom(cA)
    for y = -7, 7 do drive.putSolid(44, y, "harness_c9e_wall_" .. y) end
    stepTo(20, stayLane) -- 牆＝走廊 blocked：停留不提早釋放（0904z）
    -- 0905b／c：全滅不再解鏈回常駐線（車在 −1.5、常駐 0 → 線建在車外），改重錨在車的實際橫向
    --   ——但只做一次：車已在鏈 lane 上（差 <0.5）仍全滅＝真堵，走 blocked（st174,053：每輪重錨
    --   15 次從不 blocked、18 km/h 撞進 B）。先把車擺離鏈 lane 1m → 重錨、不 blocked；再貼回 → blocked。
    release = capture()
    stepTo(stayC + 2, stayLane + 1.0)
    st = release()
    checkTrue(st.laneChained == true, "(c9e) 全滅、車離鏈 lane 1m：鏈不放、重錨（實得 laneChained=" .. tostring(st.laneChained) .. "）")
    checkTrue(math.abs(st.fstate.laneBias - st.lastLatSigned) < 1e-6,
        "(c9e) laneBias 重錨在車的實際橫向（laneBias=" .. tostring(st.fstate.laneBias) .. " lat=" .. tostring(st.lastLatSigned) .. "）")
    checkTrue(st.blocked ~= true, "(c9e) 重錨那輪不進 blocked 停等（實得 blocked=" .. tostring(st.blocked) .. "）")
    release = capture()
    stepTo(stayC + 2.5, stayLane + 1.0)
    st = release()
    checkTrue(st.blocked == true, "(c9e) 已在錨點仍全滅：真堵、進 blocked（實得 blocked=" .. tostring(st.blocked) .. "）")
    for y = -7, 7 do drive.clearCell(44, y) end
    local _, cC3 = drive.putVehicleGeom(44, -1.0, 0, 1.8, 4.4, true) -- 擋常駐線與 −側，縫在 +側
    release = capture()
    stepTo(stayC + 3, stayLane)
    stepTo(stayC + 4, stayLane)
    st = release()
    checkTrue(st.dodging == true and type(st.fstate.offL) == "number",
        "(c9e) 下一輪從車位重枚舉承諾（offL=" .. tostring(st.fstate.offL) .. " dodging=" .. tostring(st.dodging) .. "）")
    drive.clearVehicleGeom(cC3); drive.clearVehicleGeom(cB)
    MDAD.Drive.stop(0, nil)

    -- (c9c) 回線段撞的是整寬牆：corridor 從停留 lane 對它無縫＝拒絕停留（09-02「貼縫不鑽
    --       死路」）→ blocked。
    checkTrue(armDrive(), "(c9c) 啟動")
    _, cB = drive.putVehicleGeom(20, 1.6, 0, 1.8, 4.4, true)
    for y = -7, 7 do drive.putSolid(44, y, "harness_c9c_wall_" .. y) end
    release = capture()
    driveReset(dveh)
    drive.scanRound()
    st = release()
    checkEq(haloKey(), DKEY.BLOCKED, "(c9c) 出口撞整寬牆：不停留、blocked（實得 " .. tostring(haloKey()) .. "）")
    checkTrue(st.laneChained ~= true, "(c9c) 未鏈")
    for y = -7, 7 do drive.clearCell(44, y) end
    drive.clearVehicleGeom(cB)
    MDAD.Drive.stop(0, nil)
    drive.fillWorld(-2, 70, -7, 7)
end
scenarioChain()
end

-- (c9L) 停留 lane 前瞻（2026-09-04 st176,185「為什麼沒有提前預估」：A 北側 −3.25 停留、B 縫在
--       +1.75、A 尾到 B 頭 6m 塞不進 5m 側移的 10m 跑道 → 每輪 steep → blocked → 倒車 → 斜切撞 B）：
--       圍籬把路收成 ±4.3；常駐偏置 +2；A 貼北緣（只能從南側 ≤ +1.0 過，普通停留選最靠近 +2 的
--       +1.0）、B 偏北（只能從南側 ≤ −0.5 過）、A 尾到 B 頭跑道 1.1m：+1.0 → −0.5 的 1.5m
--       側移塞不進，前瞻應把停留 lane 直接收到 −0.5（tier *-stay-look），下一段零側移。
do
C9L_BX = 40.5
local function scenarioLook()
    local function capture()
        local cap = nil
        local realOv = MDADOverlay.update
        MDADOverlay.update = function(pn, st, ...) if pn == 0 then cap = st end return realOv(pn, st, ...) end
        return function() MDADOverlay.update = realOv; return cap end
    end
    drive.fillWorld(-10, 120, -8, 8)
    setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false, AutoDriveMaxSpeed = 40, RightLaneBias = 2 })
    checkTrue(armDrive(), "(c9L) 啟動（常駐偏置 +2）")
    for x = 24, 48 do
        for _, y in ipairs({ -5, -6, 5, 6 }) do drive.putSolid(x, y, "harness_c9L_fence_" .. x .. "_" .. y) end
    end
    local _, cA = drive.putVehicleGeom(30, 3.0, 0, 1.0, 4.4, true)      -- A 北緣（2.5..3.5）：擋 +2 線、南側 ≤ +1.0 可過
    local _, cBn = drive.putVehicleGeom(C9L_BX, 1.75, 0, 1.8, 4.4, true) -- B 偏北（0.85..2.65）：擋回線、南側 ≤ −0.5 可過
    local release = capture()
    driveReset(dveh)
    drive.scanRound()
    local st = release()
    -- 0905j 起大側移閘退回 3，這片幾何有「繞 A 後緩回、順便從 B 南側過」的全繞行解，不需停留；
    -- 前瞻本身改用測試鉤 predicate 級鎖（跑道 1.1m：+1.0 → −0.5 塞不進、0/−0.25 尾段掃到 B、
    -- −0.5 過 → 收到 −0.5）
    MDADFollower.clearOffset(st.fstate)
    st.dodging = false
    local Llook = MDAD.Drive.debugStayLook(0, 4, 25.8, 34.2, 55, 1.0, 34.2, 36.3, -0.5)
    checkTrue(Llook ~= nil and math.abs(Llook + 0.5) < 1e-6,
        "(c9L) 停留 lane 往 B 縫側收到 −0.5（實得 " .. tostring(Llook) .. "；普通停留＝+1.0）")
    -- (c9N) 0905n：停留承諾時「下一群塞不進、也沒有可收 lane」→ 記 stayNextB、對它煞停。
    --       predicate 級：monkeypatch corridor 對停留 lane 的探測回「群起點 c+2、縫在 +4.5」
    --       （+1.75..+4.25 撞 A、+4.5 撞圍籬＝沒有可收 lane）→ 停留照走但 stayNextB＝c+2，
    --       進入停留段時的定速被壓到低於承諾 cap
    do
        local realPlan = MDADCorridor.plan
        MDADCorridor.plan = function(hs, hl, n, need, half, prefer, hr, baseL, lo, hi, refine, ...)
            local m, a2, b2, c2, d2, o2 = realPlan(hs, hl, n, need, half, prefer, hr, baseL, lo, hi, refine, ...)
            if prefer == baseL and math.abs(prefer - 0.75) < 1e-6 and m == "dodge" then return m, a2, 36.2, c2, d2, 4.5 end
            return m, a2, b2, c2, d2, o2
        end
        MDADFollower.clearOffset(st.fstate)
        st.dodging = false
        drive.clearVehicleGeom(cBn)
        local _, cB2 = drive.putVehicleGeom(45, 1.75, 0, 1.8, 4.4, true) -- 停留線尾（~37）掃不到、回線段撞得到
        driveReset(dveh)
        drive.scanRound()
        -- 候選：+0.75 過 A、回線到 +2 在 d=46 撞 B（p4）→ 停留路徑 → 患測 corridor 說下一群塞不進
        local okN, roN, vN = MDAD.Drive.debugSweepFallbacks(0, 4, 20, 34, 46, 0.75, "c9n")
        MDADCorridor.plan = realPlan
        drive.clearVehicleGeom(cB2)
        _, cBn = drive.putVehicleGeom(C9L_BX, 1.75, 0, 1.8, 4.4, true)
        checkTrue(okN == true and vN == "stay" and roN == 0.75,
            "(c9N) 下一群塞不進、無可收 lane：仍以停留承諾（實得 " .. tostring(okN) .. "/" .. tostring(vN) .. "/" .. tostring(roN) .. "）")
        checkTrue(type(st.stayNextB) == "number" and math.abs(st.stayNextB - 36.2) < 1e-6,
            "(c9N) 記下下一群起點 stayNextB（實得 " .. tostring(st.stayNextB) .. "）")
        -- 承諾後停留段內：對 stayNextB 的煞停 envelope 壓低定速（predicate：直接餵 dodging 狀態）
        st.dodging, st.dodgeStay, st.dodgeSpeedCap = true, true, 30
        st.fstate.offA, st.fstate.offB, st.fstate.offC, st.fstate.offD, st.fstate.offL = 4, 20, 34, 38, 0.75
        dveh._x, dveh._y = 24, 0.75
        driveReset(dveh)
        driveTick(dp, dveh)
        checkTrue(drive.calls.maxRegSpeed > 0 and drive.calls.maxRegSpeed < 20,
            "(c9N) 停留段內（距下一群 12m）定速被煞停 envelope 壓到 <20（實得 " .. tostring(drive.calls.maxRegSpeed) .. "）")
        st.stayNextB = nil
        driveReset(dveh)
        driveTick(dp, dveh)
        checkTrue(drive.calls.maxRegSpeed > 0 and drive.calls.maxRegSpeed < 20,
            "(c9N) 停留前瞻解除後，已知的線尾外下一台仍限制接近速度")
        st.dodging, st.dodgeStay = false, false
        MDADFollower.clearOffset(st.fstate)
        dveh._x, dveh._y = 0, 0
    end
    -- (c9L2) corridor 回報的「第一群」在停留段之前／之中（b2 ≤ c）＝不是下一群，不前瞻
    --        （st177,648：路緣群 b2=125 < c=154 → 停留被推到 −4.5 貼路緣 → 撞）
    MDADFollower.clearOffset(st.fstate)
    st.dodging = false
    local Lbad = MDAD.Drive.debugStayLook(0, 4, 25.8, 34.2, 55, 1.0, 34.2, 30.0, -0.5)
    checkTrue(Lbad == nil, "(c9L2) 第一群在 c 之前：不前瞻（實得 " .. tostring(Lbad) .. "）")
    drive.clearVehicleGeom(cBn); drive.clearVehicleGeom(cA)
    for x = 24, 48 do
        for _, y in ipairs({ -5, -6, 5, 6 }) do drive.clearCell(x, y) end
    end
    MDAD.Drive.stop(0, nil)
    setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false, AutoDriveMaxSpeed = 40, RightLaneBias = 0 })
    drive.fillWorld(-2, 70, -7, 7)
end
scenarioLook()
end

-- (n) 同縫微調（2026-09-04 s044 vs s045：crawl 候選 +3.25 打槍 −0.07、鄰格 +3.50 物理 0.31
--     可過；ban 帶 ±(0.25+need) 把鄰格一起封掉＝同位置重啟才過）。predicate 級鎖（測試鉤
--     debugSweepFallbacks 直接餵候選）：B 車在 +1.6，lane −0.30 差十幾公分、−0.55 過。
--     契約：近失候選往「遠離命中點」側移 0.25 一格再掃，過＝variant nudge、offL＝−0.55；
--     方向錯（往 +側）會撞得更深。差太多（NUDGE_MAX_M 以上）不微調。
do -- 主 chunk local 槽已滿：情境函式放進 do 區塊
local function scenarioNudge()
    drive.fillWorld(-10, 120, -8, 8)
    checkTrue(armDrive(), "(n) 啟動")
    local _, cB = drive.putVehicleGeom(20, 1.6, 0, 1.8, 4.4, true)
    driveReset(dveh)
    drive.scanRound()
    local ok, ro, variant = MDAD.Drive.debugSweepFallbacks(0, 6, 14, 24, 32, -1.2, "n")
    checkTrue(ok == true and variant == nil, "(n) −1.20 本身可過且淨距 ≥0.35（對照，variant " .. tostring(variant) .. "）")
    ok, ro, variant = MDAD.Drive.debugSweepFallbacks(0, 6, 14, 24, 32, -0.3, "n")
    checkTrue(ok == true, "(n) −0.30 近失：微調後可過（實得 " .. tostring(ok) .. "）")
    checkEq(variant, "nudge", "(n) 退路＝nudge（實得 " .. tostring(variant) .. "）")
    checkTrue(ro ~= nil and ro < -0.54 and ro > -0.56, "(n) 往遠離 B 車的一側移一格＝−0.55（實得 " .. tostring(ro) .. "）")
    ok = MDAD.Drive.debugSweepFallbacks(0, 6, 14, 24, 32, -0.1, "n")
    checkEq(ok, false, "(n) −0.10 差太多（B 邊 0.7）：不微調、失敗")
    -- (sp) 進入段陡坡拒收（2026-09-04 s051：4.25m 側移塞進 2.8m；運動學最小 8.8m＝比例 3.1）：
    --      b 只在車前 3m（entry ≤2m）、側移 4m → shape 回 false、reason steep；同樣 entry 側移
    --      1m（比例 <3）照常。predicate 級（debugSweepFallbacks 直接餵）。
    local okS, why = MDAD.Drive.debugSweepFallbacks(0, 1, 3, 12, 20, -4.0, "sp")
    checkEq(okS, false, "(sp) 4m 側移塞 2m 進入段：拒收")
    checkEq(why, "steep", "(sp) 拒收理由 steep（實得 " .. tostring(why) .. "）")
    local okG = MDAD.Drive.debugSweepFallbacks(0, 1, 3, 12, 20, -1.0, "sp")
    checkEq(okG, true, "(sp) 1m 側移塞 2m 進入段（比例 <3）：照常承諾")
    -- (sp2) 2026-09-04 s@167683 路口：0.25m 側移、進入段 1.2m——純運動學 sqrt(6·0.25/κ)≈2.1，
    --       比例 <3 必須放行；舊制拿 2×halfL 地板（4.2）當分母＝ratio 3.4 誤拒
    local okS2, whyS2 = MDAD.Drive.debugSweepFallbacks(0, 1, 2.2, 12, 20, -0.25, "sp")
    checkTrue(okS2 == true, "(sp2) 0.25m 側移塞 1.2m 進入段：不拒收（實得 " .. tostring(okS2) .. "/" .. tostring(whyS2) .. "）")
    -- (sp4) 大側移用較嚴比例（2026-09-04 s@172511：5.25m 側移塞 5.7m，運動學最小 9.6 → 比例 1.7
    --       過了 3 的閘 → 43° 斜切撞 B）：dl 5.25／entry 4.5（b=rs+5.5）→ steep（舊比例 3 放行）
    -- 0905j 使用者裁定「不用太保守」：大側移閘退回 3，5.25m 塞 4.5m（ratio ≈2.1）照承諾
    local okS4, whyS4 = MDAD.Drive.debugSweepFallbacks(0, 1, 5.5, 16, 24, -5.25, "sp")
    checkTrue(okS4 == true, "(sp4) 5.25m 側移塞 4.5m 進入段（ratio 2.1 < 3）：承諾（實得 " .. tostring(okS4) .. "/" .. tostring(whyS4) .. "）")
    -- (ip) 已在候選 lane 上＝進入段可為零（2026-09-04 st179,249：停留剛結束、車在 +2.0，路緣物群
    --      b < rs+1 → entryAvail ≤ 0 → 全候選靜默拒收 → blocked hit=nil → StopStuck）：車擺在 y=−1.5，
    --      候選 offL=−1.5、b=rs+0.5 → 承諾；offL=+1.5（差 3m）→ 拒收
    dveh._y = -1.5
    driveReset(dveh)
    drive.scanRound()
    local okIp = MDAD.Drive.debugSweepFallbacks(0, -2, 0.5, 6, 9, -1.5, "ip")
    checkTrue(okIp == true, "(ip) 候選 lane＝車位、群已在車旁：零進入段照承諾（實得 " .. tostring(okIp) .. "）")
    local okIp2 = MDAD.Drive.debugSweepFallbacks(0, -2, 0.5, 6, 9, 1.5, "ip")
    checkTrue(okIp2 == false, "(ip) 候選 lane 離車 3m、群已在車旁：沒有進入段＝拒收（實得 " .. tostring(okIp2) .. "）")
    dveh._y = 0
    driveReset(dveh)
    drive.scanRound()
    -- (ch) 一般繞行的通用前瞻（0905l，st179,820：近距離起步、全繞行在 A 前 1m 回線 → 5m 側移塞不進
    --      → blocked → 倒車 ×3）：B 的縫在 −1.5、回線 d=32；A 在 53.5 擋 lane 0（shape 後回線到 47、車身剛掃不到它）、縫只在 ≤ −1.75。回線後
    --      再切 1.75m 跑道只有 1.8m → 改停留在 −1.5（variant stay），不回線
    local _, cA2 = drive.putVehicleGeom(53.5, 0.4, 0, 2.4, 4.4, true) -- 回線末端＋車身剛好掃不到，跑道 1.2m
    -- 0909b：sensor.aheadM 每輪被 Drive.updatePerception 依玩家感知距離重寫，fixture
    -- 直接寫 70 已經無效；而 30 FPS 的有效視距只有 ~50m，看不到 53.5 的 A。這一小段
    -- 明確把幀時降到 10ms（有效視距＝請求值 120m），對照組跑完就還原。
    local chMs = drive.frameMs(10)
    driveReset(dveh)
    drive.scanRound()
    local okCh, roCh, vCh = MDAD.Drive.debugSweepFallbacks(0, 6, 14, 24, 32, -1.5, "ch")
    checkTrue(okCh == true and vCh == "stay" and roCh == -1.5,
        "(ch) 回線後緊接 A、側移塞不進：改停留不回線（實得 " .. tostring(okCh) .. "/" .. tostring(vCh) .. "/" .. tostring(roCh) .. "）")
    drive.clearVehicleGeom(cA2)
    driveReset(dveh)
    drive.scanRound()
    local okCh2, _, vCh2 = MDAD.Drive.debugSweepFallbacks(0, 6, 14, 24, 32, -1.5, "ch")
    checkTrue(okCh2 == true and vCh2 == nil, "(ch) 對照：A 不在＝照常回線（實得 " .. tostring(vCh2) .. "）")
    drive.frameMs(chMs)
    driveReset(dveh)
    drive.scanRound()
    -- (w) 貼縫拓寬（2026-09-04 圖 3「應該再偏右邊一點」）：−0.55 掃過但淨距 ≈0 → 往遠離 B 車
    --     側移一格 −0.80（淨距 0.25）；−0.80 本身淨距夠、不動。
    local okW, roW, vW, mgW = MDAD.Drive.debugSweepFallbacks(0, 6, 14, 24, 32, -0.55, "w")
    checkTrue(okW == true, "(w) −0.55 可過")
    checkEq(vW, "widen", "(w) 淨距貼底：拓寬（實得 " .. tostring(vW) .. "）")
    checkTrue(roW ~= nil and roW < -0.79 and roW > -0.81, "(w) 往遠離 B 車一格＝−0.80（實得 " .. tostring(roW) .. "）")
    checkTrue(mgW ~= nil and mgW > 0.2, "(w) 拓寬後淨距更大（實得 " .. tostring(mgW) .. "）")
    -- 0905o：拓寬門檻 0.15→0.35（貼縫追線落後實測 0.25-0.4）；−0.80 淨距 0.25 仍會再往 −1.05 挪
    local okW2, roW2, vW2 = MDAD.Drive.debugSweepFallbacks(0, 6, 14, 24, 32, -1.2, "w")
    checkTrue(okW2 == true and vW2 == nil and roW2 == -1.2, "(w) 淨距 ≥0.35 的候選不拓寬（實得 " .. tostring(vW2) .. "）")
    local okW3, roW3, vW3 = MDAD.Drive.debugSweepFallbacks(0, 6, 14, 24, 32, -0.8, "w")
    checkTrue(okW3 == true and vW3 == "widen" and roW3 < -1.0, "(w) 淨距 0.25 仍拓寬到 −1.05（實得 " .. tostring(vW3) .. "/" .. tostring(roW3) .. "）")
    drive.clearVehicleGeom(cB)
    MDAD.Drive.stop(0, nil)
    drive.fillWorld(-2, 70, -7, 7)
end
scenarioNudge()
end

-- (st) 窄縫進入段用滿跑道（1004g TUNE.ENTRY_STRETCH_MAX；E2E h1004f dixie9050w：唯一的縫物理淨距 0.16、彎上 11.45m 塞
--   6.3m 側移、車到 b 有 19.9m 跑道沒用，轉向延遲落後 0.16–0.2 擦到）：B（+1.9）與 C（−2.6）夾一條縫，爬行設計的候選
--   −0.40 物理淨距 <0.3 → 同一條 offL 以兩倍長的進入段重建、淨距不變＝換（variant 加 -stretch）；同組幾何把縫放寬到
--   物理 0.4（B +2.0、C −2.8、−0.35）＝不動。對照用 ENTRY_STRETCH_MAX＝1（不可能拉長）。
--   違規證明：stretch 一律原樣回／shapeProfile 不吃 entryStretch＝紅。
function drive.scenarioEntryStretch()
    local T = MDAD.Drive.debugTune()
    local function probe(by, cy, off)
        drive.fillWorld(-10, 120, -8, 8)
        drive.putVehicleGeom(32, by, 0, 1.8, 4.4, true)
        drive.putVehicleGeom(32, cy, 0, 1.8, 4.4, true)
        driveReset(dveh)
        drive.scanRound()
        T.ENTRY_STRETCH_MAX = 1
        local ok1, _, v1, mg1, a1, b1 = MDAD.Drive.debugSweepFallbacks(0, 10, 28, 36, 44, off, "st", true)
        T.ENTRY_STRETCH_MAX = 2
        local ok2, _, v2, mg2, a2, b2 = MDAD.Drive.debugSweepFallbacks(0, 10, 28, 36, 44, off, "st", true)
        return ok1, v1, mg1, a1 and b1 - a1, ok2, v2, mg2, a2 and b2 - a2
    end
    checkTrue(armDrive(), "(st) 啟動")
    local ok1, v1, mg1, e1, ok2, v2, mg2, e2 = probe(1.9, -2.6, -0.4)
    checkTrue(ok1 == true and ok2 == true and type(v2) == "string" and v2:find("stretch", 1, true) ~= nil
            and e2 >= 1.9 * e1 and mg2 >= mg1 - 0.02,
        string.format("(st) 窄縫（爬行設計、跑道 27m）：進入段 %.1f → %.1fm（%s → %s）、淨距 %.2f → %.2f", e1 or -1, e2 or -1,
            tostring(v1), tostring(v2), mg1 or -1, mg2 or -1))
    ok1, v1, mg1, e1, ok2, v2, mg2, e2 = probe(2.0, -2.8, -0.35)
    checkTrue(ok1 == true and ok2 == true and (v2 == nil or v2:find("stretch", 1, true) == nil)
            and math.abs(e2 - e1) < 1e-6,
        string.format("(st) 物理淨距 ≥0.3 的縫不拉長（進入段 %.1f／%.1fm、%s）", e1 or -1, e2 or -1, tostring(v2)))
    MDAD.Drive.stop(0, nil)
    drive.fillWorld(-2, 70, -7, 7)
end
drive.scenarioEntryStretch()

-- (c8) MP 假速度域（2026-09-02 s012：regulator 70、直路 30 秒貼死 51 km/h）：
--      CarController 用 v·lerp(1, fake, (v/min(120,SpeedLimit))²) 與 regulatorSpeed
--      比，fake=120/min(SpeedLimit,120)。SpeedLimit 70 → fake 1.714；沙盒 40 的
--      真速目標要寫成 40·(1+0.714·(40/70)²)=49。SP（fake 1／方法缺席）恆等。
local function scenarioFakeSpeed()
    local function maxRegAfterRun()
        checkTrue(armDrive(), "(c8) 啟動")
        driveReset(dveh)
        for _ = 1, 60 do driveTick(dp, dveh) end
        local m = drive.calls.maxRegSpeed
        MDAD.Drive.stop(0, nil)
        return m
    end
    setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false,
        AutoDriveMaxSpeed = 40, RightLaneBias = 0 })
    -- 40m 短路線受終點制動包絡壓住，真速目標峰值 < 40；同 fixture 重跑必同值，
    -- 拿 SP 峰值當基準算映射期望值。
    local plain = maxRegAfterRun()
    checkTrue(plain > 0 and plain <= 40,
        "(c8) 無 getFakeSpeedModifier（SP 假車）→ 定速＝真速（實得 " .. tostring(plain) .. "）")
    local fake = 120 / 70
    local d = plain * fake / 120
    local expected = math.floor(plain * (1 + (fake - 1) * d * d) + 0.5)
    BaseVehicle.getFakeSpeedModifier = function() return fake end
    local mapped = maxRegAfterRun()
    checkEq(mapped, expected, "(c8) SpeedLimit 70（fake 1.714）→ 定速寫成 v·(1+0.714·(v/70)²)")
    checkTrue(mapped > plain, "(c8) 映射後的 regulator 值高於真速目標")
    BaseVehicle.getFakeSpeedModifier = function() return 1 end
    checkEq(maxRegAfterRun(), plain, "(c8) fake=1（SpeedLimit≥120）→ 恆等")
    BaseVehicle.getFakeSpeedModifier = function() error("no server options") end
    checkEq(maxRegAfterRun(), plain, "(c8) getFakeSpeedModifier 拋錯 → 退回真速、不拋")
    BaseVehicle.getFakeSpeedModifier = nil
    checkEq(drive.calls.fractionalRegSpeed, 0, "(c8) 映射後仍是整數 km/h")
    setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false,
        AutoDriveMaxSpeed = 40, RightLaneBias = 0 })
end
scenarioFakeSpeed()

-- (c3) 停等預算是「同 episode 累計」，不被零星動作續命（2026-09-01 階段 2
--      主體 1 的違規證明）：舊制 waitSince 只要有一幀 avProgress>=1 就整個
--      歸零，實測 blocked 現場車身被物理推得晃一下就無限續命（40s+ 僵局）。
--      新契約：WAIT 意圖的幀時間一律累計，唯一歸零條件是真進度（沿線淨前
--      進 10m），車身晃動不算。
do
    checkTrue(armDrive(), "(c3) 啟動")
    for _, y in ipairs({ -5, -4, -2, -1, 0, 1, 2, 4, 5 }) do
        drive.putSolid(20, y, "harness_wall_" .. y)
    end
    for _, y in ipairs({ -1, 0, 1 }) do
        drive.putSolid(7, y, "harness_rearwall_" .. y)
    end
    dveh._x = 11
    driveTick(dp, dveh)
    drive.scanRound()
    dveh._speed = 0
    driveReset(dveh)
    driveTick(dp, dveh) -- 預算起算
    -- 四段 4 秒停等，每段之間插一幀「車身在動」（舊制的逃逸幀）。位置不變
    -- ＝沿線淨前進 0，不構成真進度。
    for i = 1, 4 do
        nowMs = nowMs + 4000
        driveTick(dp, dveh)
        dveh._speed = 3 -- 舊制此幀 avProgress>=1 → waitSince 歸零＝續命
        driveTick(dp, dveh)
        dveh._speed = 0
        checkTrue(i >= 4 or MDAD.Drive.isActive(0),
            "(c3) 累計 " .. (i * 4) .. " 秒仍在預算內（第 " .. i .. " 段）")
    end
    checkTrue(not MDAD.Drive.isActive(0),
        "(c3) 累計 16 秒 > 15s 總預算：晃動不再續命，紅字交還")
    checkEq(haloKey(), DKEY.STUCK, "(c3) 交還理由是 StopStuck")
    checkEq(drive.infoHaloIndex(), nil, "(c3) 同一啟動不重複診斷提示")
    for _, y in ipairs({ -5, -4, -2, -1, 0, 1, 2, 4, 5 }) do drive.clearCell(20, y) end
    for _, y in ipairs({ -1, 0, 1 }) do drive.clearCell(7, y) end
end

-- (c4) 合法停等不臂進度監督（2026-09-01 階段 2 主體 3 的違規證明）：WAIT
--      意圖＝「該停」，不是「卡死」。監督若被 WAIT 臂起，2.5 秒 PROGRESS_MS
--      就會 suspect→倒車（壓停與脫困互相打架＝s056）。正確行為是 3 秒毫無
--      動作，一直到 BLOCK_RETRY 累計 5 秒才由「主動倒退換視角」出手。
--      本情境後方淨空（與 (c)／(c3) 相反），所以倒車真的會發生＝可觀測。
do
    checkTrue(armDrive(), "(c4) 啟動")
    for _, y in ipairs({ -5, -4, -2, -1, 0, 1, 2, 4, 5 }) do
        drive.putSolid(20, y, "harness_wall_" .. y)
    end
    dveh._x = 11
    driveTick(dp, dveh)
    drive.scanRound()
    dveh._speed = 0
    driveReset(dveh)
    driveTick(dp, dveh) -- 預算起算
    drive.wideRounds(true) -- 停在停點：寬帶判堵到最寬一級（倒車要等這次嘗試的寬帶重判）
    nowMs = nowMs + 200 -- 再一幀確保停等狀態穩定（監督若會臂起，此刻已臂）
    driveReset(dveh)
    driveTick(dp, dveh)
    nowMs = nowMs + 2800 -- 累計 3 秒 > PROGRESS_MS 2.5 秒，但 < BLOCK_RETRY 5 秒
    driveReset(dveh)
    driveTick(dp, dveh)
    checkTrue(haloKey() ~= DKEY.UNSTICK,
        "(c4) 合法停等 3 秒：監督未被臂起，不倒車（實得 "
        .. tostring(haloKey()) .. "）")
    checkEq(dveh._imp.total, 0, "(c4) 合法停等 3 秒零 impulse")
    nowMs = nowMs + 2100 -- 累計 5.1 秒：blocked-retry 出手
    driveReset(dveh)
    driveTick(dp, dveh)
    checkEq(haloKey(), DKEY.UNSTICK,
        "(c4) 累計 5 秒才由 blocked-retry 主動倒退（後方淨空）")
    for _, y in ipairs({ -5, -4, -2, -1, 0, 1, 2, 4, 5 }) do drive.clearCell(20, y) end
    MDAD.Drive.stop(0, nil)
end

-- (c2) 近距跟車（followHold）同豁免：前車臨停常超過 5 秒，倒車＝追撞隊友
do
    checkTrue(armDrive(), "(c2) 啟動")
    dveh._x = 8
    driveTick(dp, dveh)
    -- 前車＝真行進中（輪間位移 0.4m > 0.3 判動、gap 恆 <10 保 followHold）。
    -- 手動控輪：scanRound 一口氣掃兩輪、輪間動不了車；微動用 _x 直調（格鍵
    -- 不變，位置讀 getX）
    local vLead = drive.putVehicle(16, 0, false)
    -- 12 tick＝剛好一輪（658 格 ÷ 56 格/tick）：讓「動車」正好落在輪邊界，
    -- 下一輪讀到的位置必是新值（14 tick 會把下一輪的車格掃進同段——車還沒
    -- 再動，位移 0 被誤判 still）
    nowMs = nowMs + 300
    for _ = 1, 12 do driveTick(dp, dveh) end
    vLead._x = vLead._x + 0.4
    nowMs = nowMs + 300
    for _ = 1, 12 do driveTick(dp, dveh) end
    vLead._x = vLead._x + 0.4
    nowMs = nowMs + 300
    for _ = 1, 12 do driveTick(dp, dveh) end
    dveh._speed = 0
    driveReset(dveh)
    driveTick(dp, dveh) -- followHold（gap ≈ 8.9 < 10）＋waitSince 起算
    vLead._x = vLead._x + 0.4
    nowMs = nowMs + 2000 -- 跟車停等 4s：低於 BLOCK_RETRY 5s（跟車本就不觸發倒退）
    driveTick(dp, dveh)
    vLead._x = vLead._x + 0.4
    nowMs = nowMs + 2000
    driveTick(dp, dveh)
    checkTrue(MDAD.Drive.isActive(0), "(c2) 跟車停等 4 秒：session 活著")
    checkTrue(haloKey() ~= DKEY.UNSTICK and haloKey() ~= DKEY.STUCK,
        "(c2) 跟車停等：無倒車／放棄提示（實得 " .. tostring(haloKey()) .. "）")
    drive.clearVehicle(16, 0)
    MDAD.Drive.stop(0, nil)
end

-- (d) 2.5s supervisor：near-clear 的高檔只 pulse 一次；VERIFY 失敗後 rear-clear
--     才進 unstick。倒車期間每 100ms rear 重查，新增障礙的那幀必須 0 impulse。
do
    drive.fillWorld(-10, 70, -7, 7)
    dveh._com:set(0, 0.5, 1.1) -- valid non-zero COM，舊 bodyCenter anchor 會與 vehicle origin 差 >1m
    checkTrue(armDrive(), "(d) gear-reset/rear 情境啟動")
    setHeading(dveh, 0)
    driveTick(dp, dveh) -- yaw progress，重臂到 heading=0
    drive.scanRound()
    dveh._x = 8
    driveTick(dp, dveh) -- new-route verify 必須以既有 s>1 的同座標系重新 anchor
    dveh._speed, dveh._trans = 70, 3
    drive.stallFrames(2501) -- 停住期間照常跑幀（一次跳 2.5 秒＝客戶端凍住，見 drive.stallFrames）
    local gearReads = 0
    local realTransmission = dveh.getTransmissionNumber
    dveh.getTransmissionNumber = function(self)
        gearReads = gearReads + 1
        return realTransmission(self)
    end
    driveReset(dveh)
    driveTick(dp, dveh)
    checkTrue(MDAD.Drive.isActive(0), "(d) suspect 後 session 活著")
    checkEq(dveh._imp.total, 0, "(d) gear-reset transition 0 impulse")
    checkEq(drive.calls.forceBrake, 0, "(d) 150ms neutral pulse 不混 forceBrake")
    -- 階段 2 主體 2：suspect 這幀車還在 70 km/h，恢復需求只「掛旗標」不動作
    -- （空檔脈衝必須從靜止起手）；旗標幀已經是 regulator off／不煞車／不施力。
    checkEq(dveh._regulator, false, "(d) 恢復需求掛起當幀 regulator 已關")
    checkEq(MDAD.Drive.hudState(0), "unstick",
        "(d) 恢復需求掛起即回報 unstick 狀態（旗標＝閂鎖）")
    dveh._speed = 0
    nowMs = nowMs + 100
    driveReset(dveh)
    driveTick(dp, dveh)
    checkEq(dveh._regulator, false, "(d) pulse 未滿 150ms 繼續 regulator off")
    checkEq(dveh._imp.total, 0, "(d) pulse 未滿 150ms 仍 0 impulse")
    checkEq(drive.calls.forceBrake, 0, "(d) pulse 未滿 150ms 仍不 forceBrake")
    drive.nav.route = newRoute(40, 0, 0, 4, 0) -- same-target cutover after pulse deadline
    nowMs = nowMs + 150
    driveReset(dveh)
    driveTick(dp, dveh)
    driveTick(dp, dveh)
    checkTrue(MDAD.Drive.isActive(0),
        "(d) gear-reset cutover build 後重新 anchor 2s VERIFY")
    nowMs = nowMs + 2001
    driveReset(dveh)
    driveTick(dp, dveh) -- VERIFY timeout → recovery stop → initial rear clear → unstick
    checkEq(gearReads, 1, "(d) 同 episode 高檔 getter/pulse 恰一次")
    checkEq(haloKey(), DKEY.UNSTICK, "(d) rear clear 才開始 unstick")
    drive.putSolid(4, 0, "harness_rear_mid") -- 車在 x=8、COM forward offset=1.1；rear sweep 約 x=3..7
    nowMs = nowMs + 100
    driveReset(dveh)
    driveTick(dp, dveh)
    -- 2026-09-04 契約翻轉（s051/s052：倒 1.3-1.8 秒探到後方 5m 的燒毀車就整個交還＝「太早
    -- 停」）：中途 rear hard 一寸未退＝回停等（同起步前 softFail），退過 UNSTICK_MIN_M＝settle
    -- 重掃；兩者都不交還、都零 reverse impulse。
    checkTrue(MDAD.Drive.isActive(0), "(d) unstick 中途 rear hard：不交還（一寸未退→回停等）")
    checkEq(dveh._imp.total, 0, "(d) rear hard 命中幀零 reverse impulse")
    checkEq(MDAD.Drive.hudState(0), "follow", "(d) 未退即回 follow 停等節奏（實得 " .. tostring(MDAD.Drive.hudState(0)) .. "）")
    checkTrue(haloKey() ~= DKEY.STUCK, "(d) 不出 StopStuck 紅字")
    checkEq(drive.infoHaloIndex(), nil, "(d) 同一啟動不重複診斷提示")
    drive.clearCell(4, 0)
    dveh.getTransmissionNumber = realTransmission
    dveh._com:set(0, 0.5, 0)
end

-- (d1b) Sensor probe Java errors preserve detail through the public pcall boundary.
-- Driver fails closed, logs the detail once, and sends no reverse impulse.
do
    drive.fillWorld(-10, 70, -7, 7)
    checkTrue(armDrive(), "(d1b) probe throw 啟動")
    setHeading(dveh, 0)
    driveTick(dp, dveh)
    dveh._speed, dveh._trans = 0, 1
    local realGrid = drive.cell.getGridSquare
    drive.cell.getGridSquare = function(self, x, y, z)
        if x == -4 then error("probe-grid-boom") end -- rear strip only；不炸 forward Sensor.step
        return realGrid(self, x, y, z)
    end
    -- 2026-09-01 demand 收緊後，大跳時（sensor stale → target 壓 0）不再臂起
    -- 監督（壓停≠卡死）。改小步推進：100ms/tick 讓掃描保鮮，前 ~1s 剖面
    -- 建立後 target≥1 臂起 watch，再 2.5s 零位移 → suspect → recover →
    -- rearProbe 踩 stub throw → fail-closed。窗內 assist 可打「前向」force，
    -- 契約只禁止反向（倒車）分量，逐拍記錄方向。
    driveReset(dveh)
    local sawReverse = false
    for _ = 1, 36 do
        nowMs = nowMs + 100
        local before = dveh._imp.total
        driveTick(dp, dveh)
        if dveh._imp.total > before
                and dveh._imp.x * dveh._fwdX + dveh._imp.z * dveh._fwdY < -0.01 then
            sawReverse = true
        end
    end
    drive.cell.getGridSquare = realGrid
    -- 2026-09-01 新契約：probe throw fail-closed（零倒車）但 session 回停等
    checkTrue(MDAD.Drive.isActive(0), "(d1b) probe throw fail-closed 不倒車、session 活著")
    checkFalse(sawReverse, "(d1b) probe throw 0 reverse impulse")
    local sawDetail = false
    for _, line in ipairs(drive.logs) do
        if line:find("probe-grid-boom", 1, true) then sawDetail = true end
    end
    checkTrue(sawDetail, "(d1b) probe throw detail log once 可見")
    dveh._trans = 2
end

-- (d2) current-body contact 產生 episode ban；成功倒 3m 先 SETTLE 到 <1km/h，
--      sensor reset 與 same-target route cutover 都保留 ban；前進 10m＋兩輪 clear 才 rearm。
do
    drive.fillWorld(-10, 70, -7, 7)
    local realPlan = MDADCorridor.plan
    local sawRecoveryBan = false
    MDADCorridor.plan = function(hs, hl, hn, need, corr, prefer, hr, ...)
        if type(hr) == "table" then
            for i = 1, hn do
                if hr[i] == 0.6 then sawRecoveryBan = true end
            end
        end
        return realPlan(hs, hl, hn, need, corr, prefer, hr, ...)
    end
    checkTrue(armDrive(), "(d2) contact/settle 情境啟動")
    setHeading(dveh, 0)
    driveTick(dp, dveh)
    dveh._trans = 1 -- contact 不走 gear-reset；低檔也不應 pulse
    drive.putSolid(2, 0, "harness_current_contact")
    drive.scanRound(true)
    dveh._x = 1.1 -- 已跨舊 progress anchor 1m，但車身仍包住 x=2.5 障礙
    driveReset(dveh)
    driveTick(dp, dveh)
    checkEq(dveh._regulator, false,
        "(d2) world progress 達標不得旁路 currentBlocked")
    checkTrue(drive.calls.forceBrake >= 1,
        "(d2) currentBlocked 只由兩輪 footprint clear 解除")
    drive.clearCell(2, 0)
    drive.scanRound()
    driveReset(dveh)
    driveTick(dp, dveh)
    checkEq(dveh._regulator, false, "(d2) 一輪 footprint clear 仍保持 currentBlocked")
    drive.scanRound()
    driveReset(dveh)
    driveTick(dp, dveh)
    -- 2026-09-01 契約更新（entry minimum 退役＋空間公式只壓速）：recovery-ban
    -- 的縫仍被 ban（sawRecoveryBan 斷言在後），但替代縫的陡切過渡現在可行
    -- ——「不乾等」裁定下應立即繞行（AVOID＋供油），不再 HOLD 武裝等待。
    checkEq(MDAD.Drive.controlState(0), "AVOID",
        "(d2) current-body clear 後有替代縫：立即繞行不乾等")
    drive.scanRound()
    driveReset(dveh)
    driveTick(dp, dveh)
    checkEq(dveh._regulator, true,
        "(d2) 繞行替代縫恢復供油（陡切可行、速度由連續 cap 決定）")
    drive.putSolid(2, 0, "harness_current_contact_again")
    drive.scanRound(true)
    dveh._x = 0
    dveh._speed = 0
    driveReset(dveh)
    driveTick(dp, dveh) -- 先以目前卡點重臂 progress anchor，再累計完整 2.5s
    nowMs = nowMs + 2501
    driveReset(dveh)
    driveTick(dp, dveh)
    checkEq(haloKey(), DKEY.UNSTICK, "(d2) current contact rear-clear 後開始 unstick")
    nowMs = nowMs + 16
    driveReset(dveh)
    driveTick(dp, dveh)
    checkEq(dveh._imp.total, 1, "(d2) unstick 幀恰一次 reverse impulse")
    checkTrue(dveh._imp.x * dveh._fwdX + dveh._imp.z * dveh._fwdY < 0,
        "(d2) reverse impulse 無 longitudinal forward 分量")

    dveh._x, dveh._speed = -3.1, -13
    nowMs = nowMs + 16
    driveReset(dveh)
    driveTick(dp, dveh)
    checkTrue(MDAD.Drive.isActive(0), "(d2) 退 3m 成功後進 settle，session 保留")
    checkEq(dveh._regulator, false, "(d2) settle regulator off")
    checkTrue(drive.calls.forceBrake >= 1, "(d2) -13km/h settle 強制煞停")
    checkEq(dveh._imp.total, 0, "(d2) settle 0 impulse")
    dveh._speed = -0.5
    nowMs = nowMs + 100
    driveReset(dveh)
    driveTick(dp, dveh) -- settle 完成，sensor reset + forced replan
    drive.clearCell(2, 0) -- remap 不得依賴首輪仍掃到舊 hard point

    sawRecoveryBan = false
    drive.nav.route = newRoute(40, 0, 0, 4, 0) -- same target deviation
    nowMs = nowMs + 300
    driveTick(dp, dveh)
    drive.scanRound()
    checkTrue(sawRecoveryBan, "(d2) same-target route cutover remap 並保留 recovery ban")

    sawRecoveryBan = false
    drive.nav.route = newRoute(40, 0, 8, 4, 0) -- old hit 離新 route > corridor、但不超 RETURN 容量
    nowMs = nowMs + 300
    driveTick(dp, dveh)
    drive.scanRound()
    checkFalse(sawRecoveryBan,
        "(d2) world hit 離新 route 太遠：保留 attempts/world memory 但不套 Frenet ban")

    sawRecoveryBan = false
    drive.nav.route = newRoute(40, 0, 0, 4, 0)
    nowMs = nowMs + 300
    driveTick(dp, dveh)
    for _ = 1, 4 do
        if not sawRecoveryBan then drive.scanRound() end
    end
    checkTrue(sawRecoveryBan, "(d2) 後續 near route 可重新投影同一 world hit")
    dveh._x, dveh._speed = 13.0, 20 -- >10m from projected world hit
    drive.scanRound()
    drive.scanRound() -- >10m world + 連續兩輪 footprint clear
    sawRecoveryBan = false
    drive.putSolid(20, 0, "harness_rearmed")
    drive.scanRound()
    checkFalse(sawRecoveryBan, "(d2) 10m＋兩輪 clear 後 episode rearmed、ban 清除")
    MDADCorridor.plan = realPlan
    drive.clearCell(20, 0)
    dveh._trans = 2
    MDAD.Drive.stop(0, nil)
end

-- (pb) 2026-09-27 正式服 5 段：visibility／原生未載入 chunk 煞車把車壓停（isBraking 真、fbl 0），
--      前方淨空卻被 2.5 秒停滯監督判 suspect 倒車。受控煞停期間停滯計時暫停，煞車解除後接著算；
--      連續煞停超過 PROGRESS_BRAKE_GRACE_MS 不再暫停。違規證明：progressPauseMs 恆回 0＝(pb) 紅。
do
    drive.fillWorld(-10, 70, -7, 7)
    checkTrue(armDrive(), "(pb) 受控煞停情境啟動")
    setHeading(dveh, 0)
    driveTick(dp, dveh)
    local stp = MDAD.Drive.debugSession(0)
    local function hold(ms, braking)
        dveh._speed, dveh._braking = 0, braking
        local t = 0
        while t < ms do
            nowMs = nowMs + 100
            t = t + 100
            driveReset(dveh)
            driveTick(dp, dveh)
            local ps = stp.progressState
            if (ps ~= "watch" and ps ~= "disarmed") or stp.mode == "unstick" then return true end
        end
        return false
    end
    checkFalse(hold(3500, true), "(pb) 原生煞車壓停 3.5 秒：不判卡死、不倒車")
    checkTrue(MDAD.Drive.isActive(0), "(pb) 煞停等待期間仍在自駕")
    checkTrue(hold(3000, false), "(pb) 煞車解除後真的不動：停滯計時接著算、照常判卡死")
    MDAD.Drive.stop(0, nil)
    checkTrue(armDrive(), "(pb) 煞停上限情境啟動")
    setHeading(dveh, 0)
    driveTick(dp, dveh)
    stp = MDAD.Drive.debugSession(0)
    checkTrue(hold(8000, true), "(pb) 連續煞停超過寬限：仍當卡死（不讓車乾等）")
    dveh._braking = false
    MDAD.Drive.stop(0, nil)
    -- (pb-gap) 煞停 3 秒→離開 watch 1 秒（不呼叫）→再煞停：寬限重新起算，第二段仍暫停計時。
    --   違規證明：拿掉 gap 時重設 progressBrakedSince＝第二段首 1 秒就回 0。
    local fake = { progressPauseAt = nil, progressBrakedSince = 0, forceBrakeUntil = 0 }
    local fveh = { isBraking = function() return true end }
    local tp = 0
    for _ = 1, 30 do tp = tp + 100; MDAD.Drive.progressPauseMs(fake, fveh, tp, 0) end
    tp = tp + 1000
    local paused = 0
    for _ = 1, 10 do tp = tp + 100; paused = paused + MDAD.Drive.progressPauseMs(fake, fveh, tp, 0) end
    checkEq(paused, 900, "(pb-gap) 中斷後再次煞停：新寬限重新起算、這 1 秒仍暫停停滯計時")
end

-- (d2b) SETTLE itself is bounded: non-finite speed or a brake phase exceeding its
-- deadline stops instead of holding forceBrake forever.
do
    local function enterSettle(label)
        drive.fillWorld(-10, 70, -7, 7)
        checkTrue(armDrive(), label .. " 啟動")
        setHeading(dveh, 0)
        driveTick(dp, dveh)
        dveh._trans = 1
        drive.putSolid(2, 0, "harness_settle_bound")
        drive.scanRound(true)
        dveh._speed = 0
        nowMs = nowMs + 2501
        driveReset(dveh)
        driveTick(dp, dveh)
        dveh._x, dveh._speed = -3.1, -13
        nowMs = nowMs + 16
        driveReset(dveh)
        driveTick(dp, dveh)
        checkTrue(MDAD.Drive.isActive(0), label .. " 已進 settle")
    end

    enterSettle("(d2b) NaN")
    dveh._speed = 0 / 0
    nowMs = nowMs + 16
    driveTick(dp, dveh)
    checkFalse(MDAD.Drive.isActive(0), "(d2b) settle NaN fail-stop")

    enterSettle("(d2b) deadline")
    dveh._speed = -5
    nowMs = nowMs + 4001
    driveTick(dp, dveh)
    checkFalse(MDAD.Drive.isActive(0), "(d2b) settle deadline fail-stop")
    dveh._trans = 2
end

-- (d2t) 倒車時限到時已退出 UNSTICK_MIN_M＝倒夠了進 settle 重掃，不交還（同 rear-blocked 規則）；
-- 一寸未退（<1m）照舊 StopStuck。2026-09-26 E2E trailer-grass-mp：拖著掛車在草地 4 秒只退 2.2m 就交還。
do
    local function reverseFor(label, backM)
        drive.fillWorld(-10, 70, -7, 7)
        checkTrue(armDrive(), label .. " 啟動")
        setHeading(dveh, 0)
        driveTick(dp, dveh)
        dveh._trans = 1
        drive.putSolid(2, 0, "harness_unstick_timeout")
        drive.scanRound(true)
        dveh._speed = 0
        nowMs = nowMs + 2501
        driveReset(dveh)
        driveTick(dp, dveh)
        checkEq(haloKey(), DKEY.UNSTICK, label .. " 已進倒車脫困")
        dveh._x, dveh._speed = -backM, -3
        nowMs = nowMs + 16
        driveReset(dveh)
        driveTick(dp, dveh)
        checkEq(MDAD.Drive.debugSession(0).mode, "unstick", label .. " 退 " .. backM .. "m 仍在倒車（未達標準退距）")
        nowMs = nowMs + 4001
        driveReset(dveh)
        driveTick(dp, dveh)
    end
    reverseFor("(d2t) 退 1.5m", 1.5)
    checkTrue(MDAD.Drive.isActive(0), "(d2t) 時限到、已退 1.5m：不交還")
    checkEq(MDAD.Drive.debugSession(0).mode, "settle", "(d2t) 時限到、已退 1.5m：進 settle 重掃")
    MDAD.Drive.stop(0, nil)
    drive.clearCell(2, 0)
    reverseFor("(d2t) 退 0.5m", 0.5)
    checkFalse(MDAD.Drive.isActive(0), "(d2t) 時限到、只退 0.5m：照舊交還")
    drive.clearCell(2, 0)
    dveh._trans = 2
end

-- (d2c) A true target change never preserves recovery state. Mid-unstick it first
-- enters bounded settle (zero impulse), then builds the new route after stopping.
do
    drive.fillWorld(-10, 70, -7, 7)
    checkTrue(armDrive(), "(d2c) target change mid-unstick 啟動")
    setHeading(dveh, 0)
    driveTick(dp, dveh)
    dveh._trans = 1
    drive.putSolid(2, 0, "harness_target_change_recovery")
    drive.scanRound(true)
    driveReset(dveh)
    driveTick(dp, dveh) -- current contact 完成後明確建立 2.5s progress anchor
    dveh._speed = 0
    nowMs = nowMs + 2501
    driveTick(dp, dveh)
    checkEq(haloKey(), DKEY.UNSTICK, "(d2c) 已進 unstick")
    dveh._speed = -5
    drive.nav.tx = 300.1
    drive.nav.route = newRoute(40, 0, 0, 4, 0)
    nowMs = nowMs + 250
    driveReset(dveh)
    driveTick(dp, dveh)
    checkTrue(MDAD.Drive.isActive(0), "(d2c) true target change 保留 bounded settle session")
    checkEq(dveh._imp.total, 0, "(d2c) target change 當幀停止 reverse impulse")
    checkTrue(drive.calls.forceBrake >= 1, "(d2c) target change mid-unstick 先 settle")
    dveh._speed = 0
    nowMs = nowMs + 16
    driveTick(dp, dveh) -- settle 完成 → build
    driveReset(dveh)
    driveTick(dp, dveh) -- build ready；首輪新 snapshot 前仍須保留 current contact
    checkTrue(MDAD.Drive.isActive(0), "(d2c) 停妥後建立新 route")
    checkEq(dveh._regulator, false,
        "(d2c) true target change 不得清掉世界座標 current contact")
    checkTrue(drive.calls.maxRegSpeed <= 15 or drive.calls.regulatorOff > 0,
        "(d2c) 新 route 首輪 snapshot 前 fail-closed command <=15")
    drive.nav.tx = 300
    dveh._trans = 2
    MDAD.Drive.stop(0, nil)
end

-- (d3) attempt budget belongs to the episode, not a route identity. Three successful
-- reverse attempts without 10m rearm are allowed; the fourth recovery request stops.
do
    drive.fillWorld(-10, 70, -7, 7)
    checkTrue(armDrive(), "(d3) max-attempt episode 啟動")
    setHeading(dveh, 0)
    driveTick(dp, dveh)
    dveh._trans = 1
    drive.putSolid(2, 0, "harness_attempt_limit")
    drive.scanRound(true)
    local unstickVoicesBefore = drive.voiceCount("unstick")
    for attempt = 1, 3 do
        dveh._speed = 0
        nowMs = nowMs + 2501
        driveReset(dveh)
        driveTick(dp, dveh)
        checkEq(haloKey(), DKEY.UNSTICK,
            "(d3) attempt " .. tostring(attempt) .. " starts")
        checkEq(drive.voiceCount("unstick") - unstickVoicesBefore, 1,
            "(d3) attempt " .. tostring(attempt) .. "：同 episode 只在第一次倒退開口")
        dveh._x, dveh._speed = -3.1, -13
        nowMs = nowMs + 16
        driveReset(dveh)
        driveTick(dp, dveh) -- success → settle
        dveh._speed = 0
        nowMs = nowMs + 16
        driveTick(dp, dveh) -- settle complete
        if attempt < 3 then
            dveh._x = 0
            drive.scanRound() -- same episode contact again；world progress <10m
        end
    end
    dveh._x, dveh._speed = 0, 0
    drive.scanRound()
    nowMs = nowMs + 2501
    driveReset(dveh)
    driveTick(dp, dveh)
    -- 2026-09-01 新契約：額度用盡回停等（15s timeout 兜底），不立即紅字
    checkTrue(MDAD.Drive.isActive(0), "(d3) fourth recovery request soft-fails（回停等）")
    checkTrue(haloKey() ~= DKEY.STUCK, "(d3) max3 不再立即 StopStuck")
    dveh._trans = 2
    drive.clearCell(2, 0) -- 不把 current-contact fixture 洩漏到 warm／detour 情境
end

-- (e) 感知空窗爬行：session 起步／route cutover 後首輪掃描完成前，
--     「hardN=0」是**還不知道**不是淨空——壓爬行 12 等首輪（事件驅動）。
--     2026-08-29 實測：改導航目標→調頭→正對 4m 外剛才還有紅圈的車加速，
--     首輪掃完 blocked 已物理煞不住
do
    checkTrue(armDrive(), "(e) 啟動")
    setHeading(dveh, 0.05) -- 車頭對準：排除航向誤差減速（armDrive 預設 0.3 rad 壓 40→35）
    driveReset(dveh)
    driveTick(dp, dveh) -- armDrive 後尚未跑過任何掃描輪：stamp==0
    checkTrue(drive.calls.maxRegSpeed >= 0 and drive.calls.maxRegSpeed <= 12,
        "(e) 首輪掃描完成前 command 不超過 12")
    drive.scanRound() -- 首輪完成（stamp>0）
    driveReset(dveh)
    driveTick(dp, dveh)
    checkTrue(drive.calls.maxRegSpeed >= 0 and drive.calls.maxRegSpeed <= 40,
        "(e) 首輪完成後仍按 jerk/gate 包絡恢復")
    MDAD.Drive.stop(0, nil)
end

-- (e2) 近終點免臂（2026-09-01 s058）：終點前 ARRIVE_M+3 帶內的低速是到站
--     收尾（visibility／align 近終點自然壓低、引擎 bang-bang 顆粒粗），
--     不得誤判卡死觸發倒車脫困——s058 實測終點前 5.5m 反覆倒車 20m 永遠
--     進不了站。對照組（帶外 rem 10）同樣蠕動必須照樣臂起，證明監督活著。
do
    drive.fillWorld(-10, 70, -7, 7)
    -- 實驗組：12m 短線（4 點×4m）、車在 s=6 → rem 6（ARRIVE_M(5) 圈外、
    -- +3 帶內）蠕動 3 秒 → 不倒車。armDrive 預設 route 長 156m（40 點），
    -- terminal 帶造不出來，先 same-target cutover 成短線。
    checkTrue(armDrive(), "(e2) 近終點情境啟動")
    setHeading(dveh, 0.05)
    dveh._trans = 1
    drive.nav.route = newRoute(4, 0, 0, 4, 0)
    dveh._x, dveh._speed = 6, 0.3
    drive.scanRound(true)
    driveReset(dveh)
    local sawUnstick = false
    for _ = 1, 30 do
        nowMs = nowMs + 100
        driveTick(dp, dveh)
        if haloKey() == DKEY.UNSTICK then sawUnstick = true end
    end
    checkFalse(sawUnstick, "(e2) 近終點蠕動不觸發倒車脫困")
    checkTrue(MDAD.Drive.isActive(0), "(e2) 近終點蠕動 session 活著")
    MDAD.Drive.stop(0, nil)
    -- 對照組：rem ≈ 10（帶外）同樣蠕動 → 監督照臂、倒車脫困觸發
    checkTrue(armDrive(), "(e2) 帶外對照組啟動")
    setHeading(dveh, 0.05)
    dveh._trans = 1
    dveh._x, dveh._speed = 30, 0.3
    drive.scanRound(true)
    driveReset(dveh)
    for _ = 1, 30 do
        nowMs = nowMs + 100
        driveTick(dp, dveh)
        if haloKey() == DKEY.UNSTICK then sawUnstick = true end
    end
    checkTrue(sawUnstick, "(e2) 帶外同樣蠕動照樣臂起倒車（對照）")
    MDAD.Drive.stop(0, nil)
    dveh._trans = 2
end


-- (f) 堵死改道機制已移除（2026-09-01 使用者裁定；telemetry s030/s033）：
--     blocked 的出路只留本地感知繞行與 20 秒紅字交還（既有情境另有覆蓋）。


-- =====================================================================
-- 情境二十八c：MP 登入補學（client 逐 slot 請求 → server actor-bound 補學）
--              ＋專屬雜誌的戰利品注入與生成政策
--
-- 實機病徵：MP 玩家「完成製作但零產出」。NeedToBeLearn=true 的配方對既有角色
-- 永遠沒學到——AutoLearnAny 只在升等瞬間（XpUpdate.lua:204 →
-- ScriptManager.checkAutoLearn＝ScriptManager.java:1141-1154）與**單機**開局
-- （IsoWorld.java:2410，只針對 IsoPlayer.getInstance()）被檢查，專用伺服器上的
-- 遠端角色兩個時機都碰不到。
-- =====================================================================
scenario("MP 登入補學：主玩家延到首個 Tick、逐 slot 請求、只信 actor、只補自己的兩個配方、學到才同步；雜誌注入與生成政策")

-- (1) client 端：OnGameStart 尚不能送 command；首個 Tick 逐本機 slot，新 slot 上線再補一則
do
    clientFlag, serverFlag = true, false
    setSandbox({ InstallSkillGate = true, NeedItemForNav = false })
    local a = newPlayer({ num = 0, username = "rescan0", onlineId = 7001 })
    local b = newPlayer({ num = 1, username = "rescan1", onlineId = 7002 })
    players[0], players[1], players[2] = a, b, nil
    activePlayers = 2

    resetStats()
    capturePrint(function() fire("OnGameStart") end)
    checkEq(#sentClient, 0, "OnGameStart 尚未 ingame，不提前送登入補學請求")
    capturePrint(function() fire("OnTick", 0) end)
    checkEq(#sentClient, 2, "首個 Tick 替每個本機 slot 各送一則登入補學請求")
    checkEq(sentClient[1] and sentClient[1].module, MOD_ID, "請求帶自己的 module 名")
    checkEq(sentClient[1] and sentClient[1].command, MDAD.CMD_RECIPE_RESCAN,
        "使用獨立的 RecipeRescan command")
    -- 分割畫面共用一條連線：伺服器只能靠具體玩家物件分辨 actor，送 slot 索引等於
    -- 讓兩位玩家的補學互相蓋掉
    checkEq(sentClient[1] and sentClient[1].player, a, "slot 0 的請求帶 slot 0 的玩家物件")
    checkEq(sentClient[2] and sentClient[2].player, b, "slot 1 的請求帶 slot 1 的玩家物件")
    checkEq(type(sentClient[1] and sentClient[1].args), "table", "payload 是表（空表）")
    checkNil(sentClient[1] and sentClient[1].args.recipe, "client 不指定要補哪個配方")
    checkNil(sentClient[1] and sentClient[1].args.target, "client 不指定要補給誰")
    checkNil(sentClient[1] and sentClient[1].args.username, "client 不指定角色名")
    checkEq(#halos, 0, "登入補學不對玩家丟提示（NeedItemForNav 關閉時本來就無感）")
    local sentAfterReady = #sentClient
    capturePrint(function() fire("OnTick", 1) end)
    checkEq(#sentClient, sentAfterReady, "登入補學 Tick callback 執行一次後即移除")

    players[2] = newPlayer({ num = 2, username = "rescan2", onlineId = 7003 })
    activePlayers = 3
    resetStats()
    capturePrint(function() fire("OnCreatePlayer", 2) end)
    checkEq(#sentClient, 1, "分割畫面新 slot 上線只補送自己那一則")
    checkEq(sentClient[1] and sentClient[1].player, players[2], "補送的是新 slot 的玩家物件")

    -- 玩家物件還沒建立的 slot：不能送 nil actor 的請求
    players[2] = nil
    resetStats()
    capturePrint(function() fire("OnCreatePlayer", 2) end)
    checkEq(#sentClient, 0, "玩家物件還沒建立時不送請求")

    -- SP：P0 由引擎開局補學，但後加入的分割畫面 slot 沒有該 Java 路徑；
    -- client 檔因此就地逐配方重掃，且不發 client command／同步封包。
    clientFlag, serverFlag = false, false
    recipeWorld.defs[MDAD.RECIPE_GPS] =
        recipeWorld.newRecipe(MDAD.RECIPE_GPS, Perks.Electricity, 6)
    recipeWorld.defs[MDAD.RECIPE_AUTO] =
        recipeWorld.newRecipe(MDAD.RECIPE_AUTO, Perks.Electricity, 8)
    players[0] = newPlayer({ num = 0, electricity = 9, username = "sp0", onlineId = -1 })
    players[1] = newPlayer({ num = 1, electricity = 9, username = "sp1", onlineId = -1 })
    activePlayers = 2
    resetStats()
    capturePrint(function() fire("OnGameStart") end)
    checkEq(#sentClient, 0, "SP 就地補學，不發 client command")
    checkTrue(players[0]:getKnownRecipes():contains(MDAD.RECIPE_GPS)
        and players[0]:getKnownRecipes():contains(MDAD.RECIPE_AUTO),
        "SP slot 0 兩份配方皆按門檻補學")
    checkTrue(players[1]:getKnownRecipes():contains(MDAD.RECIPE_GPS)
        and players[1]:getKnownRecipes():contains(MDAD.RECIPE_AUTO),
        "SP 後加入的 split-screen slot 也補學")
    checkEq(#recipeWorld.syncs, 0, "SP 本機狀態不送 PF_Recipes 封包")
    players[2] = newPlayer({ num = 2, electricity = 9, username = "sp2", onlineId = -1 })
    activePlayers = 3
    resetStats()
    capturePrint(function() fire("OnCreatePlayer", 2) end)
    checkEq(#sentClient, 0, "SP 後加入 slot 不發 client command")
    checkTrue(players[2]:getKnownRecipes():contains(MDAD.RECIPE_GPS)
        and players[2]:getKnownRecipes():contains(MDAD.RECIPE_AUTO),
        "SP 後加入 slot 由 OnCreatePlayer 就地補學")
    checkEq(#recipeWorld.syncs, 0, "SP 後加入 slot 不送 PF_Recipes")
    recipeWorld.defs[MDAD.RECIPE_GPS] = nil
    players[3] = newPlayer({ num = 3, electricity = 9, username = "sp3", onlineId = -1 })
    activePlayers = 4
    resetStats()
    local missingLog1 = capturePrint(function() fire("OnCreatePlayer", 3) end)
    resetStats()
    local missingLog2 = capturePrint(function() fire("OnCreatePlayer", 3) end)
    checkTrue(logHas(missingLog1, "craftRecipe not found: " .. MDAD.RECIPE_GPS),
        "SP 缺配方留下含短名的診斷")
    checkFalse(logHas(missingLog2, "craftRecipe not found: " .. MDAD.RECIPE_GPS),
        "SP 同一缺配方只記錄一次")
    recipeWorld.defs[MDAD.RECIPE_GPS] =
        recipeWorld.newRecipe(MDAD.RECIPE_GPS, Perks.Electricity, 6)
end

-- (2) server 端：只信事件 actor、只碰自己的兩個配方、真的學到才同步
do
    clientFlag, serverFlag = false, true
    recipeWorld.defs[MDAD.RECIPE_GPS] =
        recipeWorld.newRecipe(MDAD.RECIPE_GPS, Perks.Electricity, 6)
    recipeWorld.defs[MDAD.RECIPE_AUTO] =
        recipeWorld.newRecipe(MDAD.RECIPE_AUTO, Perks.Electricity, 8)

    local veteran = newPlayer({ num = 0, electricity = 9, username = "veteran", onlineId = 7101 })
    local rookie = newPlayer({ num = 1, electricity = 2, username = "rookie", onlineId = 7102 })
    local mid = newPlayer({ num = 2, electricity = 6, username = "mid", onlineId = 7103 })

    -- 技能早就達標卻沒學過（正是實機那批老角色）：兩個配方都補上，同步一次
    nowMs = nowMs + 1000
    resetStats()
    fire("OnClientCommand", MOD_ID, MDAD.CMD_RECIPE_RESCAN, veteran, {})
    checkTrue(veteran:getKnownRecipes():contains(MDAD.RECIPE_GPS), "技能 9：補學 GPS 配方")
    checkTrue(veteran:getKnownRecipes():contains(MDAD.RECIPE_AUTO), "技能 9：補學自駕配方")
    checkEq(#recipeWorld.lookups, 2, "只查本 MOD 自己的兩個配方")
    checkEq(recipeWorld.lookups[1], MDAD.RECIPE_GPS, "查的第一支是 GPS 配方短名")
    checkEq(recipeWorld.lookups[2], MDAD.RECIPE_AUTO, "查的第二支是自駕配方短名")
    checkEq(#recipeWorld.learns, 2, "兩支都交給引擎的 checkAutoLearnAnySkills 判定")
    checkEq(recipeWorld.learns[1] and recipeWorld.learns[1].chr, veteran,
        "判定對象是事件 actor")
    checkEq(recipeWorld.learns[2] and recipeWorld.learns[2].chr, veteran,
        "第二支的判定對象也是同一位 actor")
    checkEq(#recipeWorld.syncs, 1, "真的學到新配方才送一次 PF_Recipes")
    checkEq(recipeWorld.syncs[1] and recipeWorld.syncs[1].flags, 0x01,
        "同步旗標是 PF_Recipes（0x01）")
    checkEq(recipeWorld.syncs[1] and recipeWorld.syncs[1].player, veteran,
        "同步的是 actor 自己")

    -- 重播：已經學會 → knownRecipes 沒變 → 不再送封包
    nowMs = nowMs + 1000
    resetStats()
    fire("OnClientCommand", MOD_ID, MDAD.CMD_RECIPE_RESCAN, veteran, {})
    checkEq(#recipeWorld.learns, 2, "已學會仍照樣交給引擎重判（判定權不搬進 Lua）")
    checkEq(#recipeWorld.syncs, 0, "已學會時不送同步（每次登入白送封包沒意義）")
    checkEq(veteran:getKnownRecipes():size(), 2, "不會重複塞同一個配方")

    -- 技能不足：一個都不補、也不同步
    nowMs = nowMs + 1000
    resetStats()
    fire("OnClientCommand", MOD_ID, MDAD.CMD_RECIPE_RESCAN, rookie, {})
    checkEq(#recipeWorld.learns, 2, "技能不足也照樣問引擎（門檻只寫在 scripts）")
    checkEq(rookie:getKnownRecipes():size(), 0, "技能 2：不補學")
    checkEq(#recipeWorld.syncs, 0, "沒學到就不送同步")

    -- 只達 GPS 門檻：部分補學也要同步一次
    nowMs = nowMs + 1000
    resetStats()
    fire("OnClientCommand", MOD_ID, MDAD.CMD_RECIPE_RESCAN, mid, {})
    checkTrue(mid:getKnownRecipes():contains(MDAD.RECIPE_GPS), "技能 6：補學 GPS 配方")
    checkFalse(mid:getKnownRecipes():contains(MDAD.RECIPE_AUTO), "技能 6 未達自駕門檻：不補")
    checkEq(#recipeWorld.syncs, 1, "只補到一支也要同步一次")

    -- 偽造 payload：不能替別人補、不能指定配方、不能宣告等級
    local victim = newPlayer({
        num = 3, electricity = 9, username = "victim", onlineId = 7106,
    })
    nowMs = nowMs + 1000
    resetStats()
    fire("OnClientCommand", MOD_ID, MDAD.CMD_RECIPE_RESCAN, rookie,
        { target = victim, username = "victim", recipe = "Herbalist",
            recipes = { "Herbalist" }, electricity = 10, level = 10 })
    checkEq(rookie:getKnownRecipes():size(), 0, "偽造等級不能讓技能不足者補學")
    checkFalse(rookie:getKnownRecipes():contains("Herbalist"), "client 指定的配方一律不學")
    checkEq(#recipeWorld.lookups, 2, "偽造 recipe 欄位不會多查一支配方")
    checkEq(recipeWorld.lookups[1], MDAD.RECIPE_GPS, "偽造封包查的仍是自己的 GPS 配方")
    checkEq(#recipeWorld.syncs, 0, "偽造封包不觸發任何同步")
    checkEq(victim:getKnownRecipes():size(), 0, "偽造 target 不能替別人補學")
    checkEq(recipeWorld.learns[1] and recipeWorld.learns[1].chr, rookie,
        "偽造 payload 後引擎判定對象仍是事件 actor")

    -- 空／非表 payload 走同一條路（production 完全不讀 payload）
    nowMs = nowMs + 1000
    resetStats()
    fire("OnClientCommand", MOD_ID, MDAD.CMD_RECIPE_RESCAN, mid, nil)
    checkEq(#recipeWorld.lookups, 2, "payload 為 nil 照樣替 actor 重掃")
    nowMs = nowMs + 1000
    resetStats()
    fire("OnClientCommand", MOD_ID, MDAD.CMD_RECIPE_RESCAN, mid, "forged")
    checkEq(#recipeWorld.lookups, 2, "payload 是字串也不影響（完全不讀）")

    -- 沒有 actor／別的 module：不處理
    nowMs = nowMs + 1000
    resetStats()
    fire("OnClientCommand", MOD_ID, MDAD.CMD_RECIPE_RESCAN, nil, {})
    fire("OnClientCommand", "SomeOtherMod", MDAD.CMD_RECIPE_RESCAN, veteran, {})
    checkEq(#recipeWorld.lookups, 0, "沒有 actor 或別的 module 的封包完全不處理")

    -- 沿用既有 250ms per-player 節流：洪水封包不能每發都重掃配方
    nowMs = nowMs + 1000
    resetStats()
    fire("OnClientCommand", MOD_ID, MDAD.CMD_RECIPE_RESCAN, rookie, {})
    checkEq(#recipeWorld.lookups, 2, "節流窗外的請求正常處理")
    fire("OnClientCommand", MOD_ID, MDAD.CMD_RECIPE_RESCAN, rookie, {})
    checkEq(#recipeWorld.lookups, 2, "同一 actor 250ms 內的重發被既有節流擋掉")
    nowMs = nowMs + 250
    fire("OnClientCommand", MOD_ID, MDAD.CMD_RECIPE_RESCAN, rookie, {})
    checkEq(#recipeWorld.lookups, 4, "滿 250ms 後放行")

    -- 配方腳本缺失（scripts 打錯名／被別的 MOD 蓋掉）：帶配方名的診斷，最多一次
    nowMs = nowMs + 1000
    recipeWorld.defs[MDAD.RECIPE_AUTO] = nil
    local fresh = newPlayer({ num = 3, electricity = 9, username = "fresh", onlineId = 7104 })
    resetStats()
    local rlog = capturePrint(function()
        fire("OnClientCommand", MOD_ID, MDAD.CMD_RECIPE_RESCAN, fresh, {})
    end)
    checkTrue(logHas(rlog, "craftRecipe not found: " .. MDAD.RECIPE_AUTO),
        "配方腳本缺失留下帶配方名的 console 診斷")
    checkTrue(logHas(rlog, MDAD.BUILD), "診斷帶 build 印記（實機才判得出跑的是哪版）")
    checkTrue(fresh:getKnownRecipes():contains(MDAD.RECIPE_GPS),
        "一支配方缺失不影響另一支的補學")
    checkEq(#recipeWorld.syncs, 1, "缺一支仍替學到的那支同步一次")

    nowMs = nowMs + 1000
    local other = newPlayer({ num = 4, electricity = 9, username = "other", onlineId = 7105 })
    resetStats()
    rlog = capturePrint(function()
        fire("OnClientCommand", MOD_ID, MDAD.CMD_RECIPE_RESCAN, other, {})
    end)
    checkEq(#rlog, 0, "同一支缺失的配方不重複洗 log（每個配方名最多印一次）")
    recipeWorld.defs[MDAD.RECIPE_AUTO] =
        recipeWorld.newRecipe(MDAD.RECIPE_AUTO, Perks.Electricity, 8)
end

-- (3) 專屬雜誌：戰利品注入的目標／權重／防重，與 AllowCraft* 生成政策
do
    clientFlag, serverFlag = false, true
    local names = { "ArmyStorageElectronics", "ElectronicStoreMisc", "BookstoreComputer",
        "LibraryComputer", "MagazineRackMixed", "CrateRandomJunk" }
    local expect = { ArmyStorageElectronics = 1, ElectronicStoreMisc = 2,
        BookstoreComputer = 2, LibraryComputer = 1, MagazineRackMixed = 0.5 }
    ProceduralDistributions = { list = {} }
    for i = 1, #names do
        ProceduralDistributions.list[names[i]] = { items = { "Base.Plank", 3 } }
    end
    setSandbox({ AllowCraftGPS = true, AllowCraftAutopilot = true,
        SpawnGPS = true, SpawnAutopilot = true })

    fire("OnPostDistributionMerge")
    local sizes = {}
    for i = 1, #names do sizes[names[i]] = #ProceduralDistributions.list[names[i]].items end
    -- 同一行程回主選單再讀檔＝事件再觸發；ProceduralDistributions 不重置
    fire("OnPostDistributionMerge")
    fire("OnPostDistributionMerge")
    for i = 1, #names do
        local items = ProceduralDistributions.list[names[i]].items
        local n, w = countIn(items, MDAD.TYPE_MANUAL)
        checkEq(#items, sizes[names[i]], names[i] .. "：連跑三次長度不變（雜誌沒有重複注入）")
        checkEq(#items % 2, 0, names[i] .. "：items 一定成對（type, weight）")
        checkEq(n, expect[names[i]] and 1 or 0, names[i] .. "：雜誌出現次數")
        if expect[names[i]] then
            checkEq(w, expect[names[i]], names[i] .. "：雜誌權重沒有被疊加")
        end
        checkEq(items[1], "Base.Plank", names[i] .. "：原版既有條目沒被動到")
        checkEq(items[2], 3, names[i] .. "：原版既有權重沒被改")
    end
    checkEq(#ProceduralDistributions.list.CrateRandomJunk.items, 2,
        "不在雜誌目標清單的表完全沒被碰")

    -- 生成政策：手冊教的是那兩個配方，只要還有一個做得出來就有用。
    -- 與 SpawnGPS／SpawnAutopilot 分開判斷——那兩個管的是裝置本體的生成。
    local loot = newLootContainer({ MDAD.TYPE_MANUAL, GPS_T, "Base.Plank" })
    fire("OnFillContainer", "bookstore", "shelves", loot)
    checkEq(loot:count(MDAD.TYPE_MANUAL), 1, "兩個製作開關都開：保留手冊")

    setSandbox({ AllowCraftGPS = true, AllowCraftAutopilot = false,
        SpawnGPS = true, SpawnAutopilot = true })
    loot = newLootContainer({ MDAD.TYPE_MANUAL, "Base.Plank" })
    fire("OnFillContainer", "bookstore", "shelves", loot)
    checkEq(loot:count(MDAD.TYPE_MANUAL), 1, "只開 GPS 製作：手冊仍有用，保留")

    setSandbox({ AllowCraftGPS = false, AllowCraftAutopilot = true,
        SpawnGPS = true, SpawnAutopilot = true })
    loot = newLootContainer({ MDAD.TYPE_MANUAL, "Base.Plank" })
    fire("OnFillContainer", "bookstore", "shelves", loot)
    checkEq(loot:count(MDAD.TYPE_MANUAL), 1, "只開自駕製作：手冊仍有用，保留")

    setSandbox({ AllowCraftGPS = false, AllowCraftAutopilot = false,
        SpawnGPS = true, SpawnAutopilot = true })
    loot = newLootContainer({ MDAD.TYPE_MANUAL, GPS_T, AUTO_T, "Base.Plank" })
    fire("OnFillContainer", "bookstore", "shelves", loot)
    checkEq(loot:count(MDAD.TYPE_MANUAL), 0, "兩個製作開關都關才移除手冊")
    checkEq(loot:count(GPS_T), 1, "關閉製作不影響 SpawnGPS 開著的 GPS 本體")
    checkEq(loot:count(AUTO_T), 1, "關閉製作不影響 SpawnAutopilot 開著的自駕模組本體")
    checkEq(loot:count("Base.Plank"), 1, "手冊過濾不碰原版物品")

    -- 沙盒未載入（主選單／載入中）：預設是「留著」，不得誤刪
    setSandbox(nil)
    loot = newLootContainer({ MDAD.TYPE_MANUAL })
    fire("OnFillContainer", "bookstore", "shelves", loot)
    checkEq(loot:count(MDAD.TYPE_MANUAL), 1, "沙盒未載入時不移除手冊（fail-open）")

    clientFlag = true
    setSandbox({ AllowCraftGPS = false, AllowCraftAutopilot = false })
    loot = newLootContainer({ MDAD.TYPE_MANUAL })
    fire("OnFillContainer", "bookstore", "shelves", loot)
    checkEq(loot:count(MDAD.TYPE_MANUAL), 1, "MP client 不改 server 權威的生成內容")
    clientFlag = false
    setSandbox({ AllowCraftGPS = true, AllowCraftAutopilot = true,
        SpawnGPS = true, SpawnAutopilot = true })
end

-- =====================================================================
-- 情境二十八d：opt-in telemetry 接線（production Diagnostics／VehicleProfile）
-- =====================================================================
scenario("opt-in telemetry：lifecycle／pn／單檔路徑／關閉零呼叫／失敗不中斷／vprofile 不進控制")

local function scenarioTelemetry()
    checkEq(type(MDADVehicleProfile), "table", "production MDAD_VehicleProfile.lua 真的載入了")
    checkEq(type(MDADDiagnostics), "table", "production MDAD_Diagnostics.lua 真的載入了")
    checkEq(type(MDADVehicleProfile.build), "function", "VehicleProfile.build 存在")
    checkEq(type(MDADDiagnostics.start), "function", "Diagnostics.start 存在")
    checkEq(type(MDADDiagnostics.sample), "function", "Diagnostics.sample 存在")
    checkEq(type(MDADDiagnostics.event), "function", "Diagnostics.event 存在")
    checkEq(type(MDADDiagnostics.stop), "function", "Diagnostics.stop 存在")
    checkEq(type(MDADDiagnostics.fail), "function", "Diagnostics.fail 存在")

    if type(MDAD.HUD) ~= "table" then MDAD.HUD = {} end
    local hudTelem = MDAD.HUD.telemetryEnabled
    MDAD.HUD.telemetryEnabled = function() return drive.telemOn == true end

    local oldDocumentFolder = getMyDocumentFolder
    local oldFileSeparator = getFileSeparator
    local oldClipboard = Clipboard
    local copiedPath = nil
    getMyDocumentFolder = function() return "C:/Zomboid" end
    getFileSeparator = function() return "/" end
    Clipboard = {
        setClipboard = function(text) copiedPath = text end,
    }

    drive.telemOn = false
    drive.diag = {
        build = 0, start = 0, sample = 0, critical = 0, event = 0, stop = 0, fail = 0,
        startPn = nil, samplePn = nil, stopPn = nil, stopReason = nil,
        failPn = nil, failMessage = nil, names = {}, fields = {}, phases = {},
        last = {}, -- 最後一幀的碰撞證據欄位（Driver 端接線用；編碼由 test_diagnostics 驗）
    }

    local origStart = MDADDiagnostics.start
    local origSample = MDADDiagnostics.sample
    local origEvent = MDADDiagnostics.event
    local origStop = MDADDiagnostics.stop
    local origFail = MDADDiagnostics.fail
    local origShould = MDADDiagnostics.shouldSample
    local origBuild = MDADVehicleProfile.build
    local forceShould = nil
    MDADVehicleProfile.build = function(vehicle)
        drive.diag.build = drive.diag.build + 1
        return origBuild(vehicle)
    end

    MDADDiagnostics.start = function(pn, vehicle, profile)
        drive.diag.start = drive.diag.start + 1
        drive.diag.startPn = pn
        drive.diag.startProfile = profile
        return true -- Driver lifecycle spy; production file IO is covered by test_diagnostics.lua
    end
    MDADDiagnostics.sample = function(pn, nowMsArg, x, y, heading, speed, target, remaining, lat, err, steer, force, mode, gear, regulator, sensor, critical,
            planMode, routeS, blockS, dodgeMargin, dodgeNeed, roadBias,
            blockHitX, blockHitY, followerIdx,
            blocked, dodging, offroad, corner, coupled, phys)
        drive.diag.sample = drive.diag.sample + 1
        drive.diag.samplePn = pn
        if critical == true then drive.diag.critical = drive.diag.critical + 1 end
        local last = drive.diag.last
        last.planMode = planMode
        last.routeS = routeS
        last.blockS = blockS
        last.dodgeMargin = dodgeMargin
        last.dodgeNeed = dodgeNeed
        last.roadBias = roadBias
        last.blockHitX = blockHitX
        last.blockHitY = blockHitY
        last.followerIdx = followerIdx
        last.blocked = blocked
        last.dodging = dodging
        last.offroad = offroad
        last.corner = corner
        last.coupled = coupled
        last.phys = phys
        return true -- Driver lifecycle spy; production sampling is covered separately
    end
    MDADDiagnostics.event = function(pn, name, a, b, c, d)
        drive.diag.event = drive.diag.event + 1
        if type(a) == "table" then
            drive.diag.fields = drive.diag.fields or {}
            drive.diag.fields[name] = a
            drive.diag.phases[name .. ":" .. tostring(a.phase)] = a
        end
        drive.diag.names[name] = true
        if origEvent then return origEvent(pn, name, a, b, c, d) end
    end
    MDADDiagnostics.stop = function(pn, reason)
        drive.diag.stop = drive.diag.stop + 1
        drive.diag.stopPn = pn
        drive.diag.stopReason = reason
        if origStop then return origStop(pn, reason) end
    end
    MDADDiagnostics.fail = function(pn, detail)
        drive.diag.fail = drive.diag.fail + 1
        drive.diag.failPn = pn
        drive.diag.failMessage = detail
        MDADDiagnostics.stop(pn, "error")
        return true
    end
    MDADDiagnostics.shouldSample = function()
        if forceShould ~= nil then return forceShould end
        return true
    end

    drive.telemOn = false
    checkTrue(armDrive(), "telemetry off 仍可啟動")
    driveReset(dveh)
    -- isDoingOffroad 另有一條非診斷路徑：每個完成的感知輪讀一次當路面輔證（Driver 的 surface state）。
    -- 0929o 起 30 FPS 的掃描額度放大，這個短世界（只載入到 x≈70）8 幀內就可能完成一輪，所以期望值＝完成輪數。
    local offSt = MDAD.Drive.debugSession(0)
    local offRounds0 = offSt and offSt.sensor and offSt.sensor.rounds or 0
    for _ = 1, 8 do driveTick(dp, dveh) end
    local offRounds = (offSt and offSt.sensor and offSt.sensor.rounds or 0) - offRounds0
    checkEq(dveh._imp.max, 1, "off：每幀最多一次 addImpulse")
    MDAD.Drive.stop(0, nil)
    checkEq(drive.diag.start, 0, "off：零 start")
    checkEq(drive.diag.build, 1, "off：session-start 仍恰 build 一次共用 profile")
    checkEq(drive.diag.sample, 0, "off：零 sample")
    checkEq(drive.diag.event, 0, "off：零 event")
    checkEq(drive.diag.stop, 0, "off：零 stop")
    checkEq(drive.calls.isDoingOffroad, offRounds, "off：isDoingOffroad 只剩完成輪的路面輔證（完成 " .. offRounds .. " 輪）")
    checkEq(drive.calls.isBraking, 0, "off：零 isBraking")
    checkEq(drive.calls.getMinWheelSkid, 0, "off：零 getMinWheelSkid")
    checkEq(drive.calls.getEngineSpeed, 0, "off：零 getEngineSpeed")
    checkEq(drive.calls.getTransmissionNumber, 0, "off：零 getTransmissionNumber")
    checkEq(drive.calls.getRegulatorSpeed, 0, "off：零 getRegulatorSpeed")
    checkEq(drive.calls.getLinearVelocity, 0, "off：零 getLinearVelocity")

    drive.diag.start, drive.diag.sample, drive.diag.event, drive.diag.stop,
        drive.diag.build = 0, 0, 0, 0, 0
    drive.diag.names, drive.diag.fields, drive.diag.phases = {}, {}, {}
    drive.telemOn = true
    checkTrue(armDrive(), "telemetry on 啟動")
    checkEq(drive.diag.start, 1, "on：start 一次")
    checkEq(drive.diag.build, 1, "on：VehicleProfile.build 一次")
    checkEq(drive.diag.startPn, 0, "start 用精確 pn")
    checkTrue(drive.diag.sample > 0, "on：sample 有接到")
    checkEq(drive.diag.fields.target and drive.diag.fields.target.phase, "set",
        "initial target event phase=set")
    checkEq(drive.diag.fields.route and drive.diag.fields.route.why, "initial",
        "initial route event why=initial")
    checkEq(drive.diag.phases["route:cutover"].len, nil,
        "initial cutover 無 route.len 時省略，不寫假 0")
    checkNear(drive.diag.phases["route:ready"].len, 156, 1e-9,
        "profile build ready event 寫入精確非零 length")
    checkEq(drive.diag.samplePn, 0, "sample 用精確 pn")
    checkTrue(drive.diag.names.start == true, "event start 有接到")
    driveReset(dveh)
    for _ = 1, 5 do
        dveh._x = dveh._x + 0.1852
        driveTick(dp, dveh)
    end
    checkEq(dveh._imp.max, 1, "on：每幀最多一次 addImpulse")
    checkEq(drive.bad.impulse, 0, "on：無單幀兩次 impulse")

    -- 碰撞證據欄位真的從 Driver 接到 Diagnostics（值來源＝既有 session 狀態）
    local dlast = drive.diag.last
    checkEq(type(dlast.planMode), "string", "sample 帶 replan 離場分類 planMode")
    checkEq(type(dlast.routeS), "number", "sample 帶沿線弧長 routeS")
    checkEq(type(dlast.blockS), "number", "sample 帶煞停錨 blockS")
    checkEq(type(dlast.dodgeNeed), "number", "sample 帶掃掠淨距 dodgeNeed")
    checkEq(type(dlast.roadBias), "number", "sample 帶路面對中校正")
    checkEq(type(dlast.followerIdx), "number", "sample 帶 follower 投影游標")
    checkEq(dlast.blocked, false, "跟線幀 blocked=false")
    checkEq(dlast.dodging, false, "跟線幀 dodging=false")
    checkEq(dlast.corner, false, "跟線幀 corner latch=false")
    checkEq(dlast.coupled, false, "橫推跟線幀 coupled=false（不是耦力調頭）")
    checkEq(dveh._imp.max, 1, "擴充遙測欄位不改變 addImpulse 次數")
    checkEq(drive.pool.live, 0, "on：物理速度向量成對歸還")
    check(drive.calls.isDoingOffroad > 0, "on：讀 isDoingOffroad")
    check(drive.calls.getLinearVelocity > 0, "on：讀 getLinearVelocity")
    checkEq(type(dlast.phys), "table", "sample 帶 phys table")
    checkEq(type(dlast.phys.physicalOffroad), "boolean", "phys.physicalOffroad")
    checkEq(type(dlast.phys.isBraking), "boolean", "phys.isBraking")
    checkEq(type(dlast.phys.minWheelSkid), "number", "phys.minWheelSkid")
    checkEq(type(dlast.phys.vLong), "number", "phys.vLong")
    checkEq(type(dlast.phys.vLat), "number", "phys.vLat")
    checkEq(type(dlast.phys.engineSpeed), "number", "phys.engineSpeed")
    checkEq(type(dlast.phys.transmissionNumber), "number", "phys.transmissionNumber")
    checkEq(type(dlast.phys.regulatorSpeed), "number", "phys.regulatorSpeed")
    checkEq(type(dlast.phys.expectedLane), "number", "phys.expectedLane")
    checkEq(type(dlast.phys.latDev), "number", "phys.latDev")
    checkEq(type(dlast.phys.roadState), "string", "phys.roadState")
    checkEq(type(dlast.phys.capPerception), "number", "phys.capPerception")
    checkEq(dlast.phys.physicalOffroad, false, "跟線幀 Java offroad=false")

    driveReset(dveh)
    drive.diag.sample = 0
    local onSt = MDAD.Drive.debugSession(0)
    local onRounds0 = onSt and onSt.sensor and onSt.sensor.rounds or 0
    for _ = 1, 5 do
        dveh._x = dveh._x + 0.1852
        driveTick(dp, dveh)
    end
    check(drive.diag.sample > 0, "對齊窗有 sample")
    local onRounds = (onSt and onSt.sensor and onSt.sensor.rounds or 0) - onRounds0
    checkEq(drive.calls.isDoingOffroad, drive.diag.sample + onRounds,
        "isDoingOffroad 次數 = sample＋完成輪的路面輔證（" .. onRounds .. " 輪）")
    checkEq(drive.calls.getLinearVelocity, drive.diag.sample, "getLinearVelocity 次數 = sample")

    forceShould = false
    driveReset(dveh)
    drive.diag.sample = 0
    for _ = 1, 5 do driveTick(dp, dveh) end
    checkTrue(drive.calls.isDoingOffroad <= 1,
        "gate skip 不跑診斷 getter；至多一筆 sensor snapshot 輔證")
    checkEq(drive.calls.getLinearVelocity, 0, "gate skip 零 getLinearVelocity")
    check(drive.diag.sample > 0, "gate skip 仍呼叫 sample 探活")
    forceShould = nil
    drive.nav.route = newRoute(40, 0, 0, 4, 0)
    drive.nav.route.len = 156
    nowMs = nowMs + 250
    driveTick(dp, dveh)
    checkEq(drive.diag.fields.route and drive.diag.fields.route.why, "deviation",
        "same-target route cutover event why=deviation")
    checkTrue(drive.diag.names.route == true, "route cutover 有 event")
    checkNear(drive.diag.phases["route:cutover"].len, 156, 1e-9,
        "cutover 優先寫 finite route.len")

    drive.nav.tx = 300.1
    drive.nav.route = newRoute(40, 0, 0, 4, 0)
    nowMs = nowMs + 250
    driveTick(dp, dveh)
    checkEq(drive.diag.fields.target and drive.diag.fields.target.phase, "change",
        "任意非零 target 座標差都算 true target change")
    checkEq(drive.diag.fields.route and drive.diag.fields.route.why, "target",
        "小於 0.5m 的 target change route 仍分類 target")

    dveh._y = 8 -- RETURN_MAX_DEV=12 以內：仍走 RETURN（>12 交 pure pursuit）
    driveTick(dp, dveh)
    checkTrue(drive.diag.names["return"] == true, "RETURN enter 有 event")
    checkTrue(drive.diag.critical > 0, "offroad sample 切到 10Hz critical flag")
    checkEq(drive.diag.last.offroad, true, "offroad 旗標進到 sample 欄位")
    dveh._y = 0

    MDAD.Drive.stop(0, nil)
    checkEq(drive.diag.stop, 1, "stop 在 session 移除前呼叫一次")
    checkEq(drive.diag.stopPn, 0, "stop 用精確 pn")
    checkTrue(drive.diag.stopReason ~= nil, "stop 帶 reason")

    local copied = false
    pcall(function()
        copied = MDADDiagnostics.copyLatestPath(0)
        if not copied and type(MDADDiagnostics.copyFolderPath) == "function" then
            copied = MDADDiagnostics.copyFolderPath(0)
        end
    end)
    checkTrue(copied, "session 檔路徑複製成功")
    checkEq(type(copiedPath), "string", "剪貼簿收到一個 session 檔路徑")
    checkTrue(string.find(copiedPath, "Telemetry", 1, true) ~= nil,
        "路徑落在 Lua/MinidoracatAutoDrive/Telemetry")
    checkTrue(string.find(copiedPath, "Steam", 1, true) == nil, "路徑不含 SteamID")

    local stopsBeforeMenu = drive.diag.stop
    checkTrue(armDrive(), "menu cleanup 情境啟動")
    dveh._regulator = true
    nowMs = nowMs + 2200
    drive.clockAtMenu = select(7, MDAD.Drive.hudState(0))
    fire("OnMainMenuEnter")
    checkFalse(MDAD.Drive.isActive(0), "回主選單清除 drive session")
    checkEq(select(7, MDAD.Drive.hudState(0)), drive.clockAtMenu,
        "返回主選單的清理也保留末趟時間")
    checkEq(drive.diag.stop, stopsBeforeMenu + 1, "回主選單關閉 telemetry writer")
    checkEq(drive.diag.stopReason, "menu", "回主選單記錄 menu end reason")
    checkEq(dveh._regulator, false, "回主選單關閉原車 regulator")

    local sampleSpy = MDADDiagnostics.sample
    MDADDiagnostics.sample = function() error("sample-fail") end
    drive.diag.fail, drive.diag.failMessage, drive.diag.stopReason = 0, nil, nil
    driveReset(dveh)
    checkTrue(MDAD.Drive.start(dp), "Diagnostics.sample 丟錯仍啟動")
    driveTick(dp, dveh)
    driveTick(dp, dveh)
    checkTrue(MDAD.Drive.isActive(0), "sample 失敗只停診斷、不拆 drive session")
    checkEq(dveh._imp.max, 1, "sample 失敗不改變 addImpulse")
    checkEq(drive.pool.live, 0, "sample 失敗仍歸還外層向量")
    checkEq(drive.diag.fail, 1, "sample 失敗走單一 diagnostics fail boundary")
    checkTrue(string.find(drive.diag.failMessage or "", "sample-fail", 1, true) ~= nil,
        "sample failure 保留原始錯誤")
    checkEq(drive.diag.stopReason, "error", "sample 失敗以 error 收掉 telemetry session")
    MDAD.Drive.stop(0, nil)
    MDADDiagnostics.sample = sampleSpy

    local gateSpy = MDADDiagnostics.shouldSample
    MDADDiagnostics.shouldSample = function() error("gate-fail") end
    drive.diag.fail, drive.diag.failMessage, drive.diag.stopReason = 0, nil, nil
    checkTrue(armDrive(), "Diagnostics.shouldSample 丟錯仍維持 drive session")
    MDADDiagnostics.shouldSample = gateSpy
    driveReset(dveh)
    driveTick(dp, dveh)
    checkTrue(MDAD.Drive.isActive(0), "gate 失敗後 Drive 繼續")
    checkEq(dveh._imp.max, 1, "gate 失敗後下一幀控制照常")
    checkEq(drive.calls.isDoingOffroad, 0, "gate 失敗在 physics getter 前收口")
    checkEq(drive.pool.live, 0, "gate 失敗仍歸還外層向量")
    checkEq(drive.diag.fail, 1, "gate 失敗走單一 fail boundary")
    checkTrue(string.find(drive.diag.failMessage or "", "gate-fail", 1, true) ~= nil,
        "gate failure 保留原始錯誤")
    checkEq(drive.diag.stopReason, "error", "gate 失敗記 error")
    MDAD.Drive.stop(0, nil)


    -- Recovery-only sampling owns its own vector. Allocation/getter failure must stop
    -- telemetry through diagFail while SETTLE control continues and the pool stays balanced.
    drive.fillWorld(-10, 70, -7, 7)
    forceShould = true
    checkTrue(armDrive(), "recovery telemetry boundary 情境啟動")
    setHeading(dveh, 0)
    -- 0906c 起候選線／dl 以車的實際橫向為準：車要停在常駐 lane（RightLaneBias 預設 1）上，
    -- 否則 2.5 的側移會記 steep 差額、倒車要多退 ~6m，本案「倒 3.1m 即 settle」的前提就沒了
    dveh._y = 1
    driveTick(dp, dveh)
    dveh._trans = 1
    drive.putSolid(2, 0, "harness_recovery_diag")
    drive.scanRound(true)
    dveh._speed = 0
    nowMs = nowMs + 2501
    driveTick(dp, dveh)
    dveh._x, dveh._speed = -3.1, -13
    local recoveryAlloc = BaseVehicle.allocVector3f
    BaseVehicle.allocVector3f = function() error("recovery-alloc-fail") end
    drive.diag.fail, drive.diag.failMessage = 0, nil
    nowMs = nowMs + 16
    driveReset(dveh)
    driveTick(dp, dveh)
    BaseVehicle.allocVector3f = recoveryAlloc
    forceShould = nil
    checkTrue(MDAD.Drive.isActive(0), "recovery telemetry alloc 失敗不拆控制 session")
    checkTrue(drive.calls.forceBrake >= 1, "telemetry 失敗後 settle brake 仍執行")
    checkEq(drive.diag.fail, 1, "recovery telemetry 失敗走 diagFail")
    checkTrue(string.find(drive.diag.failMessage or "", "recovery-alloc-fail", 1, true) ~= nil,
        "recovery telemetry 保留原始錯誤")
    checkEq(drive.pool.live, 0, "recovery telemetry alloc failure 無池洩漏")
    checkTrue(drive.diag.phases["unstick:settle"] ~= nil,
        "倒足 3m 先記 settle transition")
    checkEq(drive.diag.phases["unstick:success"], nil,
        "尚未停到 |speed|<1 前不得宣告 success")
    dveh._trans = 2
    MDAD.Drive.stop(0, nil)

    drive.diag.phases = {}
    forceShould = true
    drive.fillWorld(-10, 70, -7, 7)
    checkTrue(armDrive(), "settle success event 情境啟動")
    setHeading(dveh, 0)
    dveh._y = 1 -- 同上：車停在常駐 lane 上
    driveTick(dp, dveh)
    dveh._trans = 1
    drive.putSolid(2, 0, "harness_settle_event")
    drive.scanRound(true)
    dveh._speed = 0
    nowMs = nowMs + 2501
    driveTick(dp, dveh)
    dveh._x, dveh._speed = -3.1, -13
    nowMs = nowMs + 16
    driveTick(dp, dveh)
    checkEq(drive.diag.phases["unstick:success"], nil,
        "settle entry 仍沒有 success event")
    dveh._speed = -0.5
    nowMs = nowMs + 100
    driveTick(dp, dveh)
    forceShould = nil
    checkNear(drive.diag.phases["unstick:success"].speed, -0.5, 1e-9,
        "真正停妥才記 success 與 final speed")
    dveh._trans = 2
    MDAD.Drive.stop(0, nil)

    local eventSpy = MDADDiagnostics.event
    MDADDiagnostics.event = function() error("event-fail") end
    drive.diag.fail, drive.diag.failMessage, drive.diag.stopReason = 0, nil, nil
    checkTrue(armDrive(), "Diagnostics.event 丟錯仍維持 drive session")
    MDADDiagnostics.event = eventSpy
    checkTrue(MDAD.Drive.isActive(0), "event 失敗只停診斷、不拆 Drive")
    checkEq(drive.diag.fail, 1, "event 失敗走單一 fail boundary")
    checkTrue(string.find(drive.diag.failMessage or "", "event-fail", 1, true) ~= nil,
        "event failure 保留原始錯誤")
    checkEq(drive.diag.stopReason, "error", "event 失敗記 error")
    MDAD.Drive.stop(0, nil)

    checkTrue(armDrive(), "getter lookup failure 情境啟動")
    local lookupGetter = dveh.isDoingOffroad
    local lookupMeta = getmetatable(dveh)
    dveh.isDoingOffroad = nil
    setmetatable(dveh, {
        __index = function(obj, key)
            if key == "isDoingOffroad" then error("lookup-fail") end
            local inherited = lookupMeta and lookupMeta.__index
            if type(inherited) == "function" then return inherited(obj, key) end
            if type(inherited) == "table" then return inherited[key] end
            return nil
        end,
    })
    drive.diag.fail, drive.diag.failMessage, drive.diag.stopReason = 0, nil, nil
    driveReset(dveh)
    driveTick(dp, dveh)
    dveh.isDoingOffroad = lookupGetter
    setmetatable(dveh, lookupMeta)
    checkTrue(MDAD.Drive.isActive(0), "getter lookup 丟錯不拆 Drive")
    checkEq(drive.pool.live, 0, "getter lookup 丟錯仍歸還外層向量")
    checkEq(drive.diag.fail, 1, "getter lookup 丟錯走 fail boundary")
    checkTrue(string.find(drive.diag.failMessage or "", "lookup-fail", 1, true) ~= nil,
        "getter lookup failure 保留原始錯誤")
    checkEq(drive.diag.stopReason, "error", "getter lookup failure 記 error")
    MDAD.Drive.stop(0, nil)

    checkTrue(armDrive(), "velocity allocation failure 情境啟動")
    local allocSpy = BaseVehicle.allocVector3f
    local skidSpy = dveh.getMinWheelSkid
    local physicsAlloc = false
    dveh.getMinWheelSkid = function(self)
        physicsAlloc = true
        return skidSpy(self)
    end
    BaseVehicle.allocVector3f = function()
        if physicsAlloc then
            physicsAlloc = false
            error("alloc-fail")
        end
        return allocSpy()
    end
    drive.diag.fail, drive.diag.failMessage, drive.diag.stopReason = 0, nil, nil
    driveReset(dveh)
    driveTick(dp, dveh)
    BaseVehicle.allocVector3f = allocSpy
    dveh.getMinWheelSkid = skidSpy
    checkTrue(MDAD.Drive.isActive(0), "velocity alloc 丟錯不拆 Drive")
    checkEq(drive.pool.live, 0, "velocity alloc 丟錯仍歸還外層向量")
    checkEq(drive.diag.fail, 1, "velocity alloc 丟錯走 fail boundary")
    checkTrue(string.find(drive.diag.failMessage or "", "alloc-fail", 1, true) ~= nil,
        "velocity alloc failure 保留原始錯誤")
    checkEq(drive.diag.stopReason, "error", "velocity alloc failure 記 error")
    MDAD.Drive.stop(0, nil)

    checkTrue(armDrive(), "velocity read failure 情境啟動")
    local velocitySpy = dveh.getLinearVelocity
    dveh.getLinearVelocity = function() error("velocity-read-fail") end
    drive.diag.fail, drive.diag.failMessage, drive.diag.stopReason = 0, nil, nil
    driveReset(dveh)
    driveTick(dp, dveh)
    dveh.getLinearVelocity = velocitySpy
    checkTrue(MDAD.Drive.isActive(0), "velocity read 丟錯不拆 Drive")
    checkEq(drive.pool.live, 0, "velocity read 丟錯先歸還 inner 與 outer 向量")
    checkEq(drive.bad.pair, 0, "velocity read 丟錯該幀 alloc/release 成對")
    checkEq(drive.diag.fail, 1, "velocity read 丟錯走 fail boundary")
    checkTrue(string.find(drive.diag.failMessage or "", "velocity-read-fail", 1, true) ~= nil,
        "velocity read failure 保留原始錯誤")
    checkEq(drive.diag.stopReason, "error", "velocity read failure 記 error")
    MDAD.Drive.stop(0, nil)

    -- 同幀 dodge 候選 24 與 8 隻殭屍 10 競合：最終 winner 必須是 zombie；
    -- dodge 候選仍獨立保留，不能用 s.dodging 推測 active reason。
    setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false,
        AutoDriveMaxSpeed = 40, RightLaneBias = 0 })
    MDAD.Drive.setSlowPref(0, "zombie", true)
    drive.fillWorld(-2, 70, -7, 7)
    drive.putSolid(20, 0, "telemetry_winner")
    -- 殭屍群放在 lead 內（0907b envelope：遠處不再是整帶平帽），8 隻 → 15 才綁得住
    drive.putMoving(10, 0, { _class = "IsoZombie" })
    drive.putMoving(10, -1, { _class = "IsoZombie" })
    drive.putMoving(11, 0, { _class = "IsoZombie" })
    drive.putMoving(11, 1, { _class = "IsoZombie" })
    drive.putMoving(12, -1, { _class = "IsoZombie" })
    drive.putMoving(12, 0, { _class = "IsoZombie" })
    drive.putMoving(12, 1, { _class = "IsoZombie" })
    drive.putMoving(13, 0, { _class = "IsoZombie" })
    drive.diag.last = {}
    -- 本案量的是 dodge 與殭屍分級檔的裁決歸因：殭屍軟縫關掉（開著時軟縫會先把 lane 帶到
    -- 殭屍群左側 −2.05，中線的箱物就不再擋線＝沒有 dodge 可歸因；那是另一個行為，⑤z 測）
    MDAD.HUD.zombieDodge = function() return false end
    checkTrue(armDrive(), "dodge+zombie winner 情境啟動")
    setHeading(dveh, 0.05)
    dveh._speed = 20
    driveReset(dveh)
    drive.scanRound()
    driveReset(dveh)
    driveTick(dp, dveh)
    local winnerPhys = drive.diag.last.phys or {}
    checkTrue(drive.calls.maxRegSpeed > 0 and drive.calls.maxRegSpeed <= 15,
        "dodge+zombie target 由殭屍分級檔裁決（≤15；2026-09-01 全油門裁定後"
        .. "爬行檔不再參與，實得 " .. tostring(drive.calls.maxRegSpeed) .. "）")
    -- 2026-09-01 binding-only capReason（外部審查抓的定罪毒化）：gate 的
    -- state bit 沒有真的壓低 target（zombie/dodge 已更嚴）就不得覆寫 reason
    -- ——歸因保留真正裁決者，telemetry 統計才可信。
    checkTrue(winnerPhys.activeCapReason == "dodge"
            or winnerPhys.activeCapReason == "sensor"
            or winnerPhys.activeCapReason == "zombie",
        "activeCapReason 歸真正 binding 的裁決者（實得 "
        .. tostring(winnerPhys.activeCapReason) .. "）")
    checkTrue(type(winnerPhys.capSensor) == "number"
            and winnerPhys.capSensor > 0 and winnerPhys.capSensor <= 15,
        "capSensor 聚合不超過殭屍分級檔 15（2026-09-02 dodge FLOOR 15 後由殭屍檔裁決）")
    checkTrue(type(winnerPhys.capDodge) == "number"
            and winnerPhys.capDodge > 0,
        "capDodge independently preserves the dynamic dodge candidate")
    MDAD.Drive.stop(0, nil)
    MDAD.HUD.zombieDodge = nil

    MDADDiagnostics.start = function() error("diag-fail") end
    drive.telemOn = true
    driveReset(dveh)
    checkTrue(MDAD.Drive.start(dp), "Diagnostics.start 丟錯仍啟動")
    checkTrue(MDAD.Drive.isActive(0), "diag 失敗不拆 session")
    driveTick(dp, dveh)
    driveTick(dp, dveh)
    checkEq(dveh._imp.max, 1, "diag 失敗不改變 addImpulse")
    MDAD.Drive.stop(0, nil)
    MDADDiagnostics.start = function(pn, vehicle, profile)
        drive.diag.start = drive.diag.start + 1
        drive.diag.startPn = pn
        return true
    end

    MDADVehicleProfile.build = function(_)
        return {
            valid = true, fallback = false, geometryValid = true, scriptName = "x",
            bodyW = 1.8, bodyL = 4.4, halfW = 0.9, halfL = 2.2,
            centerOfMassX = 0, centerOfMassY = 0.5, centerOfMassZ = 0,
            mass = 1, maxSpeed = 1, wheelbase = 1, track = 1,
            clamp0 = 0, clamp30 = 0, clampMax = 0,
            wheelFriction = 0, delta0Safe = 0, deltaVSafe = 0,
            rMin = 0, lookScale = 0, rearArm = 0, needHalf = 99, probeR = 0,
        }
    end
    drive.telemOn = true
    checkTrue(armDrive(), "wild non-geometry vprofile 仍啟動")
    driveReset(dveh)
    driveTick(dp, dveh)
    checkEq(dveh._imp.total, 1, "non-geometry profile scalars 不改變 addImpulse 次數")
    checkTrue(dveh._imp.torqueY ~= 0 or dveh._imp.x ~= 0,
        "wild rearArm=0 仍用 Driver REAR_ARM 施力")
    MDAD.Drive.stop(0, nil)

    MDADDiagnostics.start = origStart
    MDADDiagnostics.sample = origSample
    MDADDiagnostics.event = origEvent
    MDADDiagnostics.stop = origStop
    MDADDiagnostics.fail = origFail
    MDADDiagnostics.shouldSample = origShould
    MDADVehicleProfile.build = origBuild
    MDAD.HUD.telemetryEnabled = hudTelem
    drive.telemOn = false
    getMyDocumentFolder = oldDocumentFolder
    getFileSeparator = oldFileSeparator
    Clipboard = oldClipboard
end
scenarioTelemetry()

-- =====================================================================
-- Phase E：v4 strict consumer、hot getter、EWMA key、surface-aware RETURN
-- =====================================================================
scenario("Phase E：v4 strict metadata、adaptive getter cache、traction reset、RETURN exact line")
local function scenarioPhaseE()
    local oldVeh = dveh
    local oldGear = MDAD.Drive.getGear(0)
    MDAD.Drive.setGear(0, 4) -- 此組驗積極策略；不依賴使用者預設檔位。
    local hotVeh = newVehicle({
        battery = newItem("Base.CarBattery", { uses = 0.8 }),
        engineRunning = true, mass = 1200, speed = 20, maxSpeed = 90,
        bodyW = 2.0, bodyL = 5.2, comX = 0.6, comZ = 0.4, profileFull = true,
        enginePower = 4000, brakingForce = 80,
        wheelFriction = 1.5, tireFriction = 1.5,
    })
    dveh = hotVeh
    hotVeh._driver, dp._vehicle = dp, hotVeh
    local function v4Route(surface, width)
        local route = newRoute(40, 0, 0, 4, 0)
        route.segSurface, route.segWidth = {}, {}
        for i = 1, 39 do
            route.segSurface[i], route.segWidth[i] = surface, width
        end
        route.len, route.cost = 156, 156
        route.avoidPenalty, route.approachSurface = 0, "unknown"
        return route
    end
    local function v4CurveRoute(degrees)
        local pts = {}
        for i = 0, 10 do
            pts[#pts + 1] = i * 4
            pts[#pts + 1] = 0
        end
        local endA = math.rad(degrees)
        local ex, ey = 40, 0
        for i = 1, 25 do
            pts[#pts + 1] = ex + math.cos(endA) * i * 4
            pts[#pts + 1] = ey + math.sin(endA) * i * 4
        end
        local route = { pts = pts, segSurface = {}, segWidth = {},
            avoidPenalty = 0, approachSurface = "unknown" }
        for i = 1, #pts / 2 - 1 do
            route.segSurface[i], route.segWidth[i] = "paved", 10
        end
        return route
    end
    local captured = nil
    local realOverlayUpdate = MDADOverlay.update
    MDADOverlay.update = function(pn, s, ...)
        if pn == 0 then captured = s end
        return realOverlayUpdate(pn, s, ...)
    end

    setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false,
        AutoDriveMaxSpeed = 40, RightLaneBias = 0 })
    installNavApi(4)
    drive.nav.tx, drive.nav.ty, drive.nav.state = 300, 0, "ok"
    drive.nav.route = v4Route("paved", 10)
    drive.fillWorld(-2, 170, -9, 9)
    drive.putRoad(-2, 170, -9, 9)
    driveReset(hotVeh)
    checkTrue(MDAD.Drive.start(dp), "aligned v4 route starts")
    local massStart = drive.calls.getMass
    local engineStart = drive.calls.getEnginePower
    local brakeStart = drive.calls.getBrakingForce
    local tireStart = drive.calls.getWheelFriction
    local partStart = drive.calls.getPartById
    for _ = 1, 10 do driveTick(dp, hotVeh) end
    checkEq(drive.calls.getMass, massStart, "N hot frames do not reread mass")
    checkEq(drive.calls.getEnginePower, engineStart, "N hot frames do not reread enginePower")
    checkEq(drive.calls.getBrakingForce, brakeStart, "N hot frames do not reread brakingForce")
    checkEq(drive.calls.getWheelFriction, tireStart, "N hot frames do not reread tire friction")
    checkEq(drive.calls.getPartById, partStart, "N hot frames do not enumerate tires")
    nowMs = nowMs + 999
    driveTick(dp, hotVeh)
    checkEq(drive.calls.getMass, massStart, "mass remains cached before 1 second")
    nowMs = nowMs + 1
    driveTick(dp, hotVeh)
    checkEq(drive.calls.getMass, massStart + 1, "1 second boundary performs one finite mass refresh")
    checkEq(drive.calls.getEnginePower, engineStart, "mass refresh does not reread enginePower")
    checkEq(drive.calls.getBrakingForce, brakeStart, "mass refresh does not reread brakingForce")
    checkEq(drive.calls.getWheelFriction, tireStart, "mass refresh does not reread tires")

    hotVeh._x, hotVeh._y, hotVeh._speed = 0, 0, 20
    setHeading(hotVeh, 0)
    drive.scanRound()
    checkEq(type(captured), "table", "completed sensor round exposes active session to overlay")
    do
        -- hardN covers the full planner search band, while SEG_FALLBACK already owns
        -- a conservative curve envelope. Neither may force 15km/h when the sampled
        -- driven lane itself passes raw-band and OBB proof.
        local fallbackSeg = captured.fstate.idx + 6
        checkTrue(fallbackSeg < captured.profile.n,
            "regression fallback segment fits the straight v4 fixture")
        captured.profile.segKind[fallbackSeg] = MDADDynamics.SEG_FALLBACK
        local oldCorpsePref = MDAD.Drive.getSlowPref(0, "corpse")
        local oldZombiePref = MDAD.Drive.getSlowPref(0, "zombie")

        local function armFullGateFrame()
            captured.alignSince = nowMs - 1000
            captured.progressState, captured.progressSince = "watch", nowMs
            captured.cmdV, captured.cmdA, captured.cmdInitialized = 40 / 3.6, 0, true
            driveReset(hotVeh)
        end
        local function assertSensorHardCap(expected, reason, label)
            armFullGateFrame()
            driveTick(dp, hotVeh)
            checkTrue(captured.fullGate, label .. " keeps the static fullGate open")
            checkEq(captured.gateReason, "clear", label .. " static proof remains clear")
            checkEq(captured.lastSensorCap, expected, label .. " publishes the sensor cap")
            checkEq(captured.lastCapReason, reason, label .. " keeps the active cap reason")
            checkTrue(captured.cmdV * 3.6 <= expected + 1e-9,
                label .. " hard-clamps cmdV on the first frame")
            checkTrue(drive.calls.maxRegSpeed > 0
                    and drive.calls.maxRegSpeed <= expected,
                label .. " hard-clamps regulator speed on the first frame")
        end
        local function assertFullSpeed(label)
            armFullGateFrame()
            driveTick(dp, hotVeh)
            checkTrue(captured.fullGate, label .. " opens fullGate")
            checkEq(captured.gateReason, "clear", label .. " reports clear")
            checkEq(captured.lastSensorCap, nil, label .. " has no sensor cap")
            checkEq(drive.calls.maxRegSpeed, 40,
                label .. " keeps the gear/profile envelope (capReason="
                .. tostring(captured.lastCapReason)
                .. " sensorCap=" .. tostring(captured.lastSensorCap)
                .. " vis=" .. tostring(captured.visibilityCap)
                .. " laneEnv=" .. tostring(captured.laneCurveEnvelope) .. ")")
        end

        -- 0909b 起屍體也走殭屍那條軟避讓縫（Sensor 把長軸兩端併進 zomS/zomL），
        -- 所以屍體本身會生出 zombie-lane 縱向配合帽。這一組量的是「政策關掉的屍體
        -- 不得產生任何 sensor 帽」的歸因，軟縫的帽會混進來——區域內先關掉，
        -- 軟縫本身另有 (zc)／(z5) 在鎖。
        MDAD.HUD.zombieDodge = function() return false end
        MDAD.Drive.setSlowPref(0, "corpse", false)
        drive.putTree(20, 6, "vegetation_trees_01_5")
        drive.putCorpse(25, 0)
        drive.scanRound()
        checkTrue(MDAD.Drive.debugSession(0).sensor.hardN > 0,
            "planner search band sees the roadside hard point")
        checkTrue(captured.sensor.corpseN > 0,
            "sensor sees the opted-out corpse inside its slowdown band")
        local lastProofSeg = captured.verifySeg[captured.verifyLineN]
        checkTrue(type(lastProofSeg) == "number" and fallbackSeg <= lastProofSeg,
            "fallback metadata lies inside the sampled proof horizon")
        checkEq(captured.verifyLineReason, "ok",
            "fallback metadata keeps the sampled lane proof valid")
        checkTrue(captured.verifySweep,
            "roadside hard point remains outside the driven-body OBB sweep")
        assertFullSpeed("clear driven lane despite search-band clutter")
        drive.clearCell(20, 6)
        drive.clearCell(25, 0)
        MDAD.Drive.setSlowPref(0, "corpse", oldCorpsePref)
        MDAD.HUD.zombieDodge = nil
        local farSeg = 11
        local farWidth = captured.route.segWidth[farSeg]
        captured.route.segWidth[farSeg] = 1
        drive.scanRound()
        checkEq(captured.verifyLineReason, "band",
            "far road-band failure remains named")
        assertFullSpeed("road-band failure beyond stopping horizon")
        captured.route.segWidth[farSeg] = farWidth

        local nearSeg = 5
        local nearWidth = captured.route.segWidth[nearSeg]
        captured.route.segWidth[nearSeg] = 1
        drive.scanRound()
        armFullGateFrame()
        driveTick(dp, hotVeh)
        checkFalse(captured.fullGate,
            "road-band failure inside stopping horizon keeps gate closed")
        -- 2026-09-02 提速裁定：band（證明品質）失敗改走 90% 比例檔
        -- （40×0.9=36），警戒地板只留近場未知（sensor/obb/sweep=18）。近場路寬
        -- 證明不足的物理安全由 RETURN 收緊與 sweep/obb/contact 層承擔。
        checkEq(captured.gateReason, "band", "near road-band failure names band")
        checkTrue(drive.calls.maxRegSpeed > 0 and drive.calls.maxRegSpeed <= 36 + 1e-9,
            "near road-band failure stays under the proportional band cap")
        captured.route.segWidth[nearSeg] = nearWidth
        drive.scanRound()

        drive.world[45 * 100000 + 0] = nil
        drive.scanRound()
        checkTrue(captured.sensor.unloaded and captured.visibilityCap > 40,
            "far unloaded cell is visible beyond the 40km/h stopping horizon")
        checkEq(captured.verifyLineReason, "unloaded",
            "far unloaded prefix boundary remains named")
        assertFullSpeed("unloaded boundary beyond stopping horizon")
        drive.putRoad(45, 45, 0, 0)
        drive.scanRound()

        -- (frontier) 0925m：未載入前緣剛好讓可視帽綁速（帽介於 18 與 40 之間）時，照可視帽開，
        --   不因證明截在前緣前 1m 而落到近場未知 18。違規證明：拿掉前緣容忍即紅。
        for fx = 12, 17 do
            drive.world[fx * 100000 + 0] = nil
            drive.scanRound()
            armFullGateFrame()
            driveTick(dp, hotVeh)
            local vc = captured.visibilityCap
            if vc > 22 and vc < 38 then
                checkTrue(drive.calls.maxRegSpeed > 20 and drive.calls.maxRegSpeed <= math.floor(vc + 0.5) + 1e-9,
                    "(frontier) 可視帽 " .. string.format("%.1f", vc) .. " 綁速時照帽開，不落到 18（reg "
                    .. tostring(drive.calls.maxRegSpeed) .. "、gate " .. tostring(captured.gateReason) .. "）")
                drive.frontierChecked = true
            end
            drive.putRoad(fx, fx, 0, 0)
            drive.scanRound()
            if drive.frontierChecked then break end
        end
        checkTrue(drive.frontierChecked == true, "(frontier) 找到可視帽綁速的前緣位置")
        drive.world[15 * 100000 + 0] = nil
        drive.scanRound()
        armFullGateFrame()
        driveTick(dp, hotVeh)
        -- 0925m：可視帽已按未載入前緣限速，證明蓋到前緣前一格即算驗證（舊制差 1m 永遠蓋不到
        -- → 近場未知 18）。速度仍由可視帽綁住，不因 gate 開而超過前緣煞停距離。
        checkTrue(drive.calls.maxRegSpeed <= math.floor(captured.visibilityCap + 0.5) + 1e-9,
            "unloaded cell inside stopping horizon: regulator stays under the frontier visibility cap")
        checkTrue(drive.calls.maxRegSpeed < 40,
            "near unloaded cell applies a real visibility cap")
        -- 巡航與緊急紅線共用真實可視前緣，但不能共用速度值：先收油，再在真停距不足時硬煞。
        -- 2026-09-27：兩帳反應時間固定 VIS_TAU（不再加快照年齡）；前緣是未載入區塊時巡航帳另假設
        -- 前緣再停 VIS_UNLOADED_HOLD_S 秒（MDADDynamics.visibilityHoldCapKmh），所以只能比一般帳更低。
        do
            local sen = captured.sensor
            -- 中央帶未知會把 endS 截到該格（Sensor：inBand 且 curS < endS 就截短），
            -- 所以 unloadedS == scanEndS 是合法的完成輪，不是「前緣在帶外」。
            checkTrue(sen.unloaded and sen.unloadedS <= sen.scanEndS,
                "near unloaded fixture: unloaded edge inside the scan band")
            local dist = sen.unloadedS - captured.lastSNow
            local b = captured.safeBrake
            if captured.horizonStamp == sen.stamp and captured.horizonMinBrake < b then
                b = captured.horizonMinBrake
            end
            local bg = math.min(b * 2.5, 12)
            local bc = math.max(b, math.min(b * 1.5, bg * 0.75)) -- 巡航帳（0924c）：舒適與緊急之間
            local halfL = captured.vehicleProfile.halfL
            checkTrue(captured.visibilityCap < MDADDynamics.visibilityCapKmh(dist, 0.5, bc, halfL) - 1,
                "unknown frontier: cruise account assumes the streaming front may stall (below the plain cruise domain)")
            checkTrue(captured.visibilityCap > 0,
                "unknown frontier: stall assumption still leaves a drivable cruise cap")
            checkNear(captured.visibilityHardKmh,
                MDADDynamics.visibilityCapKmh(dist, 0.5, bg, halfL), 1e-6,
                "emergency visibility bound preserves the existing brake prior")
        end
        drive.putRoad(15, 15, 0, 0)
        drive.scanRound()
        local realCorridorPlan = MDADCorridor.plan
        MDADCorridor.plan = function() return "clear" end
        drive.putSolid(40, 0, "far_sweep_prefix")
        drive.scanRound()
        checkEq(captured.verifyLineReason, "sweep",
            "far world-sweep failure remains named")
        assertFullSpeed("world-sweep failure beyond stopping horizon")
        drive.clearCell(40, 0)
        drive.scanRound()

        drive.putSolid(15, 0, "near_sweep_prefix")
        drive.scanRound()
        armFullGateFrame()
        driveTick(dp, hotVeh)
        checkFalse(captured.fullGate,
            "world-sweep failure inside stopping horizon keeps gate closed")
        -- 1005：近場世界掃掠命中不再平壓 18（只夾 regulator＝斷油滑行，正式服 41–53 km/h 滑不到就撞上路口物件），改成
        --   「車心開到命中的車身取樣點（proofHitS）時降到 18」的接近包絡（Drive.proofSweepCap），超過包絡由中線外力
        --   proof 帳補減速。舊期望「regulator ≤ 18」改成「regulator ≤ 包絡、包絡＝approachCap(命中點, 18)」。
        local penv = MDADDynamics.approachCapKmh(
            (captured.proofHitS or 0) - captured.lastSNow, 18, 0.5,
            captured.safeBrake * MDAD.Drive.debugTune().APPROACH_BRAKE_FRAC)
        checkTrue(MDADDynamics.finite(captured.proofHitS) and MDADDynamics.finite(captured.proofSweepCap)
                and math.abs(captured.proofSweepCap - penv) < 1e-6 and penv > 18,
            "near world-sweep failure: approach envelope to the sweep hit, not a flat 18（hit="
            .. tostring(captured.proofHitS) .. " rs=" .. tostring(captured.lastSNow) .. " cap="
            .. tostring(captured.proofSweepCap) .. " env=" .. tostring(penv) .. "）")
        checkTrue(drive.calls.maxRegSpeed > 0
                and drive.calls.maxRegSpeed <= math.floor(captured.proofSweepCap + 0.5) + 1e-9,
            "near world-sweep failure: regulator stays under the proof envelope")
        drive.clearCell(15, 0)
        MDADCorridor.plan = realCorridorPlan
        drive.scanRound()

        -- 首次看到的行進車（還沒有位移可算車速）擋在行駛線上：當成停著的前車，套「在跟車停距前
        -- 停下」的接近帽（2026-09-24 起取代舊的 20/8/0 分級）；速度帽第一幀就硬夾 cmdV／regulator。
        drive.putVehicle(15, 0, false)
        drive.scanRound()
        local vehAheadS = captured.sensor.vehAheadS
        checkTrue(type(vehAheadS) == "number",
            "moving vehicle publishes an ahead anchor")
        checkTrue(captured.sensor.trfN == 1 and captured.sensor.trfVs[1] == false,
            "first sighting publishes one traffic entry without a speed estimate")
        armFullGateFrame()
        driveTick(dp, hotVeh)
        do
            local mc = captured.lastSensorCap
            local gap = captured.trfLeadGap
            checkTrue(type(gap) == "number" and gap > MDAD.Drive.debugTune().FOLLOW_STOP_M and gap < 15,
                "unknown-speed leader: gap measured from the body box (" .. tostring(gap) .. ")")
            checkTrue(type(mc) == "number" and mc > 0 and mc < 20,
                "unknown-speed leader mid-gap: approach cap below the old 20 flat cap (" .. tostring(mc) .. ")")
            checkTrue(captured.cmdV * 3.6 <= mc + 1e-9, "moving cap hard-clamps cmdV on the first frame")
            checkTrue(drive.calls.maxRegSpeed > 0 and drive.calls.maxRegSpeed <= math.floor(mc + 0.5),
                "moving cap hard-clamps regulator speed on the first frame (integer km/h)")
        end
        drive.clearVehicle(15, 0)

        drive.putSpriteObject(8, 0, "fixtures_soft_regression", false, true, false)
        drive.scanRound()
        checkTrue(captured.sensor.softN > 0, "soft fixture enters the slowdown band")
        assertSensorHardCap(25, "soft", "soft obstacle")
        drive.clearCell(8, 0)

        MDAD.Drive.setSlowPref(0, "zombie", true)
        MDAD.HUD.zombieDodge = function() return false end -- 只驗數量減速檔；軟縫的縱向配合帽另在 (z5) 鎖
        drive.putMoving(10, 0, { _class = "IsoZombie" }) -- lead 內＝檔位速本身（0907b envelope）
        drive.scanRound()
        checkTrue(captured.sensor.zombieN > 0, "zombie fixture enters the slowdown band")
        assertSensorHardCap(35, "zombie", "single zombie")
        drive.clearCell(10, 0)
        -- 屍體同樣走軟縫（見 (zc)）：這一組量的是屍體**數量減速檔**的歸因，
        -- 軟縫的縱向配合帽會搶走 capReason，所以整組都維持關閉，收尾才還原。
        MDAD.Drive.setSlowPref(0, "zombie", oldZombiePref)

        MDAD.Drive.setSlowPref(0, "corpse", true)
        drive.putCorpse(8, 0)
        drive.scanRound()
        checkTrue(captured.sensor.corpseN > 0, "corpse fixture enters the slowdown band")
        assertSensorHardCap(30, "corpse", "corpse slowdown")
        drive.clearCell(8, 0)
        MDAD.Drive.setSlowPref(0, "corpse", oldCorpsePref)
        MDAD.HUD.zombieDodge = nil
    end
    MDAD.Drive.stop(0, nil)
    hotVeh._x, hotVeh._y, hotVeh._speed = 0, 0, 20
    setHeading(hotVeh, 0)
    driveReset(hotVeh)
    checkTrue(MDAD.Drive.start(dp), "Phase E mass session re-arms after gate regression")
    for _ = 1, 10 do driveTick(dp, hotVeh) end
    drive.scanRound()
    checkEq(type(captured), "table", "re-armed mass session exposes its completed snapshot")
    local cachedMass = captured.runtimeMass
    local cachedAccel = captured.profile.segAccel[1]
    hotVeh._mass = cachedMass + 0.5
    nowMs = nowMs + 1000
    driveTick(dp, hotVeh)
    checkEq(captured.runtimeMass, cachedMass,
        "sub-threshold modded mass jitter does not move the retained baseline")
    checkNear(captured.profile.segAccel[1], cachedAccel, 1e-12,
        "sub-threshold mass jitter does not dirty/rebuild dynamics")
    hotVeh._mass = cachedMass + 6
    nowMs = nowMs + 1000
    captured.horizonStamp = captured.sensor.stamp
    captured.horizonMinBrake = captured.safeBrake
    driveTick(dp, hotVeh)
    driveTick(dp, hotVeh)
    checkEq(captured.horizonStamp, -1,
        "non-material mass rebuild invalidates snapshot horizon stamp")
    checkEq(captured.horizonMinBrake, 0,
        "non-material mass rebuild clears stale horizon minima")
    checkEq(captured.runtimeMass, cachedMass + 6,
        "accumulated delta at 0.5 percent threshold refreshes runtime mass")
    checkTrue(captured.profile.segAccel[1] < cachedAccel,
        "threshold-crossing mass refresh rebuilds conservative segment dynamics")
    checkEq(captured.navVersion, 4, "Driver records nav v4")
    checkEq(captured.currentSurfaceId, MDADFollower.SURFACE_PAVED,
        "Driver records current declared surface")
    checkEq(captured.currentSegWidth, 10, "Driver records current segment width")
    checkEq(MDAD.Drive.controlState(0), "TRACK", "derived control state is TRACK")
    captured.blocked, captured.returnActive = true, true
    checkEq(MDAD.Drive.controlState(0), "RETURN", "RETURN outranks planned blocked")
    captured.currentBlocked = true
    checkEq(MDAD.Drive.controlState(0), "HOLD", "current contact HOLD outranks RETURN")
    captured.currentBlocked, captured.blocked, captured.returnActive = false, false, false
    captured.dodging = true
    checkEq(MDAD.Drive.controlState(0), "AVOID", "dodge derives AVOID")
    -- 階段 2 主體 5：recover 不再是 mode 值。恢復需求＝s.recoverWhy 旗標，
    -- 空檔脈衝＝progressState "gear-reset"；兩者都必須派生 RECOVER。
    captured.dodging, captured.recoverWhy = false, "progress"
    checkEq(MDAD.Drive.controlState(0), "RECOVER", "recoverWhy 旗標派生 RECOVER")
    captured.recoverWhy = nil
    local psWas = captured.progressState
    captured.progressState = "gear-reset"
    checkEq(MDAD.Drive.controlState(0), "RECOVER",
        "progressState gear-reset 派生 RECOVER")
    captured.progressState = psWas
    checkEq(MDAD.Drive.controlState(0), "TRACK",
        "旗標清掉＋脈衝結束就回 TRACK（mode 全程是 follow）")
    captured.mode = "follow"
    captured.returnActive, captured.returnHold = true, true
    checkEq(MDAD.Drive.controlState(0), "HOLD", "returnHold outranks derived RETURN")
    captured.returnActive, captured.returnHold = false, false
    -- 越野／繞行推力輔助（2026-09-01 使用者裁定「非道路要有推力幫忙回到路上、
    -- 繞行要有推力幫忙擠過去」）。舊制 assist 的姿態上限固定 20°，而繞行／回線
    -- ／草地打滑時誤差天然偏大——最需要推力的場景剛好被切斷＝卡住的來源。
    -- 新契約：dodging／returnActive／physicalOffroad 任一為真就把上限放寬到 2×，
    -- 並讓 ratio 乘上越野補償（offroadEfficiency 低者補越多，上限 ×2）。
    do
        local massWas, speedWas = captured.runtimeMass, hotVeh._speed
        local fbWas, effWas = captured.forceBrakeUntil,
            captured.vehicleProfile.offroadEfficiency
        local offWas = hotVeh._offroad
        -- 這一段只看前推／越野／殭屍推撞；加速輔助（1001i，目標比實速高就補）另有 (acc) 案，先關掉
        local accWas = MDAD.Drive.debugTune().ACCEL_ASSIST_MPS2
        MDAD.Drive.debugTune().ACCEL_ASSIST_MPS2 = 0
        captured.runtimeMass = 1600 -- 過 ASSIST_MASS_MIN（輕車本來推得動）
        captured.forceBrakeUntil = 0
        hotVeh._speed = 5
        setHeading(hotVeh, 0.55) -- 誤差 ≈31°：在舊 20° 上限之外、2× 之內
        nowMs = nowMs + 100
        driveReset(hotVeh)
        driveTick(dp, hotVeh)
        checkEq(captured.lastAssistForce, 0,
            "on-road 誤差 31°>20°：assist 照舊切斷（原契約不變）")
        -- physicalOffroad 是 session 端的既有輸入（updateReturnSnapshot 由
        -- isDoingOffroad 寫入）。0909b 感知輪變短後 updateTraction 的冷路徑會在
        -- 這串幀裡重讀車體 getter，只寫 session 欄位會被假車的 false 蓋回去——
        -- 所以連 hotVeh._offroad 一起設（＝真的「車在草地上」），區塊結束還原。
        captured.physicalOffroad, hotVeh._offroad = true, true
        nowMs = nowMs + 100
        driveReset(hotVeh)
        driveTick(dp, hotVeh)
        local roughBase = captured.lastAssistForce
        checkTrue(roughBase > 0,
            "越野時同一個 31° 誤差不再切斷 assist（實得 "
            .. tostring(roughBase) .. "）")
        -- 同樣繞行姿態，越野效率差的車拿到不少於效率 1 的推力（BASE 2 保底
        -- 已把 eff 0.5 的 1/eff=2 追平——單調不減；eff 0.25 仍嚴格更大）
        captured.vehicleProfile.offroadEfficiency = 0.5
        nowMs = nowMs + 100
        driveReset(hotVeh)
        driveTick(dp, hotVeh)
        local roughAssist = captured.lastAssistForce
        checkTrue(roughAssist >= roughBase,
            "越野效率 0.5 的車補償後 assist 不少於效率 1（實得 "
            .. tostring(roughAssist) .. " vs " .. tostring(roughBase) .. "）")
        captured.vehicleProfile.offroadEfficiency = 0.25
        nowMs = nowMs + 100
        driveReset(hotVeh)
        driveTick(dp, hotVeh)
        local roughWorst = captured.lastAssistForce
        checkTrue(roughWorst > roughAssist,
            "越野效率 0.25（1/eff=4 > BASE 2）嚴格大於 0.5 檔（實得 "
            .. tostring(roughWorst) .. " vs " .. tostring(roughAssist) .. "）")
        checkTrue(roughWorst <= roughBase * MDADDynamics.ASSIST_OFFROAD_MAX + 1e-6,
            "補償上限 ×MAX 不得被突破")
        -- 重車超線性（2026-09-02 使用者裁定「越重推力要更大」）：同 rough／同
        -- 效率下，2600kg（=2×ASSIST_MASS_MIN）的 assist ＝ 1600kg 的
        -- (2600/1600)×massScale(2600)/massScale(1600)＝1.625×(2/1.23)≈2.64 倍；
        -- 純等比只有 1.625 倍。夾限：massScale ≤ 2。
        captured.vehicleProfile.offroadEfficiency = 1
        captured.runtimeMass = 1600
        nowMs = nowMs + 100
        captured.assistBoost = 1 -- 0905l 遞增倍率不進質量契約
        driveReset(hotVeh)
        driveTick(dp, hotVeh)
        local light = captured.lastAssistForce
        captured.runtimeMass = 2600
        nowMs = nowMs + 100
        captured.assistBoost = 1 -- 0905l 遞增倍率不進質量契約
        driveReset(hotVeh)
        driveTick(dp, hotVeh)
        local heavy = captured.lastAssistForce
        checkTrue(light > 0 and heavy > light * 2.5 and heavy < light * 3.3,
            "重車 assist 超線性（2600 vs 1600 ≈2.6×，純等比只 1.6×；實得 "
            .. tostring(heavy / (light > 0 and light or 1)) .. "×）")
        captured.runtimeMass = 9000 -- massScale 夾 2：不得無限放大
        nowMs = nowMs + 100
        captured.assistBoost = 1 -- 0905l 遞增倍率不進質量契約
        driveReset(hotVeh)
        driveTick(dp, hotVeh)
        checkTrue(captured.lastAssistForce <= light * (9000 / 1600) * 2 / (1600 / 1300) + 1e-6,
            "massScale 夾 ×2：超重車不得再放大")
        -- 安全紅線：forceBrake 期間一律不 assist（不受越野／繞行豁免影響）
        captured.forceBrakeUntil = nowMs + 1000
        nowMs = nowMs + 100
        driveReset(hotVeh)
        driveTick(dp, hotVeh)
        checkEq(captured.lastAssistForce, 0,
            "forceBrake 期間即使在繞行越野也零 assist（安全紅線）")
        -- 殭屍推撞（2026-09-04 使用者「被一群殭屍阻擋可以增加推力脫困嗎」；s024
        -- 1118kg van 低於質量門檻、帶內 5-10 隻、speed 2 target 22 卡 17 秒零 assist）：
        -- 帶內有殭屍＋低速對高目標持續 800ms → 免質量門檻推；殭屍散了即歸零。
        captured.forceBrakeUntil = 0
        captured.physicalOffroad, hotVeh._offroad = false, false
        captured.runtimeMass = 1118
        hotVeh._speed = 2
        setHeading(hotVeh, 0.05)
        captured.sensor.zombieN = 0
        nowMs = nowMs + 100
        driveReset(hotVeh)
        driveTick(dp, hotVeh)
        checkEq(captured.lastAssistForce, 0, "1118kg 無殭屍：低於質量門檻零 assist（原契約）")
        -- 0905b：越野免質量門檻（s047 草地 3 km/h 零 assist）
        captured.physicalOffroad, hotVeh._offroad = true, true
        nowMs = nowMs + 100
        driveReset(hotVeh)
        driveTick(dp, hotVeh)
        checkTrue(captured.lastAssistForce > 0,
            "1118kg 越野：免質量門檻拿到推力（實得 " .. tostring(captured.lastAssistForce) .. "）")
        local baseOff = captured.lastAssistForce
        -- 0905k：草地上姿態歪 50° 仍推（st179,012 出彎滑上草地 cap=align、thrust 0、9 km/h 爬 5 秒）
        setHeading(hotVeh, 0.87)
        nowMs = nowMs + 100
        driveReset(hotVeh)
        driveTick(dp, hotVeh)
        checkTrue(captured.lastAssistForce > 0,
            "越野＋航向誤差 50°：仍拿到推力（實得 " .. tostring(captured.lastAssistForce) .. "）")
        setHeading(hotVeh, 0.05)
        -- 0905k：輪胎抓地低於基準 1.4 的車越野推力乘 REF/實際（上限 1.6）
        local keepWf = captured.vehicleProfile.wheelFriction
        captured.vehicleProfile.wheelFriction = 0.7
        nowMs = nowMs + 100
        driveReset(hotVeh)
        driveTick(dp, hotVeh)
        checkTrue(captured.lastAssistForce > baseOff * 1.5,
            "輪胎抓地 0.7（基準 1.4）：越野推力 ≥1.5×（實得 " .. tostring(captured.lastAssistForce) .. " vs " .. tostring(baseOff) .. "）")
        captured.vehicleProfile.wheelFriction = keepWf
        -- 0905l 越野推力遞增：3 km/h 對目標 20 在草地上，2 秒後推力 ≥2.5×首幀；達速後退回
        captured.assistBoost = 1
        nowMs = nowMs + 100
        driveReset(hotVeh)
        driveTick(dp, hotVeh)
        local boost0 = captured.lastAssistForce
        local keepX = hotVeh._x
        for _ = 1, 72 do -- dt 走 mult（1/48 s/幀）＝1.5s；車有在爬（不觸發進度監督）；快照會重採 offroad，每幀重設
            nowMs = nowMs + 20
            hotVeh._x = hotVeh._x + 0.02
            captured.physicalOffroad = true
            driveReset(hotVeh)
            driveTick(dp, hotVeh)
        end
        checkTrue(boost0 > 0 and captured.assistBoost >= 2.5,
            "越野 1.5 秒未達速：推力倍率遞增到 ≥2.5×（實得 " .. tostring(captured.assistBoost) .. "×）")
        hotVeh._speed = 12
        for _ = 1, 60 do
            nowMs = nowMs + 20
            hotVeh._x = hotVeh._x + 0.07
            captured.physicalOffroad = true
            driveReset(hotVeh)
            driveTick(dp, hotVeh)
        end
        checkTrue(captured.assistBoost <= 1 + 1e-6, "達速後倍率退回 1（實得 " .. tostring(captured.assistBoost) .. "）")
        hotVeh._speed = 2
        hotVeh._x = keepX
        captured.physicalOffroad, hotVeh._offroad = false, false
        captured.sensor.zombieN = 6
        nowMs = nowMs + 100
        driveReset(hotVeh)
        driveTick(dp, hotVeh)
        checkEq(captured.lastAssistForce, 0, "殭屍剛出現：延遲期內不推（一碰就推＝每次擦到都撞）")
        nowMs = nowMs + 900
        driveReset(hotVeh)
        driveTick(dp, hotVeh)
        local zpush = captured.lastAssistForce
        checkTrue(zpush > 0,
            "殭屍擋車 ≥800ms：輕車也拿到推力（實得 " .. tostring(zpush) .. "）")
        -- 遲滯：推起來後 6 km/h（>進入門檻 5）仍續推；9.5（>退出 9）才收
        hotVeh._speed = 6
        nowMs = nowMs + 100
        driveReset(hotVeh)
        driveTick(dp, hotVeh)
        checkTrue(captured.lastAssistForce > 0,
            "推起來後 6 km/h 仍續推（遲滯，不在 5 上下每跨一次重等 800ms）")
        hotVeh._speed = 9.5
        nowMs = nowMs + 100
        driveReset(hotVeh)
        driveTick(dp, hotVeh)
        checkEq(captured.lastAssistForce, 0, "推到 9.5 km/h：收推")
        hotVeh._speed = 2
        captured.sensor.zombieN = 0
        nowMs = nowMs + 100
        driveReset(hotVeh)
        driveTick(dp, hotVeh)
        checkEq(captured.lastAssistForce, 0, "殭屍散了：推力立即歸零、質量門檻恢復")
        captured.physicalOffroad, hotVeh._offroad = false, offWas
        captured.vehicleProfile.offroadEfficiency = effWas
        captured.runtimeMass, hotVeh._speed = massWas, speedWas
        captured.forceBrakeUntil = fbWas
        MDAD.Drive.debugTune().ACCEL_ASSIST_MPS2 = accWas
        setHeading(hotVeh, 0)
        driveReset(hotVeh)
    end
    local baseRoute = drive.nav.route
    -- （detour 機制已移除：v4 avoidPenalty 驗收情境一併刪除，2026-09-01）
    drive.nav.route = baseRoute
    captured.pendingRouteWhy, captured.blocked = nil, false
    captured.forceBrakeUntil = 0
    captured.waitAccumMs, captured.waitTickMs = 0, 0
    captured.nextRouteMs = nowMs + 250
    captured.nextDynamicsMs = nowMs + 10000
    captured.dynamicsDirty, captured.mode = false, "follow"
    captured.tractionKey = captured.currentSurfaceId
        + (captured.rain ~= false and 4 or 0)
        + (captured.physicalOffroad and 32 or 0)
    captured.kinPrevMs, captured.kinPrevV, captured.kinPrevH =
        nowMs - 100, hotVeh._speed / 3.6, 0
    captured.forceBrakePrev, captured.regulatorPrev = false, true
    captured.targetPrev = 40
    for _ = 1, 6 do
        nowMs = nowMs + 100
        hotVeh._x = hotVeh._x + hotVeh._speed / 36
        driveTick(dp, hotVeh)
    end
    checkTrue(captured.accelTime > 0, "stable TRACK regulator samples accumulate EWMA time")
    -- 重建偵測器：REBUILD_BUDGET 讓重建在同一幀完成，「mode==follow」已不是判準，
    -- 直接數 invalidateDynamics 呼叫（每次重建恰一次）。
    local rebuildCount = 0
    local realInvalidateDynamics = MDADFollower.invalidateDynamics
    MDADFollower.invalidateDynamics = function(p)
        rebuildCount = rebuildCount + 1
        return realInvalidateDynamics(p)
    end
    local accelTimeBeforeCoast = captured.accelTime
    captured.coastMean, captured.coastDev, captured.coastTime = 0, 0, 0
    captured.coastConfidence, captured.coastLower = 0, 0
    captured.kinPrevMs, captured.kinPrevV, captured.kinPrevH =
        nowMs - 100, hotVeh._speed / 3.6 + 0.01, 0
    captured.forceBrakeUntil, captured.ewmaSuppressUntil = 0, 0
    captured.forceBrakePrev, captured.regulatorPrev = false, true
    captured.targetPrev = hotVeh._speed
    captured.nextDynamicsMs = nowMs + 10000
    driveTick(dp, hotVeh)
    -- 2026-09-04 issue #1 定罪 D：定速巡航（目標 ±1 內）是 bang-bang 供油混合幀，
    -- 舊契約把它鎖成「記 coast」→ lower→0 → 0.67 秒必觸發 material 重建。
    -- 新契約：目標 ±1 曖昧帶什麼都不學；實速 ≥ 目標+1（regulator 必斷油）才記 coast。
    checkEq(captured.coastTime, 0,
        "regulator-on target within +-1 of actual speed is ambiguous throttle: no coast sample")
    checkNear(captured.accelTime, accelTimeBeforeCoast, 1e-12,
        "ambiguous throttle frame is not misclassified as acceleration either")
    captured.kinPrevMs, captured.kinPrevV, captured.kinPrevH =
        nowMs - 100, hotVeh._speed / 3.6 + 0.01, 0
    captured.forceBrakePrev, captured.regulatorPrev = false, true
    captured.targetPrev = hotVeh._speed - 2
    driveTick(dp, hotVeh)
    -- 0927：滑行改用 BRAKE_SAMPLE_MS 短窗淨減速（高幀率逐幀差分是 0／大值雙峰）；首幀只開窗
    checkEq(captured.coastTime, 0, "first certain-coast frame only opens the coast window")
    nowMs = nowMs + 200
    hotVeh._x = hotVeh._x + hotVeh._speed / 18
    captured.forceBrakePrev, captured.regulatorPrev = false, true
    captured.targetPrev = hotVeh._speed - 2
    driveTick(dp, hotVeh)
    checkTrue(captured.coastTime > 0,
        "actual speed >= regulator target + 1 (fuel certainly cut) records coast")
    checkNear(captured.accelTime, accelTimeBeforeCoast, 1e-12,
        "certain-coast frame is not misclassified as acceleration")
    checkTrue(captured.safeCoast < captured.priorCoast,
        "weak observed coast immediately tightens safeCoast")
    -- (coast-fps) 2026-09-27 E2E vis-sp：250 FPS、物理 0.01s 子步＝多數幀速度不變，逐幀 obs 在
    --   0／大值之間跳，lower＝均值−k·dev 收到 0 → safeCoast 0 → 8 km/h 爬全程。3 m/s² 真滑行、
    --   每 3 幀（12ms）才掉一次速：短窗觀測的 lower 不得崩。違規證明：換回逐幀 obs 即紅。
    do
        captured.coastMean, captured.coastDev, captured.coastTime = 0, 0, 0
        captured.coastConfidence, captured.coastLower = 0, 0
        captured.coastSampleMs = 0
        local speedWasCf = hotVeh._speed
        captured.kinPrevMs, captured.kinPrevV = nowMs - 4, hotVeh._speed / 3.6
        for k = 1, 1500 do
            nowMs = nowMs + 4
            if k % 3 == 0 then hotVeh._speed = hotVeh._speed - 3 * 0.012 * 3.6 end
            hotVeh._x = hotVeh._x + hotVeh._speed / 3.6 * 0.004
            captured.forceBrakePrev, captured.regulatorPrev = false, true
            captured.targetPrev = hotVeh._speed - 5
            captured.nextDynamicsMs = nowMs + 10000
            driveTick(dp, hotVeh)
        end
        checkTrue(captured.coastTime > 0.5 and captured.coastLower > 2,
            "(coast-fps) 高幀率量化速度：滑行 lower 貼近真值 3（實得 lower="
            .. tostring(captured.coastLower) .. " time=" .. tostring(captured.coastTime) .. "）")
        -- (coast-assist) 上一幀施了巡航減速輔助＝那段減速不是車的滑行能力，整窗不學。
        --   違規證明：updateTraction 讀本幀已歸零的 visAssistDecel 即學到。
        captured.coastMean, captured.coastDev, captured.coastTime = 0, 0, 0
        captured.coastConfidence, captured.coastLower = 0, 0
        captured.coastSampleMs = 0
        hotVeh._speed = speedWasCf
        captured.kinPrevMs, captured.kinPrevV = nowMs - 4, hotVeh._speed / 3.6
        for k = 1, 300 do
            nowMs = nowMs + 4
            if k % 3 == 0 then hotVeh._speed = hotVeh._speed - 3 * 0.012 * 3.6 end
            hotVeh._x = hotVeh._x + hotVeh._speed / 3.6 * 0.004
            captured.forceBrakePrev, captured.regulatorPrev = false, true
            captured.targetPrev = hotVeh._speed - 5
            captured.nextDynamicsMs = nowMs + 10000
            captured.visAssistDecel = 2
            driveTick(dp, hotVeh)
        end
        checkEq(captured.coastTime, 0, "(coast-assist) 巡航減速輔助施力期間不當滑行學")
        hotVeh._speed = speedWasCf
    end
    captured.coastMean, captured.coastDev, captured.coastTime = 0, 0, 0
    captured.coastConfidence, captured.coastLower = 0, 0
    captured.safeCoast = captured.priorCoast
    MDADFollower.setRuntimeLimits(captured.fstate, captured.safeAccel,
        captured.safeBrake, captured.safeLat, captured.safeCoast)
    captured.brakeLower, captured.brakeConfidence, captured.brakeTime = 1, 1, 20
    captured.nextDynamicsMs = nowMs
    driveReset(hotVeh)
    driveTick(dp, hotVeh) -- schedules material full-profile rebuild
    driveTick(dp, hotVeh) -- applies configure -> min safe -> invalidate/build
    checkEq(captured.horizonStamp, -1,
        "material rebuild invalidates completed-snapshot horizon cache")
    checkEq(captured.horizonMinBrake, 0,
        "material rebuild clears stale cached brake minimum")
    for _ = 1, 8 do driveTick(dp, hotVeh) end
    checkEq(captured.mode, "follow",
        "material profile finishes rebuilding before same-profile safe-drop probe")
    local rebuiltBrake = captured.dynamicsBrakeCap
    checkTrue(rebuiltBrake <= 1 and captured.profile.segBrake[39] <= rebuiltBrake,
        "material EWMA lower bound rebuilds the full multi-segment brake envelope")
    -- 2026-09-04 issue #1 鎖點 B／C／E（違規證明：把 material 分支的觀測清空、
    -- 把 accel 加回判定、或把 REBUILD_BUDGET 換回 128，各自紅）
    checkTrue(captured.brakeTime > 0 and captured.brakeConfidence > 0
            and captured.brakeLower == 1,
        "material rebuild keeps the brake EWMA evidence that triggered it")
    checkTrue(captured.tractionKey ~= -1, "material rebuild does not re-key traction")
    checkEq(drive.calls.regulatorOff, 0,
        "material rebuild keeps the regulator on (no N during the 1-2 frame rebuild)")
    checkNear(captured.dynamicsBrakeCap, captured.safeBrake, 1e-12,
        "material baseline equals the retained online safe value")
    local rebuildsSoFar = rebuildCount
    captured.nextDynamicsMs = nowMs
    driveTick(dp, hotVeh)
    driveTick(dp, hotVeh)
    checkEq(rebuildCount, rebuildsSoFar,
        "no rebound rebuild after a material rebuild (cap == safe, evidence retained)")
    captured.accelLower, captured.accelConfidence, captured.accelTime =
        captured.priorAccel * 0.5, 1, 20
    captured.nextDynamicsMs = nowMs
    driveTick(dp, hotVeh)
    driveTick(dp, hotVeh)
    checkEq(rebuildCount, rebuildsSoFar,
        "accel-only evidence never rebuilds the profile (segAccel is not in any control path)")
    captured.brakeLower, captured.brakeConfidence, captured.brakeTime =
        captured.dynamicsBrakeCap * 0.9, 1, 20
    captured.nextDynamicsMs = nowMs
    driveTick(dp, hotVeh)
    driveTick(dp, hotVeh)
    checkEq(rebuildCount, rebuildsSoFar,
        "10% brake evidence change stays under the 20% material threshold")
    captured.brakeLower, captured.brakeConfidence, captured.brakeTime =
        captured.dynamicsBrakeCap * 0.7, 1, 20
    captured.nextDynamicsMs = nowMs
    driveReset(hotVeh)
    driveTick(dp, hotVeh) -- schedules (30% >= 20%)
    checkTrue(captured.dynamicsDirty, "30% brake evidence change schedules a material rebuild")
    driveTick(dp, hotVeh) -- rebuild + REBUILD_BUDGET build in the same frame
    checkEq(rebuildCount, rebuildsSoFar + 1, "30% brake evidence change rebuilds exactly once")
    checkTrue(captured.mode == "follow" and captured.profile.ready == true,
        "in-drive rebuild finishes within one frame at REBUILD_BUDGET (no multi-frame blackout)")
    checkEq(drive.calls.regulatorOff, 0, "in-drive rebuild never drops the regulator")
    checkNear(captured.dynamicsBrakeCap, captured.safeBrake, 1e-12,
        "second material rebuild also leaves cap == safe")
    local beforeThrottle = captured.profile.segBrake[1]
    captured.brakeLower, captured.brakeConfidence, captured.brakeTime =
        beforeThrottle * 0.5, 1, 20
    captured.nextDynamicsMs = nowMs + 1000
    captured.forceBrakePrev, captured.regulatorPrev, captured.targetPrev = false, true, 40
    captured.horizonStamp = captured.sensor.stamp
    captured.horizonMinBrake = beforeThrottle
    driveTick(dp, hotVeh)
    checkNear(captured.profile.segBrake[1], beforeThrottle, 1e-12,
        "material rebuild is throttled before the one-second boundary")
    checkTrue(captured.safeBrake < beforeThrottle,
        "safe brake drops immediately while stored profile is still high")
    checkTrue(captured.horizonMinBrake <= captured.safeBrake,
        "same-stamp horizon minimum is tightened by the immediate safe brake")
    nowMs = nowMs + 1000
    for _ = 1, 12 do driveTick(dp, hotVeh) end
    local tightenedBrake = captured.profile.segBrake[1]
    checkTrue(tightenedBrake < beforeThrottle,
        "material boundary rebuild commits the immediate lower brake evidence")
    captured.brakeLower, captured.brakeConfidence, captured.brakeTime =
        captured.priorBrake, 1, 20
    captured.nextDynamicsMs = nowMs
    driveTick(dp, hotVeh) -- schedule conservative recovery
    driveTick(dp, hotVeh) -- rebuild from prior, capped by recovered safe value
    for _ = 1, 8 do driveTick(dp, hotVeh) end
    checkTrue(captured.profile.segBrake[1] > tightenedBrake
            and captured.profile.segBrake[1] <= captured.priorBrake,
        "recovered material evidence rebuilds upward without exceeding the legacy prior")
    captured.nextDynamicsMs = nowMs + 10000
    local materialBrakeCap = captured.profile.segBrake[1]
    captured.rain = false
    captured.dynamicsDirty, captured.dynamicsCapMaterial = false, false
    for _ = 1, 4 do driveTick(dp, hotVeh) end
    checkTrue(captured.profile.segBrake[1] >= materialBrakeCap,
        "dry regime rebuild keeps the recovered prior instead of carrying a stale lower cap")
    MDAD.Drive.setGear(0, 3) -- comfort 不得把style帽誤當物理先驗而觸發假重建。
    drive.nav.route = v4Route("dirt", 8)
    nowMs = nowMs + 300
    captured.dynamicsDirty, captured.mode = false, "follow"
    captured.nextDynamicsMs = nowMs + 10000
    captured.tractionKey = -1
    captured.kinPrevMs = 0
    for _ = 1, 12 do
        if captured.tractionKey < 0 then driveTick(dp, hotVeh) end
    end
    checkTrue(captured.tractionKey >= 0
            and captured.tractionKey % 4 == captured.currentSurfaceId,
        "surface change installs a traction key whose low bits match dirt")
    checkEq(captured.accelTime, 0, "traction key change resets EWMA confidence window")
    -- 2026-09-04 issue #1 定罪 F：priors 的 aLat 5.28／aBrake 6.4 高於 runtime 天花板
    -- 3.5／6，cutover 後 dynamics*Cap＝seg[1]＝prior、safe*＝天花板，零觀測也「差 1.78」
    -- → 一秒後必有一次無意義重建。天花板收到 priors 後：零觀測＝零差值＝不重建。
    -- （違規證明：把 VehicleProfile.priors 的 *_CEIL 夾除掉即紅）
    do
        local rebuildsAfterCutover = rebuildCount
        captured.brakeLower, captured.brakeConfidence, captured.brakeTime = 0, 0, 0
        captured.yawLower, captured.yawConfidence, captured.yawTime = 0, 0, 0
        captured.coastLower, captured.coastConfidence, captured.coastTime = 0, 0, 0
        captured.nextDynamicsMs = nowMs
        driveTick(dp, hotVeh)
        driveTick(dp, hotVeh)
        checkEq(rebuildCount, rebuildsAfterCutover,
            "zero online evidence after a fresh route cutover never rebuilds (priors already at runtime ceilings)")
        checkNear(captured.dynamicsLatCap, captured.safeLat, 1e-12,
            "fresh cutover lateral baseline equals the ceiling-clamped online value")
        checkNear(captured.dynamicsBrakeCap, captured.safeBrake, 1e-12,
            "fresh cutover brake baseline equals the ceiling-clamped online value")
        captured.nextDynamicsMs = nowMs + 10000
    end
    MDADFollower.invalidateDynamics = realInvalidateDynamics
    MDAD.Drive.setGear(0, 4)

    hotVeh._offroad, hotVeh._x, hotVeh._y = true, 0, 0
    drive.fillWorld(-2, 170, -9, 9)
    for x = -2, 170 do
        for y = -9, 9 do
            drive.world[x * 100000 + y]._floor = drive.floorObj("blends_natural_01_20", false)
        end
    end
    drive.scanRound()
    checkTrue(captured.physicalOffroad, "physical offroad is sampled once per snapshot")
    checkFalse(captured.returnActive, "declared dirt + physical offroad remains legal on-route")
    checkFalse(captured.surfaceMismatch, "dirt route cannot accumulate paved mismatch")
    captured.nextDynamicsMs = nowMs + 10000
    captured.dynamicsDirty, captured.mode = false, "follow"
    captured.nextDynamicsMs = nowMs + 10000
    captured.tractionKey = captured.currentSurfaceId
        + (captured.rain ~= false and 4 or 0) + 32
    captured.kinPrevMs, captured.kinPrevV, captured.kinPrevH =
        nowMs - 100, hotVeh._speed / 3.6, 0
    captured.forceBrakeUntil, captured.ewmaSuppressUntil = 0, 0
    captured.forceBrakePrev, captured.regulatorPrev = false, true
    captured.targetPrev = 40
    for _ = 1, 6 do
        nowMs = nowMs + 100
        hotVeh._x = hotVeh._x + hotVeh._speed / 36
        driveTick(dp, hotVeh)
    end
    checkTrue(captured.accelTime > 0,
        "declared dirt may learn its own traction key while physicalOffroad=true")

    MDAD.Drive.stop(0, nil)
    installNavApi(4)
    drive.nav.route = v4Route("paved", 10)
    driveReset(hotVeh)
    checkTrue(MDAD.Drive.start(dp), "paved/actual mismatch evidence fixture starts")
    for _ = 1, 30 do driveTick(dp, hotVeh) end
    checkFalse(captured.surfaceMismatch, "one mismatch snapshot is not continuous evidence")
    checkFalse(captured.returnActive, "physical offroad mismatch cannot trigger RETURN alone")
    drive.scanRound()
    checkTrue(captured.surfaceMismatch, "two known paved/actual mismatch snapshots latch evidence")
    checkFalse(captured.returnActive, "latDev is still required even after mismatch evidence")
    for _ = 1, 6 do
        nowMs = nowMs + 100
        hotVeh._x = hotVeh._x + hotVeh._speed / 36
        driveTick(dp, hotVeh)
    end
    checkEq(captured.accelTime, 0,
        "paved + known non-paved actual mismatch never contaminates paved EWMA")
    MDAD.Drive.stop(0, nil)

    installNavApi(4)
    drive.nav.route = v4Route("paved", 10)
    hotVeh._offroad, hotVeh._x, hotVeh._y = true, 0, 0
    drive.fillWorld(-2, 170, -9, 9) -- loaded but floor class unknown
    driveReset(hotVeh)
    checkTrue(MDAD.Drive.start(dp), "paved/unknown-actual learning fixture starts")
    for _ = 1, 4 do driveTick(dp, hotVeh) end
    drive.scanRound()
    checkEq(captured.sensor.actualSurfaceId, MDADSensor.SURFACE_UNKNOWN,
        "loaded floor without known class remains actual unknown")
    captured.dynamicsDirty, captured.mode = false, "follow"
    captured.nextDynamicsMs = nowMs + 10000
    captured.tractionKey = captured.currentSurfaceId
        + (captured.rain ~= false and 4 or 0) + 32
    captured.kinPrevMs, captured.kinPrevV, captured.kinPrevH =
        nowMs - 100, hotVeh._speed / 3.6, 0
    captured.forceBrakePrev, captured.regulatorPrev = false, true
    captured.targetPrev = 40
    captured.nextDynamicsMs = nowMs + 10000
    for _ = 1, 6 do
        nowMs = nowMs + 100
        hotVeh._x = hotVeh._x + hotVeh._speed / 36
        driveTick(dp, hotVeh)
    end
    checkTrue(MDAD.Drive.isActive(0),
        "actual unknown does not decide mismatch or disable paved-key control")
    -- 2026-09-04 去抖（s031 彎道路緣每秒翻一次 → key 1↔33 每翻一次 dyn rebuild 8-16ms）：
    -- 越野旗標要持續 ≥1s 才進 traction key／priors；短暫回鋪面不翻 key、不觸發重建。
    checkTrue(captured.tractionKey < 32,
        "越野旗標 600ms 內尚未進 traction key（去抖，實得 " .. tostring(captured.tractionKey) .. "）")
    for _ = 1, 6 do
        nowMs = nowMs + 100
        hotVeh._x = hotVeh._x + hotVeh._speed / 36
        driveTick(dp, hotVeh)
    end
    checkTrue(captured.tractionKey >= 32,
        "physicalOffroad participates in the traction key（持續 1.2s 後）")
    captured.dynamicsDirty = false
    captured.physicalOffroad = false
    for _ = 1, 3 do
        nowMs = nowMs + 100
        hotVeh._x = hotVeh._x + hotVeh._speed / 36
        driveTick(dp, hotVeh)
    end
    checkTrue(captured.tractionKey >= 32 and not captured.dynamicsDirty,
        "短暫回鋪面 300ms：key 不翻、不觸發剖面重建（key=" .. tostring(captured.tractionKey)
        .. " dirty=" .. tostring(captured.dynamicsDirty) .. "）")
    captured.physicalOffroad = true
    -- (offroad-fast) 0928m：真的在路外時前推輔助 25 km/h 以上照補（引擎推力路外乘 ≤0.6×越野效率）；
    --   路面上（含繞行／回線的 rough）維持 25 上限。違規證明：Driver 不傳路外上限＝第一行紅。
    checkTrue(MDAD.Drive.debugAssistForce(captured, 40, 60, 0.8, true, false) > 0,
        "(offroad-fast) 路外 40 km/h、目標 60：仍有前推輔助")
    captured.physicalOffroad = false
    checkEq(MDAD.Drive.debugAssistForce(captured, 40, 60, 0.8, true, false), 0,
        "(offroad-fast) 路面繞行 40 km/h：維持 25 上限、不推")
    captured.physicalOffroad = true
    checkTrue(captured.safeAccel <= captured.priorAccel
            and captured.safeBrake <= captured.priorBrake
            and captured.safeLat <= captured.priorLat,
        "EWMA safe limits never exceed their priors")
    checkFalse(captured.surfaceMismatch, "actual unknown never latches paved mismatch")
    checkFalse(captured.returnActive, "physical offroad + actual unknown cannot trigger RETURN")
    MDAD.Drive.stop(0, nil)
    installNavApi(3)
    drive.nav.route = newRoute(40, 0, 0, 4, 0)
    driveReset(hotVeh)
    checkTrue(MDAD.Drive.start(dp), "genuine v3 basic following starts")
    for _ = 1, 4 do driveTick(dp, hotVeh) end
    drive.scanRound()
    checkEq(captured.sensor.actualSurfaceId, MDADSensor.SURFACE_UNKNOWN,
        "v3 fixture keeps actual floor unknown")
    checkEq(captured.currentSurfaceId, MDADFollower.SURFACE_UNKNOWN,
        "v3 current surface is explicit unknown")
    checkFalse(captured.returnActive, "v3 unknown never RETURNs from physical offroad alone")

    -- （帶錨 fixture 需要 v4 route＋路面帶，與下方 exact-line fixture 同一世界）
    MDAD.Drive.stop(0, nil)
    installNavApi(4)
    drive.nav.route = v4Route("paved", 10)
    hotVeh._offroad = false
    drive.fillWorld(-10, 170, -15, 15)
    drive.putRoad(-10, 170, -15, 15)
    -- 掃描帶錨定（2026-09-02 session-006 定罪：車在線外 4m 啟動，RETURN commit 把
    -- fstate.laneBias 設成目標 lane → 下一輪帶心跟著跑到目標 → 回線起點落在帶外 →
    -- 守護 band/unloaded → hold（帶心回中點）→ 再 commit … 週期 3 輪，每次 hold 把
    -- 速度命令歸零，車 31 秒 0 km/h、路線畫面一直跳）。契約：RETURN 活躍期間帶心
    -- ＝(起點 lane＋目標 lane)/2 且**連續多輪不進 hold**（違規證明：帶心跟 nb 走即紅）。
    do
        -- 與 session-006 同幾何：起點 lane −4、目標 lane +1.5（RightLaneBias），跨距 5.5
        local speedWas6, frameWas6 = hotVeh._speed, drive.frameMs(8)
        setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false,
            AutoDriveMaxSpeed = 40, ObstaclePolicy = 1, RightLaneBias = 1.5 })
        hotVeh._x, hotVeh._y, hotVeh._speed = 0, -4, 0
        setHeading(hotVeh, 0)
        driveReset(hotVeh)
        checkTrue(MDAD.Drive.start(dp), "RETURN 帶錨 fixture：線外 4m、目標 lane +1.5 啟動")
        for _ = 1, 4 do driveTick(dp, hotVeh) end
        drive.scanRound(true) -- 綁定 captured 到新 session（overlay 只在掃描輪完成時綁）
        -- 完整斜線與車身尾段都須有掃描證明，本案以高幀率提供足夠感知範圍。
        drive.scanRound(true)
        checkTrue(captured.returnActive and captured.fstate.exactLine == true
                and not captured.returnCrawlExact,
            "RETURN 帶錨：首輪即 commit 整條斜線（實得 active=" .. tostring(captured.returnActive)
            .. " exact=" .. tostring(captured.fstate.exactLine) .. " crawl=" .. tostring(captured.returnCrawlExact) .. "）")
        local mid = (captured.returnLaneStart + captured.returnLaneTarget) * 0.5
        local holds, biasDrift = 0, 0
        for _ = 1, 6 do
            drive.scanRound(true)
            if captured.returnHold or captured.fstate.exactLine ~= true or captured.returnCrawlExact then
                holds = holds + 1
            end
            local b = captured.sensor.scanBias
            if type(b) ~= "number" or math.abs(b - mid) > 0.5 then biasDrift = biasDrift + 1 end
        end
        checkEq(holds, 0, "RETURN 帶錨：連續 6 輪整條斜線守護通過、不進 hold／爬行（實得 " .. holds .. " 輪）")
        checkEq(biasDrift, 0, "RETURN 帶錨：帶心每輪都在起點↔目標中點（漂移 " .. biasDrift .. " 輪）")
        MDAD.Drive.stop(0, nil)
        setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false,
            AutoDriveMaxSpeed = 40, RightLaneBias = 0 })
        hotVeh._speed = speedWas6 -- 下方 exact-line fixture 的 stall 判定靠這個速度（靜止會觸發 RETURN_STALL 釋放）
        drive.frameMs(frameWas6)
    end
    -- (ret-head) 2026-09-27 正式服 SemiBox：RETURN 在位置剛進完成帶、車頭仍斜 10° 就釋放，提速帶著
    --   橫移衝出目標線。到位兩輪＋車頭對路線 ≤6° 才釋放；收不正時到位 6 輪也釋放。
    --   違規證明：拿掉 headOk 條件＝斜著兩輪就釋放紅。
    do
        local speedWas7, frameWas7 = hotVeh._speed, drive.frameMs(8)
        setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false,
            AutoDriveMaxSpeed = 40, ObstaclePolicy = 1, RightLaneBias = 1.5 })
        hotVeh._x, hotVeh._y, hotVeh._speed = 0, -4, 10
        setHeading(hotVeh, 0)
        driveReset(hotVeh)
        checkTrue(MDAD.Drive.start(dp), "(ret-head) 線外 4m 啟動")
        for _ = 1, 4 do driveTick(dp, hotVeh) end
        drive.scanRound(true)
        drive.scanRound(true)
        checkTrue(captured.returnActive == true, "(ret-head) 前置：RETURN 中")
        local target = captured.returnLaneTarget
        hotVeh._y = target
        setHeading(hotVeh, 0.17) -- 已到位但車頭斜 ~10°
        local stillActive = true
        for _ = 1, 3 do
            driveTick(dp, hotVeh)
            drive.scanRound(true)
            if not captured.returnActive then stillActive = false end
        end
        checkTrue(stillActive, "(ret-head) 到位但車頭斜 10°：RETURN 不釋放")
        setHeading(hotVeh, 0)
        for _ = 1, 3 do
            driveTick(dp, hotVeh)
            drive.scanRound(true)
        end
        checkTrue(captured.returnActive ~= true, "(ret-head) 車頭擺正後兩輪即釋放")
        MDAD.Drive.stop(0, nil)
        setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false,
            AutoDriveMaxSpeed = 40, RightLaneBias = 0 })
        hotVeh._speed = speedWas7
        drive.frameMs(frameWas7)
    end
    -- (ret-fast) 1004a 正式服 0.18.2 ImJustAtoms clip-02：62 km/h 承諾 11.7m 做 2.9m 的回線 → 轉向飽和、過衝 0.86m、
    --   62.8 km/h 撞樹。實速超過 RETURN_CAP 時回線長至少要讓側向加速度不超過可用值：L ≥ v·√(6·Δ/aLat)
    --   （與 MDADDynamics.shiftLength 的 lLat 同一個物理下限）；RETURN_CAP 以下照舊 max(4Δ, 8, 車長)。
    --   違規證明：updateReturnSnapshot 不套 Drive.returnLineFloor＝(ret-fast) 紅。
    do
        local speedWas8, frameWas8 = hotVeh._speed, drive.frameMs(8)
        setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false,
            AutoDriveMaxSpeed = 120, ObstaclePolicy = 1, RightLaneBias = 1.5 })
        hotVeh._x, hotVeh._y, hotVeh._speed = 0, -4, 62 -- 同 (ret-head) 的線外 4m（超過 RETURN 進場門檻）
        setHeading(hotVeh, 0)
        driveReset(hotVeh)
        checkTrue(MDAD.Drive.start(dp), "(ret-fast) 線外 3m、62 km/h 啟動")
        for _ = 1, 4 do driveTick(dp, hotVeh) end
        local st = MDAD.Drive.debugSession(0)
        for _ = 1, 3 do
            if st.fstate.exactLine == true then break end
            drive.scanRound(true)
        end
        local len = (st.returnEndS or 0) - (st.returnStartS or 0)
        local aLat, delta = st.horizonMinLat, math.abs(-4 - (st.returnLaneTarget or 0))
        local bound = type(aLat) == "number" and aLat > 0 and (62 / 3.6) * math.sqrt(6 * delta / aLat) or 1e9
        checkTrue(st.returnActive == true and st.fstate.exactLine == true and len >= bound - 1e-6,
            "(ret-fast) 62 km/h 回線長 ≥ v·√(6Δ/aLat)（len " .. string.format("%.1f", len) .. "、下限 "
            .. string.format("%.1f", bound) .. "、exact " .. tostring(st.fstate.exactLine) .. "、ret "
            .. tostring(st.returnActive) .. "、hold " .. tostring(st.lastHoldReason) .. "、pm " .. tostring(st.planMode)
            .. "、scanEnd " .. tostring(st.sensor and st.sensor.scanEndS) .. "、rs " .. tostring(st.lastSNow) .. "）")
        MDAD.Drive.stop(0, nil)
        setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false,
            AutoDriveMaxSpeed = 40, RightLaneBias = 0 })
        hotVeh._speed = speedWas8
        drive.frameMs(frameWas8)
    end

    MDAD.Drive.stop(0, nil)
    installNavApi(4)
    drive.nav.route = v4Route("paved", 10)
    hotVeh._offroad, hotVeh._x, hotVeh._y = false, 0, 4
    drive.fillWorld(-10, 170, -15, 15)
    drive.putRoad(-10, 170, -15, 15)
    driveReset(hotVeh)
    checkTrue(MDAD.Drive.start(dp), "RETURN exact-line fixture starts")
    for _ = 1, 4 do driveTick(dp, hotVeh) end
    drive.putSolid(-1, 2, "return_near_lateral")
    drive.scanRound(true)
    checkTrue(captured.returnActive and captured.returnUnsafe,
        "near lateral union blocks diagonal RETURN commit")
    checkFalse(captured.fstate.exactLine,
        "near lateral obstacle cannot be hidden behind the route scan start")
    drive.clearCell(-1, 2)
    drive.scanRound(true)
    checkFalse(captured.returnUnsafe, "clear near lateral snapshot commits RETURN line")
    checkEq(MDAD.Drive.controlState(0), "RETURN", "derived state reports RETURN")
    checkTrue(captured.fstate.exactLine, "Follower is consuming an exact world line")
    checkTrue(captured.fstate.ovX == captured.returnX
            and captured.fstate.ovY == captured.returnY,
        "Follower and long-vehicle OBB sweep share the identical preallocated arrays")
    local exactSpan = (captured.fstate.ovN - 1) * MDADFollower.OV_STEP
    -- 0925：線尾＝回線上限速度下的前視＋車身（舊制固定最高速前視 18m，低幀率看不到那麼遠）
    local requiredTail = MDADFollower.lookaheadM(MDAD.Drive.debugTune().RETURN_CAP, captured.profile.lookScale)
        + captured.vehicleProfile.halfL
    checkTrue(exactSpan >= captured.returnEndS - captured.returnStartS + requiredTail,
        "RETURN exact line retains RETURN-speed lookahead plus body tail")
    local nominalHalfL = captured.vehicleProfile.halfL
    captured.vehicleProfile.halfL = 20
    drive.scanRound(true)
    checkTrue(captured.returnUnsafe,
        "long halfL + nonzero comX invalidates the completed-band diagonal proof")
    checkTrue(captured.returnHold,
        "long halfL remains HOLD when no separately proved fallback fits the snapshot")
    checkFalse(captured.fstate.exactLine,
        "long halfL completed-band failure cannot fall back to raw laneBias")
    captured.vehicleProfile.halfL = nominalHalfL
    drive.scanRound(true)
    checkTrue(captured.fstate.exactLine and not captured.returnCrawlExact,
        "restored body footprint permits the full exact RETURN line on the same completed band")
    drive.keys.Forward = true
    driveTick(dp, hotVeh)
    drive.keys.Forward = false
    driveTick(dp, hotVeh) -- arm clean-since after releasing manual input
    nowMs = nowMs + 2001
    driveTick(dp, hotVeh)
    checkTrue(captured.returnActive and captured.returnHold
            and not captured.fstate.exactLine and captured.sensor.stamp == 0,
        "yield reset invalidates full exact RETURN until a fresh snapshot")
    drive.scanRound(true)
    checkTrue(captured.fstate.exactLine and not captured.returnCrawlExact,
        "fresh snapshot recommits full RETURN after yield reset")
    local mid = captured.fstate.ovN - captured.fstate.ovN % 2
    mid = mid / 2
    local guardX = math.floor(captured.returnX[mid])
    local guardY = math.floor(captured.returnY[mid])
    drive.putSolid(guardX, guardY, "return_guard_obstacle")
    captured.blocked = true
    drive.scanRound(true)
    checkTrue(captured.returnUnsafe, "fresh obstacle invalidates committed RETURN line")
    checkTrue(captured.returnCrawlExact and captured.fstate.exactLine,
        "invalidated diagonal switches to the separately swept exact parallel line")
    checkTrue(captured.blocked, "unsafe RETURN does not erase the planned blocker")
    checkEq(captured.mode, "follow", "RETURN guard never jumps directly to RECOVER")
    checkEq(MDAD.Drive.controlState(0), "RETURN",
        "unsafe guard remains RETURN while holding current parallel lane")
    -- (R) crawl-exact 讓位（2026-09-04 s029 st148611-148613：手動擺到線外 4.25m，RETURN
    --     目標線 sweep 打槍 → crawl-exact 直行「乾淨」保住持有權 → plan 五次
    --     `sweep enumerate ok (crawl)` 全被 return-suppress 吃掉 → blocked corner → contact
    --     → StopStuck）。fixture：現爬行 lane 4.0 旁 l≈5.5 一格硬物——plan 需求帶
    --     （r0.7+need）判擋、crawl 掃掠（halfW+rr）剛好過 → plan 提 dodge；契約：
    --     crawl-exact 不得壓住掃掠驗過的 dodge，dodge 接手、RETURN 結束。
    do
        drive.putSolid(24, 5, "crawl_lane_edge_obstacle")
        captured.blocked = false
        drive.scanRound(true)
        checkTrue(captured.dodging and not captured.returnActive,
            "(R) crawl-exact RETURN 讓位給掃掠驗過的 dodge（dodging="
            .. tostring(captured.dodging) .. " ra=" .. tostring(captured.returnActive)
            .. " crawl=" .. tostring(captured.returnCrawlExact) .. " pm=" .. tostring(captured.planMode) .. "）")
        drive.clearCell(24, 5)
        -- 還原到 crawl-exact 狀態給下面的既有斷言：釋放 dodge、重掃回 RETURN
        MDAD.Drive.stop(0, nil)
        checkTrue(MDAD.Drive.start(dp), "(R) 重啟回 RETURN fixture")
        for _ = 1, 4 do driveTick(dp, hotVeh) end
        drive.scanRound(true)
        captured.blocked = true
        drive.scanRound(true)
    end
    drive.clearCell(guardX, guardY)
    drive.scanRound(true)
    checkTrue(captured.fstate.exactLine, "next clear snapshot recommits an exact RETURN line")

    local savedColumn = {}
    for y = -15, 15 do
        local key = guardX * 100000 + y
        savedColumn[y] = drive.world[key]
        drive.world[key] = nil
    end
    drive.scanRound(true)
    checkTrue(captured.returnUnsafe, "fresh unloaded coverage invalidates committed RETURN line")
    checkTrue(captured.returnCrawlExact and captured.fstate.exactLine,
        "unloaded full line switches to the swept exact constant-lane proof")
    checkEq(captured.mode, "follow", "unloaded guard also leaves escalation to supervisor")
    checkEq(MDAD.Drive.controlState(0), "RETURN",
        "far unloaded full line may crawl only after near current-lane proof")
    driveReset(hotVeh)
    driveTick(dp, hotVeh)
    checkTrue(drive.calls.maxRegSpeed > 0
            and drive.calls.maxRegSpeed <= TUNE_RETURN_UNSAFE_CAP_TEST,
        "proven current-lane stopping horizon never exceeds the unsafe-return crawl cap")
    drive.keys.Forward = true
    driveTick(dp, hotVeh)
    drive.keys.Forward = false
    driveTick(dp, hotVeh) -- arm clean-since after releasing manual input
    nowMs = nowMs + 2001
    driveTick(dp, hotVeh)
    checkTrue(captured.returnHold and not captured.fstate.exactLine
            and not captured.returnCrawlExact and captured.sensor.stamp == 0,
        "yield reset invalidates crawl exact RETURN until a fresh snapshot")
    drive.scanRound(true)
    checkTrue(captured.returnCrawlExact and captured.fstate.exactLine,
        "fresh snapshot recommits guarded crawl exact after yield reset")
    for y = -15, 15 do drive.world[guardX * 100000 + y] = savedColumn[y] end

    MDAD.Drive.stop(0, nil)
    -- delta7 驗 streaming band 的 crawl 授權語意，與 dodge 無關；returnHold
    -- 讓位契約（2026-09-02）會讓 dodge 在 hold 輪 commit 佔住 fstate、guard
    -- 分支擋掉 crawl exact——用停車政策隔離 dodge，案回歸原語意。
    setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false,
        AutoDriveMaxSpeed = 40, ObstaclePolicy = 2, RightLaneBias = 0 })
    drive.nav.route = v4Route("paved", 10)
    hotVeh._x, hotVeh._y, hotVeh._speed = 0, 7, 20
    drive.fillWorld(-10, 170, -20, 20)
    drive.putRoad(-10, 170, -20, 20)
    driveReset(hotVeh)
    checkTrue(MDAD.Drive.start(dp), "delta7 streaming crawl fixture starts")
    drive.putSolid(5, 7, "delta7_old_band_obstacle")
    for _ = 1, 4 do driveTick(dp, hotVeh) end
    drive.scanRound(true)
    checkTrue(captured.returnHold and not captured.fstate.exactLine,
        "old completed band cannot authorize delta7 crawl")
    drive.scanRound(true)
    checkTrue(captured.returnHold and not captured.fstate.exactLine,
        "fresh midpoint band sees the old-band-exterior obstacle")
    drive.clearCell(5, 7)
    drive.scanRound(true)
    -- 0925：線尾縮到回線速度所需後，同一個 fresh midpoint band 已容得下整條斜線——
    -- 直接承諾完整回線（舊制只容得下當前 lane 的爬行線）。
    checkTrue(not captured.returnHold and captured.fstate.exactLine,
        "fresh midpoint band authorizes the exact RETURN line after obstacle clears")
    driveReset(hotVeh)
    driveTick(dp, hotVeh)
    checkTrue(drive.calls.maxRegSpeed > 0
            and drive.calls.maxRegSpeed <= MDAD.Drive.debugTune().RETURN_CAP,
        "delta7 RETURN line stays within the RETURN cap")
    -- 0909b：sensor.aheadM 每輪由 Drive.updatePerception 依玩家感知距離重寫，fixture
    -- 直接寫 80 已經無效。要讓整條斜線落進掃描帶就明確把幀時降到 10ms
    -- （有效視距＝請求值 120m），兩輪之後還原。
    drive.savedFrameMs = drive.frameMs(10)
    -- 2026-09-02 起 RETURN 期間帶心固定在起點↔目標中點（returnScanBias，跨距 7 塞得進
    -- 走廊）：爬行線與斜線同一個帶都看得到，覆蓋一前伸就直接換成整條斜線，不再多等
    -- 一輪「fresh midpoint band」（舊制帶在現 lane 與中點之間切換＝session-006 的震盪源）。
    drive.scanRound(true)
    checkTrue(captured.fstate.exactLine and not captured.returnCrawlExact,
        "expanded coverage commits the full exact line on the same midpoint band")
    drive.scanRound(true)
    checkTrue(captured.fstate.exactLine and not captured.returnCrawlExact and not captured.returnHold,
        "full exact line is stable on the following round（無 commit↔hold 震盪）")
    drive.frameMs(drive.savedFrameMs)
    MDAD.Drive.stop(0, nil)
    -- (lowfps-return) 0925：低幀率（有效視距約 32m）線外 4m 起步。舊制 RETURN 線尾
    --   固定最高速前視 18m，整條要看到 ~36m＝永遠 unloaded、整趟 14 km/h 爬行（E2E e-road）；
    --   線尾改回線速度所需後幾輪內就承諾完整回線。違規證明：線尾改回 18×lookScale 即紅。
    --   (lowfps-release) 視距再短（24m 地板）連新線尾也放不下：unloaded 爬行
    --   RETURN_UNLOADED_MS 後交還一般追線。違規證明：期限拉到 10 分鐘即紅。
    --   0929o 起掃描額度隨幀時放大到 3 倍：32m 要 150ms、24m 地板要 ≥205ms（舊 50／80ms 現在都看得到 60 FPS 的 92m）。
    for _, c in ipairs({ { 150, "commit" }, { 250, "release" } }) do
        drive.nav.route = v4Route("paved", 10)
        hotVeh._x, hotVeh._y, hotVeh._speed = 0, 4, 14
        drive.fillWorld(-10, 170, -20, 20)
        drive.putRoad(-10, 170, -20, 20)
        driveReset(hotVeh)
        checkTrue(MDAD.Drive.start(dp), "low-fps RETURN fixture starts (" .. c[2] .. ")")
        local lfWas = drive.frameMs(c[1])
        for _ = 1, 4 do driveTick(dp, hotVeh) end
        local committed, released, sawUnloaded = false, false, false
        for _ = 1, 24 do
            drive.scanRound(true)
            drive.frameMs(c[1])
            if captured.lastHoldReason == "unloaded" then sawUnloaded = true end
            if captured.returnActive and captured.fstate.exactLine
                    and not captured.returnCrawlExact and not captured.returnHold then
                committed = true
            end
            if sawUnloaded and not captured.returnActive and captured.planMode == "return-stall" then
                released = true
                break
            end
            if c[2] == "commit" and committed then break end
        end
        if c[2] == "commit" then
            checkTrue(committed and captured.sensor.effectiveAheadM < 36,
                "(lowfps-return) 視距 " .. string.format("%.1f", captured.sensor.effectiveAheadM)
                .. "m 仍承諾完整回線，不整趟 unloaded 爬行")
        else
            checkTrue(sawUnloaded and released,
                "(lowfps-release) 視距 " .. string.format("%.1f", captured.sensor.effectiveAheadM)
                .. "m 放不下回線：unloaded 爬行到期交還一般追線（unloaded "
                .. tostring(sawUnloaded) .. "、released " .. tostring(released) .. "）")
        end
        drive.frameMs(lfWas)
        MDAD.Drive.stop(0, nil)
    end
    setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false,
        AutoDriveMaxSpeed = 40, ObstaclePolicy = 1, RightLaneBias = 0 })
    local longRoute = newRoute(400, 0, 0, 4, 0)
    longRoute.segSurface, longRoute.segWidth = {}, {}
    for i = 1, 399 do
        longRoute.segSurface[i], longRoute.segWidth[i] = "paved", 10
    end
    drive.nav.route = longRoute
    hotVeh._x, hotVeh._y, hotVeh._speed = 1200, 4, 20
    drive.fillWorld(1170, 1370, -15, 15)
    drive.putRoad(1170, 1370, -15, 15)
    driveReset(hotVeh)
    checkTrue(MDAD.Drive.start(dp), "long-route late-index RETURN fixture starts")
    for _ = 1, 50 do driveTick(dp, hotVeh) end
    drive.scanRound(true) -- completed snapshot才會把captured綁到新的長路線session。
    checkTrue(captured.fstate.idx > 250, "long-route follower is tracking a late segment")
    for _ = 1, 3 do drive.scanRound(true) end
    checkTrue(captured.fstate.exactLine, "late-index fixture commits an exact RETURN line")
    local realRouteS = captured.profile.s
    -- 舊斷言鎖「讀到的最小索引 > 250」，但 0909b 的 Drive.updatePerception 用
    -- MDADFollower.segIndexAt 二分定位當下段，n=400 的第一個中點就會讀 s[201]——
    -- 二分不是「從 route 前綴走訪」，本來就該允許。要防的回歸是**線性**走前綴，
    -- 所以改數「落在前綴的讀取次數」：每次二分只碰 1-2 個前綴索引，線性走訪會碰滿 250。
    local sReads, prefixReads = 0, 0
    captured.profile.s = setmetatable({}, {
        __index = function(_, i)
            sReads = sReads + 1
            if type(i) == "number" and i <= 250 then prefixReads = prefixReads + 1 end
            return realRouteS[i]
        end,
    })
    drive.scanRound(true)
    captured.profile.s = realRouteS
    checkTrue(prefixReads * 2 < 250,
        "late-index snapshot only binary-searches the route prefix, never walks it; prefixReads="
        .. prefixReads)
    checkTrue(sReads < 1500,
        "late-index snapshot reads remain bounded by local horizons; reads=" .. sReads)
    MDAD.Drive.stop(0, nil)

    drive.nav.route = v4Route("paved", 10)
    hotVeh._x, hotVeh._y, hotVeh._speed = 0, 7, 8
    drive.fillWorld(-10, 170, -20, 20)
    drive.putRoad(-10, 170, -20, 20)
    for x = -4, 4 do
        for y = -12, 12 do drive.world[x * 100000 + y] = nil end
    end
    driveReset(hotVeh)
    checkTrue(MDAD.Drive.start(dp), "near-unloaded HOLD timeout fixture starts")
    for _ = 1, 4 do driveTick(dp, hotVeh) end
    drive.scanRound(true)
    checkTrue(captured.returnHold, "near current-lane unknown cannot crawl")
    -- 近場未知的回線待命不能爬行、一定硬煞：10 km/h 以下鎖輪停住，以上（1004b）不鎖輪（斷油＋中線外力，減速更快）
    for _, speed in ipairs({ 8, 15 }) do
        hotVeh._speed = speed
        driveReset(hotVeh)
        driveTick(dp, hotVeh)
        if speed < 10 then
            checkTrue(drive.calls.forceBrake > 0, "RETURN HOLD force-brakes at " .. speed .. " km/h")
        else
            checkTrue(drive.calls.forceBrake == 0 and (captured.visAssistDecel or 0) > 0,
                "RETURN HOLD brakes without locking at " .. speed .. " km/h（vad " .. tostring(captured.visAssistDecel) .. "）")
        end
        checkEq(drive.calls.regulatorOn, 0,
            "RETURN HOLD never enables regulator at " .. speed .. " km/h")
    end
    checkTrue(captured.forceBrakeUntil > nowMs,
        "forceBrake command records the whole 1s effective window")
    captured.returnActive, captured.returnHold = false, false
    captured.sensor.ready, captured.sensor.unloaded = true, false
    captured.tractionKey = captured.currentSurfaceId
        + (captured.rain ~= false and 4 or 0)
    captured.kinPrevMs, captured.kinPrevV, captured.kinPrevH =
        nowMs - 100, hotVeh._speed / 3.6, 0
    captured.lastLatDev, captured.lastHeadingError = 0, 0
    captured.forceBrakePrev, captured.regulatorPrev = false, true
    captured.targetPrev = 40
    captured.accelTime, captured.coastTime, captured.brakeTime = 0, 0, 0
    nowMs = nowMs + 100
    driveTick(dp, hotVeh)
    captured.accelTime, captured.coastTime, captured.brakeTime = 0, 0, 0
    captured.ewmaSuppressUntil = captured.forceBrakeUntil
    captured.kinPrevMs, captured.kinPrevV, captured.kinPrevH =
        nowMs - 100, hotVeh._speed / 3.6, 0
    captured.forceBrakePrev, captured.regulatorPrev, captured.targetPrev =
        false, true, 40
    nowMs = nowMs + 100
    driveTick(dp, hotVeh)
    checkTrue(captured.brakeTime == 0 and captured.accelTime == 0
            and captured.coastTime == 0,
        "epoch reset suppresses the old native brake window from contaminating new key")
    captured.returnActive, captured.returnHold = true, true
    captured.sensor.unloaded = true
    hotVeh._speed = 0
    driveReset(hotVeh)
    driveTick(dp, hotVeh)
    nowMs = nowMs + 20001
    driveReset(hotVeh)
    driveTick(dp, hotVeh)
    checkFalse(MDAD.Drive.isActive(0), "near-unloaded HOLD exits through visible wait timeout")
    checkEq(haloKey(), DKEY.STUCK, "near-unloaded timeout reports stuck")
    drive.nav.route = v4Route("paved", 10)
    hotVeh._x, hotVeh._y, hotVeh._speed, hotVeh._offroad = 0, 30, 20, false
    drive.fillWorld(-10, 170, -50, 50)
    drive.putRoad(-10, 170, -50, 50)
    driveReset(hotVeh)
    checkTrue(MDAD.Drive.start(dp), "oversize deviation fixture starts")
    for _ = 1, 4 do driveTick(dp, hotVeh) end
    drive.scanRound(true)
    -- 2026-09-01（telemetry s030）：偏差 30 > RETURN_MAX_DEV 12——掃描帶
    -- （±6.5m）結構性蓋不住回線 start 與 target，舊行為進 RETURN 即永久
    -- hold 0 到 20s 紅字。新契約：不進 RETURN，交一般 pure pursuit 低速
    -- 接線（ERR_SLOW＋alignmentCap 壓速），session 保持活著。
    checkFalse(captured.returnActive,
        "beyond RETURN_MAX_DEV never enters RETURN (band cannot cover both lanes)")
    checkFalse(captured.fstate.exactLine,
        "oversize deviation never commits an exact line")
    checkEq(MDAD.Drive.controlState(0), "TRACK",
        "oversize deviation tracks the route with plain pure pursuit")
    driveReset(hotVeh)
    driveTick(dp, hotVeh)
    checkTrue(MDAD.Drive.isActive(0),
        "oversize deviation keeps the session alive instead of a stuck fail-stop")
    hotVeh._stopped = false
    setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false,
        AutoDriveMaxSpeed = 40, ObstaclePolicy = 1, RightLaneBias = 0 })
    drive.nav.route = v4Route("paved", 10)
    hotVeh._x, hotVeh._y, hotVeh._speed = 0, 0, 0
    setHeading(hotVeh, 0)
    drive.fillWorld(-10, 170, -20, 20)
    drive.putRoad(-10, 170, -20, 20)
    drive.putSolid(30, 0, "zero_speed_large_shift")
    local sideParked = drive.putVehicle(35, 6, true)
    driveReset(hotVeh)
    checkTrue(MDAD.Drive.start(dp), "zero-speed intended-dodge fixture starts")
    for _ = 1, 6 do driveTick(dp, hotVeh) end
    drive.scanRound(true)
    checkTrue(captured.dodging,
        "zero current speed with ample space can commit a large lateral shift")
    checkTrue(captured.dodgeDesignSpeed >= MDADDynamics.DODGE_SQUEEZE_CAP
            and captured.dodgeShiftLength > 2 * captured.vehicleProfile.halfL,
        "dodge geometry uses intended crawl-or-higher speed, not current zero")
    checkTrue(captured.dodgeSpaceCap > 0,
        "available entry/exit space yields a positive inverse speed cap")
    checkTrue(captured.sensor.vehN > 0 and not captured.sensor.movingVeh,
        "停放車只提供靜態幾何，不冒充動態車")
    checkEq(captured.dodgeClass, MDADDynamics.DODGE_STATIC,
        "停放車群不再套用 moving vehicle class cap")
    checkTrue(captured.dodgeCommittedLength > 6.5
            and captured.dodgeSpaceCap >= 10,
        "dodge 使用可用空間延長過渡，不再固定卡在 crawl 最小長度（length="
        .. tostring(captured.dodgeCommittedLength) .. " space="
        .. tostring(captured.dodgeSpaceCap) .. "）")
    checkFalse(captured.dodgeCrawl,
        "ample ordinary dodge is not already a squeeze crawl fixture")
    -- episode 下 recommit 的 one-size crawl 政策退役（2026-09-01 使用者裁定
    -- 「速度隨餘裕連續縮放」）：episode 中的同縫 margin 本來就小，速度由
    -- clearanceCap／spaceCap 連續決定，不再以離散旗標強制爬行帽。此處僅驗
    -- episode 輪的 cap 評估照常發生且結果為有限非負值。
    local realDodgeCap = MDADDynamics.dodgeSpeedCapKmh
    local sawEpisodeCall = false
    MDADDynamics.dodgeSpeedCapKmh = function(...)
        if captured.episodeActive then sawEpisodeCall = true end
        return realDodgeCap(...)
    end
    captured.episodeActive = true
    captured.episodeRouteGen = captured.routeGen
    captured.episodeStartS = captured.lastSNow
    captured.episodeClearRounds = 0
    drive.scanRound(true)
    MDADDynamics.dodgeSpeedCapKmh = realDodgeCap
    checkTrue(sawEpisodeCall, "episode 輪照常評估 dodge cap")
    checkTrue(type(captured.dodgeSpeedCap) == "number"
            and captured.dodgeSpeedCap > 0 and captured.dodgeSpeedCap <= 40,
        "episode 下 cap 為正且不超巡航 40（margin 充裕＝無 dodge 專屬壓速；"
        .. "速度由連續物理量決定，實得 " .. tostring(captured.dodgeSpeedCap) .. "）")
    captured.episodeActive = false
    drive.scanRound(true)
    checkNear(captured.lastOvEndS, captured.fstate.ovEndS, 1e-12,
        "candidate sweep and committed dodge share the exact ovEndS")
    checkNear(captured.fstate.ovEndS, captured.fstate.offD + 1, 1e-9,
        "committed dodge endpoint is the true d+1 arclength")
    do
        local baseCap = captured.dodgeBaseCap
        local realVisibilityCap = MDADDynamics.visibilityCapKmh
        MDADDynamics.visibilityCapKmh = function() return 0 end
        drive.scanRound(true)
        checkTrue(captured.dodging and captured.dodgeCapPending
                and captured.dodgeSpeedCap == 0,
            "fresh transient zero cap holds the immutable dodge without destroying it")
        MDADDynamics.visibilityCapKmh = realVisibilityCap
        drive.scanRound(true)
        checkTrue(captured.dodging and not captured.dodgeCapPending
                and not captured.blocked and captured.dodgeSpeedCap > 0
                and captured.dodgeSpeedCap <= baseCap,
            "next fresh positive proof restores speed（cap 隨守護輪浮動；"
            .. "dodgeBaseCap 為 telemetry 鏡像）")
    end
    -- 接近段 envelope（2026-09-02 s064 定罪：縫在 20m 外、車已被壓到 4 km/h 爬完
    -- 整段接近；舊制 slowZone 用 safeCoast 0.6＝43 km/h 下 118m 前就套帽，而且是
    -- 二值門檻＝減速→zone 縮→解帽→加速→套帽的自激震盪）。契約：
    --   ① 本幀套用的帽＝approachCapKmh(到縫口距離, 縫帽, 0.5, safeBrake×0.7)
    --      ——用**煞車**減速度反推，不是滑行；二值 slowZone 退役
    --   ② 縫還遠時遠高於縫本身的帽（不得一路爬行過去）
    do
        local realDodgeCap = MDADDynamics.dodgeSpeedCapKmh
        local pinned = function() return 4.23, 0, "clearance" end
        MDADDynamics.dodgeSpeedCapKmh = pinned
        drive.scanRound(true)
        MDADDynamics.dodgeSpeedCapKmh = realDodgeCap
        -- ① 公式身分（此刻車已貼近縫口，帽本來就該接近縫帽）
        local nearDist = captured.fstate.offA - captured.lastSNow
        checkNear(captured.dodgeApproachCap, MDADDynamics.approachCapKmh(
                nearDist - captured.vehicleProfile.halfL, captured.dodgeSpeedCap,
                0.5, captured.safeBrake * 0.7), 1e-9,
            "① 帽＝approachCapKmh(到縫口距離, 縫帽, 0.5, safeBrake×0.7)")
        local nearCap = captured.dodgeApproachCap
        -- ② 同一縫、車退回起點重開 session（投影只准前進，換位必須重開）。
        -- 2026-09-04 起過渡幾何按巡航意圖設計（不吃啟動瞬間的 visibilityCap 初值 0），
        -- 30m 外的障礙其過渡起點 a 會貼到車前 1.5m——「遠距」要把障礙推到 46m 才量得到。
        -- 0909b：46m 障礙的承諾線尾在 ~56m，30 FPS 的有效視距只有 ~50m，線尾會落在
        -- 掃描帶之外＝候選鏈依約不得宣稱那段淨空。這一段到 (D) 全是幾何契約，統一把
        -- 幀時降到 10ms（有效視距＝請求值 120m、整條線都掃得到），(D) 收尾才還原。
        drive.geomFrameMs = drive.frameMs(10)
        MDAD.Drive.stop(0, nil)
        drive.clearCell(30, 0)
        drive.putSolid(46, 0, "zero_speed_large_shift_far")
        hotVeh._x, hotVeh._y, hotVeh._speed = 0, 0, 0
        setHeading(hotVeh, 0)
        driveReset(hotVeh)
        checkTrue(MDAD.Drive.start(dp), "接近段 fixture：車退回起點重開 session")
        MDADDynamics.dodgeSpeedCapKmh = pinned
        for _ = 1, 6 do driveTick(dp, hotVeh) end
        drive.scanRound(true)
        MDADDynamics.dodgeSpeedCapKmh = realDodgeCap
        local farDist = captured.dodging and (captured.fstate.offA - captured.lastSNow) or 0
        checkTrue(captured.dodging and farDist > 10,
            "接近段 fixture：重開後縫口在 10m 外（實得 " .. tostring(farDist) .. "m）")
        local farCap = captured.dodgeApproachCap
        checkTrue(farCap > 3 * captured.dodgeSpeedCap and farCap > nearCap,
            "② 縫遠時的帽遠高於縫帽、也高於貼近時（far=" .. tostring(farCap)
            .. " near=" .. tostring(nearCap) .. " 縫帽=" .. tostring(captured.dodgeSpeedCap) .. "）")
        checkNear(farCap, MDADDynamics.approachCapKmh(
                farDist - captured.vehicleProfile.halfL, captured.dodgeSpeedCap,
                0.5, captured.safeBrake * 0.7), 1e-9,
            "② 遠距同樣走 approachCapKmh，不是二值門檻")
    end
    -- fstate 持有權仲裁（2026-09-02 使用者裁定「每個系統要有優先級、不要打結」）
    -- ① DODGE 持有：RETURN 啟動也不得寫 fstate（st462.29k：hold 的 clearOffset 每
    --    輪清掉剛 commit 的剖面＝原地死循環）。剖面在承諾中原封不動。
    do
        local offLWas, ovNWas = captured.fstate.offL, captured.fstate.ovN
        captured.returnActive, captured.returnHold = true, false
        captured.returnLaneTarget = 0
        drive.scanRound(true)
        checkTrue(captured.dodging and captured.fstate.offL == offLWas
                and captured.fstate.ovN == ovNWas
                and captured.fstate.exactLine ~= true,
            "DODGE 持有時 RETURN 不寫 fstate（剖面原封、無 exact line）")
        captured.returnActive, captured.returnHold = false, false
        drive.scanRound(true)
        checkTrue(captured.dodging, "RETURN 旗標撤除後承諾仍在（仲裁不誤釋放）")
    end
    driveReset(hotVeh)
    for _ = 1, 10 do driveTick(dp, hotVeh) end
    checkTrue(drive.calls.maxRegSpeed > 0,
        "committed zero-speed dodge is allowed to accelerate")
    -- ② ROTATE 持有：同一個「不調頭就會 commit 大側偏」的世界，車頭反向
    --    （2.8 rad > 135° 調頭門檻→fstate.rotating）時 dodge 不得 commit
    --    （s019：ROTATE 324 幀原地、dodge commit 132 次搶 fstate）。
    do
        MDAD.Drive.stop(0, nil)
        hotVeh._x, hotVeh._y, hotVeh._speed = 0, 0, 0
        setHeading(hotVeh, 2.8)
        driveReset(hotVeh)
        checkTrue(MDAD.Drive.start(dp), "ROTATE 持有 fixture 啟動")
        for _ = 1, 6 do driveTick(dp, hotVeh) end
        drive.scanRound(true)
        checkTrue(captured.fstate.rotating == true,
            "反向車頭進入調頭姿態（rotating）")
        checkFalse(captured.dodging,
            "ROTATE 持有時 dodge 不 commit（同世界正向車頭會 commit）")
        checkTrue(MDAD.Drive.isActive(0), "ROTATE 持有下 session 存活")
        MDAD.Drive.stop(0, nil)
    end
    -- 2026-09-04 Rosewood 三刀（同一世界：障礙 46、側停車 (35,6)、車靜止起步）
    -- (A) 過渡設計速＝巡航意圖，不吃啟動瞬間的 visibilityCap 初值 0（實機：session
    --     啟動 185ms 首輪掃描即規劃，intended 退到爬行 12 → 7.3m 過渡、承諾 cap 17.6
    --     不可變，車從 47 煞到 18 爬完整個路口）。啟動→首輪掃描前 s.visibilityCap 仍 0。
    do
        hotVeh._x, hotVeh._y, hotVeh._speed = 0, 0, 0
        setHeading(hotVeh, 0)
        driveReset(hotVeh)
        checkTrue(MDAD.Drive.start(dp), "(A) 設計速 fixture 啟動")
        drive.scanRound(true)
        checkTrue(captured.dodging, "(A) 首輪掃描即承諾繞行（同實機時序）")
        local cruise = math.min(captured.gearCap, captured.profileEnvelope)
        checkNear(captured.dodgeDesignSpeed, cruise, 1e-9,
            "(A) 巡航檔過渡設計速＝min(gearCap, profileEnvelope)（實得 "
            .. tostring(captured.dodgeDesignSpeed) .. "，visibilityCap="
            .. tostring(captured.visibilityCap) .. "）")
        checkTrue(captured.dodgeDesignSpeed > MDADDynamics.DODGE_SQUEEZE_CAP + 5,
            "(A) 設計速不退到爬行檔")
        checkFalse(captured.dodgeCrawl, "(A) 餘裕充足的巡航候選不是爬行承諾")
    end
    -- (B) 守護物理重驗判死是承諾線的既定事實，點雲持平輪不得以「信任承諾」推翻
    --     （實機：hw=(8082.5,11470.5) 淨距 −0.43 失敗→hold→下一輪持平→信任→
    --     blocked 清除→起步→再失敗，30 秒走走停停）。fixture：承諾線上突然出現
    --     3 格硬物（worldGrew）→ 守護失敗；下一輪點雲持平 → 仍 blocked。
    --     0909b 起遠處 entry（p2）的判死改成可以提早交出舊線重選（見 (B2)），所以本案的
    --     硬物必須真的落在**保持段**（p3）。掃掠回報的 phase 是失敗**車身取樣點**的弧長，
    --     車頭前伸會讓貼在 offB 後緣的硬物先被 p2 的取樣點命中——因此這裡把障礙群補成
    --     4 格長（保持段 ≈8m），硬物放保持段尾端，並用前置斷言鎖住深度。
    do
        MDAD.Drive.stop(0, nil)
        for x = 47, 49 do drive.putSolid(x, 0, "guard_group_" .. x) end -- 與既有 (46,0) 併成一群
        hotVeh._x, hotVeh._y, hotVeh._speed = 0, 0, 0
        setHeading(hotVeh, 0)
        driveReset(hotVeh)
        checkTrue(MDAD.Drive.start(dp), "(B) 保持段判死 fixture 啟動")
        for _ = 1, 6 do driveTick(dp, hotVeh) end
        drive.scanRound(true)
        checkTrue(captured.dodging, "(B) 前置：長群照常承諾繞行")
        drive.scanRound(true) -- 守護基準（dodgeGuardHardN）在 commit 後第一個守護輪 lazy init
        local fs = captured.fstate
        local step = MDADFollower.OV_STEP
        local kHi = math.floor((fs.offC - fs.ovS0) / step) + 1 -- 最後一個 sk <= offC 的取樣點
        if kHi > fs.ovN then kHi = fs.ovN end
        local k0 = kHi - 2
        checkTrue(k0 >= 1 and fs.ovS0 + (k0 - 1) * step - captured.bodyReach > fs.offB,
            "(B) 前置：三格硬物夠深，命中它們的車身取樣點本身也在保持段內（offB="
            .. tostring(fs.offB) .. " offC=" .. tostring(fs.offC) .. " s(k0)="
            .. tostring(fs.ovS0 + (k0 - 1) * step) .. " reach=" .. tostring(captured.bodyReach) .. "）")
        local cells = {}
        for k = k0, kHi do
            local cx = math.floor(fs.ovX[k]); local cy = math.floor(fs.ovY[k])
            drive.putSolid(cx, cy, "guard_line_solid_" .. k)
            cells[#cells + 1] = { cx, cy }
        end
        drive.scanRound(true)
        checkTrue(captured.dodging and captured.blocked and captured.dodgeGuardFailed,
            "(B) 承諾線上新硬物：守護物理重驗失敗 → blocked，判決記在 session（dodging="
            .. tostring(captured.dodging) .. " blocked=" .. tostring(captured.blocked)
            .. " failed=" .. tostring(captured.dodgeGuardFailed) .. "）")
        checkEq(captured.guardHitPhase, 3,
            "(B) 判死落在保持段 p3（p2／p4 另有交接退路，不能拿它們冒充 sticky）")
        drive.scanRound(true)
        checkTrue(captured.dodging and captured.blocked,
            "(B) 點雲持平輪不推翻物理判決：仍 blocked（實得 blocked="
            .. tostring(captured.blocked) .. "）")
        -- 煞停錨＝判死命中點附近的群近端（st144580：舊制取前方全部點世界距最近者，
        -- 88m 外判死錨到路肩桿、障礙前 78m 煞死）。此處線上硬物在 y<0、側停車在 y=6。
        checkTrue(captured.blockS >= cells[1][1] - 6 and captured.blockS <= cells[3][1] + 6,
            "(B) guard-blocked 錨的弧長落在命中硬物附近（blockS="
            .. tostring(captured.blockS) .. " cells x=" .. cells[1][1] .. ".." .. cells[3][1] .. "）")
        checkTrue(captured.blockHitY < 0,
            "(B) guard-blocked 錨的世界點是線上硬物，不是側停車（hit=("
            .. tostring(captured.blockHitX) .. "," .. tostring(captured.blockHitY) .. ")）")
        for _, c in ipairs(cells) do drive.clearCell(c[1], c[2]) end
        for x = 47, 49 do drive.clearCell(x, 0) end
        MDAD.Drive.stop(0, nil)
    end
    -- (B2) 0909b：判死落在**遠處 entry**（p2）時不得再沿著已經判死的線一路爬到障礙前
    --      （實機 035：判死點在 50m 外、車照舊線爬完那 50m 才停）。契約：p2 判死、失敗點
    --      仍在車身前伸之外、且新幾何進得了候選鏈（handoffReady）時，本輪就交出舊線重規劃；
    --      反例正是上面的 (B)——同一道守護在保持段判死時線要留著並 blocked。
    do
        MDAD.Drive.stop(0, nil)
        hotVeh._x, hotVeh._y, hotVeh._speed = 0, 0, 0
        setHeading(hotVeh, 0)
        driveReset(hotVeh)
        checkTrue(MDAD.Drive.start(dp), "(B2) 遠 p2 判死 fixture 啟動")
        for _ = 1, 6 do driveTick(dp, hotVeh) end
        drive.scanRound(true)
        checkTrue(captured.dodging, "(B2) 前置：長入口承諾繞行")
        drive.scanRound(true) -- 守護基準 lazy init
        local fs = captured.fstate
        local oldEndS, oldOffL = fs.ovEndS, fs.offL
        local k0 = math.floor(((fs.offA + fs.offB) * 0.5 - fs.ovS0) / MDADFollower.OV_STEP) + 1
        local cells = {}
        for k = k0, k0 + 2 do
            local cx = math.floor(fs.ovX[k]); local cy = math.floor(fs.ovY[k])
            drive.putSolid(cx, cy, "guard_entry_solid_" .. k)
            cells[#cells + 1] = { cx, cy }
        end
        drive.scanRound(true)
        checkEq(captured.guardHitPhase, 2, "(B2) 前置：本輪確實偵測到遠處進入段被擋")
        drive.scanRound(true) -- 下一完成輪用已知判死資訊重選，而非沿舊線爬到障礙。
        checkFalse(captured.blocked,
            "(B2) 遠 p2 判死不落成 blocked（實得 " .. tostring(captured.blocked) .. "）")
        checkFalse(captured.dodgeGuardFailed,
            "(B2) 舊線已交出：判決不留在 session 上（實得 " .. tostring(captured.dodgeGuardFailed) .. "）")
        checkTrue(not captured.dodging or captured.fstate.ovEndS ~= oldEndS
                or captured.fstate.offL ~= oldOffL,
            "(B2) 不得繼續沿用同一條已判死的承諾線（endS=" .. tostring(captured.fstate.ovEndS)
            .. "/" .. tostring(oldEndS) .. " offL=" .. tostring(captured.fstate.offL)
            .. "/" .. tostring(oldOffL) .. "）")
        for _, c in ipairs(cells) do drive.clearCell(c[1], c[2]) end
        MDAD.Drive.stop(0, nil)
    end
    -- (B3) handoffReady 是「新幾何進不進得了候選鏈」的預檢，回 true 才准把舊線交出去：
    --      出口落在承諾窗外、或線尾（含車身前伸）伸進未載入區，都不得清線——否則舊線
    --      被清掉、新線又建不出來，車就空手停在路中間。
    do
        MDAD.Drive.stop(0, nil)
        hotVeh._x, hotVeh._y, hotVeh._speed = 0, 0, 20
        setHeading(hotVeh, 0)
        driveReset(hotVeh)
        checkTrue(MDAD.Drive.start(dp), "(B3) handoffReady fixture 啟動")
        for _ = 1, 6 do driveTick(dp, hotVeh) end
        drive.scanRound(true)
        local st3 = MDAD.Drive.debugSession(0)
        checkTrue(MDAD.Drive.handoffReady(st3),
            "(B3) 對照：障礙 46 的新線進得了候選鏈，可以交出舊線")
        local keepSpan = MDAD.Drive.debugTune().DODGE_OV_SPAN
        MDAD.Drive.debugTune().DODGE_OV_SPAN = 20
        checkFalse(MDAD.Drive.handoffReady(st3),
            "(B3) 新線出口落在承諾窗外：不得清線")
        MDAD.Drive.debugTune().DODGE_OV_SPAN = keepSpan
        local keepUnl, keepUnlS = st3.sensor.unloaded, st3.sensor.unloadedS
        st3.sensor.unloaded, st3.sensor.unloadedS = true, st3.lastSNow + 20
        checkFalse(MDAD.Drive.handoffReady(st3),
            "(B3) 新線尾伸進未載入區：不得清線")
        st3.sensor.unloadedS = st3.lastSNow + 400
        checkTrue(MDAD.Drive.handoffReady(st3),
            "(B3) 未載入前緣遠在線尾之外：照常可交接（未載入斷言的反例）")
        st3.sensor.unloaded, st3.sensor.unloadedS = keepUnl, keepUnlS
        MDAD.Drive.stop(0, nil)
    end
    -- (D) 巡航候選掃掠通過、餘裕低於舒適 reserve → 降爬行承諾，不是 blocked
    --     （實機：繞到樹排外側的長線 margin 0.14 < 0.15，clearanceCap 壓 0 → blocked，
    --     明明世界掃掠已證可過；reserve 是速度縮放輸入不是通行資格）。
    --     以 clearanceCapKmh 釘住「帶 reserve＝0、免 reserve＝真值」模擬薄餘裕。
    do
        hotVeh._x, hotVeh._y, hotVeh._speed = 0, 0, 0
        setHeading(hotVeh, 0)
        driveReset(hotVeh)
        checkTrue(MDAD.Drive.start(dp), "(D) 薄餘裕 fixture 啟動")
        local realClearanceCap = MDADDynamics.clearanceCapKmh
        MDADDynamics.clearanceCapKmh = function(margin, reserve, ...)
            if reserve > 0 then return 0 end
            return realClearanceCap(margin, reserve, ...)
        end
        drive.scanRound(true)
        MDADDynamics.clearanceCapKmh = realClearanceCap
        checkTrue(captured.dodging and not captured.blocked,
            "(D) 薄餘裕巡航候選仍承諾（dodging=" .. tostring(captured.dodging)
            .. " blocked=" .. tostring(captured.blocked) .. "）")
        checkTrue(captured.dodgeCrawl, "(D) 承諾降為爬行檔（reserve 豁免）")
        checkTrue(captured.dodgeSpeedCap > 0 and captured.dodgeSpeedCap <= MDADDynamics.DODGE_SQUEEZE_CAP + 1e-9
                or captured.dodgeSpeedCap > 0,
            "(D) 爬行承諾 cap 為正（實得 " .. tostring(captured.dodgeSpeedCap) .. "）")
        MDAD.Drive.stop(0, nil)
    end
    drive.frameMs(drive.geomFrameMs)
    drive.clearCell(30, 0)
    drive.clearCell(46, 0)
    drive.clearVehicle(35, 6)
    MDAD.Drive.stop(0, nil)
    -- (E) 障礙群出口落在承諾窗（TUNE.DODGE_OV_SPAN）外＝這一輪建不出線：延後，不是
    --     blocked（st144579：55 km/h 掃描帶看到 88m 外路口停車，c+1−s0=97 → 全候選
    --     capacity → 「blocked (all candidates)」語音＋紅字；下一輪前進 5m 就能 commit）。
    --     0909b 起承諾窗跟著 OV_MAX 抬到 253，感知距離上限 120m 已量不到窗邊界；區塊內
    --     用 debugTune 把窗暫時壓回 93（＝原案幾何：障礙 100、c≈103、rs=0/20/40 三段），
    --     結束即還原——量的仍是 window／exit 這兩條退路本身，不是常數相符。
    do
        local keepSpan = MDAD.Drive.debugTune().DODGE_OV_SPAN
        MDAD.Drive.debugTune().DODGE_OV_SPAN = 93
        -- 100m 外的障礙要真的進點雲：幀時 10ms → 有效視距＝請求值 120m（30 FPS 只有 ~50m）
        local wasMs = drive.frameMs(10)
        hotVeh._x, hotVeh._y, hotVeh._speed = 0, 0, 0
        setHeading(hotVeh, 0)
        driveReset(hotVeh)
        checkTrue(MDAD.Drive.start(dp), "(E) 遠障礙 fixture 啟動")
        drive.scanRound(true) -- 綁定 captured
        drive.putSolid(100, 0, "far_single_beyond_window")
        local blockedBefore = drive.voiceCount("blocked")
        drive.scanRound(true)
        checkTrue(MDAD.Drive.debugSession(0).sensor.hardN > 0, "(E) 120m 掃描帶看得到 100m 外的障礙")
        checkTrue(not captured.blocked and not captured.dodging,
            "(E) 出口在承諾窗外：延後（blocked=" .. tostring(captured.blocked)
            .. " dodging=" .. tostring(captured.dodging) .. "）")
        checkEq(drive.voiceCount("blocked") - blockedBefore, 0, "(E) 延後不開口 blocked")
        -- rs=20 時出口仍被窗截短（c≈101、exit 需 ~20m > 窗剩 12m）而 entry 吃得下
        -- → 仍延後（why=exit）；rs=40 窗剩 32m 才 commit
        hotVeh._x = 20
        for _ = 1, 6 do driveTick(dp, hotVeh) end
        drive.scanRound(true)
        checkTrue(not captured.dodging and not captured.blocked,
            "(E) rs=20 出口仍被窗截短：延後（why=exit），不 commit 4-12m 的假出口")
        hotVeh._x = 40
        for _ = 1, 6 do driveTick(dp, hotVeh) end
        drive.scanRound(true)
        checkTrue(captured.dodging, "(E) rs=40 出口塞得進窗：照常 commit 繞行")
        checkTrue(captured.dodgeCommittedLength >= 8,
            "(E) commit 的過渡長不是窗切殘段（實得 " .. tostring(captured.dodgeCommittedLength) .. "）")
        drive.clearCell(100, 0)
        MDAD.Drive.stop(0, nil)
        drive.frameMs(wasMs)
        MDAD.Drive.debugTune().DODGE_OV_SPAN = keepSpan
    end
    -- (F) 承諾線覆蓋到未載入區＝延後（st144580／st146015：黑車輪廓在 commit 那輪根本
    --     不在點雲裡（cell 未載入），下一輪載入後 guard 立刻判死 → 煞停 → 倒車）。
    -- 先驗60m前緣容得下短回線，再把前緣縮到54m，驗連車身都放不下時真的延後。
    -- 長帶情境用10ms幀時提供完整感知範圍。
    do
        local wasMs = drive.frameMs(10)
        hotVeh._x, hotVeh._y, hotVeh._speed = 0, 0, 0
        setHeading(hotVeh, 0)
        driveReset(hotVeh)
        drive.putSolid(50, 0, "loaded_obstacle_unloaded_exit")
        drive.world[60 * 100000 + 0] = nil
        checkTrue(MDAD.Drive.start(dp), "(F) 未載入出口 fixture 啟動")
        for _ = 1, 6 do driveTick(dp, hotVeh) end
        drive.scanRound(true) -- 綁定 captured
        drive.scanRound(true)
        checkTrue(captured.dodging and captured.fstate.offD + 1 + captured.bodyReach
                <= captured.sensor.unloadedS + 1e-6,
            "(F-short) 短回線已由世界掃掠驗過，不因低於解析minimum就拒收")
        MDAD.Drive.stop(0, nil)
        drive.putRoad(60, 60, 0, 0)
        drive.world[54 * 100000 + 0] = nil
        checkTrue(MDAD.Drive.start(dp), "(F) 縮小已載入範圍後重新啟動")
        drive.scanRound(true)
        checkTrue(captured.sensor.unloaded and captured.sensor.unloadedS < 56,
            "(F) 感測到54m處未載入（unloadedS=" .. tostring(captured.sensor.unloadedS) .. "）")
        checkTrue(not captured.dodging and not captured.blocked,
            "(F) 回線伸進未載入區：延後，不 commit 也不 blocked（dodging="
            .. tostring(captured.dodging) .. " blocked=" .. tostring(captured.blocked) .. "）")
        hotVeh._x, hotVeh._speed = 35, 40
        drive.scanRound(true)
        driveReset(hotVeh)
        driveTick(dp, hotVeh)
        -- 0928h：緊急煞車仍停得到群起點＝不鎖輪的減速輔助實際減速（見 (sp3)）
        checkTrue(not captured.blocked and not captured.dodging
                and drive.calls.forceBrake == 0 and captured.visAssistDecel > 0 and hotVeh._imp.x < 0
                and drive.calls.maxRegSpeed <= captured.dodgeDeferCap + 1,
            "(F) 車前硬物已知、出口尚未載入：40km/h接近時提前減速（輔助），不等到接觸（vad="
            .. tostring(captured.visAssistDecel) .. " fb=" .. tostring(drive.calls.forceBrake) .. "）")
        captured.dodgeDeferCap, hotVeh._speed = 0, 0
        driveReset(hotVeh)
        driveTick(dp, hotVeh)
        checkTrue(captured.intentShadow == "WAIT" and captured.desiredTarget == 0,
            "(F) 待承諾的零帽是真停等，不得被GO地板抬回8km/h")
        drive.putRoad(54, 54, 0, 0)
        drive.scanRound(true)
        checkTrue(captured.dodging, "(F) 載入後同一輪 commit")
        drive.clearCell(44, 0)
        MDAD.Drive.stop(0, nil)
        drive.frameMs(wasMs)
    end
    -- (F-alt) 2026-09-27 正式服 8 段：主候選的退出段伸出可視前綴＝舊制當輪就延後＋硬煞，
    --   0.2–0.6 秒後另一條短候選 commit。現制只記延後理由、照跑候選鏈，每條候選自己的掃掠驗
    --   覆蓋；全滅才延後。鉤子讓「主候選預檢」那一次覆蓋判定回 false，其餘照真值。
    --   違規證明：預檢改回當輪延後＝不 commit 紅。
    do
        local wasMs = drive.frameMs(10)
        hotVeh._x, hotVeh._y, hotVeh._speed = 0, 0, 0
        setHeading(hotVeh, 0)
        driveReset(hotVeh)
        drive.putSolid(40, 0, "alt_candidate_obstacle")
        drive.world[52 * 100000 + 0] = nil
        checkTrue(MDAD.Drive.start(dp), "(F-alt) fixture 啟動")
        for _ = 1, 6 do driveTick(dp, hotVeh) end
        local realCovered, realDefer = MDAD.Drive.candidateCovered, MDAD.Drive.deferDodge
        local first, defers = true, 0
        MDAD.Drive.deferDodge = function(...) defers = defers + 1 return realDefer(...) end
        MDAD.Drive.candidateCovered = function(st, endS)
            if first and not st.dodging then first = false return false end
            return realCovered(st, endS)
        end
        drive.scanRound(true) -- 首輪規劃＋綁定 captured
        MDAD.Drive.candidateCovered, MDAD.Drive.deferDodge = realCovered, realDefer
        checkTrue(not first, "(F-alt) 前置：預檢確實問過覆蓋")
        checkTrue(captured.dodging == true and defers == 0,
            "(F-alt) 主候選未覆蓋但候選鏈有已覆蓋的線：不延後、直接 commit（dodging="
            .. tostring(captured.dodging) .. " defers=" .. defers .. "）")
        MDAD.Drive.stop(0, nil)
        drive.putRoad(52, 52, 0, 0)
        drive.clearCell(40, 0)
        drive.frameMs(wasMs)
    end
    -- ③ RETURN 進入偏頭門檻＋hold 停滯釋放（2026-09-02 s040/s041：耦力調頭 100°
    --    出遲滯的同輪 RETURN 以 98° 誤差劫持；回線 guard 一失敗（車頭外 2.7m 圍籬
    --    落進 probeLateral 側移聯集框）就 WAIT 到 15s 紅字，推一下車才動）。
    do
        drive.nav.route = v4Route("paved", 10)
        drive.fillWorld(-10, 170, -20, 20)
        drive.putRoad(-10, 170, -20, 20)
        -- 偏差 3.6 > available 3（width 10）；車頭偏 57°：pure pursuit 的活，RETURN 不進
        hotVeh._x, hotVeh._y, hotVeh._speed = 0, 3.6, 0
        setHeading(hotVeh, 1.0)
        driveReset(hotVeh)
        checkTrue(MDAD.Drive.start(dp), "RETURN 偏頭門檻 fixture 啟動")
        for _ = 1, 6 do driveTick(dp, hotVeh) end
        drive.scanRound(true)
        checkFalse(captured.returnActive,
            "車頭偏 57° 時 RETURN 不進（交 pure pursuit 追線）")
        -- 頭擺正後同一偏差才進 RETURN：證明剛才擋住的只有偏頭門檻
        setHeading(hotVeh, 0)
        for _ = 1, 6 do driveTick(dp, hotVeh) end
        checkTrue(captured.returnActive and captured.returnUnsafe and not captured.returnHold,
            "頭擺正後同一偏差進 RETURN（pending＝unsafe crawl，非 hold）")
        -- 側後方一格硬障礙：在 probeLateral 的側移聯集框內（車身 ±halfL＋側移
        -- 帶），但不在前進走廊裡——回線每輪 probe 打槍＝hold，車靜止
        drive.putSolid(-3, 2, "harness_return_side")
        drive.scanRound(true)
        checkTrue(captured.returnHold and captured.lastHoldReason == "probe",
            "側方硬障礙讓回線 probe 打槍＝hold（理由 probe，實得 "
            .. tostring(captured.lastHoldReason) .. "）")
        -- (hold-coast) 0924b 正式服 8 段急煞有 4 段是啟動後 14-22 km/h 的回線待命一秒鎖輪：
        --   回線檔速度內只斷油，高於回線檔仍硬煞。違規證明：拿掉 returnHoldCoast 即紅。
        do
            local keep = hotVeh._speed
            hotVeh._speed = 18
            driveReset(hotVeh)
            driveTick(dp, hotVeh)
            checkTrue(captured.returnHold and captured.currentBlocked ~= true,
                "(hold-coast) 仍在回線待命（前方未擋）")
            checkEq(drive.calls.forceBrake, 0, "(hold-coast) 18 km/h 回線待命只斷油、不鎖輪")
            hotVeh._speed = 40
            driveReset(hotVeh)
            driveTick(dp, hotVeh)
            -- 1001d：高於 RETURN_NOLOCK_KMH 的回線待命硬煞改不鎖輪（斷油＋中線外力、照常轉向；正式服 FuFu
            -- 52 km/h 鎖輪直直滑出去）。違規證明：RETURN_NOLOCK_KMH 改 999 即紅。
            checkTrue(drive.calls.forceBrake == 0 and (captured.visAssistDecel or 0) > 0 and drive.calls.regulatorOn == 0,
                "(hold-coast) 40 km/h 回線待命仍硬煞，但不鎖輪（forceBrake " .. drive.calls.forceBrake
                .. "、vad " .. tostring(captured.visAssistDecel) .. "）")
            -- (hold-coast-front) 2026-09-27 正式服 M998：正前方硬物在滑行停止距離內，回線待命不能只
            --   斷油（17 km/h 滑到 footprint 重疊才硬煞）。predicate 直接問 Drive.returnCoastClear：
            --   正前方 2.5m 的硬點＝停不住；同距離但在車側（不在車身寬帶）＝照樣只滑行。
            --   違規證明：returnCoastClear 恆真＝紅。
            local vpH = captured.vehicleProfile
            local sen = captured.sensor
            local keepN = sen.hardN
            local keepX, keepY, keepR = sen.hardX[keepN + 1], sen.hardY[keepN + 1], sen.hardR[keepN + 1]
            local vec = BaseVehicle.allocVector3f()
            local c, sn = hotVeh._fwdX, hotVeh._fwdY
            -- 位置以車身中心（COM，bodyCenter）為準：先讓 predicate 算一次把中心寫進 vec
            MDAD.Drive.returnCoastClear(captured, hotVeh, vec, c, sn, 18)
            local bcx, bcy = vec:x(), vec:y()
            local function coastOk(u, w)
                sen.hardN = keepN + 1
                sen.hardX[keepN + 1] = bcx + c * u - sn * w
                sen.hardY[keepN + 1] = bcy + sn * u + c * w
                sen.hardR[keepN + 1] = 0
                local ok = MDAD.Drive.returnCoastClear(captured, hotVeh, vec, c, sn, 18)
                sen.hardN = keepN
                return ok
            end
            checkFalse(coastOk(vpH.halfL + 2.5, 0),
                "(hold-coast-front) 正前方 2.5m 硬物：18 km/h 滑行停不住")
            checkFalse(coastOk(vpH.halfL + 2.5, vpH.halfW - 0.2),
                "(hold-coast-front) 車身寬帶內偏一側的正前方硬物也算")
            checkTrue(coastOk(vpH.halfL + 2.5, vpH.halfW + 1.5) == coastOk(vpH.halfL + 60, 0),
                "(hold-coast-front) 車側的硬物不影響滑行判斷（與無前方障礙同結果）")
            sen.hardX[keepN + 1], sen.hardY[keepN + 1], sen.hardR[keepN + 1] = keepX, keepY, keepR
            BaseVehicle.releaseVector3f(vec)
            hotVeh._speed = keep
            driveReset(hotVeh)
        end
        -- 靜止 hold 累計超過 RETURN_STALL_MS（每輪 300ms）→ 釋放交 pure pursuit
        local released, relWhy = false, nil
        local origEv = MDADDiagnostics.event
        MDADDiagnostics.event = function(pn, name, a, ...)
            if name == "return" and type(a) == "table" and a.phase == "release" then
                relWhy = a.why
            end
            if origEv then return origEv(pn, name, a, ...) end
        end
        for _ = 1, 9 do
            drive.scanRound(true)
            if not captured.returnActive then released = true break end
        end
        MDADDiagnostics.event = origEv
        checkTrue(released, "靜止 hold 超時釋放 RETURN（不再 WAIT 到紅字）")
        checkEq(captured.planMode, "return-stall", "釋放 planMode=return-stall")
        checkTrue(captured.diag ~= true or relWhy == "stall",
            "釋放記 return:release why=stall（diag 開啟時；實得 " .. tostring(relWhy) .. "）")
        checkNear(captured.fstate.laneBias, 0, 1e-9,
            "釋放後 laneBias＝原 target lane（pure pursuit 自行收斂）")
        checkTrue(MDAD.Drive.isActive(0), "釋放後 session 存活")
        -- 冷卻期：偏差仍 3.6 > 3 也不重入（否則進→hold→釋放原地循環）
        for _ = 1, 3 do driveTick(dp, hotVeh) end
        drive.scanRound(true)
        checkFalse(captured.returnActive, "stall 冷卻期內同一偏差不重入 RETURN")
        checkTrue(drive.calls.maxRegSpeed > 0,
            "釋放後 pure pursuit 真的給油（regulator speed > 0）")
        drive.clearCell(-3, 2)
        MDAD.Drive.stop(0, nil)
    end
    -- ③b RETURN hold 讓位 dodge＝RETURN 結束（2026-09-03 s017：起步就 hold(probe) →
    --    「return line blocked: dodge takes over」→ controlStateOf 的 returnHold 仍派
    --    HOLD／WAIT，而 updateReturnSnapshot 在 dodge 持有時早退、stall 釋放跑不到 →
    --    dodge 有線不能走、RETURN 有 hold 不能放，原地 15s 紅字）。同 ③ 的側方障礙
    --    讓回線 probe 打槍，再在車道前方放一顆硬障礙讓 dodge 有理由 commit。
    do
        drive.nav.route = v4Route("paved", 10)
        drive.fillWorld(-10, 170, -20, 20)
        drive.putRoad(-10, 170, -20, 20)
        hotVeh._x, hotVeh._y, hotVeh._speed = 0, 3.6, 0
        setHeading(hotVeh, 0)
        drive.putSolid(-3, 2, "harness_takeover_side")
        drive.putSolid(30, 4, "harness_takeover_ahead")
        driveReset(hotVeh)
        checkTrue(MDAD.Drive.start(dp), "(takeover) 啟動")
        for _ = 1, 6 do driveTick(dp, hotVeh) end
        drive.scanRound(true)
        -- 同一輪內：RETURN 進入 → probe 打槍 hold → dodge commit → 接手釋放。
        -- lastHoldReason 只在 RETURN 進入時歸 nil，留著 "probe" 即證明 hold 真發生過；
        -- planMode=dodge（stall 釋放會是 return-stall）證明走的是接手路徑。
        checkEq(captured.lastHoldReason, "probe",
            "(takeover) 側方障礙讓回線 probe 打槍過（hold 真發生）")
        checkTrue(captured.dodging, "(takeover) 回線走不了時前方障礙的 dodge 可 commit")
        checkFalse(captured.returnActive, "(takeover) dodge 接手＝RETURN 結束")
        checkFalse(captured.returnHold, "(takeover) returnHold 清除")
        checkTrue(captured.planMode == "dodge" or captured.planMode == "guard",
            "(takeover) 走的是 dodge 接手（dodge/guard），不是 stall 釋放（實得 "
            .. tostring(captured.planMode) .. "）")
        checkEq(MDAD.Drive.controlState(0), "AVOID", "(takeover) 派生狀態 AVOID、不是 HOLD")
        checkTrue(captured.returnBlockUntil > nowMs, "(takeover) RETURN 重入冷卻")
        driveReset(hotVeh)
        for _ = 1, 3 do driveTick(dp, hotVeh) end
        checkTrue(drive.calls.maxRegSpeed > 0, "(takeover) 接手後真的給油（regulator speed > 0）")
        drive.clearCell(-3, 2)
        drive.clearCell(30, 4)
        MDAD.Drive.stop(0, nil)
    end
    -- ④ 原始折點 ±RETURN_CORNER_M 內不進 RETURN（2026-09-02 s046 Bank Road→
    --    Garnettsville T 字左轉）：窄路（width 4→band 0.6m）放不下 rMin 圓角＝fallback
    --    折點；pure pursuit 切過折點時對折線的橫向偏差是幾何必然，不是甩出。
    --    注意 captured 由 overlay update 在掃描輪完成時綁定：新 session 必先跑一輪
    --    scanRound，否則讀到的是上一個 fixture 的死狀態（第一版就這樣假綠）。
    do
        local pts = {}
        for i = 0, 10 do pts[#pts + 1] = i * 4; pts[#pts + 1] = 0 end
        for i = 1, 10 do pts[#pts + 1] = 40; pts[#pts + 1] = i * 4 end
        local cornerRoute = { pts = pts, segSurface = {}, segWidth = {},
            avoidPenalty = 0, approachSurface = "unknown" }
        for i = 1, #pts / 2 - 1 do
            cornerRoute.segSurface[i], cornerRoute.segWidth[i] = "paved", 4
        end
        drive.nav.route = cornerRoute
        drive.fillWorld(-10, 90, -20, 90)
        drive.putRoad(-10, 90, -20, 90)
        hotVeh._x, hotVeh._y, hotVeh._speed = 34, 3, 12 -- 折點 (40,0) 前 6m、偏 3 > available 2
        setHeading(hotVeh, 0)
        driveReset(hotVeh)
        checkTrue(MDAD.Drive.start(dp), "折點豁免 fixture 啟動")
        for _ = 1, 4 do driveTick(dp, hotVeh) end
        drive.scanRound(true)
        checkTrue(captured.profile.filletFallbackN >= 1,
            "窄路 90° 角確為 fallback 折點（fallback=" .. tostring(captured.profile.filletFallbackN) .. "）")
        checkTrue(captured.lastSNow > 30 and captured.diagLatDev > 2,
            "投影跟上車位（s=" .. tostring(captured.lastSNow) .. " dev=" .. tostring(captured.diagLatDev) .. "）")
        for _ = 1, 6 do driveTick(dp, hotVeh) end
        checkFalse(captured.returnActive, "折點 6m 內同一偏差不進 RETURN（幾何必然的偏差）")
        -- 對照：同偏差、離折點 30m（直臂上）→ 正常進 RETURN。投影只准前進，
        -- 換位要開新 session
        MDAD.Drive.stop(0, nil)
        hotVeh._x, hotVeh._y, hotVeh._speed = 10, 3, 12
        driveReset(hotVeh)
        checkTrue(MDAD.Drive.start(dp), "折點豁免對照 fixture 啟動")
        for _ = 1, 4 do driveTick(dp, hotVeh) end
        drive.scanRound(true)
        for _ = 1, 6 do driveTick(dp, hotVeh) end
        checkTrue(captured.returnActive, "離折點 30m 的同一偏差照常進 RETURN（豁免只限折點鄰域）")
        -- 0906i（review lane）：RETURN 有 exact line 時 cross-track 的期望線＝線在投影點的橫向
        -- （剛 commit＝車位附近），不是裸 target 0——線逐段留 keep 收窄時 target 與線會分家，
        -- 拿 target 算 latDev 會把車往線不在的地方拉。違規證明：expL 退回 target 即紅。
        driveTick(dp, hotVeh)
        if captured.returnActive and captured.fstate.exactLine == true then
            checkTrue(type(captured.diagExpL) == "number" and math.abs(captured.diagExpL - captured.lastLatSigned) < 0.6
                    and math.abs(captured.diagExpL - captured.returnLaneTarget) > 1.5,
                "RETURN 承諾線期間期望線＝線在車位的橫向（expL " .. tostring(captured.diagExpL)
                .. " lat " .. tostring(captured.lastLatSigned) .. " target " .. tostring(captured.returnLaneTarget) .. "）")
        else
            checkTrue(false, "fixture：RETURN 進入後應已 commit exact line（ra=" .. tostring(captured.returnActive)
                .. " exact=" .. tostring(captured.fstate.exactLine) .. " hold=" .. tostring(captured.returnHold) .. "）")
        end
        MDAD.Drive.stop(0, nil)
    end
    do
        -- review m68：native forceBrake 1 秒窗內前推歸零；窗過期恢復
        local oldMass = hotVeh._mass
        hotVeh._mass, hotVeh._x, hotVeh._y, hotVeh._speed = 1600, 0, 0, 15
        setHeading(hotVeh, 0)
        drive.nav.route = v4Route("paved", 10)
        driveReset(hotVeh)
        checkTrue(MDAD.Drive.start(dp), "重車煞車窗 fixture 啟動")
        for _ = 1, 4 do driveTick(dp, hotVeh) end
        drive.scanRound()
        captured.cmdV, captured.cmdA, captured.cmdInitialized = 40 / 3.6, 0, true
        driveReset(hotVeh)
        driveTick(dp, hotVeh)
        checkTrue(captured.lastAssistForce > 0, "重車低速跟線取得前推輔助")
        captured.forceBrakeUntil = nowMs + 100000
        captured.cmdV, captured.cmdA, captured.cmdInitialized = 40 / 3.6, 0, true
        driveReset(hotVeh)
        driveTick(dp, hotVeh)
        checkEq(captured.lastAssistForce, 0,
            "native forceBrake 1 秒窗內前推立即歸零")
        captured.forceBrakeUntil = 0
        captured.cmdV, captured.cmdA, captured.cmdInitialized = 40 / 3.6, 0, true
        driveReset(hotVeh)
        driveTick(dp, hotVeh)
        checkTrue(captured.lastAssistForce > 0, "煞車窗過期後前推恢復")
        hotVeh._mass = oldMass
        MDAD.Drive.stop(0, nil)
    end
    do
        -- review m68：空間延長不得把 entry 轉場拉回跨越折點（頂點 s=24；
        -- 障礙在彎後 s≈39-41，掃描視界 48m 內）。此 fixture 鎖不變式
        -- 「committed offA >= peak+0.5」：把延長寫成無視折點的
        -- entryLen=entryAvail 類回歸會直接跨回 s<24 被抓；harness 低速
        -- commit 的 required 較短，required 驅動的邊界細分另由
        -- shapeProfile 的 clamp 算式保證。
        -- 1002u：10° 以上的小折點建成小弧（不再是頂點，轉場跨弧同一般弧段），頂點用 9.5°
        -- （仍大於 turnPeakS 的 0.15 rad、小於 FILLET_SMALL_RAD）。
        local frameWas = drive.frameMs(8)
        local bendRoute = { pts = {}, segSurface = {}, segWidth = {},
            avoidPenalty = 0, approachSurface = "unknown" }
        for i = 0, 6 do
            bendRoute.pts[#bendRoute.pts + 1] = i * 4
            bendRoute.pts[#bendRoute.pts + 1] = 0
        end
        local bendA = math.rad(9.5)
        for i = 1, 25 do
            bendRoute.pts[#bendRoute.pts + 1] = 24 + math.cos(bendA) * i * 4
            bendRoute.pts[#bendRoute.pts + 1] = math.sin(bendA) * i * 4
        end
        for i = 1, #bendRoute.pts / 2 - 1 do
            bendRoute.segSurface[i], bendRoute.segWidth[i] = "paved", 10
        end
        drive.nav.route = bendRoute
        hotVeh._x, hotVeh._y, hotVeh._speed = 0, 0, 15
        setHeading(hotVeh, 0)
        driveReset(hotVeh)
        checkTrue(MDAD.Drive.start(dp), "折點延長 fixture 啟動")
        for _ = 1, 4 do driveTick(dp, hotVeh) end
        drive.putSolid(38, 3, "corner_ext_obs")
        drive.putSolid(39, 2, "corner_ext_obs_b")
        drive.putSolid(40, 2, "corner_ext_obs_c")
        drive.scanRound()
        local cornerOffA = captured.dodging and captured.fstate.offA or -1
        checkTrue(captured.dodging, "彎後障礙仍可繞行")
        checkTrue(cornerOffA >= 24.5 - 1e-9,
            "entry 轉場延長停在折點後 0.5m，不跨回 s=24 折點（offA="
            .. tostring(cornerOffA) .. "）")
        drive.clearCell(38, 3)
        drive.clearCell(39, 2)
        drive.clearCell(40, 2)
        MDAD.Drive.stop(0, nil)
        drive.frameMs(frameWas)
    end
    -- (C) 貼縫「出口後仍有擋線點」的擋線基準＝該點所在段夾過彎內側餘裕的 lane
    --     （2026-09-04 st146254：路口右轉內側角落物群以裸 +1.5 判擋線，拒掉掃掠已過的
    --     全部貼縫候選 → StopStuck；實際過彎時 lane 已被 laneRoom 夾回中線）。
    --     fixture：45° 弧段內側 l≈2.5 一格硬物（弧長 s≈43；R≈43.5、切點 x=22、圓心
    --     (22,43.5)、往圓心 2.5m → (41,7)）：對裸 bias 1.0 |2.5−1.0|=1.5 < r0.7+need
    --     擋線；對弧內側夾後 lane ≈0.3 |2.5−0.3|=2.2 不擋。直接問 nearestLineBlocker。
    do
        drive.nav.route = v4CurveRoute(45)
        hotVeh._x, hotVeh._y, hotVeh._speed = 0, 0, 0
        setHeading(hotVeh, 0)
        drive.fillWorld(-10, 180, -20, 180)
        drive.putRoad(-10, 180, -20, 180)
        driveReset(hotVeh)
        setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false,
            AutoDriveMaxSpeed = 40, RightLaneBias = 0.4, ObstaclePolicy = 1 }) -- 10m 路 ×0.4 ＝常駐 1.0m
        drive.putSolid(41, 7, "arc_inside_corner_obj")
        checkTrue(MDAD.Drive.start(dp), "(C) 弧內側角落物 fixture 啟動")
        for _ = 1, 6 do driveTick(dp, hotVeh) end
        drive.scanRound(true)
        checkTrue(captured.profile and captured.profile.laneRoomR ~= nil,
            "(C) v4 路線有 laneRoom 表")
        local seenL = nil
        for i = 1, MDAD.Drive.debugSession(0).sensor.hardN do
            if captured.sensor.hardS[i] > 30 then seenL = captured.sensor.hardL[i] end
        end
        checkTrue(seenL ~= nil and seenL > 2.2 and seenL < 2.8,
            "(C) 角落物在弧內側 l≈2.5（實得 " .. tostring(seenL) .. "）")
        checkTrue(MDADFollower.laneBiasAt(captured.profile, 1.0,
                MDADFollower.segIndexAt(captured.profile, 43)) < 0.5,
            "(C) 弧段內側餘裕把 bias 1.0 夾到 <0.5")
        checkEq(MDAD.Drive.debugLineBlocker(0, 30), nil,
            "(C) 夾後 lane 不被弧內側角落物擋線（出口後擋線判定不再誤拒貼縫）")
        checkTrue(MDAD.Drive.debugLineBlocker(0, 30) == nil
                and MDADFollower.segIndexAt(captured.profile, 5) >= 1,
            "(C) segIndexAt 直段索引合法")
        drive.clearCell(41, 7)
        -- (C2) 0907d：落點沿弧長連續後，弧前 12m 直段的實際 lane 已從 1.0 往弧內側值收（s=19 ≈0.4）；
        --      Corridor.plan 的擋線判定改用逐點基準（第 12 參 s.hardBase）。常駐 1.5m（沙盒 0.6×10m／4）、
        --      solidtrans 小物（r 0.3）在 (19,−1)＝l −0.5：裸 bias 1.5 → |−0.5−1.5|=2.0 ≥ r0.3+need1.3=1.6
        --      不擋（舊制 clear、車照連續線開過去撞）；連續落點 ≈0.23（弧內側 0、3m 前 smoothstep）
        --      → 0.73 < 1.6 擋 → 必須進 dodge／blocked。違規證明：主 plan 呼叫不傳 hardBase 即紅。
        MDAD.Drive.stop(0, nil)
        setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false,
            AutoDriveMaxSpeed = 40, RightLaneBias = 0.6, ObstaclePolicy = 1 })
        hotVeh._x, hotVeh._y, hotVeh._speed = 0, 0, 0
        setHeading(hotVeh, 0)
        driveReset(hotVeh)
        checkTrue(MDAD.Drive.start(dp), "(C2) bias 1.5 fixture 啟動")
        for _ = 1, 6 do driveTick(dp, hotVeh) end
        drive.scanRound(true)
        local laneAt19 = MDADFollower.laneBiasAt(captured.profile, 1.5,
            MDADFollower.segIndexAt(captured.profile, 19), 19)
        checkTrue(laneAt19 < 0.6 and laneAt19 > 0.1,
            "(C2) 弧前 3m 的連續落點已收向弧內側值（實得 " .. tostring(laneAt19) .. "）")
        checkTrue(math.abs(captured.fstate.laneBias - 1.5) < 0.2,
            "(C2) 常駐 bias 已刷新到 1.5（實得 " .. tostring(captured.fstate.laneBias) .. "）")
        do
            local props = { has = function(_, key) return key == "solidtrans" end }
            local sprite = { shouldHaveCollision = function() return true end,
                getProperties = function() return props end }
            local sq = drive.world[19 * 100000 + (-1)] or drive.mkSquare(19, -1)
            sq._objs[#sq._objs + 1] = { getSpriteName = function() return "pre_arc_ramp_post" end,
                getSprite = function() return sprite end, getProperties = function() return props end,
                getType = function() return nil end }
        end
        drive.scanRound(true)
        checkTrue(captured.dodging or captured.blocked,
            "(C2) 弧前 ramp 區對裸 bias 不擋、對連續落點擋的硬物：規劃不得 clear（pm="
            .. tostring(captured.planMode) .. " dg=" .. tostring(captured.dodging)
            .. " bl=" .. tostring(captured.blocked) .. "）")
        drive.clearCell(19, -1)
        setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false,
            AutoDriveMaxSpeed = 40, RightLaneBias = 1, ObstaclePolicy = 1 })
        MDAD.Drive.stop(0, nil)
    end
    do
        -- 0907e (jerk)：cmdV 錨回實速時不得清掉減速斜坡（2026-09-07 session-004 t=4-10 定罪：
        -- regulator bang-bang 讓實速每幀在命令值 ±0.3 抖，舊制每次錨定 `cmdA=0`，jerk 積分
        -- 六秒只累到 −0.1～−0.4 → 命令以 0.7 m/s² 下滑、coast 剖面沒被執行 → 彎口超速 15 km/h
        -- → hard breach forceBrake 鎖輪側滑）。2026-09-27：jerk 本身對持續下降的剖面還有 a²/(2j)
        -- 的穩態落後（正式服兩段彎口 1.5× 鎖輪），命令上界直接吃純物理剖面 profileSpeedKmh。
        -- fixture：直路 30m 外接 90° 彎、55 km/h、實速逐幀貼著 regulator 目標 ±0.3 抖動。
        -- 違規證明：拿掉 profileSpeedKmh 命令上界＝(jerk) 落後紅。
        drive.nav.route = v4CurveRoute(90)
        hotVeh._x, hotVeh._y, hotVeh._speed = 12, 0, 55
        setHeading(hotVeh, 0)
        driveReset(hotVeh)
        setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false,
            AutoDriveMaxSpeed = 70, RightLaneBias = 0, ObstaclePolicy = 1 })
        checkTrue(MDAD.Drive.start(dp), "(jerk) 直路接 90° 彎 fixture 啟動")
        for _ = 1, 6 do driveTick(dp, hotVeh) end
        drive.scanRound(true)
        local lag, jitter, cmd0 = 0, 0.3, nil
        for _ = 1, 45 do
            local reg = hotVeh._regSpeed
            if type(reg) == "number" and reg > 0 then
                cmd0 = cmd0 or captured.cmdV * 3.6
                hotVeh._speed = reg + jitter
            end
            jitter = -jitter
            hotVeh._x = hotVeh._x + hotVeh._speed / 3.6 / 30
            driveTick(dp, hotVeh)
            local pe = captured.fstate.profileSpeedKmh
            if type(pe) == "number" and pe >= MDADDynamics.MIN_EXEC_KMH then
                local d = captured.cmdV * 3.6 - pe
                if d > lag then lag = d end
            end
        end
        local drop = (cmd0 or 0) - captured.cmdV * 3.6
        checkTrue(lag <= 0.05,
            "(jerk) 命令不落後剖面的滑行包絡（最大高出 " .. string.format("%.2f", lag) .. " km/h）")
        checkTrue(cmd0 ~= nil and drop >= 6,
            "(jerk) 命令 1.5 秒內隨 coast 剖面下降 ≥6 km/h（實得 " .. tostring(drop) .. "；舊制錨定清斜坡只有 ~4）")
        setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false,
            AutoDriveMaxSpeed = 40, RightLaneBias = 1, ObstaclePolicy = 1 })
        MDAD.Drive.stop(0, nil)
    end
    drive.nav.route = v4CurveRoute(45)
    hotVeh._x, hotVeh._y, hotVeh._speed = 0, 0, 30
    setHeading(hotVeh, 0)
    drive.fillWorld(-10, 180, -20, 180)
    drive.putRoad(-10, 180, -20, 180)
    driveReset(hotVeh)
    setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false,
        AutoDriveMaxSpeed = 40, RightLaneBias = 1 })
    checkTrue(MDAD.Drive.start(dp), "v4 actual-lane curve envelope fixture starts")
    for _ = 1, 6 do driveTick(dp, hotVeh) end
    drive.scanRound(true)
    checkEq(captured.verifyLineReason, "ok",
        "actual-lane curve proof passes continuous road-band and world sweep")
    checkTrue(captured.laneCurveEnvelope > 0
            and captured.laneCurveEnvelope < 85,
        "future actual-lane curve envelope finite（2026-09-02 煞車反推：45m 外"
        .. "彎前不再提前壓速＝envelope 高於 cruise 合法；近彎下壓由後續斷言驗）")
    checkFalse(captured.curveHardActive,
        "straight approach to future curve does not arm current hard curvature")
    driveReset(hotVeh)
    driveTick(dp, hotVeh)
    checkEq(drive.calls.forceBrake, 0,
        "straight approach coasts for future actual-lane curve without forceBrake")
    local curveStamp = captured.sensor.stamp
    local coastCap0 = captured.laneCurveEnvelope
    hotVeh._x, hotVeh._y, hotVeh._speed = 10, 0, 10
    setHeading(hotVeh, 0)
    driveReset(hotVeh)
    driveTick(dp, hotVeh)
    local coastCap10 = captured.laneCurveEnvelope
    checkEq(captured.sensor.stamp, curveStamp,
        "10m approach remains on the same completed snapshot")
    checkEq(drive.calls.forceBrake, 0,
        "same-snapshot 10m approach remains soft coast only")
    hotVeh._x = 20
    driveReset(hotVeh)
    driveTick(dp, hotVeh)
    local coastCap20 = captured.laneCurveEnvelope
    checkEq(captured.sensor.stamp, curveStamp,
        "20m approach remains on the same completed snapshot")
    checkTrue(coastCap10 <= coastCap0 + 1e-9
            and coastCap20 <= coastCap10 + 1e-9 and coastCap20 < coastCap0,
        "same-snapshot effective lane cap monotonically drops toward the curve")
    checkEq(drive.calls.forceBrake, 0,
        "same-snapshot 20m approach never turns future curvature into hard brake")
    -- (lane-decel) 1002d：車道包絡的計畫減速度與剖面同一本帳（煞車×0.7 與斷油＋剖面輔助取大）；runtime
    --   縮放比對同一個式子——安全值沒變時不縮。違規證明：proof 端拿掉輔助＝第一條紅；runtime 只比
    --   煞車×0.7＝第二條紅（輕車的包絡無故縮兩成）。
    local planD = math.max(captured.horizonMinBrake * 0.7,
        captured.horizonMinCoast + (captured.profile.coastAssist or 0))
    checkNear(captured.laneEnvDecel, planD, 1e-9,
        "(lane-decel) 車道包絡計畫減速度＝max(煞車×0.7, 斷油＋輔助)（實得 " .. tostring(captured.laneEnvDecel) .. "）")
    checkNear(captured.laneEnvelopeScale, 1, 1e-12,
        "(lane-decel) 安全值沒變：runtime 縮放不縮（實得 " .. tostring(captured.laneEnvelopeScale) .. "）")
    local cachedEnvelopeSlot = captured.verifyEnvelope[1]
    local buildLat, buildCoast =
        captured.envelopeBuildLat, captured.envelopeBuildCoast
    local effectiveBeforeScale = captured.laneCurveEnvelope
    captured.yawLower, captured.yawConfidence, captured.yawTime =
        buildLat * 0.25, 1, 20
    captured.coastLower, captured.coastConfidence, captured.coastTime =
        buildCoast * 0.25, 1, 20
    captured.ewmaSuppressUntil = nowMs + 1000
    captured.nextDynamicsMs = nowMs + 10000
    driveReset(hotVeh)
    driveTick(dp, hotVeh)
    local scaledEnvelope = captured.laneCurveEnvelope
    checkNear(captured.verifyEnvelope[1], cachedEnvelopeSlot, 1e-12,
        "small EWMA tightening never rebuilds the 128-point cached envelope")
    checkTrue(captured.laneEnvelopeScale < 1 and scaledEnvelope < effectiveBeforeScale,
        "per-frame safeLat/safeCoast tightening applies conservative O(1) scale")
    local heldScale = captured.laneEnvelopeScale
    captured.yawLower, captured.yawConfidence = captured.priorLat, 1
    captured.coastLower, captured.coastConfidence = captured.priorCoast, 1
    driveReset(hotVeh)
    driveTick(dp, hotVeh)
    checkNear(captured.laneEnvelopeScale, heldScale, 1e-12,
        "same-snapshot safe increase never raises the cached envelope")
    checkTrue(captured.laneCurveEnvelope <= scaledEnvelope + 1e-9,
        "same-position effective cap remains conservative until a new snapshot")
    captured.ewmaSuppressUntil = 0

    local firstCurveSeg = nil
    for i = 1, captured.profile.n - 1 do
        if captured.profile.segKind[i] == MDADDynamics.SEG_ARC then
            firstCurveSeg = i
            break
        end
    end
    checkTrue(firstCurveSeg ~= nil, "v4 curve fixture exposes a current SEG_ARC")
    if firstCurveSeg then
    captured.fstate.idx = firstCurveSeg
    hotVeh._x = (captured.profile.x[firstCurveSeg]
        + captured.profile.x[firstCurveSeg + 1]) * 0.5
    hotVeh._y = (captured.profile.y[firstCurveSeg]
        + captured.profile.y[firstCurveSeg + 1]) * 0.5
    hotVeh._speed = 10
    setHeading(hotVeh, captured.profile.segH[firstCurveSeg])
    drive.scanRound(true)
    local currentCurveCap = captured.curveCap
    -- 2026-09-04 issue #2：致動器雜訊帶內（cap+1）不准叫引擎 1 秒鎖輪，走 regulator
    -- 斷油滑行；超過 hardBreachKmh（cap+5 > cap+max(3,6%)）才 forceBrake。
    -- （違規證明：把 Driver 的 hardBreachKmh 換回 cap+0.5 即紅）
    hotVeh._speed = currentCurveCap + 1
    driveReset(hotVeh)
    driveTick(dp, hotVeh)
    checkTrue(captured.curveHardActive and captured.curveKappa > 0,
        "inside actual-lane arc arms current hard curvature")
    checkEq(drive.calls.forceBrake, 0,
        "arc overspeed inside the actuator noise band (cap+1) does not forceBrake")
    checkEq(drive.calls.regulatorOn, 1,
        "arc overspeed inside the noise band keeps the regulator on with a lower target")
    checkEq(captured.lastHardBrakeReason, nil,
        "telemetry hbr stays empty inside the noise band")
    -- 0907f：cap+5（舊 hardBreach 門檻）也不再 forceBrake——彎中鎖輪＝stall（十三場 session
    -- 每個「整個停住才轉」都是它，`ib=true tn=0` 一秒）；regulator brake 15 連續減速 3.65 m/s²
    -- 不鎖輪即可。只有 cap×CURVE_BREACH_RATIO(1.5) 的離譜超速才留災難兜底。
    -- （違規證明：門檻換回 hardBreachKmh 即 cap+5 煞、紅）
    hotVeh._speed = currentCurveCap + 5
    driveReset(hotVeh)
    driveTick(dp, hotVeh)
    checkEq(drive.calls.forceBrake, 0,
        "current arc overspeed cap+5 no longer force-brakes (regulator brake only)")
    checkEq(captured.lastHardBrakeReason, nil, "telemetry hbr stays empty at cap+5")
    hotVeh._speed = currentCurveCap * 1.5 + 1
    driveReset(hotVeh)
    driveTick(dp, hotVeh)
    -- 1002a：災難兜底改不鎖輪（中線外力＋照常轉向），telemetry hbr 照樣點名、fbt 不亮（沒有鎖輪閂鎖）
    checkEq(drive.calls.forceBrake, 0,
        "current arc gross overspeed (cap×1.5+1) brakes without locking the wheels")
    checkEq(captured.lastHardBrakeReason, "curve",
        "telemetry hbr names the curve breach")
    checkTrue(captured.forceBrakeThis ~= true
            and math.abs((captured.visAssistDecel or 0) - MDAD.Drive.debugTune().TOW_BRAKE_DECEL) < 1e-9,
        "non-lock curve brake: fbt off, vad = TOW_BRAKE_DECEL (vad=" .. tostring(captured.visAssistDecel) .. ")")
    end
    MDAD.Drive.stop(0, nil)
    setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false,
        AutoDriveMaxSpeed = 40, RightLaneBias = 0 })
    drive.nav.route = v4Route("paved", 10)
    drive.nav.route.segWidth[39] = nil
    driveReset(hotVeh)
    checkFalse(MDAD.Drive.start(dp), "malformed v4 metadata fail-stops startup")
    checkEq(haloKey(), DKEY.ROUTE, "malformed v4 reports route unavailable")

    local zeroBrakeVeh = newVehicle({
        battery = newItem("Base.CarBattery", { uses = 0.8 }),
        engineRunning = true, mass = 1200, speed = 0, maxSpeed = 90,
        bodyW = 2.0, bodyL = 5.2, profileFull = true, brakingForce = 0,
    })
    dveh = zeroBrakeVeh
    zeroBrakeVeh._driver, dp._vehicle = dp, zeroBrakeVeh
    drive.nav.route = v4Route("paved", 10)
    driveReset(zeroBrakeVeh)
    checkFalse(MDAD.Drive.start(dp), "finite zero brakingForce rejects startup")
    checkEq(haloKey(), DKEY.UNSUPPORTED, "zero brakingForce reports unsupported vehicle")

    dveh = oldVeh
    oldVeh._driver, dp._vehicle = dp, oldVeh
    driveReset(oldVeh)
    checkTrue(MDAD.Drive.start(dp), "nil brakingForce keeps legacy conservative fallback")
    MDAD.Drive.stop(0, nil)

    dveh = hotVeh
    hotVeh._driver, dp._vehicle = dp, hotVeh
    hotVeh._x, hotVeh._y, hotVeh._speed = 0, 0, 20
    driveReset(hotVeh)
    checkTrue(MDAD.Drive.start(dp), "learned-zero brake fault fixture starts")
    for _ = 1, 4 do driveTick(dp, hotVeh) end
    drive.scanRound()
    captured.tractionKey = captured.currentSurfaceId
        + (captured.rain ~= false and 4 or 0)
        + (captured.physicalOffroad and 32 or 0)
    captured.kinPrevMs, captured.kinPrevV, captured.kinPrevH =
        nowMs - 100, hotVeh._speed / 3.6, 0
    captured.lastLatDev, captured.lastHeadingError = 0, 0
    captured.brakeMean, captured.brakeDev, captured.brakeTime = 0, 0, 20
    captured.brakeConfidence, captured.brakeLower = 1, 0
    captured.forceBrakeUntil, captured.ewmaSuppressUntil = 0, 0
    driveReset(hotVeh)
    driveTick(dp, hotVeh)
    checkFalse(MDAD.Drive.isActive(0), "learned uncontrollable brake bound visibly stops")
    checkEq(haloKey(), DKEY.UNSUPPORTED, "learned zero brake reports unsupported vehicle")
    checkTrue(drive.calls.forceBrake >= 1,
        "uncontrollable brake fault still attempts narrow best-effort forceBrake")
    local savedSensor, savedCorridor = MDADSensor, MDADCorridor
    dveh = hotVeh
    hotVeh._driver, dp._vehicle = dp, hotVeh
    hotVeh._x, hotVeh._y, hotVeh._speed = 0, 20, 20
    setHeading(hotVeh, 0)
    drive.nav.route = v4Route("paved", 10)
    MDADSensor = nil
    driveReset(hotVeh)
    checkTrue(MDAD.Drive.start(dp), "missing Sensor keeps M3 startup available")
    for _ = 1, 4 do driveTick(dp, hotVeh) end
    checkFalse(captured.returnActive, "missing Sensor never enters RETURN")
    checkEq(MDAD.Drive.controlState(0), "TRACK",
        "missing Sensor + large latDev stays pure follower, not RETURN/HOLD")
    MDAD.Drive.stop(0, nil)
    MDADSensor = savedSensor

    MDADCorridor = nil
    driveReset(hotVeh)
    checkTrue(MDAD.Drive.start(dp), "missing Corridor keeps M3 startup available")
    for _ = 1, 4 do driveTick(dp, hotVeh) end
    drive.scanRound(true)
    checkFalse(captured.returnActive, "missing Corridor never enters RETURN after a fresh snapshot")
    checkFalse(captured.blocked, "missing Corridor snapshot does not turn optional M4 into HOLD")
    checkEq(MDAD.Drive.controlState(0), "TRACK",
        "missing Corridor + large latDev stays pure follower, not RETURN/HOLD")
    MDAD.Drive.stop(0, nil)
    MDADCorridor = savedCorridor
    MDADOverlay.update = realOverlayUpdate
    MDAD.Drive.stop(0, nil)
    dveh = oldVeh
    oldVeh._driver, dp._vehicle = dp, oldVeh
    MDAD.Drive.setGear(0, oldGear)
    installNavApi(2)
    drive.nav.route = newRoute(40, 0, 0, 4, 0)
    drive.fillWorld(-2, 70, -7, 7)
end
scenarioPhaseE()

-- (kerb) 停留不受路面餘裕否決（2026-09-04 s004@0904n Quiet St 東向）：v4 路寬 6（餘裕
--        ±1.75），車 B 斜跨到南緣（y 0..−3）、回線段再撞後方 C（y −0.5）；唯一出路是北側
--        路緣外 lane +2.5（超出餘裕）。舊制 stayAllowed 以 `room` 拒絕 → blocked；新制
--        停留線掃掠過即承諾。違規證明：加回 room 閘即紅。
local function scenarioKerbStay()
    installNavApi(4)
    local oldVeh = dveh
    dveh = newVehicle({
        battery = newItem("Base.CarBattery", { uses = 0.8 }),
        engineRunning = true, mass = 1200, speed = 20, maxSpeed = 90,
        bodyW = 1.8, bodyL = 4.4, comX = 0, comZ = 0.4, profileFull = true,
        enginePower = 4000, brakingForce = 80, wheelFriction = 1.5, tireFriction = 1.5,
    })
    local route = newRoute(40, 0, 0, 4, 0)
    route.segSurface, route.segWidth = {}, {}
    for i = 1, 39 do route.segSurface[i], route.segWidth[i] = "paved", 6 end
    route.len, route.cost, route.avoidPenalty, route.approachSurface = 156, 156, 0, "unknown"
    drive.fillWorld(-10, 120, -9, 9)
    drive.putRoad(-10, 120, -3, 3)
    MDAD.Drive.stop(0, nil)
    dveh._x, dveh._y, dveh._speed, dveh._steering, dveh._stopped = 0, 0, 20, 0, false
    dveh._engine, dveh._driver = true, dp
    dveh._part._item._uses = 0.8
    dp._vehicle, dp._dead, dp._local = dveh, false, true
    setHeading(dveh, 0.3)
    drive.nav.tx, drive.nav.ty, drive.nav.state = 300, 0, "ok"
    drive.nav.route = route
    local okStart = MDAD.Drive.start(dp)
    for _ = 1, 2 do driveTick(dp, dveh) end
    driveReset(dveh)
    checkTrue(okStart and MDAD.Drive.isActive(0), "(kerb) 啟動")
    local st = MDAD.Drive.debugSession(0)
    local _, cB = drive.putVehicleGeom(22, -1.2, 0.35, 1.8, 4.4, true) -- 斜跨南半到中線
    local _, cC = drive.putVehicleGeom(44, -0.5, 0, 1.8, 4.4, true)   -- 回線段撞它
    for x = 14, 60 do drive.putSolid(x, -6, "harness_kerb_s_" .. x) end -- 南緣外圍籬
    for x = 14, 60 do drive.putSolid(x, 5, "harness_kerb_n_" .. x) end  -- 北側人行道外圍籬（lane ≤ ~3.3 可用）
    driveReset(dveh)
    drive.scanRound()
    checkTrue(type(st.profile.laneRoomR) == "table" and st.profile.laneRoomR[5] < 2,
        "(kerb) fixture：路面餘裕表存在且 <2（實得 " .. tostring(st.profile.laneRoomR and st.profile.laneRoomR[5]) .. "）")
    checkEq(haloKey(), DKEY.DODGE, "(kerb) 北側路緣外 lane 停留承諾＝Dodge（實得 " .. tostring(haloKey()) .. "）")
    checkTrue(st.dodgeStay == true, "(kerb) 是停留承諾（tier " .. tostring(st.dodgeTier) .. "）")
    checkTrue(type(st.fstate.offL) == "number" and st.fstate.offL > 1.75,
        "(kerb) 停留 lane 超出路面餘裕 ±1.75（實得 " .. tostring(st.fstate.offL) .. "）")
    drive.clearVehicleGeom(cB); drive.clearVehicleGeom(cC)
    for x = 14, 60 do drive.clearCell(x, -6); drive.clearCell(x, 5) end
    MDAD.Drive.stop(0, nil)
    dveh = oldVeh
    oldVeh._driver, dp._vehicle = dp, oldVeh
    installNavApi(2)
    drive.nav.route = newRoute(40, 0, 0, 4, 0)
    drive.fillWorld(-2, 70, -7, 7)
end
scenarioKerbStay()

-- (lane) 窄路常駐 lane 的證明鏈不得整段 band（2026-09-06 session-055：w=4／w=5 住宅街、
--        laneBias 1.5、車寬 1.31：舊制 clampLane 夾到 room 邊 0.944，profile 點對 raw 段的距離與
--        erode 是同一個數的兩條浮點路徑，26 秒 verifyLineReason=band → gateReason=obb → 18 km/h）。
--        路線斜 7°（軸對齊的 sin/cos 精確、翻不了車）。違規證明：LANE_BIAS_KEEP 改 0 ＋
--        rawBandContains 的 1mm 容忍拿掉即紅（單獨拿掉一個各有 test_follower／test_dynamics 鎖）。
local function scenarioNarrowLaneProof()
    installNavApi(4)
    local oldVeh = dveh
    dveh = newVehicle({
        battery = newItem("Base.CarBattery", { uses = 0.8 }),
        engineRunning = true, mass = 1000, speed = 20, maxSpeed = 120,
        bodyW = 1.31, bodyL = 3.24, comX = 0, comZ = 0.4, profileFull = true, -- session-055 RaceCar58
        enginePower = 4000, brakingForce = 80, wheelFriction = 1.5, tireFriction = 1.5,
    })
    setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false,
        AutoDriveMaxSpeed = 40, RightLaneBias = 1.5 })
    drive.fillWorld(-10, 170, -30, 40)
    drive.putRoad(-10, 170, -30, 40)
    local h = math.rad(7)
    for _, w in ipairs({ 4, 5 }) do
        local tag = "(lane w=" .. w .. ") "
        local route = newRoute(40, 0, 0, 4 * math.cos(h), 4 * math.sin(h))
        route.segSurface, route.segWidth = {}, {}
        for i = 1, 39 do route.segSurface[i], route.segWidth[i] = "paved", w end
        route.len, route.cost, route.avoidPenalty, route.approachSurface = 156, 156, 0, "unknown"
        MDAD.Drive.stop(0, nil)
        dveh._x, dveh._y, dveh._speed, dveh._steering, dveh._stopped = 0, 0, 20, 0, false
        dveh._engine, dveh._driver = true, dp
        dveh._part._item._uses = 0.8
        dp._vehicle, dp._dead, dp._local = dveh, false, true
        setHeading(dveh, h)
        drive.nav.tx, drive.nav.ty = 300 * math.cos(h), 300 * math.sin(h)
        drive.nav.state, drive.nav.route = "ok", route
        checkTrue(MDAD.Drive.start(dp), tag .. "啟動")
        for _ = 1, 2 do driveTick(dp, dveh) end
        driveReset(dveh)
        local st = MDAD.Drive.debugSession(0)
        local room = w * 0.5 - st.vehicleProfile.halfW - MDADDynamics.ROAD_EDGE_MARGIN
        local want = room - MDADFollower.LANE_BIAS_KEEP
        if want < 0 then want = 0 end
        local lane = MDADFollower.laneBiasAt(st.profile, 1.5, 1)
        checkNear(lane, want, 1e-9, tag .. "常駐 lane 1.5 落點＝room−keep（room "
            .. tostring(room) .. " 實得 " .. tostring(lane) .. "）")
        -- 車擺在夾後 lane 上、車頭沿線：對中的證明鏈只剩帶檢查與世界掃掠
        dveh._x = 8 * math.cos(h) - math.sin(h) * lane
        dveh._y = 8 * math.sin(h) + math.cos(h) * lane
        driveTick(dp, dveh)
        drive.scanRound()
        st.alignSince = nowMs - 1000
        st.progressState, st.progressSince = "watch", nowMs
        st.cmdV, st.cmdA, st.cmdInitialized = 40 / 3.6, 0, true
        st.startGuard = false -- 已過起步近物保護（真的上路會在貼線對正 1 秒後解除）
        driveReset(dveh)
        driveTick(dp, dveh)
        checkEq(st.verifyLineReason, "ok", tag .. "空直路 proof 線不得 band（實得 "
            .. tostring(st.verifyLineReason) .. "）")
        checkEq(st.gateReason, "clear", tag .. "gate clear（實得 " .. tostring(st.gateReason) .. "）")
        checkTrue(st.fullGate == true, tag .. "fullGate 開")
        -- (acc) 1001i 整合：閘門開、實速 20 對更高的目標——加速輔助補中線前推（這台 1200 kg 低於前推質量門檻，
        -- 前推輔助只給重車低速）。違規證明：ACCEL_ASSIST_MPS2＝0 即紅。
        checkTrue(st.accelAssist > 0 and dveh._imp.x * dveh._fwdX + dveh._imp.z * dveh._fwdY > 0,
            tag .. "(acc) 閘門開直路加速：補中線前推（實得 a=" .. tostring(st.accelAssist)
            .. " sg=" .. tostring(st.startGuard) .. "）")
    end
    -- (lane 0) 折點格的解析式 0（κ→∞ 假象）不得變成 fullGate 路徑的 target 0（2026-09-08 s048：
    --   調頭完成、對準的那幀 fullGate 開 → laneCurveEnvelope 0 → target 0、reason nil → min-exec
    --   的 curve-coast 分支不認、GO 意圖 0 釘死 37 秒）。兩層：① verifyEnvelope 夾 MIN_SPEED；
    --   ② 就算 envelope 真的 0（scale 0），GO+0 抬 MIN_EXEC 且 minExecFrom 記 curve-coast。
    do
        local st = MDAD.Drive.debugSession(0) -- w=5 session 仍活著、fullGate 開
        local realCap = MDADDynamics.curveSpeedCapKmh
        MDADDynamics.curveSpeedCapKmh = function() return 0 end
        drive.scanRound()
        MDADDynamics.curveSpeedCapKmh = realCap
        checkTrue((st.verifyEnvelope[1] or 0) >= MDADFollower.MIN_SPEED_KMH - 1e-9,
            "(lane 0) 解析式全 0：verifyEnvelope 夾到 MIN_SPEED（實得 " .. tostring(st.verifyEnvelope[1]) .. "）")
        st.laneEnvelopeScale = 0 -- envelope 真的 0
        driveReset(dveh)
        driveTick(dp, dveh)
        checkTrue(st.fullGate == true, "(lane 0) fullGate 仍開（實得 " .. tostring(st.fullGate) .. " gate=" .. tostring(st.gateReason) .. "）")
        checkTrue(drive.calls.maxRegSpeed >= MDADDynamics.MIN_EXEC_KMH,
            "(lane 0) fullGate 下 envelope 0：目標抬到 MIN_EXEC（實得 " .. tostring(drive.calls.maxRegSpeed) .. "）")
        checkEq(st.lastCapReason, "min-exec", "(lane 0) capReason min-exec")
        checkEq(st.minExecFrom, "curve-coast", "(lane 0) 被抬前的理由記 curve-coast（telemetry 定罪用）")
        st.laneEnvelopeScale = 1
        drive.scanRound()
    end
    -- (lane zom) 有 laneRoom 的路上，殭屍軟縫的提案帶＝Follower 對 laneBias 真的會照辦的帶
    --   （room−keep）：control／proof 線對任何 laneBias 都用同一個 clampLane，帶給到物理餘裕
    --   的提案會被靜默夾回＝telemetry「有閃」但車沒動。違規證明：帶退回物理餘裕即紅。
    do
        local st = MDAD.Drive.debugSession(0) -- w=5 session 仍活著；車在 s=8、lane 0.845
        local zs, zl = 22, -0.5
        local zx, zy = zs * math.cos(h) - math.sin(h) * zl, zs * math.sin(h) + math.cos(h) * zl
        local cx, cy = math.floor(zx), math.floor(zy)
        drive.putMoving(cx, cy, { _class = "IsoZombie",
            getX = function() return zx end, getY = function() return zy end })
        for _ = 1, 8 do drive.scanRound() end
        checkTrue(st.sensor.zomN == 1, "(lane zom) Sensor 記到 1 隻殭屍（實得 " .. tostring(st.sensor.zomN) .. "）")
        checkTrue(st.zombieLane == nil and st.fstate.laneBias == st.residentBias,
            "(lane shoulder) 殭屍未侵入實際常駐線：不得因帶邊夾限假換道")
        drive.clearCell(cx, cy)
        zl = 0.8 -- 改成真正佔到行駛線，左侧有可行縫。
        zx, zy = zs * math.cos(h) - math.sin(h) * zl, zs * math.sin(h) + math.cos(h) * zl
        cx, cy = math.floor(zx), math.floor(zy)
        drive.putMoving(cx, cy, { _class = "IsoZombie",
            getX = function() return zx end, getY = function() return zy end })
        local tx, ty = 30, 6 -- 7°路線的格量化位置；右側硬物不可否決左移。
        drive.putTree(tx, ty, "harness_zombie_right_kerb")
        for _ = 1, 8 do drive.scanRound() end
        local lb = st.fstate.laneBias
        local eff = MDADFollower.laneBiasAt(st.profile, lb, st.fstate.idx)
        checkTrue(st.zombieLane ~= nil, "(lane zom) 軟縫啟動（laneBias " .. tostring(lb) .. "）")
        checkTrue(math.abs(eff - lb) < 0.05,
            "(lane zom) 提案 lane 被 Follower 照辦（提案 " .. tostring(lb) .. " 生效 " .. tostring(eff) .. "）")
        drive.clearCell(cx, cy)
        drive.clearCell(tx, ty)
    end
    -- 彎前混合已讓實際行駛線收向內側；不能用未混合的1.5m判殭屍在路肩。
    do
        MDAD.Drive.stop(0, nil)
        drive.fillWorld(-10, 120, -20, 100)
        drive.putRoad(-10, 120, -20, 100)
        drive.nav.route = { pts = { 0, 0, 60, 0, 60, 60 },
            segSurface = { "paved", "paved" }, segWidth = { 9.14, 9.14 } }
        dveh._x, dveh._y, dveh._speed = 0, 1.5, 20
        setHeading(dveh, 0)
        checkTrue(MDAD.Drive.start(dp), "(z-curve) 真弧路線啟動")
        for _ = 1, 8 do driveTick(dp, dveh) end
        local st = MDAD.Drive.debugSession(0)
        local arcS
        for i = 1, st.profile.n - 1 do
            if st.profile.segKind[i] == MDADDynamics.SEG_ARC then arcS = st.profile.s[i]; break end
        end
        local zs, zl = arcS - 2, -0.5
        dveh._x = arcS - 15
        driveTick(dp, dveh)
        local cx = math.floor(zs)
        drive.putMoving(cx, -1, { _class = "IsoZombie",
            getX = function() return zs end, getY = function() return zl end })
        for _ = 1, 18 do
            drive.scanRound()
            dveh._y = MDADFollower.laneBiasAt(st.profile, st.fstate.laneBias,
                st.fstate.idx, st.lastSNow)
        end
        local effective = MDADFollower.laneBiasAt(st.profile, st.fstate.laneBias,
            MDADFollower.segIndexAt(st.profile, zs), zs)
        checkTrue(effective < zl - st.vehicleProfile.halfW
                - MDADCorridor.ZOMBIE_R - MDADCorridor.ZOMBIE_MARGIN + 0.05,
            "(z-curve) 彎前右側提案會被夾回殭屍處：改走真正可用的左縫")
        drive.clearCell(cx, -1)
    end
    -- (kink-small) 1002t：極小角度（< MDADFollower.TURN_GEOM_MIN_RAD＝10°）未圓角折點，證明線外接圓 κ 改用純追跡弦半徑
    --   （Follower geometryStep 同一個弦），車道包絡不再在路網量化抖動前急煞。違規證明：拿掉替換＝8° 紅。
    --   1002u：10–20° 改建小弧（切角 ≤ FILLET_SMALL_CUT_M），證明線走弧＝κ≈1/R，不再照外接圓量成 R≈4m（舊制 15° 實得
    --   κ≈0.2、車道包絡 20 km/h 級）。違規證明：FILLET_SMALL_RAD 拉回 20°（不建小弧）＝15° 紅。
    for _, deg in ipairs({ 8, 15 }) do
        MDAD.Drive.stop(0, nil)
        drive.fillWorld(-10, 160, -20, 60)
        drive.putRoad(-10, 160, -20, 60)
        local th = math.rad(deg)
        drive.nav.route = { pts = { 0, 0, 60, 0, 60 + 80 * math.cos(th), 80 * math.sin(th) },
            segSurface = { "paved", "paved" }, segWidth = { 9.14, 9.14 } }
        dveh._x, dveh._y, dveh._speed = 20, 1.5, 40
        setHeading(dveh, 0)
        checkTrue(MDAD.Drive.start(dp), "(kink-small) " .. deg .. "° 小折點路線啟動")
        for _ = 1, 8 do driveTick(dp, dveh) end
        for _ = 1, 4 do drive.scanRound() end
        local st = MDAD.Drive.debugSession(0)
        local p, v = st.profile, nil
        for i = 2, p.n - 1 do
            if math.abs(p.s[i] - 60) < 1.5 then v = i end
        end
        local kmax, envAt = 0, nil
        for k = 1, (st.verifyLineN or 0) do
            local sk = st.laneCurveS0 + (k - 1) * MDADFollower.OV_STEP
            if math.abs(sk - 60) <= 2 then
                if st.verifyKappa[k] > kmax then kmax = st.verifyKappa[k] end
                local e = st.verifyEnvelope[k]
                if envAt == nil or e < envAt then envAt = e end
            end
        end
        if deg < 10 then
            checkTrue(v ~= nil and p.segKind[v - 1] == MDADDynamics.SEG_LINE and p.segKind[v] == MDADDynamics.SEG_LINE,
                "(kink-small) 8° 頂點沒做圓角（LINE 段）")
            checkTrue(envAt ~= nil and kmax < 0.05,
                "(kink-small) 8° 頂點附近 κ 用前視弦半徑（實得 " .. tostring(kmax) .. "；外接圓約 0.23）")
            checkTrue(v ~= nil and envAt ~= nil and envAt >= p.curveV[v] * 3.6 - 1,
                "(kink-small) 8° 車道包絡不低於 Follower 頂點速（包絡 " .. tostring(envAt) .. "、頂點 "
                .. tostring(v and p.curveV[v] * 3.6) .. "）")
        else
            -- 切角＝R·(1/cos(θ/2)−1)：上限 0.6m → R≈69.5m（臂長 60m 的 45%＝27m 對應 205m，切角先綁）
            local arcN, rMax = 0, 0
            for i = 1, p.n - 1 do
                if p.segKind[i] == MDADDynamics.SEG_ARC then
                    arcN = arcN + 1
                    if p.filletRadius[i] > rMax then rMax = p.filletRadius[i] end
                end
            end
            local cut = rMax * (1 / math.cos(th * 0.5) - 1)
            checkTrue(arcN > 0 and cut <= MDADDynamics.FILLET_SMALL_CUT_M + 1e-6 and cut > MDADDynamics.FILLET_SMALL_CUT_M - 0.05,
                "(kink-small) 15° 建小弧、切角貼上限（弧段 " .. arcN .. "、R " .. string.format("%.1f", rMax)
                .. "、切角 " .. string.format("%.2f", cut) .. "m）")
            checkTrue(envAt ~= nil and kmax < 0.03 and envAt > 60,
                "(kink-small) 15° 證明線走弧：κ " .. tostring(kmax) .. " < 0.03、車道包絡 " .. tostring(envAt)
                .. " > 60（舊制外接圓 κ≈0.2）")
        end
    end
    -- (kink-short) 1002u：10–20° 但建不出小弧（臂太短：15°＋17° 兩折點只隔 0.5m，切點要的 R≈1.6m 小於 rMin 1.85）＝留 LINE 頂點，
    --   證明線照外接圓（E2E rc56b 0008：18.4° 未圓角頂點以前視弦放行、72 km/h 外漂 1.65m）。
    --   違規證明：Drive.smallKinkKappa 門檻放回 FILLET_MIN_RAD（20°）＝紅。
    do
        MDAD.Drive.stop(0, nil)
        drive.fillWorld(-10, 160, -20, 60)
        drive.putRoad(-10, 160, -20, 60)
        local a1, a2 = math.rad(15), math.rad(32)
        local x1, y1 = 60 + 0.5 * math.cos(a1), 0.5 * math.sin(a1)
        drive.nav.route = { pts = { 0, 0, 60, 0, x1, y1, x1 + 80 * math.cos(a2), y1 + 80 * math.sin(a2) },
            segSurface = { "paved", "paved", "paved" }, segWidth = { 9.14, 9.14, 9.14 } }
        dveh._x, dveh._y, dveh._speed = 20, 1.5, 40
        setHeading(dveh, 0)
        checkTrue(MDAD.Drive.start(dp), "(kink-short) 短臂雙小折點路線啟動")
        for _ = 1, 8 do driveTick(dp, dveh) end
        for _ = 1, 4 do drive.scanRound() end
        local st = MDAD.Drive.debugSession(0)
        local p, lineOnly = st.profile, true
        for i = 1, p.n - 1 do
            if p.s[i] > 50 and p.s[i] < 70 and p.segKind[i] ~= MDADDynamics.SEG_LINE then lineOnly = false end
        end
        local kmax = 0
        for k = 1, (st.verifyLineN or 0) do
            local sk = st.laneCurveS0 + (k - 1) * MDADFollower.OV_STEP
            if math.abs(sk - 60.5) <= 2 and st.verifyKappa[k] > kmax then kmax = st.verifyKappa[k] end
        end
        checkTrue(lineOnly, "(kink-short) 臂太短：兩個小折點都留 LINE（不建弧、不標 fallback）")
        checkTrue(kmax > 0.15, "(kink-short) 未圓角小折點照外接圓 κ（實得 " .. tostring(kmax) .. "）")
    end
    -- (yield-proof) 0924a 正式服兩趟：讓位中 Sensor 不跑，proof 停在讓位前那輪；玩家開過證明線尾，
    --   恢復首幀 currentS > laneCurveEnd → lane-envelope → UnsupportedVehicle 交還。
    --   違規證明：拿掉讓位恢復處的 Drive.clearLaneProof 即紅。
    do
        MDAD.Drive.stop(0, nil)
        local route = newRoute(40, 0, 0, 4 * math.cos(h), 4 * math.sin(h))
        route.segSurface, route.segWidth = {}, {}
        for i = 1, 39 do route.segSurface[i], route.segWidth[i] = "paved", 5 end
        route.len, route.cost, route.avoidPenalty, route.approachSurface = 156, 156, 0, "unknown"
        dveh._x, dveh._y, dveh._speed, dveh._steering, dveh._stopped = 0, 0, 20, 0, false
        setHeading(dveh, h)
        drive.nav.state, drive.nav.route = "ok", route
        checkTrue(MDAD.Drive.start(dp), "(yield-proof) 啟動")
        for _ = 1, 2 do driveTick(dp, dveh) end
        local st = MDAD.Drive.debugSession(0)
        local lane = MDADFollower.laneBiasAt(st.profile, 1.5, 1)
        dveh._x = 8 * math.cos(h) - math.sin(h) * lane
        dveh._y = 8 * math.sin(h) + math.cos(h) * lane
        driveTick(dp, dveh)
        drive.scanRound()
        checkTrue(st.laneCurveStamp == st.sensor.stamp and st.laneCurveEnd > st.lastSNow,
            "(yield-proof) 讓位前 proof 有效、線尾在車前（end " .. tostring(st.laneCurveEnd) .. "）")
        local oldHud = MDAD.HUD
        MDAD.HUD = { manualResumeMs = function() return 2000 end }
        dveh._steering = 0.02
        driveTick(dp, dveh)
        checkEq(st.mode, "yield", "(yield-proof) 轉方向盤＝讓位")
        local s2 = st.laneCurveEnd + 10 -- 玩家自己開過證明線尾
        dveh._x = s2 * math.cos(h) - math.sin(h) * lane
        dveh._y = s2 * math.sin(h) + math.cos(h) * lane
        driveTick(dp, dveh)
        dveh._steering = 0
        driveTick(dp, dveh)
        nowMs = nowMs + 2001
        driveReset(dveh)
        driveTick(dp, dveh)
        checkTrue(MDAD.Drive.isActive(0), "(yield-proof) 恢復首幀不交還 UnsupportedVehicle")
        checkTrue(st.stateError ~= "lane-envelope", "(yield-proof) 恢復不記 lane-envelope")
        MDAD.HUD = oldHud
    end
    -- (yield-wait) 2026-10-01 正式服 0.16.0：判堵停等中讓位，玩家接手 17 秒後放手；恢復首個停等幀把讓位時間
    --   一次補進停等預算（waitTickMs 停在讓位前）＝超過 15 秒上限即 StopStuck，同一幀又拿讓位前的舊快照算
    --   可視硬煞。恢復時舊 episode／判堵作廢、感知重掃。
    --   違規證明：拿掉恢復處的 clearEpisode＝第一行紅；拿掉恢復處的 MDADSensor.reset＝第二行紅。
    do
        MDAD.Drive.stop(0, nil)
        local route = newRoute(40, 0, 0, 4 * math.cos(h), 4 * math.sin(h))
        route.segSurface, route.segWidth = {}, {}
        for i = 1, 39 do route.segSurface[i], route.segWidth[i] = "paved", 5 end
        route.len, route.cost, route.avoidPenalty, route.approachSurface = 156, 156, 0, "unknown"
        dveh._x, dveh._y, dveh._speed, dveh._steering, dveh._stopped = 0, 0, 20, 0, false
        setHeading(dveh, h)
        drive.nav.state, drive.nav.route = "ok", route
        checkTrue(MDAD.Drive.start(dp), "(yield-wait) 啟動")
        for _ = 1, 2 do driveTick(dp, dveh) end
        local st = MDAD.Drive.debugSession(0)
        local lane = MDADFollower.laneBiasAt(st.profile, 1.5, 1)
        dveh._x = 8 * math.cos(h) - math.sin(h) * lane
        dveh._y = 8 * math.sin(h) + math.cos(h) * lane
        driveTick(dp, dveh)
        drive.scanRound()
        -- 讓位前：判堵停等已累計 4 秒、計時進行中；那一輪快照的前緣在 s=60（恢復時玩家已開到它附近）
        st.blocked, st.waitAccumMs, st.waitTickMs = true, 4000, nowMs
        st.waitAnchorS, st.waitAnchorLat, st.waitAnchorErr = st.lastSNow, 0, 0
        st.sensor.scanEndS = 60
        local oldHud = MDAD.HUD
        MDAD.HUD = { manualResumeMs = function() return 2000 end }
        dveh._steering = 0.02
        driveTick(dp, dveh)
        checkEq(st.mode, "yield", "(yield-wait) 轉方向盤＝讓位")
        -- 玩家接手 17 秒：往前開 60m、停在常駐線外 2.6m（正式服：開走 57m、恢復時進 RETURN，停等進度只看橫向收斂）
        nowMs = nowMs + 17000
        dveh._x = 68 * math.cos(h) - math.sin(h) * (lane + 2.6)
        dveh._y = 68 * math.sin(h) + math.cos(h) * (lane + 2.6)
        driveTick(dp, dveh)
        dveh._steering = 0
        driveTick(dp, dveh)
        nowMs = nowMs + 2001
        driveReset(dveh)
        dveh._speed = 25
        driveTick(dp, dveh)
        checkTrue(MDAD.Drive.isActive(0) and st.waitAccumMs < 1000,
            "(yield-wait) 恢復首幀不把讓位時間算進停等（累計 " .. tostring(st.waitAccumMs) .. " ms）")
        checkEq(drive.calls.forceBrake, 0,
            "(yield-wait) 恢復首幀不拿讓位前的舊快照硬煞（why " .. tostring(st.forceBrakeWhy) .. "）")
        MDAD.HUD = oldHud
    end
    MDAD.Drive.stop(0, nil)
    dveh = oldVeh
    oldVeh._driver, dp._vehicle = dp, oldVeh
    setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false,
        AutoDriveMaxSpeed = 40, RightLaneBias = 0 })
    installNavApi(2)
    drive.nav.tx, drive.nav.ty, drive.nav.state = 300, 0, "ok"
    drive.nav.route = newRoute(40, 0, 0, 4, 0)
    drive.fillWorld(-2, 70, -7, 7)
end
scenarioNarrowLaneProof()

-- (κwin) 繞行曲率只量兩段過渡 [a,b]／[c,d]，且從車尾起量（0906i；session-055 彎道旁一根桿子的
--        tight 繞行把整條 20-50m 線壓 15：保持段是路線平移，弧段的內側偏移由 Follower.control
--        的 κ/(1−lt·κ) 管）。保持段裡**非弧折點**（v3 原始折角／v4 fallback）偏移後的實線彎沒人管
--        → 只量它 ±3m 鄰域（review lane 反例：30m 臂 90° 原折點、offL 2）。
--        違規證明：進入段窗口上界改 d（＝含保持段）、量測起點退回線頭、拿掉折點鄰域，各自紅。
local function scenarioDodgeKappaWindow()
    local xs, ys, n = {}, {}, 31
    for i = 1, n do xs[i], ys[i] = i - 1, 0 end -- s0=0、OV_STEP=1：s=i−1
    ys[4], ys[13], ys[21] = 0.3, 1.0, 0.15    -- 進入段 s=3、保持段 s=12（最大）、出口段 s=20
    local a, b, c, d = 1, 6, 18, 24
    local K = MDADDynamics.polylineKappaMax
    local kEntry, kHold, kExit = K(xs, ys, n, 2, 7), K(xs, ys, n, 12, 14), K(xs, ys, n, 19, 25)
    checkTrue(kHold > kEntry and kEntry > kExit and kExit > 0,
        "(κwin) fixture：保持段折角最大、出口段最小（" .. kHold .. " > " .. kEntry .. " > " .. kExit .. "）")
    local hook = MDAD.Drive.debugLineKappa
    checkNear(hook(nil, xs, ys, n, 0, -5, a, b, c, d), kEntry, 1e-12,
        "(κwin) 車尾在線頭前（無 profile）：κ＝max(進入段, 出口段)，保持段的大折角不計")
    checkNear(hook(nil, xs, ys, n, 0, 8, a, b, c, d), kExit, 1e-12,
        "(κwin) 車尾越過 offB：只剩出口段")
    checkNear(hook(nil, xs, ys, n, 0, 2.5, a, b, c, d), kEntry, 1e-12,
        "(κwin) 車尾在進入段折角前 0.5m：折角頂點仍算")
    local kResid = K(xs, ys, n, 4, 7) -- 頂點（vertex 4）在車下、鄰點 5 的殘餘折角
    checkTrue(kResid < kEntry and kResid > 0, "(κwin) fixture：頂點後的鄰點殘餘 < 頂點折角")
    checkNear(hook(nil, xs, ys, n, 0, 3.5, a, b, c, d), math.max(kResid, kExit), 1e-12,
        "(κwin) 車尾越過折角頂點 0.5m：頂點已在車下不計，只剩鄰點殘餘與出口段")
    checkNear(hook(nil, xs, ys, n, 0, -5, nil, b, c, d), kHold, 1e-12,
        "(κwin) 缺剖面參數保守退整線（含保持段）")
    -- 上界含 b 本身、不含之後的頂點：b=6 整數時 last＝頂點 s=6（圓周 κ 會吃到 s=7 這個鄰點，
    -- 所以尖角放在 s=8：舊的 floor+2 上界會量到 s=7 頂點＝紅）
    do
        local ys2 = {}
        for i = 1, n do ys2[i] = ys[i] end
        ys2[9] = 2.0 -- s=8＝保持段第二個頂點
        checkNear(hook(nil, xs, ys2, n, 0, -5, a, b, c, d), kEntry, 1e-12,
            "(κwin) b 恰在頂點上：b 之後的折角屬保持段不計（ceil 上界）")
    end
    -- 保持段的非弧折點：假 profile 在 s=12 有 90° 原始折角（LINE／LINE）→ 鄰域照量＝kHold；
    -- 同一頂點若是弧段（ARC）→ 交給 control 的內側修正，不量；落在弧上的過渡窗也不量
    -- （弧 κ 會透過鄰點進到整條線的常駐帽＝從 a 前 20m 就壓 15：0907 T 字路口探針）
    local function fakeProf(kind, turn, kind2)
        return { ready = true, n = 3, s = { 0, 12, 30 }, segH = { 0, turn or math.pi / 2 },
            segKind = { kind, kind2 or kind } }
    end
    checkNear(hook(fakeProf(MDADDynamics.SEG_LINE), xs, ys, n, 0, -5, a, b, c, d), kHold, 1e-12,
        "(κwin) 保持段原始 90° 折點：±3m 鄰域的實線 κ 照量")
    checkNear(hook(fakeProf(MDADDynamics.SEG_FALLBACK), xs, ys, n, 0, -5, a, b, c, d), kHold, 1e-12,
        "(κwin) 保持段 fallback 折點同樣照量")
    checkNear(hook(fakeProf(MDADDynamics.SEG_LINE, nil, MDADDynamics.SEG_ARC), xs, ys, n, 0, -5, a, b, c, d), kEntry, 1e-12,
        "(κwin) 折點一側是弧段：保持段折角不計、出口窗落在弧上也不量（內側偏移由 control 硬帽管）→ 只剩進入段")
    -- 0907b（Codex lane）：過渡窗與弧**實質重疊**（≥2 步）要量合成曲率（基弧＋側移）——Follower 的
    -- κ/(1−lt·κ) 只對固定偏移成立、spaceCap 只算直路 S 彎；整條線在弧上＝兩窗都量＝max(進入, 出口)
    checkNear(hook(fakeProf(MDADDynamics.SEG_ARC), xs, ys, n, 0, -5, a, b, c, d), kEntry, 1e-12,
        "(κwin) 整條線都在弧上：過渡窗照量合成曲率（保持段折角仍不計）")
    do
        -- 真 v4 剖面（R≈12 圓角）＋真 buildOffsetLine：2m 側移整段落在弧內 → 合成 κ 高於基弧 κ
        -- 與直路同側移的 κ 兩者；側移落在弧前直路（b 在弧起點前 3m）→ 只量直路 S 彎、弧 κ 不漏進來
        local F = MDADFollower
        local R = 12
        local w = 2 * (R * (1 - math.cos(math.pi / 4)) + 0.656 + 0.4)
        local route = { pts = { 0, -40, 0, 0, 40, 0 }, segSurface = { "paved", "paved" }, segWidth = { w, w } }
        local vp = { valid = true, geometryValid = true, halfW = 0.656, rMin = 2.26, wheelbase = 1.985,
            delta0Safe = 0.72, deltaVSafe = 0.24, maxSpeed = 120 }
        local pArc = F.begin(route, 120, 4, vp)
        while not pArc.ready do F.stepBuild(pArc, 4096) end
        local arcI, arcE
        for i = 1, pArc.n - 1 do
            if pArc.segKind[i] == MDADDynamics.SEG_ARC then arcI = arcI or i; arcE = i end
        end
        local sA, sE = pArc.s[arcI], pArc.s[arcE + 1]
        local kArc = pArc.kappa[arcI + 2]
        checkTrue(arcI ~= nil and sE - sA > 14 and kArc > 0.07 and kArc < 0.1,
            "(κwin) 真弧 fixture：弧長 >14m、κ≈0.083（實得 " .. tostring(kArc) .. "）")
        local ox, oy = {}, {}
        local dl = 2
        -- 側移在弧內：a=弧起+3、b=a+8（全在弧內）、c=b+2、d 在弧尾
        local a2, b2 = sA + 3, sA + 11
        local c2, d2 = b2 + 2, sE
        local nIn, s0In = F.buildOffsetLine(pArc, sA - 6, a2, b2, c2, d2, dl, 0, ox, oy)
        checkTrue(nIn > 10, "(κwin) 弧內側移線建好（點數 " .. tostring(nIn) .. "）")
        local kIn = hook(pArc, ox, oy, nIn, s0In, sA - 6, a2, b2, c2, d2)
        -- 同側移在直路：a 放在 −30..−22（弧前直臂上）
        local ox2, oy2 = {}, {}
        local aS, bS = sA - 30, sA - 22
        local nSt, s0St = F.buildOffsetLine(pArc, sA - 36, aS, bS, bS + 2, sA - 3, dl, 0, ox2, oy2)
        local kSt = hook(pArc, ox2, oy2, nSt, s0St, sA - 36, aS, bS, bS + 2, sA - 3)
        checkTrue(kSt > 0.1 and kSt < 0.2,
            "(κwin) 直路 2m/8m 側移的 S 彎 κ≈0.14（實得 " .. tostring(kSt) .. "）")
        checkTrue(kIn > kArc + 0.03 and kIn > kSt + 0.03,
            "(κwin) 弧內同側移：合成 κ 高於基弧 κ 與直路 S 彎 κ（實得 " .. tostring(kIn)
            .. " vs 弧 " .. tostring(kArc) .. "／直路 " .. tostring(kSt) .. "）")
        -- 出口窗 [c,d] 只碰到弧起點（d=弧起+1 ＜ 2 步）→ 不量弧：κ 不得吃到基弧
        local ox3, oy3 = {}, {}
        local nT, s0T = F.buildOffsetLine(pArc, sA - 36, aS, bS, sA - 9, sA + 1, dl, 0, ox3, oy3)
        local kT = hook(pArc, ox3, oy3, nT, s0T, sA - 36, aS, bS, sA - 9, sA + 1)
        checkTrue(kT < kIn - 0.03,
            "(κwin) 回線窗只碰到弧起點（重疊 1 步）：不量弧、無合成 κ（實得 " .. tostring(kT) .. "）")
    end
    -- 弧邊界退 OV_BLEND：進入窗 [1,12] 的線段在 s<12 是 LINE，弧從 12 起；尖角放在 s=11（弧前
    -- 1m＝法向混合區）→ 不得計入（弧起點側退 3 頂點：s=10 的圓周 κ 會用到 s=11 當鄰點）；放在 s=9 則照量
    do
        local ys3 = {}
        for i = 1, n do ys3[i] = 0 end
        ys3[12] = 0.5 -- s=11
        checkNear(hook(fakeProf(MDADDynamics.SEG_LINE, 0.001, MDADDynamics.SEG_ARC), xs, ys3, n, 0, -5, 1, 12, 20, 26), 0, 1e-12,
            "(κwin) 弧前 2m 內的頂點屬法向混合區：不計")
        ys3[12], ys3[10] = 0, 0.5 -- s=9
        checkTrue(hook(fakeProf(MDADDynamics.SEG_LINE, 0.001, MDADDynamics.SEG_ARC), xs, ys3, n, 0, -5, 1, 12, 20, 26) > 0.3,
            "(κwin) 弧前 3m 的頂點照量")
    end
    -- 起始段（車位→a）的 raw 折點也要量：shapeProfile 的 entryPeak 會把 a 放到折點之後。
    -- 同一條線把剖面改成 a=16（折點 s=12 落在 a 之前）→ 仍＝kHold；只搜 [b,c] 的舊制＝紅
    checkNear(hook(fakeProf(MDADDynamics.SEG_LINE), xs, ys, n, 0, -5, 16, 19, 22, 26), kHold, 1e-12,
        "(κwin) 起始段（a 之前）的原始折點：鄰域照量")
    checkNear(hook(fakeProf(MDADDynamics.SEG_LINE), xs, ys, n, 0, 16, a, b, c, d), kExit, 1e-12,
        "(κwin) 車尾越過保持段折點 4m：不再計")
    local kAfter = hook(fakeProf(MDADDynamics.SEG_LINE), xs, ys, n, 0, 12.5, a, b, c, d)
    checkTrue(kAfter > kExit and kAfter < kHold,
        "(κwin) 車尾剛越過折點頂點 0.5m：頂點在車下不計、鄰點殘餘仍算（候選要從 lo−reach 找；實得 "
        .. tostring(kAfter) .. "）")
    checkNear(hook(fakeProf(MDADDynamics.SEG_LINE, 0.01), xs, ys, n, 0, -5, a, b, c, d), kEntry, 1e-12,
        "(κwin) 保持段 0.6° 共線點（cell 邊界預切）不算折點")
end
scenarioDodgeKappaWindow()

-- =====================================================================
-- 情境（bridge）：橋面三層疊格（水面 sprite 最底、路面地板蓋在上面）不是水
-- =====================================================================
local function scenarioBridge()
scenario("橋面：水面 sprite 上有實地板＝可通行；純水面才是硬障礙")
    -- 2026-09-04 使用者截圖：(2275,8794) 物件 street／blends_natural_02_3（water）／industry_01_39，
    -- getFloor() 拿到載入最底層的水面 → 整排橋中線硬障礙、兩個方向都過不了橋。
    drive.fillWorld(-2, 70, -7, 7)
    drive.putRoad(-2, 70, -3, 3)
    -- 橋中線一排（x=20，帶內全寬）：水面在 index 0、路面地板疊在後面（模擬載入順序）
    for y = -7, 7 do
        local sq = drive.world[20 * 100000 + y]
        -- 實機 (2274,8795)：blends_natural_02_7（solidfloor＋solidtrans＋water）＋ industry_01_39
        -- （橋板：solidfloor，無 water、無碰撞）——沒有 blends_street，路面統計不認它也無妨
        sq._floor = drive.floorObj("blends_natural_02_7", true)
        sq._objs[#sq._objs + 1] = drive.floorObj("industry_01_39", false)
    end
    checkTrue(armDrive(), "(bridge) 啟動")
    driveReset(dveh)
    drive.scanRound()
    checkEq(MDAD.Drive.debugSession(0).sensor.hardN, 0, "(bridge) 水上有路面地板：零硬障礙（實得 " .. tostring(MDAD.Drive.debugSession(0).sensor.hardN) .. "）")
    checkTrue(haloKey() ~= DKEY.BLOCKED, "(bridge) 不 blocked（實得 " .. tostring(haloKey()) .. "）")
    -- 對照：同一排改成純水面（沒有地板蓋）＝硬障礙、blocked
    for y = -7, 7 do
        local sq = drive.world[20 * 100000 + y]
        sq._objs = {}
        sq._objList = nil
        drive.mkSquare(20, y)
        drive.world[20 * 100000 + y]._floor = drive.floorObj("blends_natural_02_3", true)
    end
    driveReset(dveh)
    drive.scanRound()
    checkTrue(MDAD.Drive.debugSession(0).sensor.hardN > 0, "(bridge) 純水面：硬障礙（實得 " .. tostring(MDAD.Drive.debugSession(0).sensor.hardN) .. "）")
    MDAD.Drive.stop(0, nil)
    drive.fillWorld(-2, 70, -7, 7)
end
scenarioBridge()
-- =====================================================================
-- 情境（gate）0928m：關著的門／柵門是車輛碰撞牆（IsoChunk.calcPhysics：DoorWall＋door 且沒有 open）
-- E2E rc13 0190：車頂著關著的鐵絲網柵門 0 km/h、每輪掃描淨空（門類 sprite 一律當開口）。
-- 違規證明：closedDoor 一律回 false＝(gate) 關著這行紅。
-- =====================================================================
function drive.scenarioGate()
scenario("關著的柵門＝硬障礙、停下；開著的柵門照常通過")
    drive.fillWorld(-2, 70, -7, 7)
    drive.putRoad(-2, 70, -3, 3)
    for y = -7, 7 do drive.putGate(20, y, false, false) end
    checkTrue(armDrive(), "(gate) 啟動")
    driveReset(dveh)
    drive.scanRound()
    local hn = MDAD.Drive.debugSession(0).sensor.hardN
    checkTrue(hn > 0, "(gate) 關著：柵門整排是硬障礙（hardN=" .. tostring(hn) .. "）")
    checkEq(haloKey(), DKEY.BLOCKED, "(gate) 關著而且整排擋住：停下 blocked")
    MDAD.Drive.stop(0, nil)
    drive.fillWorld(-2, 70, -7, 7)
    drive.putRoad(-2, 70, -3, 3)
    for y = -7, 7 do drive.putGate(20, y, false, true) end
    checkTrue(armDrive(), "(gate) 開著 啟動")
    driveReset(dveh)
    drive.scanRound()
    checkEq(MDAD.Drive.debugSession(0).sensor.hardN, 0, "(gate) 開著：不是障礙")
    checkTrue(haloKey() ~= DKEY.BLOCKED, "(gate) 開著：不 blocked")
    MDAD.Drive.stop(0, nil)
    drive.fillWorld(-2, 70, -7, 7)
end
drive.scenarioGate()

-- =====================================================================
-- 0908a：調頭＋blocked（s030）、短帶倒車（s026）
-- =====================================================================
local function scenarioUturnBlocked()
scenario("調頭＋blocked：遠處不倒車、近處才退、額度用盡不空轉、ROTATE 計停等預算；短帶倒車")
    -- s030 定罪：目標在後、路線前方 20m 車群（blocked 錨在車尾方向 20m 外）——舊制
    -- 一律 uturn-blocked 倒車＝朝障礙退三次、額度用盡後每幀 requestRecover→attempt-limit
    -- 事件洪水（4889 筆／20 秒），ROTATE 意圖不計停等預算＝掛到手動停。
    local savedTelemetry = MDAD.HUD.telemetryEnabled
    MDAD.HUD.telemetryEnabled = function() return true end -- 事件計數要 s.diag
    -- 情境自帶 Diagnostics 樁（前面情境的樁可能已還原成真檔案 IO → s.diag=false）
    local savedStart, savedEvent, savedSample, savedStop =
        MDADDiagnostics.start, MDADDiagnostics.event, MDADDiagnostics.sample, MDADDiagnostics.stop
    local evs = { n = 0 }
    MDADDiagnostics.start = function() return true end
    MDADDiagnostics.sample = function() return true end
    MDADDiagnostics.stop = function() return true end
    MDADDiagnostics.event = function(pn, name, a)
        evs.n = evs.n + 1
        if type(a) == "table" then evs[name .. ":" .. tostring(a.phase)] = a end
    end
    local function stuckWorld(wallX)
        for _, y in ipairs({ -5, -4, -2, -1, 0, 1, 2, 4, 5 }) do
            drive.putSolid(wallX, y, "u_wall_" .. y)
        end
    end
    local function clearWorld(wallX)
        for _, y in ipairs({ -5, -4, -2, -1, 0, 1, 2, 4, 5 }) do drive.clearCell(wallX, y) end
    end
    local function reversedStart(label)
        evs["progress:recover"], evs["unstick:start"] = nil, nil
        checkTrue(armDrive(), label .. " 啟動")
        dveh._x, dveh._y, dveh._speed = 0, 0, 0
        setHeading(dveh, 2.8) -- 反向 160°＝調頭姿態
        driveReset(dveh)
        driveTick(dp, dveh)
        drive.scanRound(true)
        driveTick(dp, dveh)
        return MDAD.Drive.debugSession(0)
    end
    -- (u1) 車群在路線前方 20m（車尾方向）：blocked 但不倒車，調頭照跑
    stuckWorld(20)
    local st = reversedStart("(u1)")
    checkTrue(st.fstate.rotating == true, "(u1) 反向車頭＝調頭姿態")
    checkTrue(st.blocked == true, "(u1) 路線前方 20m 車群＝blocked（實得 " .. tostring(st.blocked) .. "）")
    for _ = 1, 8 do driveTick(dp, dveh) end
    checkEq(st.mode, "follow", "(u1) 20m 外的 blocked 不倒車（mode 實得 " .. tostring(st.mode) .. "）")
    checkTrue(evs["progress:recover"] == nil, "(u1) 沒有 uturn-blocked 恢復請求")
    checkTrue(MDAD.Drive.isActive(0), "(u1) session 活著、調頭意圖持有")
    -- (u3) ROTATE 也計停等預算：原地不轉（harness 車不自轉）16 秒 → StopStuck 交還，
    --      不再永久掛著
    nowMs = nowMs + 8000
    driveTick(dp, dveh)
    checkTrue(MDAD.Drive.isActive(0), "(u3) ROTATE 8 秒仍在預算內")
    nowMs = nowMs + 8000
    driveTick(dp, dveh)
    checkFalse(MDAD.Drive.isActive(0), "(u3) ROTATE 原地 16 秒：超時交還（舊制永久掛著）")
    local stuckHalo = false
    for i = 1, #halos do if haloKey(i) == DKEY.STUCK then stuckHalo = true end end
    checkTrue(stuckHalo, "(u3) 交還理由 StopStuck（同幀先有 Blocked 紅字）")
    clearWorld(20)
    -- (u2) 車群貼在旋轉圈內（錨 4.5m ≤ probeR+1）：才走倒車創造空間。牆面在車尾後 1.8m：
    --      4m／2m 帶命中、最短帶 1.5（MIN+KEEP）清 → 退 1.0
    stuckWorld(4)
    st = reversedStart("(u2)")
    checkTrue(st.blocked == true, "(u2) 4m 車群＝blocked")
    checkEq(st.mode, "unstick", "(u2) 旋轉圈內的 blocked：倒車創造空間（mode 實得 " .. tostring(st.mode) .. "）")
    checkEq((evs["progress:recover"] or {}).why, "uturn-blocked", "(u2) 恢復理由 uturn-blocked")
    checkNear((evs["unstick:start"] or {}).len or -1, 1.5, 1e-9,
        "(u2) 4m／2m 帶命中、最短帶清：短帶倒車（len 實得 "
        .. tostring((evs["unstick:start"] or {}).len) .. "）")
    checkNear(st.unstickTravelM, 1.0, 1e-9, "(u2) 本次退距上限＝帶長−KEEP＝1.0")
    -- (u4) 額度用盡（attempt-limit）後不再每幀重打：事件數不隨幀數增長
    MDAD.Drive.stop(0, nil)
    stuckWorld(4)
    st = reversedStart("(u4)")
    -- 第一次 uturn-blocked 已起步倒車；模擬「三次都沒解掉」：額度歸滿、回 follow 再問一次
    st.mode, st.episodeAttempts, st.progressState = "follow", 3, "disarmed"
    st.blockRetryDone = false
    driveTick(dp, dveh)
    local n0 = evs.n
    for _ = 1, 20 do driveTick(dp, dveh) end
    checkTrue(evs.n - n0 <= 2,
        "(u4) 額度用盡後 20 幀不再逐幀 attempt-limit（事件增量實得 " .. tostring(evs.n - n0) .. "）")
    checkTrue(MDAD.Drive.isActive(0), "(u4) 額度用盡仍在停等預算內（15s 保險另計）")
    clearWorld(4)
    -- (rot-stall) 0928b E2E replay：車頭朝路線反方向、車頭前 2m 有牆（走廊沿路線往車尾方向掃、看不到），
    --   車周探測被擋＝走大弧前進，但車根本動不了。連續 ROTATE_STALL_MS 不動＝倒車創造空間。
    --   違規證明：Drive.rotateStall 恆 false＝原地乾等到停等預算紅。
    MDAD.Drive.stop(0, nil)
    for _, y in ipairs({ -1, 0, 1, 2 }) do drive.putSolid(-3, y, "rot_front_" .. y) end
    st = reversedStart("(rot-stall)")
    checkTrue(st.fstate.rotating == true and st.rotProbeClear == false,
        "(rot-stall) 前置：調頭姿態、車周探測被擋（rotProbeClear=" .. tostring(st.rotProbeClear) .. "）")
    checkEq(st.mode, "follow", "(rot-stall) 剛開始不倒車")
    nowMs = nowMs + 1500
    driveTick(dp, dveh)
    checkEq(st.mode, "follow", "(rot-stall) 1.5 秒內不倒車")
    nowMs = nowMs + 1500
    driveTick(dp, dveh)
    driveTick(dp, dveh)
    checkEq(st.mode, "unstick", "(rot-stall) 走大弧卻 3 秒不動：倒車創造空間（mode 實得 " .. tostring(st.mode) .. "）")
    checkEq((evs["progress:recover"] or {}).why, "rotate-stall", "(rot-stall) 恢復理由 rotate-stall")
    for _, y in ipairs({ -1, 0, 1, 2 }) do drive.clearCell(-3, y) end
    MDAD.Drive.stop(0, nil)
    MDAD.Drive.stop(0, nil)
    MDAD.HUD.telemetryEnabled = savedTelemetry
    MDADDiagnostics.start, MDADDiagnostics.event, MDADDiagnostics.sample, MDADDiagnostics.stop =
        savedStart, savedEvent, savedSample, savedStop
    -- (c4b) 一般（非調頭）blocked 停等到期的倒車：後牆在車尾後 4m（4m 帶命中）＝舊制一寸不退
    --       回停等、15 秒 StopStuck；現制 2m 帶清 → 退 1.5m 進 settle 重掃
    checkTrue(armDrive(), "(c4b) 啟動")
    for _, y in ipairs({ -5, -4, -2, -1, 0, 1, 2, 4, 5 }) do
        drive.putSolid(20, y, "harness_wall_" .. y)
    end
    for _, y in ipairs({ -1, 0, 1 }) do drive.putSolid(4, y, "harness_rearwall_" .. y) end
    dveh._x = 11
    driveTick(dp, dveh)
    drive.scanRound()
    checkEq(haloKey(), DKEY.BLOCKED, "(c4b) 堵死紅字")
    dveh._speed = 0
    driveReset(dveh)
    driveTick(dp, dveh)
    drive.wideRounds(true) -- 寬帶判堵到最寬一級
    nowMs = nowMs + 6000
    driveTick(dp, dveh)
    st = MDAD.Drive.debugSession(0)
    checkEq(MDAD.Drive.hudState(0), "unstick", "(c4b) 後牆 4m：短帶倒車（實得 " .. tostring(MDAD.Drive.hudState(0)) .. "）")
    checkNear(st.unstickTravelM, 1.5, 1e-9, "(c4b) 退距上限 1.5m")
    -- 中途（退 0.5m、100ms 後重探）：重探帶＝剩餘 1.0＋KEEP 0.5＝1.5m 淨空（4m 帶會命中後牆）
    -- → 仍在 unstick、本幀有倒車衝量（Codex lane：沒有這一幀，帶長公式沒被走到）
    dveh._x = 10.5
    dveh._speed = -3
    nowMs = nowMs + 150
    driveReset(dveh)
    driveTick(dp, dveh)
    checkEq(st.mode, "unstick", "(c4b) 退 0.5m 重探（短帶淨空）：仍在倒車（實得 " .. tostring(st.mode) .. "）")
    checkTrue(dveh._imp.total >= 1 and st.reverseForce > 0, "(c4b) 重探淨空幀施倒車衝量")
    -- (rev-cap) 倒車限速：已經以 12 km/h 倒退（> UNSTICK_REVERSE_KMH 10）＝本幀不再施倒車衝量，滑回上限
    --   以下再推。違規證明：拿掉限速＝12 km/h 仍施力紅。
    dveh._speed = -12
    nowMs = nowMs + 20
    driveReset(dveh)
    driveTick(dp, dveh)
    checkEq(st.mode, "unstick", "(rev-cap) 前置：仍在倒車")
    checkTrue(dveh._imp.total == 0 and st.reverseForce == 0,
        "(rev-cap) 倒退已超過 10 km/h：不再施倒車衝量（衝量 " .. tostring(dveh._imp.total) .. "）")
    -- (ext-align) steep／貼縫的加長倒車只在車頭大致沿路線時才有意義；斜 72°（正式服 c25：垂直停在路旁）
    --   倒 11m 只換到 3m 跑道、其餘往路外橫移 → 不加長。違規證明：拿掉對齊條件＝72° 仍加 5m 紅。
    local fx = { blocked = true, blockSteepM = 5, lastRouteErr = 0.1, episodeReason = "blocked", episodeAttempts = 1 }
    checkNear(MDAD.Drive.unstickExtraM(fx), 5, 1e-9, "(ext-align) 車頭沿路線：steep 差額照加 5m")
    fx.lastRouteErr = 1.25
    checkEq(MDAD.Drive.unstickExtraM(fx), 0, "(ext-align) 車頭斜 72°：不加長倒車")
    -- 退 1.5m：達標進 settle
    dveh._x = 9.5
    dveh._speed = -5
    nowMs = nowMs + 400
    driveReset(dveh)
    driveTick(dp, dveh)
    checkEq(st.mode, "settle", "(c4b) 退滿 1.5m 進 settle（實得 " .. tostring(st.mode) .. "）")
    checkTrue(MDAD.Drive.isActive(0), "(c4b) 不交還")
    for _, y in ipairs({ -5, -4, -2, -1, 0, 1, 2, 4, 5 }) do drive.clearCell(20, y) end
    for _, y in ipairs({ -1, 0, 1 }) do drive.clearCell(4, y) end
    MDAD.Drive.stop(0, nil)
end
scenarioUturnBlocked()

-- 弧段自適應前饋的 Driver 接線（0908a）：applySteering 把夾限／死區後真的施出去的 steer 回寫
-- fstate.appliedSteer（Follower 的 yaw 增益估計分母）；不施力的幀歸 0（滑行中的 yaw 不歸功
-- 給沒施出去的 steer）；telemetry phys 帶 ffSteer。
local function scenarioAppliedSteer()
scenario("弧段前饋接線：applySteering 回寫 appliedSteer、煞停幀歸 0、telemetry 帶 ffSteer")
    checkTrue(armDrive(), "(ff) 啟動")
    driveReset(dveh)
    driveTick(dp, dveh) -- 車頭偏 0.3 rad：每幀真的施力
    local st = MDAD.Drive.debugSession(0)
    checkTrue(dveh._imp.total >= 1, "(ff) 本幀施了轉向力")
    checkTrue(type(st.fstate.appliedSteer) == "number" and st.fstate.appliedSteer ~= 0,
        "(ff) applySteering 回寫非零 appliedSteer（實得 " .. tostring(st.fstate.appliedSteer) .. "）")
    checkTrue(math.abs(st.fstate.appliedSteer) <= 5, "(ff) 回寫值已夾限 ±5")
    checkTrue(type(st.fstate.yawGain) == "number" and st.fstate.yawGain >= 0.2 and st.fstate.yawGain <= 3,
        "(ff) yaw 增益估計在夾限內（實得 " .. tostring(st.fstate.yawGain) .. "）")
    -- 車身接觸（forceBrake 幀）：不施力 → appliedSteer 0
    drive.putSolid(2, 0, "harness_ff_contact")
    driveReset(dveh)
    drive.scanRound()
    driveTick(dp, dveh)
    checkTrue(st.currentBlocked == true or drive.calls.forceBrake > 0, "(ff) 車頭接觸：煞停幀")
    checkEq(st.fstate.appliedSteer, 0, "(ff) 煞停幀 appliedSteer 歸 0（實得 " .. tostring(st.fstate.appliedSteer) .. "）")
    drive.clearCell(2, 0)
    MDAD.Drive.stop(0, nil)
end
scenarioAppliedSteer()

-- =====================================================================
-- 情境二十九：理由鍵不得缺翻譯（鍵是 runtime 真的吐出來的，不是抄原始碼）
-- =====================================================================
local function scenarioDriveClock()
    scenario("行車計時：成功啟動歸零、等待照計、結束凍結、失敗啟動保留")
    checkTrue(armDrive(), "計時情境啟動")
    local started = nowMs
    checkEq(select(7, MDAD.Drive.hudState(0)), 0, "新行程從零秒開始")
    nowMs = started + 1999
    checkEq(select(7, MDAD.Drive.hudState(0)), 1, "按現實經過秒數取整，不按 tick 次數")
    MDAD.Drive.start(dp)
    checkEq(select(7, MDAD.Drive.hudState(0)), 1, "重複啟動既有行程不歸零")
    nowMs = started + 5400
    MDAD.Drive.stop(0, nil)
    nowMs = nowMs + 4000
    checkEq(MDAD.Drive.hudState(0), nil, "結束後仍是 inactive")
    checkEq(select(7, MDAD.Drive.hudState(0)), 5, "結束後時間凍結，不再繼續增加")
    checkEq(select(7, MDAD.Drive.hudState(9)), nil, "沒有行程的其他玩家槽不借用末趟時間")
    dveh._engine = false
    checkFalse(MDAD.Drive.start(dp), "熄火時啟動失敗")
    checkEq(select(7, MDAD.Drive.hudState(0)), 5, "失敗啟動不蓋掉上一趟時間")
    dveh._engine = true
    checkTrue(MDAD.Drive.start(dp), "下一趟成功啟動")
    checkEq(select(7, MDAD.Drive.hudState(0)), 0, "下一趟取代末趟時間並歸零")
    nowMs = nowMs + 3500
    MDAD.Drive.stop(0, nil)
end
scenarioDriveClock()

function drive.scenarioPauseBoundaries()
    scenario("受困／抵達暫停：獨立選項、停妥與語音順序、取消等待及單人界線")
    local oldClient, oldServer, oldPlayers = clientFlag, serverFlag, activePlayers
    local oldGetter, oldVoice, oldLoaded = getSpecificPlayer, MDAD.Voice, loaded.MDAD_Voice
    local oldResume, oldPaused, oldPauseVehicle = drive.resumeMs, drive.paused, drive.pauseVehicle
    local oldPauseCalls, oldHadSession, oldHadRegulator =
        drive.pauseCalls, drive.pauseHadSession, drive.pauseHadRegulator
    local oldTicks = eventHandlers.OnTickEvenPaused
    local oldNav, oldKeys = drive.nav, drive.keys
    local oldUses = dveh._part._item._uses
    local saved = {
        { object = MDAD.HUD, keys = { "pauseOnStuck", "pauseOnArrival", "voiceEnabled", "voiceVolume", "voiceLanguage" } },
        { object = dp },
        { object = dveh },
    }
    for _, entry in ipairs(saved) do
        entry.values = {}
        if entry.keys then
            for _, key in ipairs(entry.keys) do entry.values[key] = entry.object[key] end
        else
            for key, value in pairs(entry.object) do entry.values[key] = value end
        end
    end
    drive.nav, drive.keys, eventHandlers.OnTickEvenPaused = {}, {}, {}
    for key, value in pairs(oldNav) do drive.nav[key] = value end
    for i, fn in ipairs(oldTicks or {}) do eventHandlers.OnTickEvenPaused[i] = fn end
    local tickBaseline = #(oldTicks or {})
    local currentPlayer = dp
    getSpecificPlayer = function(pn) if pn == 0 then return currentPlayer end end
    local options = {}
    MDAD.HUD.pauseOnStuck = function() return options.stuck end
    MDAD.HUD.pauseOnArrival = function() return options.arrive end
    MDAD.HUD.voiceEnabled = function() return options.enabled end
    MDAD.HUD.voiceVolume = function() return options.volume end
    MDAD.HUD.voiceLanguage = function() return "en" end
    local emitter = { nextRef = 0, sounds = {} }
    function emitter:playSoundImpl(name)
        self.nextRef = self.nextRef + 1
        self.sounds[self.nextRef] = {
            name = name, state = "queued",
            hadSession = MDAD.Drive.isActive(0), hadRegulator = dveh._regulator,
        }
        return self.nextRef
    end
    function emitter:isPlaying(ref)
        if self.queryError then error("emitter query unavailable") end
        local sound = self.sounds[ref]
        return sound ~= nil and (sound.state == "queued" or sound.state == "playing")
    end
    function emitter:stopSound(ref)
        if self.sounds[ref] then self.sounds[ref].state = nil end
    end
    function emitter:setVolume(ref, volume) self.sounds[ref].volume = volume end
    dp.getEmitter = function() return emitter end
    MDAD.Voice, loaded.MDAD_Voice = nil, nil
    require "MDAD_Voice"
    local realVoice = MDAD.Voice
    local function tick(ms)
        nowMs = nowMs + ms
        fire("OnTickEvenPaused")
    end
    local function begin()
        clientFlag, serverFlag, activePlayers = false, false, 1
        currentPlayer, MDAD.Voice = dp, realVoice
        options.stuck, options.arrive, options.enabled, options.volume = true, true, true, 70
        emitter.sounds, emitter.queryError = {}, false
        drive.keys.Forward, drive.resumeMs, drive.paused = nil, oldResume, false
        nowMs = nowMs + 9000 -- 跨過同句冷卻，不把上一案例的拒播誤認成即時 fallback。
        checkTrue(armDrive(), "(pause) 啟動獨立 session")
        drive.pauseCalls, drive.pauseVehicle = 0, dveh
    end
    local function notify(event)
        if event == "handback" then
            MDAD.Drive.stop(0, DKEY.STUCK)
        else
            MDAD.Drive.debugSession(0).mode = "arrive"
            dveh._speed, dveh._stopped = 0, true
            driveTick(dp, dveh)
        end
    end
    local function finishSound()
        emitter:stopSound(emitter.nextRef)
        tick(150)
    end

    -- Voice 關閉時仍必須尊重兩個獨立選項；MP／server／分割畫面都不能暫停世界。
    for _, event in ipairs({ "handback", "arrive" }) do
        for _, case in ipairs({
            { label = "純單人兩項開啟", own = true, other = true, pause = true },
            { label = "只關閉本事件", own = false, other = true, pause = false },
            { label = "只開啟本事件", own = true, other = false, pause = true },
            { label = "MP／Host", own = true, other = true, client = true, pause = false },
            { label = "伺服器", own = true, other = true, server = true, pause = false },
            { label = "本機分割畫面", own = true, other = true, players = 2, pause = false },
        }) do
            begin()
            options.enabled = false
            if event == "handback" then options.stuck, options.arrive = case.own, case.other
            else options.stuck, options.arrive = case.other, case.own end
            clientFlag, serverFlag, activePlayers = case.client == true, case.server == true, case.players or 1
            notify(event)
            local label = "(pause) " .. event .. "／" .. case.label
            checkEq(isGamePaused(), case.pause, label .. "：無語音時直接遵守暫停選項")
            checkEq(drive.pauseCalls, case.pause and 1 or 0, label .. "：只作必要的原生暫停")
            checkFalse(MDAD.Drive.isActive(0) or dveh._regulator, label .. "：先交還控制權")
            tick(11000)
            checkEq(drive.pauseCalls, case.pause and 1 or 0, label .. "：沒有延後補暫停")
        end
    end

    for _, event in ipairs({ "handback", "arrive" }) do
        begin()
        local label = "(voice-pause) " .. event
        if event == "arrive" then
            MDAD.Drive.debugSession(0).mode = "arrive"
            dveh._speed, dveh._stopped = 5, false
            local before = emitter.nextRef
            driveTick(dp, dveh)
            checkTrue(MDAD.Drive.isActive(0), label .. "：尚未停妥必須保留收尾 session")
            checkFalse(isGamePaused(), label .. "：煞停途中不暫停")
            checkEq(emitter.nextRef, before, label .. "：煞停途中不先播到站語音")
            checkTrue(haloKey() ~= DKEY.ARRIVED, label .. "：煞停途中不先顯示到站")
            dveh._speed = 0 -- 速度數字為零仍不等於原生 isStopped。
            driveTick(dp, dveh)
            checkTrue(MDAD.Drive.isActive(0), label .. "：速度零但 isStopped=false 仍等待停妥")
        end
        dveh._regulator = true -- 證明收尾真的關閉定速，不能靠 fixture 原本就是 false。
        notify(event)
        local sound = emitter.sounds[emitter.nextRef]
        checkEq(sound.name, realVoice.soundName(event), label .. "：真 Voice 已把對應通知排入 emitter")
        checkFalse(sound.hadSession or sound.hadRegulator, label .. "：送語音前已交還 session 與定速")
        checkFalse(MDAD.Drive.isActive(0) or dveh._regulator, label .. "：等候語音期間不持有車輛")
        checkTrue(MDAD.Drive.isPausePending(), label .. "：HUD 可辨識通知仍持有待暫停狀態")
        tick(150)
        checkFalse(isGamePaused(), label .. "：native ref 還在排隊時不暫停")
        sound.state = "playing"
        tick(6500)
        checkFalse(isGamePaused(), label .. "：已開始播放但尚未播完仍不暫停")
        sound.state = nil
        tick(150)
        checkTrue(isGamePaused(), label .. "：同一句完整播完才暫停")
        checkEq(drive.pauseCalls, 1, label .. "：完成只暫停一次")
        checkFalse(drive.pauseHadSession or drive.pauseHadRegulator, label .. "：暫停不復活控制權")
        checkEq(#eventHandlers.OnTickEvenPaused, tickBaseline, label .. "：完成後卸除等待事件")
        checkFalse(MDAD.Drive.isPausePending(), label .. "：播完後 HUD 恢復一般試聽")
        drive.paused = false
        tick(11000)
        driveTick(dp, dveh)
        checkFalse(isGamePaused() or MDAD.Drive.isActive(0) or dveh._regulator,
            label .. "：玩家恢復後沒有 late pause，也不自動重啟或供油")
        checkEq(drive.pauseCalls, 1, label .. "：後續 tick 不重寫恢復速度")
    end

    for _, previewPlaying in ipairs({ true, false }) do
        begin()
        checkTrue(realVoice.play("arrive", 0), "(preview) 行駛中調音量試聽到站句")
        local previewRef = emitter.nextRef
        if not previewPlaying then emitter:stopSound(previewRef) end
        notify("arrive")
        check(emitter.nextRef ~= previewRef, "(preview) 正式抵達另播完整通知，不借用試聽或被冷卻擋住")
        tick(150)
        checkFalse(isGamePaused(), "(preview) 正式通知尚未播完，不因試聽而立即暫停")
        finishSound()
        checkTrue(isGamePaused(), "(preview) 正式通知完整播完才暫停")
    end

    for _, event in ipairs({ "handback", "arrive" }) do
        begin()
        drive.paused = true
        notify(event)
        finishSound()
        checkTrue(isGamePaused(), "(pause) " .. event .. "：已暫停就維持，不自動播放世界")
        checkEq(drive.pauseCalls, 0, "(pause) " .. event .. "：不重寫原版暫停前的恢復速度")
    end
    MDAD.Drive.stop(0, DKEY.STUCK)
    checkEq(drive.pauseCalls, 0, "(pause) 重複 stop 不再有副作用")

    -- 取消必須是永久撤銷：先觸發一次取消檢查，再恢復環境、跨過 10 秒，不能晚到暫停。
    for _, kind in ipairs({
        "restart", "steering", "keyboard", "menu", "dead", "player", "exit",
        "option", "client", "server", "split", "paused", "replaced",
    }) do
        begin()
        notify("arrive")
        tick(150)
        checkFalse(isGamePaused(), "(cancel) " .. kind .. "：先確實進入語音等待")
        if kind == "restart" then checkTrue(MDAD.Drive.start(dp), "(cancel) 玩家主動重啟")
        elseif kind == "steering" then dveh._steering = 0.02
        elseif kind == "keyboard" then drive.keys.Forward = true
        elseif kind == "menu" then fire("OnMainMenuEnter")
        elseif kind == "dead" then dp._dead = true
        elseif kind == "player" then currentPlayer = pc1
        elseif kind == "exit" then dp._vehicle = nil
        elseif kind == "option" then options.arrive = false
        elseif kind == "client" then clientFlag = true
        elseif kind == "server" then serverFlag = true
        elseif kind == "split" then activePlayers = 2
        elseif kind == "paused" then drive.paused = true
        elseif kind == "replaced" then
            checkTrue(realVoice.play("blocked", 0), "(cancel) 外部新句取代到站通知")
        end
        tick(150)
        checkEq(drive.pauseCalls, 0, "(cancel) " .. kind .. "：取消時不改寫世界速度")
        checkEq(#eventHandlers.OnTickEvenPaused, tickBaseline, "(cancel) " .. kind .. "：卸除等待事件")
        currentPlayer, dp._dead, dp._vehicle = dp, false, dveh
        dveh._steering, drive.keys.Forward = 0, nil
        options.arrive, clientFlag, serverFlag, activePlayers, drive.paused = true, false, false, 1, false
        finishSound()
        tick(11000)
        checkFalse(isGamePaused(), "(cancel) " .. kind .. "：環境恢復／新句播完也不補暫停")
        if kind == "restart" then
            checkTrue(MDAD.Drive.isActive(0), "(cancel) 舊通知不會關閉新行程")
        else
            checkFalse(MDAD.Drive.isActive(0), "(cancel) " .. kind .. "：不復活舊行程")
        end
    end

    begin()
    notify("handback")
    tick(9900)
    checkFalse(isGamePaused(), "(timeout) 壞 emitter 未滿十秒仍等待")
    tick(200)
    checkTrue(isGamePaused(), "(timeout) emitter 永遠說排隊中：十秒保險結束等待")
    checkEq(drive.pauseCalls, 1, "(timeout) 保險只暫停一次")
    checkEq(#eventHandlers.OnTickEvenPaused, tickBaseline, "(timeout) 保險也卸除事件")

    begin()
    notify("arrive")
    emitter.queryError = true
    tick(150)
    checkTrue(isGamePaused(), "(fallback) 真 Voice 的 native 查詢拋錯按播放失敗暫停")
    begin()
    MDAD.Voice = nil
    notify("arrive")
    checkTrue(isGamePaused(), "(fallback) Voice 模組缺席也立即暫停")

    begin()
    MDAD.Drive.stop(0, nil)
    checkFalse(isGamePaused(), "(pause) 玩家手動關閉不暫停")
    begin()
    drive.resumeMs, dveh._steering = 0, 0.02
    driveTick(dp, dveh)
    check(not MDAD.Drive.isActive(0) and not isGamePaused(), "(pause) 玩家直接接手不暫停")
    begin()
    drive.resumeMs, dveh._steering = 2000, 0.02
    driveTick(dp, dveh)
    check(MDAD.Drive.hudState(0) == "yield" and not isGamePaused(), "(pause) 暫時讓位不暫停")
    begin()
    dveh._engine = false
    driveTick(dp, dveh)
    check(not MDAD.Drive.isActive(0) and not isGamePaused(), "(pause) 熄火停用不暫停")

    MDAD.Drive.stop(0, nil)
    for _, entry in ipairs(saved) do
        if entry.keys then
            for _, key in ipairs(entry.keys) do entry.object[key] = entry.values[key] end
        else
            for key in pairs(entry.object) do entry.object[key] = nil end
            for key, value in pairs(entry.values) do entry.object[key] = value end
        end
    end
    dveh._part._item._uses = oldUses
    MDAD.Voice, loaded.MDAD_Voice, getSpecificPlayer = oldVoice, oldLoaded, oldGetter
    eventHandlers.OnTickEvenPaused, drive.nav, drive.keys = oldTicks, oldNav, oldKeys
    clientFlag, serverFlag, activePlayers = oldClient, oldServer, oldPlayers
    drive.resumeMs, drive.paused, drive.pauseVehicle = oldResume, oldPaused, oldPauseVehicle
    drive.pauseCalls, drive.pauseHadSession, drive.pauseHadRegulator = oldPauseCalls, oldHadSession, oldHadRegulator
end
drive.scenarioPauseBoundaries()

-- 053/055：前一承諾走完時，下一台車的點雲早已被守護讀過，布局不變仍須重新規劃。
function drive.scenarioReleasedNextCar()
    scenario("承諾釋放：靜態布局不變仍及早繞過下一台停車")
    local oldWorld, oldGeo, oldSandbox = drive.world, drive.vehGeo, SandboxVars
    local oldGear = dp._modData.MDADGear
    drive.fillWorld(-20, 210, -10, 10)
    setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false,
        AutoDriveMaxSpeed = 40, RightLaneBias = 0 })
    dp._modData.MDADGear = 4
    -- 第二台在 70m、第二段承諾線尾約 80m：0909b 起視距由玩家感知距離＋固定每幀預算
    -- 決定（30 FPS 只有 ~50m，線尾會落在掃描帶外＝依約不得宣稱淨空），本情境量的是
    -- 「布局不變仍及早重規劃」的幾何契約，明確把幀時降到 10ms，收尾還原。
    local ncMs = drive.frameMs(10)
    drive.putVehicleGeom(20, 0.5, 0, 1.8, 4.4, true)
    drive.putVehicleGeom(70, -0.5, 0, 1.8, 4.4, true)
    checkTrue(armDrive(), "(next-car) 啟動")
    setHeading(dveh, 0)
    dveh._speed = 10
    drive.scanRound(true)
    local st = MDAD.Drive.debugSession(0)
    checkTrue(st.dodging, "(next-car) 第一台有掃掠通過的繞行")
    local finish = st.fstate.offD
    local function place(x)
        local fs = st.fstate
        local k = math.floor((x - fs.ovS0) / MDADFollower.OV_STEP) + 1
        dveh._x = x
        if k >= 1 and k < fs.ovN then
            dveh._y = fs.ovY[k]
            setHeading(dveh, math.atan(fs.ovY[k + 1] - fs.ovY[k], fs.ovX[k + 1] - fs.ovX[k]))
        else
            dveh._y = 0
            setHeading(dveh, 0)
        end
    end
    for x = 3, finish - 2, 3 do
        place(x)
        drive.scanRound(true)
    end
    place(finish - 0.5)
    drive.scanRound(true)
    -- 兩次掃描之間越過線尾，走真實的逐幀釋放，而不是在replan內順便重規劃。
    dveh._x, dveh._y = finish + 0.25, 0
    setHeading(dveh, 0)
    nowMs = nowMs + 30
    driveTick(dp, dveh)
    drive.scanRound(true)
    checkTrue(st.dodging and st.fstate.offB > finish + 5,
        "(next-car) 前車仍有跑道時已承諾第二段，不等碰撞改變布局")
    checkFalse(st.currentBlocked, "(next-car) 新承諾發生在接觸之前")
    drive.frameMs(ncMs)
    MDAD.Drive.stop(0, nil)
    drive.world, drive.vehGeo, SandboxVars = oldWorld, oldGeo, oldSandbox
    dp._modData.MDADGear = oldGear
end
drive.scenarioReleasedNextCar()

function drive.scenarioSpeedWindows()
    scenario("繞行速度視窗：可視區內完整回線、遠窄點漸進減速")
    local oldWorld, oldGeo, oldSandbox = drive.world, drive.vehGeo, SandboxVars
    local oldGear = MDAD.Drive.getGear(0)
    -- 本情境量的就是「長入口的逐點速度視窗」：舊制靠高速檔把 aheadM 拉到 ~110m 才看得到
    -- 75m 的窄點群，0909b 改由玩家感知距離（預設 120）＋固定每幀預算決定，30 FPS 只剩 ~50m。
    -- 這裡明確把幀時降到 10ms（有效視距＝請求值 120m），離開情境還原。
    local wasMs = drive.frameMs(10)
    setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false,
        AutoDriveMaxSpeed = 120, RightLaneBias = 0 })
    MDAD.Drive.setGear(0, 4)
    drive.fillWorld(-10, 72, -8, 8)
    drive.putVehicleGeom(20, 0, 0, 2.5, 4.4, true)
    drive.putVehicleGeom(27, 0, 0, 2.5, 4.4, true)
    checkTrue(armDrive(), "(horizon) 啟動")
    setHeading(dveh, 0)
    dveh._speed = 10
    drive.scanRound(true)
    local st = MDAD.Drive.debugSession(0)
    checkTrue(st.dodging and st.sensor.unloaded,
        "(horizon) 遠處尚未載入，但當下空間足夠完整回線，首輪即可承諾")
    checkTrue(st.dodging and st.fstate.offD + 1 + st.vehicleProfile.halfL
            + st.vehicleProfile.halfW <= st.sensor.unloadedS + 1e-6,
        "(horizon) 截短後線尾與車身仍完全留在已載入區")
    MDAD.Drive.stop(0, nil)

    -- 出口被路口截短，不能把它的窄點帽套滿前方長入口（051/055同型）。
    drive.fillWorld(-10, 160, -8, 8)
    drive.putVehicleGeom(75, 0.2, 0, 4.4, 4.4, true)
    drive.putVehicleGeom(75, 6.5, 0, 1.8, 4.4, true)
    for x = 65, 85 do drive.putSolid(x, -5, "harness_pinch_edge") end
    checkTrue(armDrive(), "(pinch) 啟動")
    setHeading(dveh, 0)
    dveh._speed = 10
    MDAD.Drive.stop(0, nil)
    drive.nav.route = { pts = {0, 0, 100, 0, 100, 80} }
    drive.nav.tx, drive.nav.ty = 100, 80
    checkTrue(MDAD.Drive.start(dp), "(pinch) 路口短回線場景啟動")
    for _ = 1, 4 do driveTick(dp, dveh) end
    drive.scanRound(true)
    drive.scanRound(true)
    st = MDAD.Drive.debugSession(0)
    checkTrue(st.dodging and st.fstate.offB - st.fstate.offA > 30,
        "(pinch) 真規劃器承諾長入口，而不是測試手寫運動剖面")
    local function sample(x)
        local fs = st.fstate
        local k = math.floor((x - fs.ovS0) / MDADFollower.OV_STEP) + 1
        dveh._x, dveh._y = x, fs.ovY[k]
        setHeading(dveh, math.atan(fs.ovY[k + 1] - fs.ovY[k], fs.ovX[k + 1] - fs.ovX[k]))
        nowMs = nowMs + 20
        driveReset(dveh)
        driveTick(dp, dveh)
        return st.dodgeApproachCap
    end
    local midpoint = (st.fstate.offA + st.fstate.offB) * 0.5
    local far = sample(midpoint)
    checkTrue(far > st.dodgeSpeedCap + 5 and drive.calls.maxRegSpeed > 10,
        "(pinch) 窄點仍遠時真的加速，不把整個入口鎖在10")
    -- 0909b：升速另外要有姿態證據——車還沒對上承諾線就提速，等於把入口的側移能力
    -- 當成已經在走直線。追線誤差超過門檻或車頭偏離該格切線 >5° 一律退回整線窄點帽。
    -- 1004e：門檻隨車身前方逐點淨距放寬（×0.5、上限 DODGE_ALIGN_DEV_MAX_M），窄處仍是 DODGE_ALIGN_DEV_M。
    local keepDev, keepHead = st.lastLatDev, st.lastVehicleHeading
    local envAligned = MDAD.Drive.dodgeEnvelopeCap(st, 10, nowMs)
    checkTrue(type(envAligned) == "number" and envAligned > st.dodgeSpeedCap,
        "(pinch) 對線且證明完整：逐點包絡高於整線窄點帽（實得 " .. tostring(envAligned) .. "）")
    local TA = MDAD.Drive.debugTune()
    local kA = math.floor((st.lastSNow - st.fstate.ovS0) / MDADFollower.OV_STEP) + 1
    local kB = math.min(st.fstate.ovN, kA + math.ceil(st.bodyReach / MDADFollower.OV_STEP))
    local mA = 1e9
    for j = kA, kB do mA = math.min(mA, st.dodgeClr[j]) end
    checkTrue(mA >= 2 * TA.DODGE_ALIGN_DEV_MAX_M, "(pinch) 前置：入口中段車身前方淨距寬（實得 " .. tostring(mA) .. "）")
    st.lastLatDev = 0.5
    checkTrue(MDAD.Drive.dodgeEnvelopeCap(st, 10, nowMs) > st.dodgeSpeedCap,
        "(pinch) 淨距寬處追線誤差 0.5m（>0.35、< 淨距一半）：照樣升速")
    st.lastLatDev = TA.DODGE_ALIGN_DEV_MAX_M + 0.05
    checkTrue(MDAD.Drive.dodgeEnvelopeCap(st, 10, nowMs) <= st.dodgeSpeedCap + 1e-9,
        "(pinch) 追線誤差超過放寬上限：不得升速，退回整線帽")
    local keepClr = {}
    for j = kA, kB do keepClr[j] = st.dodgeClr[j]; st.dodgeClr[j] = 0.4 end
    st.lastLatDev = TA.DODGE_ALIGN_DEV_M + 0.05
    checkTrue(MDAD.Drive.dodgeEnvelopeCap(st, 10, nowMs) <= st.dodgeSpeedCap + 1e-9,
        "(pinch) 車身前方淨距 0.4 時門檻回到 0.35：誤差 0.4 不得升速")
    for j = kA, kB do st.dodgeClr[j] = keepClr[j] end
    st.lastLatDev = keepDev
    st.lastVehicleHeading = keepHead + 10 * math.pi / 180
    checkTrue(MDAD.Drive.dodgeEnvelopeCap(st, 10, nowMs) <= st.dodgeSpeedCap + 1e-9,
        "(pinch) 車頭偏離該格切線 10°（>5°）：不得升速")
    st.lastVehicleHeading = keepHead
    checkNear(MDAD.Drive.dodgeEnvelopeCap(st, 10, nowMs), envAligned, 1e-9,
        "(pinch) 姿態恢復後同一張表照樣放行（偏頭斷言的反例）")
    local envN = st.dodgeEnvN
    st.dodgeEnvN = 0
    checkNear(sample(midpoint), st.dodgeSpeedCap, 1e-6,
        "(pinch) 沒有完整逐點速度證明時，維持原始整線保護")
    st.dodgeEnvN = envN
    local firstValid = st.dodgeClrK0
    st.dodgeClrK0 = math.floor((midpoint - st.fstate.ovS0) / MDADFollower.OV_STEP) + 2
    checkNear(sample(midpoint), st.dodgeSpeedCap, 1e-6,
        "(pinch) 部分守護表不能把未驗前綴的舊值當成完整證明")
    st.dodgeClrK0 = firstValid
    checkEq(MDAD.Drive.dodgeEnvelopeCap(st, 10, st.sensor.stamp + MDADDynamics.SNAPSHOT_FRESH_MS + 1), nil,
        "(pinch) 感知過期時不使用入口提速證明")
    st.sensor.hardOverflow = true
    checkEq(MDAD.Drive.dodgeEnvelopeCap(st, 10, nowMs), nil,
        "(pinch) 不完整點雲不能放行入口提速")
    st.sensor.hardOverflow = false
    -- 1002o：有效範圍縮短不再撤銷逐點表——表裡每一點都是看得到時量的，未掃區由逐點帽裡的可視帽與全域可視帽管
    -- （E2E rc52 0004：撤表後退回不含出口窄點的整線帽 64，表回來時窄點已在 10m 內，從 64 km/h 減到 27 擦上）。
    local savedEnd = st.sensor.scanEndS
    st.sensor.scanEndS = st.fstate.ovEndS - 1
    checkTrue(MDAD.Drive.dodgeEnvelopeCap(st, 10, nowMs) ~= nil,
        "(pinch) 有效範圍縮短：同一條線的逐點速度表照用，不退回不含出口窄點的整線帽")
    st.sensor.scanEndS = savedEnd
    checkTrue(MDAD.Drive.dodgeEnvelopeCap(st, 10, nowMs) ~= nil,
        "(pinch) 完整覆蓋時速度證明照用")
    local savedLat, savedCoast = st.safeLat, st.safeCoast
    st.safeLat = savedLat * 0.5
    checkEq(MDAD.Drive.dodgeEnvelopeCap(st, 10, nowMs), nil,
        "(pinch) 兩次冷輪之間側向能力收緊，不沿用較樂觀的舊速度表")
    st.safeLat, st.safeCoast = savedLat, savedCoast * 0.5
    checkEq(MDAD.Drive.dodgeEnvelopeCap(st, 10, nowMs), nil,
        "(pinch) 兩次冷輪之間滑行能力收緊，不沿用舊煞停距離")
    st.safeCoast = savedCoast
    local near = sample(st.fstate.offB - st.vehicleProfile.halfL - 4)
    checkTrue(near < far and near > st.dodgeSpeedCap,
        "(pinch) 接近窄點連續收斂，按滑行能力提前減速，不是到點才二值降速")
    MDAD.Drive.stop(0, nil)
    drive.frameMs(wasMs)
    drive.world, drive.vehGeo, SandboxVars = oldWorld, oldGeo, oldSandbox
    MDAD.Drive.setGear(0, oldGear)
end
drive.scenarioSpeedWindows()

function drive.scenarioReviewBoundaries()
    scenario("候選與停等安全邊界：拓寬不越視界、重心支撐、低帽與同輪交接")
    local oldWorld, oldGeo, oldSandbox, oldVeh = drive.world, drive.vehGeo, SandboxVars, dveh
    local oldGear = MDAD.Drive.getGear(0)
    setSandbox({NeedItemForNav=false, NeedItemForAutoDrive=false, AutoDriveMaxSpeed=40, RightLaneBias=0})
    MDAD.Drive.setGear(0, 4)
    drive.fillWorld(-10, 160, -8, 8)
    drive.putTree(25, 0, "vegetation_trees_01_5")
    checkTrue(armDrive(), "(window-widen) 啟動")
    setHeading(dveh, 0)
    dveh._speed = 10
    drive.scanRound(true)
    local st = MDAD.Drive.debugSession(0)
    local vp = st.vehicleProfile
    local ck = MDADDynamics.steeringKappa(vp.wheelbase, vp.delta0Safe, vp.deltaVSafe, vp.maxSpeed, 12)
    local min1 = MDADDynamics.shiftLength(1.9, 0, st.safeLat, ck, vp.halfL, MDADDynamics.LATERAL_JERK_MAX)
    local min2 = MDADDynamics.shiftLength(2.15, 0, st.safeLat, ck, vp.halfL, MDADDynamics.LATERAL_JERK_MAX)
    st.sensor.unloaded = true
    st.sensor.unloadedS = 30 + 1 + st.bodyReach + (min1 + min2) * 0.5
    local ok, lane, _, _, _, _, _, tail = MDAD.Drive.debugSweepFallbacks(0, 1, 20, 30, 60, 1.9, "window-widen")
    checkTrue(ok and lane >= 1.9 and tail + 1 + st.bodyReach <= st.sensor.unloadedS + 1e-6,
        "(window-widen) 原線或更寬的線都須將完整車身留在已知範圍，短出口由世界掃掠裁決")
    MDAD.Drive.stop(0, nil)

    dveh = newVehicle({battery=newItem("Base.CarBattery", {uses=0.8}),
        engineRunning=true, mass=1200, speed=10, maxSpeed=120, bodyW=2, bodyL=6, comX=0, comZ=2,
        profileFull=true, enginePower=4000, brakingForce=80, wheelFriction=1.5, tireFriction=1.5})
    setSandbox({NeedItemForNav=false, NeedItemForAutoDrive=false, AutoDriveMaxSpeed=120, RightLaneBias=0})
    drive.fillWorld(-10, 40, -10, 10)
    drive.putTree(20, 0, "vegetation_trees_01_5")
    checkTrue(armDrive(), "(window-com) 非零重心車啟動")
    setHeading(dveh, 0)
    dveh._speed = 10
    drive.scanRound(true)
    st, vp = MDAD.Drive.debugSession(0), MDAD.Drive.debugSession(0).vehicleProfile
    checkTrue(st.dodging, "(window-com) 可視空間足夠仍能承諾")
    if st.dodging then
        local fs, n = st.fstate, st.fstate.ovN
        local dx, dy = fs.ovX[n] - fs.ovX[n - 1], fs.ovY[n] - fs.ovY[n - 1]
        local length = math.sqrt(dx * dx + dy * dy)
        local fx, fy = dx / length, dy / length
        local front = fs.ovX[n] + fx * vp.centerOfMassZ + fy * vp.centerOfMassX
            + math.abs(fx) * vp.halfL + math.abs(fy) * vp.halfW
        checkTrue(front <= st.sensor.unloadedS,
            "(window-com) 驗真OBB最前角，不能只驗漏掉重心的支撐式")
    end
    MDAD.Drive.stop(0, nil)
    dveh = oldVeh
    setSandbox({NeedItemForNav=false, NeedItemForAutoDrive=false, AutoDriveMaxSpeed=40, RightLaneBias=0})
    MDAD.Drive.setGear(0, 3)
    drive.fillWorld(-20, 210, -10, 10)
    drive.putVehicleGeom(20, 0.5, 0, 1.8, 4.4, true)
    checkTrue(armDrive(), "(next-stop) 啟動")
    setHeading(dveh, 0)
    dveh._speed = 10
    drive.scanRound(true)
    st = MDAD.Drive.debugSession(0)
    checkTrue(st.dodging and not st.dodgeCrawl, "(next-stop) 普通巡航承諾，不能靠CRAWL假綠")
    local finish = st.fstate.offD
    drive.putTree(math.floor(finish + 5), 0, "vegetation_trees_01_5")
    local function place(x)
        local fs = st.fstate
        local k = math.floor((x - fs.ovS0) / MDADFollower.OV_STEP) + 1
        dveh._x, dveh._y = x, fs.ovY[k]
        setHeading(dveh, math.atan(fs.ovY[k + 1] - fs.ovY[k], fs.ovX[k + 1] - fs.ovX[k]))
    end
    local oldCf, oldCl, oldDc = st.coastConfidence, st.coastLower, st.dynamicsCoastCap
    place(st.fstate.offB + 1)
    dveh._speed = 0
    st.coastConfidence, st.coastLower, st.dynamicsCoastCap = 1, 0, 0
    drive.scanRound(true)
    drive.scanRound(true)
    checkTrue(st.dodging and st.fstate.offD == finish and st.intentShadow == "WAIT" and st.waitAccumMs > 0,
        "(next-stop) 尚未整車越過舊群：保留承諾並計停等，不抬速或無限GO+0")
    -- (next-deadlock) 下一群的滑行停點是圓盤距離，斜前方物件會把車停在 c+bodyReach 之前（0929k E2E Oshkosh C 段：
    -- 停在門檻前 0.13m，12 秒後受困交還）。進入段已走完且已開到停點就交接；停點還沒到／還在進入段照舊停等。
    -- 1005：原本要車頭過 c，改成過 b（E2E m1004g dixie9050w：出口被截到 1.41m、下一台貼在線尾後，停點在 c 前 1.5m，
    -- 車永遠到不了 c、停等 15 秒交還）。停留照舊要過 c（stayLanePending 過 b 才寫 laneBias）。
    -- 違規證明：門檻改回 offC＝「保持段內」紅；改成不看 offB＝「進入段」紅；拿掉停留例外＝「停留」紅。
    do
        local fs, keepS = st.fstate, st.lastSNow
        local keepCap, keepDist = st.dodgeNextCap, st.dodgeNextDist
        st.dodgeNextCap = 0
        st.lastSNow, st.dodgeNextDist = fs.offC + 0.5, 0.1
        checkTrue(MDAD.Drive.nextStopHandoff(st, 0),
            "(next-deadlock) 車頭過 c、已開到下一群停點、還沒整車過 c：停穩就交接，不等到受困")
        st.dodgeNextDist = 2.0
        checkFalse(MDAD.Drive.nextStopHandoff(st, 0), "(next-deadlock) 還沒開到停點：繼續往前，不提早交接")
        st.lastSNow, st.dodgeNextDist = fs.offC - 1.5, 0.1 -- m1004g：停在 c 前 1.5m
        checkTrue(fs.offB < fs.offC - 1.5 and MDAD.Drive.nextStopHandoff(st, 0),
            "(next-deadlock) 保持段內（過 b、未到 c）就停在下一群停點：交接，不停等到受困交還")
        st.dodgeStay = true
        checkFalse(MDAD.Drive.nextStopHandoff(st, 0), "(next-deadlock) 停留承諾照舊要過 c 才交接")
        st.dodgeStay = false
        st.lastSNow = fs.offB - 0.5
        checkFalse(MDAD.Drive.nextStopHandoff(st, 0), "(next-deadlock) 還在進入段：不交接")
        st.lastSNow, st.dodgeNextDist = fs.offC + 0.5, 0.1
        checkFalse(MDAD.Drive.nextStopHandoff(st, 5), "(next-deadlock) 還在動：不交接")
        st.lastSNow, st.dodgeNextDist = fs.offC + st.bodyReach + 0.1, 5
        checkTrue(MDAD.Drive.nextStopHandoff(st, 0), "(next-deadlock) 整車過 c 的舊條件照舊")
        st.lastSNow, st.dodgeNextCap, st.dodgeNextDist = keepS, keepCap, keepDist
    end
    st.coastConfidence, st.coastLower, st.dynamicsCoastCap = oldCf, oldCl, oldDc
    dveh._speed = 10
    place(finish - 0.5)
    st.safeCoast = 0.6
    -- 在下一個完成快照交接前驗帽；新契約不再為了驗帽而等到停穩才重規劃。
    nowMs = nowMs + 20
    driveReset(dveh)
    driveTick(dp, dveh)
    checkTrue(st.intentShadow == "WAIT" and st.dodgeNextCap > 0 and st.dodgeNextCap < 8
            and st.cmdV * 3.6 <= st.dodgeNextCap + 1e-6,
        "(next-stop) 低於8km/h的真正停止包絡不被MIN_EXEC抬高")
    oldCf, oldCl, oldDc = st.coastConfidence, st.coastLower, st.dynamicsCoastCap
    st.coastConfidence, st.coastLower, st.dynamicsCoastCap = 1, 0, 0
    dveh._speed = 0
    nowMs = nowMs + 20
    driveReset(dveh)
    driveTick(dp, dveh)
    checkTrue(st.intentShadow == "WAIT" and st.dodgeNextCap == 0 and st.cmdV == 0
            and drive.calls.maxRegSpeed == 0, "(next-stop) 零能力停止要求不被GO零帽分支抬高")
    st.coastConfidence, st.coastLower, st.dynamicsCoastCap = oldCf, oldCl, oldDc
    drive.scanRound(true)
    checkTrue(st.dodging and st.fstate.offB > finish and st.planMode ~= "guard",
        "(next-stop) 已停穩且整車過舊群，同一輪交下一候選，不永遠停在線尾前")
    MDAD.Drive.stop(0, nil)
    drive.world, drive.vehGeo, SandboxVars, dveh = oldWorld, oldGeo, oldSandbox, oldVeh
    MDAD.Drive.setGear(0, oldGear)
end
drive.scenarioReviewBoundaries()

function drive.scenarioDualPinch(switchStyle)
    scenario(switchStyle and "逐點速度證明：MAX與舒適切換不復活舊世界"
        or "逐點速度證明：較早窄點不得被後方更窄點掩蓋")
    local oldWorld, oldGeo, oldSandbox = drive.world, drive.vehGeo, SandboxVars
    local oldGear = MDAD.Drive.getGear(0)
    setSandbox({NeedItemForNav=false, NeedItemForAutoDrive=false, AutoDriveMaxSpeed=120, RightLaneBias=0})
    MDAD.Drive.setGear(0, 4)
    -- 窄點群在 75m：0909b 起視距由玩家感知距離＋固定每幀預算決定（30 FPS 只有 ~50m），
    -- 這裡明確把幀時降到 10ms（有效視距＝請求值 120m），情境收尾還原。
    local dpMs = drive.frameMs(10)
    drive.fillWorld(-10, 160, -8, 8)
    drive.putVehicleGeom(75, 0.2, 0, 4.4, 4.4, true)
    drive.putVehicleGeom(75, 6.5, 0, 1.8, 4.4, true)
    for x = 65, 85 do drive.putSolid(x, -5, "harness_dual_edge") end
    checkTrue(armDrive(), "(dual) 啟動")
    setHeading(dveh, 0)
    dveh._speed = 10
    MDAD.Drive.stop(0, nil)
    drive.nav.route = {pts={0, 0, 100, 0, 100, 80}}
    drive.nav.tx, drive.nav.ty = 100, 80
    checkTrue(MDAD.Drive.start(dp), "(dual) 真長入口場景啟動")
    for _ = 1, 4 do driveTick(dp, dveh) end
    drive.scanRound(true)
    drive.scanRound(true)
    local st = MDAD.Drive.debugSession(0)
    local fs = st.fstate
    local originalLine = fs.ovX
    if switchStyle then
        MDAD.Drive.setGear(0, 3)
        drive.scanRound(true)
        checkEq(st.profile.styleName, "comfort", "(dual-style) 真實套用舒適策略")
    end
    local function obstacle(sk, gap)
        local k = math.floor((sk - fs.ovS0) / MDADFollower.OV_STEP) + 1
        local dx, dy = fs.ovX[k + 1] - fs.ovX[k], fs.ovY[k + 1] - fs.ovY[k]
        local length = math.sqrt(dx * dx + dy * dy)
        local fx, fy = dx / length, dy / length
        local shift = st.dodgeNeed + 0.9 + 0.15 + gap
        drive.putVehicleGeom(fs.ovX[k] - fy * shift, fs.ovY[k] + fx * shift,
            math.atan(fy, fx), 1.8, 2.4, true)
        return fs.ovS0 + (k - 1) * MDADFollower.OV_STEP
    end
    local early, later = obstacle(fs.offA + 8, 0.14), obstacle(fs.offA + 20, 0.07)
    -- 高速帶可能需超過28個tick；第二輪保證兩台新增車都在完整快照中。
    drive.scanRound(true)
    drive.scanRound(true)
    checkTrue(not st.blocked and st.dodgeMarginS > early + 5,
        "(dual) 兩窄處都掃掠通過，而全域最緊點確實在較後方")
    if switchStyle then
        checkTrue(st.dodgeSpeedCap <= 5, "(dual-style) 舒適重驗已知前方變窄")
        MDAD.Drive.setGear(0, 4)
        drive.scanRound(true)
        drive.scanRound(true)
        checkTrue(st.profile.styleName == "brisk" and fs.ovX == originalLine,
            "(dual-style) 切回MAX仍保留同一承諾線")
    end
    local function sample(x)
        local k = math.floor((x - fs.ovS0) / MDADFollower.OV_STEP) + 1
        dveh._x, dveh._y = x, fs.ovY[k]
        setHeading(dveh, math.atan(fs.ovY[k + 1] - fs.ovY[k], fs.ovX[k + 1] - fs.ovX[k]))
        nowMs = nowMs + 20
        driveReset(dveh)
        driveTick(dp, dveh)
        return drive.calls.maxRegSpeed
    end
    if not switchStyle then
        -- 0928m brisk 彎前晚收油：剖面速度較高、承諾線入口可從車位附近開始（a≈1），接近段取承諾線內
        checkTrue(sample(math.max(early - 10, fs.ovS0)) > 9, "(dual) 空曠接近段仍可提速，不退化為全線5")
    end
    local sh = math.min(1, 1.2 * st.dodgeShapeDl / st.dodgeEntryLength)
    local earlyCap = math.max(5, MDADDynamics.clearanceCapKmh(0.14, 0, 0.3, st.dodgeEnvLat, sh))
    local laterCap = math.max(5, MDADDynamics.clearanceCapKmh(0.07, 0, 0.3, st.dodgeEnvLat, sh))
    checkTrue(sample(early) <= math.ceil(earlyCap),
        "(dual) 較早窄點按當地側移斜率限速，不能只看遠處最窄點")
    checkTrue(sample(later) <= math.ceil(laterCap) and not st.currentBlocked,
        "(dual) 後一窄點同樣守住當地淨距能力")
    drive.frameMs(dpMs)
    MDAD.Drive.stop(0, nil)
    drive.world, drive.vehGeo, SandboxVars = oldWorld, oldGeo, oldSandbox
    MDAD.Drive.setGear(0, oldGear)
end
drive.scenarioDualPinch(false)
drive.scenarioDualPinch(true)

function drive.scenarioThreeCarHandoff()
    scenario("三車交接：後載入回線障礙不必停車，失敗則跨輪保持停止")
    local oldWorld, oldGeo, oldSandbox, oldVeh, oldGet =
        drive.world, drive.vehGeo, SandboxVars, dveh, getSpecificPlayer
    local oldGear = MDAD.Drive.getGear(0)
    MDAD.Drive.stop(0, nil)
    getSpecificPlayer = function(n) if n == 0 then return dp end end
    dveh = newVehicle({ battery = newItem("Base.CarBattery", { uses = 0.8 }),
        engineRunning = true, mass = 1341, speed = 20, maxSpeed = 85,
        bodyW = 1.8, bodyL = 5.8, comX = 0, comZ = 0, profileFull = true,
        enginePower = 4200, brakingForce = 112, wheelFriction = 1.7, tireFriction = 1.59 })
    for i = 0, 3 do
        local offset = dveh:getScript():getWheel(i):getOffset()
        offset:set(offset:x(), offset:y(), (i < 2 and 1 or -1) * 1.895)
    end
    -- 14m 路 ×(1/3.5)＝常駐 1.0m：fixture 車位幾何（第一台 y=1.55 擋線）以 1.0m 靠右設計。
    setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false,
        AutoDriveMaxSpeed = 120, RightLaneBias = 1 / 3.5 })
    MDAD.Drive.setGear(0, 4)
    -- 三台車分別在 51／75／90，車要一路開到 97：整段幾何契約需要 ~100m 視距。
    -- 0909b 起視距由玩家感知距離＋固定每幀預算決定（30 FPS 只有 ~50m），所以明確把
    -- 幀時降到 10ms（有效視距＝請求值 120m），情境收尾還原。
    local hoMs = drive.frameMs(10)
    local st
    local observing, minCommand, contact, braked = false, math.huge, false, false
    local originalTick = driveTick
    driveTick = function(player, vehicle)
        originalTick(player, vehicle)
        if observing then
            minCommand = math.min(minCommand, st.cmdV * 3.6)
            contact = contact or st.currentBlocked or st.mode == "unstick"
            braked = braked or drive.calls.forceBrake > 0
        end
    end
    local function round()
        driveReset(dveh)
        local stamp = st.sensor.stamp
        drive.scanRound(true)
        drive.scanRound(true)
        -- 退化成恢復流程時本來就不掃前方；由逐幀觀測判錯，不把它誤報為 fixture 失效。
        if st.mode == "follow" then
            assert(st.sensor.stamp > stamp, "(handoff) fixture 必須使用新完成快照")
        end
    end
    local function place(x, speed)
        local fs = st.fstate
        local k = math.floor((x - fs.ovS0) / MDADFollower.OV_STEP) + 1
        dveh._x, dveh._speed = x, speed
        if k >= 1 and k < fs.ovN then
            dveh._y = fs.ovY[k]
            setHeading(dveh, math.atan(fs.ovY[k + 1] - fs.ovY[k], fs.ovX[k + 1] - fs.ovX[k]))
        end
    end
    local function arm(nextX)
        MDAD.Drive.stop(0, nil)
        drive.fillWorld(-20, 76, -10, 10)
        -- 026/030 的相對幾何：第一台在可視區內，第二台在首次承諾後才進入點雲。
        drive.putVehicleGeom(51, 1.55, -0.1835, 1.31, 3.24, true)
        dveh._x, dveh._y, dveh._speed, dveh._driver = 0, 1, 20, dp
        dp._vehicle = dveh
        setHeading(dveh, 0)
        local route = newRoute(2, 0, 0, 180, 0)
        route.navVersion, route.segSurface, route.segWidth = 4, { "paved" }, { 14 }
        drive.nav.route, drive.nav.tx, drive.nav.ty, drive.nav.state = route, 180, 0, "ok"
        checkTrue(MDAD.Drive.start(dp), "(handoff) F350 幾何啟動")
        for _ = 1, 4 do driveTick(dp, dveh) end
        st = MDAD.Drive.debugSession(0)
        round()
        checkTrue(st.dodging and not st.dodgeStay, "(handoff) 首線是普通繞行，不是假造停留")
        local firstB, firstC = st.fstate.offB, st.fstate.offC
        for x = 77, 180 do
            for y = -10, 10 do drive.mkSquare(x, y) end
        end
        drive.putVehicleGeom(nextX or 75, 1.17, -0.1165, 1.31, 3.24, true)
        if not nextX then drive.putVehicleGeom(90, -0.21, 0.0292, 1.64, 4.72, true) end
        round()
        if nextX then
            checkTrue(st.dodging and not st.blocked, "(handoff-far) 遠車不破壞原承諾")
        else
            checkTrue(st.blocked and st.dodgeGuardFailed and st.guardHitPhase == 4,
                "(handoff) 真守護在後載入第二台的回線段判死")
        end
        for x = 4, 58, 3 do
            place(x, math.min(20, math.max(0, st.cmdV * 3.6)))
            round()
            checkTrue(st.fstate.offB == firstB and st.dodging,
                "(handoff) 整車未過舊群不改入口／保持段")
        end
        checkTrue(st.lastSNow < firstC + st.bodyReach, "(handoff) 前置位置仍在全車過清門檻內")
        return firstB
    end

    local firstB = arm()
    place(61, 15)
    -- 非回線段失敗不能借用此交接；hardS 在 c 後不能冒充 p4。
    st.guardHitPhase = 3
    round()
    checkEq(st.fstate.offB, firstB, "(handoff) p3 失敗不交接")
    st.guardHitPhase = 4
    local originalStep = MDADSensor.step
    for _, field in ipairs({ "hardOverflow", "movingVeh" }) do
        MDADSensor.step = function(...)
            local complete = originalStep(...)
            if complete then st.sensor[field] = true end
            return complete
        end
        round()
        checkEq(st.fstate.offB, firstB, "(handoff) " .. field .. " 不交接")
    end
    MDADSensor.step = originalStep
    observing = true
    round()
    local secondB = st.fstate.offB
    checkTrue(st.dodging and secondB > firstB + 10 and st.dodgeStay,
        "(handoff) 15km/h 同輪交第二台停留，不等停穩或倒車")
    checkTrue(st.cmdV > 0 and drive.calls.forceBrake == 0 and st.mode == "follow",
        "(handoff) 成功交接沒有零命令／煞車閂鎖")
    local thirdSeen = false
    for x = 64, 97, 3 do
        place(x, math.min(20, math.max(0, st.cmdV * 3.6)))
        round()
        thirdSeen = thirdSeen or st.fstate.offB > secondB + 5
    end
    observing = false
    checkTrue(thirdSeen and minCommand > 0 and not contact and not braked,
        "(handoff) 每個控制tick均無接觸／倒車／零命令／強制煞車，第二到第三台連續通過")

    -- 0925p：80 km/h 距第二群縫口 8m，連緊急煞車都停不住＝延後只會撞上；改採納新候選線
    -- （掃掠驗過、Follower 持有新線），不得沿被候選覆寫的舊線前進
    arm()
    place(61, 80)
    round()
    checkTrue(st.dodging and st.fstate.offB > firstB + 10 and st.dodgeDeferCap < 0,
        "(handoff-speed) 停不住的交接：當輪採納新線，不沿舊線、不延後")

    arm()
    for y = -10, 10 do drive.putSolid(74, y, "handoff_wall") end
    place(61, 15)
    round()
    checkTrue(st.blocked and not st.dodging and st.cmdV == 0,
        "(handoff-wall) 新候選全部撞牆：當輪停止")
    dveh._speed = 0
    for _ = 1, 3 do
        round()
        checkTrue(st.cmdV == 0 and drive.calls.maxRegSpeed == 0,
            "(handoff-wall) 沒有可用新線，不因下輪重規劃解除停止")
    end
    for x = 1, 180 do
        for y = -10, 10 do drive.mkSquare(x, y) end
    end
    drive.vehGeo = {}
    for _ = 1, 4 do round() end
    checkTrue(not st.blocked and st.cmdV > 0,
        "(handoff-wall) 真正淨空後恢復，停止約束不殘留")

    firstB = arm()
    st.guardHitPhase = 3
    place(67, 0)
    round()
    checkTrue(not st.dodging or st.fstate.offB > firstB + 10,
        "(handoff-stop) 無法行駛中交接的失效線，停穩後仍會釋放，不等倒車")
    checkTrue(st.mode == "follow", "(handoff-stop) 停穩清線不必先進入倒車")

    firstB = arm(156)
    place(61, 15)
    round()
    checkTrue(st.dodging and st.fstate.offB == firstB and not st.blocked and st.cmdV > 0,
        "(handoff-far) 約95m外的下一群不提早交接；避免停在尚未進入承諾窗的位置")
    driveTick = originalTick
    drive.frameMs(hoMs)
    MDAD.Drive.stop(0, nil)
    drive.world, drive.vehGeo, SandboxVars, dveh, getSpecificPlayer =
        oldWorld, oldGeo, oldSandbox, oldVeh, oldGet
    MDAD.Drive.setGear(0, oldGear)
end
drive.scenarioThreeCarHandoff()

-- (beside) 1002t：正式服 20261002b Aho clip-24／AngryPanda clip-11：P1 繞行的回線段順手讓過 P2（10m 後、只擋常駐線），
--   整車過 c 的第一個完成輪 next-group 交接時 P2 就在車身旁。主候選從常駐線規劃 → entry／steep 塑形失敗，
--   舊 handoffReady 卻以 `not ok` 回 true；正式鏈的直走／爬行檔又被 P3（舊線尾後）deadend 拒 → blocked
--   停止線＝shape 失敗的 b（≤ rs+halfL）→ 34 km/h 鎖輪。契約：舊線仍有效時塑形失敗不交接，P2 離開規劃
--   群後在行駛中交到新線。違規證明：handoffReady 改回 `return not ok or (...)` 即兩組全紅。
function drive.scenarioHandoffBesideGroup(p2x, p2y)
    scenario("交接預檢：下一群貼在車身旁時保留仍有效的舊線，不在車身處判堵 p2=" .. p2x .. "," .. p2y)
    local oldWorld, oldGeo, oldSandbox, oldVeh, oldGet =
        drive.world, drive.vehGeo, SandboxVars, dveh, getSpecificPlayer
    local oldGear = MDAD.Drive.getGear(0)
    MDAD.Drive.stop(0, nil)
    getSpecificPlayer = function(n) if n == 0 then return dp end end
    dveh = newVehicle({ battery = newItem("Base.CarBattery", { uses = 0.8 }),
        engineRunning = true, mass = 1327, speed = 34, maxSpeed = 120,
        bodyW = 1.62, bodyL = 4.12, comX = 0, comZ = 0, profileFull = true,
        enginePower = 4200, brakingForce = 112, wheelFriction = 1.7, tireFriction = 1.59 })
    setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false,
        AutoDriveMaxSpeed = 120, RightLaneBias = 1 / 3.5 }) -- 14m 路＝常駐 +1.0
    MDAD.Drive.setGear(0, 4)
    local hoMs = drive.frameMs(10)
    local st
    local braked, atBody = false, false
    local originalTick = driveTick
    driveTick = function(player, vehicle)
        originalTick(player, vehicle)
        -- 逐 tick 觀測：停止線落在車頭以內＝本案的鎖輪條件
        if st and st.blocked and not st.dodging and type(st.blockS) == "number"
                and st.blockS <= st.lastSNow + st.vehicleProfile.halfL then
            atBody = true
        end
        braked = braked or drive.calls.forceBrake > 0
    end
    local function round()
        driveReset(dveh)
        drive.scanRound(true)
        drive.scanRound(true)
    end
    local function place(x, speed)
        local fs = st.fstate
        dveh._x, dveh._speed = x, speed
        local k = math.floor((x - fs.ovS0) / MDADFollower.OV_STEP) + 1
        if k >= 1 and k < fs.ovN then
            dveh._y = fs.ovY[k]
            setHeading(dveh, math.atan(fs.ovY[k + 1] - fs.ovY[k], fs.ovX[k + 1] - fs.ovX[k]))
        end
    end
    drive.fillWorld(-20, 200, -10, 10)
    drive.putRoad(-20, 200, -7, 7)
    drive.putSolid(50, 0, "p1"); drive.putSolid(50, 1, "p1")
    dveh._x, dveh._y, dveh._speed, dveh._driver = 0, 1, 34, dp
    dp._vehicle = dveh
    setHeading(dveh, 0)
    local route = newRoute(2, 0, 0, 180, 0)
    route.navVersion, route.segSurface, route.segWidth = 4, { "paved" }, { 14 }
    drive.nav.route, drive.nav.tx, drive.nav.ty, drive.nav.state = route, 180, 0, "ok"
    checkTrue(MDAD.Drive.start(dp), "(beside) 啟動")
    for _ = 1, 4 do driveTick(dp, dveh) end
    st = MDAD.Drive.debugSession(0)
    round()
    checkTrue(st.dodging and not st.dodgeStay, "(beside) 前置：P1 普通繞行（有回線段）")
    local firstB, firstC = st.fstate.offB, st.fstate.offC
    -- P2／P3 承諾後才進點雲（正式服是 unloaded defer 後載入）：P2 只擋常駐線、舊回線段讓得過；
    -- P3 落在舊線尾後 bodyReach 內（交接門檻收得到），且讓直走／爬行檔 deadend。
    drive.putSolid(p2x, p2y, "p2"); drive.putSolid(p2x + 1, p2y, "p2")
    drive.putSolid(120, 0, "p3"); drive.putSolid(120, 1, "p3")
    local gate, newB = false, nil
    braked, atBody = false, false
    for x = 30, 80, 1.5 do
        place(x, 34)
        round()
        if not gate and st.lastSNow >= firstC + st.bodyReach then
            gate = true
            checkTrue(st.dodging and st.fstate.offB == firstB,
                "(beside) 首個交接輪：P2 在車身旁、主候選塑形失敗＝保留仍有效的舊線")
        end
        if st.dodging and st.fstate.offB ~= firstB then newB = st.fstate.offB end
        if newB or atBody then break end
    end
    checkTrue(gate, "(beside) 前置：走到整車過清門檻")
    checkFalse(atBody, "(beside) 每個 tick 都沒有落在車身處的判堵停止線")
    checkTrue(newB ~= nil and st.cmdV > 0, "(beside) P2 離開規劃群後行駛中交到新線（不先停）")
    checkFalse(braked, "(beside) 全程無強制煞車")
    driveTick = originalTick
    drive.frameMs(hoMs)
    MDAD.Drive.stop(0, nil)
    drive.world, drive.vehGeo, SandboxVars, dveh, getSpecificPlayer =
        oldWorld, oldGeo, oldSandbox, oldVeh, oldGet
    MDAD.Drive.setGear(0, oldGear)
end
drive.scenarioHandoffBesideGroup(57, 1) -- P2 起點在車頭後（Aho：entry）
drive.scenarioHandoffBesideGroup(58, 2) -- P2 起點在車頭前 1–2m（AngryPanda 同族；本 fixture 回 entry）

-- 0909b 感知距離可調（48/80/120/160/200，動態上限 240）的四個審查反例。一個 setup、
-- 四個彼此獨立的邊界；量的全是真 Sensor 快照與真承諾線的行為，不手塞 ready／stamp。
--   (cov)   完成的 48m 快照＋整段已載入的世界：候選線尾落在掃描帶外＝「不知道」，
--           不是淨空。同一個 world 把請求改成 200m、跑完新的一輪，同一候選必須收——
--           證明拒收來自「沒掃到」而不是幾何本身不行。違規證明：candidateCovered 改成
--           只看 sensor.unloaded（或拿 profile.length 當視界）即由紅轉綠。
--   (soft)  200m 視界看得到 150m 外的屍體／軟物／行進車，但「看得到」不等於「現在要慢」：
--           三者都只給 approach envelope，不得把當下壓成 CORPSE_CAP 30／SOFT_CAP 25／
--           MOVING_VEH_CAP 20；進到 lead 窗內才回到原本的近端平帽。遠處屍體同時不得
--           擠進 softLookahead（max 40m／3s）的軟縫點雲額度。違規證明：把
--           approachSoftCap 換回整帶平帽、或讓 wSoftEndS 跟著 aheadM 長，即紅。
--   (pre-a) 承諾線上還沒進入 entry 的當前點不吃 entry 的 shift-space 帽：縮短
--           dodgeEntryLength 只壓得動 entry 起點，當前點必須一動不動。違規證明：
--           拿掉 dodgePointCap 的 `sk < fs.offA` 分支（＝整條線共用入口 dl）即紅。
--   (cap)   0.5m 分段的 601 點路線＋200m 視界：證明線橫跨的**剖面段數**遠超 LANE_MAX
--           （那是 1m 證明線的點數上限，不是段索引上限）。舊制拿 LANE_MAX 夾 rangeN，
--           密路線一律 verifyLineReason=capacity → 永遠拿不到 full gate。
function drive.scenarioPerceptionRange()
    scenario("長感知：未掃尾段不是淨空、遠處軟點只做 envelope、pre-a 不吃入口帽、密分段證明線不因容量失敗")
    local oldWorld, oldGeo, oldSandbox, oldVeh, oldGet =
        drive.world, drive.vehGeo, SandboxVars, dveh, getSpecificPlayer
    local oldGear, oldApi = MDAD.Drive.getGear(0), MinidoracatMiniMapAPI.navApiVersion
    local oldPerception, oldDodgeZ = MDAD.HUD.perceptionDistance, MDAD.HUD.zombieDodge
    local oldCorpse = MDAD.Drive.getSlowPref(0, "corpse")
    local oldRoute, oldTx, oldTy, oldNavState =
        drive.nav.route, drive.nav.tx, drive.nav.ty, drive.nav.state
    MDAD.Drive.stop(0, nil)
    getSpecificPlayer = function(n) if n == 0 then return dp end end
    -- 走廊整段填滿（fillWorld 自己會清掉 world/vehGeo）：本情境每一條斷言都要能歸因
    -- 「沒掃到」，不能混進「未載入」（未載入另有既有情境在鎖）。200m 掃描帶＋±6.5
    -- 橫向＝需要 x 2..202、y −7..7 全部在。
    drive.fillWorld(-12, 232, -9, 9)
    drive.putRoad(-12, 232, -7, 7)
    setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false,
        AutoDriveMaxSpeed = 120, RightLaneBias = 0 })
    MinidoracatMiniMapAPI.navApiVersion = 4
    -- 屍體 0909b 起也併進殭屍軟縫；本情境量的是速度帽的歸因，軟縫的縱向配合帽會搶走
    -- capReason（同 Phase E 的 (zc) 區塊），整段關掉、收尾還原。
    MDAD.HUD.zombieDodge = function() return false end
    MDAD.Drive.setSlowPref(0, "corpse", true)
    MDAD.Drive.setGear(0, 4)
    dveh = newVehicle({ battery = newItem("Base.CarBattery", { uses = 0.8 }),
        engineRunning = true, mass = 1341, speed = 20, maxSpeed = 120,
        bodyW = 1.8, bodyL = 5.8, comX = 0, comZ = 0, profileFull = true,
        enginePower = 4200, brakingForce = 112, wheelFriction = 1.7, tireFriction = 1.59 })
    -- 每幀 56 格的固定預算下，4ms 幀時買得起 SCAN_NEAR + (56/14)×375/4 ≈ 377m，
    -- 請求值 200 才不會先被有效視距夾掉（30 FPS 只買得起 ~50m）。收尾還原。
    local wasMs = drive.frameMs(4)
    local function arm(route, target, tag)
        MDAD.Drive.stop(0, nil)
        dveh._x, dveh._y, dveh._speed, dveh._steering, dveh._stopped = 0, 0, 20, 0, false
        dveh._engine, dveh._driver = true, dp
        dp._vehicle, dp._dead, dp._local = dveh, false, true
        setHeading(dveh, 0)
        drive.nav.route, drive.nav.tx, drive.nav.ty, drive.nav.state = route, target, 0, "ok"
        checkTrue(MDAD.Drive.start(dp), "(" .. tag .. ") 啟動")
        for _ = 1, 24 do driveTick(dp, dveh) end
        return MDAD.Drive.debugSession(0)
    end

    -- ① (cov) 48m：候選的 hold 段本身就在掃描帶外，拒收；改 200m 後同一候選可收
    MDAD.HUD.perceptionDistance = function() return 48 end
    local st = arm({ pts = { 0, 0, 300, 0 }, segSurface = { "paved" },
        segWidth = { 14 } }, 300, "cov")
    drive.scanRound()
    checkFalse(st.sensor.unloaded, "(cov) 走廊整段已載入：拒收不得歸因未載入")
    checkTrue(st.sensor.scanEndS < 60,
        "(cov) 請求 48m 的完成快照只掃到 " .. tostring(st.sensor.scanEndS) .. "m")
    -- 0928d：群長過可視距離時停留保持段收到已掃範圍內（鏈式停留）——收短的停留可以承諾，
    --   原線（回線段在掃描帶外）不行
    local okNear, _, varNear, _, _, _, _, dNear = MDAD.Drive.debugSweepFallbacks(0, 1, 8, 60, 80, 2, "cov")
    checkTrue(okNear ~= true or (varNear == "stay" and dNear + st.bodyReach <= st.sensor.scanEndS + 1e-6),
        "(cov) hold 段 60m 起就沒掃到：未掃 ≠ 淨空，只准收短到已掃範圍的停留（ok=" .. tostring(okNear)
        .. " variant=" .. tostring(varNear) .. " d=" .. tostring(dNear) .. "）")
    checkEq(st.dodgeBuildReason, "coverage",
        "(cov) 拒收理由是沒掃到而不是未載入（實得 " .. tostring(st.dodgeBuildReason) .. "）")
    MDAD.HUD.perceptionDistance = function() return 200 end
    drive.scanRound()
    checkTrue(st.sensor.effectiveAheadM >= 199,
        "(cov) 幀時買得起時請求 200m 就真的掃到 200m（實得 "
            .. tostring(st.sensor.effectiveAheadM) .. "）")
    local okFar, offFar = MDAD.Drive.debugSweepFallbacks(0, 1, 8, 60, 80, 2, "cov")
    checkTrue(okFar == true and offFar == 2,
        "(cov) 同一 world、同一候選：掃到 200m 之後就收得下（實得 " .. tostring(okFar)
            .. "／offL " .. tostring(offFar) .. "）")

    -- ② (soft) 150m 外的三種軟訊號：收得到，但只做 approach envelope
    drive.putCorpse(150, 0)
    drive.putSpriteObject(152, 1, "fixtures_soft_far", false, true, false)
    drive.putVehicle(154, 0, false)
    drive.scanRound()
    checkTrue(st.sensor.corpseN > 0 and st.sensor.softN > 0 and st.sensor.movingVeh == true,
        "(soft) 200m 視界真的收到 150m 外的屍體／軟物／行進車")
    checkEq(st.sensor.zomN, 0,
        "(soft) 遠處屍體不進 softLookahead 窗：不擠掉近端軟縫點雲額度")
    checkTrue(type(st.lastSensorCap) == "number" and st.lastSensorCap > 30 + 1e-6,
        "(soft) 150m 外只給 approach envelope，不把當下壓成 30／25／20（實得 "
            .. tostring(st.lastSensorCap) .. "、理由 " .. tostring(st.lastSensorReason) .. "）")
    drive.clearCell(150, 0)
    drive.clearCell(152, 1)
    drive.clearVehicle(154, 0)
    -- 近端帽沒有被長視距改掉：進到 halfL + ZOMBIE_APPROACH_LEAD_M 窗內就是 CORPSE_CAP 平帽
    drive.putCorpse(6, 0)
    drive.scanRound()
    checkTrue(st.sensor.corpseN > 0, "(soft) 近端屍體進入減速帶")
    checkEq(st.lastSensorCap, 30, "(soft) 進到預留窗內仍守 CORPSE_CAP 30 平帽")
    checkEq(st.lastSensorReason, "corpse", "(soft) 近端平帽歸因屍體")
    drive.clearCell(6, 0)

    -- ③ (pre-a) 承諾線上「還沒開始側移」的當前點不吃 entry 的 shift-space 帽
    local _, cells = drive.putVehicleGeom(30, 0, 0, 2.5, 4.4, true)
    -- 承諾之後不讓 fixture 的假前進越過 offA（既有繞行情境同款）：凍結進度跑兩輪。
    drive.scanRound(true)
    drive.scanRound(true)
    checkTrue(st.dodging == true and st.dodgeStay == false
            and type(st.dodgeShapeDl) == "number" and st.dodgeShapeDl > 0
            and type(st.dodgeEntryLength) == "number" and st.dodgeEntryLength > 0
            and type(st.dodgeSpaceLat) == "number" and st.dodgeSpaceLat > 0,
        "(pre-a) 30m 外的停車真的承諾了一段有側移 entry 的繞行線")
    local fs = st.fstate
    local kNow = math.floor(st.lastSNow - fs.ovS0) + 1
    local kEntry = math.ceil(fs.offA - fs.ovS0) + 1
    checkTrue(kNow >= 1 and kEntry > kNow and kEntry < fs.ovN
            and fs.ovS0 + (kNow - 1) * MDADFollower.OV_STEP < fs.offA
            and fs.ovS0 + (kEntry - 1) * MDADFollower.OV_STEP >= fs.offA
            and fs.ovS0 + (kEntry - 1) * MDADFollower.OV_STEP < fs.offB,
        "(pre-a) 取樣點就位：當前點落在 a 之前、對照點落在 [a, b) 之內")
    -- 同一條真承諾線、同一組 margin／lat／reserve：兩點的唯一差別就是所在的轉場段。
    local capNow = MDAD.Drive.dodgePointCap(st, kNow, 3, st.dodgeSpaceLat, 0, false)
    local capEntry = MDAD.Drive.dodgePointCap(st, kEntry, 3, st.dodgeSpaceLat, 0, false)
    local realEntry = st.dodgeEntryLength
    st.dodgeEntryLength = realEntry * 0.3
    local shortNow = MDAD.Drive.dodgePointCap(st, kNow, 3, st.dodgeSpaceLat, 0, false)
    local shortEntry = MDAD.Drive.dodgePointCap(st, kEntry, 3, st.dodgeSpaceLat, 0, false)
    st.dodgeEntryLength = realEntry
    checkNear(shortNow, capNow, 1e-9,
        "(pre-a) 入口過渡長縮到三成：當前點的帽一動不動（它還沒開始側移）")
    checkTrue(shortEntry < capEntry - 1e-6,
        "(pre-a) 同一個縮短確實壓低了入口起點的帽（對照組有效，" .. tostring(capEntry)
            .. " → " .. tostring(shortEntry) .. "）")
    checkTrue(shortNow > shortEntry + 1e-6,
        "(pre-a) 短入口下當前點仍可全速接近（實得 " .. tostring(shortNow)
            .. " vs 入口 " .. tostring(shortEntry) .. "）")
    drive.clearVehicleGeom(cells)

    -- ④ (cap) 0.5m 分段的密路線：證明線橫跨的剖面段數遠超 LANE_MAX，但那不是段索引上限
    local dense = { pts = {}, segSurface = {}, segWidth = {} }
    for i = 1, 601 do
        dense.pts[2 * i - 1], dense.pts[2 * i] = (i - 1) * 0.5, 0
        if i < 601 then dense.segSurface[i], dense.segWidth[i] = "paved", 14 end
    end
    st = arm(dense, 300, "cap")
    drive.scanRound()
    drive.scanRound()
    checkTrue(st.sensor.effectiveAheadM >= 199,
        "(cap) 密路線同樣掃到 200m（實得 " .. tostring(st.sensor.effectiveAheadM) .. "）")
    checkTrue(st.curveVerifiedUntilS >= 199,
        "(cap) 200m 的彎道證明整段有效（實得 " .. tostring(st.curveVerifiedUntilS) .. "）")
    checkTrue(MDADFollower.segIndexAt(st.profile, st.curveVerifiedUntilS)
            - MDADFollower.segIndexAt(st.profile, st.lastSNow) + 1 > MDADFollower.LANE_MAX,
        "(cap) 證明線橫跨的剖面段數超過 LANE_MAX " .. tostring(MDADFollower.LANE_MAX)
            .. "（舊制拿它夾 rangeN 的反例）")
    checkEq(st.verifyLineReason, "ok",
        "(cap) 密分段不得讓證明線以 capacity 失敗（實得 "
            .. tostring(st.verifyLineReason) .. "）")

    drive.frameMs(wasMs)
    MDAD.Drive.stop(0, nil)
    MDAD.HUD.perceptionDistance, MDAD.HUD.zombieDodge = oldPerception, oldDodgeZ
    MDAD.Drive.setSlowPref(0, "corpse", oldCorpse)
    MDAD.Drive.setGear(0, oldGear)
    MinidoracatMiniMapAPI.navApiVersion = oldApi
    drive.nav.route, drive.nav.tx, drive.nav.ty, drive.nav.state =
        oldRoute, oldTx, oldTy, oldNavState
    drive.world, drive.vehGeo, SandboxVars, dveh, getSpecificPlayer =
        oldWorld, oldGeo, oldSandbox, oldVeh, oldGet
end
drive.scenarioPerceptionRange()

function drive.scenarioVisibilityBraking()
    scenario("可視制動：空路輪間波動不鎖輪，真未知前緣仍可停車")
    local oldWorld, oldGeo, oldSandbox, oldVeh, oldGet =
        drive.world, drive.vehGeo, SandboxVars, dveh, getSpecificPlayer
    local oldApi, oldGear = MinidoracatMiniMapAPI.navApiVersion, MDAD.Drive.getGear(0)
    local oldPerception, oldZ = MDAD.HUD.perceptionDistance, MDAD.HUD.zombieDodge
    local oldRoute, oldTx, oldTy, oldState =
        drive.nav.route, drive.nav.tx, drive.nav.ty, drive.nav.state
    local wasMs = drive.frameMs(20)
    MDAD.Drive.stop(0, nil)
    getSpecificPlayer = function(n) if n == 0 then return dp end end
    MinidoracatMiniMapAPI.navApiVersion = 5
    setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false,
        AutoDriveMaxSpeed = 120, RightLaneBias = 0 })
    MDAD.Drive.setGear(0, 4)
    MDAD.HUD.zombieDodge = function() return false end
    dveh = newVehicle({ battery = newItem("Base.CarBattery", { uses = 0.8 }),
        engineRunning = true, mass = 1330, speed = 20, maxSpeed = 85,
        bodyW = 1.62, bodyL = 3.62, comX = 0, comZ = 0.12, profileFull = true,
        enginePower = 4100, brakingForce = 112, wheelFriction = 1.5, tireFriction = 1.5 })
    local st
    local function arm(perception)
        MDAD.Drive.stop(0, nil)
        drive.fillWorld(-12, 900, -9, 9)
        drive.putRoad(-12, 900, -8, 8)
        MDAD.HUD.perceptionDistance = function() return perception end
        dveh._x, dveh._y, dveh._speed, dveh._steering, dveh._stopped = 0, 0, 20, 0, false
        dveh._engine, dveh._driver = true, dp
        dp._vehicle, dp._dead, dp._local = dveh, false, true
        setHeading(dveh, 0)
        drive.nav.route = { pts = { 0, 0, 1000, 0 }, segSurface = { "paved" }, segWidth = { 16 } }
        drive.nav.tx, drive.nav.ty, drive.nav.state = 1000, 0, "ok"
        drive.frameMs(20)
        checkTrue(MDAD.Drive.start(dp), "(visibility) 空直路啟動")
        for _ = 1, 40 do driveTick(dp, dveh) end
        st = MDAD.Drive.debugSession(0)
        checkTrue(st.sensor.ready and st.sensor.hardN == 0 and not st.sensor.unloaded,
            "(visibility) 真Sensor已完成空路快照")
        driveReset(dveh)
    end
    -- 縱向模型只驗控制時序：讀真regulator命令，硬煞按一秒閂鎖，不假裝車瞬間跟上目標。
    -- 低幀階段仍保留56格/幀預算；這不是Bullet或FPS效能驗證。
    local function advance(dt)
        local v = dveh._speed / 3.6
        local acc = -2.3
        if nowMs < st.forceBrakeUntil then
            acc = -13
        elseif dveh._regulator and dveh._speed < (dveh._regSpeed or 0) then
            acc = 2.5
        end
        local nv = math.max(0, v + acc * dt)
        dveh._x = dveh._x + (v + nv) * 0.5 * dt
        dveh._speed = nv * 3.6
        drive.mult = dt * 48
        nowMs = nowMs + dt * 1000
        driveTick(dp, dveh)
    end
    for case, distance in ipairs({ 48, 80, 80 }) do
        arm(distance)
        local label = distance .. (case == 3 and "m 固定50ms" or "m 漸變幀時")
        local elapsed, minSpeed, maxSpeed = 0, math.huge, 0
        while elapsed < 36 and MDAD.Drive.isActive(0) do
            local dt = case == 3 and 0.05
                or 0.02 + 0.03 * math.max(0, 1 - math.abs(elapsed - 20) / 10)
            advance(dt)
            elapsed = elapsed + dt
            maxSpeed = math.max(maxSpeed, dveh._speed)
            if elapsed > 10 then minSpeed = math.min(minSpeed, dveh._speed) end
        end
        checkTrue(MDAD.Drive.isActive(0), "(visibility) 空路保持自駕 " .. distance)
        checkEq(drive.calls.forceBrake, 0,
            "(visibility) 輪間更新與正常幀時變化不觸發一秒硬煞 " .. label)
        checkTrue(maxSpeed > 40 and minSpeed > 20,
            "(visibility) 真命令驅動前進，不以全程龜速或煞停換假綠 " .. label
            .. "（峰值 " .. maxSpeed .. "、最低 " .. minSpeed .. "）")
        -- 0924c：巡航可視帳用舒適與緊急之間的煞車、煞停視界按准開速度算——空路要真的貼到
        -- 車輛極速 85（舊制 64／77／46：可視帳只用舒適煞車，且 gate visibility 疊 ungated 上限）。
        checkTrue(dveh._speed >= (case == 3 and 50 or 80),
            "(visibility) 空路巡航貼近上限 " .. label .. "（末速 " .. dveh._speed .. "）")
    end
    arm(80)
    -- 同一份已驗證前綴，載入旗標解除只能增加證據，不能降低命令。
    local realStep = MDADSensor.step
    MDADSensor.step = function() return false end
    st.sensor.scanEndS, st.sensor.unloadedS = st.lastSNow + 40, st.lastSNow + 40
    st.sensor.unloaded, st.sensor.stamp = true, nowMs
    driveTick(dp, dveh)
    local before = st.cmdV
    st.sensor.unloaded = false
    driveTick(dp, dveh)
    checkTrue(st.cmdV + 1e-9 >= before,
        "(visibility) 同距離載入完成不產生限速斷層")
    -- 不再有新快照，車仍須在已掃前緣內停下；不能把平滑誤寫成略過未知。
    st.sensor.scanEndS, st.sensor.unloadedS = st.lastSNow + 15, st.lastSNow + 15
    st.sensor.unloaded, st.sensor.stamp = true, nowMs
    dveh._speed = 60
    driveReset(dveh)
    driveTick(dp, dveh)
    checkTrue(drive.calls.forceBrake > 0,
        "(visibility) 60km/h僅剩15m仍立即緊急煞車")
    local frontier = st.sensor.scanEndS
    for _ = 1, 100 do advance(0.02) end
    checkTrue(dveh._speed < 1 and dveh._x + st.vehicleProfile.halfL < frontier,
        "(visibility) 前緣不再更新時，真命令在未知區前停穩")
    -- (terminal-hard) 0924e E2E：MAX 檔滑行到站，實速落後剖面 3-4 km/h，終點前 7m、18 km/h 撞上
    --   硬煞紅線一秒鎖輪。前緣＝路線終點時終點不是障礙，硬煞帳不扣障礙緩衝。違規證明：拿掉即紅。
    do
        MDADSensor.step = realStep
        arm(80)
        MDADSensor.step = function() return false end
        local len = st.profile.length
        dveh._x, dveh._speed = len - 7, 20
        MDAD.Drive.clearLaneProof(st) -- 瞬移到終點前：舊 proof 已在車後（真實行駛會逐輪重建）
        st.sensor.scanEndS, st.sensor.unloadedS = len, len
        st.sensor.unloaded, st.sensor.stamp = false, nowMs
        driveReset(dveh)
        driveTick(dp, dveh)
        checkTrue(st.visibilityHardKmh > 20 * 1.2,
            "(terminal-hard) 終點前 7m 的硬煞紅線不把終點當障礙（實得 " .. st.visibilityHardKmh .. "）")
        checkEq(drive.calls.forceBrake, 0, "(terminal-hard) 20 km/h 滑向終點不鎖輪")
        -- 對照：同距離但前緣是未知區（非終點）仍硬煞
        dveh._x = len - 14
        MDAD.Drive.clearLaneProof(st)
        st.sensor.scanEndS, st.sensor.unloadedS = len - 7, len - 7
        st.sensor.unloaded, st.sensor.stamp = true, nowMs
        dveh._speed = 40
        driveReset(dveh)
        driveTick(dp, dveh)
        checkTrue(drive.calls.forceBrake > 0, "(terminal-hard) 未知前緣仍緊急煞車")
    end
    -- (terminal-cruise) 1002l：前緣＝路線終點時巡航帳＝硬煞帳，反應時間只算致動延遲（VIS_TERMINAL_TAU）、不扣
    --   障礙緩衝、不套停滯保持；終點停車交給剖面的終點包絡（斷油＋Follower.STOP_ASSIST）。舊巡航帳在終點前
    --   15–28m 就把目標壓在剖面下 5–7 km/h（E2E rc52 抵達 20 趟全被它綁過）。違規證明：拿掉終點分支＝三條全紅。
    do
        MDADSensor.step = realStep
        arm(80)
        MDADSensor.step = function() return false end
        local len = st.profile.length
        dveh._x, dveh._speed = len - 20, 45
        MDAD.Drive.clearLaneProof(st)
        st.sensor.scanEndS, st.sensor.unloadedS = len, len
        st.sensor.unloaded, st.sensor.stamp = false, nowMs
        driveReset(dveh)
        driveTick(dp, dveh)
        local tune = MDAD.Drive.debugTune()
        local visBrake = math.min(st.safeBrake * tune.EMERGENCY_BRAKE_GAIN, tune.EMERGENCY_BRAKE_MAX)
        checkNear(st.visibilityCap, st.visibilityHardKmh, 1e-9,
            "(terminal-cruise) 前緣＝終點：巡航帳＝硬煞帳（" .. tostring(st.visibilityCap) .. "）")
        checkNear(st.visibilityHardKmh, MDADDynamics.approachCapKmh(len - st.lastSNow, 0, tune.VIS_TERMINAL_TAU, visBrake),
            1e-6, "(terminal-cruise) 終點硬煞帳的反應時間只算致動延遲（" .. tostring(st.visibilityHardKmh) .. "）")
        checkTrue(st.lastCapReason ~= "visibility",
            "(terminal-cruise) 終點前 20m、45 km/h：目標由剖面終點包絡決定，不被可視帳先壓（" .. tostring(st.lastCapReason) .. "）")
    end
    -- (terminal-comfort) 1002t：舒適檔（計畫制動 3.0）的終點包絡上限與終點硬煞帳都用車輛煞車能力（不套風格），
    --   兩檔一樣快停進終點（使用者：強力減速、緊急煞車都可以）。違規證明：硬煞帳改回風格計畫制動＝紅。
    do
        MDAD.Drive.setGear(0, 3)
        MDADSensor.step = realStep
        arm(80)
        MDADSensor.step = function() return false end
        local len = st.profile.length
        dveh._x, dveh._speed = len - 20, 45
        MDAD.Drive.clearLaneProof(st)
        st.sensor.scanEndS, st.sensor.unloadedS = len, len
        st.sensor.unloaded, st.sensor.stamp = false, nowMs
        driveReset(dveh)
        driveTick(dp, dveh)
        local tune = MDAD.Drive.debugTune()
        local p, k = st.profile, st.profile.n - 1
        local termBrake = math.min(st.safeBrake * tune.EMERGENCY_BRAKE_GAIN, tune.EMERGENCY_BRAKE_MAX)
        checkTrue(st.horizonMinBrake < st.safeBrake - 1,
            "(terminal-comfort) 舒適檔計畫制動（" .. tostring(st.horizonMinBrake) .. "）低於車輛能力（"
            .. tostring(st.safeBrake) .. "）")
        checkNear(st.visibilityHardKmh, MDADDynamics.approachCapKmh(len - st.lastSNow, 0, tune.VIS_TERMINAL_TAU, termBrake),
            1e-6, "(terminal-comfort) 終點硬煞帳用車輛緊急帳（" .. tostring(st.visibilityHardKmh) .. "）")
        checkNear(p.coastRate[k], math.min(p.segStopCoast[k] + MDADFollower.STOP_ASSIST,
            p.segStopBrake[k] * MDADFollower.STOP_BRAKE_RATIO), 1e-9,
            "(terminal-comfort) 終點包絡上限＝車輛煞車×1.5（" .. tostring(p.coastRate[k]) .. "）")
        checkTrue(p.coastRate[k] > 3.0 * MDADFollower.STOP_BRAKE_RATIO + 1,
            "(terminal-comfort) 舒適檔終點減速不再卡在 4.5（" .. tostring(p.coastRate[k]) .. "）")
        MDAD.Drive.setGear(0, 4)
    end

    local function learnBrake(deceleration, startSpeed, episodes)
        MDADSensor.step = realStep
        arm(120)
        MDADSensor.step = function() return false end
        st.sensor.scanEndS = 900
        local prior = st.priorBrake
        for _ = 1, episodes do
            dveh._speed = startSpeed
            st.kinPrevMs, st.kinPrevV = nowMs, startSpeed / 3.6
            st.forceBrakeUntil, st.ewmaSuppressUntil = nowMs + 1000, 0
            for frame = 1, 50 do
                -- 前100ms無反應，其後固定真減速度；停妥尾段仍在引擎煞車閂鎖內。
                local v = frame <= 5 and startSpeed
                    or math.max(0, startSpeed - deceleration * 3.6 * (frame - 5) * 0.02)
                dveh._speed, dveh._x = v, dveh._x + v / 3.6 * 0.02
                nowMs, drive.mult = nowMs + 20, 0.96
                st.sensor.stamp = nowMs
                driveTick(dp, dveh)
            end
        end
        checkTrue(MDAD.Drive.isActive(0), "(brake-observation) 觀測未破壞行程")
        return st.safeBrake / prior, st.brakeTime
    end
    local strong, observed = learnBrake(13, 36, 8)
    checkTrue(observed > 1, "(brake-observation) 強煞車仍有真觀測，不是停用學習")
    checkTrue(strong > 0.95,
        "(brake-observation) 起始延遲與停車尾段不把13m/s²學成弱煞車（比例 " .. strong .. "）")
    learnBrake(13, 36, 40)
    checkNear(st.brakeConfidence, 1, 1e-9, "(brake-observation) 真強煞車累積到完整信心")
    checkTrue(st.visibilityHardKmh > st.visibilityCap + 1,
        "(brake-observation) 強煞車信心收斂後仍保留兩個制動界限")
    local weak = learnBrake(1, 50, 8)
    checkTrue(weak < 0.85, "(brake-observation) 真弱煞車仍收緊能力（比例 " .. weak .. "）")
    local failed = learnBrake(0, 50, 8)
    checkTrue(failed < 0.8, "(brake-observation) 車仍高速卻毫無減速，不得拒收零觀測")
    st.brakeLower, st.brakeConfidence, st.brakeTime = 1, 1, 20
    nowMs = nowMs + 20
    st.sensor.stamp = nowMs
    driveTick(dp, dveh)
    checkNear(st.visibilityHardKmh, MDADDynamics.visibilityCapKmh(
            st.sensor.scanEndS - st.lastSNow, 0.5, 1, st.vehicleProfile.halfL), 1e-6,
        "(brake-observation) 已證實的弱煞車不能在緊急界限再乘2.5")
    checkTrue(st.visibilityCap <= st.visibilityHardKmh + 1e-9,
        "(brake-observation) 弱煞車下巡航帽不高於緊急界限")
    local parked, parkedTime = learnBrake(0, 0.5, 1)
    checkNear(parked, 1, 1e-9, "(brake-observation) 已近停的閂鎖尾段不降低煞車能力")
    checkEq(parkedTime, 0, "(brake-observation) 已近停的尾段不累積學習信心")
    MDADSensor.step = realStep
    MDAD.Drive.stop(0, nil)
    drive.frameMs(wasMs)
    MDAD.HUD.perceptionDistance, MDAD.HUD.zombieDodge = oldPerception, oldZ
    MDAD.Drive.setGear(0, oldGear)
    MinidoracatMiniMapAPI.navApiVersion = oldApi
    drive.nav.route, drive.nav.tx, drive.nav.ty, drive.nav.state = oldRoute, oldTx, oldTy, oldState
    drive.world, drive.vehGeo, SandboxVars, dveh, getSpecificPlayer =
        oldWorld, oldGeo, oldSandbox, oldVeh, oldGet
end
drive.scenarioVisibilityBraking()

-- 可視時間模型（2026-09-27 正式服 222 段 visibility 一秒鎖輪定罪）。真 Sensor 建第一張空路快照後
-- 停掉 Sensor.step，手動擺可視前緣，驗三個機制：
--   (vt-hitch)  遊戲卡住 1.6 秒（牆鐘前進、世界沒動）：硬煞帳不因快照年齡崩。
--               違規證明：硬煞帳 tau 改回「年齡＋0.25」＝紅。
--   (vt-stream) 未載入前緣每次停 1.5 秒才往前跳 40m（MP 區塊串流）：80 km/h 跟著跑三個週期不鎖輪、
--               不爬行。違規證明：VIS_UNLOADED_HOLD_S＝0 且 VIS_ASSIST_MAX＝0＝紅。
--   (vt-assist) 實速高於巡航帽：同一個 impulse 槽沿車身中線反向補減速，不產生 yaw；未超速不補。
function drive.scenarioVisibilityTiming()
    scenario("可視時間模型：卡頓不崩硬煞帳、串流前緣停滯不鎖輪、超速沿中線補減速")
    local oldWorld, oldGeo, oldSandbox, oldVeh, oldGet =
        drive.world, drive.vehGeo, SandboxVars, dveh, getSpecificPlayer
    local oldApi, oldGear = MinidoracatMiniMapAPI.navApiVersion, MDAD.Drive.getGear(0)
    local oldPerception, oldZ = MDAD.HUD.perceptionDistance, MDAD.HUD.zombieDodge
    local oldRoute, oldTx, oldTy, oldState =
        drive.nav.route, drive.nav.tx, drive.nav.ty, drive.nav.state
    local wasMs = drive.frameMs(20)
    local realStep = MDADSensor.step
    MDAD.Drive.stop(0, nil)
    getSpecificPlayer = function(n) if n == 0 then return dp end end
    MinidoracatMiniMapAPI.navApiVersion = 5
    setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false,
        AutoDriveMaxSpeed = 120, RightLaneBias = 0 })
    MDAD.Drive.setGear(0, 4)
    MDAD.HUD.zombieDodge = function() return false end
    dveh = newVehicle({ battery = newItem("Base.CarBattery", { uses = 0.8 }),
        engineRunning = true, mass = 1330, speed = 20, maxSpeed = 120,
        bodyW = 1.62, bodyL = 3.62, comX = 0, comZ = 0.12, profileFull = true,
        enginePower = 4100, brakingForce = 112, wheelFriction = 1.5, tireFriction = 1.5 })
    local st
    local function arm()
        MDADSensor.step = realStep
        MDAD.Drive.stop(0, nil)
        drive.fillWorld(-12, 1500, -9, 9)
        drive.putRoad(-12, 1500, -8, 8)
        MDAD.HUD.perceptionDistance = function() return 120 end
        dveh._x, dveh._y, dveh._speed, dveh._steering, dveh._stopped = 0, 0, 20, 0, false
        dveh._engine, dveh._driver = true, dp
        dp._vehicle, dp._dead, dp._local = dveh, false, true
        setHeading(dveh, 0)
        drive.nav.route = { pts = { 0, 0, 1400, 0 }, segSurface = { "paved" }, segWidth = { 16 } }
        drive.nav.tx, drive.nav.ty, drive.nav.state = 1400, 0, "ok"
        drive.frameMs(20)
        checkTrue(MDAD.Drive.start(dp), "(vt) 空直路啟動")
        for _ = 1, 40 do driveTick(dp, dveh) end
        st = MDAD.Drive.debugSession(0)
        checkTrue(st.sensor.ready and st.sensor.hardN == 0, "(vt) 真Sensor已完成空路快照")
        MDADSensor.step = function() return false end
        driveReset(dveh)
    end
    -- 縱向模型：真 regulator 命令＋滑行 2.3＋production 要求的中線補減速；硬煞按一秒閂鎖。
    local function advance(dt)
        local v = dveh._speed / 3.6
        local acc = -2.3 - (st.visAssistDecel or 0)
        if nowMs < st.forceBrakeUntil then
            acc = -13
        elseif dveh._regulator and dveh._speed < (dveh._regSpeed or 0) then
            acc = 2.5
        end
        local nv = math.max(0, v + acc * dt)
        dveh._x = dveh._x + (v + nv) * 0.5 * dt
        dveh._speed = nv * 3.6
        drive.mult = dt * 48
        nowMs = nowMs + dt * 1000
        driveTick(dp, dveh)
    end
    local function front(ahead, unloaded)
        local sen = st.sensor
        sen.scanEndS = st.lastSNow + ahead
        sen.unloaded = unloaded == true
        sen.unloadedS = unloaded and sen.scanEndS or nil
        sen.stamp = nowMs
    end

    -- (vt-hitch)
    arm()
    dveh._speed = 60
    front(35, false)
    driveTick(dp, dveh)
    local hardBefore = st.visibilityHardKmh
    checkEq(drive.calls.forceBrake, 0, "(vt-hitch) 60 km/h、前緣 35m：卡頓前不硬煞")
    nowMs = nowMs + 1600 -- 世界沒前進（車位、快照都沒變），只有牆鐘走了 1.6 秒
    driveTick(dp, dveh)
    checkEq(drive.calls.forceBrake, 0, "(vt-hitch) 卡住 1.6 秒後第一幀不因快照年齡鎖輪")
    checkNear(st.visibilityHardKmh, hardBefore, 1e-6, "(vt-hitch) 同距離同速的硬煞帳不隨牆鐘年齡縮")

    -- (vt-stream)：先正常跑，再把補減速關掉只靠前緣停滯保持（兩道各自獨立承重）。
    local tn = MDAD.Drive.debugTune()
    local assistMax = tn.VIS_ASSIST_MAX
    for pass = 1, 2 do
        if pass == 2 then tn.VIS_ASSIST_MAX = 0 end
        arm()
        dveh._speed = 80
        local base = st.lastSNow + 70
        local minSpeed, assisted, cycles = math.huge, false, 0
        local nextStamp = nowMs
        local stallUntil = nowMs + 1500
        front(base - st.lastSNow, true)
        while cycles < 3 and MDAD.Drive.isActive(0) do
            if nowMs >= stallUntil then
                base, stallUntil, cycles = base + 40, nowMs + 1500, cycles + 1
            end
            if nowMs >= nextStamp then -- 輪照常完成，只是前緣不動（區塊還沒送到）
                st.sensor.scanEndS, st.sensor.unloadedS = base, base
                st.sensor.unloaded, st.sensor.stamp = true, nowMs
                nextStamp = nowMs + 400
            end
            advance(0.02)
            if cycles >= 1 then minSpeed = math.min(minSpeed, dveh._speed) end
            if (st.visAssistDecel or 0) > 0 then assisted = true end
        end
        local tag = pass == 1 and "" or "（只靠停滯保持）"
        checkEq(drive.calls.forceBrake, 0, "(vt-stream) 串流前緣每次停 1.5 秒：三個週期都不鎖輪" .. tag)
        checkTrue(minSpeed > 35, "(vt-stream) 仍以可用速度前進，不爬行（最低 "
            .. string.format("%.1f", minSpeed) .. "）" .. tag)
        if pass == 1 then
            checkTrue(assisted, "(vt-stream) 前緣逼近時有用中線補減速，而不是等硬煞")
        end
    end
    tn.VIS_ASSIST_MAX = assistMax

    -- (vt-assist)
    arm()
    dveh._speed = 80
    front(40, false)
    dveh._imp.frame, dveh._imp.x, dveh._imp.z, dveh._imp.torqueY = 0, 0, 0, 0
    driveTick(dp, dveh)
    local imp = dveh._imp
    local lon = imp.x * dveh._fwdX + imp.z * dveh._fwdY
    checkTrue(st.visibilityCap < 80 - 5 and st.visAssistDecel > 0,
        "(vt-assist) 80 km/h 高於巡航帽 " .. string.format("%.1f", st.visibilityCap) .. "：要求補減速")
    checkTrue(imp.frame == 1 and lon < 0,
        "(vt-assist) 同一個 impulse 槽帶反向中線分量（lon " .. string.format("%.1f", lon) .. "）")
    checkEq(drive.calls.forceBrake, 0, "(vt-assist) 補減速不是一秒硬煞")
    front(200, false)
    dveh._speed = 60
    driveReset(dveh)
    dveh._imp.frame = 0
    driveTick(dp, dveh)
    checkEq(st.visAssistDecel, 0, "(vt-assist) 未超過巡航帽不補減速")

    MDADSensor.step = realStep
    MDAD.Drive.stop(0, nil)
    drive.frameMs(wasMs)
    MDAD.HUD.perceptionDistance, MDAD.HUD.zombieDodge = oldPerception, oldZ
    MDAD.Drive.setGear(0, oldGear)
    MinidoracatMiniMapAPI.navApiVersion = oldApi
    drive.nav.route, drive.nav.tx, drive.nav.ty, drive.nav.state = oldRoute, oldTx, oldTy, oldState
    drive.world, drive.vehGeo, SandboxVars, dveh, getSpecificPlayer =
        oldWorld, oldGeo, oldSandbox, oldVeh, oldGet
end
drive.scenarioVisibilityTiming()

-- 會車／跟車（2026-09-24 雙客戶端 E2E 定罪：舊制帶內有行進車就壓 20、<10m 煞停，兩台自駕
-- 面對面停死；人工車佔中線只煞不閃被迎面撞上）。真 Sensor＋真 Driver，假車用 putVehicleGeom
-- 的真 OBB，兩輪之間真的移動（同一台車同一個 id，Sensor 才算得出沿路線速度）。
--   (keep)     沙盒 1.0＝右車道中心：8m 路常駐 2.0（舊制 1.0＝貼中線）。
--   (own-lane) 對向車在它自己的車道：不衝突、不減速、不側移。
--   (center)   對向車佔中線：靠右錯開到路面餘裕、配合減速，不停車。
--   (yield)    7m 路右邊讓不開：減速停等讓對方先過（followHold＝合法停等）。
--   (lead)     同向前車照它的速度跟，不再是舊的 20 平帽。
function drive.scenarioTraffic()
    scenario("會車／跟車：對向照車道錯開、佔中線靠右閃、讓不開才停等、前車照速跟")
    local oldClient = clientFlag
    clientFlag = true -- 對向來車只存在於 MP（0928c：借對向車道短設計只在 MP 套）
    local oldWorld, oldGeo, oldSandbox, oldVeh, oldGet =
        drive.world, drive.vehGeo, SandboxVars, dveh, getSpecificPlayer
    local oldApi, oldGear, oldZ = MinidoracatMiniMapAPI.navApiVersion, MDAD.Drive.getGear(0), MDAD.HUD.zombieDodge
    local oldRoute, oldTx, oldTy, oldState =
        drive.nav.route, drive.nav.tx, drive.nav.ty, drive.nav.state
    local wasMs = drive.frameMs(20)
    MDAD.Drive.stop(0, nil)
    getSpecificPlayer = function(n) if n == 0 then return dp end end
    MinidoracatMiniMapAPI.navApiVersion = 5
    MDAD.Drive.setGear(0, 3)
    MDAD.HUD.zombieDodge = function() return false end
    dveh = newVehicle({ battery = newItem("Base.CarBattery", { uses = 0.8 }),
        engineRunning = true, mass = 1200, speed = 30, maxSpeed = 120,
        bodyW = 1.8, bodyL = 4.6, comX = 0, comZ = 0, profileFull = true,
        enginePower = 4000, brakingForce = 100, wheelFriction = 1.5, tireFriction = 1.5 })
    local st
    local function arm(width)
        MDAD.Drive.stop(0, nil)
        drive.vehGeo = {}
        drive.fillWorld(-12, 220, -10, 10)
        setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false,
            AutoDriveMaxSpeed = 120, RightLaneBias = 1 })
        dveh._x, dveh._y, dveh._speed, dveh._steering, dveh._stopped = 0, 0, 30, 0, false
        dveh._engine, dveh._driver = true, dp
        dp._vehicle, dp._dead, dp._local = dveh, false, true
        setHeading(dveh, 0)
        drive.nav.route = { pts = { 0, 0, 200, 0 }, segSurface = { "paved" }, segWidth = { width },
            navVersion = 4 }
        drive.nav.tx, drive.nav.ty, drive.nav.state = 200, 0, "ok"
        checkTrue(MDAD.Drive.start(dp), "(traffic) " .. width .. "m 直路啟動")
        for _ = 1, 30 do driveTick(dp, dveh) end
        st = MDAD.Drive.debugSession(0)
        checkTrue(st.sensor.ready, "(traffic) 真 Sensor 已完成快照")
    end
    -- 真 OBB 行進車；move 保留同一台（同 id）重登記佔位格，Sensor 以兩輪位移算速度
    local function car(cx, cy, heading)
        local v, cells = drive.putVehicleGeom(cx, cy, heading, 1.8, 4.6, false)
        v._cells, v._h = cells, heading
        return v
    end
    local function move(v, dx, dy)
        drive.clearVehicleGeom(v._cells)
        v._x, v._y = v._x + dx, v._y + (dy or 0)
        local fx, fy = math.cos(v._h), math.sin(v._h)
        v._cells = {}
        for gx = math.floor(v._x - 4), math.floor(v._x + 4) do
            for gy = math.floor(v._y - 3), math.floor(v._y + 3) do
                local dx2, dy2 = gx + 0.5 - v._x, gy + 0.5 - v._y
                if math.abs(dx2 * fx + dy2 * fy) <= 2.3 + 0.5 and math.abs(-dx2 * fy + dy2 * fx) <= 0.9 + 0.5 then
                    drive.vehGeo[gx * 100000 + gy] = v
                    v._cells[#v._cells + 1] = gx * 100000 + gy
                end
            end
        end
    end
    local function traffic(v, dx, rounds)
        for _ = 1, rounds do
            drive.scanRound()
            move(v, dx)
        end
        drive.scanRound()
        driveReset(dveh)
        driveTick(dp, dveh)
    end
    local TRAFFIC = { traffic = true, ["traffic-yield"] = true, moving = true }
    -- 提示計數：前面情境可能換掉 HaloTextHelper，這裡自己接住綠字
    local shown, oldHalo = {}, HaloTextHelper
    HaloTextHelper = { addGoodText = function(_, text) shown[#shown + 1] = text end,
        addBadText = function() end, addText = function() end }
    local function shownN(key)
        local n = 0
        for _, t in ipairs(shown) do if t == key then n = n + 1 end end
        return n
    end

    -- (keep)
    arm(8)
    checkNear(st.fstate.laneBias, 2.0, 0.05, "(keep) 沙盒 1.0 在 8m 路＝右車道中心 2.0（實得 "
        .. tostring(st.fstate.laneBias) .. "）")
    checkNear(MDADFollower.laneBiasAt(st.profile, st.fstate.laneBias, st.fstate.idx), 2.0, 0.05,
        "(keep) 右車道中心在路面餘裕內，control 不再夾回")

    -- (own-lane) 對向車在自己的車道（我方左側 l=−2）
    local on = car(60, -2, math.pi)
    traffic(on, -3, 2)
    checkTrue(st.sensor.trfN >= 1, "(own-lane) Sensor 收到行進車")
    checkEq(st.trfOnGap, nil, "(own-lane) 對向車沒壓到我方車道＝不衝突")
    checkTrue(not TRAFFIC[st.lastCapReason] and not st.followHold,
        "(own-lane) 不為對向車減速或停等（capReason=" .. tostring(st.lastCapReason) .. "）")
    checkNear(st.fstate.laneBias, 2.0, 0.05, "(own-lane) 不側移")
    drive.clearVehicleGeom(on._cells)

    -- (center) 8m 路對向車佔中線：靠右錯開到路面餘裕（2.1）、限速錯車，不停等
    arm(8)
    on = car(55, 0, math.pi)
    traffic(on, -3, 2)
    checkTrue(st.trfOnGap ~= nil and not st.trfOnYield, "(center) 衝突但右邊讓得開：錯車不讓車")
    checkTrue(st.trfOnWant ~= nil and st.trfOnWant > 2.05,
        "(center) 目標 lane 往右推（實得 " .. tostring(st.trfOnWant) .. "）")
    checkEq(st.lastSensorReason, "traffic", "(center) 感知帽是錯車限速（最終帽可能被對線等更低的帽取代）")
    checkTrue(st.lastSensorCap < 70, "(center) 錯車限速包絡低於檔位上限（實得 " .. tostring(st.lastSensorCap) .. "）")
    checkFalse(st.followHold, "(center) 不停等")
    local lb0, wantL = st.fstate.laneBias, st.trfOnWant
    drive.scanRound()
    checkTrue(st.fstate.laneBias > lb0 + 1e-6 or st.fstate.laneBias > 2.05,
        "(center) laneBias 真的往右移（" .. tostring(lb0) .. " → " .. tostring(st.fstate.laneBias) .. "）")
    drive.clearVehicleGeom(on._cells)
    -- (center-done) 已閃到錯車 lane：交會前一刻不得再為「側移時間＋LEAD」煞停
    --   （E2E fix1b：側移早已完成，對向車 4m 前 (gap/0.6s − vO) 算成負值 → forceBrake 停死）
    dveh._y = MDADFollower.laneBiasAt(st.profile, wantL, st.fstate.idx)
    on = car(18, 0, math.pi)
    traffic(on, -3, 2)
    checkTrue(st.trfOnGap ~= nil and st.trfOnGap < 8 and not st.trfOnYield,
        "(center-done) 對向車已逼近（gap " .. tostring(st.trfOnGap) .. "）且錯得開")
    checkFalse(st.followHold, "(center-done) 側移已完成：交會前只限淨距速度，不停等")
    checkTrue(st.lastSensorCap >= MDAD.Drive.debugTune().TRAFFIC_PASS_MIN_KMH - 1e-9,
        "(center-done) 錯車速度不低於淨距限速下限（實得 " .. tostring(st.lastSensorCap) .. "）")
    drive.clearVehicleGeom(on._cells)
    dveh._y = 0
    checkTrue(shownN("UI_MinidoracatAutoDrive_TrafficPass") >= 1, "(center) 為對向車偏離車道時跳錯車提示")

    -- (edge) 1001b：7m 路對向車佔中線——會車時可貼到路緣（keep 0.1，平常 0.6）：右邊擠得出錯車淨距就
    -- 錯車不讓車，control／期望線同步用 fstate.laneKeep。違規證明：trafficScan 帶寬退回 LANE_BIAS_KEEP 即紅。
    arm(7)
    on = car(26, 0, math.pi)
    traffic(on, -2, 2)
    checkTrue(st.trfOnGap ~= nil and not st.trfOnYield,
        "(edge) 7m 路佔中線的對向車：貼路緣錯得開，不讓車（want " .. tostring(st.trfOnWant) .. "）")
    checkTrue(st.trfOnWant ~= nil and st.trfOnWant > MDADFollower.laneBiasAt(st.profile, 9, st.fstate.idx) + 0.3,
        "(edge) 錯車 lane 超過平常的路緣保留")
    drive.scanRound()
    checkEq(st.fstate.laneKeep, MDAD.Drive.debugTune().TRAFFIC_EDGE_KEEP_M, "(edge) 側移期間 control 用會車的路緣保留")
    drive.clearVehicleGeom(on._cells)

    -- (yield) 6m 路：貼到路緣（1.6−0.1）也錯不開佔中線的對向車 → 靠近時停等讓車
    arm(6)
    on = car(26, 0, math.pi)
    traffic(on, -2, 2)
    checkTrue(st.trfOnGap ~= nil and st.trfOnYield, "(yield) 右邊讓不開：判讓車")
    checkEq(st.lastSensorReason, "traffic-yield", "(yield) 讓車帽")
    checkTrue(st.lastSensorCap < 30, "(yield) 遠距離先照停車包絡減速（實得 " .. tostring(st.lastSensorCap) .. "）")
    for _ = 1, 8 do
        if st.followHold then break end
        traffic(on, -2, 1)
    end
    checkTrue(st.followHold, "(yield) 對方逼近後合法停等（WAIT），不是撞上去")
    -- 讓玩家知道為什麼停：讓車提示跳一次，多輪停等不重複
    checkEq(shownN("UI_MinidoracatAutoDrive_TrafficYield"), 1, "(yield) 讓車提示跳一次，停等期間不重複")
    -- (yield-nolock) 1001a：讓車停等在 30 km/h 不鎖輪（鎖輪中方向盤沒用＝正式服 5m 路對撞直直撞上），改中線外力＋照常轉向；
    -- 低速才鎖輪停住。違規證明：hardBrake 的 nolock 條件拿掉 followHold 分支即紅。
    driveReset(dveh)
    dveh._speed = 30
    driveTick(dp, dveh)
    checkTrue(st.followHold and drive.calls.forceBrake == 0 and (st.visAssistDecel or 0) > 0,
        string.format("(yield-nolock) 30 km/h 讓車停等：不鎖輪、施減速外力（forceBrake %d、vad %s）",
            drive.calls.forceBrake, tostring(st.visAssistDecel)))
    driveReset(dveh)
    dveh._speed = 5
    driveTick(dp, dveh)
    checkTrue(st.followHold and drive.calls.forceBrake >= 1,
        "(yield-nolock) 5 km/h 讓車停等：鎖輪停住（forceBrake " .. drive.calls.forceBrake .. "）")
    drive.clearVehicleGeom(on._cells)

    -- (lead) 同向前車 30m 外以 ~10 m/s 前進：接近帽的出口速度＝前車速度，不是舊的 20 平帽
    arm(8)
    local lead = car(35, 2, 0)
    traffic(lead, 2.5, 2)
    checkTrue(st.trfLeadGap ~= nil and st.trfLeadV > 5,
        "(lead) 前車速度由兩輪位移算出（實得 " .. tostring(st.trfLeadV) .. "）")
    checkTrue(st.lastCapReason ~= "moving" or st.lastSensorCap > 20,
        "(lead) 前車在跑：不再壓到舊的 20 平帽（cap=" .. tostring(st.lastSensorCap) .. "）")
    drive.clearVehicleGeom(lead._cells)
    -- (lead-slow) 前車 ~6 km/h：跟車帽低於最低執行速＝停等，不被 GO 的 8 km/h 地板抬起來貼上去
    arm(8)
    lead = car(11.4, 2, 0)
    traffic(lead, 0.5, 2)
    checkTrue(st.trfLeadGap ~= nil and st.trfLeadV > 0.5 and st.trfLeadV * 3.6 < 8 / 0.7,
        "(lead-slow) 慢前車（v=" .. tostring(st.trfLeadV) .. "）")
    checkTrue(st.followHold, "(lead-slow) 帽低於 MIN_EXEC 就停等（capReason=" .. tostring(st.lastCapReason) .. "）")
    drive.clearVehicleGeom(lead._cells)
    -- (cross) 路口橫越車：還在行駛線外，但以橫向速度會在我方抵達前壓進來＝先算前車
    arm(8)
    local cross = car(30, 9, -math.pi / 2)
    traffic(cross, 0, 1)
    for _ = 1, 2 do drive.scanRound(); move(cross, 0, -1.2) end
    drive.scanRound()
    driveTick(dp, dveh)
    checkTrue(st.trfLeadGap ~= nil, "(cross) 橫越車以橫向速度外推＝前車（l0="
        .. tostring(st.sensor.trfL0[1]) .. " vl=" .. tostring(st.sensor.trfVl[1]) .. "）")
    drive.clearVehicleGeom(cross._cells)

    -- (park-out) 1002s：對向車正偏在它自己的路邊（繞它那側的東西），之後會回它的車道：承諾借道前的會車
    --   檢查取「現在的位置」與「它的常駐線」的聯集（E2E meet park 1002r 正面相撞）。違規證明：拿掉聯集即紅。
    do
        arm(8)
        local parkedO = car(40, 2, 0)
        parkedO._stopped = true
        local onO = car(75, -4.4, math.pi)
        traffic(onO, -3, 2)
        checkTrue(st.sensor.trfN >= 1 and st.sensor.trfL1[1] < -2.9,
            "(park-out) 對向車整台偏在它的路邊外側（l1=" .. tostring(st.sensor.trfL1[1]) .. "）")
        checkFalse(st.dodging, "(park-out) 對向車偏在路邊：會回它的車道，照樣不切出去")
        drive.clearVehicleGeom(onO._cells)
        drive.clearVehicleGeom(parkedO._cells)
        for k = #shown, 1, -1 do shown[k] = nil end -- (park) 下面數提示次數
    end
    -- (park) 我方車道停一台車、要切到對向車道繞：對向來車會進繞行段＝先別切出去（defer
    --   why=traffic，停在繞行起點前讓它過）；對向車走了才承諾繞行。
    arm(8)
    local parked = car(40, 2, 0)
    parked._stopped = true
    on = car(75, -2, math.pi)
    traffic(on, -3, 2)
    checkFalse(st.dodging, "(park) 對向車會進繞行段：不切出去")
    checkTrue(st.dodgeDeferCap ~= nil and st.dodgeDeferCap >= 0,
        "(park) 延後時套停在繞行起點前的接近帽（實得 " .. tostring(st.dodgeDeferCap) .. "）")
    local deferCap = st.dodgeDeferCap
    drive.scanRound()
    checkEq(shownN("UI_MinidoracatAutoDrive_TrafficWait"), 1, "(park) 在障礙後等對向車：提示跳一次、多輪不重複")
    drive.clearVehicleGeom(on._cells)
    for _ = 1, 3 do drive.scanRound() end
    checkTrue(st.dodging, "(park) 對向車離開後照常承諾繞行")
    checkTrue(st.dodgeDesignSpeed <= MDAD.Drive.debugTune().ONCOMING_DESIGN_KMH,
        "(park) 借對向車道：過渡段按短設計速（實得 " .. tostring(st.dodgeDesignSpeed) .. "）")
    -- 停點不貼著停車（b）：留爬行側移跑道，對向車過了之後不必倒車就能切出去
    local coastP = st.safeCoast > 0.5 and st.safeCoast or 0.5
    local atB = MDADDynamics.approachCapKmh(st.fstate.offB - st.lastSNow - 2.3, 0, 0.5, coastP)
    checkTrue(deferCap < atB - 1, "(park) 延後停點在 b 前留側移跑道（cap " .. tostring(deferCap)
        .. " < 停在 b 的 " .. tostring(atB) .. "）")
    -- (lead-dodge) 繞行線上的同向慢車：前車判定看承諾線，不是常駐線
    local slow = car(st.fstate.offB + 6, st.fstate.offL, 0)
    traffic(slow, 1.0, 2)
    checkTrue(st.trfLeadGap ~= nil, "(lead-dodge) 承諾線上的同向車＝前車（offL=" .. tostring(st.fstate.offL) .. "）")
    drive.clearVehicleGeom(slow._cells)
    for _ = 1, 2 do drive.scanRound() end
    -- (park-abort) 已承諾、還在切出去的過渡段（offB 前）才出現錯不開的對向車：放棄繞行回常駐線，
    --   不是停在半路（E2E park 變體：長過渡段已壓進對向車道 1m，停等＝被迎面撞上）
    checkTrue(st.lastSNow < st.fstate.offB, "(park-abort) 車仍在過渡段（rs < offB）")
    -- 對向車現位在承諾線回線段末端（d≈73）：那裡的 lane 已回常駐、不衝突；交會點（我方 30 km/h、
    -- 對方 ~12 m/s）落在切出去的過渡段才衝突——要看交會點（E2E park400 定罪）。
    local oldPd = MDAD.HUD.perceptionDistance
    MDAD.HUD.perceptionDistance = function() return 120 end
    drive.scanRound()
    on = car(80, -1.5, math.pi)
    traffic(on, -3, 2)
    checkTrue(st.sensor.trfN >= 1 and st.sensor.trfS0[1] > st.fstate.offD - 2,
        "(park-abort) 對向車現位在回線段末端之後（s0=" .. tostring(st.sensor.trfS0[1]) .. "）")
    checkFalse(st.dodging, "(park-abort) 放棄這次繞行")
    checkFalse(st.followHold, "(park-abort) 回常駐線後不再停等（對向車在自己的線外）")
    drive.clearVehicleGeom(on._cells)
    drive.clearVehicleGeom(parked._cells)
    -- (park-late) 已來不及鬆油門停在障礙前（離 offB 太近）才出現錯不開的對向車：照承諾線做完，
    --   不放棄、也不停在半路（E2E park400：放棄＝硬煞鎖輪沿車頭滑進對向車道被撞）
    arm(8)
    parked = car(40, 2, 0)
    parked._stopped = true
    for _ = 1, 3 do drive.scanRound() end
    checkTrue(st.dodging, "(park-late) 承諾繞行")
    dveh._x = st.fstate.offB - 6
    drive.scanRound()
    on = car(st.fstate.offB + 30, -1.5, math.pi)
    traffic(on, -3, 2)
    checkTrue(st.dodging, "(park-late) 來不及停在障礙前：不放棄繞行")
    checkFalse(st.followHold, "(park-late) 不停在半路讓車（capReason=" .. tostring(st.lastCapReason) .. "）")
    dveh._speed = 5 -- 照繞行帽減速後停止距離縮回可放棄範圍：已判 late 就不得再放棄
    traffic(on, -3, 1)
    checkTrue(st.dodging, "(park-late) 減速後仍維持承諾，不半路放棄")
    -- 單輪沒看到對向車（速度算不出來／漏掃）不得清掉 late：否則下一輪又判讓車就半路放棄
    local vs0 = st.sensor.trfVs[1]
    st.sensor.trfVs[1] = false
    MDAD.Drive.trafficScan(st, getTimestampMs(), 5)
    st.sensor.trfVs[1] = vs0
    checkTrue(st.trafficLate, "(park-late) 單輪判讀閃掉：late 仍綁在這次承諾上")
    dveh._speed = 30
    dveh._x = st.fstate.offC + 1
    traffic(on, -3, 1)
    checkTrue(st.dodging and st.trafficLate,
        "(park-late) 過 c 仍照承諾線回線，不提前交 RETURN（late=" .. tostring(st.trafficLate) .. "）")
    drive.clearVehicleGeom(on._cells)
    drive.clearVehicleGeom(parked._cells)
    -- (park-own) 同樣來不及鬆油門停在停點前，但車身還在自己半邊（剛開始切出）：放棄繞行在自己
    --   這邊停下，不照承諾線爬進對向車道（E2E k-suv-park／k-f350-park）
    arm(8)
    parked = car(40, 2, 0)
    parked._stopped = true
    for _ = 1, 3 do drive.scanRound() end
    checkTrue(st.dodging, "(park-own) 承諾繞行")
    dveh._x, dveh._y = st.fstate.offB - 6, 2
    drive.scanRound()
    on = car(st.fstate.offB + 30, -1.5, math.pi)
    traffic(on, -3, 2)
    checkFalse(st.dodging or st.trafficLate, "(park-own) 車身還在自己半邊：放棄繞行，不硬做")
    drive.clearVehicleGeom(on._cells)
    drive.clearVehicleGeom(parked._cells)
    dveh._y = 0
    dveh._x = 0
    MDAD.HUD.perceptionDistance = oldPd

    -- (relay) 1001i 伺服器轉送（Drive.relayReceive／mergeRelay）：原生快照之外 150m 的對向車（佔中線、
    --   72 km/h）接到本輪快照尾端，本輪就判衝突、往右錯開。違規證明：不呼叫 mergeRelay＝(relay) 紅；
    --   拿掉原生去重＝(relay-dup) 紅；拿掉 TTL＝(relay-stale) 紅；拿掉離路線距離＝(relay-off) 紅。
    arm(8)
    drive.scanRound()
    checkEq(st.trfOnGap, nil, "(relay) 沒有轉送：150m 外的對向車看不到")
    MDAD.Drive.relayReceive({ n = 1, 9001, 150, 0, -20, 0, -1, 0, 0.9, 2.3 })
    drive.scanRound()
    checkTrue(st.relayN == 1 and st.trfOnGap ~= nil and st.trfOnGap > 90,
        "(relay) 轉送的對向車本輪就判衝突（gap " .. tostring(st.trfOnGap) .. "、relayN " .. tostring(st.relayN) .. "）")
    checkTrue(st.trfOnWant ~= nil and st.trfOnWant > 2.05,
        "(relay) 往右錯開（實得 " .. tostring(st.trfOnWant) .. "）")
    -- (relay-stale) 超過 RELAY_TTL_MS 沒再更新：不用
    nowMs = nowMs + 2000
    drive.scanRound()
    checkEq(st.relayN, 0, "(relay-stale) 1.5 秒沒更新的轉送不用")
    -- (relay-off) 離路線中心線 30m（平行道路）：不接
    MDAD.Drive.relayReceive({ n = 1, 9002, 150, 30, -20, 0, -1, 0, 0.9, 2.3 })
    drive.scanRound()
    checkEq(st.relayN, 0, "(relay-off) 離路線 30m 的車不在這條路上")
    -- (relay-own) 自己這台不接：轉送表是整個客戶端共用的，分割畫面時另一位本機玩家收到的轉送會帶到這台
    MDAD.Drive.relayReceive({ n = 1, dveh:getId(), 150, 0, -20, 0, -1, 0, 0.9, 2.3 })
    drive.scanRound()
    checkEq(st.relayN, 0, "(relay-own) 自己的車不接")
    -- (relay-dup) 原生快照已經有的同一台（同 id）不重複接：轉送後那一輪對方仍在動（兩輪沒動＝停著的硬障礙，不進 trf）
    on = car(55, 0, math.pi)
    traffic(on, -3, 1)
    MDAD.Drive.relayReceive({ n = 1, on:getId(), on._x, on._y, -20, 0, -1, 0, 0.9, 2.3 })
    move(on, -3)
    drive.scanRound()
    checkTrue((st.sensor.trfNativeN or 0) >= 1 and st.relayN == 0, "(relay-dup) 原生已看到的同一台不重複接（native "
        .. tostring(st.sensor.trfNativeN) .. "、relayN " .. tostring(st.relayN) .. "）")
    drive.clearVehicleGeom(on._cells)
    MDAD.Drive.relay = {}

    MDAD.Drive.stop(0, nil)
    HaloTextHelper = oldHalo
    drive.frameMs(wasMs)
    MDAD.HUD.zombieDodge = oldZ
    MDAD.Drive.setGear(0, oldGear)
    -- (park-sp) 0928c：單機沒有別的駕駛＝不會有對向來車，借對向車道也照剖面速設計（不套 25 的短過渡）。
    --   違規證明：拿掉 isClient 條件＝設計速 25 紅。
    clientFlag = false
    arm(8)
    local parkedSp = car(40, 2, 0)
    parkedSp._stopped = true
    traffic(parkedSp, 0, 2)
    -- 剖面速設計的過渡段較長，要車往前開到整條線都在已掃範圍內才承諾（假車不會自己動）
    for _ = 1, 8 do
        if st.dodging then break end
        dveh._x = dveh._x + 3
        drive.scanRound()
        driveReset(dveh)
        driveTick(dp, dveh)
    end
    checkTrue(st.dodging, "(park-sp) 單機借對向車道繞停車")
    checkTrue(st.dodgeDesignSpeed > MDAD.Drive.debugTune().ONCOMING_DESIGN_KMH,
        "(park-sp) 單機不套對向短設計（實得 " .. tostring(st.dodgeDesignSpeed) .. "）")
    drive.clearVehicleGeom(parkedSp._cells)
    MDAD.Drive.stop(0, nil)
    MinidoracatMiniMapAPI.navApiVersion = oldApi
    drive.nav.route, drive.nav.tx, drive.nav.ty, drive.nav.state = oldRoute, oldTx, oldTy, oldState
    drive.world, drive.vehGeo, SandboxVars, dveh, getSpecificPlayer =
        oldWorld, oldGeo, oldSandbox, oldVeh, oldGet
    clientFlag = oldClient
end
drive.scenarioTraffic()

-- 路外起步的越野接線（2026-09-27 E2E startpush-sp loc=c25＝正式服原位置）：路網在車前才開始（死路端點），
-- 車停在路外、車頭垂直朝路，路線起點 2.5m 處硬物擋住中線。舊制剖面從路線起點 s=0 起算、車在起點之前
-- 的 3m 被夾掉，入口跑道只剩 2.5m＋起始 lane 在路外 5.5m → steep／sweep 全滅 → blocked，倒車又垂直於路線
-- 換不到跑道。現制把「車位→路線起點」接在剖面前面（Drive.approachRoute）。
--   (apr)      車在起點之前：剖面第一點＝車位、接線長 ≈ 6.3、不 blocked
--   (apr-side) 車在路旁（投影落在第一段內）：不接，維持 RETURN 併入
-- 違規證明：approachRoute 一律回原路線＝(apr) blocked 紅。
function drive.scenarioApproach()
    scenario("路外起步：路網在車前才開始時把越野接線接在剖面前面，路線起點旁有硬物也排得出入口")
    local oldSandbox, oldVeh, oldGet = SandboxVars, dveh, getSpecificPlayer
    local oldApi = MinidoracatMiniMapAPI.navApiVersion
    local oldRoute, oldTx, oldTy, oldState = drive.nav.route, drive.nav.tx, drive.nav.ty, drive.nav.state
    local wasMs = drive.frameMs(20)
    MDAD.Drive.stop(0, nil)
    getSpecificPlayer = function(n) if n == 0 then return dp end end
    MinidoracatMiniMapAPI.navApiVersion = 5
    dveh = newVehicle({ battery = newItem("Base.CarBattery", { uses = 0.8 }),
        engineRunning = true, mass = 1600, speed = 0, maxSpeed = 100,
        bodyW = 1.6, bodyL = 4.2, comX = 0, comZ = 0, profileFull = true,
        enginePower = 3000, brakingForce = 100, wheelFriction = 1.5, tireFriction = 1.5 })
    local function arm(x, y, heading, route)
        MDAD.Drive.stop(0, nil)
        drive.fillWorld(-12, 90, -12, 12)
        drive.putRoad(0, 90, -3, 2)
        setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false,
            AutoDriveMaxSpeed = 60, RightLaneBias = 0 })
        dveh._x, dveh._y, dveh._speed, dveh._steering, dveh._stopped = x, y, 0, 0, true
        dveh._engine, dveh._driver = true, dp
        dp._vehicle, dp._dead, dp._local = dveh, false, true
        setHeading(dveh, heading)
        -- 路網從 (0,0) 往東：第一點就是死路端點（主 MOD 的起點＝路網上離車最近點）
        drive.nav.route = route or { pts = { 0, 0, 80, 0 }, segSurface = { "gravel" }, segWidth = { 5 },
            len = 80, cost = 80, avoidPenalty = 0 }
        drive.nav.tx, drive.nav.ty, drive.nav.state = 80, 0, "ok"
        return MDAD.Drive.start(dp)
    end
    -- 車在路線起點西 3m、北 5.5m，車頭朝南（垂直朝路），起點後 2.5m 中線一格硬物
    checkTrue(arm(-3, -5.5, math.pi / 2), "(apr) 路外起步啟動")
    drive.putSolid(2, 0, "approach_start_obstacle")
    for _ = 1, 30 do driveTick(dp, dveh) end
    for _ = 1, 3 do drive.scanRound(true) end
    local st = MDAD.Drive.debugSession(0)
    checkTrue(st ~= nil and st.approachM > 6 and st.approachM < 6.6,
        "(apr) 接上越野接線（長 " .. tostring(st and st.approachM) .. "）")
    checkTrue(st ~= nil and math.abs(st.profile.x[1] + 3) < 1e-6 and math.abs(st.profile.y[1] + 5.5) < 1e-6,
        "(apr) 剖面第一點就是車位")
    checkTrue(st ~= nil and st.route.pts[1] == 0 and #st.route.pts == 4,
        "(apr) 原路線 identity 不動（cutover 仍比對原 table）")
    checkTrue(st ~= nil and not st.blocked,
        "(apr) 路線起點旁有硬物：排得出入口、不 blocked（blocked=" .. tostring(st and st.blocked)
        .. " mode=" .. tostring(st and st.mode) .. " pm=" .. tostring(st and st.planMode) .. "）")
    drive.clearCell(2, 0)
    -- 車在路旁（投影落在第一段內）：不接越野線（RETURN 的平滑併入）
    checkTrue(arm(20, -5.5, 0), "(apr-side) 路旁起步啟動")
    for _ = 1, 4 do driveTick(dp, dveh) end
    st = MDAD.Drive.debugSession(0)
    checkTrue(st ~= nil and st.approachM == 0 and st.profile.x[1] == 0,
        "(apr-side) 車在路旁：不接越野線（approachM=" .. tostring(st and st.approachM) .. "）")
    -- (apr-mid) 0928a：開著導航走了一段才按自駕，主 MOD 回快取同一條線、起點早在車後（正式服 10 趟接出
    --   164／7136m 回頭接線）。車離第三段只有 1m，只是剛好也在第一段反向延長線上、10m 內。
    --   違規證明：拿掉「整條路線最近點」檢查即紅（舊制接出 10.3m）。
    checkTrue(arm(-5, -9, math.pi, { pts = { 0, 0, 40, 0, 40, -10, -20, -10 },
        segSurface = { "gravel", "gravel", "gravel" }, segWidth = { 5, 5, 5 },
        len = 110, cost = 110, avoidPenalty = 0 }), "(apr-mid) 車在路線中段旁啟動")
    for _ = 1, 4 do driveTick(dp, dveh) end
    st = MDAD.Drive.debugSession(0)
    checkTrue(st ~= nil and st.approachM == 0 and st.profile.x[1] == 0,
        "(apr-mid) 車離後段只有 1m：不從車位接回起點（approachM=" .. tostring(st and st.approachM) .. "）")
    -- (apr-far) 起點在車後 25m（> SNAP_MAX_M）：不接越野線。違規證明：拿掉距離上限即紅（舊制接出 25m）。
    checkTrue(arm(-25, 0, 0), "(apr-far) 起點前 25m 啟動")
    for _ = 1, 4 do driveTick(dp, dveh) end
    st = MDAD.Drive.debugSession(0)
    checkTrue(st ~= nil and st.approachM == 0,
        "(apr-far) 超過 20m 不接越野線（approachM=" .. tostring(st and st.approachM) .. "）")
    -- (apr-perp) 0928b E2E replay Annilex：車在路線中段旁 15m 草地（超過 RETURN_MAX_DEV 12、未超過 SNAP_MAX_M 20）：
    --   把「車位→最近點」接成剖面開頭、最近點之前捨去，感知／繞行才看得到中間的障礙。
    --   違規證明：拿掉 far 分支＝不接（approachM 0）紅。
    checkTrue(arm(40, -15, math.pi / 2), "(apr-perp) 路線中段旁 15m 啟動")
    for _ = 1, 4 do driveTick(dp, dveh) end
    st = MDAD.Drive.debugSession(0)
    checkTrue(st ~= nil and math.abs(st.approachM - 15) < 1e-6,
        "(apr-perp) 接上車位→最近點的接線（approachM=" .. tostring(st and st.approachM) .. "）")
    checkTrue(st ~= nil and st.profileRoute.pts[1] == 40 and st.profileRoute.pts[2] == -15
        and st.profileRoute.pts[3] == 40 and st.profileRoute.pts[4] == 0 and st.profileRoute.pts[5] == 80,
        "(apr-perp) 剖面＝車位→(40,0)→(80,0)，最近點之前捨去")
    checkTrue(st ~= nil and #st.profileRoute.segWidth == #st.profileRoute.pts / 2 - 1,
        "(apr-perp) 段屬性數量對齊點數")
    -- (apr-near) 同樣在中段旁但只 8m（RETURN 管得到）：不接
    checkTrue(arm(40, -8, math.pi / 2), "(apr-near) 路線中段旁 8m 啟動")
    for _ = 1, 4 do driveTick(dp, dveh) end
    st = MDAD.Drive.debugSession(0)
    checkTrue(st ~= nil and st.approachM == 0, "(apr-near) 12m 內交給 RETURN：不接（approachM=" .. tostring(st and st.approachM) .. "）")
    -- (apr-rev) 0928g E2E startpush c25（起手偏 36°）：起步接了越野線，倒車又退到接線起點之後——
    --   舊剖面從舊車位起算，退出來的距離夾在 s=0、進入段一寸也沒多（三次倒車 entry 恆 1.0 → 受困）。
    --   倒車收手後從現在的車位重接越野線。違規證明：拿掉 settle 成功處的旗標＝剖面仍從舊車位起算、紅。
    checkTrue(arm(-3, -5.5, math.pi / 2), "(apr-rev) 路外起步啟動")
    for _ = 1, 30 do driveTick(dp, dveh) end
    st = MDAD.Drive.debugSession(0)
    checkTrue(st ~= nil and st.approachM > 6 and st.approachM < 6.6, "(apr-rev) 起步接線 ≈6.3")
    -- 倒車退了 6.5m：車停在接線起點北方，settle 收手
    dveh._x, dveh._y, dveh._speed, dveh._stopped = -3, -12, 0, true
    st.mode, st.progressState = "settle", "settle"
    st.settleUntil = 1e15
    st.unstickX, st.unstickY = -3, -5.5
    for _ = 1, 4 do driveTick(dp, dveh) end
    st = MDAD.Drive.debugSession(0)
    local gapRev = math.sqrt(3 * 3 + 12 * 12)
    checkTrue(st ~= nil and math.abs(st.approachM - gapRev) < 1e-6,
        "(apr-rev) 倒車後從現在的車位重接（approachM=" .. tostring(st and st.approachM)
        .. " 期望 " .. tostring(gapRev) .. "）")
    checkTrue(st ~= nil and math.abs(st.profile.x[1] + 3) < 1e-6 and math.abs(st.profile.y[1] + 12) < 1e-6,
        "(apr-rev) 新剖面第一點＝倒車後的車位")
    checkTrue(st ~= nil and st.route.pts[1] == 0 and #st.route.pts == 4 and not st.reapproach,
        "(apr-rev) 原路線 identity 不動、旗標已消費")

    MDAD.Drive.stop(0, nil)
    drive.frameMs(wasMs)
    MinidoracatMiniMapAPI.navApiVersion = oldApi
    drive.nav.route, drive.nav.tx, drive.nav.ty, drive.nav.state = oldRoute, oldTx, oldTy, oldState
    SandboxVars, dveh, getSpecificPlayer = oldSandbox, oldVeh, oldGet
end
drive.scenarioApproach()

-- (xk) 0928i rc6 0070 路口 jog：保持段延過 −75° 大折點後，2.8m 外又一個 19° 小折點落在 c 後 2m 內
--   → 出口轉場塞不進 → 全部候選 exit-room → 倒車三次交還。緊接的小折點一併在偏移上通過；
--   大折點（外側偏移繞急彎）照舊拒收。違規證明：拿掉小折點迴圈＝(xk) exit-room 紅。
--   1002u：19° 起建成小弧（不再是頂點，出口轉場跨弧同一般弧段＝(xk-arc)）；原始頂點規則改用 9.5°
--   （turnPeakS 的 0.15 rad 看得到、小於 FILLET_SMALL_RAD 不建弧）。
function drive.scenarioExitKink()
    scenario("繞行出口：保持段延過大折點後緊接小折點，出口轉場放到小折點之後")
    local oldSandbox, oldVeh, oldGet = SandboxVars, dveh, getSpecificPlayer
    local oldApi = MinidoracatMiniMapAPI.navApiVersion
    local oldRoute, oldTx, oldTy, oldState = drive.nav.route, drive.nav.tx, drive.nav.ty, drive.nav.state
    local wasMs = drive.frameMs(20)
    MDAD.Drive.stop(0, nil)
    getSpecificPlayer = function(n) if n == 0 then return dp end end
    MinidoracatMiniMapAPI.navApiVersion = 5
    dveh = newVehicle({ battery = newItem("Base.CarBattery", { uses = 0.8 }),
        engineRunning = true, mass = 1600, speed = 0, maxSpeed = 100,
        bodyW = 1.6, bodyL = 4.2, comX = 0, comZ = 0, profileFull = true,
        enginePower = 3000, brakingForce = 100, wheelFriction = 1.5, tireFriction = 1.5 })
    local function arm(turn2)
        MDAD.Drive.stop(0, nil)
        drive.fillWorld(-12, 80, -50, 12)
        setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false,
            AutoDriveMaxSpeed = 60, RightLaneBias = 0 })
        dveh._x, dveh._y, dveh._speed, dveh._steering, dveh._stopped = 0, 0, 0, 0, true
        dveh._engine, dveh._driver = true, dp
        dp._vehicle, dp._dead, dp._local = dveh, false, true
        setHeading(dveh, 0)
        -- 東行 40m → 左折 75°（窄路＝保留折點）走 2.8m → 右折 turn2 → 直行
        local h1 = -75 * math.pi / 180
        local x2, y2 = 40 + 2.8 * math.cos(h1), 2.8 * math.sin(h1)
        local h2 = h1 + turn2 * math.pi / 180
        drive.nav.route = { pts = { 0, 0, 40, 0, x2, y2, x2 + 40 * math.cos(h2), y2 + 40 * math.sin(h2) },
            segSurface = { "paved", "paved", "paved" }, segWidth = { 4, 4, 4 },
            len = 82.8, cost = 82.8, avoidPenalty = 0 }
        drive.nav.tx, drive.nav.ty, drive.nav.state = drive.nav.route.pts[7], drive.nav.route.pts[8], "ok"
        local ok = MDAD.Drive.start(dp)
        for _ = 1, 10 do driveTick(dp, dveh) end
        return ok
    end
    checkTrue(arm(9.5), "(xk) 大折點後 2.8m 接 9.5° 小折點：啟動")
    local st = MDAD.Drive.debugSession(0)
    checkTrue(st ~= nil and st.profile ~= nil and st.profile.ready == true, "(xk) 剖面建好")
    -- 群在大折點前結束（c=39.5），走廊給的出口很短（d=43）：上面的既有規則把保持段延到大折點後 1m
    local ok, _, _, rc, rd, why = MDAD.Drive.debugShape(0, 20, 30, 39.5, 43, -1)
    checkTrue(ok == true and rc ~= nil and rc > 42.8 and rd > rc,
        "(xk) 小折點一併在偏移上通過、出口放到它之後（ok=" .. tostring(ok) .. " c=" .. tostring(rc)
        .. " d=" .. tostring(rd) .. " why=" .. tostring(why) .. "）")
    -- 門檻以上的折點照舊拒收（外側偏移繞急彎＝車追不上、切內）：門檻暫時壓到 9.5° 以下
    local tune = MDAD.Drive.debugTune()
    local oldKink = tune.EXIT_HOLD_KINK_RAD
    tune.EXIT_HOLD_KINK_RAD = 0.16
    ok, _, _, rc, rd, why = MDAD.Drive.debugShape(0, 20, 30, 39.5, 43, -1)
    tune.EXIT_HOLD_KINK_RAD = oldKink
    checkTrue(ok == false and why == "exit-room",
        "(xk-big) 超過門檻的緊接折點照舊拒收（ok=" .. tostring(ok) .. " why=" .. tostring(why) .. "）")
    -- 19°（原案角度）：建成小弧，出口照常放得下（門檻壓低也不拒——弧不是折點）
    checkTrue(arm(19), "(xk-arc) 大折點後 2.8m 接 19° 小折點：啟動")
    st = MDAD.Drive.debugSession(0)
    local arcN = 0
    for i = 1, st.profile.n - 1 do
        if st.profile.s[i] > 40 and st.profile.s[i] < 46 and st.profile.segKind[i] == MDADDynamics.SEG_ARC then
            arcN = arcN + 1
        end
    end
    tune.EXIT_HOLD_KINK_RAD = 0.16
    ok, _, _, rc, rd, why = MDAD.Drive.debugShape(0, 20, 30, 39.5, 43, -1)
    tune.EXIT_HOLD_KINK_RAD = oldKink
    checkTrue(arcN > 0 and ok == true,
        "(xk-arc) 19° 建成小弧（弧段 " .. arcN .. "）、出口照常（ok=" .. tostring(ok) .. " why=" .. tostring(why) .. "）")
    MDAD.Drive.stop(0, nil)
    drive.frameMs(wasMs)
    MinidoracatMiniMapAPI.navApiVersion = oldApi
    drive.nav.route, drive.nav.tx, drive.nav.ty, drive.nav.state = oldRoute, oldTx, oldTy, oldState
    SandboxVars, dveh, getSpecificPlayer = oldSandbox, oldVeh, oldGet
end
drive.scenarioExitKink()

-- (ps) 0928i rc8 0086／0089：群已貼到車前（進入段不到 1m），舒適需求要的側移全因 steep 拒收，但車就這樣
--   直走在物理檔也過得去（兩側各 0.1m）。舊制 blocked 一秒鎖輪；現制沿車的實際橫向直走、物理檔承諾。
--   違規證明：拿掉直走候選＝(ps) blocked 紅。
function drive.scenarioStraightProbe()
    scenario("貼在車前的窄縫：側移塞不進時沿現在的橫向直走（物理檔），不 blocked 鎖輪")
    local oldSandbox, oldVeh, oldGet = SandboxVars, dveh, getSpecificPlayer
    local oldApi = MinidoracatMiniMapAPI.navApiVersion
    local oldRoute, oldTx, oldTy, oldState = drive.nav.route, drive.nav.tx, drive.nav.ty, drive.nav.state
    local wasMs = drive.frameMs(20)
    MDAD.Drive.stop(0, nil)
    getSpecificPlayer = function(n) if n == 0 then return dp end end
    MinidoracatMiniMapAPI.navApiVersion = 5
    dveh = newVehicle({ battery = newItem("Base.CarBattery", { uses = 0.8 }),
        engineRunning = true, mass = 1600, speed = 0, maxSpeed = 100,
        bodyW = 1.2, bodyL = 4.2, comX = 0, comZ = 0, profileFull = true,
        enginePower = 3000, brakingForce = 100, wheelFriction = 1.5, tireFriction = 1.5 })
    drive.fillWorld(-12, 90, -12, 12)
    drive.putRoad(0, 90, -6, 6)
    setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false,
        AutoDriveMaxSpeed = 60, RightLaneBias = 0 })
    dveh._x, dveh._y, dveh._speed, dveh._steering, dveh._stopped = 0, 0, 0, 0, true
    dveh._engine, dveh._driver = true, dp
    dp._vehicle, dp._dead, dp._local = dveh, false, true
    setHeading(dveh, 0)
    drive.nav.route = { pts = { 0, 0, 80, 0 }, segSurface = { "paved" }, segWidth = { 12 },
        len = 80, cost = 80, avoidPenalty = 0 }
    drive.nav.tx, drive.nav.ty, drive.nav.state = 80, 0, "ok"
    checkTrue(MDAD.Drive.start(dp), "(ps) 啟動")
    for _ = 1, 6 do driveTick(dp, dveh) end
    -- 車頭前 2m 兩側各一格硬物（l=±1.5）：車道兩側物理各剩 0.1m，舒適縫要側移 3m 以上
    drive.putSolid(4, 1, "ps_right")
    drive.putSolid(4, -2, "ps_left")
    for _ = 1, 3 do drive.scanRound(true) end
    local st = MDAD.Drive.debugSession(0)
    checkTrue(st ~= nil and not st.blocked and st.dodging == true
            and type(st.dodgeTier) == "string" and st.dodgeTier:find("probe%-straight") ~= nil,
        "(ps) 沿現在的橫向直走、物理檔承諾（blocked=" .. tostring(st and st.blocked) .. " tier="
        .. tostring(st and st.dodgeTier) .. " offL=" .. tostring(st and st.fstate and st.fstate.offL) .. "）")
    drive.clearCell(4, 1)
    drive.clearCell(4, -2)
    MDAD.Drive.stop(0, nil)
    drive.frameMs(wasMs)
    MinidoracatMiniMapAPI.navApiVersion = oldApi
    drive.nav.route, drive.nav.tx, drive.nav.ty, drive.nav.state = oldRoute, oldTx, oldTy, oldState
    SandboxVars, dveh, getSpecificPlayer = oldSandbox, oldVeh, oldGet
end
drive.scenarioStraightProbe()

-- (xkeep) 0928j rc8 0086：offL −2.5、常駐 +1.5（差 4m），整車過 c 即提前釋放 → 偏離超過 RETURN 門檻
--   → RETURN 25 km/h 爬回；承諾線出口本來就帶著 60 的帽回常駐線。車離常駐線超過 RETURN 門檻時
--   沿承諾線走完出口。0929e 起低帽（爬行）也一樣：RETURN 斜切回線常被剛繞過的那群打回 hold（rc28 0009
--   hold → stall → 頂上硬物）。違規證明：exitKeepsDodge 恆回 false＝(xkeep) 提前釋放紅；
--   把帽條件加回（帽 < RETURN_CAP 回 false）＝(xkeep) 帽 10 紅；不看出口窄點（照舊只看 RETURN 門檻）＝
--   (xkeep)「出口前方還有窄點」紅；離 0.5m 以上一律走完＝「出口淨空」「沒有證據」與 (c9) 紅。
function drive.scenarioExitKeep()
    scenario("繞行出口：離常駐線太遠且承諾線不慢時沿承諾線走完，不交 RETURN 慢爬")
    local oldSandbox, oldVeh, oldGet = SandboxVars, dveh, getSpecificPlayer
    local oldApi = MinidoracatMiniMapAPI.navApiVersion
    local oldRoute, oldTx, oldTy, oldState = drive.nav.route, drive.nav.tx, drive.nav.ty, drive.nav.state
    local wasMs = drive.frameMs(20)
    MDAD.Drive.stop(0, nil)
    getSpecificPlayer = function(n) if n == 0 then return dp end end
    MinidoracatMiniMapAPI.navApiVersion = 5
    dveh = newVehicle({ battery = newItem("Base.CarBattery", { uses = 0.8 }),
        engineRunning = true, mass = 1600, speed = 0, maxSpeed = 100,
        bodyW = 1.6, bodyL = 4.2, comX = 0, comZ = 0, profileFull = true,
        enginePower = 3000, brakingForce = 100, wheelFriction = 1.5, tireFriction = 1.5 })
    drive.fillWorld(-12, 130, -12, 12)
    drive.putRoad(0, 130, -6, 6)
    setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false,
        AutoDriveMaxSpeed = 60, RightLaneBias = 0.5 }) -- 12m 路 ×0.5＝常駐 +1.5
    dveh._x, dveh._y, dveh._speed, dveh._steering, dveh._stopped = 0, 1.5, 0, 0, true
    dveh._engine, dveh._driver = true, dp
    dp._vehicle, dp._dead, dp._local = dveh, false, true
    setHeading(dveh, 0)
    drive.nav.route = { pts = { 0, 0, 120, 0 }, segSurface = { "paved" }, segWidth = { 12 },
        len = 120, cost = 120, avoidPenalty = 0 }
    drive.nav.tx, drive.nav.ty, drive.nav.state = 120, 0, "ok"
    checkTrue(MDAD.Drive.start(dp), "(xkeep) 啟動")
    for _ = 1, 6 do driveTick(dp, dveh) end
    drive.scanRound(true)
    local st = MDAD.Drive.debugSession(0)
    -- predicate：常駐 +1.5、車在 −2.5（差 4m > 門檻 3）：帽 60 沿線、帽 10 照舊放；車在 +0.5 照舊放
    st.lastLatSigned, st.dodgeApproachCap = -2.5, 60
    checkTrue(MDAD.Drive.exitKeepsDodge(st) == true, "(xkeep) 離常駐線 4m、帽 60：沿承諾線走完出口")
    st.dodgeApproachCap = 10
    checkTrue(MDAD.Drive.exitKeepsDodge(st) == true, "(xkeep) 帽 10（爬行）同樣沿承諾線走完出口")
    st.lastLatSigned, st.dodgeApproachCap = 0.5, 60
    checkTrue(MDAD.Drive.exitKeepsDodge(st) == false, "(xkeep) 離常駐線 1m、沒有出口淨距證據：照舊提前放")
    do -- 0929h：guard 收過這條線的逐點淨距——出口還有窄點＝走完；全段淨空＝照舊放（rc34 0030 彎上出口）
        local fs0 = st.fstate
        local keep = { fs0.ovN, fs0.ovS0, fs0.ovEndS, st.dodgeClrN, st.dodgeClrK0, st.dodgeClrS0, st.dodgeClrS1, st.dodgeClr }
        fs0.ovN, fs0.ovS0, fs0.ovEndS = 40, st.lastSNow - 20, st.lastSNow + 19
        st.dodgeClrN, st.dodgeClrK0, st.dodgeClrS0, st.dodgeClrS1 = 40, 1, fs0.ovS0, fs0.ovEndS
        st.dodgeClr = {}
        for k = 1, 40 do st.dodgeClr[k] = 9 end
        st.dodgeClr[5] = 0.1 -- 車身後方的窄點不算
        checkTrue(MDAD.Drive.exitKeepsDodge(st) == false, "(xkeep) 離常駐線 1m、出口淨空（窄點已在車後）：照舊提前放")
        st.dodgeClr[30] = 0.3
        checkTrue(MDAD.Drive.exitKeepsDodge(st) == true,
            "(xkeep) 離常駐線 1m、出口前方還有窄點：沿承諾線走完（0929h rc33 0004：1.7m 就放手，斜切頂上出口旁的物件）")
        fs0.ovN, fs0.ovS0, fs0.ovEndS, st.dodgeClrN, st.dodgeClrK0, st.dodgeClrS0, st.dodgeClrS1, st.dodgeClr =
            keep[1], keep[2], keep[3], keep[4], keep[5], keep[6], keep[7], keep[8]
    end
    st.lastLatSigned = 1.2
    checkTrue(MDAD.Drive.exitKeepsDodge(st) == false, "(xkeep) 離常駐線 0.3m：照舊提前放")
    -- 整合：右側整排硬物（l +0.5..+5.5，x 40–49）逼車繞到左邊
    for x = 40, 49 do for y = 0, 5 do drive.putSolid(x, y, "xkeep_" .. x .. "_" .. y) end end
    for _ = 1, 3 do drive.scanRound(true) end
    st = MDAD.Drive.debugSession(0)
    local fs = st.fstate
    checkTrue(st.dodging == true and type(fs.offL) == "number" and fs.offL < -1.5,
        "(xkeep) 承諾左繞（offL=" .. tostring(fs.offL) .. "）")
    if st.dodging and type(fs.offC) == "number" then
        -- 車擺到出口起點之後（整車過 c）、仍在承諾線上；清掉硬物（前方淨空）
        for x = 40, 49 do for y = 0, 5 do drive.clearCell(x, y) end end
        dveh._x, dveh._y, dveh._speed = fs.offC + st.bodyReach + 1, fs.offL, 40
        for _ = 1, 2 do driveTick(dp, dveh) end
        st.planSig = -1
        drive.scanRound(true)
        checkTrue(st.dodging == true and not st.returnActive,
            "(xkeep) 整車過 c、離常駐線 4m：不提前釋放（dodging=" .. tostring(st.dodging)
            .. " ret=" .. tostring(st.returnActive) .. " rs=" .. tostring(st.lastSNow)
            .. " c=" .. tostring(fs.offC) .. "）")
    end
    MDAD.Drive.stop(0, nil)
    drive.frameMs(wasMs)
    MinidoracatMiniMapAPI.navApiVersion = oldApi
    drive.nav.route, drive.nav.tx, drive.nav.ty, drive.nav.state = oldRoute, oldTx, oldTy, oldState
    SandboxVars, dveh, getSpecificPlayer = oldSandbox, oldVeh, oldGet
end
drive.scenarioExitKeep()

-- (relg) 1004a 正式服 0.18.2 Sixya clip-11／MI clip-01（同一點、兩台車、同一事件序）：承諾期間 laneBias 凍結在
--   commit 值、常駐線隨路面對中漂走；出口釋放後期望線一幀跳回常駐線，規劃只問常駐線判 clear，車身卻還在舊出口
--   線上、車鼻前 1m 有物件 → 5→17 km/h 撞上。釋放時車離接下來要跟的線 > START_GUARD_LAT_M＝重新武裝起步近物
--   限速（Drive.armReleaseGuard），以前半車身淨距限速到對正。
--   (relg-pred) predicate：離常駐線 2.1m 武裝、0.3m 不武裝；鏈著時量鏈 lane。
--   (relg) 整合：12m 路常駐 +1.5、左繞後在出口段離常駐線 2.1m（< RETURN 門檻）提前釋放，車鼻前 1.5m 有物件
--   （不擋常駐線）：釋放後武裝、目標速度被前半車身淨距壓住。
--   違規證明：releaseDodge 不呼叫 armReleaseGuard＝(relg) 紅；門檻改成恆武裝＝(relg-pred) 0.3m 案紅。
function drive.scenarioReleaseGuard()
    scenario("繞行釋放時車不在常駐線上：重新武裝起步近物限速")
    local oldSandbox, oldVeh, oldGet = SandboxVars, dveh, getSpecificPlayer
    local oldApi = MinidoracatMiniMapAPI.navApiVersion
    local oldRoute, oldTx, oldTy, oldState = drive.nav.route, drive.nav.tx, drive.nav.ty, drive.nav.state
    local wasMs = drive.frameMs(20)
    MDAD.Drive.stop(0, nil)
    getSpecificPlayer = function(n) if n == 0 then return dp end end
    MinidoracatMiniMapAPI.navApiVersion = 5
    dveh = newVehicle({ battery = newItem("Base.CarBattery", { uses = 0.8 }),
        engineRunning = true, mass = 1600, speed = 0, maxSpeed = 100,
        bodyW = 1.6, bodyL = 4.2, comX = 0, comZ = 0, profileFull = true,
        enginePower = 3000, brakingForce = 100, wheelFriction = 1.5, tireFriction = 1.5 })
    drive.fillWorld(-12, 130, -12, 12)
    drive.putRoad(0, 130, -6, 6)
    setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false,
        AutoDriveMaxSpeed = 60, RightLaneBias = 0.5 }) -- 12m 路 ×0.5＝常駐 +1.5
    dveh._x, dveh._y, dveh._speed, dveh._steering, dveh._stopped = 0, 1.5, 0, 0, true
    dveh._engine, dveh._driver = true, dp
    dp._vehicle, dp._dead, dp._local = dveh, false, true
    setHeading(dveh, 0)
    drive.nav.route = { pts = { 0, 0, 120, 0 }, segSurface = { "paved" }, segWidth = { 12 },
        len = 120, cost = 120, avoidPenalty = 0 }
    drive.nav.tx, drive.nav.ty, drive.nav.state = 120, 0, "ok"
    local function start()
        MDAD.Drive.stop(0, nil)
        dveh._x, dveh._y, dveh._speed, dveh._steering, dveh._stopped = 0, 1.5, 0, 0, true
        setHeading(dveh, 0)
        checkTrue(MDAD.Drive.start(dp), "(relg) 啟動")
        for _ = 1, 6 do driveTick(dp, dveh) end
        drive.scanRound(true)
        return MDAD.Drive.debugSession(0)
    end
    -- 右側整排硬物逼車左繞；車擺到整車過 c、仍離常駐線 2.1m（< RETURN 門檻 3、沒有出口窄點證據＝會提前釋放）
    local function commitLeft()
        local st = start()
        for x = 40, 49 do for y = 0, 5 do drive.putSolid(x, y, "relg_" .. x .. "_" .. y) end end
        for _ = 1, 3 do drive.scanRound(true) end
        local fs = st.fstate
        local ok = st.dodging == true and type(fs.offL) == "number" and fs.offL < -1.5 and type(fs.offC) == "number"
        checkTrue(ok, "(relg) 前置：承諾左繞（offL=" .. tostring(fs.offL) .. "）")
        for x = 40, 49 do for y = 0, 5 do drive.clearCell(x, y) end end
        if not ok then return nil end
        st.startGuard = false
        local x0 = math.floor(fs.offC + st.bodyReach + 1)
        dveh._x, dveh._y, dveh._speed, dveh._stopped = x0, -0.6, 20, false
        for _ = 1, 2 do driveTick(dp, dveh) end
        st.planSig = -1
        return st, x0
    end
    local st = start()
    -- predicate
    local keep = { st.lastLatSigned, st.frontClearX, st.frontClearY, st.residentBias, st.startGuard, st.laneChained }
    st.startGuard, st.residentBias, st.laneChained = false, 1.5, false
    st.lastLatSigned, st.frontClearX, st.frontClearY = -0.6, 10, 0
    MDAD.Drive.armReleaseGuard(st)
    checkTrue(st.startGuard == true and st.startGuardX == 10, "(relg-pred) 離常駐線 2.1m：武裝（實得 " .. tostring(st.startGuard) .. "）")
    st.startGuard, st.lastLatSigned = false, 1.2
    MDAD.Drive.armReleaseGuard(st)
    checkTrue(st.startGuard == false, "(relg-pred) 離常駐線 0.3m：不武裝")
    st.laneChained, st.fstate.laneBias, st.lastLatSigned = true, -2.5, -2.4
    MDAD.Drive.armReleaseGuard(st)
    checkTrue(st.startGuard == false, "(relg-pred) 鏈著時量鏈 lane（車在鏈 lane 上）：不武裝")
    st.lastLatSigned, st.frontClearX, st.frontClearY, st.residentBias, st.startGuard, st.laneChained =
        keep[1], keep[2], keep[3], keep[4], keep[5], keep[6]
    st.fstate.laneBias = keep[4] or st.fstate.laneBias
    -- (relg) 整合：車鼻前約 1.5m、不擋常駐線 +1.5 的物件；釋放時 20 km/h
    local x0
    st, x0 = commitLeft()
    if st then
        drive.putSolid(x0 + 3, -1, "relg_nose")
        drive.scanRound(true)
        driveReset(dveh)
        driveTick(dp, dveh)
        checkTrue(not st.dodging and not st.returnActive and st.startGuard == true,
            "(relg) 釋放時離常駐線 2.1m：重新武裝起步近物限速（dodging=" .. tostring(st.dodging) .. " ret="
            .. tostring(st.returnActive) .. " guard=" .. tostring(st.startGuard) .. "）")
        -- 只擋加速、不減速：車鼻前 1.5m 有物件時目標停在釋放時的 20 km/h（不加速、也不被滑行包絡壓到爬行——
        -- 高速釋放時那樣壓會在路邊任何東西旁邊急減速，E2E 1004a replay 45→12 km/h）
        local capFrom = st.lastCapReason == "min-exec" and st.minExecFrom or st.lastCapReason
        checkTrue(capFrom == "start-near" and math.abs(drive.calls.maxRegSpeed - 20) <= 1e-6,
            "(relg) 車鼻前 1.5m 有物件：目標停在釋放時的車速 20、不加速也不壓到爬行（cap=" .. tostring(st.lastCapReason)
            .. "(" .. tostring(st.minExecFrom) .. ") reg=" .. tostring(drive.calls.maxRegSpeed) .. " fc="
            .. tostring(st.frontClearance) .. " floor=" .. tostring(st.startGuardFloorKmh) .. "）")
        drive.clearCell(x0 + 3, -1)
    end
    -- (relg-tail) 1004a 正式服 0.18.2 Qoo clip-15：快照裡擋常駐線的點落在車尾與車心之間（Corridor.plan／判堵錨
    --   都從 rs−halfL 收）。提前釋放的擋線檢查也從車尾起算＝不放手、沿承諾線走；舊制從車心找＝放手後同輪判堵、
    --   錨在車身旁鎖輪。點由 Sensor.step 完成輪時注入（車身旁的點不在新掃描窗內，正式服是同輪車已開過去）。
    --   違規證明：exitReady 改回從車心找＝(relg-tail) 紅。
    st, x0 = commitLeft()
    if st then
        local realStep = MDADSensor.step
        MDADSensor.step = function(sen, ...)
            local done = realStep(sen, ...)
            if done and sen.ready then
                local n = sen.hardN + 1
                local hs = st.lastSNow - 1
                sen.hardS[n], sen.hardL[n], sen.hardN = hs, 1.5, n
                if sen.hardR then sen.hardR[n] = 0.15 end
                if sen.hardX then sen.hardX[n], sen.hardY[n] = hs, 1.5 end
                sen.sig = sen.sig + 7
            end
            return done
        end
        drive.scanRound(true)
        MDADSensor.step = realStep
        checkTrue(st.dodging == true,
            "(relg-tail) 車尾與車心之間有擋常駐線的點：不提前釋放（dodging=" .. tostring(st.dodging) .. " blocked="
            .. tostring(st.blocked) .. "）")
    end
    MDAD.Drive.stop(0, nil)
    drive.frameMs(wasMs)
    MinidoracatMiniMapAPI.navApiVersion = oldApi
    drive.nav.route, drive.nav.tx, drive.nav.ty, drive.nav.state = oldRoute, oldTx, oldTy, oldState
    SandboxVars, dveh, getSpecificPlayer = oldSandbox, oldVeh, oldGet
end
drive.scenarioReleaseGuard()

-- (dvis) 0928k rc9 0104／0109：路線終點前 4–9m 的繞行，可視帽把終點當未知前緣扣 halfL＋2 → 0，
--   車停在終點前、帶著偏移進不了到站圈。可視帶已含終點、剩 ≤ ARRIVE_M+3 時地板到爬行（同一般跟線）。
--   違規證明：拿掉地板＝終點前 4m 的帽回 0、(dvis) 紅。
function drive.scenarioDodgeTerminalVis()
    scenario("繞行可視帽：路線終點已在可視帶內、剩 ≤ ARRIVE_M+3 時不把終點當障礙")
    local s = { lastSNow = 96, vehicleProfile = { halfL = 2.1 }, profile = { length = 100 } }
    local capEnd = MDAD.Drive.dodgeVisibilityCap(s, { scanEndS = 100, unloaded = false }, 4.6)
    checkTrue(capEnd >= MDADDynamics.DODGE_SQUEEZE_CAP,
        "(dvis) 終點前 4m、可視到終點：地板到爬行（cap=" .. tostring(capEnd) .. "）")
    local capUnknown = MDAD.Drive.dodgeVisibilityCap(s, { scanEndS = 99, unloaded = false }, 4.6)
    checkTrue(capUnknown < 1, "(dvis) 前緣不是終點（未知）：照舊壓到 0（cap=" .. tostring(capUnknown) .. "）")
    s.lastSNow = 70
    local capFar = MDAD.Drive.dodgeVisibilityCap(s, { scanEndS = 100, unloaded = false }, 4.6)
    checkNear(capFar, MDADDynamics.visibilityCapKmh(30, 0.5, 4.6, 2.1), 1e-9,
        "(dvis) 離終點 30m：照一般可視帽")
end
drive.scenarioDodgeTerminalVis()

-- 0928l 正式服 salomon 兩則回報（6289,11203 拖一般車交還；5188,11151 一直原地旋轉）：
--   (tt)  拖車要調頭：先要一條不用調頭的繞行（避讓圈在車尾正後方），等 cutover 期間停住，沒有才交還。
--         違規證明：towTurnaround 一律回 false＝(tt1) 交還紅；routeLeavesForward 恆 true＝(tt3) 收下倒車線紅；
--         避讓圈往車頭前放（fx 反號）＝(tt1) 圈心位置紅。
--   (ul)  同一處 30m 內第 4 次進入調頭＝受困交還（五趟繞圈 16～204 次、繞到手動接手）。
--         違規證明：拿掉 uturnLoop 計數＝(ul) 仍在自駕紅；範圍判定拿掉＝(ul-far) 紅。
--   (ds)  地圖資料微反折（0.7m 倒退段）在建剖面前清掉：開過去不原地調頭。
--         違規證明：despikeRoute 直接回原表＝(ds) 投影釘死、進調頭紅。
--   (dg)  Trailer.guard 讀剖面實際建構的路線，反折點不當不可過轉角（SemiTruck 在同點 TrailerCorner）。
--         違規證明：guard 改回 T.shape(s.route)＝(dg) 限速紅。
function drive.scenarioTowTurn()
    scenario("拖車要調頭改走不用調頭的繞行、同處反覆調頭受困交還、地圖微反折建剖面前清掉")
    local oldSandbox, oldVeh, oldGet = SandboxVars, dveh, getSpecificPlayer
    local oldApi = MinidoracatMiniMapAPI.navApiVersion
    local oldRoute, oldTx, oldTy, oldState = drive.nav.route, drive.nav.tx, drive.nav.ty, drive.nav.state
    local oldDetour, oldReq = drive.nav.detour, MinidoracatMiniMapAPI.requestDetour
    local wasMs = drive.frameMs(20)
    MDAD.Drive.stop(0, nil)
    getSpecificPlayer = function(n) if n == 0 then return dp end end
    MinidoracatMiniMapAPI.navApiVersion = 5
    -- 主 MOD 的 requestDetour 一算出就覆寫該玩家的路線快取（addon-api 3.10）：下一次 requestRoute 回的就是它
    MinidoracatMiniMapAPI.requestDetour = function(...)
        local r, state = oldReq(...)
        if r then drive.nav.route = r end
        return r, state
    end
    dveh = newVehicle({ battery = newItem("Base.CarBattery", { uses = 0.8 }),
        engineRunning = true, mass = 1600, speed = 0, maxSpeed = 100,
        bodyW = 1.6, bodyL = 4.2, comX = 0, comZ = 0, profileFull = true,
        enginePower = 3000, brakingForce = 100, wheelFriction = 1.5, tireFriction = 1.5 })
    local trailer = {
        getForwardVector = function(_, out) return out:set(dveh._fwdX, 0, dveh._fwdY) end,
        getUpVectorDot = function() return 1 end,
    }
    local function arm(route, tx, ty, bias)
        MDAD.Drive.stop(0, nil)
        drive.fillWorld(-90, 90, -12, 12)
        drive.putRoad(-90, 90, -3, 3)
        setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false,
            AutoDriveMaxSpeed = 60, RightLaneBias = bias or 0 })
        dveh._speed, dveh._steering, dveh._stopped = 0, 0, true
        dveh._engine, dveh._driver = true, dp
        dp._vehicle, dp._dead, dp._local = dveh, false, true
        drive.nav.route, drive.nav.tx, drive.nav.ty, drive.nav.state = route, tx, ty, "ok"
        drive.nav.detourCalls, drive.nav.lastDetour = 0, nil
        clearList(halos)
        return MDAD.Drive.start(dp)
    end
    local function behind()
        return { pts = { 0, 0, -80, 0 }, segSurface = { "paved" }, segWidth = { 8 },
            len = 80, cost = 80, avoidPenalty = 0 }
    end
    local function haloOf(key, kind)
        for i = 1, #halos do
            if halos[i].kind == kind and noteReason(halos[i].text) == key then return true end
        end
        return false
    end
    local function tickUntil(pred, n)
        for _ = 1, n do
            if pred() then return true end
            driveTick(dp, dveh)
        end
        return pred()
    end
    local towGeo = { trailer = trailer, L2 = 3, hitchToRear = 5, halfW = 0.9 }

    -- (tt1) 目標在車後、拖著車：向主 MOD 要繞行，圈心在車尾正後方 13m、半徑 12
    dveh._x, dveh._y = 0, 0
    setHeading(dveh, 0)
    -- 繞一圈回到同一個終點（1002k：requestDetourRoute 驗終點與原路線同一個）
    local fwd = { pts = { 0, 0, 60, 0, 60, 40, -80, 0 }, segSurface = { "paved", "paved", "paved" },
        segWidth = { 8, 8, 8 }, len = 100, cost = 100, avoidPenalty = 0 }
    drive.nav.detour = fwd
    checkTrue(arm(behind(), -80, 0), "(tt1) 拖車、目標在車後啟動")
    local st = MDAD.Drive.debugSession(0)
    st.tow = towGeo
    tickUntil(function() return drive.nav.detourCalls > 0 or not MDAD.Drive.isActive(0) end, 60)
    checkEq(drive.nav.detourCalls, 1, "(tt1) 要了一次繞行")
    local ld = drive.nav.lastDetour or {}
    checkEq(ld.r, 12, "(tt1) 避讓半徑 12")
    checkTrue(ld.ax ~= nil and math.abs(ld.ax + 13) < 1e-6 and math.abs(ld.ay) < 1e-6,
        "(tt1) 圈心在車尾正後方 13m（ax=" .. tostring(ld.ax) .. " ay=" .. tostring(ld.ay) .. "）")
    checkTrue(MDAD.Drive.isActive(0), "(tt1) 拿到不用調頭的路線：不交還")
    checkTrue(haloOf("UI_MinidoracatAutoDrive_TrailerTurn", "good"), "(tt1) 綠字告知改走繞行")
    tickUntil(function() return st.route == fwd end, 10)
    for _ = 1, 3 do driveTick(dp, dveh) end
    checkTrue(st.route == fwd and st.routeReadyWhy == "towturn",
        "(tt1) cutover 到繞行線（why=" .. tostring(st.routeReadyWhy) .. "）")
    checkTrue(MDAD.Drive.isActive(0) and not st.fstate.rotating and drive.nav.detourCalls == 1,
        "(tt1) 新路線朝車頭方向：不再調頭、不再要繞行（calls=" .. tostring(drive.nav.detourCalls) .. "）")
    checkTrue(st.avoidTow == true and st.avoidR == 12, "(tt1) sticky 避讓記住拖車圈")

    -- (tt2) 沒有替代路：照舊交還 TrailerRotate
    drive.nav.detour = nil
    checkTrue(arm(behind(), -80, 0), "(tt2) 拖車、沒有替代路啟動")
    MDAD.Drive.debugSession(0).tow = towGeo
    tickUntil(function() return not MDAD.Drive.isActive(0) end, 60)
    checkFalse(MDAD.Drive.isActive(0), "(tt2) 沒有不用調頭的路：交還")
    checkTrue(haloOf("UI_MinidoracatAutoDrive_TrailerRotate", "bad"), "(tt2) 紅字 TrailerRotate")

    -- (tt3) 主 MOD 給的線還是往車後出發：不收（收了等於原地調頭）
    drive.nav.detour = { pts = { 0, 0, -60, 0, -60, 40 }, segSurface = { "paved", "paved" },
        segWidth = { 8, 8 }, len = 100, cost = 100, avoidPenalty = 0 }
    checkTrue(arm(behind(), -80, 0), "(tt3) 拖車、替代路仍往後啟動")
    MDAD.Drive.debugSession(0).tow = towGeo
    tickUntil(function() return not MDAD.Drive.isActive(0) end, 60)
    checkEq(drive.nav.detourCalls, 1, "(tt3) 問過一次")
    checkFalse(MDAD.Drive.isActive(0), "(tt3) 往後出發的線不收：交還")
    drive.nav.detour = nil

    -- (ul) 沒拖車、目標在車後：同一處第 4 次進入調頭＝受困交還
    checkTrue(arm(behind(), -80, 0), "(ul) 目標在車後啟動")
    st = MDAD.Drive.debugSession(0)
    tickUntil(function() return st.uturn ~= nil or not MDAD.Drive.isActive(0) end, 60)
    checkTrue(st.uturn ~= nil, "(ul) 進入調頭")
    for _ = 2, 3 do
        st.uturn = nil
        driveTick(dp, dveh)
    end
    checkTrue(MDAD.Drive.isActive(0) and st.uturnLoopN == 3, "(ul) 第 3 次仍在自駕（N=" .. tostring(st.uturnLoopN) .. "）")
    st.uturn = nil
    driveTick(dp, dveh)
    checkFalse(MDAD.Drive.isActive(0), "(ul) 30m 內第 4 次進入調頭：受困交還")
    checkTrue(haloOf("UI_MinidoracatAutoDrive_StopStuck", "bad"), "(ul) 紅字 StopStuck")
    -- (ul-far) 每次都在 30m 外：不是繞圈，不交還
    dveh._x = 0
    checkTrue(arm(behind(), -80, 0), "(ul-far) 目標在車後啟動")
    st = MDAD.Drive.debugSession(0)
    tickUntil(function() return st.uturn ~= nil end, 60)
    for _ = 2, 4 do
        dveh._x = dveh._x + 40
        st.uturn = nil
        driveTick(dp, dveh)
    end
    checkTrue(MDAD.Drive.isActive(0) and st.uturnLoopN == 1,
        "(ul-far) 每次調頭相隔 40m：計數重來、不交還（N=" .. tostring(st.uturnLoopN) .. "）")
    dveh._x = 0

    -- (ds) 路線中段 0.7m 倒退段（161° 兩次折返）：建剖面前清掉，靠右開過去不原地調頭
    local spiky = { pts = { 0, 0, 30, 0, 29.4, -0.2, 80, 0 }, segSurface = { "paved", "paved", "paved" },
        segWidth = { 8, 8, 8 }, len = 80, cost = 80, avoidPenalty = 0 }
    dveh._x, dveh._y = 0, 1.5
    setHeading(dveh, 0)
    checkTrue(arm(spiky, 80, 0, 0.75), "(ds) 反折路線啟動")
    st = MDAD.Drive.debugSession(0)
    checkTrue(st.profileRoute ~= nil and st.profileRoute.despiked == 1 and #st.profileRoute.pts == 6,
        "(ds) 剖面路線清掉 1 點（despiked=" .. tostring(st.profileRoute and st.profileRoute.despiked) .. "）")
    checkTrue(st.route == spiky and #st.route.pts == 8, "(ds) 原 route identity 不動")
    local rotated = false
    for k = 1, 90 do
        dveh._x, dveh._y, dveh._speed, dveh._stopped = k * 0.5, 1.5, 12, false
        driveTick(dp, dveh)
        if st.fstate.rotating or st.uturn ~= nil then rotated = true end
    end
    checkFalse(rotated, "(ds) 開過反折點不進調頭")
    checkTrue(MDAD.Drive.isActive(0) and st.lastSNow > 40,
        "(ds) 投影跟著前進（s=" .. tostring(st.lastSNow) .. "）")

    -- (dg) guard 讀清過的剖面路線；原始路線直接改寫會把反折點列不可過轉角
    -- 半聯結車幾何（test_trailer 的 W900＋貨櫃）：反折點當 161° 轉角必然轉不過
    local semi = { trailer = trailer, L2 = 9.5, hitchToRear = 12, halfW = 1.27 }
    local fakeS = { tow = semi, route = spiky, towNextMs = 0, safeCoast = 1,
        profileRoute = MDAD.Drive.profileRouteOf(spiky, semi, { halfW = 1.19, halfL = 3.55 }, 0, 0, false) }
    dveh._x, dveh._y = 0, 0
    setHeading(dveh, 0)
    local cap, why = MDADTrailer.guard(fakeS, dveh, 1e12, 20)
    checkTrue(why == nil and cap == nil,
        "(dg) 反折點不當不可過轉角（cap=" .. tostring(cap) .. " why=" .. tostring(why) .. "）")
    local raw = MDADTrailer.shape(spiky, semi, 1.19, 7.1)
    checkTrue(#raw.towBlocked > 0, "(dg) 對照：原始路線直接改寫會列不可過轉角")

    MDAD.Drive.stop(0, nil)
    drive.frameMs(wasMs)
    MinidoracatMiniMapAPI.requestDetour = oldReq
    MinidoracatMiniMapAPI.navApiVersion = oldApi
    drive.nav.route, drive.nav.tx, drive.nav.ty, drive.nav.state = oldRoute, oldTx, oldTy, oldState
    drive.nav.detour = oldDetour
    SandboxVars, dveh, getSpecificPlayer = oldSandbox, oldVeh, oldGet
end
drive.scenarioTowTurn()
-- (tc) 1005 拖車路線上有過不去的轉角（MDADTrailer.shape 的 towBlocked）：得知當下先要一條避開那些轉角的改道
--   （Drive.towCornerDetour），新線走同一條剖面管線（profileRouteOf → shape）後沒有不可過轉角才收；否則拒收、保留
--   原線，照舊停在轉角前交還 TrailerCorner。fixture：半聯結車（test_trailer 的 W900＋貨櫃）、4m 巷兩個直角都不可過。
--   (tc-ok)      起步第一個跟線幀（離轉角 60m）就問：主圈＝第一個轉角、半徑＝路口方塊半對角線＋PAD、moreAvoid＝第二個
--                轉角；收下、cutover why=towcorner、新剖面沒有 towBlocked、不交還。違規證明：拿掉 towCornerDetour 呼叫＝
--                calls 紅；半徑不加 towBlockedR＝半徑紅；不附其餘轉角＝more 紅。
--   (tc-near)    已停在轉角前 18m 才得知：收下後等 cutover、不交還。違規證明：拿掉 guard 後的等待＝紅。
--   (tc-blocked) 替代路仍是 4m 直角：拒收 blocked、記 rejectedRoute、原線不換，開到轉角前照舊交還 TrailerCorner。
--                違規證明：不驗新剖面（left 恆 0）＝紅。
--   (tc-once)    同一（route identity、轉角集合）只問一次：剖面重建同一條線不重問；新 identity 再問，到 TRIES 上限記
--                skip max。違規證明：拿掉 pair 判定＝重建紅；拿掉 TRIES 上限＝max 紅。
--   (tc-v8)      nav API 8：只給主圈（more=nil），回來的線穿第二個轉角圈＝拒收 again。違規證明：拿掉自驗＝紅。
--   (tc-off)     「堵死時自動改道」關：不問、記 skip off。違規證明：拿掉選項閘＝紅。
--   (tc-solo)    沒拖車：剖面帶 towBlocked 也不問。違規證明：呼叫搬到拖車分支外＝紅。
function drive.scenarioTowCorner()
    scenario("拖車過不去的轉角：得知當下先要避開的改道，替代線剖面也過不去才照舊交還")
    local oldSandbox, oldVeh, oldGet = SandboxVars, dveh, getSpecificPlayer
    local oldApi = MinidoracatMiniMapAPI.navApiVersion
    local oldRoute, oldTx, oldTy, oldState = drive.nav.route, drive.nav.tx, drive.nav.ty, drive.nav.state
    local oldDetour, oldReq = drive.nav.detour, MinidoracatMiniMapAPI.requestDetour
    local oldAuto, oldEvent = MDAD.HUD.autoDetour, MDADDiagnostics.event
    local wasMs = drive.frameMs(20)
    local T = MDAD.Drive.debugTune()
    MDAD.Drive.stop(0, nil)
    getSpecificPlayer = function(n) if n == 0 then return dp end end
    MinidoracatMiniMapAPI.requestDetour = function(...)
        local r, state = oldReq(...)
        if r then drive.nav.route = r end -- 主 MOD 算出就覆寫快取（addon-api 3.10）
        return r, state
    end
    local ev = {}
    MDADDiagnostics.event = function(pn, name, a, ...)
        if name == "detour" and type(a) == "table" and a.kind == "towcorner" then ev[#ev + 1] = a end
        return oldEvent(pn, name, a, ...)
    end
    local autoOn = true
    MDAD.HUD.autoDetour = function() return autoOn end
    dveh = newVehicle({ battery = newItem("Base.CarBattery", { uses = 0.8 }),
        engineRunning = true, mass = 1600, speed = 0, maxSpeed = 100,
        bodyW = 1.6, bodyL = 4.2, comX = 0, comZ = 0, profileFull = true,
        enginePower = 3000, brakingForce = 100, wheelFriction = 1.5, tireFriction = 1.5 })
    local trailer = {
        getForwardVector = function(_, out) return out:set(dveh._fwdX, 0, dveh._fwdY) end,
        getUpVectorDot = function() return 1 end,
    }
    local semi = { trailer = trailer, L2 = 9.5, hitchToRear = 12, halfW = 1.27 }
    local function road(pts, w)
        local sw, ss, len = {}, {}, 0
        for i = 1, #pts / 2 - 1 do
            sw[i], ss[i] = w, "paved"
            len = len + math.sqrt((pts[i * 2 + 1] - pts[i * 2 - 1]) ^ 2 + (pts[i * 2 + 2] - pts[i * 2]) ^ 2)
        end
        return { pts = pts, segSurface = ss, segWidth = sw, len = len, cost = len, avoidPenalty = 0 }
    end
    -- 4m 巷：(60,0)、(60,60) 兩個直角，半聯結車都轉不過
    local function lanes(x0) return road({ x0 or 0, 0, 60, 0, 60, 60, 0, 60 }, 4) end
    -- 12m 大弧（每點只轉 20°＝沒有要外拉的轉角）：從 (x0,0) 朝 +x 出發、繞到 (x0,60)，再接回同一個終點
    local function arc(x0)
        local p = {}
        for k = 0, 9 do
            local th = math.rad(-90 + 20 * k)
            p[#p + 1], p[#p + 2] = x0 + 30 * math.cos(th), 30 + 30 * math.sin(th)
        end
        if x0 ~= 0 then p[#p + 1], p[#p + 2] = 0, 60 end
        return road(p, 12)
    end
    local function arm(route, x0, tow, api)
        MDAD.Drive.stop(0, nil)
        drive.fillWorld(-10, 80, -12, 72)
        drive.putRoad(-10, 80, -3, 3)
        setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false, AutoDriveMaxSpeed = 60, RightLaneBias = 0 })
        dveh._x, dveh._y = x0, 0
        setHeading(dveh, 0)
        dveh._speed, dveh._steering, dveh._stopped = 0, 0, true
        dveh._engine, dveh._driver = true, dp
        dp._vehicle, dp._dead, dp._local = dveh, false, true
        MinidoracatMiniMapAPI.navApiVersion = api or 9
        drive.nav.route, drive.nav.tx, drive.nav.ty, drive.nav.state = route, 0, 60, "ok"
        drive.nav.detourCalls, drive.nav.lastDetour = 0, nil
        clearList(halos)
        clearList(ev)
        if not MDAD.Drive.start(dp) then return nil end
        local st = MDAD.Drive.debugSession(0)
        st.diag = true
        -- 起步時就拖著（假車沒有 getVehicleTowing）：剖面路線照 production 管線改寫，guard 讀它
        st.tow = tow
        st.profileRoute = MDAD.Drive.profileRouteOf(route, tow or semi, st.vehicleProfile, x0, 0, false)
        return st
    end
    local function haloOf(key, kind)
        for i = 1, #halos do
            if halos[i].kind == kind and noteReason(halos[i].text) == key then return true end
        end
        return false
    end
    local function tickUntil(pred, n) -- driveTick 不推時間：每幀推 20ms（guard 節流、取路間隔才會過）
        for _ = 1, n do
            if pred() then return true end
            nowMs = nowMs + 20
            -- 假車的物理取樣會讓診斷 fail 關掉 s.diag（velocity-read-fail）；本案只收事件，每幀重開
            local cur = MDAD.Drive.debugSession(0)
            if cur then cur.diag = true end
            driveTick(dp, dveh)
        end
        return pred()
    end
    local function tick(n) tickUntil(function() return false end, n) end
    local r0 = 2 * math.sqrt(2) + T.TOW_CORNER_AVOID_PAD -- 4m×4m 路口方塊半對角線＋PAD

    -- (tc-ok)
    local alt = arc(0)
    drive.nav.detour = alt
    local st = arm(lanes(), 0, semi)
    checkTrue(st ~= nil and #st.profileRoute.towBlocked == 4, "(tc-ok) 拖車、路線上兩個不可過轉角啟動")
    tickUntil(function() return drive.nav.detourCalls > 0 or not MDAD.Drive.isActive(0) end, 30)
    checkTrue(drive.nav.detourCalls == 1 and dveh._x == 0,
        "(tc-ok) 還在起點（離轉角 60m）就要了一次改道（calls=" .. tostring(drive.nav.detourCalls) .. "）")
    local ld = drive.nav.lastDetour or {}
    checkTrue(ld.ax == 60 and ld.ay == 0, "(tc-ok) 主圈＝第一個不可過轉角（" .. tostring(ld.ax) .. "," .. tostring(ld.ay) .. "）")
    checkNear(ld.r, r0, 1e-9, "(tc-ok) 主圈半徑蓋住整個路口方塊")
    local more = ld.more
    checkTrue(type(more) == "table" and #more == 3 and more[1] == 60 and more[2] == 60 and math.abs(more[3] - r0) < 1e-9,
        "(tc-ok) moreAvoid＝其餘不可過轉角（n=" .. tostring(more and #more) .. "）")
    checkTrue(MDAD.Drive.isActive(0) and haloOf("UI_MinidoracatAutoDrive_Detour", "good"), "(tc-ok) 收下：綠字改道、不交還")
    tickUntil(function() return st.route == alt end, 30)
    tick(3)
    checkTrue(st.route == alt and st.routeReadyWhy == "towcorner" and #st.profileRoute.towBlocked == 0,
        "(tc-ok) cutover 到替代線（why=" .. tostring(st.routeReadyWhy) .. "）、新剖面沒有不可過轉角")
    checkTrue(MDAD.Drive.isActive(0) and drive.nav.detourCalls == 1, "(tc-ok) 新線不再問、仍在自駕")
    local e1 = ev[1] or {}
    checkTrue(#ev == 1 and e1.phase == "towcorner" and e1.why == "ok" and e1.towN == 2 and e1.avoidN == 1
        and e1.hitX == 60 and e1.attempt == 1,
        "(tc-ok) detour 事件 phase=towcorner why=ok towN=2 avoidN=1（why=" .. tostring(e1.why) .. "）")

    -- (tc-near) 已停在轉角前 18m 才得知
    alt = arc(42)
    drive.nav.detour = alt
    st = arm(lanes(42), 42, semi)
    tickUntil(function() return st.route == alt or not MDAD.Drive.isActive(0) end, 30)
    checkTrue(MDAD.Drive.isActive(0) and st.route == alt and drive.nav.detourCalls == 1,
        "(tc-near) 停在轉角前：等 cutover 不交還、換到替代線")

    -- (tc-blocked) 替代路仍不可過
    local bad = road({ 0, 0, 30, 0, 30, 60, 0, 60 }, 4)
    drive.nav.detour = bad
    local orig = lanes()
    st = arm(orig, 0, semi)
    tickUntil(function() return drive.nav.detourCalls > 0 end, 30)
    tick(20)
    e1 = ev[1] or {}
    checkTrue(drive.nav.detourCalls == 1 and e1.why == "blocked" and e1.towLeft == 2 and st.rejectedRoute == bad,
        "(tc-blocked) 替代線剖面仍有不可過轉角：拒收 blocked（left=" .. tostring(e1.towLeft) .. "）")
    checkTrue(st.route == orig and MDAD.Drive.isActive(0) and not haloOf("UI_MinidoracatAutoDrive_Detour", "good"),
        "(tc-blocked) 原線不換、仍在自駕")
    dveh._x = 42
    tickUntil(function() return not MDAD.Drive.isActive(0) end, 30)
    checkTrue(not MDAD.Drive.isActive(0) and haloOf("UI_MinidoracatAutoDrive_TrailerCorner", "bad"),
        "(tc-blocked) 開到轉角前照舊交還 TrailerCorner")
    checkEq(drive.nav.detourCalls, 1, "(tc-once) 同一條線從起步到交還只問一次")

    -- (tc-once) 剖面重建同一條線不重問；新 identity 再問，第 TRIES+1 次記 skip max
    st = arm(lanes(), 0, semi)
    tickUntil(function() return drive.nav.detourCalls > 0 end, 30)
    local cp = {}
    for k, v in pairs(st.profileRoute) do cp[k] = v end
    st.profileRoute = cp
    tick(5)
    checkEq(drive.nav.detourCalls, 1, "(tc-once) 剖面重建同一條 route：不重問")
    local function recut(cost)
        local nr = lanes()
        nr.cost = cost -- 同幾何、不同 cost＝新 identity，照常 cutover（不被同目標防抖吃掉）
        drive.nav.route = nr
        tickUntil(function() return st.route == nr end, 30)
        tick(5)
        return st.route == nr
    end
    checkTrue(recut(181) and drive.nav.detourCalls == T.TOW_CORNER_TRIES,
        "(tc-once) 新 identity 再問一次（calls=" .. tostring(drive.nav.detourCalls) .. "）")
    checkTrue(recut(182) and drive.nav.detourCalls == T.TOW_CORNER_TRIES and ev[#ev].phase == "skip"
        and ev[#ev].why == "max",
        "(tc-once) 到上限不再問、記 skip max（why=" .. tostring(ev[#ev] and ev[#ev].why) .. "）")

    -- (tc-v8) API 8：只給主圈、自己驗不穿其他圈
    local v8 = road({ 0, 0, 20, 0, 40, 8, 55, 25, 62, 40, 62, 62, 0, 62 }, 12)
    drive.nav.detour = v8
    st = arm(lanes(), 0, semi, 8)
    tickUntil(function() return drive.nav.detourCalls > 0 end, 30)
    ld = drive.nav.lastDetour or {}
    e1 = ev[1] or {}
    checkTrue(drive.nav.detourCalls == 1 and ld.more == nil and ld.ax == 60 and e1.why == "again"
        and st.rejectedRoute == v8,
        "(tc-v8) API 8 只給主圈、穿第二個轉角圈的線拒收 again（why=" .. tostring(e1.why) .. "）")

    -- (tc-off) 自動改道關
    autoOn = false
    drive.nav.detour = arc(0)
    st = arm(lanes(), 0, semi)
    tick(20)
    e1 = ev[1] or {}
    checkTrue(drive.nav.detourCalls == 0 and e1.phase == "skip" and e1.why == "off",
        "(tc-off) 自動改道關：不問、記 skip off（calls=" .. tostring(drive.nav.detourCalls) .. "）")
    autoOn = true

    -- (tc-solo) 沒拖車
    st = arm(lanes(), 0, nil)
    checkTrue(#st.profileRoute.towBlocked == 4, "(tc-solo) 剖面帶不可過轉角")
    tick(20)
    checkTrue(drive.nav.detourCalls == 0 and #ev == 0, "(tc-solo) 沒拖車不問")

    MDAD.Drive.stop(0, nil)
    drive.frameMs(wasMs)
    MinidoracatMiniMapAPI.requestDetour = oldReq
    MinidoracatMiniMapAPI.navApiVersion = oldApi
    MDAD.HUD.autoDetour, MDADDiagnostics.event = oldAuto, oldEvent
    drive.nav.route, drive.nav.tx, drive.nav.ty, drive.nav.state = oldRoute, oldTx, oldTy, oldState
    drive.nav.detour = oldDetour
    SandboxVars, dveh, getSpecificPlayer = oldSandbox, oldVeh, oldGet
end
drive.scenarioTowCorner()
-- 0928m 交還前的最後一次改道（Drive.stuckDetour；使用者裁定「遇大量障礙可改道」）：E2E rc13 12 個固定堵點
-- 開著自動改道仍 0 次改道——舊觸發只在 blocked 停等 WAIT，實際堵死多在倒車額度用完後的停等預算／倒車
-- 逾時交還。違規證明：拿掉停等預算出口的 stuckDetour＝(sd1) 紅；拿掉 NEAR_M 判定＝(sd2) 紅。
function drive.scenarioStuckDetour()
    scenario("交還前先要一條替代路線：拿到就繼續開、同處不重問、選項關著照舊交還")
    local oldSandbox, oldGet = SandboxVars, getSpecificPlayer
    local oldApi = MinidoracatMiniMapAPI.navApiVersion
    local oldRoute, oldTx, oldTy, oldState = drive.nav.route, drive.nav.tx, drive.nav.ty, drive.nav.state
    local oldDetour, oldReq, oldAuto = drive.nav.detour, MinidoracatMiniMapAPI.requestDetour, MDAD.HUD.autoDetour
    local wasMs = drive.frameMs(20)
    MDAD.Drive.stop(0, nil)
    getSpecificPlayer = function(n) if n == 0 then return dp end end
    MinidoracatMiniMapAPI.navApiVersion = 5
    MinidoracatMiniMapAPI.requestDetour = function(...)
        local r, state = oldReq(...)
        if r then drive.nav.route = r end
        return r, state
    end
    local function arm(auto)
        MDAD.Drive.stop(0, nil)
        MDAD.HUD.autoDetour = function() return auto end
        drive.fillWorld(-90, 120, -12, 12)
        drive.putRoad(-90, 120, -3, 3)
        setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false, AutoDriveMaxSpeed = 60, RightLaneBias = 0 })
        dveh._x, dveh._y = 0, 0
        setHeading(dveh, 0)
        dveh._speed, dveh._steering, dveh._stopped = 0, 0, true
        dveh._engine, dveh._driver = true, dp
        dp._vehicle, dp._dead, dp._local = dveh, false, true
        drive.nav.route = { pts = { 0, 0, 100, 0 }, segSurface = { "paved" }, segWidth = { 8 }, len = 100, cost = 100,
            avoidPenalty = 0 }
        drive.nav.tx, drive.nav.ty, drive.nav.state = 100, 0, "ok"
        drive.nav.detourCalls, drive.nav.lastDetour = 0, nil
        -- 繞一大圈（2 km）：一般改道上限（剩餘 100×1.5＋200＝350）會拒收 long，交還前改道要收
        drive.nav.detour = { pts = { 0, 0, 0, 40, 100, 40, 100, 0 }, segSurface = { "paved", "paved", "paved" },
            segWidth = { 8, 8, 8 }, len = 2000, cost = 2000, avoidPenalty = 0 }
        local ok = MDAD.Drive.start(dp)
        for _ = 1, 4 do driveTick(dp, dveh) end
        return ok
    end
    -- (sd1) 停等預算用完：先要替代路線，拿到就不交還、預算歸零
    checkTrue(arm(true), "(sd1) 啟動")
    local st = MDAD.Drive.debugSession(0)
    st.waitAccumMs = 20000
    driveTick(dp, dveh)
    checkTrue(MDAD.Drive.isActive(0) and drive.nav.detourCalls == 1 and st.waitAccumMs < 1000,
        "(sd1) 停等預算用完：要了替代路線（2 km 繞行也收）、session 繼續（calls=" .. tostring(drive.nav.detourCalls)
        .. " wait=" .. tostring(st.waitAccumMs) .. "）")
    -- (sd2) 同一處再用完：不重問，照常交還
    st = MDAD.Drive.debugSession(0)
    if st then
        st.waitAccumMs = 20000
        driveTick(dp, dveh)
    end
    checkTrue(not MDAD.Drive.isActive(0) and drive.nav.detourCalls == 1,
        "(sd2) 同一處第二次用完：不重問、交還（calls=" .. tostring(drive.nav.detourCalls) .. "）")
    -- (sd3) 選項關著：照舊交還、不問
    checkTrue(arm(false), "(sd3) 啟動")
    st = MDAD.Drive.debugSession(0)
    st.waitAccumMs = 20000
    driveTick(dp, dveh)
    checkTrue(not MDAD.Drive.isActive(0) and drive.nav.detourCalls == 0, "(sd3) 自動改道關著：直接交還、不問")
    -- (sd4) 找不到替代路線：問一次後交還
    checkTrue(arm(true), "(sd4) 啟動")
    drive.nav.detour = nil
    st = MDAD.Drive.debugSession(0)
    st.waitAccumMs = 20000
    driveTick(dp, dveh)
    checkTrue(not MDAD.Drive.isActive(0) and drive.nav.detourCalls == 1, "(sd4) 沒有替代路線：問一次後交還")
    -- (sd5) 替代線被拒收 far、但主 MOD 已把它寫進快取：下一次取路不得拿它觸發 RouteTooFar 交還
    --   （E2E rc15 0095）。違規證明：拒收略過搬回距離閘之後＝紅。
    checkTrue(arm(true), "(sd5) 啟動")
    drive.nav.detour = { pts = { 60, 30, 100, 30, 100, 0 }, segSurface = { "paved", "paved" }, segWidth = { 8, 8 },
        len = 200, cost = 200, avoidPenalty = 0, snapDist = 35 }
    local okD, whyD = MDAD.Drive.requestDetour(0, true)
    checkTrue(okD == false and whyD == "far" and drive.nav.route == drive.nav.detour,
        "(sd5) far 被拒收、快取已被覆寫（why=" .. tostring(whyD) .. "）")
    for _ = 1, 20 do
        nowMs = nowMs + 100
        driveTick(dp, dveh)
    end
    checkTrue(MDAD.Drive.isActive(0), "(sd5) 拒收的 far 線留在快取：不因它 RouteTooFar 交還")
    -- (sd6) 跟線中倒車待命（recoverWhy）時換線：先 build，不拿未建好的剖面跟線（E2E rc15 0094／0118 同幀
    --   UnsupportedVehicle）。違規證明：cutover 對 follow 不改 build＝紅。
    checkTrue(arm(true), "(sd6) 啟動")
    st = MDAD.Drive.debugSession(0)
    st.recoverWhy = "blocked-retry"
    drive.nav.route = { pts = { 0, 0, 50, 0, 100, 0 }, segSurface = { "paved", "paved" }, segWidth = { 8, 8 },
        len = 100, cost = 100.5, avoidPenalty = 0 }
    -- 實機是邊煞車邊等倒車（13 km/h，capReason recover）時換線：車還在動，stepFollow 每幀跑 control
    dveh._speed, dveh._stopped = 13, false
    local realControl, unready = MDADFollower.control, 0
    MDADFollower.control = function(p, ...)
        if p.ready ~= true then unready = unready + 1 end
        return realControl(p, ...)
    end
    for _ = 1, 6 do
        nowMs = nowMs + 100
        driveTick(dp, dveh)
    end
    MDADFollower.control = realControl
    dveh._speed, dveh._stopped = 0, true
    checkTrue(MDAD.Drive.isActive(0) and st.route == drive.nav.route and unready == 0,
        "(sd6) 倒車待命中換線：換上新線、不拿未建好的剖面跟線（unready=" .. unready .. " mode="
        .. tostring(st.mode) .. "）")
    MDAD.Drive.stop(0, nil)
    MDAD.HUD.autoDetour, MinidoracatMiniMapAPI.requestDetour = oldAuto, oldReq
    drive.nav.detour = oldDetour
    drive.nav.route, drive.nav.tx, drive.nav.ty, drive.nav.state = oldRoute, oldTx, oldTy, oldState
    MinidoracatMiniMapAPI.navApiVersion = oldApi
    SandboxVars, getSpecificPlayer = oldSandbox, oldGet
    drive.frameMs(wasMs)
end
drive.scenarioStuckDetour()

-- 0928a 正式服 0.13.1 片段修正（各段違規證明寫在段首）：
--   (aw)          前方區域未載入的引擎煞車：不判卡死、不倒車、HUD 顯示等待、等滿上限才以專屬理由交還。
--                 違規證明：progressPauseMs 不看 areaWaitActive＝8 秒內 suspect 紅；areaWait 恆 false＝HUD／理由紅。
--   (ret-rot)     RETURN 待命中被甩成調頭姿態：調頭接手即結束 RETURN。違規證明：拿掉 stepFollow 的呼叫即紅。
--   (esc)         車身 yaw 率限制：自轉同向 steer 收掉、反向不限、一般過彎與高幀率子步不誤判。
--                 違規證明：yawGovern 原樣回 steer＝(esc)／(esc-wire) 紅；ESC_WINDOW_MS 改 0＝(esc-fps) 紅。
--   (sg)          起步近物限速：前半車身旁有硬物且還沒貼上車道時照淨距限速，對正 1 秒後解除。
--                 違規證明：startGuardApply 原樣回 target＝紅。
--   (dassist)     繞行超速的中線減速輔助放大到 DODGE_ASSIST_MAX。違規證明：拿掉繞行分支＝0 紅。
--   (proof-stale) 證明線被越過＝丟掉等重建，不當車輛不支援交還。違規證明：退回 fault＝session 結束紅。
--   (far)         離線 >20m 持續 4 秒才以 RouteTooFar 交還；回到路線附近計時歸零。
--                 違規證明：routeFarWatch 恆 false＝不交還紅。
function drive.scenario0928()
    scenario("0928a：區域載入等待／RETURN 讓調頭／yaw 率限制／起步近物／繞行補減速／證明過期／離線過遠")
    local oldVeh, oldSandbox = dveh, SandboxVars
    local wasMs = drive.frameMs(20)
    local Dr, T = MDAD.Drive, MDAD.Drive.debugTune()
    MDAD.Drive.stop(0, nil)
    dveh = newVehicle({ battery = newItem("Base.CarBattery", { uses = 0.8 }),
        engineRunning = true, mass = 1200, speed = 20, maxSpeed = 90,
        bodyW = 2.0, bodyL = 5.2, comX = 0, comZ = 0, profileFull = true,
        enginePower = 3000, brakingForce = 100, wheelFriction = 1.5, tireFriction = 1.5 })
    setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false, AutoDriveMaxSpeed = 40,
        ObstaclePolicy = 1, RightLaneBias = 0 })
    local function ticks(n, ms)
        for _ = 1, n do
            nowMs = nowMs + ms
            driveReset(dveh)
            driveTick(dp, dveh)
        end
    end

    -- (aw) 前方區域未載入
    drive.fillWorld(-10, 70, -7, 7)
    checkTrue(armDrive(), "(aw) 啟動")
    setHeading(dveh, 0)
    driveTick(dp, dveh)
    local st = Dr.debugSession(0)
    dveh.isInvalidChunkAhead = function(self) return self._invalidAhead == true end
    dveh._invalidAhead, dveh._braking, dveh._speed = true, true, 0
    local bad = false
    for _ = 1, 80 do
        ticks(1, 100)
        local ps = st.progressState
        if (ps ~= "watch" and ps ~= "disarmed") or st.mode == "unstick" then bad = true end
    end
    checkFalse(bad, "(aw) 前方區域未載入 8 秒：不判卡死、不倒車")
    checkTrue(Dr.isActive(0), "(aw) 等待中仍在自駕")
    checkEq(Dr.hudState(0), "areawait", "(aw) HUD 顯示等待區域載入")
    dveh._invalidAhead, dveh._braking = false, false
    ticks(1, 100)
    checkFalse(st.areaWaitActive, "(aw) 區域載入後解除等待")
    dveh._invalidAhead, dveh._braking = true, true
    clearList(halos)
    local waited = 0
    while waited <= T.AREA_WAIT_MAX_MS + 500 and Dr.isActive(0) do
        ticks(1, 100)
        waited = waited + 100
    end
    checkFalse(Dr.isActive(0), "(aw) 連續等滿上限才交還")
    checkTrue(waited >= T.AREA_WAIT_MAX_MS, "(aw) 不提早交還（等了 " .. waited .. "ms）")
    checkEq(haloKey(), "UI_MinidoracatAutoDrive_AreaLoadStop", "(aw) 交還理由＝前方區域未載入")
    dveh.isInvalidChunkAhead, dveh._invalidAhead, dveh._braking = nil, nil, false

    -- (ret-rot) RETURN 待命中被甩成調頭姿態
    MDAD.Drive.stop(0, nil)
    setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false, AutoDriveMaxSpeed = 40,
        ObstaclePolicy = 1, RightLaneBias = 1.5 })
    drive.fillWorld(-10, 170, -15, 15)
    dveh._x, dveh._y, dveh._speed, dveh._steering, dveh._stopped = 0, -4, 10, 0, false
    dveh._engine, dveh._driver = true, dp
    dp._vehicle, dp._dead, dp._local = dveh, false, true
    setHeading(dveh, 0)
    drive.nav.tx, drive.nav.ty, drive.nav.state = 300, 0, "ok"
    drive.nav.route = newRoute(40, 0, 0, 4, 0)
    driveReset(dveh)
    checkTrue(Dr.start(dp), "(ret-rot) 線外 4m 啟動")
    for _ = 1, 4 do driveTick(dp, dveh) end
    drive.scanRound(true)
    drive.scanRound(true)
    st = Dr.debugSession(0)
    checkTrue(st ~= nil and st.returnActive == true, "(ret-rot) 前置：RETURN 中")
    st.returnHold = true
    setHeading(dveh, math.pi)
    dveh._speed = 0
    ticks(1, 20)
    checkTrue(st.fstate.rotating == true, "(ret-rot) 前置：Follower 判調頭")
    checkFalse(st.returnActive, "(ret-rot) 調頭接手即結束 RETURN")
    checkEq(st.planMode, "return-rotate", "(ret-rot) 釋放理由記 rotate")
    MDAD.Drive.stop(0, nil)
    setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false, AutoDriveMaxSpeed = 40,
        ObstaclePolicy = 1, RightLaneBias = 0 })

    -- (esc) 車身 yaw 率限制
    local es = { vehicleProfile = { rMin = 2.2 }, safeLat = 4.2 }
    local t, h = 1000, 0
    Dr.yawGovern(es, 3.9, h, 18, t)
    t, h = t + 30, h + 6.4 * 0.03
    local g = Dr.yawGovern(es, 3.9, h, 18, t)
    checkTrue(g < 3.9 * 0.2 and es.escScale < 0.2,
        "(esc) 18 km/h 自轉 6.4 rad/s：同向 steer 收掉（實得 " .. tostring(g) .. "）")
    t, h = t + 30, h + 6.4 * 0.03
    checkEq(Dr.yawGovern(es, -2, h, 18, t), -2, "(esc) 反向（修正自轉）steer 不受限")
    local en = { vehicleProfile = { rMin = 2.2 }, safeLat = 4.2 }
    t, h = 5000, 0
    Dr.yawGovern(en, 1, h, 18, t)
    t, h = t + 30, h + (5 / 12) * 0.03
    checkEq(Dr.yawGovern(en, 1, h, 18, t), 1, "(esc) R 12m 一般過彎的 yaw 率不收")
    local hf = { vehicleProfile = { rMin = 2.2 }, safeLat = 4.2 }
    t, h = 9000, 0
    local minOut = 1
    for _ = 1, 40 do
        t = t + 4
        if t % 10 < 4 then h = h + 0.8 * 0.01 end
        local out = Dr.yawGovern(hf, 1, h, 18, t)
        if out < minOut then minOut = out end
    end
    checkEq(minOut, 1, "(esc-fps) 250 FPS、heading 每 10ms 子步才變：0.8 rad/s 一般修正不誤判")
    -- wiring：車頭 57° 偏右（追線要往右轉）又以 3.3 rad/s 往右自轉＝同向 steer 被收
    drive.fillWorld(-10, 70, -7, 7)
    checkTrue(armDrive(), "(esc-wire) 啟動")
    st = Dr.debugSession(0)
    local hw = 1.0
    setHeading(dveh, hw)
    ticks(1, 30)
    local minScale, flagged = 1, false
    for _ = 1, 4 do
        hw = hw - 0.1
        setHeading(dveh, hw)
        ticks(1, 30)
        if st.escScale < minScale then minScale = st.escScale end
        if st.escScale < 1 and st.fstate.escLimited == true then flagged = true end
    end
    checkTrue(minScale < 1, "(esc-wire) stepFollow 經 yaw 率限制才施側推（最小比例 " .. tostring(minScale) .. "）")
    checkTrue(flagged, "(esc-wire) 被收掉的幀告知 Follower（fstate.escLimited）：側滑幀不進高速增益學習")

    -- (sg) 起步近物限速
    MDAD.Drive.stop(0, nil)
    drive.fillWorld(-10, 70, -7, 7)
    drive.putSolid(5, 2, "start_guard_pole")
    checkTrue(armDrive(), "(sg) 啟動（車頭斜 17°、右前 3m 有桿）")
    st = Dr.debugSession(0)
    drive.scanRound(true)
    local capHit = false
    for _ = 1, 3 do
        ticks(1, 20)
        if st.lastCapReason == "start-near"
                or (st.lastCapReason == "min-exec" and st.minExecFrom == "start-near") then capHit = true end
    end
    checkTrue(st.startGuard == true, "(sg) 未貼上車道：起步近物限速仍武裝")
    checkTrue(capHit, "(sg) 前半車身旁有桿：照淨距限速（capReason=" .. tostring(st.lastCapReason)
        .. " from=" .. tostring(st.minExecFrom) .. " fc=" .. tostring(st.frontClearance)
        .. " coast=" .. tostring(st.safeCoast) .. "）")
    drive.clearCell(5, 2)
    dveh._x, dveh._y = 0, 0
    setHeading(dveh, 0)
    ticks(15, 100)
    checkFalse(st.startGuard, "(sg) 對正並貼上車道 1 秒：解除")

    -- (dassist) 繞行超速的中線減速輔助
    local da = { tow = false, sensor = { ready = true }, visibilityCap = 80, dodging = true,
        dodgeApproachCap = 18.24, runtimeMass = 1457 }
    local f = Dr.visAssistForce(da, 63.5, 0.8)
    checkTrue(f > 0 and math.abs(da.visAssistDecel - T.DODGE_ASSIST_MAX) < 1e-9,
        "(dassist) 63 km/h 承諾 cap 18 的繞行：補到 DODGE_ASSIST_MAX（實得 " .. tostring(da.visAssistDecel) .. "）")
    da.dodging = false
    Dr.visAssistForce(da, 63.5, 0.8)
    checkEq(da.visAssistDecel, 0, "(dassist) 沒在繞行：可視帽 80 以下不補")
    da.dodging, da.dodgeApproachCap = true, 70
    Dr.visAssistForce(da, 63.5, 0.8)
    checkEq(da.visAssistDecel, 0, "(dassist) 繞行帽高於實速：不補")

    -- (blk-app) 0928b E2E rc1 0005：重車 70 km/h 在 68m 外判 blocked，舊制只把目標壓 20 滑行、
    --   到停止線仍 34 km/h、撞前車。現制：以規劃煞車能力反推「停止線降到 20」的包絡，
    --   略超＝中線減速輔助、超過硬煞門檻＝一秒鎖輪。違規證明：包絡恆 nil／輔助不認包絡／不硬煞各紅。
    local bq = { blockS = 100, lastSNow = 30, blockHitX = 100, blockHitY = 0, safeBrake = 4.6,
        cornerLatch = false }
    local bcap = Dr.blockedApproachCap(bq, 30, 0)
    checkNear(bcap, MDADDynamics.approachCapKmh(70 - T.BLOCK_STOP_DIST, T.BLOCK_APPROACH_KMH, 0.5,
        4.6 * T.APPROACH_BRAKE_FRAC), 1e-9, "(blk-app) 包絡＝在停止線降到 BLOCK_APPROACH_KMH（規劃煞車）")
    local ba = { tow = false, sensor = { ready = true }, visibilityCap = 90, dodging = false,
        blockedApproachCap = bcap, runtimeMass = 3000 }
    Dr.visAssistForce(ba, bcap + 4, 0.8)
    checkTrue(ba.visAssistDecel > 0, "(blk-app) 超過包絡：中線減速輔助（實得 " .. tostring(ba.visAssistDecel) .. "）")
    ba.blockedApproachCap = nil
    Dr.visAssistForce(ba, bcap + 4, 0.8)
    checkEq(ba.visAssistDecel, 0, "(blk-app) 沒有 blocked 包絡：可視帽以下不補")
    MDAD.Drive.stop(0, nil)
    setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false, AutoDriveMaxSpeed = 90,
        ObstaclePolicy = 1, RightLaneBias = 0 })
    drive.fillWorld(-10, 90, -9, 9)
    for y = -9, 9 do drive.putSolid(50, y, "blk_app_wall_" .. y) end
    checkTrue(armDrive(), "(blk-app) 啟動（前方 50m 整排牆）")
    setHeading(dveh, 0)
    st = Dr.debugSession(0)
    for _ = 1, 3 do drive.scanRound(true) end
    checkTrue(st.blocked == true, "(blk-app) 前置：判 blocked")
    local capNow = Dr.blockedApproachCap(st, dveh._x, dveh._y)
    dveh._speed = capNow + 1.5
    st.forceBrakeUntil = 0
    ticks(1, 20)
    checkTrue(MDADDynamics.finite(st.blockedApproachCap) and st.visAssistDecel > 0 and st.lastHardBrakeReason == nil,
        "(blk-app) 略超包絡：減速輔助、不鎖輪（cap=" .. tostring(st.blockedApproachCap) .. " vad="
        .. tostring(st.visAssistDecel) .. " hbr=" .. tostring(st.lastHardBrakeReason) .. "）")
    dveh._speed = capNow + 12
    st.forceBrakeUntil = 0
    ticks(1, 20)
    checkEq(st.lastHardBrakeReason, "blocked-approach", "(blk-app) 遠超包絡：硬煞")
    -- 1001e：25 km/h 以上改不鎖輪（正式服 0.16.0 GTR 50 km/h、MR2 64 km/h 在 22–56m 外判 blocked 就一秒鎖到 0，
    --   下一輪就承諾了 18 km/h 的繞行）：斷油＋中線外力，停止線的 blockedStop 照舊鎖輪兜底。
    --   違規證明：hardBrake 拿掉 blocked-approach＝這條紅。
    checkTrue((st.forceBrakeUntil or 0) == 0 and math.abs((st.visAssistDecel or 0) - T.TOW_BRAKE_DECEL) < 1e-9,
        "(blk-app) 遠超包絡、" .. string.format("%.0f", dveh._speed) .. " km/h：不鎖輪、中線外力（fbu="
        .. tostring(st.forceBrakeUntil) .. " vad=" .. tostring(st.visAssistDecel) .. "）")
    -- 停止線前的低速段（≤20+10）不鎖輪（E2E rc2 0021：24 km/h 在停止線前先停死再爬一次）：交給 blockedStop
    dveh._x, dveh._speed = 39, 24
    st.forceBrakeUntil = 0
    ticks(1, 20)
    checkTrue(st.lastHardBrakeReason ~= "blocked-approach",
        "(blk-app) 停止線前 24 km/h：不為接近包絡鎖輪（hbr=" .. tostring(st.lastHardBrakeReason) .. " cap=" .. tostring(st.blockedApproachCap) .. "）")
    -- (anchor-base) 0928b E2E rc1 0008：錨用 Corridor.plan 同一組逐點基準（s.hardBase）。
    --   近點 l=-0.9：原始 laneBias 0.84 下不擋線、彎道連續落點 0 下擋線；遠點 60m 在原始 lane 上。
    --   舊制挑遠點（blockedNear 永遠不近、車撞近點）。違規證明：hb 恆 nil＝錨落遠點紅。
    local asen = { hardN = 3, hardS = { 5, 20, 60 }, hardL = { -0.5, -0.9, 0.84 }, hardR = { 0.35, 0.35, 0.35 },
        hardX = { -5, 12, 50 }, hardY = { 0.5, -0.9, 0.84 }, stamp = 77 }
    local as = { needHalf = 1.1, hardBase = { 0, 0, 0.84 }, hardBaseStamp = 77, fstate = { laneBias = 0.84 } }
    local aveh = { getX = function() return 10 end, getY = function() return 0 end }
    local abs = Dr.debugResolveBlockAnchor(as, asen, aveh, true, 8)
    checkTrue(as.blockHitX == 12 and abs == 20,
        "(anchor-base) 擋線用彎道連續落點：錨＝車前近點（x=" .. tostring(as.blockHitX) .. " s=" .. tostring(abs) .. "）")
    as.hardBaseStamp, as.blockHitX = 76, nil
    Dr.debugResolveBlockAnchor(as, asen, aveh, true, 8)
    checkEq(as.blockHitX, 50, "(anchor-base) 逐點基準不是本快照的：退回原始 laneBias")
    for y = -9, 9 do drive.clearCell(50, y) end
    -- (line-geom) 1005：擋線判定（Corridor.plan 步驟①②、blocksLine＝resolveBlockAnchor／nearestLineBlocker）用引擎形狀
    --   位置（Sensor hardLc）＋掃掠同一套橫向半寬（hardW：方塊半邊×boxK、圓半徑），縫隙搜尋仍用取樣點 hardL／hardR。
    --   幽靈（正式服 0.18.2 Ywy clip-19）：樹的取樣點 l 在快照間跳到 3.34、離 lane 2.0 只差 r+need 0.01＝舊制判擋線、
    --   錨落在車前 12m；樹幹形狀在 4.2，lane 2.0＋1.2＋0.15＝3.35 碰不到＝不擋，錨留在真正擋線的 60m 那台。
    --   漏判（GGGMAMEER clip-22／23）：端柱取樣 l 3.91＝舊制以 0.01 判淨空；方塊形狀在 3.44（面 2.94），lane 2.0 的
    --   規劃半寬到 3.2＝擋線；同一條線的世界掃掠（sweepLine 的方塊式）也撞。
    --   違規證明：Corridor 擋線退回 hardL／hardR、blocksLine 不傳 hardLc／hardW、Sensor 不寫形狀橫向、hardW 方塊用規劃
    --   半徑、pre-a 淨距窗改成 [a,c] 或少加 pad 各紅。
    function drive.scenarioLineGeom()
        local need, halfW = 1.2, 0.9
        local gs = { hardN = 2, hardS = { 12, 60 }, hardL = { 3.34, 2.0 }, hardLc = { 4.2, 2.0 }, hardW = { 0.15, 0.5 },
            hardR = { 0.15, 0.7 }, hardX = { 12, 60 }, hardY = { 4.2, 2.0 }, stamp = 5 }
        local gsess = { needHalf = need, fstate = { laneBias = 2.0 } }
        local gveh = { getX = function() return 0 end, getY = function() return 2.0 end }
        checkEq(Dr.debugResolveBlockAnchor(gsess, gs, gveh, true, 0), 60,
            "(line-geom) 幽靈：樹幹形狀不擋 lane 2.0，停止錨不跳到車前 12m")
        checkEq(gsess.blockHitX, 60, "(line-geom) 幽靈：錨的世界點是 60m 那台")
        checkEq((MDADCorridor.plan(gs.hardS, gs.hardL, 1, need, 6.5, 2.0, gs.hardR, 2.0, nil, nil, true,
            nil, nil, nil, gs.hardLc, gs.hardW)), "clear", "(line-geom) 幽靈：只有那棵樹時 Corridor.plan 判淨空")
        checkEq((MDADCorridor.plan(gs.hardS, gs.hardL, 1, need, 6.5, 2.0, gs.hardR, 2.0, nil, nil, true)), "dodge",
            "(line-geom) 對照：不給形狀位置＝照取樣點判（舊制）擋線")
        local ms = { hardN = 1, hardS = { 30 }, hardL = { 3.91 }, hardLc = { 3.44 }, hardW = { 0.5 }, hardR = { 0.7 },
            hardX = { 30 }, hardY = { 3.44 }, stamp = 6 }
        local mm, ma = MDADCorridor.plan(ms.hardS, ms.hardL, 1, need, 6.5, 2.0, ms.hardR, 2.0, nil, nil, true,
            nil, nil, nil, ms.hardLc, ms.hardW)
        checkTrue(mm ~= "clear" and ma < 30, "(line-geom) 漏判：方塊形狀在 lane 2.0 的規劃半寬內＝擋線（"
            .. tostring(mm) .. " a=" .. tostring(ma) .. "）")
        checkEq((MDADCorridor.plan(ms.hardS, ms.hardL, 1, need, 6.5, 2.0, ms.hardR, 2.0, nil, nil, true)), "clear",
            "(line-geom) 對照：取樣點 3.91 以 0.01 判淨空（舊制漏判）")
        local msess = { needHalf = need, fstate = { laneBias = 2.0 } }
        checkEq(Dr.debugResolveBlockAnchor(msess, ms, gveh, true, 0), 30, "(line-geom) 漏判：停止錨＝端柱")
        local pad = MDADVehicleProfile.sweepBase(halfW, "cruise") - halfW
        local d2 = MDADCorridor.orientedDistanceSqUnchecked(30, 2.0, 1, 0, halfW + 0.5, 2.2 + 0.5, 30, 3.44)
        checkTrue(d2 <= pad * pad, "(line-geom) 漏判：同一條線的世界掃掠（巡航 base、方塊式）也撞（d="
            .. string.format("%.3f", math.sqrt(d2)) .. " pad=" .. string.format("%.2f", pad) .. "）")
        -- 同一套模型：沿 lane 2.0 的世界掃掠以 pad＝need−halfW 量，命中 ⇔ 擋線判定擋（方塊與圓各掃一段橫向位置）
        local agree = true
        for k = 0, 80 do
            local lc = 2.0 + 1.0 + k * 0.0125
            for _, w in ipairs({ 0.5, 0.15 }) do
                local box = w == 0.5
                local dd = MDADCorridor.orientedDistanceSqUnchecked(30, 2.0, 1, 0, halfW + (box and w or 0),
                    2.2 + (box and w or 0), 30, lc)
                local rr = box and (need - halfW) or (w + need - halfW)
                local hit = dd <= rr * rr - 1e-9
                local blk = MDADCorridor.blocksLine({ 9 }, { 0.7 }, { lc }, { w }, 1, 2.0, need)
                if math.abs(math.sqrt(dd) - rr) > 1e-6 and hit ~= blk then agree = false end
            end
        end
        checkTrue(agree, "(line-geom) 擋線判定 ⇔ 同一條線的世界掃掠命中（pad＝need−halfW，方塊／圓）")
        checkTrue(MDADCorridor.blocksLine({ 3.0 }, { 0.6 }, { nil }, { nil }, 1, 2.0, need)
                and not MDADCorridor.blocksLine({ 3.0 }, { 0.6 }, { 4.0 }, { 0.15 }, 1, 2.0, need),
            "(line-geom) 沒有形狀位置的點（虛擬 ban）退回取樣點＋規劃半徑")
        -- 真 Sensor：方塊（格 30,2）與樹（格 34,−3）的形狀橫向／掃掠半寬
        drive.fillWorld(-10, 70, -7, 7)
        drive.putSolid(30, 2, "line_geom_box")
        drive.putTree(34, -3, "line_geom_tree")
        checkTrue(armDrive(), "(line-geom) 真 Sensor 情境啟動")
        setHeading(dveh, 0)
        for _ = 1, 3 do drive.scanRound(true) end
        local sen = Dr.debugSession(0).sensor
        local boxOk, treeOk = false, false
        for i = 1, sen.hardN do
            if sen.hardX[i] == 30.5 and sen.hardY[i] == 2.5 then
                boxOk = math.abs(sen.hardLc[i] - 2.5) < 1e-9 and math.abs(sen.hardW[i] - 0.5) < 1e-9
            elseif math.abs(sen.hardX[i] - 34.6) < 1e-9 and math.abs(sen.hardY[i] + 2.4) < 1e-9 then
                treeOk = math.abs(sen.hardLc[i] + 2.4) < 1e-9 and math.abs(sen.hardW[i] - 0.15) < 1e-9
            end
        end
        checkTrue(boxOk, "(line-geom) Sensor 方塊：hardLc＝格心 2.5、hardW＝半邊 0.5（軸向路線）")
        checkTrue(treeOk, "(line-geom) Sensor 樹：hardLc＝樹幹 −2.4、hardW＝樹幹半徑 0.15")
        drive.clearCell(30, 2)
        drive.clearCell(34, -3)
        -- pre-a 淨距（dodge commit 事件 preA）：沿 +x 的承諾線、a=20；pre-a 段旁方塊面離車身 0.3、[a,c] 段另有更近的方塊
        local lx, ly = {}, {}
        for k = 1, 41 do lx[k], ly[k] = k - 1, 0 end
        local ps = { fstate = { ovN = 41, ovS0 = 0, offA = 20, offL = 0, ovX = lx, ovY = ly },
            sensor = { hardN = 2, hardS = { 10, 25 }, hardX = { 10, 25 }, hardY = { 1.7, 1.45 }, hardR = { 0.7, 0.7 },
                hardB = { 0.5, 0.5 } },
            vehicleProfile = { halfW = halfW, halfL = 2.2, centerOfMassX = 0, centerOfMassZ = 0 }, lastSNow = 0 }
        checkNear(Dr.preAClear(ps), 0.3, 1e-6, "(line-geom) preA＝pre-a 段最小物理淨距（[a,c] 段更近的方塊不算）")
        ps.sensor.hardN, ps.sensor.hardS[1], ps.sensor.hardX[1] = 1, 35, 35 -- 只剩出口段旁的方塊：離 pre-a 段車身 > 9m
        checkTrue(Dr.preAClear(ps) >= 9, "(line-geom) pre-a 段沒有近物：preA ≥ 9（實得 " .. tostring(Dr.preAClear(ps)) .. "）")
        ps.fstate.offA = 0.5
        checkNil(Dr.preAClear(ps), "(line-geom) pre-a 段不足兩個取樣點：nil")
        -- 命中時只量不留痕：blocked 事件 kind（sweepHitBody）與 replan 掃掠數（sweepCount）不被這次診斷掃描改寫。
        -- 違規證明：拿掉 preAClear 的還原就紅。
        ps.fstate.offA = 20
        ps.sensor.hardN, ps.sensor.hardS[1], ps.sensor.hardX[1], ps.sensor.hardY[1] = 1, 10, 10, 0.4
        ps.sweepHitBody, ps.sweepCount = "trailer", 7
        local hitPreA = Dr.preAClear(ps)
        checkTrue(type(hitPreA) == "number" and ps.sweepHitBody == "trailer" and ps.sweepCount == 7,
            "(line-geom) preA 命中：回淨距、不改寫 sweepHitBody／sweepCount（實得 " .. tostring(hitPreA) .. "／"
            .. tostring(ps.sweepHitBody) .. "／" .. tostring(ps.sweepCount) .. "）")
        -- (proof-env) 證明線掃掠命中（gate sweep）：平帽 18（只夾 regulator＝斷油）改成「車心開到命中的車身取樣點時降到
        --   同一個警戒帽」的接近包絡，超過包絡由中線外力 "proof" 帳補減速。違規證明：包絡改回平帽、visAssist 拿掉 proof 帳、
        --   gate 不接包絡各紅。
        local pe = { proofHitS = 60, lastSNow = 30, safeBrake = 4.6 }
        local want = MDADDynamics.approachCapKmh(30, 18, 0.5, 4.6 * T.APPROACH_BRAKE_FRAC)
        checkTrue(want > 30, "(proof-env) 前置：命中點 30m 外的包絡遠高於警戒帽（" .. tostring(want) .. "）")
        checkNear(Dr.proofSweepCap(pe, 18, 90), want, 1e-9, "(proof-env) 包絡＝開到命中點降到警戒帽 18")
        checkNear(pe.proofSweepCap, want, 1e-9, "(proof-env) 包絡記在 s.proofSweepCap（減速輔助的帳）")
        checkNear(Dr.proofSweepCap(pe, 18, 30), 30, 1e-9, "(proof-env) 包絡不高於 fullTarget")
        pe.lastSNow = 60
        checkNear(Dr.proofSweepCap(pe, 18, 90), 18, 1e-9, "(proof-env) 到命中點＝警戒帽")
        pe.proofHitS = nil
        checkEq(Dr.proofSweepCap(pe, 18, 90), 18, "(proof-env) 命中點不明（未載入）：照舊平帽")
        checkNil(pe.proofSweepCap, "(proof-env) 命中點不明：不留包絡帳")
        local pa = { tow = false, sensor = { ready = true }, visibilityCap = 90, dodging = false, proofSweepCap = 30,
            runtimeMass = 1500 }
        Dr.visAssistForce(pa, 40, 0.8)
        checkTrue(pa.visAssistDecel > 0 and pa.visAssistWhy == "proof",
            "(proof-env) 超過包絡：中線減速輔助、帳名 proof（vad=" .. tostring(pa.visAssistDecel) .. " vaw="
            .. tostring(pa.visAssistWhy) .. "）")
    end
    drive.scenarioLineGeom()
    MDAD.Drive.stop(0, nil)
    setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false, AutoDriveMaxSpeed = 40,
        ObstaclePolicy = 1, RightLaneBias = 0 })

    -- (proof-stale) 證明線被越過
    MDAD.Drive.stop(0, nil)
    drive.fillWorld(-10, 70, -7, 7)
    checkTrue(armDrive(), "(proof-stale) 啟動")
    setHeading(dveh, 0)
    st = Dr.debugSession(0)
    local built = false
    for _ = 1, 4 do
        drive.scanRound(true)
        if st.laneCurveStamp == st.sensor.stamp and st.verifyLineN >= 2 then built = true; break end
    end
    checkTrue(built, "(proof-stale) 前置：有新鮮證明線")
    st.laneCurveEnd = st.lastSNow - 1
    ticks(1, 20)
    checkTrue(Dr.isActive(0), "(proof-stale) 證明過期：不當車輛不支援交還")
    checkNil(st.stateError, "(proof-stale) 沒有 stateError")
    checkEq(st.laneCurveStamp, -1, "(proof-stale) 丟掉證明等下一輪重建")

    -- (far) 離線過遠
    MDAD.Drive.stop(0, nil)
    drive.fillWorld(-10, 70, -7, 7)
    checkTrue(armDrive(), "(far) 啟動")
    setHeading(dveh, 0)
    dveh._y = 25
    ticks(30, 100)
    checkTrue(Dr.isActive(0), "(far) 3 秒內等主 MOD 重算，不交還")
    dveh._y = 0
    ticks(3, 100)
    checkEq(Dr.debugSession(0).routeFarSince, 0, "(far) 回到路線附近：計時歸零")
    dveh._y = 25
    clearList(halos)
    local far = 0
    while far < 6000 and Dr.isActive(0) do
        ticks(1, 100)
        far = far + 100
    end
    checkFalse(Dr.isActive(0), "(far) 持續離線超過 4 秒：交還")
    checkTrue(far >= T.ROUTE_FAR_MS, "(far) 不提早交還（" .. far .. "ms）")
    checkEq(haloKey(), "UI_MinidoracatAutoDrive_RouteTooFar", "(far) 交還理由＝離道路太遠")

    MDAD.Drive.stop(0, nil)
    drive.frameMs(wasMs)
    dveh, SandboxVars = oldVeh, oldSandbox
end
drive.scenario0928()

-- 0928c：常駐線 ramp 的追線落後不算對不準（Drive.laneRampDev）。真 Follower 剖面（R12 左彎、弧內側餘裕 0）、
--   靠內側 bias 2：弧後期望線從 0 ramp 回 2，36 km/h 時車身落在 0.6 秒前與現在的期望線之間＝偏差 0；
--   落在區間外只算到區間的距離；繞行中不套。違規證明：laneRampDev 原樣回傳＝(ramp) 偏差 >0 紅。
function drive.scenario0928c()
    scenario("0928c：常駐線 ramp 落後不觸發對線帽")
    local F = MDADFollower
    local R = 12
    local w = 2 * (R * (1 - math.cos(math.pi / 4)) + 0.656 + 0.4)
    local route = { pts = { 0, -40, 0, 0, 40, 0 }, segSurface = { "paved", "paved" }, segWidth = { w, w } }
    local vp = { valid = true, geometryValid = true, halfW = 0.656, rMin = 2.26, wheelbase = 1.985,
        delta0Safe = 0.72, deltaVSafe = 0.24, maxSpeed = 120 }
    local p = F.begin(route, 120, 4, vp)
    while not p.ready do F.stepBuild(p, 4096) end
    local arcI, arcE
    for i = 1, p.n - 1 do if p.segKind[i] == MDADDynamics.SEG_ARC then arcI = arcI or i; arcE = i end end
    local sE = p.s[arcE + 1]
    local inside = (p.laneRoomL[arcI] < p.laneRoomR[arcI]) and -1 or 1
    local bias = inside * 2.0
    local sNow = sE + 10
    local el = F.laneBiasAt(p, bias, F.segIndexAt(p, sNow), sNow)
    local ep = F.laneBiasAt(p, bias, F.segIndexAt(p, sNow - 6), sNow - 6)
    checkTrue(math.abs(el - ep) > 0.3, "(ramp) 前置：弧後 10m 期望線仍在 ramp（" .. tostring(ep) .. "→" .. tostring(el) .. "）")
    local s = { profile = p, fstate = { laneBias = bias }, lastSNow = sNow, diagExpL = el,
        lastLatSigned = (el + ep) / 2, dodging = false, returnActive = false }
    local raw = math.abs(s.lastLatSigned - el)
    checkNear(MDAD.Drive.laneRampDev(s, raw, 36), 0, 1e-9,
        "(ramp) 36 km/h 車身落在 0.6 秒前與現在的期望線之間：偏差 0（原 " .. string.format("%.2f", raw) .. "）")
    s.lastLatSigned = ep - inside * 0.5
    checkNear(MDAD.Drive.laneRampDev(s, math.abs(s.lastLatSigned - el), 36), 0.5, 1e-6,
        "(ramp) 落在區間外：只算到區間的距離")
    s.lastLatSigned, s.dodging = (el + ep) / 2, true
    checkNear(MDAD.Drive.laneRampDev(s, raw, 36), raw, 1e-9, "(ramp) 繞行中不套")

    -- (oncoming) 0928d：借對向車道短設計只在 MP、且對向車道剩不到一台車寬（8m 路：側偏 0.5＝剩 3.6m 不算、
    --   −1.0＝剩 2.1m 算）；路寬未知時壓線 >0.5m 才算；單機一律不算。違規證明：拿掉 isClient＝SP 案紅。
    local oc = { laneRatio = 1, roadBias = 0, vehicleProfile = { halfW = 0.9 }, currentSegWidth = 8 }
    local oldClient = clientFlag
    clientFlag = true
    checkFalse(MDAD.Drive.borrowsOncoming(oc, 0.5), "(oncoming) MP 8m 路側偏到 0.5：對向還剩 3.6m，不算借道")
    checkTrue(MDAD.Drive.borrowsOncoming(oc, -1.0), "(oncoming) MP 8m 路側偏到 −1：對向只剩 2.1m，算借道")
    oc.currentSegWidth = 5
    checkTrue(MDAD.Drive.borrowsOncoming(oc, 0.5), "(oncoming) MP 5m 窄路壓線 0.4m：對向只剩 2.1m，算借道")
    oc.currentSegWidth = 10
    checkFalse(MDAD.Drive.borrowsOncoming(oc, -0.5), "(oncoming) MP 10m 寬路壓線 1.4m：對向還剩 3.6m，不算")
    oc.currentSegWidth = nil
    checkFalse(MDAD.Drive.borrowsOncoming(oc, 0.5), "(oncoming) 路寬未知：壓線 0.4m 不算")
    checkTrue(MDAD.Drive.borrowsOncoming(oc, 0), "(oncoming) 路寬未知：壓線 0.9m 算")
    clientFlag = false
    oc.currentSegWidth = 8
    checkFalse(MDAD.Drive.borrowsOncoming(oc, -1.0), "(oncoming) 單機沒有對向來車：不算借道")
    clientFlag = oldClient

    -- (hitch) 0928c E2E rc1 0007：遊戲卡住 3.6 秒（引擎單幀物理夾 83ms、車只前進 0.5m）不是停滯。
    --   違規證明：progressPauseMs 不認卡頓＝suspect 紅。
    local oldVeh = dveh
    local wasMs = drive.frameMs(30)
    drive.fillWorld(-10, 90, -7, 7)
    checkTrue(armDrive(), "(hitch) 啟動")
    setHeading(dveh, 0)
    local st = MDAD.Drive.debugSession(0)
    drive.scanRound(true)
    dveh._speed = 40
    for _ = 1, 8 do
        nowMs = nowMs + 30
        dveh._x = dveh._x + 0.33
        driveReset(dveh)
        driveTick(dp, dveh)
    end
    checkEq(st.progressState, "watch", "(hitch) 前置：正常行駛在看門")
    drive.mult = 4.0 -- fpsMultiplier 上限 5 ×0.8＝單幀 83ms
    nowMs = nowMs + 3600
    dveh._x = dveh._x + 0.5
    driveReset(dveh)
    driveTick(dp, dveh)
    checkEq(st.progressState, "watch", "(hitch) 卡頓 3.6 秒只動 0.5m：不判 suspect（實得 " .. tostring(st.progressState) .. "）")
    -- (freeze) 1004a 正式服 0.18.2 Qoo clip-16：整個客戶端凍住 5.8 秒、恢復首幀 fdt 只有 27ms（不是頂到上限的
    --   83ms），物理一樣只前進一小步。違規證明：條件改回「幀時 ≥80ms」＝(freeze) 紅。
    drive.frameMs(30)
    for _ = 1, 4 do
        nowMs = nowMs + 30
        dveh._x = dveh._x + 0.33
        driveReset(dveh)
        driveTick(dp, dveh)
    end
    drive.frameMs(27)
    nowMs = nowMs + 5800
    -- 從進度錨點只動 0.5m（< 重臂門檻 1m）：凍住前那幾幀的位移不能湊滿重臂，否則測不到停滯判定
    dveh._x = st.progressX + 0.5
    driveReset(dveh)
    driveTick(dp, dveh)
    checkEq(st.progressState, "watch", "(freeze) 客戶端凍住 5.8 秒、恢復首幀 27ms、只動 0.5m：不判 suspect（實得 "
        .. tostring(st.progressState) .. "）")
    drive.frameMs(30)
    -- (stale) 恢復需求沒經 dispatch 就被撤銷（episode 重臂清掉 recoverWhy）：suspect 不得留著
    st.progressState, st.recoverWhy = "suspect", nil
    nowMs = nowMs + 30
    dveh._x = dveh._x + 0.33
    driveReset(dveh)
    driveTick(dp, dveh)
    checkEq(st.progressState, "watch", "(stale) 沒有待辦恢復的 suspect：重新看門（實得 " .. tostring(st.progressState) .. "）")
    MDAD.Drive.stop(0, nil)
    drive.frameMs(wasMs)
    dveh = oldVeh
end
drive.scenario0928c()

-- (long-row) 0928d E2E rc3 0030：F350 右側 80m 長的圍欄一路延伸到未載入區——主候選的回線段與
--   停留線的車身前伸都驗不到，舊制每輪延後（dodge-defer），在群前停死到 15 秒交還。現制停留
--   的保持段收到可視前緣容得下的地方（鏈式停留）；走完後常駐線仍被擋就不解鏈，群尾看得到、
--   常駐線淨空才解鏈。違規證明：sweepStay 不收短＝不 commit 紅。
function drive.scenario0928d()
    scenario("0928d：長群伸出可視前緣＝收短的停留（鏈式）")
    local oldSand = SandboxVars
    setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false, AutoDriveMaxSpeed = 40,
        RightLaneBias = 0 })
    local wasMs = drive.frameMs(10)
    drive.fillWorld(-10, 160, -8, 8)
    for x = 30, 53 do drive.putSolid(x, 0, "long_row_" .. x) end
    drive.world[54 * 100000 + 0] = nil -- 前緣：群一路延伸到未載入格
    checkTrue(armDrive(), "(long-row) 啟動")
    setHeading(dveh, 0)
    dveh._speed = 20
    local st = MDAD.Drive.debugSession(0)
    drive.frameMs(10)
    drive.scanRound()
    drive.frameMs(10)
    drive.scanRound()
    checkTrue(st.sensor.unloaded and st.sensor.unloadedS < 56,
        "(long-row) 前置：54m 處未載入（unloadedS=" .. tostring(st.sensor.unloadedS) .. "）")
    -- 遠處：靠近後前緣跟著前進就驗得到完整繞行＝照舊延後，不收短（停留是爬行檔）
    checkTrue(st.dodging ~= true and st.blocked ~= true,
        "(long-row) 群還遠：延後、不收短（dodging=" .. tostring(st.dodging) .. " tier=" .. tostring(st.dodgeTier) .. "）")
    -- 開到群前（fixture 的前緣固定在 54m＝車到了也驗不到）：收短的停留
    dveh._x = 20
    driveReset(dveh)
    driveTick(dp, dveh)
    drive.frameMs(10)
    drive.scanRound()
    checkTrue(st.dodging == true and st.dodgeStay == true and st.laneChained == true,
        "(long-row) 群尾伸出前緣：收短的停留承諾（dodging=" .. tostring(st.dodging)
        .. " stay=" .. tostring(st.dodgeStay) .. " tier=" .. tostring(st.dodgeTier) .. "）")
    local fs = st.fstate
    checkTrue(type(fs.offD) == "number" and fs.offD + st.bodyReach <= st.sensor.unloadedS + 1e-6
            and fs.offC < 53,
        "(long-row) 停留線整條在已載入範圍內、保持段收在群尾之前（c=" .. tostring(fs.offC)
        .. " d=" .. tostring(fs.offD) .. "）")
    local stayLane = fs.offL
    dveh._x, dveh._y = (fs.offC or 40) + 0.5, stayLane or 0
    driveReset(dveh)
    driveTick(dp, dveh)
    drive.frameMs(10)
    drive.scanRound()
    checkTrue(st.dodgeStay ~= true and st.laneChained == true and math.abs(fs.laneBias - stayLane) < 1e-6,
        "(long-row) 保持段走完：常駐線仍被擋＝鏈不解、沿停留 lane 續行（chained=" .. tostring(st.laneChained)
        .. " bias=" .. tostring(fs.laneBias) .. "）")
    drive.mkSquare(54, 0)
    dveh._x = 60
    driveReset(dveh)
    driveTick(dp, dveh)
    for _ = 1, 3 do drive.frameMs(10); drive.scanRound() end
    checkTrue(st.laneChained == false,
        "(long-row) 群尾已過、常駐線淨空：解鏈（chained=" .. tostring(st.laneChained) .. "）")
    MDAD.Drive.stop(0, nil)
    for x = 30, 53 do drive.clearCell(x, 0) end
    drive.frameMs(wasMs)
    drive.fillWorld(-2, 70, -7, 7)

    -- (lamp) 0928d E2E rc3 0027：車輛靜態碰撞形狀由 IsoChunk.calcPhysics 決定——室外路燈
    --   lighting_outdoor_* 不帶任何碰撞旗標也是一根柱；PhysicsShape 屬性直接給形狀。牆上的燈
    --   （MoveType=WallObject）與 PhysicsShape=Floor 不算。違規證明：拿掉路燈／PhysicsShape 規則即紅。
    local function propObj(x, y, name, vals)
        local props = {
            has = function(_, key) return vals[key] ~= nil end,
            get = function(_, key) return vals[key] end,
        }
        local sprite = { shouldHaveCollision = function() return false end,
            getProperties = function() return props end }
        local sq = drive.world[x * 100000 + y] or drive.mkSquare(x, y)
        sq._objs[#sq._objs + 1] = { getSpriteName = function() return name end,
            getSprite = function() return sprite end, getProperties = function() return props end,
            getType = function() return nil end }
    end
    local function hardAt(name, vals)
        drive.fillWorld(-10, 90, -8, 8)
        propObj(30, 0, name, vals)
        checkTrue(armDrive(), "(lamp) " .. name .. " 啟動")
        drive.scanRound()
        local n = MDAD.Drive.debugSession(0).sensor.hardN
        MDAD.Drive.stop(0, nil)
        return n
    end
    checkTrue(hardAt("lighting_outdoor_01_1", {}) > 0, "(lamp) 不帶碰撞旗標的室外路燈是硬障礙")
    checkEq(hardAt("lighting_outdoor_01_77", { MoveType = "WallObject" }), 0, "(lamp) 牆上的燈不算")
    checkTrue(hardAt("signs_one-off_09_72", { PhysicsShape = "Tree" }) > 0,
        "(lamp) PhysicsShape=Tree 的招牌桿是硬障礙")
    checkEq(hardAt("harness_phys_floor", { PhysicsShape = "Floor" }), 0, "(lamp) PhysicsShape=Floor 不算")
    drive.fillWorld(-2, 70, -7, 7)

    -- (clr-retry) 0928d E2E rc3 0039：承諾後第一次 guard-pass 時線尾剛好掉出可視範圍（有效感知距離抖動），
    --   逐點淨距表沒收、之後持平輪又不再掃——53m 進入段全程用整線 5 km/h 帽。線再看全時同一條線補掃一次。
    --   違規證明：拿掉補掃＝表一直缺。
    do
        drive.fillWorld(-10, 90, -8, 8)
        drive.putSolid(50, 0, "clr_retry_obstacle")
        drive.world[62 * 100000 + 0] = nil
        checkTrue(armDrive(), "(clr-retry) 啟動")
        setHeading(dveh, 0)
        dveh._speed = 10
        drive.frameMs(10)
        drive.scanRound(true)
        drive.frameMs(10)
        drive.scanRound(true)
        local stc = MDAD.Drive.debugSession(0)
        checkTrue(stc.dodging == true, "(clr-retry) 前置：已承諾繞行（dodging=" .. tostring(stc.dodging) .. "）")
        -- 前緣縮回：首個 guard-pass 掃不到線尾
        stc.dodgeMarginS, stc.dodgeClrN, stc.dodgeEnvN = nil, 0, 0
        drive.world[57 * 100000 + 0] = nil
        drive.frameMs(10)
        drive.scanRound(true)
        checkTrue(stc.dodging == true and (stc.dodgeClrN or 0) == 0,
            "(clr-retry) 前置：線尾不在可視範圍內時不收表（clrN=" .. tostring(stc.dodgeClrN) .. "）")
        drive.mkSquare(57, 0)
        drive.frameMs(10)
        drive.scanRound(true)
        checkTrue(stc.dodging == true and (stc.dodgeClrN or 0) >= 2 and (stc.dodgeEnvN or 0) >= 2,
            "(clr-retry) 線再看全：同一條線補掃、收回逐點淨距表（clrN=" .. tostring(stc.dodgeClrN)
            .. " envN=" .. tostring(stc.dodgeEnvN) .. "）")
        MDAD.Drive.stop(0, nil)
        drive.clearCell(50, 0)
        drive.fillWorld(-2, 70, -7, 7)
    end

    -- (clr-keep) 1002o E2E rc52 0004：承諾後可視範圍縮回（線尾掉出），舊制 guard 掃描一開始就清表、又因未覆蓋不收＝
    --   只剩不含出口窄點的整線帽 64，表回來時窄點已在 10m 內，帽一步 64→5、27 km/h 擦上。同一條線看全時量到的
    --   逐點淨距照留、只重量看得到的那段，讀表也不再要求線尾可見（逐點帽含可視帽）。
    --   違規證明：sweepLine 照舊清表＝第一條紅；讀表照舊要求線尾可見＝第二條紅。
    do
        drive.fillWorld(-10, 90, -8, 8)
        drive.putSolid(50, 0, "clr_keep_obstacle")
        checkTrue(armDrive(), "(clr-keep) 啟動")
        setHeading(dveh, 0)
        dveh._speed = 10
        drive.frameMs(10)
        drive.scanRound(true)
        drive.frameMs(10)
        drive.scanRound(true)
        local stk = MDAD.Drive.debugSession(0)
        checkTrue(stk.dodging == true and (stk.dodgeClrN or 0) >= 2,
            "(clr-keep) 前置：已承諾繞行、線看全時收到逐點淨距表（clrN=" .. tostring(stk.dodgeClrN) .. "）")
        local ovN = stk.fstate.ovN
        stk.dodgeMarginS = nil -- 最緊點未知＝本輪 guard-pass 帶收表重掃（同 clr-retry；縮窗時才會走到清表那條路）
        drive.world[57 * 100000 + 0] = nil
        drive.frameMs(10)
        drive.scanRound(true)
        checkTrue(stk.dodging == true and stk.dodgeClrN == ovN and (stk.dodgeEnvN or 0) >= 2,
            "(clr-keep) 線尾掉出可視範圍：同一條線的逐點淨距表照留（clrN=" .. tostring(stk.dodgeClrN)
            .. " ovN=" .. tostring(ovN) .. " envN=" .. tostring(stk.dodgeEnvN) .. "）")
        checkTrue(MDAD.Drive.dodgeEnvelopeCap(stk, 10, nowMs) ~= nil,
            "(clr-keep) 縮窗時仍讀逐點速度表（不退回不含出口窄點的整線帽）")
        drive.mkSquare(57, 0)
        MDAD.Drive.stop(0, nil)
        drive.clearCell(50, 0)
        drive.fillWorld(-2, 70, -7, 7)
    end

    -- (exit-extend) 0928e：遠處就看到的障礙，出口被當下的可視範圍截短（空間帽 0 → 整段繞行最後降到 10）。
    --   車前進、前緣跟著前進後，同一組 a/b/c/offL 重建更長的出口並重掃；停留（沒有出口）不做。
    --   違規證明：extendDodgeExit 一律回 false＝出口不變紅。
    do
        local oldPer, oldGear = MDAD.HUD.perceptionDistance, MDAD.Drive.getGear(0)
        setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false, AutoDriveMaxSpeed = 120,
            RightLaneBias = 0 })
        MDAD.Drive.setGear(0, 4)
        MDAD.HUD.perceptionDistance = function() return 48 end
        local wasE = drive.frameMs(10)
        drive.fillWorld(-10, 200, -8, 8)
        drive.putVehicleGeom(34, 0, 0, 1.8, 4.4, true)
        checkTrue(armDrive(), "(exit-extend) 啟動")
        setHeading(dveh, 0)
        dveh._speed = 30
        local ste = MDAD.Drive.debugSession(0)
        local realExt, ext, probed = MDAD.Drive.extendDodgeExit, nil, nil
        MDAD.Drive.extendDodgeExit = function(st, sen, pn)
            -- (exit-keep) 1002r：加長掃不過時，現行承諾線的逐點淨距表要原封不動（表是同一個陣列）。
            --   need 撐到 50＝這次加長必掃不過；之後還原、照常加長。違規證明：加長掃掠照舊收表即紅。
            if probed == nil then
                local kN, kS0, kNeed, kFail = st.dodgeClrN, st.dodgeClrS0, st.dodgeNeed, st.dodgeExtendFailS
                st.dodgeClrN, st.dodgeClrS0, st.dodgeNeed, st.dodgeExtendFailS = 7, -1, 50, nil
                realExt(st, sen, pn)
                if st.dodgeExtendFailS ~= nil then probed = st.dodgeClrN end
                st.dodgeClrN, st.dodgeClrS0, st.dodgeNeed, st.dodgeExtendFailS = kN, kS0, kNeed, kFail
            end
            local d0, e0, cap0 = st.fstate.offD, st.dodgeExitLength, st.dodgeSpeedCap
            local a0, b0, c0, l0 = st.fstate.offA, st.fstate.offB, st.fstate.offC, st.fstate.offL
            local ok = realExt(st, sen, pn)
            if ok and ext == nil then
                ext = { d0 = d0, e0 = e0, cap0 = cap0, a0 = a0, b0 = b0, c0 = c0, l0 = l0 }
            end
            return ok
        end
        for _ = 1, 4 do drive.frameMs(10); drive.scanRound(true) end
        checkTrue(probed == 7, "(exit-keep) 加長掃不過：現行線的逐點淨距表不動（N " .. tostring(probed) .. "）")
        MDAD.Drive.extendDodgeExit = realExt
        local fse = ste.fstate
        checkTrue(ext ~= nil and ext.e0 < ste.dodgeExitWant - 10,
            "(exit-extend) 承諾時出口被可視範圍截短、之後加長（出口 " .. tostring(ext and ext.e0)
            .. "m、要 " .. tostring(ste.dodgeExitWant) .. "m）")
        checkTrue(ext ~= nil and ste.dodging == true and fse.offD > ext.d0 + 4
                and fse.offD + 1 + ste.bodyReach <= ste.sensor.scanEndS + 1e-6,
            "(exit-extend) 出口加長、線尾仍在可視範圍內（d " .. tostring(ext and ext.d0) .. " → " .. tostring(fse.offD) .. "）")
        checkTrue(ext ~= nil and fse.offA == ext.a0 and fse.offB == ext.b0 and fse.offC == ext.c0 and fse.offL == ext.l0,
            "(exit-extend) 進入段、保持段、偏移量不變")
        checkTrue(ext ~= nil and ste.dodgeSpeedCap > ext.cap0 + 5 and (ste.dodgeClrN or 0) >= 2,
            "(exit-extend) 出口變長後繞行帽跟著放寬、逐點淨距表跟著新線（cap " .. tostring(ext and ext.cap0) .. " → "
            .. tostring(ste.dodgeSpeedCap) .. "）")
        MDAD.Drive.stop(0, nil)
        drive.frameMs(wasE)
        MDAD.HUD.perceptionDistance = oldPer
        MDAD.Drive.setGear(0, oldGear)
        drive.fillWorld(-2, 70, -7, 7)
    end
    SandboxVars = oldSand
end
drive.scenario0928d()

-- (chain-far) 1004a 玩家回報「繞道後判定走路邊草地，要到第一次轉彎或殭屍／屍體出現才回到路上」：鏈式停留只在
--   常駐線前方淨空才解鏈，看的是整個感知窗——遠處還有任何擋常駐線的東西，車就沿停留 lane（常在路外）一路開，
--   直到減速把窗縮短。現制擋常駐線那群夠遠（回常駐線＋再側移出去兩段都塞得進，Drive.chainBlockerFar）就解鏈。
--   fixture 同 (c9b)：B 在 +1.6、A 在 +1.3（只擋常駐線）→ 停留 −1.5；另放 C 在 x=140（常駐線上、很遠）。
--   (chain-far) 過了 A 就解鏈（why=far），不等到 C；(c9b) 仍鎖「A 緊接在後＝續鏈」。
--   違規證明：chainBlockerFar 恆 false＝(chain-far) 紅（實測舊制到 x=144 才解鏈）。
function drive.scenarioChainFar()
    scenario("鏈式停留：擋常駐線的下一群夠遠就解鏈回路上，不沿停留 lane 開到它")
    local function stepTo(x, y)
        dveh._x, dveh._y = x, y
        driveReset(dveh)
        driveTick(dp, dveh)
        drive.scanRound()
    end
    local oldSand = SandboxVars
    drive.fillWorld(-10, 200, -8, 8)
    setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false, AutoDriveMaxSpeed = 40, RightLaneBias = 0 })
    nowMs = nowMs + 5000
    MDAD.Drive.stop(0, nil)
    dveh._x, dveh._y, dveh._speed, dveh._steering, dveh._stopped = 0, 0, 20, 0, false
    dveh._engine, dveh._driver = true, dp
    dp._vehicle, dp._dead, dp._local = dveh, false, true
    setHeading(dveh, 0.3)
    drive.nav.tx, drive.nav.ty, drive.nav.state = 190, 0, "ok"
    drive.nav.route = newRoute(48, 0, 0, 4, 0)
    checkTrue(MDAD.Drive.start(dp), "(chain-far) 啟動")
    for _ = 1, 2 do driveTick(dp, dveh) end
    local _, cB = drive.putVehicleGeom(20, 1.6, 0, 1.8, 4.4, true)
    local _, cA = drive.putVehicleGeom(42, 1.3, 0, 1.8, 4.4, true)
    local _, cC = drive.putVehicleGeom(140, 1.3, 0, 1.8, 4.4, true)
    driveReset(dveh)
    drive.scanRound()
    local st = MDAD.Drive.debugSession(0)
    local stayLane = st.fstate.offL
    checkTrue(st.dodgeStay == true and st.laneChained == true and type(stayLane) == "number" and stayLane < -1,
        "(chain-far) 前置：B 的停留承諾、鏈住（tier " .. tostring(st.dodgeTier) .. " offL " .. tostring(stayLane) .. "）")
    local unchainAt, residentPm = nil, nil
    if type(stayLane) == "number" then
        stepTo(10, stayLane * 0.7)
        stepTo(20, stayLane)
        local x = 24
        while x <= 136 and unchainAt == nil do
            stepTo(x, stayLane)
            if not st.laneChained then
                unchainAt = x
                -- 解鏈當下常駐線前方仍有擋線群（C）＝走的是 far，不是 clear
                local sen, res = st.sensor, st.residentBias or 0
                residentPm = MDADCorridor.plan(sen.hardS, sen.hardL, sen.hardN, st.needHalf,
                    sen.corridorHalf or MDADSensor.CORRIDOR_HALF, res, sen.hardR, res, sen.roadLo, sen.roadHi,
                    false, nil, st.lastSNow - st.vehicleProfile.halfL)
            end
            x = x + 4
        end
    end
    checkTrue(unchainAt ~= nil and unchainAt <= 56,
        "(chain-far) 過了 A、C 還在 80m 外：解鏈回常駐線（解鏈於 x=" .. tostring(unchainAt) .. "）")
    checkEq(residentPm, "dodge", "(chain-far) 解鏈當下常駐線前方仍被 C 擋（＝夠遠才解鏈，不是淨空）")
    drive.clearVehicleGeom(cA)
    drive.clearVehicleGeom(cB)
    drive.clearVehicleGeom(cC)
    MDAD.Drive.stop(0, nil)
    drive.fillWorld(-2, 70, -7, 7)
    SandboxVars = oldSand
end
drive.scenarioChainFar()

-- (chain-keep) 1004a 正式服 0.18.2 dandankk clip-30：6m 路停留 2.25 釋放後鏈上 lane 被常駐 keep 0.6 夾回 1.12，
--   車被拉回障礙側、重錨兩次仍被夾 → blocked 停死交還（open-issues「鏈上 lane 被 clampLane 拉回障礙側」）。
--   鏈上 lane 是掃掠驗過的絕對 lane：鏈著時 fstate.laneKeep＝0，期望線停在鏈 lane（只夾物理餘裕）。
--   違規證明：laneKeep 不給鏈 0＝(chain-keep) 紅。
function drive.scenarioChainKeep()
    scenario("鏈上 lane 不被常駐 keep 夾回障礙側")
    local oldSandbox, oldVeh, oldGet = SandboxVars, dveh, getSpecificPlayer
    local oldApi = MinidoracatMiniMapAPI.navApiVersion
    local oldRoute, oldTx, oldTy, oldState = drive.nav.route, drive.nav.tx, drive.nav.ty, drive.nav.state
    local wasMs = drive.frameMs(20)
    MDAD.Drive.stop(0, nil)
    getSpecificPlayer = function(n) if n == 0 then return dp end end
    MinidoracatMiniMapAPI.navApiVersion = 5
    dveh = newVehicle({ battery = newItem("Base.CarBattery", { uses = 0.8 }),
        engineRunning = true, mass = 1600, speed = 0, maxSpeed = 100,
        bodyW = 1.6, bodyL = 4.2, comX = 0, comZ = 0, profileFull = true,
        enginePower = 3000, brakingForce = 100, wheelFriction = 1.5, tireFriction = 1.5 })
    drive.fillWorld(-12, 130, -8, 8)
    drive.putRoad(0, 130, -3, 3)
    setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false,
        AutoDriveMaxSpeed = 60, RightLaneBias = 0.5 }) -- 6m 路 ×0.5＝常駐 +0.75
    dveh._x, dveh._y, dveh._speed, dveh._steering, dveh._stopped = 0, 0.75, 0, 0, true
    dveh._engine, dveh._driver = true, dp
    dp._vehicle, dp._dead, dp._local = dveh, false, true
    setHeading(dveh, 0)
    drive.nav.route = { pts = { 0, 0, 120, 0 }, segSurface = { "paved" }, segWidth = { 6 },
        len = 120, cost = 120, avoidPenalty = 0 }
    drive.nav.tx, drive.nav.ty, drive.nav.state = 120, 0, "ok"
    checkTrue(MDAD.Drive.start(dp), "(chain-keep) 啟動")
    for _ = 1, 6 do driveTick(dp, dveh) end
    drive.scanRound(true)
    local st = MDAD.Drive.debugSession(0)
    local roomR = type(st.profile.laneRoomR) == "table" and st.profile.laneRoomR[1] or nil
    checkTrue(type(roomR) == "number" and roomR > MDADFollower.LANE_BIAS_KEEP + 0.4,
        "(chain-keep) 前置：6m 路有 laneRoom（room " .. tostring(roomR) .. "）")
    if type(roomR) == "number" then
        local L = roomR - 0.2 -- 在 room−keep 之外、物理餘裕之內
        -- 常駐線左前方 14m 一格硬物：擋常駐線、不擋鏈 lane，且夠近＝鏈續留（Drive.chainBlockerFar 為假）
        drive.putSolid(14, -1, "chain_keep_resident_block")
        st.laneChained = true
        MDADFollower.setLaneBias(st.fstate, L)
        dveh._y, dveh._speed, dveh._stopped = L, 15, false
        drive.scanRound(true)
        driveReset(dveh)
        driveTick(dp, dveh)
        checkTrue(st.laneChained == true and st.fstate.laneKeep == 0,
            "(chain-keep) 鏈著：laneKeep＝0（chained=" .. tostring(st.laneChained) .. " keep="
            .. tostring(st.fstate.laneKeep) .. "）")
        checkTrue(type(st.diagExpL) == "number" and math.abs(st.diagExpL - L) < 0.05,
            "(chain-keep) 期望線停在鏈 lane " .. string.format("%.2f", L) .. "，不被夾回 room−0.6（實得 "
            .. tostring(st.diagExpL) .. "）")
        drive.clearCell(14, -1)
    end
    MDAD.Drive.stop(0, nil)
    drive.frameMs(wasMs)
    MinidoracatMiniMapAPI.navApiVersion = oldApi
    drive.nav.route, drive.nav.tx, drive.nav.ty, drive.nav.state = oldRoute, oldTx, oldTy, oldState
    SandboxVars, dveh, getSpecificPlayer = oldSandbox, oldVeh, oldGet
    drive.fillWorld(-2, 70, -7, 7)
end
drive.scenarioChainKeep()

-- 0929j 玩家 KI5 Oshkosh 消防車撞樹／撞路邊物（Telemetry (4).rar）：
--   (shape) 點雲幾何對齊引擎的車輛碰撞形狀（IsoChunk.calcPhysics＋libPZBullet64）：樹幹格 +0.6、半徑 0.15；
--           solidtrans 整格方塊（規劃 r 0.7、掃掠方塊半邊 0.5）；籬笆 collideN／collideW 在格的北緣／西緣；
--           無旗標籬笆與同格多形狀。違規證明：樹幹退回格心、solidtrans 退回小圓、籬笆退回格心各自紅。
--   (norm)  回授依 yawGain 正規化：k＝REF/yawGain 夾 [1, MAX]，前饋不乘。違規證明：k 固定 1 即紅。
--   (align) 繞行未對正不加速：偏線 >0.35 或車頭對承諾線切線 >5° 時帽夾在目前車速。違規證明：恆對正即紅。
--   (shy)   靠右留路邊距：右緣外 0.6m 內的路邊物把靠右目標往左收；壓進車身帶的障礙＝不收。違規證明：不收即紅。
--   (exit)  出口用自己的側移：被可視範圍截成陡出口、進入段等得起就延後承諾。違規證明：拿掉出口陡坡閘即紅。
function drive.scenario0929j()
    scenario("0929j：引擎碰撞形狀、回授正規化、繞行未對正不加速、靠右留路邊距、出口陡坡延後")
    local oldSand = SandboxVars
    setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false, AutoDriveMaxSpeed = 40,
        RightLaneBias = 0 })
    local function flagObj(x, y, name, flags, collide, class)
        local props = { has = function(_, key) return flags[key] == true end, get = function() return nil end }
        local sprite = { shouldHaveCollision = function() return collide == true end,
            getProperties = function() return props end }
        local sq = drive.world[x * 100000 + y] or drive.mkSquare(x, y)
        sq._objs[#sq._objs + 1] = { _class = class, getSpriteName = function() return name end,
            getSprite = function() return sprite end, getProperties = function() return props end,
            getType = function() return nil end }
    end
    local function pointsNear(sen, x, y)
        local found = nil
        for i = 1, sen.hardN do
            if math.abs(sen.hardX[i] - x) < 1e-6 and math.abs(sen.hardY[i] - y) < 1e-6 then found = i end
        end
        return found
    end
    drive.fillWorld(-10, 90, -8, 8)
    drive.putTree(30, 3, "vegetation_trees_01_5")
    flagObj(34, 3, "street_decoration_harness_box", { solidtrans = true }, true)
    flagObj(38, 3, "fencing_harness_n", { collideN = true }, true)
    flagObj(42, 3, "fencing_harness_w", { collideW = true }, true)
    flagObj(46, 3, "fencing_harness_nw", { collideN = true, collideW = true }, true)
    drive.putPost(50, 3, "harness_post")
    flagObj(54, 3, "fencing_harness_n2", { collideN = true }, true)
    drive.putTree(54, 3, "vegetation_trees_01_6")
    flagObj(58, 3, "lighting_outdoor_01_1", {}, false)
    flagObj(62, 3, "e_harnessJUMBOXL_1_0", { solid = true, StopCar = true }, true, "IsoTree")
    checkTrue(armDrive(), "(shape) 啟動")
    setHeading(dveh, 0)
    local st = MDAD.Drive.debugSession(0)
    drive.scanRound()
    drive.scanRound()
    local sen = st.sensor
    local function shapeAt(x, y, r, b, label)
        local i = pointsNear(sen, x, y)
        checkTrue(i ~= nil and math.abs(sen.hardR[i] - r) < 1e-6 and math.abs((sen.hardB[i] or 0) - b) < 1e-6,
            "(shape) " .. label .. "（實得 " .. (i and string.format("r=%s b=%s", tostring(sen.hardR[i]),
                tostring(sen.hardB[i])) or "沒有這個點") .. "）")
    end
    shapeAt(30.6, 3.6, 0.15, 0, "樹幹：格 +0.6/+0.6、半徑 0.15")
    checkTrue(pointsNear(sen, 30.5, 3.5) == nil, "(shape) 樹幹不在格心")
    shapeAt(34.5, 3.5, 0.7, 0.5, "solidtrans：整格方塊（規劃 r 0.7、掃掠半邊 0.5）")
    shapeAt(38.25, 3.05, 0.26, 0, "collideN 籬笆：北緣 1/4 點")
    shapeAt(38.75, 3.05, 0.26, 0, "collideN 籬笆：北緣 3/4 點")
    checkTrue(pointsNear(sen, 38.5, 3.5) == nil, "(shape) collideN 籬笆不在格心")
    shapeAt(42.05, 3.25, 0.26, 0, "collideW 籬笆：西緣 1/4 點")
    shapeAt(42.05, 3.75, 0.26, 0, "collideW 籬笆：西緣 3/4 點")
    shapeAt(46.25, 3.05, 0.26, 0, "WallNW 籬笆：北緣")
    shapeAt(46.05, 3.75, 0.26, 0, "WallNW 籬笆：西緣")
    shapeAt(50.5, 3.5, 0, 0, "無旗標籬笆：格心 0 半徑（引擎不給形狀，保守留著）")
    shapeAt(54.25, 3.05, 0.26, 0, "同格籬笆＋樹：籬笆照推")
    shapeAt(54.6, 3.6, 0.15, 0, "同格籬笆＋樹：樹幹也推（第一個硬物不再蓋掉其他形狀）")
    shapeAt(58.6, 3.6, 0.15, 0, "室外路燈柱＝樹幹形狀")
    shapeAt(62.6, 3.6, 0.15, 0, "帶 solid 的大樹（JUMBO）：引擎只給樹幹，不是整格方塊")
    MDAD.Drive.stop(0, nil)
    drive.fillWorld(-2, 70, -7, 7)

    -- (box-sweep) 世界掃掠把整格方塊當方塊：方塊面離車側留 0.05 的線，舒適檔直接過（外接圓 0.7 在軸向多估 0.2，
    -- 會判撞、落到同線物理檔）。違規證明：掃掠不讀 hardB 即紅。
    flagObj(30, 3, "street_decoration_harness_box", { solidtrans = true }, true)
    checkTrue(armDrive(), "(box-sweep) 啟動")
    setHeading(dveh, 0)
    drive.scanRound()
    drive.scanRound()
    st = MDAD.Drive.debugSession(0)
    st.sensor.ready, st.sensor.unloaded, st.sensor.scanEndS = true, false, 300
    local boxPad = (st.sweepBase or 0) - st.vehicleProfile.halfW
    if boxPad < 0.05 then boxPad = 0.05 end
    local boxOff = 3 - st.vehicleProfile.halfW - boxPad - 0.05
    local okBox, roBox, varBox, mgBox = MDAD.Drive.debugSweepFallbacks(0, 10, 20, 40, 50, boxOff, "boxsweep")
    -- 舒適檔主候選過（淨距 0.05 貼底）→ 同縫往外拓寬一格＝variant "widen"；外接圓會先判撞、落到物理檔或微調
    checkTrue(okBox == true and varBox == "widen", string.format(
        "(box-sweep) 方塊面留 0.05：舒適檔主候選就過（只拓寬、不落物理檔／微調；ok=%s offL=%.2f→%s variant=%s margin=%s）",
        tostring(okBox), boxOff, tostring(roBox), tostring(varBox), tostring(mgBox)))
    MDAD.Drive.stop(0, nil)
    drive.fillWorld(-2, 70, -7, 7)

    -- (norm) 回授正規化
    local fake = { fstate = { yawGain = 0.2, ffSteer = 0.3 } }
    local tune = MDAD.Drive.debugTune()
    local k = tune.FB_NORM_REF / 0.2
    checkNear(MDAD.Drive.normalizeSteer(fake, 0.6), 0.3 + k * 0.3, 1e-9,
        "(norm) 低增益車：回授（扣掉前饋）乘 REF/yawGain，前饋不乘")
    checkNear(fake.fbNorm, k, 1e-9, "(norm) 倍率進遙測")
    fake.fstate.yawGain = 0.8
    checkNear(MDAD.Drive.normalizeSteer(fake, 1.0), 1.0, 1e-12, "(norm) 增益 ≥ REF 的車不變")
    fake.fstate.yawGain, fake.fstate.ffSteer = 0.05, 0
    checkNear(MDAD.Drive.normalizeSteer(fake, -0.4), tune.FB_NORM_MAX * -0.4, 1e-9,
        "(norm) 倍率夾在 FB_NORM_MAX（反向一樣）")
    checkNear(MDAD.Drive.normalizeSteer(fake, 1.0), tune.FB_NORM_CLAMP, 1e-9,
        "(norm) 放大後的回授最多到 FB_NORM_CLAMP")
    checkNear(MDAD.Drive.normalizeSteer(fake, 2.2), 2.2, 1e-9,
        "(norm) 原本就超過上限的暫態尖峰不放大（E2E 53 km/h 繞行承諾幀 2.2×3 打滿轉向）")
    fake.fstate.ffSteer = 0.3
    fake.fstate.yawGain = nil
    checkNear(MDAD.Drive.normalizeSteer(fake, 1.0), 1.0, 1e-12, "(norm) 還沒學到增益＝不動")
    -- (norm-fb) 1001h：無偏估計 yawGainFb 優先（舊 yawGain 被 heading 噪聲估高 2–3 倍，正規化形同沒作用）。
    -- 違規證明：normalizeSteer 改回只讀 yawGain＝紅。
    fake.fstate.yawGain, fake.fstate.yawGainFb, fake.fstate.ffSteer = 0.5, 0.15, 0
    checkNear(MDAD.Drive.normalizeSteer(fake, 0.3), tune.FB_NORM_MAX * 0.3, 1e-9,
        "(norm-fb) 舊估計 0.5、無偏估計 0.15：以 0.15 正規化（倍率夾在 FB_NORM_MAX）")
    -- (norm-tow) 拖車照舊用 yawGain（掛車折角動態沒有離線模型，維持已通過拖掛 E2E 的行為）。
    -- 違規證明：拖車也讀 yawGainFb＝紅（0.3→0.9）。
    fake.tow = { halfW = 1.2 }
    checkNear(MDAD.Drive.normalizeSteer(fake, 0.3), 0.3, 1e-9,
        "(norm-tow) 拖車：舊估計 0.5 ≥ REF＝不放大（不讀無偏估計 0.15）")
    fake.tow = nil

    -- (align) 繞行未對正不加速
    local ov = { fstate = { ovX = { 0, 1, 2, 3, 4, 5 }, ovY = { 0, 0, 0, 0, 0, 0 }, ovS0 = 0, ovN = 6 },
        lastSNow = 2.3, lastVehicleHeading = 0, lastLatDev = 0.1 }
    checkTrue(MDAD.Drive.dodgeAligned(ov), "(align) 貼線且車頭順線＝對正")
    checkNear(MDAD.Drive.dodgeAlignCap(ov, 30, 12), 30, 1e-12, "(align) 對正：帽不變")
    checkFalse(ov.dodgeAlignHold, "(align) 對正：不標 hold")
    ov.lastVehicleHeading = 0.12
    checkNear(MDAD.Drive.dodgeAlignCap(ov, 30, 12), 12, 1e-12, "(align) 車頭偏 6.9°：帽夾在目前車速")
    checkTrue(ov.dodgeAlignHold, "(align) 未對正 hold 進遙測")
    ov.lastVehicleHeading, ov.lastLatDev = 0, 0.5
    checkNear(MDAD.Drive.dodgeAlignCap(ov, 30, 12), 12, 1e-12, "(align) 偏線 0.5m：同樣不加速")
    -- (align-latch) 1004a 正式服 0.18.2 kanazawa clip-10：未對正期間被外力減速（撞殭屍），舊制每幀夾「當下車速」
    --   13.8→6 km/h 一路棘輪往下爬。夾的值閂在剛偏離時的車速，只跟著自己的帽往下。
    --   違規證明：每幀改回夾當下車速＝(align-latch) 紅。
    checkNear(MDAD.Drive.dodgeAlignCap(ov, 30, 8), 12, 1e-12, "(align-latch) 外力掉到 8：帽仍是偏離時的 12")
    checkNear(MDAD.Drive.dodgeAlignCap(ov, 9, 8), 9, 1e-12, "(align-latch) 自己的帽壓到 9：照帽")
    checkNear(MDAD.Drive.dodgeAlignCap(ov, 30, 8), 9, 1e-12, "(align-latch) 帽放開但仍未對正：不超過自己壓過的 9")
    ov.lastLatDev = 0.1
    checkNear(MDAD.Drive.dodgeAlignCap(ov, 30, 8), 30, 1e-12, "(align-latch) 對正：放開、閂鎖清掉")
    checkTrue(ov.dodgeAlignHoldKmh == nil, "(align-latch) 對正後閂鎖清空")
    ov.lastLatDev = 0.5
    checkNear(MDAD.Drive.dodgeAlignCap(ov, 30, 2), tune.DODGE_COMMIT_MIN_KMH, 1e-12,
        "(align) 靜止起步：夾在可執行下限")
    ov.dodgeAlignHoldKmh = nil
    checkNear(MDAD.Drive.dodgeAlignCap(ov, 10, 12), 10, 1e-12, "(align) 已超帽：照原帽減速，不抬")

    -- (shy) 靠右留路邊距
    local prof = { ready = true, n = 2, s = { 0, 200 }, x = { 0, 200 }, y = { 0, 0 }, segH = { 0 } }
    local shySen = { ready = true, hardN = 1, hardS = { 20 }, hardX = { 20.5 }, hardY = { 5.0 },
        hardR = { 0.7 }, hardB = { 0.5 } }
    local shy = { sensor = shySen, profile = prof, vehicleProfile = { halfW = 1.24, halfL = 3.56 },
        lastSNow = 0, roadBias = 0, sandBias = 3.0 }
    checkNear(MDAD.Drive.keepRightShy(shy, 3.0), 4.5 - tune.KEEP_RIGHT_CLEAR_M - 1.24, 1e-9,
        "(shy) 右緣外 0.26m 的路邊方塊：靠右往左收到留出 KEEP_RIGHT_CLEAR_M")
    shySen.hardY[1] = 7.0
    checkNear(MDAD.Drive.keepRightShy(shy, 3.0), 3.0, 1e-12, "(shy) 夠遠的路邊物不影響")
    shySen.hardY[1], shySen.hardS[1] = 5.0, -10
    checkNear(MDAD.Drive.keepRightShy(shy, 3.0), 3.0, 1e-12, "(shy) 車後的點不算")
    shySen.hardS[1] = 20
    shySen.hardN = 2
    shySen.hardS[2], shySen.hardX[2], shySen.hardY[2], shySen.hardR[2], shySen.hardB[2] = 30, 30.5, 3.0, 0.7, 0.5
    checkNear(MDAD.Drive.keepRightShy(shy, 3.0), 3.0, 1e-12,
        "(shy) 視窗內有壓進車身帶的障礙＝繞行的事，不收（停車遠側輪廓不會被當路邊物）")
    shySen.hardN = 1
    shy.sandBias = 1.0
    checkNear(MDAD.Drive.keepRightShy(shy, 1.0), 1.0, 1e-12, "(shy) 常駐線離路邊物已夠遠：不動")
    -- 目前靠右 1.5、target 3.0（路寬放大）：路邊方塊面 3.8 不擋目前車身，但 target 走過去會貼上＝提前收
    --（E2E 0929j C 段：路寬 14 讓常駐線一路往右，巨石等走過去才變擋線點，53 km/h 在縫口前 3m 才承諾繞行）
    shy.sandBias = 1.5
    shySen.hardY[1] = 4.3
    checkNear(MDAD.Drive.keepRightShy(shy, 3.0), 3.8 - tune.KEEP_RIGHT_CLEAR_M - 1.24, 1e-9,
        "(shy) 往右移的途中會貼上的路邊物：用目前位置判擋線、target 先收")
    -- 靠右值 2.9 在這段被路面餘裕夾到 2.4（laneRoom 3.0−KEEP 0.6）：車身其實在 3.64，右緣外 0.21m 的樹幹要收；
    -- 用裸值 2.9 判會以為樹壓進車身帶而不收（與下面 BIAS_MAX 同一類：判車身帶要用實際落點）
    local roomProf = { ready = true, n = 2, s = { 0, 200 }, x = { 0, 200 }, y = { 0, 0 }, segH = { 0 },
        laneRoomR = { 3.0 }, laneRoomL = { 3.0 } }
    local roomShy = { sensor = { ready = true, hardN = 1, hardS = { 20 }, hardX = { 20.6 }, hardY = { 4.0 },
        hardR = { 0.15 }, hardB = { 0 } }, profile = roomProf, vehicleProfile = { halfW = 1.24, halfL = 3.56 },
        lastSNow = 0, roadBias = 0, sandBias = 2.9 }
    checkNear(MDAD.Drive.keepRightShy(roomShy, 2.9), 3.85 - tune.KEEP_RIGHT_CLEAR_M - 1.24, 1e-9,
        "(shy) 靠右值被路面餘裕夾住時，用實際落點判車身帶：右緣外的路邊樹照樣收")
    -- 路面沒有夾（無 laneRoom 表），但靠右值 3.75 超過常駐偏置上限 BIAS_MAX 3：實際行駛線是 3.0（0929k E2E W 段
    -- 真實情況），路邊大樹樹幹（l 4.93、r 0.15）在右緣外 0.54m、要收到 0.6m
    local capShy = { sensor = { ready = true, hardN = 1, hardS = { 20 }, hardX = { 20.6 }, hardY = { 4.93 },
        hardR = { 0.15 }, hardB = { 0 } }, profile = prof, vehicleProfile = { halfW = 1.24, halfL = 3.56 },
        lastSNow = 0, roadBias = 0, sandBias = 3.75 }
    checkNear(MDAD.Drive.keepRightShy(capShy, 3.75), 4.78 - tune.KEEP_RIGHT_CLEAR_M - 1.24, 1e-9,
        "(shy) 靠右值超過 BIAS_MAX：用夾過的實際行駛線判車身帶，右緣外 0.54m 的樹幹照樣收")

    -- (exit) 出口陡坡延後
    checkTrue(armDrive(), "(exit) 啟動")
    setHeading(dveh, 0)
    drive.scanRound()
    st = MDAD.Drive.debugSession(0)
    dveh._y = -0.35
    driveReset(dveh)
    driveTick(dp, dveh)
    -- 常駐線 2.0（靠右）、車在 −0.35：offL 0.25 的進入側移 0.6、出口側移 1.75（tick 會重設 laneBias，放在它之後）
    MDADFollower.setLaneBias(st.fstate, 2.0)
    st.sensor.ready, st.sensor.unloaded, st.sensor.scanEndS = true, false, 300
    local ok1 = MDAD.Drive.debugShape(0, 20, 30, 40, 50, 0.25)
    checkTrue(ok1 == true and st.dodgeWindowShort ~= true,
        "(exit) 看得到完整出口：照常承諾（ok=" .. tostring(ok1) .. " short=" .. tostring(st.dodgeWindowShort) .. "）")
    local want1 = st.dodgeExitWant
    st.sensor.scanEndS = 40 + 1 + st.bodyReach + 1.0
    local ok2 = MDAD.Drive.debugShape(0, 20, 30, 40, 50, 0.25)
    checkTrue(ok2 == true and st.dodgeWindowShort == true,
        "(exit) 出口被可視範圍截到 1m、側移 2.25m：延後等看得到（short=" .. tostring(st.dodgeWindowShort)
        .. " exit=" .. tostring(st.dodgeExitLength) .. " want=" .. tostring(want1) .. "）")
    st.sensor.scanEndS = 8 + 1 + st.bodyReach + 1.0
    local ok3 = MDAD.Drive.debugShape(0, 1, 3, 8, 15, 0.25)
    checkTrue(ok3 == true and st.dodgeWindowShort ~= true,
        "(exit) 障礙就在眼前、進入段等不起：照舊承諾（0909b 不新增否決；short="
        .. tostring(st.dodgeWindowShort) .. "）")
    -- (exit-len／exit-cap) 車已貼著 offL（進入側移 0.05）、常駐線在 3.0：出口要回 3.5m。出口長度照出口側移補到低速
    -- 最短過渡、速度帽也照出口側移算；對照組常駐線就在 offL（出口 0）。舊制兩段都照進入側移算。
    dveh._y = -0.45
    driveReset(dveh)
    driveTick(dp, dveh)
    st.sensor.ready, st.sensor.unloaded, st.sensor.scanEndS = true, false, 300
    MDADFollower.setLaneBias(st.fstate, 3.0)
    local okA = MDAD.Drive.debugShape(0, 20, 30, 40, 50, -0.5)
    local wantA, capA = st.dodgeExitWant, st.dodgeSpaceCap
    MDADFollower.setLaneBias(st.fstate, -0.5)
    local okB = MDAD.Drive.debugShape(0, 20, 30, 40, 50, -0.5)
    local wantB, capB = st.dodgeExitWant, st.dodgeSpaceCap
    checkTrue(okA == true and okB == true and wantA > wantB + 0.5, string.format(
        "(exit) 出口側移 3.5 > 進入 0.05：出口長度補到出口的低速最短過渡（出口 3.5 要 %.2f、出口 0 要 %.2f）",
        wantA or -1, wantB or -1))
    checkTrue(okA == true and okB == true and capA < capB * 0.7, string.format(
        "(exit) 速度帽照出口側移算（出口 3.5：%.1f、出口 0：%.1f）", capA or -1, capB or -1))
    -- (exit-inplace) 群已在車旁、車就在 offL 上（原地承諾，沒有進入段）：唯一的過渡是回常駐線的出口，長度照出口
    -- 側移的設計速度算。0.17m 的出口若只拿車長地板，出口帽掉到 15 km/h 上下（E2E C 段 55 km/h 被急煞到 22）。
    dveh._y = 1.72
    driveReset(dveh)
    driveTick(dp, dveh)
    st.sensor.ready, st.sensor.unloaded, st.sensor.scanEndS = true, false, 300
    MDADFollower.setLaneBias(st.fstate, 1.92)
    local okIp, aIp, bIp = MDAD.Drive.debugShape(0, st.lastSNow - 5, st.lastSNow + 0.5, st.lastSNow + 4,
        st.lastSNow + 12, 1.75)
    checkTrue(okIp == true and bIp == st.lastSNow and st.dodgeSpaceCap > 30, string.format(
        "(exit-inplace) 原地承諾、出口 0.17m：出口照設計速度留長度，不為小修正急煞（b=%s rs=%s 帽 %.1f 出口 %.1fm）",
        tostring(bIp), tostring(st.lastSNow), st.dodgeSpaceCap or -1, st.dodgeExitLength or -1))
    MDAD.Drive.stop(0, nil)
    SandboxVars = oldSand
end
drive.scenario0929j()

-- 0929o（Workshop 兩則回報：拖 40 呎貨櫃走走停停、開車燈更慢）：
--   (tow-assist) 拖車也有不鎖輪減速：牽引車照舊（runtimeMass），掛車依自己的質量分到同一減速度，方向跟
--     掛車自己的速度相反（被倒著拖的車 forward 朝後也一樣），施在質心；掛車幾乎不動時不施。舊制拖車一律
--     不補，只剩滑行與一秒鎖輪（掛車自己不煞車，鎖牽引車＝掛車從後面推）。
--     違規證明：visAssistForce 加回拖車排除＝第一條紅；不分攤（towDecel 空轉）＝質量比那條紅；
--     掛車力改沿 forward＝倒拖那條紅。
--   (tow-defer) 待承諾接近的鎖輪門檻拖車也用緊急帳（有輔助可追）。違規證明：deferHardKmh 加回拖車排除＝紅。
--   (tow-nolock) 0929p 使用者裁定：拖車 ≥10 km/h 的硬煞不鎖輪（鎖輪時掛車從後面推，整組只 2.0 m/s²），改兩節
--     各自 7 m/s² 的中線外力、照常轉向；低速、非拖車、dynamics-fault 照舊鎖輪。違規證明：towNolock 門檻改成
--     永遠鎖輪＝前兩條紅；拿掉掛車分攤＝質量比那條紅；拿掉 visAssistDecel 標記＝滑行排除那條紅。
function drive.scenario0929o()
    scenario("0929o：拖車不鎖輪減速依質量分攤到掛車")
    local Dr = MDAD.Drive
    local hit = {}
    local function trailer(vx, vz, fx, fz)
        return {
            getLinearVelocity = function(_, out) return out:set(vx, 0, vz) end,
            getForwardVector = function(_, out) return out:set(fx, 0, fz) end,
            addImpulse = function(_, imp, rel)
                hit.n = (hit.n or 0) + 1
                hit.x, hit.z, hit.rx, hit.rz = imp:x(), imp:z(), rel:x(), rel:z()
            end,
        }
    end
    local s = { sensor = { ready = true }, visibilityCap = 40, fstate = {}, profile = {}, runtimeMass = 3000,
        tow = { trailer = trailer(0, 20, 0, 1), mass = 1500 } }
    local f = Dr.visAssistForce(s, 50, 0.8)
    checkTrue(f > 0 and s.visAssistDecel > 0,
        "(tow-assist) 拖車超過可視帽：牽引車照樣補不鎖輪減速（" .. tostring(s.visAssistDecel) .. "）")
    Dr.towDecel(s, s.visAssistDecel, 0.8)
    local ft = math.sqrt((hit.x or 0) ^ 2 + (hit.z or 0) ^ 2)
    checkNear(ft / math.max(f, 1e-9), 1500 / 3000, 1e-9, "(tow-assist) 掛車分到的力／牽引車的力＝質量比（兩節同減速度）")
    checkTrue((hit.z or 0) < 0 and math.abs(hit.x or 1) < 1e-9 and hit.rx == 0 and hit.rz == 0,
        "(tow-assist) 掛車外力朝它自己的速度反向、施在質心")
    checkEq(s.towAssistDecel, s.visAssistDecel, "(tow-assist) 記下施給掛車的減速度（telemetry tda）")
    s.tow.trailer, hit.n = trailer(0, 20, 0, -1), 0
    Dr.towDecel(s, s.visAssistDecel, 0.8)
    checkTrue(hit.n == 1 and hit.z < 0, "(tow-assist) 被倒著拖（forward 朝後）：仍朝速度反向，不會往前推")
    s.tow.trailer, hit.n = trailer(0, 0.3, 0, 1), 0
    Dr.towDecel(s, s.visAssistDecel, 0.8)
    checkTrue(hit.n == 0 and s.towAssistDecel == 0, "(tow-assist) 掛車幾乎沒在動：不施")
    local d = { tow = s.tow, dodgeDeferS = 60, dodgeDeferCap = 10, lastSNow = 0, safeBrake = 4,
        sensor = { ready = true }, vehicleProfile = { halfL = 3 } }
    local hard = Dr.deferHardKmh(d, 50)
    checkTrue(hard > d.dodgeDeferCap,
        "(tow-defer) 拖車待承諾接近：鎖輪門檻用緊急帳（" .. tostring(hard) .. " > 接近帽 10），不是一超過就鎖輪")
    -- (tow-nolock)
    local imp = {}
    local veh = {
        addImpulse = function(_, i, r) imp.x, imp.z = i:x(), i:z() end,
        setForceBrake = function() imp.locked = true end,
    }
    local function towSess(towed)
        return { tow = towed and { trailer = trailer(0, 13.9, 0, 1), mass = 1500 } or nil, runtimeMass = 3000,
            fstate = {}, vehicleProfile = {}, escScale = 1, parity = 1, forceBrakeUntil = 0 }
    end
    local fwdV = BaseVehicle.allocVector3f()
    local t = towSess(true)
    hit.n, hit.x, hit.z = 0, nil, nil
    local tf = Dr.hardBrake(t, veh, 1000, "visibility", 50, 0.8, 0, 0, fwdV, 0, 1)
    checkTrue(tf ~= nil and not imp.locked and t.forceBrakeUntil == 0, "(tow-nolock) 拖車 50 km/h 硬煞：不鎖輪")
    checkTrue((imp.z or 0) < 0 and math.abs(imp.x or 1) < 1e-9, "(tow-nolock) 牽引車施車頭反向的中線外力")
    checkNear(math.abs(hit.z or 0) / math.max(math.abs(imp.z or 0), 1e-9), 1500 / 3000, 1e-9,
        "(tow-nolock) 掛車分到同一減速度（外力比＝質量比，掛點不推）")
    checkTrue(t.towAssistDecel == 7 and t.towBrakeWhy == "visibility", "(tow-nolock) telemetry tda 7／tbw visibility")
    checkEq(t.visAssistDecel, 7, "(tow-nolock) 記成輔助減速度：下一幀滑行學習不收（外力不是車的能力）")
    imp.x, imp.z = nil, nil
    Dr.hardBrake(towSess(true), veh, 1000, "blocked", 50, 0.8, 1, 0, fwdV, 0, 1)
    checkTrue(math.abs(imp.x or 0) > 0, "(tow-nolock) 不鎖輪時照常轉向（同一 impulse 帶側推）")
    for _, c in ipairs({ { true, 5, "blocked", "低於 10 km/h 停住" }, { false, 50, "visibility", "非拖車" },
            { true, 50, "dynamics-fault", "dynamics-fault" },
            { true, -50, "blocked", "倒退中（外力沿車頭反向會加速倒退）" } }) do
        local u = towSess(c[1])
        imp.locked, hit.n = nil, 0
        Dr.hardBrake(u, veh, 1000, c[3], c[2], 0.8, 0, 0, fwdV, 0, 1)
        checkTrue(imp.locked == true and u.forceBrakeUntil > 0 and hit.n == 0,
            "(tow-nolock) " .. c[4] .. "：照舊一秒鎖輪、掛車不施")
    end
    BaseVehicle.releaseVector3f(fwdV)
end
drive.scenario0929o()

-- 0929p（使用者裁定「允許繞到道路之外的地方繞路」；E2E semi-long-mp block：三台車連路肩擋死 14m 大路）：
--   (wide) 一般帶（±7）判堵；停下判堵的寬帶（±14、看 100m、輪時放寬）重掃，Corridor 讀快照的帶寬、候選到路外，
--     承諾的寬帶繞行走完前維持寬帶（起步後回到一般寬帶的 60m）。違規證明：Sensor 不鎖寬帶／wideScanWanted 恆 false
--     ／Corridor 讀固定 CORRIDOR_HALF／停下判堵不放長＝各自紅。
--   (tow-sweep) 拖車候選線驗掛車軌跡：同一條線牽引車過得去、掛車內切撞到 → 拒收。違規證明：拿掉掛車掃掠＝紅。
--   (tow-hold) 拖車保持段延長 trailLen（牽引車照原 c 回線時掛車還在障礙旁）。違規證明：拿掉延長＝紅。
function drive.scenario0929p()
    scenario("0929p：整條擋死寬帶重掃從路外繞過、拖車驗掛車軌跡")
    local oldSand = SandboxVars
    setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false, AutoDriveMaxSpeed = 40,
        RightLaneBias = 0 })
    local wasMs = drive.frameMs(10)
    -- (wide)
    -- 牆整條落在一般帶內（l −5.5..6.5）：兩側空地沒有新硬點，寬帶輪的點雲簽章要靠寬帶旗標才會變（0929p 審查）
    drive.fillWorld(-10, 160, -16, 16)
    for x = 40, 42 do for y = -6, 6 do drive.putSolid(x, y, "wide_wall") end end
    checkTrue(armDrive(), "(wide) 啟動")
    setHeading(dveh, 0)
    local st = MDAD.Drive.debugSession(0)
    -- 起步就判堵、群還在 25m 外：一般帶先開近重判，不武裝寬帶（E2E arrive 0929p：起步寬帶→路外繞→偏離重算 600m）
    dveh._x, dveh._y, dveh._speed = 15, 0, 0
    driveReset(dveh)
    driveTick(dp, dveh)
    for _ = 1, 2 do drive.frameMs(10); drive.scanRound(true) end
    checkTrue(st.blocked == true and st.dodging ~= true and st.sensor.corridorHalf == 7
            and st.wideArmed ~= true and st.sensor.wideDone ~= true,
        "(wide) 起步判堵但群在 25m 外：不武裝寬帶、維持一般帶（armed=" .. tostring(st.wideArmed)
        .. " half=" .. tostring(st.sensor.corridorHalf) .. "）")
    -- 開到停點（車心離牆 9m ≤ BLOCK_STOP_DIST）停住：這一幀就武裝，下一輪寬帶
    dveh._x = 31
    driveReset(dveh)
    driveTick(dp, dveh)
    checkTrue(st.blocked == true and st.wideArmed == true,
        "(wide) 一般帶（±7）整條擋死、開到停點＝武裝寬帶（blocked=" .. tostring(st.blocked) .. "）")
    drive.frameMs(10)
    drive.scanRound(true)
    checkTrue(st.sensor.wideDone == true and st.sensor.corridorHalf == 14
            and (st.sensor.effectiveAheadM or 0) >= 99,
        "(wide) 停下判堵的寬帶：±14、看 100m（拖車繞行的出口要驗得完）（half=" .. tostring(st.sensor.corridorHalf)
        .. " eff=" .. tostring(st.sensor.effectiveAheadM) .. "）")
    checkTrue(st.dodging == true and st.dodgeWide == true and (st.fstate.offL or 0) < -7,
        "(wide) 從路外繞過：承諾寬帶繞行（offL=" .. tostring(st.fstate.offL) .. "）")
    drive.frameMs(10)
    drive.scanRound(true)
    checkTrue(st.sensor.wideDone == true and MDAD.Drive.wideScanWanted(st, 30) == true
            and (st.sensor.effectiveAheadM or 99) <= 60,
        "(wide) 寬帶繞行走完前維持寬帶（守護輪才看得到承諾線兩側；車速高也一樣），起步後回到一般寬帶 60m（eff="
        .. tostring(st.sensor.effectiveAheadM) .. "）")
    -- (wide-route) 1002t：寬帶路外繞行承諾中，同目標的偏航重算新線先不收（承諾線不被換掉，E2E rc43 0010）；
    --   繞完照常 cutover。違規證明：拿掉延後＝承諾中就 cutover 紅。
    do
        local rg0, r0, offL0 = st.routeGen, st.route, st.fstate.offL
        drive.nav.route = newRoute(40, 0, 0, 4, 0) -- 同目標、新 identity＝主 MOD 偏航重算
        nowMs = nowMs + 300
        driveReset(dveh)
        driveTick(dp, dveh)
        checkTrue(st.dodging == true and st.routeGen == rg0 and st.route == r0 and st.fstate.offL == offL0,
            "(wide-route) 寬帶繞行承諾中：同目標新線不 cutover、承諾線保留（rg " .. tostring(rg0) .. "→"
            .. tostring(st.routeGen) .. "）")
        st.dodging = false -- 繞完
        nowMs = nowMs + 300
        driveReset(dveh)
        driveTick(dp, dveh)
        checkTrue(st.routeGen == rg0 + 1 and st.route == drive.nav.route,
            "(wide-route) 繞完下一次取路照常 cutover（rg " .. tostring(st.routeGen) .. "）")
        local base = { dodging = true, dodgeWide = true }
        local function hold(k, v)
            local t = { dodging = true, dodgeWide = true }
            t[k] = v
            return MDAD.Drive.holdWideReroute(t, true, true)
        end
        checkTrue(MDAD.Drive.holdWideReroute(base, true, true)
                and not MDAD.Drive.holdWideReroute(base, false, true)
                and not MDAD.Drive.holdWideReroute(base, true, false)
                and not hold("tow", {}) and not hold("dodgeWide", false) and not hold("dodging", false)
                and not hold("pendingDetour", true) and not hold("pendingRouteWhy", "detour"),
            "(wide-route) 只延後同目標同版本的偏航重算；拖車、一般帶繞行、換目標、改道請求照收")
    end
    MDAD.Drive.stop(0, nil)
    for x = 40, 42 do for y = -6, 6 do drive.clearCell(x, y) end end
    checkTrue(not MDAD.Drive.wideScanWanted({ blocked = true, wideArmed = true, wideArmedS = 5, lastSNow = 5 }, 30)
            and MDAD.Drive.wideScanWanted({ blocked = true, wideArmed = true, wideArmedS = 5, lastSNow = 5 }, 2)
            and not MDAD.Drive.wideScanWanted({ blocked = true, lastSNow = 5 }, 2),
        "(wide) 判堵但還在跑＝一般帶（前視留給煞車）；開到停點幾乎停住才寬帶")
    -- 倒車成功會清 blocked（blocked-retry 的倒車不開 episode）：退回武裝點之後武裝不解除，下一次判堵（還停著）直接
    -- 寬帶重判退出來的跑道；開過武裝點（堵點已解、照常往前）才解除
    local ep = { blocked = false, wideArmed = true, wideArmedS = 50, lastSNow = 45 }
    local wantEp = MDAD.Drive.wideScanWanted(ep, 0)
    local keptEp = ep.wideArmed
    ep.blocked = true
    local wantEp2 = MDAD.Drive.wideScanWanted(ep, 0)
    local passed = { blocked = false, wideArmed = true, wideArmedS = 50, lastSNow = 52 }
    MDAD.Drive.wideScanWanted(passed, 0)
    checkTrue(wantEp == false and keptEp == true and wantEp2 == "stop" and passed.wideArmed == false,
        "(wide) 倒車退回武裝點後（blocked 暫清）武裝保留、再判堵即寬帶；開過武裝點才解除")
    -- 倒車退出停止線外：已在停止線武裝的堵點停著等寬帶重判，不再用接近包絡開回停止線
    local far = { blockS = 100, lastSNow = 0, blockHitX = 100, blockHitY = 0, wideArmed = true, wideArmedS = 5 }
    local holdBack = MDAD.Drive.blockedAtStop(far, 0, 0)
    far.lastSNow = 7
    local holdPast = MDAD.Drive.blockedAtStop(far, 7, 0)
    far.wideArmed, far.lastSNow = false, 0
    local holdNone = MDAD.Drive.blockedAtStop(far, 0, 0)
    checkTrue(holdBack == true and holdPast == false and holdNone == false,
        "(wide) 倒車退到停止線外：武裝點之後停著寬帶重判（不開回停止線）；開過武裝點或沒武裝照舊接近")
    -- (wide-anchor) 武裝只綁當時的堵點：判堵錨換到 6m 外（原障礙移走、改判遠處另一群）＝解除武裝照常接近；
    --   同一群錨小幅變動照舊停著（0929v 審查）。違規證明：不比錨＝錨換到 30m 外仍停在第一道停止線前。
    local an = { blockS = 100, lastSNow = 0, blockHitX = 10, blockHitY = 0, wideArmed = true, wideArmedS = 5,
        wideArmedX = 9, wideArmedY = 1.5 }
    local anSame = MDAD.Drive.blockedAtStop(an, 0, 0)
    an.blockHitX = 40
    local anMoved = MDAD.Drive.blockedAtStop(an, 0, 0)
    checkTrue(anSame == true and anMoved == false and an.wideArmed == false,
        "(wide-anchor) 同一群停著；判堵錨換到 30m 外另一群＝解除武裝、照常接近（same=" .. tostring(anSame)
        .. " moved=" .. tostring(anMoved) .. " armed=" .. tostring(an.wideArmed) .. "）")
    -- (corner-wide) 一般帶判成 corner 鎖住（原地重試沒新資訊）：寬帶是新資訊，第一輪寬帶照跑候選鏈（0929v 審查：
    --   否則彎道旁堵住時寬帶掃完卻從不規劃路外縫）。違規證明：latch 對寬帶也早退＝不承諾路外繞行。
    drive.fillWorld(-10, 160, -16, 16)
    for x = 40, 42 do for y = -6, 6 do drive.putSolid(x, y, "corner_wide_wall") end end
    armDrive()
    setHeading(dveh, 0)
    local cw = MDAD.Drive.debugSession(0)
    dveh._x, dveh._y, dveh._speed = 31, 0, 0
    driveReset(dveh)
    driveTick(dp, dveh)
    drive.frameMs(10)
    drive.scanRound(true) -- 一般帶判堵、停點武裝
    cw.cornerLatch, cw.cornerS, cw.cornerLatchWide = true, cw.lastSNow, false
    drive.frameMs(10)
    drive.scanRound(true) -- 寬帶
    checkTrue(cw.sensor.wideDone == true and cw.dodging == true and cw.dodgeWide == true,
        "(corner-wide) 一般帶 corner 鎖住後第一輪寬帶照規劃、從路外繞過（wide=" .. tostring(cw.sensor.wideDone)
        .. " dodging=" .. tostring(cw.dodging) .. " plan=" .. tostring(cw.planMode) .. "）")
    MDAD.Drive.stop(0, nil)
    for x = 40, 42 do for y = -6, 6 do drive.clearCell(x, y) end end
    -- (tow-sweep)／(tow-hold)：假掛車幾何（掛點在車位後 2m、軸距 8m、車身 12m）
    local trl = { getForwardVector = function(_, out) return out:set(1, 0, 0) end }
    local geo = { trailer = trl, L2 = 8, hitchZ = -2, hitchX = 0, boxBack = 5, boxSide = 0, halfW = 1.25,
        halfL = 6, trailLen = 13, mass = 1500 }
    local function towRound(ox)
        drive.fillWorld(-10, 160, -16, 16)
        drive.putSolid(ox, 0, "tow_sweep_obs")
        armDrive()
        setHeading(dveh, 0)
        local t = MDAD.Drive.debugSession(0)
        dveh._x, dveh._y, dveh._speed = 20, 0, 0
        driveReset(dveh)
        driveTick(dp, dveh)
        drive.frameMs(10)
        drive.scanRound(true)
        return t
    end
    local t = towRound(30)
    local ok0 = MDAD.Drive.debugSweepCandidate(0, 24, 28, 40, 46, 3)
    t.tow = geo -- 掃完才掛（假掛車沒有 Java 介面，不能讓它跑行駛防線）
    -- 一般帶只驗牽引車（0929p E2E：一般帶也驗掛車＝路邊小物前全判不過，三個拖車回歸 StopStuck）
    local okN = MDAD.Drive.debugSweepCandidate(0, 24, 28, 40, 46, 3)
    t.sensor.wideDone, t.sensor.corridorHalf = true, 14 -- 寬帶快照：開始驗掛車
    local ok1, ph1, hx1, hy1 = MDAD.Drive.debugSweepCandidate(0, 24, 28, 40, 46, 3)
    -- 被倒著拖的車（forward 朝後、attach 量到 axisSign −1）：軸向要照真實「軸→掛點」，結果同正常掛車
    t.tow = { trailer = { getForwardVector = function(_, out) return out:set(-1, 0, 0) end },
        L2 = 8, hitchZ = -2, hitchX = 0, boxBack = 5, boxSide = 0, halfW = 1.25, halfL = 6, trailLen = 13,
        mass = 1500, axisSign = -1 }
    local ok2, ph2, hx2, hy2 = MDAD.Drive.debugSweepCandidate(0, 24, 28, 40, 46, 3)
    t.tow = nil
    t.sensor.wideDone, t.sensor.corridorHalf = false, 7
    checkTrue(ok2 == ok1 and ph2 == ph1 and hx2 == hx1 and hy2 == hy1,
        "(tow-sweep) 被倒著拖（forward 朝後）：軸向照實際掛點方向＝同一判定（ok=" .. tostring(ok2)
        .. " phase=" .. tostring(ph2) .. "）")
    checkTrue(ok0 == true and ok1 == false and ph1 == 3 and hx1 == 30.5 and hy1 == 0.5,
        "(tow-sweep) 寬帶：牽引車在 +3 過得去、掛車內切撞到原車道上的障礙＝拒收（tractor=" .. tostring(ok0)
        .. " trailer=" .. tostring(ok1) .. " phase=" .. tostring(ph1) .. "）")
    checkTrue(okN == true, "(tow-sweep) 一般帶只驗牽引車（候選不知道掛車落後，驗了只會卡在路邊小物前）")
    MDAD.Drive.stop(0, nil)
    drive.clearCell(30, 0)
    t = towRound(36)
    local okShape, _, _, c0, d0 = MDAD.Drive.debugShape(0, 24, 28, 40, 46, 3)
    t.tow = geo
    local _, _, _, cN = MDAD.Drive.debugShape(0, 24, 28, 40, 46, 3)
    t.sensor.wideDone, t.sensor.corridorHalf = true, 14
    local okShapeTow, _, _, c1, d1 = MDAD.Drive.debugShape(0, 24, 28, 40, 46, 3)
    local okShort, phShort = MDAD.Drive.debugSweepCandidate(0, 24, 28, 40, 46, 3)
    local okLong = MDAD.Drive.debugSweepCandidate(0, 24, 28, 40 + 13, 46 + 13, 3)
    t.tow = nil
    t.sensor.wideDone, t.sensor.corridorHalf = false, 7
    checkTrue(cN == c0, "(tow-hold) 一般帶不延長保持段（c " .. tostring(c0) .. "／" .. tostring(cN) .. "）")
    checkTrue(okShape and okShapeTow and math.abs((c1 or 0) - (c0 or 0) - 13) < 1e-9
            and math.abs((d1 or 0) - (d0 or 0) - 13) < 1e-9,
        "(tow-hold) 拖車保持段與出口一起延後 trailLen（c " .. tostring(c0) .. "→" .. tostring(c1) .. "）")
    checkTrue(okShort == false and phShort == 4 and okLong == true,
        "(tow-hold) 照原 c 回線＝掛車在出口內切撞到；保持到掛車也過了才回線＝通過")
    MDAD.Drive.stop(0, nil)
    drive.clearCell(36, 0)
    -- (tow-stop) 判堵停止線加掛車跑道（base＋trailLen＋L2/2）：停在線上就寬帶繞過，不必倒車
    local big = { trailer = { getForwardVector = function(_, out) return out:set(dveh._fwdX, 0, dveh._fwdY) end,
            getUpVectorDot = function() return 1 end },
        L2 = 9.5, hitchToRear = 12, halfW = 1.27, halfL = 6.5, hitchZ = -2.5, hitchX = 0, boxBack = 6,
        boxSide = 0, trailLen = 14.5, mass = 1400, axisSign = 1 }
    drive.fillWorld(-10, 160, -18, 18)
    for x = 60, 61 do for y = -8, 8 do drive.putSolid(x, y, "tow_block") end end
    armDrive()
    setHeading(dveh, 0)
    local ts = MDAD.Drive.debugSession(0)
    ts.tow = big
    local stopD = MDAD.Drive.blockStopDist(ts)
    checkNear(stopD, 10 + 14.5 + 4.75, 1e-9, "(tow-stop) 拖車停止線＝10＋trailLen＋L2/2")
    dveh._x, dveh._y, dveh._speed = 60 - (stopD - 1), 0, 0
    driveReset(dveh)
    driveTick(dp, dveh)
    drive.frameMs(10)
    drive.scanRound(true)
    driveTick(dp, dveh)
    checkTrue(ts.blocked == true and ts.wideArmed == true,
        "(tow-stop) 車心離群 " .. string.format("%.1f", stopD - 1) .. "m（一般車還在滑行接近）＝拖車已到停止線、武裝寬帶")
    drive.frameMs(10)
    drive.scanRound(true)
    checkTrue(ts.dodging == true and ts.dodgeWide == true and (ts.fstate.offL or 0) < -7,
        "(tow-stop) 停在拖車線上寬帶一次繞過（offL=" .. tostring(ts.fstate.offL) .. "）")
    -- (tow-back) 拖車改道線要從車頭方向出發：先往車後再轉進支路＝拒收（非拖車照收）
    local oldGet = getSpecificPlayer
    getSpecificPlayer = function(n) if n == 0 then return dp end end
    local cx = dveh._x
    local function detourReply(pts)
        local r = ts.route.pts -- 終點接回原路線的終點（1002k：requestDetourRoute 驗終點）
        pts[#pts + 1], pts[#pts + 2] = r[#r - 1], r[#r]
        drive.nav.detour = { pts = pts, segSurface = { "paved", "paved", "paved" }, segWidth = { 8, 8, 8 },
            len = 30, cost = 30, avoidPenalty = 0 }
        return drive.nav.detour
    end
    detourReply({ cx, 0, cx - 4, 0, cx - 4, 20 })
    local okBack, whyBack = MDAD.Drive.requestDetour(0, true)
    detourReply({ cx, 0, cx + 10, 0, cx + 10, 20 })
    local okFwd = MDAD.Drive.requestDetour(0, true)
    ts.tow = nil
    ts.pendingDetour, ts.pendingRouteWhy = nil, nil
    detourReply({ cx, 0, cx - 4, 0, cx - 4, 20 })
    local okCar = MDAD.Drive.requestDetour(0, true)
    checkTrue(okBack == false and whyBack == "back" and okFwd == true and okCar == true,
        "(tow-back) 拖車：往車後再轉的改道線拒收、往前的照收；非拖車同一條照收（back=" .. tostring(okBack)
        .. "/" .. tostring(whyBack) .. " fwd=" .. tostring(okFwd) .. " car=" .. tostring(okCar) .. "）")
    -- (tow-back2) 先退 3m 再斜向前（8m 點已在車前）仍拒收：Follower 會先投影在往後那段判調頭；起點略在車後、
    --   第一段本身朝前（車投影就在這段上）照收（0929v 審查）。違規證明：拿掉第一段方向檢查＝紅。
    checkTrue(MDAD.Drive.routeLeavesForward({ pts = { 0, 0, -3, 0, 10, 6 } }, 0, 0, 1, 0) == false
            and MDAD.Drive.routeLeavesForward({ pts = { -2, 0, 10, 8 } }, 0, 0, 1, 0) == true,
        "(tow-back2) 先退 3m 再斜向前拒收；起點略在車後、第一段朝前照收")
    drive.nav.detour = nil
    getSpecificPlayer = oldGet
    MDAD.Drive.stop(0, nil)
    for x = 60, 61 do for y = -8, 8 do drive.clearCell(x, y) end end
    -- (bush) 樹叢：一般帶一律不收（路邊樹叢不擋車）。寬帶：抵消得了樹叢阻力（非拖車、引擎方法在，1004d Drive.bushCancel）
    --   ＝同樣不避；抵消不可用（假車拿掉 applyImpulseFromHitPlant）＝當 0.3 圓避開（0929t：引擎每幀對碰到的樹叢施
    --   −0.025×動量、不乘 dt，E2E 路外繞進樹叢地 1 km/h 動不了）。違規證明：寬帶一律避開／一律不避／一般帶也收＝各自紅。
    do
        local bprops = { has = function(_, key) return key == "Bush" end, get = function() return nil end }
        local bsprite = { shouldHaveCollision = function() return false end, getProperties = function() return bprops end }
        local plantFn = dveh.applyImpulseFromHitPlant
        for _, noApi in ipairs({ false, true }) do
            -- 路邊樹叢（l≈±3.5，一般帶也掃得到）與路外樹叢（l≈±10.5，寬帶才掃得到），牆整條擋死 ±6：開到停止線武裝後下一輪寬帶
            drive.fillWorld(-10, 90, -16, 16)
            for x = 40, 42 do for y = -6, 6 do drive.putSolid(x, y, "bush_wall") end end
            for _, c in ipairs({ { 35, 3 }, { 45, 10 } }) do
                local sq = drive.world[c[1] * 100000 + c[2]] or drive.mkSquare(c[1], c[2])
                sq._objs[#sq._objs + 1] = { getSpriteName = function() return "harness_bush" end,
                    getSprite = function() return bsprite end, getProperties = function() return bprops end,
                    getType = function() return nil end }
            end
            if noApi then dveh.applyImpulseFromHitPlant = nil end
            armDrive()
            dveh.applyImpulseFromHitPlant = plantFn
            setHeading(dveh, 0)
            local bs = MDAD.Drive.debugSession(0)
            local function bushR(x, y)
                for i = 1, bs.sensor.hardN do
                    if math.abs(bs.sensor.hardX[i] - x) < 0.01 and math.abs(bs.sensor.hardY[i] - y) < 0.01 then
                        return bs.sensor.hardR[i]
                    end
                end
                return nil
            end
            dveh._x, dveh._y, dveh._speed = 15, 0, 0 -- 群在 25m 外：判堵但還沒到停止線＝一般帶
            driveReset(dveh)
            driveTick(dp, dveh)
            for _ = 1, 2 do drive.frameMs(10); drive.scanRound(true) end
            local rNormal, halfNormal = bushR(35.5, 3.5), bs.sensor.corridorHalf
            dveh._x = 31 -- 開到停止線：武裝，下一輪寬帶
            driveReset(dveh)
            driveTick(dp, dveh)
            drive.frameMs(10)
            drive.scanRound(true)
            local rWideIn, rWideOut = bushR(35.5, 3.5), bushR(45.5, 10.5)
            local wideR = noApi and 0.3 or nil
            checkTrue(halfNormal == 7 and rNormal == nil and bs.sensor.wideDone == true and rWideIn == wideR
                    and rWideOut == wideR and bs.bushOff == (noApi and "api" or nil),
                "(bush) " .. (noApi and "抵消不可用：寬帶收成格心 0.3 圓" or "抵消得了：寬帶也不避") .. "，一般帶不收（一般 "
                .. tostring(rNormal) .. "、寬帶路邊 " .. tostring(rWideIn) .. "／路外 " .. tostring(rWideOut)
                .. "、off " .. tostring(bs.bushOff) .. "）")
            MDAD.Drive.stop(0, nil)
        end
    end
    -- (wide-gate) 寬帶武裝後的倒車／自動改道：下一次都要等這次嘗試的寬帶重判（E2E 0929u：倒車一結束、等待額度
    --   早已累滿，一般帶一判堵就再倒，三次倒車中間一輪寬帶都沒跑就交還）。自動改道開著時，倒車重判仍堵才改道。
    --   違規證明：拿掉倒車的閘／改道的閘＝一般帶判堵那一刻就再倒／就改道。
    for _, detourOn in ipairs({ false, true }) do
        -- 1004c：牆蓋滿寬帶第二級（±19.5）；只蓋 ±16 時第二級看得到牆端外的空地，判成 steep、倒車多退，就不是本情境要的「整條擋死」
        drive.fillWorld(-10, 160, -24, 24)
        for x = 40, 42 do for y = -24, 24 do drive.putSolid(x, y, "gate_wall") end end
        if type(MDAD.HUD) ~= "table" then MDAD.HUD = {} end
        local oldAuto = MDAD.HUD.autoDetour
        MDAD.HUD.autoDetour = function() return detourOn end
        drive.nav.detourCalls = 0
        armDrive()
        setHeading(dveh, 0)
        local gs = MDAD.Drive.debugSession(0)
        dveh._x, dveh._y, dveh._speed = 31, 0, 0
        driveReset(dveh)
        driveTick(dp, dveh)
        drive.frameMs(10); drive.scanRound(true) -- 一般帶判堵、停點武裝
        drive.frameMs(10); drive.wideRounds(true) -- 寬帶判堵到最寬一級
        local judged0 = gs.wideArmed == true and gs.wideJudged == 0 and gs.sensor.wideDone == true
        nowMs = nowMs + 5100
        driveReset(dveh)
        driveTick(dp, dveh)
        local rev1 = gs.mode == "unstick" and gs.episodeAttempts == 1
        dveh._x, dveh._speed = 26.9, -13
        nowMs = nowMs + 16
        driveReset(dveh)
        driveTick(dp, dveh) -- 退夠 → settle
        dveh._speed = 0
        nowMs = nowMs + 16
        driveTick(dp, dveh) -- settle 完成：快照重置、blocked 暫清
        drive.frameMs(10)
        drive.scanRound(true) -- 退後第一輪（一般帶）又判堵
        local normalAgain = gs.blocked == true and gs.sensor.wideDone ~= true and gs.wideArmed == true
        nowMs = nowMs + 6000
        driveReset(dveh)
        driveTick(dp, dveh)
        local held = gs.mode ~= "unstick" and gs.episodeAttempts == 1 and (drive.nav.detourCalls or 0) == 0
        drive.frameMs(10)
        drive.wideRounds(true) -- 寬帶重判仍整條擋死：最寬一級判過才准再倒／改道
        driveReset(dveh)
        driveTick(dp, dveh)
        local next2 = detourOn and (drive.nav.detourCalls or 0) == 1
            or (not detourOn and gs.mode == "unstick" and gs.episodeAttempts == 2)
        checkTrue(judged0 and rev1 and normalAgain and held and next2,
            "(wide-gate) 倒車後等寬帶重判才" .. (detourOn and "改道" or "再倒") .. "（judged0=" .. tostring(judged0)
            .. " rev1=" .. tostring(rev1) .. " normal=" .. tostring(normalAgain) .. " held=" .. tostring(held)
            .. " next=" .. tostring(next2) .. "）")
        MDAD.HUD.autoDetour = oldAuto
        MDAD.Drive.stop(0, nil)
        for x = 40, 42 do for y = -24, 24 do drive.clearCell(x, y) end end
    end
    -- (wide-defer) 停點的寬帶判堵：候選伸出已載入區（覆蓋不足）照判堵走倒車重判，不延後——延後的接近帽會讓車往群
    --   前爬、吃掉進入段，清掉判堵又解除武裝，一般帶／寬帶來回判、永遠不倒車。違規證明：照舊延後＝紅。
    do
        drive.fillWorld(-10, 44, -16, 16) -- x≥45 未載入：路外那條線的出口與收短的停留都驗不完
        for x = 40, 42 do for y = -6, 6 do drive.putSolid(x, y, "defer_wall") end end
        armDrive()
        setHeading(dveh, 0)
        local ds = MDAD.Drive.debugSession(0)
        dveh._x, dveh._y, dveh._speed = 31, 0, 0
        driveReset(dveh)
        driveTick(dp, dveh)
        for _ = 1, 3 do drive.frameMs(10); drive.scanRound(true) end
        checkTrue(ds.sensor.wideDone == true and ds.blocked == true and ds.wideArmed == true and ds.dodging ~= true
                and (ds.dodgeDeferCap or -1) < 0,
            "(wide-defer) 停點寬帶判堵、候選伸出已載入區：判堵（倒車重判），不延後往群前爬（wide="
            .. tostring(ds.sensor.wideDone) .. " blocked=" .. tostring(ds.blocked) .. " armed=" .. tostring(ds.wideArmed)
            .. " deferCap=" .. tostring(ds.dodgeDeferCap) .. "）")
        MDAD.Drive.stop(0, nil)
        for x = 40, 42 do for y = -6, 6 do drive.clearCell(x, y) end end
    end
    -- (stay-armed／stay-tow) 停點寬帶判堵時停留線照「現在看得到的」收短（車不會再往前開近，前緣不跟著前進）；
    --   拖車的保持段已延長到掛車過群，收短不得截到掛車還在群旁。合成點雲：rel 10..24 整條擋死 ±6，前緣 H=30／38。
    --   違規證明：停點也算可開近的距離＝一般車收不短而判堵；拖車下限退回 b+halfL＝收成掛車還在群旁的停留。
    do
        drive.fillWorld(-10, 200, -20, 20)
        armDrive()
        setHeading(dveh, 0)
        local ss = MDAD.Drive.debugSession(0)
        dveh._x, dveh._y, dveh._speed = 40, 0, 0
        driveReset(dveh)
        driveTick(dp, dveh)
        for _ = 1, 2 do drive.frameMs(10); drive.scanRound(true) end
        local sen, rs = ss.sensor, ss.lastSNow
        local n = 0
        for dsx = 10, 24 do for l = -6, 6 do
            n = n + 1
            sen.hardS[n], sen.hardL[n], sen.hardR[n], sen.hardB[n] = rs + dsx, l, 0.7, 0.5
            sen.hardX[n], sen.hardY[n] = dveh._x + dsx, l
        end end
        sen.hardN, sen.wideDone, sen.corridorHalf, sen.unloaded = n, true, 14, false
        local function tryAt(H)
            sen.scanEndS = rs + H
            local _, a, b, c, d, offL = MDADCorridor.plan(sen.hardS, sen.hardL, n, ss.needHalf, 14, 0, sen.hardR, 0,
                nil, nil, true, nil, rs - ss.vehicleProfile.halfL)
            local ok, _, variant, _, _, _, rc = MDAD.Drive.debugSweepFallbacks(0, a, b, c, d, offL, "stay-trunc")
            return ok, variant, rc and (rc - rs), c and (c - rs)
        end
        ss.wideArmed = true
        local okA, varA, rcA, cA = tryAt(30)
        ss.wideArmed = false
        local okN = tryAt(30)
        checkTrue(okA == true and varA == "stay" and rcA < cA and okN ~= true,
            "(stay-armed) 停點寬帶：停留線收短到看得到的地方（stay c=" .. tostring(rcA) .. " < 群出口 "
            .. tostring(cA) .. "）；非停點仍等開近（ok=" .. tostring(okN) .. "）")
        local trl = { getForwardVector = function(_, out) return out:set(dveh._fwdX, 0, dveh._fwdY) end,
            getUpVectorDot = function() return 1 end }
        ss.tow = { trailer = trl, L2 = 3, hitchToRear = 3.5, halfW = 1.0, halfL = 2.0, hitchZ = -2.0,
            hitchX = 0, boxBack = 1.0, boxSide = 0, trailLen = 5, mass = 800, axisSign = 1 }
        local okT30 = tryAt(30)
        local okT38, _, rcT38, cT38 = tryAt(38)
        ss.wideArmed = true
        local okTA = tryAt(30)
        checkTrue(okT30 ~= true and okTA ~= true and okT38 == true and rcT38 >= cT38 + 5 - 1e-6,
            "(stay-tow) 拖車停留不收到掛車還在群旁：前緣 30 不承諾（" .. tostring(okT30) .. "／停點 " .. tostring(okTA)
            .. "）、前緣 38 保持段到群出口＋掛車長（c=" .. tostring(rcT38) .. "）")
        ss.tow, ss.wideArmed = nil, false
        MDAD.Drive.stop(0, nil)
    end
    drive.frameMs(wasMs)
    drive.fillWorld(-2, 70, -7, 7)
    SandboxVars = oldSand
end
drive.scenario0929p()

-- 1004c（使用者 2026-10-04「障礙多的地方不要太早判定繞遠路，逐漸掃描加大、找得到回到道路的路線就走，真的都不行才考慮繞道」）：
--   (wide2) 牆蓋滿第一級寬帶（±13.5）可規劃的範圍：第一級判堵不開倒車／自動改道的閘（停等 11 秒也不動）、升第二級重掃
--     （±19.5、規劃半寬 19），從更外側繞過。違規證明：TUNE.WIDE_LEVEL_MAX＝1（不升級）＝第一級判完就改道、沒有第二級＝紅。
--   (wide2-tow) 拖車維持第一級：判完即開閘。違規證明：拿掉 wideJudge 的拖車條件＝紅。
--   (wide2-band) 寬帶輪帶心在 nav 線：常駐偏置 +3 時第一級的帶照樣是 ±13.5（Corridor.plan 以 nav 線對稱規劃，帶心跟偏置走
--     會留一條沒掃過的帶當淨空）。違規證明：拿掉 Sensor 寬帶輪的帶心歸零＝紅。
function drive.scenario1004c()
    scenario("1004c：寬帶逐級加大——第一級仍堵升第二級才倒車／改道、拖車不升、帶心在 nav 線")
    local oldSand = SandboxVars
    setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false, AutoDriveMaxSpeed = 40, RightLaneBias = 0 })
    local wasMs = drive.frameMs(10)
    if type(MDAD.HUD) ~= "table" then MDAD.HUD = {} end
    local oldAuto = MDAD.HUD.autoDetour
    MDAD.HUD.autoDetour = function() return true end
    local function stopAtWall(half)
        drive.fillWorld(-10, 160, -24, 24)
        for x = 40, 42 do for y = -half, half do drive.putSolid(x, y, "wide2_wall") end end
        drive.nav.detourCalls = 0
        armDrive()
        setHeading(dveh, 0)
        dveh._x, dveh._y, dveh._speed = 31, 0, 0
        driveReset(dveh)
        driveTick(dp, dveh)
        drive.frameMs(10); drive.scanRound(true) -- 一般帶判堵、停點武裝
        drive.frameMs(10); drive.scanRound(true) -- 寬帶第一級
        return MDAD.Drive.debugSession(0)
    end
    local function clearWall(half)
        MDAD.Drive.stop(0, nil)
        for x = 40, 42 do for y = -half, half do drive.clearCell(x, y) end end
    end
    -- (wide2)
    local st = stopAtWall(13)
    local lvl1 = st.sensor.wideDoneLevel
    local held = st.blocked == true and st.wideJudged == nil and MDAD.Drive.wideLevelOf(st) == 2
    nowMs = nowMs + 11000 -- 超過自動改道 10s、倒車 5s 的門檻：第二級沒判完都不能動
    driveReset(dveh)
    driveTick(dp, dveh)
    local idle = st.mode ~= "unstick" and (drive.nav.detourCalls or 0) == 0
    checkTrue(lvl1 == 1 and held and idle,
        "(wide2) 第一級判堵：升第二級，倒車／自動改道等第二級判完（lvl=" .. tostring(lvl1) .. " held=" .. tostring(held)
        .. " mode=" .. tostring(st.mode) .. " detour=" .. tostring(drive.nav.detourCalls) .. "）")
    drive.frameMs(10); drive.scanRound(true) -- 第二級
    local offL = st.fstate.offL or 0
    checkTrue(st.sensor.wideDoneLevel == 2 and st.sensor.corridorHalf == 19 and st.dodging == true
            and st.dodgeWide == true and st.dodgeWideLevel == 2 and math.abs(offL) > 13.5,
        "(wide2) 第二級從更外側繞過（lvl=" .. tostring(st.sensor.wideDoneLevel) .. " half=" .. tostring(st.sensor.corridorHalf)
        .. " dodging=" .. tostring(st.dodging) .. " offL=" .. tostring(offL) .. " plan=" .. tostring(st.planMode) .. "）")
    -- (wide2-ring) 第二級停點輪只多出外圈：判堵候選鏈排除第一級的內圈（Corridor.plan ringFrom）；承諾後的守護輪不分圈
    --   （途中釋放後重規劃要看得到回路面的近縫）。違規證明：守護輪也發布 corridorInner＝紅。
    local innerStop = st.sensor.corridorInner
    drive.frameMs(10); drive.scanRound(true) -- 承諾後的守護輪
    checkTrue(st.sensor.wideDoneLevel == 2 and (drive.nav.detourCalls or 0) == 0,
        "(wide2) 承諾後的守護輪沿用第二級（看得到整條承諾線），從頭到尾沒改道（lvl=" .. tostring(st.sensor.wideDoneLevel) .. "）")
    checkTrue(innerStop == 14 and st.sensor.corridorInner == nil,
        "(wide2-ring) 停點第二級只搜外圈（inner=" .. tostring(innerStop) .. "）、守護輪不分圈（inner="
        .. tostring(st.sensor.corridorInner) .. "）")
    -- (wide2-gate) 跑道不夠先倒車不問改道（額度用完或倒不了才問）；倒車後的新跑道寬帶還沒判完，停等預算到期最多再等
    --   WIDE_JUDGE_GRACE_MS（第一次停等不寬限）。違規證明：拿掉 autoDetourNow 的 runwayRetryFirst／寬限的 attempt 條件＝紅。
    local R, P = MDAD.Drive.runwayRetryFirst, MDAD.Drive.wideJudgePending
    checkTrue(R({ blockSteepM = 2, episodeAttempts = 1 }) and not R({ blockSteepM = 2, episodeAttempts = 3 })
            and not R({ blockSteepM = 2, episodeAttempts = 1, blockRetryDone = true })
            and not R({ blockSteepM = -1, episodeAttempts = 0 }),
        "(wide2-gate) 跑道不夠＋倒車額度還在＋沒被後方擋過＝先倒車；額度用完、倒不了、不是跑道問題＝照常可改道")
    local T = MDAD.Drive.debugTune()
    local W, G = T.WAIT_TIMEOUT_MS, T.WIDE_JUDGE_GRACE_MS
    checkTrue(P({ wideArmed = true, episodeAttempts = 1, wideJudged = 0, waitAccumMs = W + 500 })
            and not P({ wideArmed = true, episodeAttempts = 0, wideJudged = nil, waitAccumMs = W + 500 })
            and not P({ wideArmed = true, episodeAttempts = 1, wideJudged = 1, waitAccumMs = W + 500 })
            and not P({ wideArmed = true, episodeAttempts = 1, wideJudged = 0, waitAccumMs = W + G + 1 }),
        "(wide2-gate) 倒車後寬帶還沒判完：預算到期再等（判完、第一次停等、超過寬限都照常交還）")
    clearWall(13)
    -- 整合：牆蓋滿兩級寬帶＝判堵；判定是跑道不夠（steep）、已倒車一次又停等過 5 秒＝倒車，不問改道（舊制同一幀就改道）
    st = stopAtWall(24)
    drive.frameMs(10); drive.scanRound(true) -- 第二級判完
    st.blockSteepM, st.episodeAttempts, st.wideJudged, st.waitAccumMs = 3, 1, 1, 6000
    drive.nav.detourCalls = 0
    nowMs = nowMs + 16
    driveReset(dveh)
    driveTick(dp, dveh)
    checkTrue((drive.nav.detourCalls or 0) == 0 and st.mode == "unstick",
        "(wide2-gate) 跑道不夠＋額度還在：先倒車補跑道、不問改道（detour=" .. tostring(drive.nav.detourCalls)
        .. " mode=" .. tostring(st.mode) .. "）")
    clearWall(24)
    -- (wide2-stale) 沒跑候選鏈的判堵（初判無縫、降檔也沒縫）不沿用上一次判定的 steep 差額／shape：否則第二級留下的 steep
    --   讓之後每次第一級無縫判堵都不再升級、改道一直讓給倒車（E2E blockscan dixie9350w）。違規證明：拿掉重設＝紅。
    st = stopAtWall(24)
    st.blockSteepM, st.dodgeShapeReason, st.planSig = 3, "steep", -1
    drive.frameMs(10); drive.scanRound(true)
    checkTrue(st.blocked == true and st.blockSteepM < 0 and st.dodgeShapeReason == nil,
        "(wide2-stale) 無縫判堵重設 steep 差額（blockSteepM=" .. tostring(st.blockSteepM) .. " shape="
        .. tostring(st.dodgeShapeReason) .. "）")
    clearWall(24)
    -- (wide2-tow)
    st = stopAtWall(13)
    st.tow = { trailLen = 0 }
    st.wideJudged, st.wideLevel, st.wideLevelAt = nil, nil, nil
    MDAD.Drive.wideJudge(st, 0)
    checkTrue(st.wideJudged == st.episodeAttempts and MDAD.Drive.wideLevelOf(st) == 1,
        "(wide2-tow) 拖車不升級：第一級判完即開倒車／改道的閘（judged=" .. tostring(st.wideJudged) .. "）")
    st.tow = nil
    clearWall(13)
    -- (wide2-band)
    st = stopAtWall(13)
    st.sensor.scanBias = 3
    st.wideLevel, st.wideLevelAt = nil, nil -- 撤回第一級的升級：這一輪量第一級（±13.5）的帶心
    drive.frameMs(10); drive.scanRound(true)
    local lo, hi = 99, -99
    for i = 1, st.sensor.hardN do
        local l = st.sensor.hardL[i]
        if l < lo then lo = l end
        if l > hi then hi = l end
    end
    -- 帶心跟偏置走（舊制）＝第一級只掃 [−10.5, 16.5]，牆在 −10.5 外那段（y −13..−11）看不到
    checkTrue(st.sensor.wideDone == true and st.sensor.completedBandBias == 0 and lo < -11,
        "(wide2-band) 寬帶輪帶心在 nav 線：常駐偏置 +3 仍掃到 −10.5 外的牆（band=" .. tostring(st.sensor.completedBandBias)
        .. " l=[" .. tostring(lo) .. "," .. tostring(hi) .. "]）")
    clearWall(13)
    MDAD.HUD.autoDetour = oldAuto
    drive.frameMs(wasMs)
    SandboxVars = oldSand
end
drive.scenario1004c()

-- 1004d（使用者 2026-10-04「遇到樹叢也可以加大推力來幫助通過」）：
--   (bush-cancel) 引擎每幀對車身外 0.3m 內的每一叢施 −mul×質量×速度（側面或 <10 km/h 0.025、正面 ≥10 km/h 0.1）；
--     Drive.bushCancel 對同一批樹叢以 −mul 呼叫同一個方法抵消。車心 (20.5,0.5) 朝 +x、車身 1.8×4.4：側面一叢（車身外
--     0.1）、車頭內一叢、車身外 1.1 一叢（沒碰到）、車身內 d_plants_1 一叢（引擎不施力）：只抵消前兩叢，10 km/h 以上
--     正面那叢換 0.1；倒車照抵；≤1 km/h、鋪面上跟線（不在路外／繞行／回線／倒車）不抵消。每一格都斷言 session 還活著
--     （引擎熄火時 driveGate 直接收掉 session，在死 session 上數到 0 次＝假綠）。
--     違規證明：mul 不取負／側正面判反／速度門檻拿掉／d_plants 排除拿掉／路外閘拿掉＝各自紅。
--   (bush-fail) 方法呼叫失敗：bushOff "call"、Sensor 寬帶改回避開樹叢、記一次 bush off 事件、之後不再呼叫。
--   (bush-stale) 候選抓到後才被砍掉、物件已回收（getSquare 回 nil）：只跳過那叢，不當方法失敗。違規證明：失敗一律關掉＝紅。
--   (bush-tow) 拖車：不抵消（掛車自己的樹叢阻力抵不掉），寬帶照舊避開樹叢。違規證明：拿掉 tow 條件＝紅。
function drive.scenario1004d()
    scenario("1004d：樹叢阻力抵消——照引擎的接觸判定逐叢反向施力、失敗退回避開、拖車不做")
    local oldSand = SandboxVars
    setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false, AutoDriveMaxSpeed = 40, RightLaneBias = 0 })
    drive.fillWorld(-10, 80, -10, 10)
    local bprops = { has = function(_, key) return key == "Bush" end, get = function() return nil end }
    local bsprite = { shouldHaveCollision = function() return false end, getProperties = function() return bprops end }
    local function putBush(x, y, name)
        local sq = drive.world[x * 100000 + y] or drive.mkSquare(x, y)
        local obj = { getSpriteName = function() return name end, getSprite = function() return bsprite end,
            getProperties = function() return bprops end, getType = function() return nil end,
            getSquare = function() return sq end }
        sq._objs[#sq._objs + 1] = obj
        return obj
    end
    local side = putBush(21, 1, "harness_bush")  -- 格心 (21.5,1.5)：橫向 1.0＝車身外 0.1
    local front = putBush(22, 0, "harness_bush") -- 格心 (22.5,0.5)：縱向 2.0、橫向 0＝車身框內、最近車頭那一面
    putBush(20, 2, "harness_bush")               -- 格心 (20.5,2.5)：車身外 1.1，沒碰到
    putBush(19, 0, "d_plants_1_5")               -- 車身框內，但 d_plants_1 引擎只播聲音
    armDrive()
    local s = MDAD.Drive.debugSession(0)
    local passable0, off0 = s.sensor.bushPassable, s.bushOff
    setHeading(dveh, 0)
    dveh._x, dveh._y = 20.5, 0.5
    dveh._offroad, s.physicalOffroad = true, true
    local function frame(speed)
        dveh._speed = speed
        dveh._plant = { n = 0, obj = {}, mul = {} }
        s.bushScanMs = 0 -- 車沒動、只換速度：每格重抓候選
        nowMs = nowMs + 16
        driveReset(dveh)
        driveTick(dp, dveh)
        local p, got = dveh._plant, {}
        for i = 1, p.n do got[p.obj[i]] = p.mul[i] end
        return p.n, got[side], got[front]
    end
    local n8, s8, f8 = frame(8)
    local contact8 = s.bushContactN
    checkTrue(passable0 == true and off0 == nil and n8 == 2 and s8 == -0.025 and f8 == -0.025 and contact8 == 2,
        "(bush-cancel) 8 km/h：側面、正面兩叢各以 −0.025 抵消，沒碰到的與 d_plants_1 不動（n=" .. tostring(n8)
        .. " side=" .. tostring(s8) .. " front=" .. tostring(f8) .. " contact=" .. tostring(contact8)
        .. " passable=" .. tostring(passable0) .. "）")
    local n15, s15, f15 = frame(15)
    checkTrue(n15 == 2 and s15 == -0.025 and f15 == -0.1,
        "(bush-cancel) 15 km/h：正面那叢換 −0.1、側面維持 −0.025（side=" .. tostring(s15) .. " front=" .. tostring(f15) .. "）")
    local nRev, sRev, fRev = frame(-8)
    checkTrue(nRev == 2 and sRev == -0.025 and fRev == -0.025,
        "(bush-cancel) 倒車 8 km/h 照樣抵消（n=" .. tostring(nRev) .. "）")
    local nSlow = frame(0.9)
    dveh._offroad, s.physicalOffroad = false, false
    local nPaved = frame(8)
    checkTrue(nSlow == 0 and nPaved == 0 and s.dodging ~= true and s.returnActive ~= true
            and MDAD.Drive.debugSession(0) == s,
        "(bush-cancel) ≤1 km/h、鋪面上跟線都不抵消，session 仍在（slow=" .. tostring(nSlow) .. " paved="
        .. tostring(nPaved) .. "）")
    -- (bush-stale) 候選抓到後被砍掉、物件已回收（getSquare 回 nil）：那叢呼叫失敗只跳過，其他照抵、不關掉抵消
    dveh._offroad, s.physicalOffroad = true, true
    local plantOk, sideSq = dveh.applyImpulseFromHitPlant, side.getSquare
    side.getSquare = function() return nil end
    dveh.applyImpulseFromHitPlant = function(self, obj, mul)
        if obj == side then error("reclaimed") end
        return plantOk(self, obj, mul)
    end
    local nStale, sStale, fStale = frame(8)
    dveh.applyImpulseFromHitPlant, side.getSquare = plantOk, sideSq
    checkTrue(nStale == 1 and sStale == nil and fStale == -0.025 and s.bushOff == nil and s.sensor.bushPassable == true
            and MDAD.Drive.debugSession(0) == s,
        "(bush-stale) 已回收的樹叢呼叫失敗：只跳過那叢、其他照抵、不關掉（n=" .. tostring(nStale) .. " front="
        .. tostring(fStale) .. " off=" .. tostring(s.bushOff) .. "）")
    -- (bush-fail)
    dveh._offroad, s.physicalOffroad = true, true
    -- 這段要 diag 開著才看得到事件：取樣也換成假的（真的 sample 沒有起 telemetry session，會把 s.diag 關掉）
    local oldEvent, oldSample, events, calls = MDADDiagnostics.event, MDADDiagnostics.sample, {}, 0
    MDADDiagnostics.event = function(_, name, a) events[#events + 1] = { name = name, a = a } end
    MDADDiagnostics.sample = function() return true end
    local plantFn = dveh.applyImpulseFromHitPlant
    dveh.applyImpulseFromHitPlant = function() calls = calls + 1 error("plant-fail") end
    local diagWas = s.diag
    s.diag = true
    frame(8)
    local offAfter, passAfter, callsAfter = s.bushOff, s.sensor.bushPassable, calls
    frame(8)
    frame(8)
    local offEvents = 0
    for _, e in ipairs(events) do
        if e.name == "bush" and e.a and e.a.phase == "off" and e.a.why == "call" then offEvents = offEvents + 1 end
    end
    local diagOn = s.diag
    s.diag = diagWas
    MDADDiagnostics.event, MDADDiagnostics.sample = oldEvent, oldSample
    dveh.applyImpulseFromHitPlant = plantFn
    checkTrue(offAfter == "call" and passAfter == false and callsAfter == 1 and calls == 1 and offEvents == 1
            and diagOn == true and MDAD.Drive.debugSession(0) == s,
        "(bush-fail) 呼叫失敗：bushOff call、寬帶改回避開樹叢、之後不再呼叫、bush off 事件一筆（off=" .. tostring(offAfter)
        .. " passable=" .. tostring(passAfter) .. " calls=" .. tostring(calls) .. " events=" .. tostring(offEvents)
        .. " diag=" .. tostring(diagOn) .. "）")
    MDAD.Drive.stop(0, nil)
    -- (bush-tow)
    local oldAttach = MDADTrailer.attach
    local trl = { getForwardVector = function(_, out) return out:set(dveh._fwdX, 0, dveh._fwdY) end,
        getUpVectorDot = function() return 1 end }
    MDADTrailer.attach = function()
        return { trailer = trl, L2 = 3, hitchToRear = 3.5, halfW = 1.0, halfL = 2.0, hitchZ = -2.0, hitchX = 0,
            boxBack = 1.0, boxSide = 0, trailLen = 5, mass = 800, axisSign = 1 }
    end
    local startedTow = armDrive()
    MDADTrailer.attach = oldAttach
    local ts = MDAD.Drive.debugSession(0)
    setHeading(dveh, 0)
    dveh._x, dveh._y = 20.5, 0.5
    dveh._offroad, ts.physicalOffroad = true, true
    s = ts
    local nTow = frame(8)
    checkTrue(startedTow and type(ts.tow) == "table" and ts.bushOff == "tow" and ts.sensor.bushPassable == false
            and nTow == 0,
        "(bush-tow) 拖車：不抵消、寬帶照舊避開樹叢（off=" .. tostring(ts.bushOff) .. " passable="
        .. tostring(ts.sensor.bushPassable) .. " n=" .. tostring(nTow) .. "）")
    dveh._offroad = false
    MDAD.Drive.stop(0, nil)
    drive.fillWorld(-2, 70, -7, 7)
    SandboxVars = oldSand
end
drive.scenario1004d()

-- 1004e（使用者「遇到障礙可以流暢判斷路線、不要停留太久」；E2E dixie9050w 改道調頭後 start-near 被 MIN_EXEC 抬回 8 撞上）：
--   (hold) 車不在常駐線（3.4 vs 0），往常駐線斜切的帶內有硬物：Drive.transitionHold 回車位（保持）、記 lane hold；
--     車尾越過物件後放回常駐線、記 lane release clear。違規證明：拿掉保持＝回常駐線＝紅。
--   (hold-far) 車心另一側、貼著車側外 0.2 的桿不算（斜切是遠離它；保持反而沿它擦過去）。違規證明：拿掉 d ≥ 0＝紅。
--   (hold-live) 真的掃描輪：車在 1.9（不進 RETURN）、斜切帶內有硬物 → laneBias 留在車位。
--   (strip) 起步近物限速只看車頭前方帶：車側帶外的硬物不限速（舊制取前半車身任何方向最近點＝start-near／min-exec）。
--   (near) 車頭正對 1.4m 外的硬物（車頭偏路線 34°，規劃器以常駐線判不擋）：start-near 帽 < MIN_EXEC 不抬回、意圖 WAIT；
--     停住 START_NEAR_STALL_MS 請求倒車（start-near）進 unstick。違規證明：拿掉 WAIT 歸類＝抬回 8＝紅；拿掉停住出口＝紅。
function drive.scenario1004e()
    scenario("1004e：斜切保持、起步近物限速只看前方帶、低於 MIN_EXEC 不抬回並倒車讓空間")
    local oldSand = SandboxVars
    setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false, AutoDriveMaxSpeed = 40, RightLaneBias = 0 })
    drive.fillWorld(-10, 80, -10, 10)
    local oldEvent, oldSample, events = MDADDiagnostics.event, MDADDiagnostics.sample, {}
    MDADDiagnostics.event = function(_, name, a) events[#events + 1] = { name = name, a = a } end
    MDADDiagnostics.sample = function() return true end
    local function lastEvent(name, phase)
        for i = #events, 1, -1 do
            local e = events[i]
            if e.name == name and e.a and e.a.phase == phase then return e.a end
        end
        return nil
    end
    armDrive()
    local s = MDAD.Drive.debugSession(0)
    s.diag = true
    setHeading(dveh, 0)
    dveh._x, dveh._y, dveh._speed = 10, 0, 10
    driveReset(dveh)
    drive.scanRound(true)
    -- (hold)／(hold-far)：直接問 Drive.transitionHold（真 session 的剖面與車身，只換快照點）
    local sen = s.sensor
    local keepN, keepS, keepL, keepR = sen.hardN, sen.hardS[1], sen.hardL[1], sen.hardR[1]
    local keepLat, keepRs = s.lastLatSigned, s.lastSNow
    sen.hardN, sen.hardS[1], sen.hardL[1], sen.hardR[1] = 1, 16.5, 0.5, 0.7
    s.lastLatSigned, s.lastSNow, s.holdLaneL = 3.4, 10, nil
    local held = MDAD.Drive.transitionHold(s, 0, 0, 10)
    local holdEv = lastEvent("lane", "hold")
    s.lastSNow = 16.5 + s.vehicleProfile.halfL + 1.5
    local passed = MDAD.Drive.transitionHold(s, 0, 0, 10)
    local relEv = lastEvent("lane", "release")
    checkTrue(held == 3.4 and holdEv ~= nil and holdEv.l == 3.4 and passed == 0 and s.holdLaneL == nil
            and relEv ~= nil and relEv.why == "clear",
        "(hold) 斜切帶內有硬物先沿車位直走、車尾越過後放回常駐線（held=" .. tostring(held) .. " passed="
        .. tostring(passed) .. " release=" .. tostring(relEv and relEv.why) .. "）")
    sen.hardS[1], sen.hardL[1], sen.hardR[1] = 10.5, 4.5, 0
    s.lastSNow = 10
    local far = MDAD.Drive.transitionHold(s, 0, 0, 10)
    checkTrue(far == 0 and s.holdLaneL == nil,
        "(hold-far) 車心另一側貼著車側的桿不算：不保持（實得 " .. tostring(far) .. "）")
    sen.hardN, sen.hardS[1], sen.hardL[1], sen.hardR[1] = keepN, keepS, keepL, keepR
    s.lastLatSigned, s.lastSNow = keepLat, keepRs
    -- (hold-live)
    drive.putSolid(16, -1, "harness_hold_obj") -- 格心 (16.5,−0.5)：擋常駐線 0、不擋車位 1.9
    dveh._x, dveh._y = 10, 1.9
    driveReset(dveh)
    drive.scanRound(true)
    checkTrue(s.holdLaneL ~= nil and math.abs(s.holdLaneL - 1.9) < 0.1 and math.abs(s.fstate.laneBias - s.holdLaneL) < 1e-9
            and not s.dodging and not s.returnActive and MDAD.Drive.debugSession(0) == s,
        "(hold-live) 掃描輪：斜切帶內有硬物，laneBias 留在車位、不另起繞行（hold=" .. tostring(s.holdLaneL)
        .. " bias=" .. tostring(s.fstate.laneBias) .. " dodging=" .. tostring(s.dodging) .. "）")
    drive.clearCell(16, -1)
    MDAD.Drive.stop(0, nil)
    -- (strip)：車側 2.5（車身外 0.9＋半徑 0.7 之外）的硬物
    drive.putSolid(13, 2, "harness_side_obj")
    armDrive()
    s = MDAD.Drive.debugSession(0)
    setHeading(dveh, 0)
    dveh._x, dveh._y, dveh._speed = 10, 0, 10
    driveReset(dveh)
    drive.scanRound(true)
    driveReset(dveh)
    driveTick(dp, dveh)
    checkTrue(s.startGuard == true and s.frontClearance == nil and s.lastCapReason ~= "start-near"
            and s.minExecFrom ~= "start-near",
        "(strip) 車頭前方帶外的硬物不觸發起步近物限速（fc=" .. tostring(s.frontClearance) .. " cap="
        .. tostring(s.lastCapReason) .. "）")
    MDAD.Drive.stop(0, nil)
    -- (near)：車頭偏 0.6 rad 正對同一個物件（車座標前方 4.3m、橫向 0.1）
    armDrive()
    s = MDAD.Drive.debugSession(0)
    s.diag = true
    setHeading(dveh, 0.6)
    dveh._x, dveh._y, dveh._speed = 10, 0, 0
    driveReset(dveh)
    drive.scanRound(true)
    driveReset(dveh)
    driveTick(dp, dveh)
    local nearCap, nearIntent, nearReg = s.startNearCap, s.intentShadow, drive.calls.maxRegSpeed
    checkTrue(s.startGuard == true and s.lastCapReason == "start-near" and type(nearCap) == "number"
            and nearCap < MDADDynamics.MIN_EXEC_KMH and nearIntent == "WAIT" and nearReg < MDADDynamics.MIN_EXEC_KMH
            and not s.blocked and not s.dodging,
        "(near) start-near 帽 < MIN_EXEC：意圖 WAIT、不抬回 8（cap=" .. tostring(nearCap) .. " intent="
        .. tostring(nearIntent) .. " reg=" .. tostring(nearReg) .. " reason=" .. tostring(s.lastCapReason) .. "）")
    drive.stallFrames(MDAD.Drive.debugTune().START_NEAR_STALL_MS + 300)
    driveReset(dveh)
    driveTick(dp, dveh)
    driveTick(dp, dveh)
    local recEv = lastEvent("progress", "recover")
    checkTrue(s.mode == "unstick" and recEv ~= nil and recEv.why == "start-near",
        "(near) 停住 START_NEAR_STALL_MS：請求倒車讓空間（mode=" .. tostring(s.mode) .. " why="
        .. tostring(recEv and recEv.why) .. "）")
    MDADDiagnostics.event, MDADDiagnostics.sample = oldEvent, oldSample
    MDAD.Drive.stop(0, nil)
    -- (handoff-wide)：交接停住（dodgeHandoffHold＋blocked）在停止線外也武裝寬帶，帶速不武裝（煞停途中會開過武裝點）
    armDrive()
    s = MDAD.Drive.debugSession(0)
    setHeading(dveh, 0)
    dveh._x, dveh._y, dveh._speed = 10, 0, 0
    driveReset(dveh)
    drive.scanRound(true)
    local function handoffTick(speed)
        s.dodgeHandoffHold, s.blocked, s.dodging = true, true, false
        s.blockHitX, s.blockHitY, s.blockS = 30.5, 0.5, 30 -- 停止線（10m）外
        s.wideArmed, s.wideArmedS = false, nil
        dveh._speed = speed
        driveReset(dveh)
        driveTick(dp, dveh)
        return s.wideArmed == true
    end
    local armedMoving = handoffTick(12)
    local armedStopped = handoffTick(0)
    checkTrue(not armedMoving and armedStopped and MDAD.Drive.debugSession(0) == s,
        "(handoff-wide) 交接停住在停止線外也武裝寬帶、帶速不武裝（moving=" .. tostring(armedMoving)
        .. " stopped=" .. tostring(armedStopped) .. "）")
    MDAD.Drive.stop(0, nil)
    drive.clearCell(13, 2)
    drive.fillWorld(-2, 70, -7, 7)
    SandboxVars = oldSand
end
drive.scenario1004e()

do -- 主 chunk local 槽已滿：整段包成函式，內部 local 不佔主 chunk
-- =====================================================================
-- v6 多停靠點行程（docs/addon-api.md §6）
-- 契約的另一半用「真的會拒絕」的模型實作：站點、revision、legToken、claim 擁有者
-- 與一次性收據全部照 §6.2-§6.4 判斷。把條件全設 true 的假 API 測不到任何東西——
-- claim 前不准控制、token 失效要交還、road_end 不是抵達，統統要靠真的被拒才驗得到。
-- =====================================================================
local function scenarioItinerary()
scenario("v6 行程：claim 前零控制、每幀核對 token、到站／road_end／重送、交還不留 orphan")

local M = {
    phase = "draft", revision = 3, stops = {}, current = 1,
    legToken = nil, claimOwner = nil, claimToken = nil, tokenSeq = 0, receipt = nil,
    starts = 0, claims = 0, reports = 0, releases = 0,
    lastStart = nil, lastRelease = nil, lastOwner = nil, releaseRegOff = nil,
    rejectReports = 0, rejectReleases = 0, oddReport = false,
    oddConsume = false, pausedReason = nil,
}
local function newToken()
    M.tokenSeq = M.tokenSeq + 1
    return "leg#" .. M.tokenSeq
end
local function activeToken() return M.claimToken or M.legToken end
local function currentStop() return M.stops[M.current] end
local function bump() M.revision = M.revision + 1 end

-- 六個 v6 函式（§6.4）。失敗一律回契約規定的原因字串，不回 true 蒙混。
local function api6()
    installNavApi(6)
    local api = MinidoracatMiniMapAPI
    api.getNavItinerary = function(pn)
        if pn ~= 0 then return nil, "badargs" end
        if #M.stops == 0 then return nil, "noitinerary" end
        -- paused 的快照帶 reason（§6.4 的 UI 原因）：載入問題／不可達都靠它說明。
        local out = { revision = M.revision, phase = M.phase, count = #M.stops,
            reason = M.pausedReason, stops = {} }
        for i = 1, #M.stops do
            out.stops[i] = { id = M.stops[i].id, x = M.stops[i].x,
                y = M.stops[i].y, status = M.stops[i].status }
        end
        return out
    end
    -- 有行程但沒有活動段：只回 phase/revision，不是錯誤（§6.4）
    api.getNavLeg = function(pn)
        if pn ~= 0 then return nil, "badargs" end
        if #M.stops == 0 then return nil, "noitinerary" end
        if M.phase ~= "navigating" and M.phase ~= "approach" then
            return nil, nil, nil, nil, M.phase, M.revision
        end
        local st = currentStop()
        return activeToken(), st.id, st.x, st.y, M.phase, M.revision
    end
    -- §6.6：只有 navigating／approach 投影目前站，其餘 notarget
    api.getNavTarget = function(pn)
        drive.nav.targetCalls = drive.nav.targetCalls + 1
        if #M.stops == 0 or (M.phase ~= "navigating" and M.phase ~= "approach") then
            return nil, "notarget"
        end
        local st = currentStop()
        return st.x, st.y
    end
    api.startNavItinerary = function(pn, expectedRevision)
        M.starts, M.lastStart = M.starts + 1, expectedRevision
        if #M.stops == 0 then return nil, "noitinerary" end
        if M.phase ~= "draft" and M.phase ~= "paused" and M.phase ~= "waiting" then
            return nil, "state"
        end
        if expectedRevision ~= M.revision then return nil, "stale" end
        for i = 1, #M.stops do
            if M.stops[i].status == "pending" then M.current = i break end
        end
        M.phase, M.claimOwner, M.claimToken = "navigating", nil, nil
        M.legToken = newToken()
        bump()
        return M.legToken, "ok"
    end
    api.claimNavLeg = function(pn, owner, expectedToken)
        M.claims, M.lastOwner = M.claims + 1, owner
        if type(owner) ~= "string" or owner == "" then return nil, "badargs" end
        if #M.stops == 0 then return nil, "noitinerary" end
        if M.phase ~= "navigating" then return nil, "state" end
        if M.claimOwner and M.claimOwner ~= owner then return nil, "busy" end
        if expectedToken ~= activeToken() then return nil, "stale" end
        if M.claimOwner == owner then return M.claimToken, "ok" end -- 同 owner 重 claim 回同 token
        if dveh._driver ~= dp then return nil, "notdriver" end
        if not dveh._stopped then return nil, "notstopped" end
        M.claimOwner, M.claimToken = owner, newToken()
        return M.claimToken, "ok"
    end
    api.reportNavArrival = function(pn, owner, token)
        M.reports = M.reports + 1
        local r = M.receipt
        if r and r.op == "report" and r.owner == owner and r.token == token then
            return true, "duplicate"
        end
        if type(owner) ~= "string" or owner == "" then return false, "badargs" end
        -- 情境旋鈕：MiniMap 暫時不認同「已停妥」／回一個我們沒見過的成功值
        if M.rejectReports > 0 then
            M.rejectReports = M.rejectReports - 1
            return false, "notstopped"
        end
        -- 未知成功值：oddConsume 決定 token 到底有沒有被吃掉。addon 不能只看
        -- 「回了 true」就當作交割完成。
        if M.oddReport then
            M.oddReport = false
            if M.oddConsume then
                M.receipt = { op = "report", owner = owner, token = token }
                M.claimOwner, M.claimToken, M.legToken = nil, nil, nil
                M.phase = "paused"
                bump()
            end
            return true, "something_new"
        end
        if M.claimOwner ~= owner or token ~= M.claimToken then return false, "stale" end
        if M.phase ~= "navigating" then return false, "state" end
        if not dveh._stopped then return false, "notstopped" end
        local st = currentStop()
        local dx, dy = dveh._x - st.x, dveh._y - st.y
        local near = dx * dx + dy * dy <= 25
        M.receipt = { op = "report", owner = owner, token = token }
        M.claimOwner, M.claimToken, M.legToken = nil, nil, nil
        if near then
            st.status = "arrived"
            local more = false
            for i = 1, #M.stops do
                if M.stops[i].status == "pending" then more = true end
            end
            M.phase = more and "waiting" or "completed"
        else
            -- road_end：站仍 pending，簽發新的徒步 token，不沿用已消耗的駕駛 token
            M.phase, M.legToken = "approach", newToken()
        end
        bump()
        -- 「回程掉了」：MiniMap 其實記下了，回給 addon 的卻是失敗。晚到的第一次回報
        -- 就長這樣——收據已經寫下，token 也已消耗。
        if M.lieOnce then
            M.lieOnce = false
            return false, "busy"
        end
        return true, near and "arrived" or "road_end"
    end
    api.releaseNavLeg = function(pn, owner, token, reason)
        M.releases, M.lastRelease = M.releases + 1, reason
        M.releaseRegOff = dveh._regulator == false
        local r = M.receipt
        if r and r.op == "release" and r.owner == owner and r.token == token then
            return true, "duplicate"
        end
        if M.rejectReleases > 0 then
            M.rejectReleases = M.rejectReleases - 1
            return false, "busy"
        end
        if reason ~= "manual" and reason ~= "cancelled" and reason ~= "unavailable"
                and reason ~= "noroad" and reason ~= "failed" then
            return false, "badargs"
        end
        if M.claimOwner ~= owner or token ~= M.claimToken then return false, "stale" end
        M.receipt = { op = "release", owner = owner, token = token }
        M.claimOwner, M.claimToken, M.legToken = nil, nil, nil
        M.phase = "paused"
        bump()
        if M.lieRelease then
            M.lieRelease = false
            return false, "busy"
        end
        return true, "released"
    end
end

local function setTrip(phase, x, y)
    M.stops = { { id = 1, x = x or 300, y = y or 0, status = "pending" } }
    M.current, M.phase, M.receipt = 1, phase, nil
    M.claimOwner, M.claimToken = nil, nil
    M.legToken = (phase == "navigating" or phase == "approach") and newToken() or nil
    M.starts, M.claims, M.reports, M.releases = 0, 0, 0, 0
    M.rejectReports, M.rejectReleases, M.oddReport = 0, 0, false
    M.lieOnce, M.lieRelease, M.oddConsume, M.pausedReason = false, false, false, nil
    bump()
end

-- 乾淨的一輛車＋一位駕駛；stopped 預設 true（claim 要求停妥）
local function ready(stopped)
    MDAD.Drive.stop(0, nil)
    -- 前面的情境（登入補學）在 slot0 塞過別的角色：本組要的是自駕那位駕駛。
    players[0], players[1], players[2], players[3] = dp, nil, nil, nil
    activePlayers = 1
    dveh._x, dveh._y, dveh._speed, dveh._steering = 0, 0, 0, 0
    dveh._stopped = stopped ~= false
    dveh._engine, dveh._driver, dveh._regulator = true, dp, nil
    dveh._part._item._uses = 0.8
    dp._vehicle, dp._dead, dp._local = dveh, false, true
    setHeading(dveh, 0.3)
    drive.nav.tx, drive.nav.ty, drive.nav.state = 300, 0, "ok"
    -- v4 起的嚴格 metadata：路線要帶逐段路面／路寬，否則 Follower.begin 直接拒收
    drive.nav.route = newRoute(40, 0, 0, 4, 0)
    drive.nav.route.segSurface, drive.nav.route.segWidth = {}, {}
    for i = 1, 39 do
        drive.nav.route.segSurface[i], drive.nav.route.segWidth[i] = "paved", 10
    end
    driveReset(dveh)
    clearList(halos)
    drive.voiceLog = {}
end

setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false,
    AutoDriveMaxSpeed = 40, RightLaneBias = 0 })
MDAD.Voice = { play = function(event) drive.voiceLog[#drive.voiceLog + 1] = event return true end }
api6()
-- 準備是跨幀的（查路線 → 建 session → 分幀建限速剖面 → claim → 接上），
-- 這個小工具就把它推到真的開起來或真的失敗為止。
local function pump(frames)
    for _ = 1, frames or 20 do
        if MDAD.Drive.debugSession(0) or not MDAD.Drive.isActive(0) then break end
        nowMs = nowMs + 300
        driveTick(dp, dveh)
    end
end


-- ① 路線還沒好：受理、進準備狀態、零控制、不逼玩家重複點
ready(true)
setTrip("draft")
local rev0 = M.revision
drive.nav.state = "pending"
local ok, why = MDAD.Drive.continueItinerary(0)
checkTrue(ok, "(t1) 路線未就緒：繼續行程仍受理，不當成失敗")
checkNil(why, "(t1) 受理時不回原因")
checkEq(M.starts, 1, "(t1) 玩家明確操作才 start 一次")
checkEq(M.lastStart, rev0, "(t1) start 帶讀取當下的 revision")
checkEq(M.claims, 0, "(t1) 路線未就緒：一次都不 claim")
checkEq(drive.calls.setRegulator, 0, "(t1) claim 成功前完全不碰車（零正向控制）")
checkEq(drive.calls.forceBrake, 0, "(t1) 準備中不煞車")
checkEq((MDAD.Drive.hudState(0)), "build", "(t1) 準備中 HUD 顯示 build")
checkTrue(MDAD.Drive.isActive(0), "(t1) 準備中算已啟動（停止鈕收得掉）")
checkTrue(MDAD.Drive.continueItinerary(0), "(t1) 準備中再按一次：不重發 token")
checkEq(M.starts, 1, "(t1) 重按不重複 start")
for _ = 1, 3 do nowMs = nowMs + 300 driveTick(dp, dveh) end
checkEq(drive.calls.setRegulator, 0, "(t1) 準備中每一幀都不控制")
checkEq(#halos, 0, "(t1) 等路線期間不因每次 idle 假報路線遺失")
checkTrue(MDAD.Drive.isActive(0), "(t1) 準備意圖跨幀存活，不需要重按")
checkEq(M.claims, 0, "(t1) 等待期間不重試 claim")
-- 路線就緒，但限速剖面還沒建完：仍然一次都不准 claim。
-- 用 stepBuild 樁讓前兩輪回「還沒好」，證明的是順序不是時間。
drive.nav.state = "ok"
local realStep = MDADFollower.stepBuild
local stepCalls = 0
MDADFollower.stepBuild = function(profile, budget)
    stepCalls = stepCalls + 1
    if stepCalls <= 2 then return false end
    return realStep(profile, budget)
end
nowMs = nowMs + 300
driveTick(dp, dveh)
checkEq(M.claims, 0, "(t1) 拿到路線的那一幀還不能 claim（剖面尚未建置）")
nowMs = nowMs + 300
driveTick(dp, dveh)
checkEq(stepCalls, 1, "(t1) 下一幀開始分幀建剖面")
checkEq(M.claims, 0, "(t1) 剖面沒建完就不 claim")
checkEq(drive.calls.setRegulator, 0, "(t1) 剖面建置期間仍然零控制輸出")
checkEq((MDAD.Drive.hudState(0)), "build", "(t1) 剖面建置期間 HUD 仍是 build")
checkNil(MDAD.Drive.debugSession(0), "(t1) 剖面沒好之前 session 不接上")
nowMs = nowMs + 300
driveTick(dp, dveh)
checkEq(M.claims, 0, "(t1) 第二輪剖面仍未就緒：還是不 claim")
MDADFollower.stepBuild = realStep
pump()
checkEq(M.claims, 1, "(t1) 剖面 ready 之後才 claim，而且只 claim 一次")
checkEq(M.lastOwner, MOD_ID, "(t1) claim 帶自己的 ownerModId")
checkTrue(MDAD.Drive.isActive(0), "(t1) claim 成功後 session 才接上")
checkEq(MDAD.Drive.debugSession(0).legToken, M.claimToken,
    "(t1) session 認 claim 簽發的新 token，不是 start 的 token")
checkTrue(drive.calls.setRegulator > 0, "(t1) claim 成功後才動 regulator")
checkEq(haloKey(), DKEY.START, "(t1) 真的開起來才回饋啟動")
checkTrue(MDAD.Drive.debugSession(0).profile.ready,
    "(t1) 接上的就是準備階段建好的剖面（不重建第二份）")
nowMs = nowMs + 300
driveTick(dp, dveh)
checkEq(MDAD.Drive.debugSession(0).mode, "follow",
    "(t1) 剖面已 ready：接上後第一幀就跟線，不再分幀重建")

-- ② 準備期間 token 被撤銷（玩家改了目前站）：立刻收手，沒有 claim 要還
ready(true)
setTrip("draft")
drive.nav.state = "pending"
checkTrue(MDAD.Drive.continueItinerary(0), "(t2) 進準備狀態")
M.legToken = newToken()
bump()
nowMs = nowMs + 300
driveTick(dp, dveh)
checkFalse(MDAD.Drive.isActive(0), "(t2) 準備期間 token 被撤銷：立刻收手")
checkEq(haloKey(), "UI_MinidoracatAutoDrive_TripStale", "(t2) 提示行程已變更")
checkEq(M.claims, 0, "(t2) 撤銷後不 claim")
checkEq(M.releases, 0, "(t2) 沒 claim 過就沒有東西要交還")

-- ③ 準備逾時：有界等待，時限到就真的拒絕啟動（不驗文案，只驗行為）
ready(true)
setTrip("draft")
drive.nav.state = "pending"
checkTrue(MDAD.Drive.continueItinerary(0), "(t3) 進準備狀態")
for _ = 1, 20 do nowMs = nowMs + 300 driveTick(dp, dveh) end
checkTrue(MDAD.Drive.isActive(0), "(t3) 時限之內照樣等，不提早放棄")
for _ = 1, 40 do nowMs = nowMs + 300 driveTick(dp, dveh) end
checkFalse(MDAD.Drive.isActive(0), "(t3) 逾時之後不再是啟動中：真的拒絕啟動")
checkNil(MDAD.Drive.debugSession(0), "(t3) 逾時不會偷偷留下 session")
checkEq(M.claims, 0, "(t3) 逾時期間一次都沒 claim")
checkEq(M.releases, 0, "(t3) 沒 claim 過就沒有東西要交還")
checkEq(drive.calls.setRegulator, 0, "(t3) 逾時期間完全沒控制")
checkEq(drive.calls.forceBrake, 0, "(t3) 逾時期間完全沒煞車")
checkEq(#halos, 1, "(t3) 逾時對玩家說一次原因，不是安靜失敗也不是洗版")
checkEq(halos[1] and halos[1].kind, "bad", "(t3) 逾時是失敗提示")
noteReason(halos[1] and halos[1].text) -- 只登記翻譯覆蓋，不釘文案
-- 逾時之後仍然要玩家自己再按一次；系統不會自己重試
for _ = 1, 5 do nowMs = nowMs + 300 driveTick(dp, dveh) end
checkFalse(MDAD.Drive.isActive(0), "(t3) 逾時之後不自行重試")
checkEq(M.starts, 1, "(t3) 逾時之後不自行再 start 一次")
drive.nav.state = "ok"

-- ④ claim 被拒：別人接管中（剖面備好才知道）／車沒停妥（按鈕當下就知道）
ready(true)
setTrip("navigating")
M.claimOwner, M.claimToken = "SomeOtherMod", newToken()
checkTrue(MDAD.Drive.continueItinerary(0), "(t4) 先受理：claim 要等剖面備好才問得到")
pump()
checkFalse(MDAD.Drive.isActive(0), "(t4) 別的模組正在接管：不啟動")
checkTrue(M.claims > 0, "(t4) 真的問過 MiniMap 才判定")
checkEq(haloKey(), "UI_MinidoracatAutoDrive_TripBusy", "(t4) busy 對應 TripBusy")
checkNil(MDAD.Drive.debugSession(0), "(t4) 被拒不留 session")
checkEq(drive.calls.setRegulator, 0, "(t4) 被拒全程沒碰車")
checkEq(M.releases, 0, "(t4) 沒 claim 到就沒有東西要交還")
ready(false)
setTrip("navigating")
ok, why = MDAD.Drive.continueItinerary(0)
checkFalse(ok, "(t4) 車還在動：按鈕當下就拒絕")
checkEq(noteReason(why), "UI_MinidoracatAutoDrive_TripNotStopped", "(t4) notstopped 對應 TripNotStopped")
checkEq(M.starts, 0, "(t4) 沒停妥連 start 都不發")
checkEq(drive.calls.setRegulator, 0, "(t4) 被拒＝一次控制輸出都不准送")
checkFalse(MDAD.Drive.isActive(0), "(t4) 被拒不留準備意圖")

-- ⑤ 不可自駕的狀態：completed 與 approach（road_end 之後）
ready(true)
setTrip("navigating")
M.stops[1].status, M.phase = "arrived", "completed"
ok, why = MDAD.Drive.continueItinerary(0)
checkFalse(ok, "(t5) 行程已完成：沒有可出發的站")
checkEq(noteReason(why), "UI_MinidoracatAutoDrive_TripState", "(t5) completed 對應 TripState")
checkEq(MDAD.Drive.hudStartReason(0), "UI_MinidoracatAutoDrive_TripState", "(t5) HUD 停用態同一原因")
setTrip("approach")
ok, why = MDAD.Drive.continueItinerary(0)
checkFalse(ok, "(t5) approach 段不自動接管")
checkEq(noteReason(why), "UI_MinidoracatAutoDrive_TripRoadEnd", "(t5) approach 顯示手動前往")
checkEq(MDAD.Drive.hudStartReason(0), "UI_MinidoracatAutoDrive_TripRoadEnd",
    "(t5) HUD 停用態也是手動前往，不是抵達")
checkEq(M.claims, 0, "(t5) 這兩種狀態一次都不 claim")

-- ⑥ 純查詢：draft／paused／waiting 的 getNavTarget 是 nil，不得誤報沒有路線
ready(true)
setTrip("draft")
checkNil(MDAD.Drive.hudStartReason(0), "(t6) draft 有 pending：可開始行程")
M.phase = "paused"
checkNil(MDAD.Drive.hudStartReason(0), "(t6) paused 可恢復")
M.phase = "waiting"
checkNil(MDAD.Drive.hudStartReason(0), "(t6) waiting 可前往下一站")
checkEq(M.starts, 0, "(t6) hudStartReason 不啟用目標")
checkEq(M.claims, 0, "(t6) hudStartReason 不 claim")

-- ⑦ 到站：arrive＋停妥才回報，回報在清 session 之前
ready(true)
setTrip("draft")
checkTrue(MDAD.Drive.continueItinerary(0), "(t7) 出發")
pump()
dveh._x, dveh._y, dveh._speed, dveh._stopped = 298, 0, 0, true
MDAD.Drive.debugSession(0).mode = "arrive"
clearList(halos)
drive.voiceLog = {}
driveTick(dp, dveh)
checkEq(M.reports, 1, "(t7) 停妥才回報，且只回報一次")
checkEq(M.stops[1].status, "arrived", "(t7) 距離內記 arrived")
checkEq(M.phase, "completed", "(t7) 沒有後續 pending＝completed")
checkFalse(MDAD.Drive.isActive(0), "(t7) 回報完成後才收 session")
checkEq(haloKey(), DKEY.ARRIVED, "(t7) 真到站才說抵達")
checkEq(drive.voiceCount("arrive"), 1, "(t7) 真到站才播抵達語音")
checkNil(M.claimOwner, "(t7) 到站後不留 orphan claim")

-- ⑧ 晚到的第一次回報：MiniMap 其實已經記下抵達，回給我們的卻是失敗。
-- 下一幀的 token 核對就看得到接管已被撤銷 → 乾淨交還，不假報抵達、不播成功語音、
-- 不重複記一次進度，也沒有 orphan claim（token 早就被消耗了）。
ready(true)
setTrip("draft")
checkTrue(MDAD.Drive.continueItinerary(0), "(t8) 出發")
pump()
local staleToken = M.claimToken
dveh._x, dveh._y, dveh._speed, dveh._stopped = 298, 0, 0, true
MDAD.Drive.debugSession(0).mode = "arrive"
M.lieOnce = true
clearList(halos)
drive.voiceLog = {}
driveTick(dp, dveh)
checkEq(M.reports, 1, "(t8) 送出一次回報")
checkEq(M.stops[1].status, "arrived", "(t8) MiniMap 其實已經記下抵達")
checkTrue(MDAD.Drive.isActive(0), "(t8) 我們收到的是失敗：維持收尾狀態、不亂猜")
checkEq(drive.voiceCount("arrive"), 0, "(t8) 沒收到成功就不播抵達語音")
checkEq(MDAD.Drive.debugSession(0).legToken, staleToken, "(t8) 還沒確認之前不丟掉 token")
clearList(halos)
nowMs = nowMs + 300
driveTick(dp, dveh)
checkFalse(MDAD.Drive.isActive(0), "(t8) token 已被消耗：下一幀核對就交還控制")
checkEq(M.reports, 1, "(t8) 不對已消耗的 token 重送第二次")
checkEq(haloKey(), "UI_MinidoracatAutoDrive_TripLost", "(t8) 說明接管已結束，不宣稱抵達")
checkEq(drive.voiceCount("arrive"), 0, "(t8) 全程不播第二次成功語音")
checkEq(M.releases, 0, "(t8) token 已消耗＝沒有 orphan，不再 release")
checkEq(M.stops[1].status, "arrived", "(t8) 進度就是 MiniMap 記的那一次，沒有被重複消耗")

-- ⑨ road_end：到道路終點但離站點還很遠。單人且勾了抵達暫停時，道路終點同樣暫停
-- （沒有語音可等、直接暫停；Workshop nick）；沒勾就不暫停。
do
    local oldClient, oldServer, oldArrive = clientFlag, serverFlag, MDAD.HUD.pauseOnArrival
    for _, arrivePause in ipairs({ true, false }) do
        local tag = arrivePause and "(t9)" or "(t9b)"
        ready(true)
        setTrip("draft", 300, 40)
        clientFlag, serverFlag = false, false
        MDAD.HUD.pauseOnArrival = function() return arrivePause end
        drive.paused, drive.pauseCalls = false, 0
        checkTrue(MDAD.Drive.continueItinerary(0), tag .. " 出發")
        pump()
        dveh._x, dveh._y, dveh._speed, dveh._stopped = 300, 0, 0, true
        MDAD.Drive.debugSession(0).mode = "arrive"
        clearList(halos)
        drive.voiceLog = {}
        driveTick(dp, dveh)
        checkEq(M.reports, 1, tag .. " 一樣走正式回報")
        checkEq(M.stops[1].status, "pending", tag .. " road_end 不把站標成 arrived")
        checkEq(M.phase, "approach", tag .. " road_end 轉 approach")
        checkEq(noteReason(halos[1] and halos[1].text), "UI_MinidoracatAutoDrive_TripRoadEnd",
            tag .. " 顯示手動前往，不冒稱到達最終目的地")
        checkEq(halos[1] and halos[1].kind, "info", tag .. " road_end 是資訊不是失敗")
        checkEq(#drive.voiceLog, 0, tag .. " road_end 不播任何語音（含抵達成功語音）")
        checkFalse(MDAD.Drive.isActive(0), tag .. " road_end 之後不自動再開")
        checkNil(M.claimOwner, tag .. " road_end 釋放 claim")
        checkEq(isGamePaused(), arrivePause, tag .. " 道路終點照抵達暫停設定暫停")
        checkEq(drive.pauseCalls, arrivePause and 1 or 0, tag .. " 只在勾選時呼叫一次原生暫停")
        checkFalse(MDAD.Drive.isPausePending(), tag .. " 沒有語音可等，不留延遲暫停")
    end
    clientFlag, serverFlag, MDAD.HUD.pauseOnArrival = oldClient, oldServer, oldArrive
    drive.paused, drive.pauseCalls = false, 0
end

-- ⑩ 途中設備失效：先停控制、再交還，站點仍 pending
ready(true)
setTrip("draft")
checkTrue(MDAD.Drive.continueItinerary(0), "(t10) 出發")
pump()
driveTick(dp, dveh)
clearList(halos)
dveh._engine = false
driveTick(dp, dveh)
checkFalse(MDAD.Drive.isActive(0), "(t10) 設備失效：結束自駕")
checkEq(M.releases, 1, "(t10) 交還 claim 一次")
checkEq(M.lastRelease, "unavailable", "(t10) 失效交還的原因是 unavailable")
checkTrue(M.releaseRegOff, "(t10) 先停掉自己的控制輸出才交還")
checkNil(M.claimOwner, "(t10) 不留 orphan claim")
checkEq(M.phase, "paused", "(t10) 交還後行程 paused")
checkEq(M.stops[1].status, "pending", "(t10) 交還不等於到站")
checkEq(M.reports, 0, "(t10) 交還不回報抵達")
checkEq(haloKey(), DKEY.ENGINE, "(t10) 顯示真正的失效原因")

-- ⑪ 一般 Drive.stop：只交還控制，絕不是到站
ready(true)
setTrip("draft")
checkTrue(MDAD.Drive.continueItinerary(0), "(t11) 出發")
pump()
checkTrue(MDAD.Drive.stop(0, nil), "(t11) 玩家關閉自駕")
checkEq(M.reports, 0, "(t11) Drive.stop 不得當成到站回報")
checkEq(M.releases, 1, "(t11) 只交還控制")
checkEq(M.lastRelease, "manual", "(t11) 玩家主動關閉＝manual")
checkTrue(M.releaseRegOff, "(t11) 先關 regulator 再交還")
checkEq(M.stops[1].status, "pending", "(t11) 站點仍待辦")

-- ⑫ 行駛中 claim 被 MiniMap 撤銷：立刻交還控制、不再 release、不自動接下一段
ready(true)
setTrip("draft")
checkTrue(MDAD.Drive.continueItinerary(0), "(t12) 出發")
pump()
driveTick(dp, dveh)
clearList(halos)
M.claimOwner, M.claimToken = nil, nil
M.legToken = newToken()
bump()
M.releases = 0
driveTick(dp, dveh)
checkFalse(MDAD.Drive.isActive(0), "(t12) claim 被撤銷：立刻交還控制")
checkEq(haloKey(), "UI_MinidoracatAutoDrive_TripLost", "(t12) 顯示接管已結束")
checkEq(M.releases, 0, "(t12) 已確認撤銷就不再 release")
checkEq(M.reports, 0, "(t12) 不把撤銷當成到站")
driveTick(dp, dveh)
checkEq(M.claims, 1, "(t12) 新 token 不是自動開下一段的指令")
checkFalse(MDAD.Drive.isActive(0), "(t12) 要玩家再次明確操作才會動")

-- ⑬ 到站回報被拒：有界重試，維持停妥與 session，不假報抵達也不偷偷丟掉 claim
ready(true)
setTrip("draft")
checkTrue(MDAD.Drive.continueItinerary(0), "(t13) 出發")
pump()
dveh._x, dveh._y, dveh._speed, dveh._stopped = 298, 0, 0, true
MDAD.Drive.debugSession(0).mode = "arrive"
M.rejectReports = 1 -- MiniMap 這一輪還不認同「已停妥」
clearList(halos)
drive.voiceLog = {}
driveTick(dp, dveh)
checkEq(M.reports, 1, "(t13) 回報被拒一次")
checkTrue(MDAD.Drive.isActive(0), "(t13) 被拒不清 session，維持收尾狀態")
checkEq(MDAD.Drive.debugSession(0).mode, "arrive", "(t13) 維持 arrive，不自動出發")
checkEq(MDAD.Drive.debugSession(0).legToken, M.claimToken, "(t13) claim 沒有被偷偷丟掉")
checkEq(haloKey(), "UI_MinidoracatAutoDrive_TripNotStopped", "(t13) 明示被拒原因")
checkEq(drive.voiceCount("arrive"), 0, "(t13) 被拒不播抵達語音")
checkEq(M.stops[1].status, "pending", "(t13) 被拒不記 arrived")
driveTick(dp, dveh)
checkEq(M.reports, 1, "(t13) 重試有間隔，不是每幀猛送")
clearList(halos)
nowMs = nowMs + 300
driveTick(dp, dveh)
checkEq(M.reports, 2, "(t13) 間隔到了才重試")
checkFalse(MDAD.Drive.isActive(0), "(t13) 重試成功才收尾")
checkEq(M.stops[1].status, "arrived", "(t13) 重試成功記 arrived")
checkEq(haloKey(), DKEY.ARRIVED, "(t13) 重試成功才說抵達")
checkEq(drive.voiceCount("arrive"), 1, "(t13) 成功語音只播一次")

-- ⑭ 回報一直被拒：有界視窗用完就停手交還，不無限重試、不假報抵達
ready(true)
setTrip("draft")
checkTrue(MDAD.Drive.continueItinerary(0), "(t14) 出發")
pump()
dveh._x, dveh._y, dveh._speed, dveh._stopped = 298, 0, 0, true
MDAD.Drive.debugSession(0).mode = "arrive"
M.rejectReports = 99
clearList(halos)
drive.voiceLog = {}
for _ = 1, 30 do nowMs = nowMs + 300 driveTick(dp, dveh) end
checkFalse(MDAD.Drive.isActive(0), "(t14) 有界重試用完就收手")
checkTrue(M.reports > 1 and M.reports < 20, "(t14) 重試有上限（實得 " .. tostring(M.reports) .. "）")
checkEq(M.releases, 1, "(t14) 放棄時交還 claim，不留 orphan")
checkEq(M.lastRelease, "failed", "(t14) 交還原因是失敗，不是到站")
checkEq(M.stops[1].status, "pending", "(t14) 始終沒有假報抵達")
checkEq(drive.voiceCount("arrive"), 0, "(t14) 始終沒有成功語音")

-- ⑮ 回報回了我們不認得的成功值：「回了 true」不能證明 claim 已經交割。
-- ⑮a token 其實還在我們手上 → 不准當成已收尾，維持 arrive 有界重試，也不冒稱抵達。
ready(true)
setTrip("draft")
checkTrue(MDAD.Drive.continueItinerary(0), "(t15) 出發")
pump()
local oddToken = M.claimToken
dveh._x, dveh._y, dveh._speed, dveh._stopped = 298, 0, 0, true
MDAD.Drive.debugSession(0).mode = "arrive"
M.oddReport, M.oddConsume = true, false
clearList(halos)
drive.voiceLog = {}
driveTick(dp, dveh)
checkTrue(MDAD.Drive.isActive(0), "(t15) 未知結果但 token 還在：不准當成已收尾")
checkEq(MDAD.Drive.debugSession(0).legToken, oddToken, "(t15) 沒被消耗的 claim 不丟掉")
checkEq(M.claimOwner, MOD_ID, "(t15) MiniMap 那邊也還記在我們名下")
checkEq(drive.voiceCount("arrive"), 0, "(t15) 未知結果不播抵達語音")
checkEq(M.stops[1].status, "pending", "(t15) 未知結果不自己把站記成到達")
nowMs = nowMs + 300
driveTick(dp, dveh)
checkEq(M.reports, 2, "(t15) 照樣在有界視窗內重試同一顆 token")
checkFalse(MDAD.Drive.isActive(0), "(t15) 重試拿到真答案才收尾")
checkEq(M.stops[1].status, "arrived", "(t15) 真答案才是進度")
-- ⑮b token 真的被吃掉了 → 收尾，但仍然不冒稱抵達、不播成功語音
ready(true)
setTrip("draft")
checkTrue(MDAD.Drive.continueItinerary(0), "(t15b) 出發")
pump()
dveh._x, dveh._y, dveh._speed, dveh._stopped = 298, 0, 0, true
MDAD.Drive.debugSession(0).mode = "arrive"
M.oddReport, M.oddConsume = true, true
clearList(halos)
drive.voiceLog = {}
driveTick(dp, dveh)
checkFalse(MDAD.Drive.isActive(0), "(t15b) token 已被消耗：收尾")
checkEq(M.reports, 1, "(t15b) 已消耗就不再重送")
checkEq(drive.voiceCount("arrive"), 0, "(t15b) 未知結果不播抵達語音")
checkEq(haloKey(), "UI_MinidoracatAutoDrive_TripLost", "(t15b) 明說接管已結束，不宣稱抵達")
checkEq(M.stops[1].status, "pending", "(t15b) 未知結果不自己把站記成到達")
checkEq(M.releases, 0, "(t15b) 已消耗的 token 不需要也不應該再交還")

-- ⑯ 交還被拒：有界重試，不把仍有效的 claim 丟掉
ready(true)
setTrip("draft")
checkTrue(MDAD.Drive.continueItinerary(0), "(t16) 出發")
pump()
local heldToken = M.claimToken
M.rejectReleases = 1
checkTrue(MDAD.Drive.stop(0, nil), "(t16) 玩家關閉自駕")
checkEq(M.releases, 1, "(t16) 交還送出一次")
checkEq(M.claimOwner, MOD_ID, "(t16) 被拒時 claim 還在我們手上")
checkFalse(MDAD.Drive.isActive(0), "(t16) 控制已經交還，不再自駕")
ok, why = MDAD.Drive.continueItinerary(0)
checkFalse(ok, "(t16) 上一段還沒交還完就不接新的一段")
checkEq(noteReason(why), "UI_MinidoracatAutoDrive_TripLost", "(t16) 說明接管尚未結束")
nowMs = nowMs + 300
driveTick(dp, dveh)
checkEq(M.releases, 2, "(t16) 有界重試把交還補完")
checkNil(M.claimOwner, "(t16) 補完之後不留 orphan claim")
checkEq(M.stops[1].status, "pending", "(t16) 交還不等於到站")
checkTrue(MDAD.Drive.continueItinerary(0), "(t16) 交還乾淨之後可以再出發")
MDAD.Drive.stop(0, nil)
checkTrue(heldToken ~= nil, "(t16) 整段測的是同一顆真 token")

-- ⑯b 交還的回程掉了：MiniMap 其實已經放開，回給我們的卻是失敗。
-- 交還與否看的是 token 還在不在，不是那個回傳值——所以不該排重試，也不該擋下一段。
ready(true)
setTrip("draft")
checkTrue(MDAD.Drive.continueItinerary(0), "(t16b) 出發")
pump()
M.lieRelease = true
checkTrue(MDAD.Drive.stop(0, nil), "(t16b) 玩家關閉自駕")
checkEq(M.releases, 1, "(t16b) 交還送出一次")
checkNil(M.claimOwner, "(t16b) MiniMap 其實已經放開了")
ok, why = MDAD.Drive.continueItinerary(0)
checkTrue(ok, "(t16b) token 已不在我們名下：當下就不該被待交還擋住")
checkNil(why, "(t16b) 沒有待交還就沒有原因可說")
MDAD.Drive.stop(0, nil)
nowMs = nowMs + 300
driveTick(dp, dveh)
checkEq(M.releases, 1, "(t16b) 全程只送出那一次交還，不做無謂重試")

-- ⑰ arrive 煞停途中 claim 被撤銷：立刻放手，不再跟玩家搶煞車
ready(true)
setTrip("draft")
checkTrue(MDAD.Drive.continueItinerary(0), "(t17) 出發")
pump()
MDAD.Drive.debugSession(0).mode = "arrive"
dveh._x, dveh._y, dveh._speed, dveh._stopped = 250, 0, 8, false -- 還在煞停途中
driveReset(dveh)
clearList(halos)
M.claimOwner, M.claimToken = nil, nil
M.legToken = newToken()
bump()
driveTick(dp, dveh)
checkFalse(MDAD.Drive.isActive(0), "(t17) 撤銷後立刻交還，不把車煞到底")
checkEq(drive.calls.forceBrake, 0, "(t17) 撤銷那一幀不再送煞車指令")
checkEq(haloKey(), "UI_MinidoracatAutoDrive_TripLost", "(t17) 顯示接管已結束")
checkEq(M.reports, 0, "(t17) 不回報抵達")
checkEq(M.releases, 0, "(t17) 已確認撤銷就不再 release")

-- ⑱ 準備中玩家自己操作／車子動起來：安靜放棄，不搶方向盤也不 claim
ready(true)
setTrip("draft")
drive.nav.state = "pending"
checkTrue(MDAD.Drive.continueItinerary(0), "(t18) 進準備狀態")
dveh._steering = 0.5 -- 玩家自己在轉方向盤
nowMs = nowMs + 300
driveTick(dp, dveh)
checkFalse(MDAD.Drive.isActive(0), "(t18) 玩家自己操作：放棄準備")
checkEq(#halos, 0, "(t18) 玩家自己在開不是錯誤，不噴紅字")
checkEq(M.claims, 0, "(t18) 沒有 claim")
dveh._steering = 0
setTrip("draft")
checkTrue(MDAD.Drive.continueItinerary(0), "(t18) 再進一次準備狀態")
dveh._stopped = false -- 車子開始移動
nowMs = nowMs + 300
driveTick(dp, dveh)
checkFalse(MDAD.Drive.isActive(0), "(t18) 車動起來就放棄準備（claim 本來就要求停妥）")
checkEq(M.claims, 0, "(t18) 仍然沒有 claim")

-- ⑲ 準備中同槽位換角色：舊意圖作廢，不套到新角色頭上
ready(true)
setTrip("draft")
drive.nav.state = "pending"
checkTrue(MDAD.Drive.continueItinerary(0), "(t19) 進準備狀態")
players[0] = newPlayer({ num = 0, electricity = 2, username = "swapped0" })
nowMs = nowMs + 300
driveTick(dp, dveh)
checkFalse(MDAD.Drive.isActive(0), "(t19) 換角色：舊準備意圖作廢")
checkEq(M.claims, 0, "(t19) 不替新角色 claim")
players[0] = dp
drive.nav.state = "ok"

-- ⑳ 確定無路／規劃失敗保真理由：不得被抹成「行程狀態不對」或「行程已變更」，
-- 也不得被拖到逾時才說。路線階段與剖面階段各驗一次。
ready(true)
setTrip("draft")
drive.nav.state = "noroad"
ok, why = MDAD.Drive.continueItinerary(0)
checkFalse(ok, "(t20) 確定無路：不啟動")
checkEq(noteReason(why), "UI_MinidoracatAutoDrive_TripNoRoad", "(t20) noroad 保留原因")
checkFalse(MDAD.Drive.isActive(0), "(t20) 不留準備意圖")
checkEq(M.claims, 0, "(t20) 沒有 claim")
ready(true)
setTrip("draft")
drive.nav.state = "failed"
ok, why = MDAD.Drive.continueItinerary(0)
checkFalse(ok, "(t20) 規劃失敗：不啟動")
checkEq(noteReason(why), "UI_MinidoracatAutoDrive_TripFailed", "(t20) failed 保留原因")
-- 剖面建到一半才變成確定無路：一樣保真理由，不是逾時也不是 stale
ready(true)
setTrip("draft")
drive.nav.state = "ok"
checkTrue(MDAD.Drive.continueItinerary(0), "(t20) 先進準備狀態")
local realStep20 = MDADFollower.stepBuild
local step20 = 0
MDADFollower.stepBuild = function(profile, budget)
    step20 = step20 + 1
    if step20 == 1 then return false end -- 卡一幀，讓路線狀態在 claim 之前先變
    return realStep20(profile, budget)
end
nowMs = nowMs + 300
driveTick(dp, dveh) -- 寄放 session
nowMs = nowMs + 300
driveTick(dp, dveh) -- 剖面第一輪：還沒好
clearList(halos)
drive.nav.state = "noroad"
nowMs = nowMs + 300
driveTick(dp, dveh) -- 剖面就緒，但路線已確定無路
MDADFollower.stepBuild = realStep20
checkFalse(MDAD.Drive.isActive(0), "(t20) 剖面階段確定無路：收手")
checkEq(haloKey(), "UI_MinidoracatAutoDrive_TripNoRoad", "(t20) 剖面階段也保真理由")
checkEq(M.claims, 0, "(t20) 確定無路不 claim")
drive.nav.state = "ok"

-- ⑳b 準備期間 MiniMap 自己把行程 paused 並附原因：用那個原因，不要一律說「已變更」
ready(true)
setTrip("draft")
drive.nav.state = "pending"
checkTrue(MDAD.Drive.continueItinerary(0), "(t20b) 進準備狀態")
M.phase, M.legToken, M.pausedReason = "paused", nil, "noroad"
bump()
clearList(halos)
nowMs = nowMs + 300
driveTick(dp, dveh)
checkFalse(MDAD.Drive.isActive(0), "(t20b) 行程被暫停：收手")
checkEq(haloKey(), "UI_MinidoracatAutoDrive_TripNoRoad", "(t20b) 說出暫停的真原因")
checkEq(M.claims, 0, "(t20b) 不 claim")
M.pausedReason = nil
drive.nav.state = "ok"

-- ㉑a claim 之前路線被重算：丟掉寄放的 session 用新路線重建，不拿舊剖面去接管；
-- 重建也不會把準備時限重新計時。
ready(true)
setTrip("draft")
checkTrue(MDAD.Drive.continueItinerary(0), "(t21a) 進準備狀態")
local realStep21 = MDADFollower.stepBuild
local stalled = true
MDADFollower.stepBuild = function(profile, budget)
    if stalled then return false end
    return realStep21(profile, budget)
end
nowMs = nowMs + 300
driveTick(dp, dveh) -- 寄放 session（用舊路線）
local staged = drive.nav.route
drive.nav.route = newRoute(40, 0, 0, 4, 0) -- 主 MOD 重算：新的 table identity
drive.nav.route.segSurface, drive.nav.route.segWidth = {}, {}
for i = 1, 39 do drive.nav.route.segSurface[i], drive.nav.route.segWidth[i] = "paved", 10 end
stalled = false
nowMs = nowMs + 300
driveTick(dp, dveh)
checkEq(M.claims, 0, "(t21a) 路線換了：先重建，不拿舊剖面去 claim")
checkTrue(MDAD.Drive.isActive(0), "(t21a) 重建期間仍在準備中")
pump()
checkEq(M.claims, 1, "(t21a) 用新路線重建完才 claim")
checkTrue(MDAD.Drive.debugSession(0).route == drive.nav.route,
    "(t21a) 接管用的是重算後的路線")
checkTrue(staged ~= drive.nav.route, "(t21a) 本案真的換過一次路線 identity")
MDAD.Drive.stop(0, nil)
-- 路線一直被重算：準備時限照原本的算，不會被無限延長
ready(true)
setTrip("draft")
checkTrue(MDAD.Drive.continueItinerary(0), "(t21b) 進準備狀態")
for _ = 1, 70 do
    drive.nav.route = newRoute(40, 0, 0, 4, 0)
    drive.nav.route.segSurface, drive.nav.route.segWidth = {}, {}
    for i = 1, 39 do drive.nav.route.segSurface[i], drive.nav.route.segWidth[i] = "paved", 10 end
    nowMs = nowMs + 300
    driveTick(dp, dveh)
end
checkFalse(MDAD.Drive.isActive(0), "(t21b) 路線一直換也要在原時限內放棄，不無限重建")
checkEq(M.claims, 0, "(t21b) 全程沒有 claim")
checkEq(drive.calls.setRegulator, 0, "(t21b) 全程零控制輸出")

-- ㉑c 交還一直被拒：寫入重試有界，但沒解除之前不准安靜丟掉——擋著不接新段，
-- 直到上游真的把 token 撤銷為止。
ready(true)
setTrip("draft")
checkTrue(MDAD.Drive.continueItinerary(0), "(t21c) 出發")
pump()
M.rejectReleases = 99
checkTrue(MDAD.Drive.stop(0, nil), "(t21c) 玩家關閉自駕")
for _ = 1, 40 do nowMs = nowMs + 300 driveTick(dp, dveh) end
local writesAfterDeadline = M.releases
checkTrue(writesAfterDeadline > 1 and writesAfterDeadline < 30,
    "(t21c) 寫入重試有界（實得 " .. tostring(writesAfterDeadline) .. "）")
for _ = 1, 20 do nowMs = nowMs + 300 driveTick(dp, dveh) end
checkEq(M.releases, writesAfterDeadline, "(t21c) 時限之後不再一直寫")
checkEq(M.claimOwner, MOD_ID, "(t21c) claim 仍在我們名下，沒有被安靜丟掉")
ok, why = MDAD.Drive.continueItinerary(0)
checkFalse(ok, "(t21c) 沒交還乾淨就不接新的一段")
checkEq(noteReason(why), "UI_MinidoracatAutoDrive_TripLost", "(t21c) 說明接管尚未結束")
-- 上游（角色／世界生命週期清理）撤銷 token 之後才解除阻擋
M.claimOwner, M.claimToken, M.legToken = nil, nil, nil
M.phase = "paused"
bump()
nowMs = nowMs + 300
driveTick(dp, dveh)
checkTrue(MDAD.Drive.continueItinerary(0), "(t21c) 撤銷之後恢復正常")
MDAD.Drive.stop(0, nil)

-- ㉑d 行駛中主 MOD 的介面整個不見了：讀不到 token 不等於 claim 被撤銷。
-- 必須交還控制、把交還記著（擋住下一段），等介面回來再補送——不可以就地把
-- 手上那顆 token 當成沒事丟掉。
ready(true)
setTrip("draft")
checkTrue(MDAD.Drive.continueItinerary(0), "(t21d) 出發")
pump()
local savedApi = MinidoracatMiniMapAPI
clearList(halos)
MinidoracatMiniMapAPI = nil
driveTick(dp, dveh)
checkFalse(MDAD.Drive.isActive(0), "(t21d) 介面不見了：交還控制")
checkEq(#halos, 1, "(t21d) 對玩家說一次原因")
checkEq(noteReason(halos[1] and halos[1].text), NAV_API_MISSING, "(t21d) 說的是介面不見了")
checkEq(M.releases, 0, "(t21d) 介面不在，根本送不出交還")
checkEq(M.claimOwner, MOD_ID, "(t21d) claim 沒有被安靜丟掉，仍記在我們名下")
MinidoracatMiniMapAPI = savedApi
ok, why = MDAD.Drive.continueItinerary(0)
checkFalse(ok, "(t21d) 交還還沒補完就不接新的一段")
checkEq(noteReason(why), "UI_MinidoracatAutoDrive_TripLost", "(t21d) 說明接管尚未結束")
nowMs = nowMs + 300
driveTick(dp, dveh)
checkEq(M.releases, 1, "(t21d) 介面回來就把欠的交還補送出去")
checkNil(M.claimOwner, "(t21d) 補送之後才真的不留 orphan")
checkEq(M.stops[1].status, "pending", "(t21d) 整段都不是到站")
checkTrue(MDAD.Drive.continueItinerary(0), "(t21d) 結清之後可以再出發")
MDAD.Drive.stop(0, nil)

-- ㉑ 導覽耗電心跳：只有活動段計費，光有清單不算
setTrip("navigating")
local realSet, realClear = MDAD.setNavUsage, MDAD.clearNavUsage
local navOn, navOff = 0, 0
MDAD.setNavUsage = function(...) navOn = navOn + 1 return realSet(...) end
MDAD.clearNavUsage = function(...) navOff = navOff + 1 return realClear(...) end
for _ = 1, 120 do fire("OnTick") end
navOn, navOff = 0, 0
M.phase = "waiting"
nowMs = nowMs + 1200
for _ = 1, 60 do fire("OnTick") end
checkEq(navOff, 1, "(t20) 只有站點清單、沒有活動段：導覽耗電轉 off")
checkEq(navOn, 0, "(t20) waiting 不計費")
navOn, navOff = 0, 0
M.phase = "navigating"
nowMs = nowMs + 1200
for _ = 1, 60 do fire("OnTick") end
checkEq(navOn, 1, "(t20) 活動段（含自駕準備中的那一段）照常計費")
MDAD.setNavUsage, MDAD.clearNavUsage = realSet, realClear

-- ㉒ 舊主 MOD（v5）一路不退化
installNavApi(5)
ready(true)
dveh._speed, dveh._stopped = 20, false
ok, why = MDAD.Drive.continueItinerary(0)
checkFalse(ok, "(t21) 舊主 MOD 沒有行程介面：繼續行程不可用")
checkEq(noteReason(why), NAV_API_MISSING, "(t21) 舊版回 NavApiMissing")
checkTrue(MDAD.Drive.start(dp), "(t21) 舊單站自駕照常啟動")
checkNil(MDAD.Drive.debugSession(0).legToken, "(t21) 舊路徑沒有 claim token")
checkEq(M.claims, 0, "(t21) 不對舊主 MOD 呼叫 v6 函式")
dveh._x = 295
drive.nav.tx, drive.nav.ty = nil, nil
nowMs = nowMs + 300
driveTick(dp, dveh)
checkEq(MDAD.Drive.debugSession(0) and MDAD.Drive.debugSession(0).mode, "arrive",
    "(t21) 目標在 12 格內消失：舊的抵達收尾啟發原封不動")
MDAD.Drive.stop(0, nil)
end
scenarioItinerary()
end

do -- 主 chunk local 槽已滿：v7 自動接續整段包成函式，內部 local 不佔主 chunk
-- =====================================================================
-- v7 自動接續／被動到站（凍結契約）
-- 模型照 Core 真的會拒絕的地方拒絕：claim 前不准控制、mode 關就不續發、
-- 只有「本 session 自己的 continue 回報」才准接下一段。站 id 刻意不等於索引
-- （101 起），index／id 混用不會蒙對。NO reserveNavLeg、NO reserved 欄位：
-- 新增的介面只有 setNavContinuation，claim 仍是唯一的執行權。
-- getNavLeg 一律只回六個值——activation 只從快照讀。
-- =====================================================================
local function scenarioContinuation()
scenario("v7 自動接續：continue／stopover／completed、mode 開關、被動到站採用、取消不復活")

local V = {
    phase = "draft", revision = 41, autoContinue = true, activation = nil,
    stops = {}, currentId = nil, legToken = nil, claimOwner = nil, claimToken = nil,
    tokenSeq = 0, receipt = nil, reason = nil,
    starts = 0, claims = 0, reports = 0, releases = 0, modeCalls = 0,
    lastRelease = nil, gateSet = true, blockStart = nil, onClaim = nil, legacy = false,
}
local function token7()
    V.tokenSeq = V.tokenSeq + 1
    return "v7#" .. V.tokenSeq
end
local function liveToken() return V.claimToken or V.legToken end
local function indexOf(id)
    for i = 1, #V.stops do if V.stops[i].id == id then return i end end
    return nil
end
local function pendingIndex()
    for i = 1, #V.stops do if V.stops[i].status == "pending" then return i end end
    return nil
end
local function current7()
    local index = V.currentId and indexOf(V.currentId)
    return index and V.stops[index] or nil
end
-- Core.activateNext：啟用第一個待辦站、換新 token、記下 activation
local function activate7(kind)
    local index = pendingIndex()
    if not index then return nil end
    V.currentId, V.phase, V.activation, V.reason = V.stops[index].id, "navigating", kind, nil
    V.legToken, V.claimOwner, V.claimToken = token7(), nil, nil
    V.revision = V.revision + 1
    return V.legToken
end
-- Core.finishStop：處置只有三種。autoContinue 與**該站自己的 pause** 都在這裡生效，
-- pause 優先於自動接續。
local function finish7(id)
    local stop = V.stops[indexOf(id)]
    stop.status = "arrived"
    V.activation, V.reason = nil, nil
    V.legToken, V.claimOwner, V.claimToken = nil, nil, nil
    V.revision = V.revision + 1
    if not pendingIndex() then
        V.phase, V.currentId = "completed", nil
        return "completed"
    end
    V.phase, V.currentId = "waiting", id
    if V.autoContinue and not stop.pause then return "continue" end
    return "stopover"
end
local function install7(legacy)
    V.legacy = legacy == true
    installNavApi(V.legacy and 6 or 7)
    local api = MinidoracatMiniMapAPI
    api.getNavItinerary = function(pn)
        if pn ~= 0 then return nil, "badargs" end
        if #V.stops == 0 then return nil, "noitinerary" end
        local out = { schemaVersion = V.legacy and 1 or 2, revision = V.revision,
            phase = V.phase, count = #V.stops, currentStopId = V.currentId,
            reason = V.reason, stops = {} }
        if not V.legacy then
            out.autoContinue, out.activation = V.autoContinue, V.activation
        end
        for i = 1, #V.stops do
            local st = V.stops[i]
            out.stops[i] = { id = st.id, x = st.x, y = st.y,
                status = st.status, pause = st.pause }
        end
        return out
    end
    -- 六個回傳，一個都不多：activation 不進 getNavLeg。
    api.getNavLeg = function(pn)
        if pn ~= 0 then return nil, "badargs" end
        if #V.stops == 0 then return nil, "noitinerary" end
        if V.phase ~= "navigating" and V.phase ~= "approach" then
            return nil, nil, nil, nil, V.phase, V.revision
        end
        local st = current7()
        return liveToken(), st.id, st.x, st.y, V.phase, V.revision
    end
    api.getNavTarget = function(pn)
        drive.nav.targetCalls = drive.nav.targetCalls + 1
        if #V.stops == 0 or (V.phase ~= "navigating" and V.phase ~= "approach") then
            return nil, "notarget"
        end
        local st = current7()
        return st.x, st.y
    end
    api.startNavItinerary = function(pn, expectedRevision)
        V.starts = V.starts + 1
        if #V.stops == 0 then return nil, "noitinerary" end
        if V.phase ~= "draft" and V.phase ~= "paused" and V.phase ~= "waiting" then
            return nil, "state"
        end
        if expectedRevision ~= V.revision then return nil, "stale" end
        if V.claimOwner then return nil, "busy" end
        if not dveh._stopped then return nil, "notstopped" end
        -- gate(set)：主 MOD 這一刻不允許就是不允許，沒有詳細鍵時 addon 退 NeedGPS
        if V.blockStart then
            return nil, "blocked", type(V.blockStart) == "string" and V.blockStart or nil
        end
        local issued = activate7("start")
        if not issued then return nil, "state" end
        return issued, "ok"
    end
    api.claimNavLeg = function(pn, owner, expectedToken)
        V.claims = V.claims + 1
        if type(owner) ~= "string" or owner == "" then return nil, "badargs" end
        if #V.stops == 0 then return nil, "noitinerary" end
        if V.phase ~= "navigating" then return nil, "state" end
        if V.claimOwner and V.claimOwner ~= owner then return nil, "busy" end
        if expectedToken ~= liveToken() then return nil, "stale" end
        if V.claimOwner == owner then return V.claimToken, "ok" end
        if dveh._driver ~= dp then return nil, "notdriver" end
        if not dveh._stopped then return nil, "notstopped" end
        V.claimOwner, V.claimToken = owner, token7()
        -- 情境鉤：claim 成功「當下」的同步回呼（真 Core 的 notify／分享就在這個位置）
        if V.onClaim then
            local hook = V.onClaim
            V.onClaim = nil
            hook()
        end
        return V.claimToken, "ok"
    end
    api.reportNavArrival = function(pn, owner, token)
        V.reports = V.reports + 1
        local r = V.receipt
        if r and r.op == "report" and r.owner == owner and r.token == token then
            return true, "duplicate"
        end
        if V.claimOwner ~= owner or token ~= V.claimToken then return false, "stale" end
        if V.phase ~= "navigating" then return false, "state" end
        if not dveh._stopped then return false, "notstopped" end
        local st = current7()
        local dx, dy = dveh._x - st.x, dveh._y - st.y
        V.receipt = { op = "report", owner = owner, token = token }
        if dx * dx + dy * dy > 25 then
            V.phase, V.activation = "approach", nil
            V.legToken, V.claimOwner, V.claimToken = token7(), nil, nil
            V.revision = V.revision + 1
            if V.legacy then return true, "road_end" end
            return true, "road_end", "road_end", V.revision
        end
        local disposition = finish7(st.id)
        -- v6 Core 只回兩個值：addon 收不到處置就必須維持逐點手動。
        if V.legacy then return true, "arrived" end
        return true, "arrived", disposition, V.revision
    end
    api.releaseNavLeg = function(pn, owner, token, reason)
        V.releases, V.lastRelease = V.releases + 1, reason
        local r = V.receipt
        if r and r.op == "release" and r.owner == owner and r.token == token then
            return true, "duplicate"
        end
        if reason ~= "manual" and reason ~= "cancelled" and reason ~= "unavailable"
                and reason ~= "noroad" and reason ~= "failed" then
            return false, "badargs"
        end
        if V.claimOwner ~= owner or token ~= V.claimToken then return false, "stale" end
        V.receipt = { op = "release", owner = owner, token = token }
        V.claimOwner, V.claimToken, V.legToken = nil, nil, nil
        V.phase, V.activation, V.reason = "paused", nil, reason
        V.revision = V.revision + 1
        return true, "released"
    end
    if V.legacy then return end
    api.setNavContinuation = function(pn, expectedRevision, enabled)
        V.modeCalls = V.modeCalls + 1
        if pn ~= 0 or type(enabled) ~= "boolean" then return false, "badargs" end
        if #V.stops == 0 then return false, "noitinerary" end
        if expectedRevision ~= V.revision then return false, "stale" end
        if V.autoContinue == enabled then return true, "ok" end
        -- mode 只改開關：正在執行的 token／claim 一律保留
        V.autoContinue, V.revision = enabled, V.revision + 1
        return true, "ok"
    end
end
-- Core 的 OnTick 被動到站：沒有 claim、車停妥、在 5m 內才收站；
-- continue 還要 gate(set) 允許才啟用下一段，不允許就留在 waiting。
local function coreTick()
    if V.legacy or V.phase ~= "navigating" or V.claimOwner then return end
    if not dveh._stopped then return end
    local st = current7()
    if not st then return end
    local dx, dy = dveh._x - st.x, dveh._y - st.y
    if dx * dx + dy * dy > 25 then return end
    if finish7(st.id) ~= "continue" then return end
    if V.gateSet then activate7("continue") else V.reason = "unavailable" end
end
-- 站點規格 { {x, y, pause}, ... }
local function setTrip7(phase, spec)
    V.stops = {}
    for i = 1, #spec do
        V.stops[i] = { id = 100 + i, x = spec[i][1], y = spec[i][2],
            status = "pending", pause = spec[i][3] == true }
    end
    V.phase, V.currentId, V.activation, V.reason = phase, nil, nil, nil
    V.legToken, V.claimOwner, V.claimToken, V.receipt = nil, nil, nil, nil
    V.starts, V.claims, V.reports, V.releases, V.modeCalls = 0, 0, 0, 0, 0
    V.gateSet, V.blockStart, V.onClaim, V.autoContinue = true, nil, nil, true
    V.revision = V.revision + 1
    if phase == "navigating" then activate7("start") end
end
local function ready7(x)
    MDAD.Drive.stop(0, nil)
    players[0], players[1], players[2], players[3] = dp, nil, nil, nil
    activePlayers = 1
    dveh._x, dveh._y, dveh._speed, dveh._steering = x or 0, 0, 0, 0
    dveh._stopped = true
    dveh._engine, dveh._driver, dveh._regulator = true, dp, nil
    dveh._part._item._uses = 0.8
    dp._vehicle, dp._dead, dp._local = dveh, false, true
    setHeading(dveh, 0.3)
    drive.nav.tx, drive.nav.ty, drive.nav.state = 300, 0, "ok"
    drive.nav.route = newRoute(40, 0, 0, 4, 0)
    drive.nav.route.segSurface, drive.nav.route.segWidth = {}, {}
    for i = 1, 39 do
        drive.nav.route.segSurface[i], drive.nav.route.segWidth[i] = "paved", 10
    end
    driveReset(dveh)
    clearList(halos)
    drive.voiceLog = {}
    drive.paused, drive.pauseCalls = false, 0
end
-- 把準備推到真的接管或真的失敗為止（每幀也跑一次 Core 的 tick）
local function pump7(frames)
    for _ = 1, frames or 20 do
        if MDAD.Drive.debugSession(0) or not MDAD.Drive.isActive(0) then break end
        nowMs = nowMs + 300
        driveTick(dp, dveh)
        coreTick()
    end
end

install7(false)
setSandbox({ NeedItemForNav = false, NeedItemForAutoDrive = false,
    AutoDriveMaxSpeed = 40, RightLaneBias = 0 })

-- ① 一般中途站：自己的 continue 回報才接下一段；不播抵達、不要求暫停
