checkEq(haloKey(1), "UI_MinidoracatAutoDrive_Arrived", "(v7-1) 真的抵達才說抵達")
checkEq(haloKey(2), "UI_MinidoracatAutoDrive_TripCompleted", "(v7-1) 並宣告整份行程完成")
