for _, ok in ipairs(EXPECT_KEYS) do
    check(reasonKeys[ok] == true, "分支有被執行到並吐出 " .. ok)
end

local function readFile(rel)
    for _, root in ipairs(ROOTS) do
        local fh = io.open(root .. rel, "r")
        if fh then
            local text = fh:read("*a")
            fh:close()
            return text
        end
    end
    return nil
end

-- 排序輸出，讓失敗訊息可重現
local emitted = {}
for ok in pairs(reasonKeys) do emitted[#emitted + 1] = ok end
table.sort(emitted)

for _, ok in ipairs({ "EN", "CH", "CN", "JP" }) do
    it = readFile(MEDIA .. "/shared/Translate/" .. ok .. "/UI.json")
    if check(it ~= nil, ok .. "/UI.json 讀得到") then
        for _, reason in ipairs(emitted) do
            check(it:find('"' .. reason .. '"', 1, true) ~= nil,
                ok .. "/UI.json 缺翻譯鍵 " .. reason)
        end
    end
end
end
scenarioReasonKeys()

-- 速度明細（0925n）：沒有 session 時仍回上限組成（HUD 停止自駕也要能看明細），目標等四項為 nil
;(function()
    local vm, sand, _, target = MDAD.Drive.speedInfo(3, { getMaxSpeed = function() return 90 end })
    check(vm == 90 and type(sand) == "number" and sand > 0 and target == nil,
        "(speed-info idle) 未自駕時仍回車輛極速與沙盒上限")
end)()

